    return () => { cancelled = true; stopCamera(); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, manualMode]);

  if (!open) return null;

  return (
    <div
      className="fixed inset-0 z-[90] bg-slate-900/70 flex items-end sm:items-center justify-center"
      data-testid="equipment-scan-modal"
      role="dialog"
      aria-modal="true"
    >
      <div className="w-full max-w-md bg-white rounded-t-3xl sm:rounded-3xl shadow-xl overflow-hidden">
        <div className="flex items-center gap-2 px-4 py-3 border-b border-slate-100">
          <Camera size={16} className="text-cyan-600" />
          <p className="text-sm font-bold text-slate-900 flex-1">Scan machine barcode</p>
          <button
            type="button"
            onClick={handleClose}
            className="w-8 h-8 rounded-full hover:bg-slate-100 flex items-center justify-center text-slate-500"
            data-testid="equipment-scan-close"
            aria-label="Close"
          >
            <X size={16} />
          </button>
        </div>

        <div className="p-4 space-y-3">
          {!manualMode ? (
            <div className="relative aspect-video bg-slate-900 rounded-2xl overflow-hidden">
              <video ref={videoRef} playsInline muted className="absolute inset-0 w-full h-full object-cover" data-testid="equipment-scan-video" />
              <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
                <div className="w-3/4 h-16 border-2 border-white/70 rounded-xl shadow-[0_0_0_2000px_rgba(0,0,0,0.35)]" />
              </div>
              <p className="absolute bottom-2 inset-x-2 text-center text-[11px] font-bold uppercase tracking-wide text-white/90">
                Point at the barcode on the machine
              </p>
            </div>
          ) : (
            <div className="space-y-2" data-testid="equipment-scan-manual">
              <p className="text-xs text-slate-600">Type the serial number printed under the barcode.</p>
              <div className="flex items-center gap-2">
                <div className="relative flex-1">
                  <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                  <input
                    type="text"
                    value={manualValue}
                    onChange={(e) => setManualValue(e.target.value)}
                    placeholder="e.g. 17150704760"
                    className="w-full pl-9 pr-3 py-2 rounded-xl border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-cyan-500"
                    data-testid="equipment-scan-manual-input"
                    onKeyDown={(e) => { if (e.key === 'Enter' && manualValue.trim()) lookup(manualValue.trim()); }}
                  />
                </div>
                <button
                  type="button"
                  onClick={() => manualValue.trim() && lookup(manualValue.trim())}
                  disabled={busy || !manualValue.trim()}
                  className="px-3 py-2 rounded-xl bg-cyan-600 text-white text-xs font-bold disabled:opacity-50"
                  data-testid="equipment-scan-manual-submit"
                >
                  {busy ? <Loader2 size={12} className="animate-spin" /> : 'Look up'}
                </button>
              </div>
            </div>
          )}

          {busy && !manualMode && (
            <p className="text-xs text-cyan-700 flex items-center gap-2" data-testid="equipment-scan-busy"><Loader2 size={12} className="animate-spin" /> Looking up machine…</p>
          )}

          {error && (
            <div className="p-2 rounded-lg bg-amber-50 border border-amber-200 text-xs text-amber-800 flex items-start gap-2" data-testid="equipment-scan-error">
              <AlertTriangle size={14} className="mt-0.5 shrink-0" />
              <span>{error}</span>
            </div>
          )}

          {options.length > 0 && (
            <div className="space-y-1" data-testid="equipment-scan-options">
              <p className="text-[10px] font-bold uppercase tracking-wide text-slate-500">Multiple machines — pick one</p>
              {options.map((eq) => (
                <button
                  key={eq.id}
                  type="button"
                  onClick={() => goToMachine(eq.id)}
                  className="w-full text-left px-3 py-2 rounded-xl border border-slate-200 hover:bg-slate-50"
                  data-testid={`equipment-scan-option-${eq.id}`}
                >
                  <p className="text-sm font-bold text-slate-900">{eq.name || 'Unnamed'}</p>
                  <p className="text-[11px] text-slate-500">
                    {eq.serial_number || eq.asset_tag || ''}
                    {eq.model ? ` · ${eq.model}` : ''}
                    {eq.location ? ` · ${eq.location}` : ''}
                  </p>
                </button>
              ))}
            </div>
          )}

          {!manualMode && hasBarcodeDetector() && (
            <button
              type="button"
              onClick={() => { stopCamera(); setManualMode(true); }}
              className="text-[11px] font-bold uppercase tracking-wide text-slate-500 hover:text-slate-700"
              data-testid="equipment-scan-switch-manual"
            >
              Or type the serial number instead
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

/**
 * StockTakeHistoryModal — review saved bulk stock-take reports.
 * Managers open this (any device) to see past audits: who ran it, when, and
 * the found / missing / unexpected breakdown. Missing machines are listed so
 * they can follow up.
 */
import { useEffect, useState } from 'react';
import axios from 'axios';
import { X, Loader2, ClipboardList, ChevronRight, AlertTriangle, Flag, CheckSquare, Square, ListChecks } from 'lucide-react';

const API = process.env.REACT_APP_BACKEND_URL ? `${process.env.REACT_APP_BACKEND_URL}/api` : '/api';
const auth = () => ({ headers: { Authorization: `Bearer ${localStorage.getItem('token') || ''}` } });
const fmt = (iso) => { try { return new Date(iso).toLocaleString(); } catch (_e) { return iso || ''; } };

export default function StockTakeHistoryModal({ open, onClose, siteId }) {
  const [view, setView] = useState('history'); // history | followups
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [detail, setDetail] = useState(null);
  const [detailLoading, setDetailLoading] = useState(false);
  const [flagging, setFlagging] = useState(false);
  const [followUps, setFollowUps] = useState([]);
  const [fuLoading, setFuLoading] = useState(false);

  const loadHistory = () => {
    setLoading(true);
    axios.get(`${API}/equipment/stocktakes`, { ...auth(), params: { site_id: siteId || undefined } })
      .then((r) => setRows(r.data?.stocktakes || []))
      .catch(() => setRows([]))
      .finally(() => setLoading(false));
  };
  const loadFollowUps = () => {
    setFuLoading(true);
    axios.get(`${API}/equipment/follow-ups`, { ...auth(), params: { site_id: siteId || undefined, status: 'open' } })
      .then((r) => setFollowUps(r.data?.follow_ups || []))
      .catch(() => setFollowUps([]))
      .finally(() => setFuLoading(false));
  };

  useEffect(() => {
    if (!open) return;
    setDetail(null); setView('history');
    loadHistory();
    loadFollowUps();
  }, [open, siteId]); // eslint-disable-line react-hooks/exhaustive-deps

  const openDetail = async (id) => {
    setDetailLoading(true);
    try { const r = await axios.get(`${API}/equipment/stocktakes/${id}`, auth()); setDetail(r.data); }
    catch (_e) { /* noop */ }
    setDetailLoading(false);
  };

  const flagMissing = async () => {
    if (!detail) return;
    setFlagging(true);
    try {
      await axios.post(`${API}/equipment/stocktakes/${detail.id}/flag-missing`, {}, auth());
      const r = await axios.get(`${API}/equipment/stocktakes/${detail.id}`, auth());
      setDetail(r.data);
      loadFollowUps();
    } catch (_e) { /* noop */ }
    setFlagging(false);
  };

  const resolveFollowUp = async (item) => {
    try {
      await axios.put(`${API}/equipment/stocktakes/${item.stocktake_id}/follow-ups/${item.equipment_id}`,
        { status: 'resolved' }, auth());
      setFollowUps((list) => list.filter((f) => !(f.stocktake_id === item.stocktake_id && f.equipment_id === item.equipment_id)));
    } catch (_e) { /* noop */ }
  };

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-[90] bg-slate-900/70 flex items-end sm:items-center justify-center" data-testid="stocktake-history-modal" role="dialog" aria-modal="true">
      <div className="w-full max-w-md bg-white rounded-t-3xl sm:rounded-3xl shadow-xl overflow-hidden max-h-[92vh] flex flex-col">
        <div className="flex items-center gap-2 px-4 py-3 border-b border-slate-100 shrink-0">
          <ClipboardList size={16} className="text-cyan-600" />
          <p className="text-sm font-bold text-slate-900 flex-1">{detail ? 'Stock-take report' : 'Stock-takes'}</p>
          {detail && <button type="button" onClick={() => setDetail(null)} className="text-xs font-bold text-cyan-600 mr-2" data-testid="stocktake-history-back">Back</button>}
          <button type="button" onClick={onClose} className="w-8 h-8 rounded-full hover:bg-slate-100 flex items-center justify-center text-slate-500" data-testid="stocktake-history-close" aria-label="Close"><X size={16} /></button>
        </div>

        {!detail && (
          <div className="flex px-4 pt-3 gap-2 shrink-0">
            <button type="button" onClick={() => setView('history')} className={`text-xs font-bold px-3 py-1.5 rounded-full ${view === 'history' ? 'bg-slate-900 text-white' : 'bg-slate-100 text-slate-600'}`} data-testid="stocktake-tab-history">History</button>
            <button type="button" onClick={() => setView('followups')} className={`text-xs font-bold px-3 py-1.5 rounded-full inline-flex items-center gap-1.5 ${view === 'followups' ? 'bg-slate-900 text-white' : 'bg-slate-100 text-slate-600'}`} data-testid="stocktake-tab-followups">
              <ListChecks size={13} /> Follow-ups{followUps.length ? ` (${followUps.length})` : ''}
            </button>
          </div>
        )}

        <div className="p-4 overflow-y-auto">
          {detail ? (
            <div className="space-y-3">
              <p className="text-xs text-slate-500">{detail.location} · {fmt(detail.created_at)} · by {detail.started_by || 'staff'}</p>
              <div className="grid grid-cols-3 gap-2 text-center">
                <div className="p-2 rounded-xl bg-green-50 border border-green-100"><p className="text-lg font-bold text-green-700">{detail.found_count}</p><p className="text-[10px] uppercase text-green-700/70">Found</p></div>
                <div className="p-2 rounded-xl bg-red-50 border border-red-100"><p className="text-lg font-bold text-red-700">{detail.missing_count}</p><p className="text-[10px] uppercase text-red-700/70">Missing</p></div>
                <div className="p-2 rounded-xl bg-amber-50 border border-amber-100"><p className="text-lg font-bold text-amber-700">{detail.unexpected_count}</p><p className="text-[10px] uppercase text-amber-700/70">Unexpected</p></div>
              </div>
              {detail.missing?.length > 0 && (
                <div>
                  <div className="flex items-center justify-between mb-1">
                    <p className="text-[10px] font-bold uppercase tracking-wide text-red-600 flex items-center gap-1"><AlertTriangle size={11} /> Missing</p>
                    <button type="button" onClick={flagMissing} disabled={flagging || detail.follow_up_flagged} className="text-[11px] font-bold inline-flex items-center gap-1 px-2 py-1 rounded-lg bg-amber-500 text-white disabled:opacity-50" data-testid="stocktake-flag-missing">
                      {flagging ? <Loader2 size={11} className="animate-spin" /> : <Flag size={11} />} {detail.follow_up_flagged ? 'Flagged for follow-up' : 'Flag for follow-up'}
                    </button>
                  </div>
                  <div className="space-y-1 max-h-48 overflow-y-auto">
                    {detail.missing.map((e) => <div key={e.id} className="text-xs text-slate-700">{e.name || e.serial_number} <span className="text-slate-400">· {e.serial_number}{e.location ? ` · ${e.location}` : ''}</span></div>)}
                  </div>
                </div>
              )}
            </div>
          ) : view === 'followups' ? (
            fuLoading ? (
              <div className="py-10 text-center text-slate-400"><Loader2 size={20} className="animate-spin inline" /></div>
            ) : followUps.length === 0 ? (
              <p className="py-10 text-center text-sm text-slate-400" data-testid="stocktake-followups-empty">No open follow-ups. Flag a stock-take's missing machines to create tasks.</p>
            ) : (
              <div className="space-y-2" data-testid="stocktake-followups-list">
                {followUps.map((f) => (
                  <div key={`${f.stocktake_id}-${f.equipment_id}`} className="flex items-start gap-2 px-3 py-2 rounded-xl border border-slate-200" data-testid={`followup-item-${f.equipment_id}`}>
                    <button type="button" onClick={() => resolveFollowUp(f)} className="mt-0.5 text-slate-400 hover:text-green-600" title="Mark resolved" data-testid={`followup-resolve-${f.equipment_id}`}>
                      <Square size={16} />
                    </button>
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-bold text-slate-900 truncate">{f.name}</p>
                      <p className="text-[11px] text-slate-500">{f.serial_number}{f.location ? ` · ${f.location}` : ''} · from {f.stocktake_location} · {fmt(f.stocktake_at)}</p>
                    </div>
                  </div>
                ))}
              </div>
            )
          ) : loading ? (
            <div className="py-10 text-center text-slate-400"><Loader2 size={20} className="animate-spin inline" /></div>
          ) : rows.length === 0 ? (
            <p className="py-10 text-center text-sm text-slate-400" data-testid="stocktake-history-empty">No stock-takes yet.</p>
          ) : (
            <div className="space-y-2" data-testid="stocktake-history-list">
              {rows.map((s) => (
                <button key={s.id} type="button" onClick={() => openDetail(s.id)} disabled={detailLoading} className="w-full text-left px-3 py-2.5 rounded-xl border border-slate-200 hover:bg-slate-50 flex items-center gap-2" data-testid={`stocktake-history-row-${s.id}`}>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-bold text-slate-900 truncate">{s.location}</p>
                    <p className="text-[11px] text-slate-500">{fmt(s.created_at)} · {s.started_by || 'staff'}</p>
                  </div>
                  <span className="text-xs font-bold text-green-600">{s.found_count}/{s.expected_count}</span>
                  {s.missing_count > 0 && <span className="text-xs font-bold text-red-600">{s.missing_count} missing</span>}
                  <ChevronRight size={14} className="text-slate-400" />
                </button>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import axios from 'axios';
import { CheckCircle, CheckCheck, Check, XCircle, HelpCircle } from 'lucide-react';
import { Button } from '@/components/ui/button';

/**
 * One "Notified" card for a fault (replaces the separate "Notified when
 * logged" + "Sent to <supplier>" cards). Every recipient is listed once with
 * a tick showing whether the email provider confirmed delivery to their inbox:
 *   ✓✓ green  delivered      ✓ grey  sent, awaiting confirmation
 *   ✕ red    not delivered  ? grey  not tracked (older faults)
 */
const ROLE_BADGE = {
  pulse: { label: 'Pulse', cls: 'bg-sky-500/20 text-sky-600 dark:text-sky-300' },
  overseas: { label: 'Service provider', cls: 'bg-amber-500/20 text-amber-700 dark:text-amber-300' },
  supplier: { label: 'Supplier', cls: 'bg-zinc-500/20 text-zinc-600 dark:text-zinc-300' },
};

const STATUS = {
  delivered: { Icon: CheckCheck, cls: 'text-emerald-500', label: 'Delivered to inbox' },
  pending: { Icon: Check, cls: 'text-zinc-400', label: 'Sent — waiting for delivery confirmation' },
  bounced: { Icon: XCircle, cls: 'text-red-500', label: 'Not delivered (bounced)' },
  failed: { Icon: XCircle, cls: 'text-red-500', label: 'Not delivered — Master Admin → Email log can resend it' },
  unknown: { Icon: HelpCircle, cls: 'text-zinc-400', label: 'Delivery not tracked for this older fault' },
};

function fallbackRecipients(issue) {
  const list = (Array.isArray(issue.notified_recipients) ? issue.notified_recipients : []).map((r) => ({
    role: r.role, name: r.name, email: r.email, at: r.at,
    status: r.delivery_status || (r.delivered === false ? 'failed' : 'pending'),
  }));
  const sc = issue.supplier_case;
  if (sc?.supplier_email && !list.some((r) => (r.email || '').toLowerCase() === sc.supplier_email.toLowerCase())) {
    list.push({ role: 'supplier', name: sc.supplier_name, email: sc.supplier_email, at: issue.auto_dispatched_at, status: 'pending' });
  }
  return list;
}

export default function FaultNotifiedCard({ issue, API }) {
  const [recipients, setRecipients] = useState(() => fallbackRecipients(issue));
  const hasAny = recipients.length > 0 || !!issue.supplier_case?.supplier_name;

  useEffect(() => {
    setRecipients(fallbackRecipients(issue));
    if (!issue?.id) return undefined;
    let cancelled = false;
    const token = localStorage.getItem('token');
    axios.get(`${API}/issues/${issue.id}/delivery-status`, { headers: { Authorization: `Bearer ${token}` } })
      .then((res) => { if (!cancelled && Array.isArray(res.data?.recipients)) setRecipients(res.data.recipients); })
      .catch(() => { /* keep the fallback list */ });
    return () => { cancelled = true; };
  }, [issue?.id, API]);

  if (!hasAny) return null;
  const firstAt = recipients.find((r) => r.at)?.at;
  const token = issue.supplier_case?.token;

  return (
    <div className="p-4 rounded-xl bg-emerald-500/5 border border-emerald-500/20" data-testid={`issue-notified-card-${issue.id}`}>
      <div className="flex items-center justify-between gap-2 mb-2">
        <div className="flex items-center gap-2">
          <CheckCircle size={14} className="text-emerald-500" />
          <span className="text-[var(--color-text-muted)] text-xs uppercase tracking-wide">Notified</span>
        </div>
        {token && (
          <Button size="sm" variant="outline"
            onClick={() => window.open(`/supplier/case/${token}?view=site`, '_blank', 'noopener')}
            className="border-emerald-500/40 text-emerald-600 dark:text-emerald-400 hover:bg-emerald-500/20 text-xs h-7"
            data-testid={`supplier-sent-view-${issue.id}`}>
            View card
          </Button>
        )}
      </div>
      <div className="space-y-1.5">
        {recipients.map((r, i) => {
          const badge = ROLE_BADGE[r.role] || ROLE_BADGE.supplier;
          const st = STATUS[r.status] || STATUS.unknown;
          const { Icon } = st;
          return (
            <div key={`${r.email || i}-${i}`} className="flex items-center justify-between gap-3 text-sm" data-testid={`issue-notified-${issue.id}-${i}`}>
              <div className="min-w-0 flex items-center gap-2">
                <span className={`text-[9px] uppercase font-bold px-1.5 py-0.5 rounded shrink-0 ${badge.cls}`}>{badge.label}</span>
                <span className="text-[var(--theme-text,#fff)] font-medium truncate">{r.name || r.email}</span>
                <span className={`inline-flex shrink-0 ${st.cls}`} title={st.label} aria-label={st.label}
                  data-testid={`issue-notified-tick-${issue.id}-${i}`} data-status={r.status}>
                  <Icon size={15} strokeWidth={2.5} />
                </span>
              </div>
              <span className="text-[var(--color-text-muted)] text-xs truncate min-w-0">{r.email}</span>
            </div>
          );
        })}
      </div>
      <p className="text-[11px] text-[var(--color-text-muted)] mt-2">
        Emailed {firstAt ? new Date(firstAt).toLocaleString() : 'when the job was logged'}.{' '}
        <span className="inline-flex items-center gap-1"><CheckCheck size={11} className="text-emerald-500" /> = delivered to their inbox</span>
      </p>
    </div>
  );
}

/**
 * Public, multi-currency module pricing for the /pulse-pricing page.
 * Modules are the product: Operations is the flagship ("Pulse Fitness Pro").
 * Prices come live from Stripe via GET /api/payments/pricing/live (public).
 * CTAs route unauthenticated visitors into sign-in/start; the actual Stripe
 * checkout stays behind auth at /choose-plan.
 */
import { useEffect, useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { motion } from 'framer-motion';
import { ArrowRight, Check, Loader2, Sparkles } from 'lucide-react';
import { toast } from 'sonner';
import { useAuth } from '@/App';

const CCY = { gbp: '£', eur: '€', usd: '$' };

const MODULE_META = {
  operations: { name: 'Operations', tag: 'Pulse Fitness Pro', blurbKey: 'pulse_pricing.blurb_operations' },
  crm: { name: 'CRM', blurbKey: 'pulse_pricing.blurb_crm' },
  marketing: { name: 'Marketing', blurbKey: 'pulse_pricing.blurb_marketing' },
  memberships: { name: 'Memberships', blurbKey: 'pulse_pricing.blurb_memberships' },
};
const ORDER = ['operations', 'crm', 'marketing', 'memberships'];

export default function PulseModulePricing({ onStart }) {
  const { API, user, token } = useAuth();
  const { t, i18n } = useTranslation();
  const navigate = useNavigate();
  const [live, setLive] = useState(null);
  const [trialBusy, setTrialBusy] = useState(false);
  // Language nudges the currency (FR/DE → €), so the price matches the words a
  // visitor sees. IP-detected currency disambiguates GBP vs USD for English.
  const langCcy = (l, detected) => {
    const base = (l || 'en').slice(0, 2);
    if (base === 'de' || base === 'fr') return 'eur';
    return detected || 'gbp';
  };
  const [currency, setCurrency] = useState(() => langCcy(i18n.language));
  const [ccyPicked, setCcyPicked] = useState(false);
  const [cycle, setCycle] = useState('monthly');
  const annual = cycle === 'annual';

  useEffect(() => {
    let cancelled = false;
    axios.get(`${API}/payments/pricing/live`)
      .then((r) => { if (!cancelled) { setLive(r.data); if (!ccyPicked) setCurrency(langCcy(i18n.language, r.data?.detected_currency)); } })
      .catch(() => {});
    return () => { cancelled = true; };
  }, [API]); // eslint-disable-line react-hooks/exhaustive-deps

  // Re-nudge currency if the visitor switches language (unless they picked one).
  useEffect(() => {
    if (!ccyPicked) setCurrency(langCcy(i18n.language, live?.detected_currency));
  }, [i18n.language]); // eslint-disable-line react-hooks/exhaustive-deps

  const fmt = (id) => {
    const node = live?.pricing?.[id]?.[currency];
    if (!node) return null;
    const minor = annual ? node.annual : node.monthly;
    return minor == null ? null : `${CCY[currency]}${Math.round(minor / 100)}`;
  };

  const start = (moduleId) => {
    const qs = `?module=${moduleId}&billing=${cycle}&currency=${currency}`;
    const dest = `/choose-plan${qs}`;
    // Everyone is already a Pulse Lite customer, so there is no public sign-up:
    // logged-in users go straight to Stripe checkout for the chosen module;
    // otherwise they sign in first and are then routed to the same checkout.
    if (user) navigate(dest);
    else if (onStart) onStart(dest);
    else navigate(`/login?next=${encodeURIComponent(dest)}`);
  };

  // Lite is included free with a Pulse Fitness equipment agreement — the CTA
  // just takes the customer into their existing portal (or sign-in first).
  const goToPortal = () => {
    if (user) navigate('/dashboard');
    else if (onStart) onStart('/dashboard');
    else navigate('/login?next=/dashboard');
  };

  // Start a free 3-day trial with ALL modules unlocked (owners/managers only).
  const startTrial = async () => {
    if (!user) { if (onStart) onStart('/dashboard'); else navigate('/login?next=/dashboard'); return; }
    setTrialBusy(true);
    try {
      const r = await axios.post(
        `${API}/me/upgrade-to-pro`,
        { start_trials: ['crm', 'marketing', 'memberships'] },
        { headers: { Authorization: `Bearer ${token}` } },
      );
      if (r.data?.already_pro) toast.info("You're already on Pulse Pro — all modules are available.");
      else toast.success('Your free 3-day trial is live — all modules unlocked.');
      navigate('/dashboard');
    } catch (e) {
      toast.error(e?.response?.data?.detail || 'Could not start the trial. Please try again.');
    } finally {
      setTrialBusy(false);
    }
  };

  const pillBase = 'px-3.5 h-8 rounded-full text-sm font-semibold transition-colors';
  const activePill = 'bg-[var(--pulse-primary)] text-[#1B1C1D]';
  const idlePill = 'text-[var(--color-text-slate)] hover:text-[var(--color-surface-dark-panel-alt)]';

  return (
    <section className="relative py-6" data-testid="pulse-module-pricing">
      <div className="max-w-6xl mx-auto px-6">
        <div className="text-center max-w-2xl mx-auto">
          <div className="text-xs uppercase tracking-[0.18em] text-[var(--pulse-primary)] font-semibold mb-3">{t('pulse_pricing.modules_eyebrow', 'Modules')}</div>
          <h2 className="text-2xl sm:text-4xl font-bold tracking-[-0.02em] text-[var(--color-surface-dark-panel-alt)]">
            {t('pulse_pricing.heading', 'Build your platform, one module at a time.')}
          </h2>
          <p className="mt-3 text-sm sm:text-base text-[var(--color-text-slate)]">
            {t('pulse_pricing.subtitle', 'Every module is a standalone subscription — mix and match, cancel anytime. Priced in your currency.')}
          </p>
        </div>

        {/* Currency + billing controls */}
        <div className="mt-7 flex flex-wrap items-center justify-center gap-3" data-testid="pulse-pricing-controls">
          <div className="inline-flex rounded-full border border-[var(--color-border-subtle,#e0e0e0)] bg-white p-1" data-testid="pulse-currency-toggle">
            {['gbp', 'eur', 'usd'].map((c) => (
              <button key={c} type="button" onClick={() => { setCcyPicked(true); setCurrency(c); }}
                className={`${pillBase} ${currency === c ? activePill : idlePill}`} data-testid={`pulse-currency-${c}`}>
                {CCY[c]} {c.toUpperCase()}
              </button>
            ))}
          </div>
          <div className="inline-flex items-center rounded-full border border-[var(--color-border-subtle,#e0e0e0)] bg-white p-1" data-testid="pulse-billing-toggle">
            {[['monthly', t('pulse_pricing.monthly', 'Monthly')], ['annual', t('pulse_pricing.annual', 'Annual')]].map(([v, label]) => (
              <button key={v} type="button" onClick={() => setCycle(v)}
                className={`${pillBase} ${cycle === v ? activePill : idlePill}`} data-testid={`pulse-billing-${v}`}>
                {label}
              </button>
            ))}
            {live?.annual_discount_pct ? (
              <span className="px-2.5 text-xs font-semibold text-[var(--pulse-primary)]">{t('pulse_pricing.save_pct', 'Save {{pct}}%', { pct: live.annual_discount_pct })}</span>
            ) : null}
          </div>
        </div>

        {/* Module cards */}
        <div className="mt-8 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
          {ORDER.map((id, i) => {
            const meta = MODULE_META[id];
            const featured = id === 'operations';
            const price = fmt(id);
            return (
              <motion.div
                key={id}
                initial={{ opacity: 0, y: 16 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ duration: 0.5, delay: i * 0.05 }}
                className={`relative rounded-2xl bg-white p-6 flex flex-col ${featured ? 'border-2 border-[var(--pulse-primary)] shadow-lg' : 'border border-[var(--color-border-subtle,#e0e0e0)]'}`}
                data-testid={`pulse-module-card-${id}`}
              >
                {featured ? (
                  <span className="absolute -top-2.5 left-6 bg-[var(--pulse-primary)] text-[#1B1C1D] text-[10px] font-bold uppercase tracking-[0.14em] px-2.5 py-0.5 rounded-full" data-testid="pulse-flagship-badge">
                    {t('pulse_pricing.recommended', 'Recommended')}
                  </span>
                ) : null}
                <div className="font-bold text-lg text-[var(--color-surface-dark-panel-alt)]">{meta.name}</div>
                {featured ? <div className="text-xs font-semibold text-[var(--pulse-primary)] mt-0.5">Pulse Fitness Pro</div> : null}
                <p className="text-xs text-[var(--color-text-slate)] mt-2 leading-relaxed min-h-[48px]">{t(meta.blurbKey)}</p>
                <div className="mt-4 flex items-baseline gap-1">
                  <span className="text-3xl font-extrabold text-[var(--color-surface-dark-panel-alt)]" data-testid={`pulse-module-price-${id}`}>{price || '—'}</span>
                  <span className="text-sm text-[var(--color-text-slate)]">{annual ? t('pulse_pricing.per_year', '/yr') : t('pulse_pricing.per_month', '/mo')}</span>
                </div>
                <button
                  type="button"
                  onClick={() => start(id)}
                  className={`mt-5 w-full h-11 rounded-full font-semibold text-sm flex items-center justify-center gap-2 transition-colors ${featured ? 'bg-[var(--pulse-primary)] hover:brightness-95 text-[#1B1C1D]' : 'border border-[var(--color-border-subtle,#c9cbcc)] text-[var(--color-surface-dark-panel-alt)] hover:border-[var(--pulse-primary)]'}`}
                  data-testid={`pulse-module-start-${id}`}
                >
                  {user
                    ? <>{t('pulse_pricing.cta_upgrade', 'Upgrade to')} {featured ? 'Pulse Fitness Pro' : meta.name}</>
                    : <>{t('pulse_pricing.cta_signin_upgrade', 'Sign in to upgrade')}</>} <ArrowRight size={15} />
                </button>
              </motion.div>
            );
          })}
        </div>

        {/* Lite — free, included with a Pulse Fitness equipment agreement.
            Light styling to match the module cards on the light pricing page. */}
        <div
          className="mt-6 rounded-2xl border border-[var(--color-border-subtle,#c9cbcc)] bg-white p-5 sm:p-6 flex flex-col sm:flex-row sm:items-center justify-between gap-4"
          data-testid="pulse-module-lite-tile"
        >
          <div className="flex items-start gap-3">
            <span className="mt-0.5 inline-flex items-center justify-center w-9 h-9 rounded-xl bg-[var(--pulse-primary)]/15 text-[var(--pulse-primary)]">
              <Sparkles size={18} />
            </span>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="text-lg font-bold text-[var(--color-surface-dark-panel-alt,#1b1c1d)]">Lite</h3>
                <span className="text-xs font-bold uppercase tracking-wide px-2 py-0.5 rounded-full bg-[var(--pulse-primary)] text-[#1B1C1D]">Free</span>
              </div>
              <p className="text-sm text-[var(--color-text-slate,#565B5E)] mt-0.5 max-w-md">
                {t('pulse_pricing.lite_blurb', 'Included free with your Pulse Fitness equipment agreement — asset register, fault logging and your service portal.')}
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={goToPortal}
            className="shrink-0 h-11 px-5 rounded-full font-semibold text-sm flex items-center justify-center gap-2 border border-[var(--color-border-subtle,#c9cbcc)] text-[var(--color-surface-dark-panel-alt,#1b1c1d)] hover:border-[var(--pulse-primary)] hover:text-[var(--pulse-primary)] transition-colors"
            data-testid="pulse-module-lite-cta"
          >
            {user ? t('pulse_pricing.lite_open', 'Open your portal') : t('pulse_pricing.lite_signin', 'Sign in to your portal')} <ArrowRight size={15} />
          </button>
        </div>

        {/* Free 3-day all-module trial (owners / managers) */}
        <div className="mt-5 flex flex-col items-center gap-2">
          <button
            type="button"
            onClick={startTrial}
            disabled={trialBusy}
            className="h-12 px-7 rounded-full font-bold text-sm flex items-center justify-center gap-2 bg-[var(--pulse-primary)] text-[#1B1C1D] hover:brightness-95 transition disabled:opacity-60"
            data-testid="pulse-start-trial-btn"
          >
            {trialBusy ? <Loader2 size={16} className="animate-spin" /> : <Sparkles size={16} />}
            {t('pulse_pricing.start_trial', 'Start your free 3-day trial (all modules)')}
          </button>
          <p className="text-center text-xs text-[var(--color-text-slate)]">
            {t('pulse_pricing.trial_footer', '3-day free trial · all modules unlocked for owners & managers · cancel anytime')}
          </p>
        </div>
      </div>
    </section>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import axios from 'axios';
import { toast } from 'sonner';
import { Globe, Loader2 } from 'lucide-react';
import { API, useAuthHeaders } from './shared';
import { invalidateLocalization } from '@/utils/localization';

/**
 * Localization panel (Iter 220p1 — USA readiness).
 * Owner / master admin sets the org's market: country drives currency +
 * timezone + tax vocabulary. Defaults to the UK so nothing changes for
 * existing customers.
 */
export default function LocalizationPanel() {
  const { t } = useTranslation();
  const headers = useAuthHeaders();
  const [data, setData] = useState(null);
  const [form, setForm] = useState({ country_code: '', currency: '', timezone: '' });
  const [saving, setSaving] = useState(false);

  const load = useCallback(async () => {
    try {
      const { data } = await axios.get(`${API}/org/localization`, { headers: headers() });
      setData(data);
      const loc = data.localization || {};
      setForm({
        country_code: loc.country_code || 'GB',
        currency: loc.currency || 'GBP',
        timezone: loc.timezone || 'Europe/London',
      });
    } catch {
      setData(null);
    }
  }, [headers]);

  useEffect(() => { load(); }, [load]);

  if (!data) return null;

  const countries = data.supported_countries || [];
  const canEdit = !!data.can_edit;
  const selectedCountry = countries.find((c) => c.code === form.country_code) || countries[0] || {};
  const tzOptions = selectedCountry.timezones || [form.timezone];
  const currencyOptions = Object.keys(data.currency_symbols || { GBP: '£' });

  // When the country changes, snap currency + timezone to that country's defaults.
  const onCountry = (code) => {
    const c = countries.find((x) => x.code === code) || {};
    setForm({
      country_code: code,
      currency: c.currency || form.currency,
      timezone: (c.timezones && c.timezones[0]) || c.timezone || form.timezone,
    });
  };

  const save = async () => {
    setSaving(true);
    try {
      const { data: res } = await axios.put(`${API}/org/localization`, form, { headers: headers() });
      invalidateLocalization();
      const loc = res.localization || {};
      setData((d) => ({ ...d, localization: loc }));
      toast.success(t('settings.loc_market_set', 'Market set to {{country}} · {{currency}}', { country: loc.country_name, currency: loc.currency }));
    } catch (e) {
      toast.error(e.response?.data?.detail || t('settings.loc_update_failed', 'Could not update localization'));
    }
    setSaving(false);
  };

  const taxLabel = selectedCountry.tax_label || data.localization?.tax_label || 'VAT';

  return (
    <div data-testid="account-section-localization">
      <h3 className="account-section-title flex items-center gap-2"><Globe size={15} /> {t('settings.loc_title', 'Region & currency')}</h3>
      <p className="account-section-sub">
        {t('settings.loc_sub', 'Your market drives the currency, timezone and tax wording shown on invoices, quotes and dashboards.')}
      </p>

      <div className="account-card rounded-xl p-5 mt-3 grid sm:grid-cols-3 gap-4">
        <div>
          <label className="text-[11px] uppercase tracking-wider font-semibold block mb-1.5" style={{ color: 'var(--theme-text-muted)' }}>{t('settings.loc_country', 'Country')}</label>
          <select
            value={form.country_code}
            disabled={!canEdit}
            onChange={(e) => onCountry(e.target.value)}
            className="w-full text-sm border rounded-md px-2.5 py-2 bg-transparent disabled:opacity-60"
            style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }}
            data-testid="localization-country-select"
          >
            {countries.map((c) => <option key={c.code} value={c.code}>{c.name}</option>)}
          </select>
        </div>

        <div>
          <label className="text-[11px] uppercase tracking-wider font-semibold block mb-1.5" style={{ color: 'var(--theme-text-muted)' }}>{t('settings.loc_currency', 'Currency')}</label>
          <select
            value={form.currency}
            disabled={!canEdit}
            onChange={(e) => setForm((f) => ({ ...f, currency: e.target.value }))}
            className="w-full text-sm border rounded-md px-2.5 py-2 bg-transparent disabled:opacity-60"
            style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }}
            data-testid="localization-currency-select"
          >
            {currencyOptions.map((cur) => (
              <option key={cur} value={cur}>{cur} ({data.currency_symbols[cur]})</option>
            ))}
          </select>
        </div>

        <div>
          <label className="text-[11px] uppercase tracking-wider font-semibold block mb-1.5" style={{ color: 'var(--theme-text-muted)' }}>{t('settings.loc_timezone', 'Timezone')}</label>
          <select
            value={form.timezone}
            disabled={!canEdit}
            onChange={(e) => setForm((f) => ({ ...f, timezone: e.target.value }))}
            className="w-full text-sm border rounded-md px-2.5 py-2 bg-transparent disabled:opacity-60"
            style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }}
            data-testid="localization-timezone-select"
          >
            {tzOptions.map((tz) => <option key={tz} value={tz}>{tz}</option>)}
          </select>
        </div>

        <div className="sm:col-span-3 flex items-center justify-between flex-wrap gap-2">
          <p className="text-xs" style={{ color: 'var(--theme-text-muted)' }}>
            {t('settings.loc_tax_shown', 'Tax is shown as')} <span className="font-semibold" style={{ color: 'var(--theme-text)' }}>{taxLabel}</span> {t('settings.loc_for_market', 'for this market.')}
            {!canEdit && ` ${t('settings.loc_owner_only', 'Only the Owner can change this.')}`}
          </p>
          {canEdit && (
            <button
              type="button"
              onClick={save}
              disabled={saving}
              className="inline-flex items-center gap-2 text-xs font-bold uppercase tracking-wider px-4 py-2 rounded-md text-white disabled:opacity-50"
              style={{ background: 'var(--theme-accent, #0091ca)' }}
              data-testid="localization-save-btn"
            >
              {saving ? <Loader2 size={13} className="animate-spin" /> : null} {t('settings.loc_save', 'Save market')}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

/**
 * Inline QR-print panel for Account Settings → Onboarding (Iter 216h108).
 *
 * User feedback: "We have lost the ability to print QR codes in bulk
 * within Account Settings". This component restores that — fetches
 * every machine in the org, lets the operator select / select-all,
 * and opens a print-ready window with one QR per machine.
 *
 * Identical print template to PulseSettingsTab so labels look the
 * same wherever they're triggered.
 */
import { useEffect, useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import axios from 'axios';
import { toast } from 'sonner';
import { Printer, Loader2, CheckSquare, Square, Search } from 'lucide-react';
import { API, useAuthHeaders } from './shared';

export default function QrPrintInline({ onClose }) {
  const { t } = useTranslation();
  const headers = useAuthHeaders();
  const [equipment, setEquipment] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selected, setSelected] = useState(new Set());
  const [filter, setFilter] = useState('');

  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const r = await axios.get(`${API}/equipment`, { headers: headers() });
        if (alive) setEquipment(r.data?.equipment || []);
      } catch {
        if (alive) toast.error(t('settings.qr_load_failed', 'Could not load equipment'));
      } finally { if (alive) setLoading(false); }
    })();
    return () => { alive = false; };
  }, [headers]);

  const filtered = useMemo(() => {
    const q = filter.trim().toLowerCase();
    if (!q) return equipment;
    return equipment.filter((e) =>
      [e.name, e.manufacturer, e.model, e.serial_number, e.location]
        .filter(Boolean).some((v) => String(v).toLowerCase().includes(q))
    );
  }, [equipment, filter]);

  const allSelected = filtered.length > 0 && filtered.every((e) => selected.has(e.id));
  const toggleOne = (id) => setSelected((p) => {
    const n = new Set(p); n.has(id) ? n.delete(id) : n.add(id); return n;
  });
  const toggleAll = () => setSelected((p) => {
    const n = new Set(p);
    if (allSelected) filtered.forEach((e) => n.delete(e.id));
    else filtered.forEach((e) => n.add(e.id));
    return n;
  });

  const printSelected = () => {
    const items = equipment.filter((e) => selected.has(e.id));
    if (!items.length) { toast.error(t('settings.qr_select_one', 'Select at least one machine')); return; }
    const printWindow = window.open('', '_blank');
    if (!printWindow) { toast.error(t('settings.qr_popup_blocked', 'Pop-up blocked — please allow pop-ups to print')); return; }
    const origin = window.location.origin;
    // Pulse Fitness logo CDN — same asset used by PulseSettingsTab so
    // labels look identical wherever they're triggered.
    const logoUrl = 'https://customer-assets.emergentagent.com/job_maintenance-hub-357/artifacts/iscy9t7o_Pulse%20Fitness%20Primary%20Logo%20Badge%20RGB.jpg';
    const rows = items.map((eq) => {
      const url = `${origin}/scan/${eq.id}`;
      const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(url)}`;
      const itemCode = eq.model || eq.equipment_type || '';
      const fullName = eq.name || 'Unknown';
      const name = fullName.includes(',') ? fullName.split(',')[0].trim() : (fullName.length > 35 ? fullName.slice(0, 35) + '…' : fullName);
      const serial = eq.serial_number || '';
      return `<div style="width:200px;text-align:center;page-break-inside:avoid;margin:8px;border:1px dashed #ccc;border-radius:8px;padding:10px 6px 8px;">
        <img src="${qrUrl}" width="140" height="140" style="display:block;margin:0 auto;" />
        <img src="${logoUrl}" width="70" style="display:block;margin:6px auto 2px;" />
        ${itemCode ? `<p style="font-size:11px;color:#000;margin:4px 0 0;font-family:sans-serif;font-weight:800;letter-spacing:0.3px;">${itemCode}</p>` : ''}
        <p style="font-size:9px;color:#000;margin:2px 0 0;font-family:sans-serif;font-weight:600;line-height:1.2;">${name}</p>
        ${serial ? `<p style="font-size:8px;color:#000;font-family:monospace;margin:3px 0 0;background:#f0f0f0;display:inline-block;padding:1px 6px;border-radius:3px;">S/N: ${serial}</p>` : ''}
      </div>`;
    }).join('');
    printWindow.document.write(`<!DOCTYPE html><html><head><title>QR Codes</title>
      <style>@media print{body{margin:0}}body{font-family:sans-serif}</style></head>
      <body><div style="display:flex;flex-wrap:wrap;justify-content:center;gap:4px;padding:12px;">${rows}</div>
      <script>setTimeout(()=>window.print(),1500)</script></body></html>`);
    printWindow.document.close();
  };

  if (loading) {
    return <div className="flex items-center gap-2 text-sm" style={{ color: 'var(--theme-text-muted)' }}><Loader2 size={14} className="animate-spin" /> {t('settings.qr_loading', 'Loading equipment…')}</div>;
  }

  return (
    <div className="space-y-3" data-testid="account-qr-print-inline">
      <div>
        <h3 className="text-base font-semibold" style={{ color: 'var(--theme-text)' }}>{t('settings.qr_title', 'Print QR codes')}</h3>
        <p className="text-xs mt-1" style={{ color: 'var(--theme-text-muted)' }}>
          {t('settings.qr_sub', 'Select the machines you want labels for, then click Print. Each label includes a unique scan URL, your brand logo, the model, serial number, and asset name.')}
        </p>
      </div>

      <div className="flex flex-wrap items-center gap-2">
        <div className="relative flex-1 min-w-[180px]">
          <Search size={13} className="absolute left-2.5 top-1/2 -translate-y-1/2" style={{ color: 'var(--theme-text-muted)' }} />
          <input
            value={filter}
            onChange={(e) => setFilter(e.target.value)}
            placeholder={t('settings.qr_search_ph', 'Search machines…')}
            className="w-full pl-7 pr-3 py-1.5 text-xs rounded-md border focus:outline-none"
            style={{ background: 'var(--theme-surface)', border: '1px solid var(--theme-border)', color: 'var(--theme-text)' }}
            data-testid="account-qr-search"
          />
        </div>
        <button
          type="button"
          onClick={toggleAll}
          className="account-btn-secondary inline-flex items-center gap-1.5 text-xs"
          data-testid="account-qr-select-all"
        >
          {allSelected ? <CheckSquare size={13} /> : <Square size={13} />}
          {allSelected ? t('settings.qr_deselect_all', 'Deselect all') : t('settings.qr_select_all', 'Select all')}
        </button>
      </div>

      <div className="max-h-64 overflow-auto rounded-lg border" style={{ borderColor: 'var(--theme-border)' }} data-testid="account-qr-list">
        {filtered.length === 0 ? (
          <p className="p-4 text-xs text-center" style={{ color: 'var(--theme-text-muted)' }}>{t('settings.qr_no_match', 'No equipment matches.')}</p>
        ) : filtered.map((eq) => (
          <label
            key={eq.id}
            className="flex items-center gap-3 px-3 py-2 text-sm cursor-pointer hover:bg-black/[0.02]"
            style={{ borderTop: '1px solid var(--theme-border)' }}
            data-testid={`account-qr-row-${eq.id}`}
          >
            <input
              type="checkbox"
              checked={selected.has(eq.id)}
              onChange={() => toggleOne(eq.id)}
              data-testid={`account-qr-check-${eq.id}`}
            />
            <div className="flex-1 min-w-0">
              <div className="text-sm font-medium truncate" style={{ color: 'var(--theme-text)' }}>{eq.name}</div>
              <div className="text-[11px] truncate" style={{ color: 'var(--theme-text-muted)' }}>
                {[eq.manufacturer, eq.model, eq.serial_number].filter(Boolean).join(' · ') || '—'}
              </div>
            </div>
          </label>
        ))}
      </div>

      <div className="flex items-center justify-between pt-2">
        <span className="text-xs" style={{ color: 'var(--theme-text-muted)' }}>
          {t('settings.qr_selected_count', '{{sel}} of {{total}} selected', { sel: selected.size, total: equipment.length })}
        </span>
        <div className="flex gap-2">
          <button type="button" onClick={onClose} className="account-btn-secondary" data-testid="account-qr-close">
            {t('settings.qr_back', 'Back')}
          </button>
          <button
            type="button"
            onClick={printSelected}
            disabled={selected.size === 0}
            className="account-btn-primary inline-flex items-center gap-2 disabled:opacity-50"
            data-testid="account-qr-print-btn"
          >
            <Printer size={14} /> {t('settings.qr_print_n', 'Print {{n}} QR', { n: selected.size || '', count: selected.size })}
          </button>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import axios from 'axios';
import { useAuth } from '@/App';
import { notify } from '@/components/notifications';
import { notifyApiError } from '@/lib/formatApiError';
import { Gift, Loader2, CheckCircle2 } from 'lucide-react';

const API = process.env.REACT_APP_BACKEND_URL;

// Shown in Plan & Billing to Lite owners whose one free Pulse Pro trial is used.
export default function TrialRequestCard() {
  const { user } = useAuth();
  const [trial, setTrial] = useState(null);
  const [note, setNote] = useState('');
  const [busy, setBusy] = useState(false);
  const isLiteOwner = (user?.account_type || '').toLowerCase() === 'lite' && (user?.role || '').toLowerCase() === 'owner';
  const headers = { Authorization: `Bearer ${localStorage.getItem('token') || ''}` };

  useEffect(() => {
    if (!isLiteOwner) return;
    axios.get(`${API}/api/me/pro-trial`, { headers }).then((r) => setTrial(r.data)).catch(() => setTrial(null));
    // eslint-disable-next-line react-hooks/exhaustive-deps -- headers rebuilt each render
  }, [isLiteOwner]);

  if (!isLiteOwner || !trial || trial.available) return null;

  const send = async () => {
    setBusy(true);
    try {
      const r = await axios.post(`${API}/api/me/pro-trial/request`, { note }, { headers });
      setTrial({ ...trial, requested_at: r.data.requested_at });
      notify.success('Request sent', 'The Pulse team will be in touch about another free trial.');
    } catch (e) { notifyApiError(notify, e, 'Could not send the request'); }
    setBusy(false);
  };

  return (
    <div className="rounded-xl border p-4" style={{ borderColor: 'var(--theme-border, #e0e0e0)' }} data-testid="trial-request-card">
      <p className="text-sm font-semibold flex items-center gap-1.5" style={{ color: 'var(--theme-text)' }}>
        <Gift size={15} /> Free Pulse Pro trial already used
      </p>
      {trial.requested_at ? (
        <p className="text-xs mt-1.5 flex items-center gap-1 text-emerald-600" data-testid="trial-request-sent">
          <CheckCircle2 size={13} /> Request sent {new Date(trial.requested_at).toLocaleDateString()} — we'll be in touch.
        </p>
      ) : (
        <>
          <p className="text-xs mt-1" style={{ color: 'var(--theme-text-muted, #6e7476)' }}>
            Need more time to try Memberships, Marketing or CRM? Ask the Pulse team for another trial.
          </p>
          <textarea value={note} onChange={(e) => setNote(e.target.value)} rows={2} maxLength={500}
            placeholder="Optional — tell us what you'd like to try"
            className="mt-2 w-full rounded-md border px-2.5 py-1.5 text-sm bg-transparent" data-testid="trial-request-note" />
          <button type="button" onClick={send} disabled={busy}
            className="mt-2 inline-flex items-center gap-1.5 rounded-full px-4 py-1.5 text-sm font-semibold"
            style={{ background: '#f59e0b', color: '#1b1c1d' }} data-testid="trial-request-btn">
            {busy ? <Loader2 size={14} className="animate-spin" /> : <Gift size={14} />} Request another trial
          </button>
        </>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import axios from 'axios';
import { toast } from 'sonner';
import { Check, Loader2, Rocket, ChevronDown, ClipboardList, Upload, ArrowLeft } from 'lucide-react';
import { API, useAuthHeaders } from './shared';
import { useNavigate } from 'react-router-dom';
import EquipmentImportInline from './EquipmentImportInline';
import QrPrintInline from './QrPrintInline';
import StripeConnectErrorBanner from '@/components/shared/StripeConnectErrorBanner';

const PORTAL_STATUS_IDS = ['in_progress', 'ready_for_review', 'complete'];

function CustomerPortalPanel() {
  const { t } = useTranslation();
  const headers = useAuthHeaders();
  const PORTAL_STATUSES = [
    { id: 'in_progress', label: t('settings.ob_status_in_progress', 'In progress') },
    { id: 'ready_for_review', label: t('settings.ob_status_ready', 'Ready for review') },
    { id: 'complete', label: t('settings.ob_status_complete', 'Complete') },
  ];
  const [portal, setPortal] = useState(null);
  const [loading, setLoading] = useState(true);
  const [savingStep, setSavingStep] = useState(null);

  const load = async () => {
    try {
      const { data } = await axios.get(`${API}/onboarding/portal/me`, { headers: headers() });
      setPortal(data);
    } catch {
      setPortal(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); /* eslint-disable-next-line */ }, []);

  const setStep = async (stepId, status) => {
    setSavingStep(stepId);
    try {
      await axios.patch(`${API}/onboarding/portal/me/steps/${stepId}`, { status }, { headers: headers() });
      await load();
      toast.success(t('settings.ob_step_updated', 'Step updated'));
    } catch (e) {
      toast.error(e.response?.data?.detail || t('settings.ob_step_failed', 'Could not update step'));
    } finally {
      setSavingStep(null);
    }
  };

  if (loading || !portal) return null;

  const pct = portal.progress?.percent ?? 0;
  const groups = (portal.steps || []).reduce((acc, s) => { (acc[s.group] = acc[s.group] || []).push(s); return acc; }, {});

  return (
    <div className="space-y-4 pb-5 mb-5 border-b" style={{ borderColor: 'var(--theme-border)' }} data-testid="customer-onboarding-portal">
      <div className="flex items-center gap-2">
        <Rocket size={16} style={{ color: 'var(--brand-color, var(--color-brand-blue))' }} />
        <div>
          <h3 className="account-section-title">{t('settings.ob_your_onboarding', 'Your onboarding')}</h3>
          <p className="account-section-sub">
            {t('settings.ob_required_complete', '{{done}} of {{total}} required steps complete', { done: portal.progress?.required_complete ?? 0, total: portal.progress?.required_total ?? 0 })}
            {portal.go_live_target ? ` · ${t('settings.ob_go_live', 'go-live target')} ${String(portal.go_live_target).slice(0, 10)}` : ''}
          </p>
        </div>
      </div>
      <div className="rounded-full overflow-hidden h-2 w-full" style={{ background: 'var(--theme-border-soft)' }}>
        <div className="h-full rounded-full transition-all" style={{ width: `${pct}%`, background: 'var(--brand-color, var(--color-brand-blue))' }} data-testid="portal-progress" />
      </div>
      <div className="space-y-4">
        {Object.entries(groups).map(([grp, steps]) => (
          <div key={grp}>
            <p className="text-[10px] uppercase tracking-wider font-semibold mb-1.5" style={{ color: 'var(--theme-text-muted)' }}>{grp}</p>
            <div className="space-y-1.5">
              {steps.map((s) => (
                <div key={s.id} className="account-card rounded-lg p-2.5 flex items-center gap-2" data-testid={`portal-step-${s.id}`}>
                  <div className="w-4 h-4 rounded-full flex items-center justify-center flex-shrink-0"
                       style={{ background: s.status === 'complete' ? 'var(--brand-color, var(--color-brand-blue))' : 'transparent', border: s.status === 'complete' ? 'none' : '1.5px solid var(--theme-border)' }}>
                    {s.status === 'complete' && <Check size={10} color="#FFFFFF" strokeWidth={3} />}
                  </div>
                  <span className="flex-1 text-sm" style={{ color: 'var(--theme-text)' }}>
                    {s.label}{s.optional && <span className="text-[10px] ml-1" style={{ color: 'var(--theme-text-muted)' }}>{t('settings.ob_optional', '(optional)')}</span>}
                  </span>
                  <div className="relative flex items-center">
                    {savingStep === s.id && <Loader2 size={13} className="animate-spin mr-1.5" style={{ color: 'var(--theme-text-muted)' }} />}
                    <select
                      value={PORTAL_STATUSES.some((o) => o.id === s.status) ? s.status : ''}
                      onChange={(e) => setStep(s.id, e.target.value)}
                      disabled={savingStep === s.id}
                      className="account-input account-input-sm pr-6 appearance-none"
                      style={{ width: 140 }}
                      data-testid={`portal-step-status-${s.id}`}
                    >
                      {!PORTAL_STATUSES.some((o) => o.id === s.status) && <option value="" disabled>{t('settings.ob_update', 'Update…')}</option>}
                      {PORTAL_STATUSES.map((o) => <option key={o.id} value={o.id}>{o.label}</option>)}
                    </select>
                    <ChevronDown size={12} className="absolute right-2 pointer-events-none" style={{ color: 'var(--theme-text-muted)' }} />
                  </div>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

// ── Pre-Install Site Survey customer portal ─────────────────────────
function PortalField({ f, value, onChange }) {
  const { t } = useTranslation();
  const label = (
    <div className="text-[11px] font-semibold uppercase tracking-wide mb-1" style={{ color: 'var(--theme-text-muted)' }}>{f.label}</div>
  );
  if (f.type === 'boolean') {
    return (
      <label className="block">{label}
        <div className="flex gap-2">
          {[[t('settings.ob_yes', 'Yes'), true], [t('settings.ob_no', 'No'), false]].map(([lbl, val]) => (
            <button key={String(val)} type="button" onClick={() => onChange(val)}
              className="px-3 py-1.5 text-xs font-medium rounded-md border"
              style={value === val
                ? { background: 'var(--brand-color, var(--color-brand-blue))', color: '#fff', borderColor: 'transparent' }
                : { borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }}
              data-testid={`survey-portal-field-${f.key}-${val ? 'yes' : 'no'}`}>{lbl}</button>
          ))}
        </div>
      </label>
    );
  }
  if (f.type === 'select') {
    return (
      <label className="block">{label}
        <select className="account-input" value={value || ''} onChange={(e) => onChange(e.target.value)} data-testid={`survey-portal-field-${f.key}`}>
          <option value="">—</option>
          {(f.options || []).map((o) => <option key={o} value={o}>{o}</option>)}
        </select>
      </label>
    );
  }
  if (f.type === 'textarea') {
    return (<label className="block">{label}<textarea className="account-input" style={{ height: 64, padding: 8 }} value={value || ''} onChange={(e) => onChange(e.target.value)} data-testid={`survey-portal-field-${f.key}`} /></label>);
  }
  const inputType = f.type === 'number' ? 'number' : (f.type === 'date' ? 'date' : 'text');
  return (<label className="block">{label}<input className="account-input" type={inputType} value={value ?? ''} onChange={(e) => onChange(e.target.value)} data-testid={`survey-portal-field-${f.key}`} /></label>);
}

function SurveyPortalDetail({ survey, onBack, headers }) {
  const { t } = useTranslation();
  const [data, setData] = useState(survey.data || {});
  const [saving, setSaving] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [attachments, setAttachments] = useState([]);
  const [cat, setCat] = useState('floor_plans');
  const schema = survey.schema || [];
  const uploadCats = survey.upload_categories || [];

  const loadAtt = async () => {
    try {
      const { data: r } = await axios.get(`${API}/survey-portal/surveys/${survey.id}/attachments`, { headers: headers() });
      setAttachments(r.attachments || []);
    } catch { /* ignore */ }
  };
  useEffect(() => { loadAtt(); /* eslint-disable-next-line */ }, []);

  const setField = (sec, key, val) => setData((d) => ({ ...d, [sec]: { ...(d[sec] || {}), [key]: val } }));
  const setContact = (idx, key, val) => setData((d) => { const a = [...(d.site_contacts || [])]; a[idx] = { ...(a[idx] || {}), [key]: val }; return { ...d, site_contacts: a }; });
  const addContact = () => setData((d) => ({ ...d, site_contacts: [...(d.site_contacts || []), {}] }));
  const removeContact = (idx) => setData((d) => ({ ...d, site_contacts: (d.site_contacts || []).filter((_, i) => i !== idx) }));

  const save = async () => {
    setSaving(true);
    try {
      await axios.put(`${API}/survey-portal/surveys/${survey.id}`, { data }, { headers: headers() });
      toast.success(t('settings.ob_survey_sent', 'Thank you — your information has been sent to the installation team'));
      onBack(true);
    } catch (e) { toast.error(e.response?.data?.detail || t('settings.ob_survey_save_failed', 'Could not save')); } finally { setSaving(false); }
  };
  const upload = async (file) => {
    if (!file) return;
    setUploading(true);
    try {
      const fd = new FormData(); fd.append('file', file);
      await axios.post(`${API}/survey-portal/surveys/${survey.id}/attachments?category=${cat}`, fd, { headers: { ...headers() } });
      toast.success(t('settings.ob_file_uploaded', 'File uploaded')); await loadAtt();
    } catch (e) { toast.error(e?.response?.status === 413 ? t('settings.ob_file_too_large', 'File too large (max 25MB)') : t('settings.ob_upload_failed', 'Upload failed')); } finally { setUploading(false); }
  };

  return (
    <div className="space-y-4" data-testid="survey-portal-detail">
      <button onClick={() => onBack(false)} className="account-btn-secondary" data-testid="survey-portal-back"><ArrowLeft size={13} /> {t('settings.ob_back_surveys', 'Back to surveys')}</button>
      <div>
        <h3 className="account-section-title">{survey.reference} — {survey.site_name || t('settings.ob_your_site', 'Your site')}</h3>
        <p className="account-section-sub">{t('settings.ob_survey_detail_sub', 'Please confirm the details below and upload a floor plan or site photos to help our installation team prepare.')}</p>
      </div>

      {schema.map((sec) => (
        <div key={sec.id} className="account-card rounded-lg p-3" data-testid={`survey-portal-section-${sec.id}`}>
          <p className="text-xs font-bold mb-2" style={{ color: 'var(--theme-text)' }}>{sec.title}</p>
          {sec.repeatable ? (
            <div className="space-y-3">
              {(data[sec.id] || []).map((item, idx) => (
                <div key={idx} className="rounded-md border p-2.5" style={{ borderColor: 'var(--theme-border)' }}>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                    {sec.fields.map((f) => <PortalField key={f.key} f={f} value={item[f.key]} onChange={(v) => setContact(idx, f.key, v)} />)}
                  </div>
                  <button onClick={() => removeContact(idx)} className="mt-2 text-[11px]" style={{ color: 'var(--color-error-ios, #ef4444)' }}>{t('settings.ob_remove', 'Remove')}</button>
                </div>
              ))}
              <button onClick={addContact} className="account-btn-secondary" data-testid="survey-portal-add-contact">{t('settings.ob_add_contact', '+ Add contact')}</button>
            </div>
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
              {sec.fields.map((f) => <PortalField key={f.key} f={f} value={(data[sec.id] || {})[f.key]} onChange={(v) => setField(sec.id, f.key, v)} />)}
            </div>
          )}
        </div>
      ))}

      <div className="account-card rounded-lg p-3" data-testid="survey-portal-uploads">
        <div className="flex items-center justify-between mb-2 flex-wrap gap-2">
          <p className="text-xs font-bold" style={{ color: 'var(--theme-text)' }}>{t('settings.ob_floor_plan', 'Floor plan / photos')}</p>
          <div className="flex items-center gap-2">
            <select className="account-input account-input-sm" style={{ width: 160 }} value={cat} onChange={(e) => setCat(e.target.value)} data-testid="survey-portal-upload-cat">
              {uploadCats.map((u) => <option key={u.key} value={u.key}>{u.label}</option>)}
            </select>
            <label className="account-btn-secondary cursor-pointer" data-testid="survey-portal-upload-btn">
              {uploading ? <Loader2 size={13} className="animate-spin" /> : <Upload size={13} />} {t('settings.ob_upload', 'Upload')}
              <input type="file" className="hidden" accept="image/*,.pdf,.dwg,.dxf" onChange={(e) => upload(e.target.files?.[0])} />
            </label>
          </div>
        </div>
        {attachments.length === 0 ? <p className="text-xs" style={{ color: 'var(--theme-text-muted)' }}>{t('settings.ob_no_files', 'No files uploaded yet.')}</p> : (
          <div className="space-y-1">
            {attachments.map((a) => (
              <div key={a.id} className="text-xs flex items-center gap-2" style={{ color: 'var(--theme-text)' }}>
                <Check size={12} style={{ color: 'var(--brand-color, var(--color-brand-blue))' }} /> {a.original_filename}
                <span className="text-[10px]" style={{ color: 'var(--theme-text-muted)' }}>({a.category?.replace(/_/g, ' ')})</span>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="flex justify-end">
        <button onClick={save} disabled={saving} className="account-btn-primary" data-testid="survey-portal-save">
          {saving ? <Loader2 size={13} className="animate-spin" /> : <Check size={13} />} {t('settings.ob_send_install', 'Send to installation team')}
        </button>
      </div>
    </div>
  );
}

function SurveyPortalPanel() {
  const { t } = useTranslation();
  const headers = useAuthHeaders();
  const [surveys, setSurveys] = useState([]);
  const [loading, setLoading] = useState(true);
  const [openSurvey, setOpenSurvey] = useState(null);

  const load = async () => {
    try {
      const { data } = await axios.get(`${API}/survey-portal/surveys`, { headers: headers() });
      setSurveys(data.enabled ? (data.surveys || []) : []);
    } catch { setSurveys([]); } finally { setLoading(false); }
  };
  useEffect(() => { load(); /* eslint-disable-next-line */ }, []);

  const openOne = async (id) => {
    try {
      const { data } = await axios.get(`${API}/survey-portal/surveys/${id}`, { headers: headers() });
      setOpenSurvey(data);
    } catch (e) { toast.error(t('settings.ob_open_survey_failed', 'Could not open survey')); }
  };

  if (loading || surveys.length === 0) return null;

  if (openSurvey) {
    return (
      <div className="pb-5 mb-5 border-b" style={{ borderColor: 'var(--theme-border)' }}>
        <SurveyPortalDetail survey={openSurvey} headers={headers}
          onBack={(refresh) => { setOpenSurvey(null); if (refresh) load(); }} />
      </div>
    );
  }

  return (
    <div className="space-y-3 pb-5 mb-5 border-b" style={{ borderColor: 'var(--theme-border)' }} data-testid="survey-portal-panel">
      <div className="flex items-center gap-2">
        <ClipboardList size={16} style={{ color: 'var(--brand-color, var(--color-brand-blue))' }} />
        <div>
          <h3 className="account-section-title">{t('settings.ob_preinstall_title', 'Pre-Install Site Surveys')}</h3>
          <p className="account-section-sub">{t('settings.ob_preinstall_sub', 'Your installer needs a few site details. Please review and add any missing information.')}</p>
        </div>
      </div>
      <div className="space-y-1.5">
        {surveys.map((s) => (
          <button key={s.id} onClick={() => openOne(s.id)} className="account-card rounded-lg p-3 w-full text-left flex items-center gap-2" data-testid={`survey-portal-row-${s.id}`}>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-semibold truncate" style={{ color: 'var(--theme-text)' }}>{s.reference} — {s.site_name || t('settings.ob_your_site', 'Your site')}</p>
              <p className="text-xs" style={{ color: 'var(--theme-text-muted)' }}>{t('settings.ob_info_requested', 'Information requested')}{s.target_install_date ? ` · ${t('settings.ob_target_install', 'target install')} ${String(s.target_install_date).slice(0, 10)}` : ''}</p>
            </div>
            <span className="text-[10px] font-bold uppercase px-2 py-1 rounded" style={{ background: 'color-mix(in srgb, var(--brand-color, #19CDFF) 15%, transparent)', color: 'var(--brand-color, var(--color-brand-blue))' }}>{t('settings.ob_action_needed', 'Action needed')}</span>
          </button>
        ))}
      </div>
    </div>
  );
}


export default function OnboardingSection({ onJumpSection, onClose, profile }) {
  const { t } = useTranslation();
  const headers = useAuthHeaders();
  const navigate = useNavigate();
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [stripeBusy, setStripeBusy] = useState(false);
  const [stripeError, setStripeError] = useState(null);
  // Iter 216h108 — inline panel mode for steps that should open IN the
  // settings modal rather than navigating away.
  const [inlinePanel, setInlinePanel] = useState(null);  // 'equipment_import' | 'qr_print' | null

  const reload = async () => {
    try {
      const { data } = await axios.get(`${API}/account/onboarding`, { headers: headers() });
      setData(data);
    } catch { /* ignore */ }
  };

  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      try {
        const { data } = await axios.get(`${API}/account/onboarding`, { headers: headers() });
        if (!cancelled) setData(data);
      } catch {
        if (!cancelled) setData({ steps: [], percent: 0 });
      }
      if (!cancelled) setLoading(false);
    };
    load();
    return () => { cancelled = true; };
  }, [headers]);

  // Iter 216h60 — resolve symbolic onboarding routes to ACTUAL react-
  // router routes for the current user. Previously the backend handed
  // out `/sites` and `/dashboard?tab=equipment` indiscriminately and
  // Pulse/Lite operators bounced to the Pulse Fitness 404 page (Lee's
  // screenshot). Now we map them to the right destination.
  const resolveRoute = (route) => {
    if (!route) return route;
    const isMaster = !!profile?.is_master_admin;
    const at = (profile?.account_type || '').toLowerCase();
    const isMOD = at.startsWith('mod_') || !!profile?.is_mod_user;
    const isPulse = at === 'pulse_pro' || at === 'lite' || isMOD;
    // /sites isn't a real route — direct to the right Sites surface.
    if (route === '/sites' || route.startsWith('/sites?')) {
      if (isMaster) return '/master-admin?section=organizations';
      // Pulse operators manage sites via the Settings dialog (which
      // hosts PulseSettingsTab → "Add Site"). Opening with the
      // ?settings=sites deep-link triggers the dialog on mount.
      if (isPulse) return '/pulse?settings=sites';
      return '/dashboard';
    }
    // Equipment tab: Pulse operators land on /pulse with the equipment tab.
    if (route.startsWith('/dashboard?tab=equipment')) {
      if (isPulse) return '/pulse?tab=equipment';
    }
    if (route === '/dashboard' || route.startsWith('/dashboard?')) {
      if (isMaster) return route.replace('/dashboard', '/master-admin');
      if (isPulse) return route.replace('/dashboard', '/pulse');
    }
    if (route === '/pricing' && isMaster) return '/master-admin?section=integrations-hub';
    return route;
  };

  // Iter 220w — "Connect Stripe" self-serve. Previously routed owners to
  // the marketing /pricing page (never reached Stripe). Now it requests a
  // fresh Stripe Connect Express onboarding link for the owner's own org
  // and redirects straight to Stripe; on return they land back on Account
  // Settings → billing.
  const startStripeConnect = async () => {
    setStripeBusy(true);
    try {
      const { data: res } = await axios.post(
        `${API}/stripe-connect/me/onboarding-link`,
        { return_path: window.location.pathname },
        { headers: headers() },
      );
      if (res?.url) {
        window.location.href = res.url;
        return;
      }
      toast.error(t('settings.ob_stripe_failed', 'Could not start Stripe onboarding'));
    } catch (e) {
      const detail = e.response?.data?.detail;
      const code = (typeof detail === 'object' && detail) ? detail.code : null;
      if (code === 'stripe_connect_profile_incomplete' || code === 'stripe_connect_not_enabled') {
        // Persistent banner with the fix link (survives the failed redirect).
        setStripeError(detail);
      }
      toast.error((typeof detail === 'object' ? detail?.message : detail) || t('settings.ob_stripe_failed', 'Could not start Stripe onboarding'));
    }
    setStripeBusy(false);
  };

  const handleStep = (step) => {
    // Iter 220w — Stripe Connect self-serve action (no route push).
    if (step.cta_action === 'connect_stripe') {
      startStripeConnect();
      return;
    }
    // Iter 216h108 — inline panels open within the settings modal
    if (step.cta_inline) {
      setInlinePanel(step.cta_inline);
      return;
    }
    if (step.cta_section) {
      onJumpSection(step.cta_section);
    } else if (step.cta_route) {
      navigate(resolveRoute(step.cta_route));
      onClose();
    }
  };

  if (loading) {
    return <div className="text-sm" style={{ color: 'var(--theme-text-muted)' }}>{t('settings.ob_loading_checklist', 'Loading checklist…')}</div>;
  }
  // Iter 216h108 — inline mode renders the panel in place of the
  // checklist so the user never bounces out of Account Settings.
  if (inlinePanel === 'equipment_import') {
    return (
      <EquipmentImportInline
        onClose={() => { setInlinePanel(null); reload(); }}
        onImported={reload}
      />
    );
  }
  if (inlinePanel === 'qr_print') {
    return <QrPrintInline onClose={() => setInlinePanel(null)} />;
  }
  const pct = data?.percent ?? 0;
  return (
    <div className="space-y-5" data-testid="account-section-onboarding">
      <SurveyPortalPanel />
      <CustomerPortalPanel />
      <div>
        <h3 className="account-section-title">{t('settings.ob_setup_checklist', 'Setup checklist')}</h3>
        <p className="account-section-sub">
          {t('settings.ob_steps_complete', '{{done}} of {{total}} steps complete — finish them in any order.', { done: data?.completed_count ?? 0, total: data?.total ?? 0 })}
        </p>
      </div>
      <StripeConnectErrorBanner error={stripeError} />
      <div className="rounded-full overflow-hidden h-2 w-full" style={{ background: 'var(--theme-border-soft)' }}>
        <div
          className="h-full rounded-full transition-all"
          style={{ width: `${pct}%`, background: 'var(--brand-color, var(--color-brand-blue))' }}
          data-testid="account-onboarding-progress"
        />
      </div>
      <div className="space-y-2">
        {(data?.steps || []).map((s) => (
          <div
            key={s.id}
            className="account-card rounded-xl p-4 flex flex-col sm:flex-row items-start gap-3"
            data-testid={`account-onboarding-step-${s.id}`}
            data-completed={s.completed ? 'true' : 'false'}
          >
            <div className="flex items-start gap-3 flex-1 min-w-0 w-full sm:w-auto">
              <div
                className="mt-0.5 w-5 h-5 rounded-full flex items-center justify-center flex-shrink-0"
                style={{
                  background: s.completed
                    ? 'var(--brand-color, var(--color-brand-blue))'
                    : 'transparent',
                  border: s.completed
                    ? 'none'
                    : '1.5px solid var(--theme-border)',
                }}
              >
                {s.completed && <Check size={12} color="#FFFFFF" strokeWidth={3} />}
              </div>
              <div className="flex-1 min-w-0">
                <div
                  className={`text-sm font-semibold`}
                  style={{ color: 'var(--theme-text)' }}
                >
                  {s.label}
                </div>
                <div className="text-xs mt-0.5" style={{ color: 'var(--theme-text-muted)' }}>
                  {s.description}
                </div>
              </div>
            </div>
            <button
              type="button"
              onClick={() => handleStep(s)}
              disabled={s.cta_action === 'connect_stripe' && stripeBusy}
              className="account-btn-secondary flex-shrink-0 w-full sm:w-auto justify-center"
              data-testid={`account-onboarding-cta-${s.id}`}
            >
              {s.cta_action === 'connect_stripe' && stripeBusy && (
                <Loader2 size={13} className="animate-spin mr-1" />
              )}
              {s.completed ? t('settings.ob_review', 'Review') : (s.cta_label || t('settings.ob_open', 'Open'))}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

