                  ) : (
                    <>
                      <button type="button" onClick={() => openEdit(s)} className="p-1.5 rounded-md" style={{ color: 'var(--theme-text-muted)' }} data-testid={`account-supplier-edit-${s.id}`} aria-label={t('settings.sup_edit', 'Edit')}>
