                      <button type="button" onClick={() => remove(s)} className="p-1.5 rounded-md" style={{ color: 'var(--color-status-error, #DC2626)' }} data-testid={`account-supplier-delete-${s.id}`} aria-label={t('settings.sup_remove', 'Remove')}>
                        <Trash2 size={14} />
                      </button>
