function SupField({ label, testid, children }) {
  return (
    <label className="block" data-testid={testid}>
      <span className="text-[11px] font-semibold uppercase tracking-wide mb-1.5 block" style={{ color: 'var(--theme-text-muted)' }}>{label}</span>
