import React from 'react';
import { useLocation } from 'react-router-dom';
import { LayoutGrid, ChevronDown, Headphones, HardHat, Activity, Check, Boxes, CalendarClock, ShieldCheck, FileSignature, Briefcase } from 'lucide-react';

/**
 * Iter 283 — "Switch area" button.
 *
 * The pill ModuleSwitcher stays reserved for the four consistently-designed
 * modules (Operations / Memberships / CRM / Marketing). The Service Desk and
 * Engineer app have their own distinct shells, so a separate compact
 * "Switch area" dropdown (placed next to Account settings) lets users who can
 * access those surfaces hop between them without breaking the pill bar's
 * visual consistency.
 *
 * Renders only when the user can reach 2+ areas.
 */
function accessibleAreas(user) {
  if (!user) return [];
  const isMaster = user.is_master_admin === true || user.is_pulse_admin === true
    || user.role === 'master_admin' || user.role === 'master';
  const at = user.account_type;
  const mainPath = (at === 'pulse_pro' || at === 'lite') ? '/pulse' : '/dashboard';

  const areas = [];
  // External Service Provider engineers: Engineer App only, never the operations portal.
  if (user.is_external_engineer === true && !isMaster) {
    return [{ id: 'engineer', label: 'Engineer app', path: '/svc/engineer', icon: HardHat }];
  }

  // Main app — only for users who actually have operator/module access, so a
  // pure field engineer doesn't get a dead "Main app" link.
  const ma = user.moduleAccess || user.module_access || {};
  const hasAnyModule = ['operations', 'memberships', 'marketing', 'crm'].some((k) => ma && ma[k]);
  const operatorTypes = ['full', 'pulse_pro', 'lite', 'mod_site', 'mod_branch', 'mod_org'];
  // Operator-company staff logins are opt-in, so they only get "Main app" when
  // a module has actually been granted to them.
  const optInStaff = user.role === 'staff' && user.is_operator_company === true;
  const canMain = isMaster || hasAnyModule || user.role === 'owner' || (operatorTypes.includes(at) && !optInStaff);
  if (canMain) areas.push({ id: 'main', label: 'Main app', path: mainPath, icon: Activity });

  const canServiceDesk = isMaster || user.is_service_desk === true || user.role === 'service_desk';
  if (canServiceDesk) areas.push({ id: 'service-desk', label: 'Service Desk', path: '/service-desk', icon: Headphones });

  // Inventory & Distribution — its own module; reachable by users with the
  // inventory right OR Service Desk access (so existing operators keep it).
  const canInventory = isMaster || user.is_inventory === true || canServiceDesk;
  if (canInventory) areas.push({ id: 'inventory', label: 'Inventory & Distribution', path: '/inventory', icon: Boxes });

  const canEngineer = isMaster || user.role === 'engineer' || user.is_engineer === true || !!user.engineer_id;
  if (canEngineer) areas.push({ id: 'engineer', label: 'Engineer app', path: '/svc/engineer', icon: HardHat });

  // CRM + Contract Management — same CRM records, two workspaces. Access is the
  // backend-resolved workspace role (user.crm_workspaces), matching the launcher.
  const ws = user.crm_workspaces;
  if (ws?.crm) areas.push({ id: 'crm', label: 'CRM', path: '/crm', icon: Briefcase });
  if (ws?.contract_management) areas.push({ id: 'contract-management', label: 'Contract Management', path: '/contract-management', icon: FileSignature });

  // MOD Operations — per-user opt-in module (platform admins always qualify).
  const canModOps = isMaster || (user.module_overrides && user.module_overrides.mod_operations === true);
  if (canModOps) areas.push({ id: 'mod-operations', label: 'MOD Operations', path: '/bfpo', icon: ShieldCheck });

  // Staff Portal — anyone with an employee record in the staffing register
  // (resolved server-side into user.has_staff_portal).
  if (user.has_staff_portal === true) {
    areas.push({ id: 'staff-portal', label: 'Staff Portal', path: '/staff-portal', icon: CalendarClock });
  }

  return areas;
}

function currentAreaId(pathname) {
  const p = pathname || '';
  if (p.startsWith('/inventory') || p.startsWith('/service-desk/inventory')) return 'inventory';
  if (p.startsWith('/service-desk')) return 'service-desk';
  if (p.startsWith('/svc/engineer') || p.startsWith('/engineer')) return 'engineer';
  if (p.startsWith('/bfpo')) return 'mod-operations';
  if (p.startsWith('/contract-management')) return 'contract-management';
  if (p.startsWith('/crm')) return 'crm';
  if (p.startsWith('/staff-portal')) return 'staff-portal';
  return 'main';
}

export default function AreaSwitcher({ user, tone = 'header', className = '' }) {
  const location = useLocation();
  const [open, setOpen] = React.useState(false);

  const areas = accessibleAreas(user);
  if (areas.length < 2) return null;

  const active = currentAreaId(location.pathname);
  const dark = tone === 'header';
  const icon = tone === 'icon';
  const openUp = tone === 'sidebar';

  const go = (area) => {
    setOpen(false);
    if (area.id === active) return;
    // Service Desk / Engineer live in separate shells — full navigation is
    // the most reliable way to switch between them.
    window.location.href = area.path;
  };

  let btnClass, btnStyle;
  if (icon) {
    btnClass = 'relative p-2 rounded-full border border-slate-200 bg-white hover:bg-slate-50 text-slate-700';
    btnStyle = {};
  } else if (dark) {
    btnClass = 'flex items-center gap-2 px-3 py-2 rounded-lg border hover:opacity-80 transition-colors';
    btnStyle = { borderColor: 'var(--theme-border)', color: 'var(--theme-text)' };
  } else {
    btnClass = 'flex items-center gap-2 px-3 py-2 rounded-lg border border-slate-200 text-slate-700 hover:bg-slate-50 transition-colors w-full';
    btnStyle = {};
  }

  const menuPos = openUp ? 'left-0 bottom-full mb-2' : 'right-0 top-full mt-2';

  return (
    <div className={`relative ${className}`}>
      <button
        onClick={() => setOpen((o) => !o)}
        className={btnClass}
        style={btnStyle}
        data-testid="area-switcher-btn"
        aria-haspopup="true"
        aria-expanded={open}
        title={icon ? 'Switch area' : undefined}
        aria-label={icon ? 'Switch area' : undefined}
      >
        <LayoutGrid size={icon ? 16 : 15} />
        {!icon && <span className="text-sm font-medium">Switch area</span>}
        {!icon && <ChevronDown size={14} className={`ml-auto transition-transform ${open ? 'rotate-180' : ''}`} />}
      </button>

      {open && (
        <>
          <div className="fixed inset-0 z-40" onClick={() => setOpen(false)} />
          <div
            className={`absolute ${menuPos} w-60 rounded-lg shadow-xl z-50 overflow-hidden`}
            style={dark
              ? { background: 'var(--theme-surface)', border: '1px solid var(--theme-border)' }
              : { background: '#fff', border: '1px solid #e0e0e0' }}
            data-testid="area-switcher-menu"
          >
            <p className={`px-4 pt-3 pb-1 text-[10px] uppercase tracking-[0.16em] font-semibold ${dark ? '' : 'text-slate-400'}`}
               style={dark ? { color: 'var(--theme-text-muted)' } : {}}>Switch area</p>
            <div className="py-1">
              {areas.map((a) => {
                const Icon = a.icon;
                const on = a.id === active;
                return (
                  <button
                    key={a.id}
                    onClick={() => go(a)}
                    className={`w-full flex items-center gap-3 px-4 py-2.5 text-sm transition-colors ${dark ? 'hover:opacity-80' : 'hover:bg-slate-50'} ${on ? 'font-semibold' : ''}`}
                    style={dark ? { color: 'var(--theme-text)' } : { color: on ? '#1b1c1d' : '#565B5E' }}
                    data-testid={`area-switcher-${a.id}`}
                  >
                    <Icon size={16} /> {a.label}
                    {on && <Check size={14} className="ml-auto" style={{ color: 'var(--color-brand-cyan)' }} />}
                  </button>
                );
              })}
            </div>
            {user.is_operator_company === true && (
              <div className="py-1 border-t" style={dark ? { borderColor: 'var(--theme-border)' } : { borderColor: '#e0e0e0' }}>
                <button
                  onClick={() => { setOpen(false); window.location.href = '/launch?choose=1'; }}
                  className={`w-full flex items-center gap-3 px-4 py-2.5 text-sm transition-colors ${dark ? 'hover:opacity-80' : 'hover:bg-slate-50'}`}
                  style={dark ? { color: 'var(--theme-text-muted)' } : { color: '#565B5E' }}
                  data-testid="area-switcher-chooser"
                >
                  <LayoutGrid size={16} /> Area Selector…
                </button>
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
}

import React, { lazy, Suspense, useState } from 'react';
import { createPortal } from 'react-dom';
import axios from 'axios';
import { CalendarPlus, Loader2 } from 'lucide-react';
import { notify } from '@/components/notifications';

const ServiceDeskIntakeForm = lazy(() => import('@/pages/ServiceOps/ServiceDeskIntakeForm'));
const API = `${process.env.REACT_APP_BACKEND_URL}/api`;
const auth = () => ({ headers: { Authorization: `Bearer ${localStorage.getItem('token')}` } });

// One-tap follow-up from a completed job's "Further Work / Parts Required".
export function BookFollowUpButton({ caseId, report, followUpRef, onBooked }) {
  const [initial, setInitial] = useState(null);
  const [busy, setBusy] = useState(false);
  const [bookedRef, setBookedRef] = useState(followUpRef || null);
  const needed = (report?.further_work_required || '').trim() || (report?.further_parts_required || []).length;
  if (!needed) return null;
  if (bookedRef) {
    return <span className="inline-flex items-center gap-1 text-xs font-semibold text-emerald-700" data-testid="follow-up-booked"><CalendarPlus size={13} /> Follow-up booked · {bookedRef}</span>;
  }
  const open = async () => {
    setBusy(true);
    try {
      const { data } = await axios.get(`${API}/svc/cases/${caseId}/follow-up-draft`, auth());
      if (data.existing_follow_up) { setBookedRef(data.existing_follow_up); return; }
      setInitial({ ...data, followUpOf: data.follow_up_of, followUpRef: data.reference });
    } catch (e) {
      notify.error('Could not prepare the follow-up', e?.response?.data?.detail || e.message);
    } finally { setBusy(false); }
  };
  return (
    <>
      <button type="button" onClick={open} disabled={busy} data-testid="book-follow-up-btn"
        className="inline-flex items-center gap-1.5 rounded-full bg-[#19CDFF] text-[#1B1C1D] px-3.5 py-1.5 text-xs font-semibold hover:bg-[#0091CA] hover:text-white disabled:opacity-60">
        {busy ? <Loader2 size={13} className="animate-spin" /> : <CalendarPlus size={13} />} Book follow-up
      </button>
      {initial && createPortal(
        <div style={{ position: 'fixed', inset: 0, zIndex: 1200 }} data-testid="follow-up-intake-layer">
          <Suspense fallback={null}>
            <ServiceDeskIntakeForm initial={initial} onClose={() => setInitial(null)}
              onCreated={(c) => { setInitial(null); setBookedRef(c?.reference || 'booked'); notify.success('Follow-up job booked', c?.reference || ''); onBooked?.(c); }} />
          </Suspense>
        </div>,
        document.body,
      )}
    </>
  );
}

export default BookFollowUpButton;

/**
 * Button — Iter 216h27 (D3 button hierarchy audit) + Iter 216h37 (icon size).
 *
 * Caps the platform button vocabulary at 5 variants × 5 sizes so the UI
 * never drifts back to the 8+ ad-hoc styles we found in the audit:
 *
 *   PRIMARY            — exactly one per screen. The "do the thing" CTA.
 *                        Brand cyan background, dark text.
 *   SECONDARY          — supportive actions next to the primary
 *                        (Cancel, Bulk import, Refresh). Outline + hover.
 *   TERTIARY           — low-emphasis text-only links ("View all",
 *                        "Manage", "Reset filter").
 *   DESTRUCTIVE        — irreversible danger CTA (Delete, Cancel plan).
 *                        Pale red background, dark red text.
 *   GHOST              — Iter 216h37. Icon-only or icon+label row actions
 *                        (Edit, Archive, Toggle, Copy). No background;
 *                        soft hover surface. Used inside dense tables and
 *                        drawer headers where a bordered button would
 *                        compete with row content.
 *   GHOST_DESTRUCTIVE  — Iter 216h37. Same as ghost but red-tinted hover —
 *                        for row-level delete / archive icons.
 *
 * Sizes — sm / md (default) / lg / icon / iconSm — keep layouts consistent.
 * The `icon` / `iconSm` sizes are square (equal padding all sides) and
 * skip the text span so a single Lucide icon centres cleanly. Pair them
 * with `ghost` + a `title=""` for accessibility.
 *
 * Pass an `icon` to render a Lucide icon inline (icon-left). Pass
 * `data-testid` for testing. Avoid wrapping a `<Link>` — use `as="a"`
 * for anchors instead.
 *
 * Example:
 *   <Button variant="primary" icon={Plus}>Add member</Button>
 *   <Button variant="secondary">Bulk import</Button>
 *   <Button variant="tertiary">View all</Button>
 *   <Button variant="ghost" size="icon" icon={Edit3} title="Edit" />
 *   <Button variant="ghostDestructive" size="iconSm" icon={Trash2} title="Delete" />
 */
import React from 'react';

const SIZE = {
  sm: 'text-xs px-2.5 py-1.5 gap-1',
  md: 'text-sm px-3 py-2 gap-1.5',
  lg: 'text-sm px-4 py-2.5 gap-2',
  icon: 'p-2 gap-0',
  iconSm: 'p-1.5 gap-0',
};

const ICON_SIZE = { sm: 12, md: 14, lg: 16, icon: 14, iconSm: 12 };

const VARIANT = {
  primary: {
    className: 'inline-flex items-center justify-center rounded-lg font-extrabold transition-colors disabled:opacity-40 disabled:cursor-not-allowed',
    style: { background: 'var(--color-brand-cyan, #00D6E0)', color: 'var(--color-surface-darker, #1B1C1D)' },
    hoverClass: 'hover:brightness-110',
  },
  secondary: {
    className: 'inline-flex items-center justify-center rounded-lg font-bold border transition-colors disabled:opacity-40 disabled:cursor-not-allowed',
    style: { borderColor: 'var(--theme-border, #E0E0E0)', color: 'var(--theme-text, #1B1C1D)', background: 'var(--theme-surface, #FFFFFF)' },
    hoverClass: 'hover:bg-zinc-50',
  },
  tertiary: {
    className: 'inline-flex items-center font-semibold transition-colors disabled:opacity-40 disabled:cursor-not-allowed underline-offset-2',
    style: { color: 'var(--theme-text-muted, #6E7476)' },
    hoverClass: 'hover:text-zinc-900 hover:underline',
  },
  destructive: {
    className: 'inline-flex items-center justify-center rounded-lg font-bold transition-colors disabled:opacity-40 disabled:cursor-not-allowed',
    style: { background: '#FEE2E2', color: '#B91C1C', borderColor: '#FECACA' },
    hoverClass: 'hover:bg-red-100',
  },
  ghost: {
    // Iter 216h37 — Row-action neutral icon button. No border, no
    // background by default; reveals a soft hover surface so it sits
    // quietly inside dense tables and drawer headers.
    className: 'inline-flex items-center justify-center rounded-md font-semibold transition-colors disabled:opacity-40 disabled:cursor-not-allowed',
    style: { color: 'var(--theme-text-muted, #6E7476)', background: 'transparent' },
    hoverClass: 'hover:bg-black/[0.06] hover:text-zinc-900 dark:hover:bg-white/10 dark:hover:text-white',
  },
  ghostDestructive: {
    // Iter 216h37 — Row-action danger icon button. Red hover surface +
    // text so it visually telegraphs "irreversible" without shouting.
    className: 'inline-flex items-center justify-center rounded-md font-semibold transition-colors disabled:opacity-40 disabled:cursor-not-allowed',
    style: { color: '#FCA5A5', background: 'transparent' },
    hoverClass: 'hover:bg-red-500/15 hover:text-red-300',
  },
};

export const Button = React.forwardRef(({
  variant = 'primary',
  size = 'md',
  icon: Icon,
  iconRight: IconRight,
  loading = false,
  disabled = false,
  className = '',
  children,
  as = 'button',
  ...rest
}, ref) => {
  const v = VARIANT[variant] || VARIANT.primary;
  const Component = as;
  const iconSize = ICON_SIZE[size] || 14;
  // Iter 216h37 — Icon-only sizes (`icon`, `iconSm`) deliberately omit
  // the children span so a single Lucide icon centres in a square box.
  const isIconOnly = size === 'icon' || size === 'iconSm';
  return (
    <Component
      ref={ref}
      type={as === 'button' ? (rest.type || 'button') : undefined}
      disabled={as === 'button' ? (disabled || loading) : undefined}
      className={`${v.className} ${SIZE[size] || SIZE.md} ${v.hoverClass} ${className}`}
      style={v.style}
      {...rest}
    >
      {Icon && !loading && <Icon size={iconSize} aria-hidden />}
      {loading && (
        <svg className="animate-spin" width={iconSize} height={iconSize} viewBox="0 0 24 24" fill="none" aria-hidden>
          <circle cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="3" opacity="0.25" />
          <path d="M22 12a10 10 0 0 0-10-10" stroke="currentColor" strokeWidth="3" strokeLinecap="round" />
        </svg>
      )}
      {!isIconOnly && children && <span>{children}</span>}
      {IconRight && <IconRight size={iconSize} aria-hidden />}
    </Component>
  );
});
Button.displayName = 'Button';

export default Button;

/**
 * MOD Classification Banner.
 *
 * Sticky marking shown on every MOD surface to remind users of the platform's
 * approved classification ceiling. Defaults to OFFICIAL-SENSITIVE for MOD;
 * configurable per-tenant via ``organization.classification``.
 *
 * OFFICIAL-SENSITIVE is styled distinctly (amber) from OFFICIAL (cyan) so the
 * higher marking is unmistakable at a glance.
 */
const LEVEL_STYLES = {
  'OFFICIAL-SENSITIVE': {
    background: '#1a1205',
    color: '#fbbf24',
    border: 'rgba(251,191,36,0.35)',
  },
  'OFFICIAL': {
    background: '#0A0B10',
    color: '#19CDFF',
    border: 'rgba(25,205,255,0.25)',
  },
};

export default function ClassificationBanner({ level = 'OFFICIAL-SENSITIVE', dense = false, rightSlot = null }) {
  const label = (level || 'OFFICIAL-SENSITIVE').toUpperCase();
  const s = LEVEL_STYLES[label] || LEVEL_STYLES['OFFICIAL'];
  return (
    <div
      data-testid="mod-classification-banner"
      data-classification={label}
      role="note"
      aria-label={`Classification: ${label}`}
      className={`w-full font-extrabold uppercase tracking-[0.3em] ${
        dense ? 'text-[10px] py-1' : 'text-[11px] py-1.5'
      } flex items-center justify-center gap-3 px-3 relative`}
      style={{
        background: s.background,
        color: s.color,
        borderTop: `1px solid ${s.border}`,
        borderBottom: `1px solid ${s.border}`,
        letterSpacing: '0.3em',
      }}
    >
      <span aria-hidden="true">◆</span>
      {label}
      <span aria-hidden="true">◆</span>
      {rightSlot && (
        <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center" data-testid="mod-classification-right-slot">
          {rightSlot}
        </div>
      )}
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { Plus, Trash2 } from 'lucide-react';

const pad = (n) => String(n).padStart(2, '0');
export const toLocalInput = (iso) => {
  if (!iso) return '';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
};
const fromLocalInput = (v) => (v ? new Date(v).toISOString() : '');

// Fills the auto times (from the job's timers) when the engineer hasn't edited them.
export function withReportDefaults(report, defaultStart, defaultEnd) {
  const r = report || {};
  return {
    ...r,
    start_time: r.start_time !== undefined ? r.start_time : (defaultStart || ''),
    end_time: r.end_time !== undefined ? r.end_time : (defaultEnd || new Date().toISOString()),
    further_parts_required: (r.further_parts_required || []).filter((p) => (p.name || '').trim()),
  };
}

export function reportTimeError(r) {
  if (r.start_time && r.end_time && new Date(r.end_time) <= new Date(r.start_time)) return 'End time must be after the start time';
  return '';
}

const inputCls = 'w-full text-sm border border-slate-200 rounded-lg px-3 py-2 bg-white';
const labelCls = 'text-[11px] uppercase font-bold tracking-wide text-slate-500 mb-1 block';

function PartRow({ part, idx, onChange, onRemove, onSearch }) {
  const [hits, setHits] = useState([]);
  useEffect(() => {
    if (!onSearch || (part.name || '').length < 2 || part.sku) { setHits([]); return undefined; }
    const tm = setTimeout(() => onSearch(part.name).then(setHits).catch(() => setHits([])), 250);
    return () => clearTimeout(tm);
  }, [part.name, part.sku, onSearch]);
  return (
    <div className="relative flex gap-2 items-start" data-testid={`report-part-row-${idx}`}>
      <input className={`${inputCls} flex-1 min-w-0`} placeholder="Part name or number" value={part.name || ''}
        onChange={(e) => onChange({ name: e.target.value, sku: '', part_id: null })} data-testid={`report-part-name-${idx}`} />
      <input type="number" min="1" className="w-20 shrink-0 text-sm border border-slate-200 rounded-lg px-3 py-2 bg-white" value={part.qty || 1}
        onChange={(e) => onChange({ qty: Math.max(1, parseInt(e.target.value, 10) || 1) })} data-testid={`report-part-qty-${idx}`} aria-label="Quantity" />
      <button type="button" onClick={onRemove} className="p-2 text-slate-400 hover:text-red-600" data-testid={`report-part-remove-${idx}`} aria-label="Remove part"><Trash2 size={16} /></button>
      {hits.length > 0 && (
        <div className="absolute z-20 top-full left-0 right-24 mt-1 bg-white border border-slate-200 rounded-lg shadow-lg max-h-48 overflow-auto" data-testid={`report-part-suggestions-${idx}`}>
          {hits.map((h) => (
            <button key={h.id || h.sku} type="button" className="w-full text-left px-3 py-2 text-sm hover:bg-slate-50"
              onClick={() => { onChange({ name: h.name || h.description || h.sku, sku: h.sku || '', part_id: h.id || null }); setHits([]); }}>
              <span className="font-semibold">{h.name || h.description}</span>{h.sku ? <span className="text-slate-400"> · {h.sku}</span> : null}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

export function EngineerReportFields({ value, onChange, defaultStart, defaultEnd, showWork = false, onPartSearch }) {
  const r = withReportDefaults(value, defaultStart, defaultEnd);
  const parts = (value?.further_parts_required) || [];
  const setParts = (next) => onChange({ further_parts_required: next });
  return (
    <div className="bg-white rounded-2xl border border-slate-200 p-4 space-y-3" data-testid="engineer-report-fields">
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
        <label className="block"><span className={labelCls}>Start time *</span>
          <input type="datetime-local" className={inputCls} value={toLocalInput(r.start_time)} onChange={(e) => onChange({ start_time: fromLocalInput(e.target.value) })} data-testid="report-start-time" />
        </label>
        <label className="block"><span className={labelCls}>End time *</span>
          <input type="datetime-local" className={inputCls} value={toLocalInput(r.end_time)} onChange={(e) => onChange({ end_time: fromLocalInput(e.target.value) })} data-testid="report-end-time" />
        </label>
      </div>
      {reportTimeError(r) && <p className="text-xs text-red-600" data-testid="report-time-error">{reportTimeError(r)}</p>}
      {showWork && (
        <label className="block"><span className={labelCls}>Description of Work Completed *</span>
          <textarea rows={4} className={inputCls} value={value?.work_completed || ''} onChange={(e) => onChange({ work_completed: e.target.value })} data-testid="report-work-completed" />
        </label>
      )}
      <label className="block"><span className={labelCls}>Further Work Required</span>
        <textarea rows={3} className={inputCls} placeholder="Leave blank if none" value={value?.further_work_required || ''} onChange={(e) => onChange({ further_work_required: e.target.value })} data-testid="report-further-work" />
      </label>
      <div>
        <span className={labelCls}>Further Parts Required</span>
        <div className="space-y-2">
          {parts.map((p, i) => (
            <PartRow key={i} idx={i} part={p} onSearch={onPartSearch}
              onChange={(patch) => setParts(parts.map((x, j) => (j === i ? { ...x, ...patch } : x)))}
              onRemove={() => setParts(parts.filter((_, j) => j !== i))} />
          ))}
        </div>
        <button type="button" onClick={() => setParts([...parts, { name: '', qty: 1 }])}
          className="mt-2 inline-flex items-center gap-1 text-sm font-semibold text-[#0091CA]" data-testid="report-add-part">
          <Plus size={14} /> Add part
        </button>
      </div>
    </div>
  );
}

export default EngineerReportFields;

import React from 'react';

const fmt = (iso) => (iso ? new Date(iso).toLocaleString('en-GB', { dateStyle: 'medium', timeStyle: 'short' }) : '—');
const dur = (a, b) => {
  if (!a || !b) return '';
  const m = Math.round((new Date(b) - new Date(a)) / 60000);
  return m >= 0 ? ` (${Math.floor(m / 60)}h ${String(m % 60).padStart(2, '0')}m)` : '';
};

function Row({ label, children, testid }) {
  return (
    <div className="grid grid-cols-[150px_1fr] gap-2 py-1.5 border-b border-zinc-100 dark:border-zinc-800 last:border-0" data-testid={testid}>
      <span className="text-[11px] font-bold uppercase tracking-wide text-zinc-400">{label}</span>
      <span className="text-xs text-zinc-800 dark:text-zinc-200 whitespace-pre-wrap">{children}</span>
    </div>
  );
}

function SignoffBlock({ signoff }) {
  if (!signoff) return <p className="text-xs text-zinc-400 mt-2" data-testid="report-view-no-signature">No customer signature captured.</p>;
  if (signoff.unavailable) {
    return <p className="text-xs text-amber-700 mt-2" data-testid="report-view-unavailable">Customer unable to sign — {signoff.unavailable_reason}{signoff.signed_at ? ` · ${fmt(signoff.signed_at)}` : ''}</p>;
  }
  return (
    <div className="mt-2" data-testid="report-view-signature">
      <p className="text-[11px] font-bold uppercase tracking-wide text-zinc-400 mb-1">Customer sign-off</p>
      {signoff.image_data ? <img src={signoff.image_data} alt="Customer signature" className="max-h-24 rounded border border-zinc-200 bg-white p-1" /> : null}
      <p className="text-xs text-zinc-600 dark:text-zinc-300 mt-1">
        Signed by <b>{signoff.signed_by_name || 'Customer'}</b>{signoff.signed_by_role ? ` (${signoff.signed_by_role})` : ''}{signoff.signed_at ? ` · ${fmt(signoff.signed_at)}` : ''}
      </p>
    </div>
  );
}

export function EngineerReportView({ report, signoff, fallbackSummary }) {
  if (!report && !signoff && !fallbackSummary) return null;
  const parts = report?.further_parts_required || [];
  return (
    <div className="rounded-lg border border-zinc-200 dark:border-zinc-700 p-3" data-testid="engineer-report-view">
      <p className="text-[11px] font-bold uppercase tracking-wide text-zinc-500 mb-1">Engineer report</p>
      {report ? (
        <>
          <Row label="Start time" testid="report-view-start">{fmt(report.start_time)}</Row>
          <Row label="End time" testid="report-view-end">{fmt(report.end_time)}{dur(report.start_time, report.end_time)}</Row>
          <Row label="Work completed" testid="report-view-work">{report.work_completed || '—'}</Row>
          <Row label="Further work" testid="report-view-further-work">{report.further_work_required || 'None'}</Row>
          <Row label="Further parts" testid="report-view-further-parts">{parts.length ? parts.map((p) => `${p.qty} × ${p.name}${p.sku ? ` (${p.sku})` : ''}`).join('\n') : 'None'}</Row>
        </>
      ) : (
        <Row label="Work completed" testid="report-view-work">{fallbackSummary || '—'}</Row>
      )}
      <SignoffBlock signoff={signoff} />
    </div>
  );
}

export default EngineerReportView;

/**
 * LanguagePrompt — one-tap browser-language offer.
 *
 * The i18n detector already auto-selects FR/DE for brand-new anonymous
 * visitors (order: localStorage → navigator). This prompt covers the gap
 * that detector can't: a signed-in user whose *account* language is English
 * (the default) but whose browser is set to French or German — App.js forces
 * the saved account language on hydrate, so they'd never see the auto-detect.
 *
 * We offer, we don't force: a small dismissible card in the TARGET language
 * ("Continuer en français ?" / "Auf Deutsch fortfahren?"). One tap switches
 * the UI and — when signed in — persists the choice to the account profile.
 * Shown at most once per browser (localStorage flag), so it never nags.
 */
import { useEffect, useState } from 'react';
import { Globe, X } from 'lucide-react';
import i18n from '@/i18n';
import { useAuth } from '@/App';
import { setLanguagePreference } from '@/utils/languagePref';

const SEEN_KEY = 'pf_lang_prompt_seen';
export const LANG_PROMPT_SEEN_KEY = SEEN_KEY;

const COPY = {
  fr: {
    title: 'Continuer en français ?',
    body: 'Votre navigateur semble être en français. Vous pouvez changer la langue à tout moment.',
    accept: 'Passer en français',
    dismiss: 'Non, merci',
  },
  de: {
    title: 'Auf Deutsch fortfahren?',
    body: 'Ihr Browser ist offenbar auf Deutsch eingestellt. Sie können die Sprache jederzeit ändern.',
    accept: 'Auf Deutsch wechseln',
    dismiss: 'Nein, danke',
  },
};

// Base language of the browser, restricted to the two we offer.
function detectBrowserLang() {
  const raw = (navigator.languages && navigator.languages[0]) || navigator.language || '';
  const base = raw.toLowerCase().split('-')[0];
  return base === 'fr' || base === 'de' ? base : null;
}

export default function LanguagePrompt() {
  const { user, token, refreshUser } = useAuth();
  const [lang, setLang] = useState(null);
  const [busy, setBusy] = useState(false);
  const [leaving, setLeaving] = useState(false);

  useEffect(() => {
    if (localStorage.getItem(SEEN_KEY) === '1') return;
    const browser = detectBrowserLang();
    if (!browser) return;
    const active = (i18n.language || 'en').split('-')[0];
    if (active === browser) return; // already in their language — nothing to offer
    // Small delay so it doesn't fight the initial app paint / other banners.
    const timer = setTimeout(() => setLang(browser), 1200);
    return () => clearTimeout(timer);
  }, [user?.id]);

  const finish = () => {
    localStorage.setItem(SEEN_KEY, '1');
    setLeaving(true);
    setTimeout(() => setLang(null), 220);
  };

  const accept = async () => {
    setBusy(true);
    try {
      // Offline-safe: switches + persists locally now, syncs to the account
      // when possible (queued for retry if offline).
      await setLanguagePreference(lang);
      if (user && token) refreshUser?.();
    } finally {
      setBusy(false);
      finish();
    }
  };

  if (!lang) return null;
  const c = COPY[lang];

  return (
    <div
      role="dialog"
      aria-label={c.title}
      data-testid="language-prompt"
      className="fixed bottom-4 left-4 z-[300] max-w-[320px] w-[calc(100%-2rem)] sm:w-[320px]"
      style={{
        transition: 'opacity 220ms ease, transform 220ms ease',
        opacity: leaving ? 0 : 1,
        transform: leaving ? 'translateY(12px)' : 'translateY(0)',
      }}
    >
      <div
        className="rounded-2xl border border-white/15 shadow-2xl p-4"
        style={{
          background: 'rgba(27, 28, 29, 0.92)',
          backdropFilter: 'blur(16px)',
          WebkitBackdropFilter: 'blur(16px)',
          color: '#e0e0e0',
        }}
      >
        <div className="flex items-start gap-3">
          <div className="shrink-0 rounded-xl bg-cyan-500/15 text-cyan-300 p-2">
            <Globe size={18} />
          </div>
          <div className="min-w-0 flex-1">
            <p className="text-sm font-bold text-white leading-snug">{c.title}</p>
            <p className="text-[12px] text-slate-300 mt-1 leading-relaxed">{c.body}</p>
          </div>
          <button
            type="button"
            onClick={finish}
            aria-label={c.dismiss}
            data-testid="language-prompt-dismiss"
            className="shrink-0 -mr-1 -mt-1 p-1 rounded-lg text-slate-400 hover:text-white hover:bg-white/10 transition-colors"
          >
            <X size={15} />
          </button>
        </div>
        <div className="mt-3 flex items-center gap-2">
          <button
            type="button"
            onClick={accept}
            disabled={busy}
            data-testid="language-prompt-accept"
            className="flex-1 rounded-xl bg-cyan-500 hover:bg-cyan-400 disabled:opacity-60 text-slate-900 text-sm font-bold py-2 transition-colors"
          >
            {c.accept}
          </button>
          <button
            type="button"
            onClick={finish}
            data-testid="language-prompt-decline"
            className="rounded-xl px-3 py-2 text-sm font-semibold text-slate-300 hover:text-white hover:bg-white/10 transition-colors"
          >
            {c.dismiss}
          </button>
        </div>
      </div>
    </div>
  );
}

/**
 * LanguageSwitcher — compact EN/FR/DE globe dropdown for the AUTHENTICATED app
 * (operator module headers + customer/portal headers). Mirrors the marketing
 * Navbar switcher: changes the UI language and, when a user is signed in,
 * persists the choice to their profile so it follows them across devices and
 * localises the emails the platform sends them.
 */
import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Globe, Check } from 'lucide-react';
import { setLanguagePreference } from '@/utils/languagePref';

const LANGS = [
  { code: 'en', label: 'English', flag: '🇬🇧' },
  { code: 'fr', label: 'Français', flag: '🇫🇷' },
  { code: 'de', label: 'Deutsch', flag: '🇩🇪' },
];

export const LanguageSwitcher = ({ className = '' }) => {
  const { i18n } = useTranslation();
  const [open, setOpen] = useState(false);
  const current = i18n.language?.substring(0, 2) || 'en';

  const choose = (code) => {
    setOpen(false);
    // Offline-safe switch + persist + best-effort account sync.
    setLanguagePreference(code);
  };

  return (
    <div className={`relative ${className}`}>
      <button
        onClick={() => setOpen(!open)}
        className="flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg border hover:opacity-80 transition-colors"
        style={{ borderColor: 'var(--theme-border, #e0e0e0)', color: 'var(--theme-text-muted, #6e7476)' }}
        data-testid="lang-switcher-btn"
        aria-label="Change language"
      >
        <Globe size={15} />
        <span className="text-xs font-medium uppercase">{current}</span>
      </button>
      {open && (
        <>
          <div className="fixed inset-0 z-40" onClick={() => setOpen(false)} />
          <div
            className="absolute right-0 top-full mt-2 w-40 rounded-lg shadow-xl z-50 overflow-hidden"
            style={{ background: 'var(--theme-surface, #ffffff)', border: '1px solid var(--theme-border, #e0e0e0)' }}
            data-testid="lang-dropdown"
          >
            {LANGS.map((lang) => (
              <button
                key={lang.code}
                onClick={() => choose(lang.code)}
                className={`w-full flex items-center gap-3 px-4 py-2.5 text-sm transition-colors ${
                  current === lang.code ? 'font-medium' : 'opacity-70 hover:opacity-100'
                }`}
                style={{ color: 'var(--theme-text, #1b1c1d)' }}
                data-testid={`lang-option-${lang.code}`}
              >
                <span className="text-base">{lang.flag}</span>
                <span className="flex-1 text-left">{lang.label}</span>
                {current === lang.code ? <Check size={14} /> : null}
              </button>
            ))}
          </div>
        </>
      )}
    </div>
  );
};

export default LanguageSwitcher;

/**
 * ListPanel — Iter 216h44
 *
 * Lightweight list-panel skeleton that bundles the four pieces every
 * CRM / Memberships list view duplicates today:
 *
 *   1. Toolbar  — search input + count chip + secondary actions + primary CTA.
 *   2. Loading  — centred spinner.
 *   3. Empty    — wraps `<EmptyState>` so consumers just pass the same props.
 *   4. Rows     — children, fully owned by the caller (rows are too
 *                 domain-specific to abstract — contact rows look nothing
 *                 like plan cards which look nothing like class tiles).
 *
 * Why this scope?
 *   The rows themselves vary too much to standardise without painting
 *   ourselves into a corner. But the surrounding 30-50 LOC of toolbar +
 *   loading + count-chip + search-input repeats verbatim across
 *   CRMContacts, CRMCompanies, MembershipsConsole (Plans/Classes/Ads),
 *   PromotionsTab, etc. Standardising just that surface kills ~80 LOC
 *   per panel without sacrificing flexibility.
 *
 * Props:
 *   - `title`              (optional) — H2 above the toolbar.
 *   - `subtitle`           (optional) — supportive copy below the title.
 *   - `search`             (optional) — `{ value, onChange, placeholder, testId }`.
 *   - `count`              (optional) — `{ value, label, singular?, plural? }`.
 *   - `secondaryActions`   (optional) — array of `<Button>` / `<ExportCsvButton>` nodes.
 *   - `primaryAction`      (optional) — `{ label, icon, onClick, loading?, disabled?, testId? }`.
 *   - `loading`            (bool) — show spinner instead of children.
 *   - `empty`              (optional) — `{ when, icon, title, hint, primaryAction, testId }`.
 *                                       When `when=true` AND children is empty, renders <EmptyState>.
 *   - `toolbarRight`       (optional) — extra JSX appended to the toolbar (filters / view-switchers).
 *   - `className`          (optional) — wrapper override.
 *   - `bodyClassName`      (optional) — override for the inner body wrapper (default `space-y-2`).
 *                                       Use this for grid layouts like Plans / Promotions cards.
 *   - `data-testid`        (optional).
 *   - `children`           — list rows.
 *
 * Usage:
 *   <ListPanel
 *     search={{ value: search, onChange: setSearch, placeholder: 'Search contacts…', testId: 'contact-search' }}
 *     count={{ value: total, label: 'contact' }}
 *     secondaryActions={[<ExportCsvButton key="csv" module="contacts" testId="contacts-export-csv" />]}
 *     primaryAction={{ label: 'New Contact', icon: Plus, onClick: openCreate, testId: 'create-contact-btn' }}
 *     loading={loading}
 *     empty={{ when: contacts.length === 0, icon: Users, title: 'No contacts yet', primaryAction: { label: 'Add your first contact', onClick: openCreate }, testId: 'crm-contacts-empty' }}
 *     data-testid="crm-contacts-list"
 *   >
 *     {contacts.map(ct => <ContactRow key={ct.id} ct={ct} … />)}
 *   </ListPanel>
 */
import React from 'react';
import { Search, Loader2 } from 'lucide-react';
import Button from './Button';
import EmptyState from './EmptyState';

const ListPanel = ({
  title,
  subtitle,
  search,
  count,
  secondaryActions = [],
  primaryAction,
  loading = false,
  empty,
  toolbarRight,
  className = '',
  bodyClassName = 'space-y-2',
  children,
  ...rest
}) => {
  // The empty state should only render when the caller signals it AND
  // there are no rows. We don't auto-count children because callers
  // sometimes pass conditional render trees that yield non-row content.
  // Iter 216h243 — title + subtitle suppression. The platform-wide
  // audit (user prod review) flagged sub-page H1+description blocks
  // as redundant — the parent tab pill already names the section.
  // Suppressed unconditionally here so every Memberships sub-tab that
  // uses ListPanel collapses its header gap in one place. The
  // `title`/`subtitle` props are kept on the API so callers don't need
  // edits and a future toggle can re-expose them if needed.
  const showTitleBlock = false;
  const showEmpty = empty?.when && !loading;
  const hasToolbar = search || count || secondaryActions.length > 0 || primaryAction || toolbarRight;

  return (
    <div className={`space-y-3 ${className}`} {...rest}>
      {/* Title + subtitle — Iter 216h243: suppressed platform-wide. */}
      {showTitleBlock && (title || subtitle) && (
        <div>
          {title && <h2 className="text-base font-bold tracking-tight" style={{ color: 'var(--theme-text)' }}>{title}</h2>}
          {subtitle && <p className="text-xs mt-0.5" style={{ color: 'var(--theme-text-muted)' }}>{subtitle}</p>}
        </div>
      )}

      {/* Toolbar */}
      {hasToolbar && (
        <div className="flex items-center justify-between gap-3 flex-wrap" data-testid={rest['data-testid'] ? `${rest['data-testid']}-toolbar` : undefined}>
          {/* Left side: search */}
          {search ? (
            <div className="relative flex-1 min-w-[200px] max-w-sm">
              <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2" style={{ color: 'var(--theme-text-muted)' }} />
              <input
                value={search.value || ''}
                onChange={(e) => search.onChange?.(e.target.value)}
                placeholder={search.placeholder || 'Search…'}
                className="w-full pl-9 pr-3 py-2 text-sm rounded-md"
                style={{
                  background: 'var(--theme-input-bg, #fff)',
                  border: '1px solid var(--theme-border, #E0E0E0)',
                  color: 'var(--theme-text, #1B1C1D)',
                }}
                data-testid={search.testId}
              />
            </div>
          ) : <div />}

          {/* Right side: count + secondary actions + primary action + custom JSX */}
          <div className="flex items-center gap-2 flex-wrap">
            {count != null && (
              <p className="text-xs" style={{ color: 'var(--theme-text-muted)' }}>
                {count.value} {count.value === 1 ? (count.singular || count.label) : (count.plural || `${count.label || 'item'}${count.label?.endsWith('s') ? '' : 's'}`)}
              </p>
            )}
            {secondaryActions.map((node, i) => (
              <React.Fragment key={node.key || i}>{node}</React.Fragment>
            ))}
            {primaryAction && (
              <Button
                variant="primary"
                size="sm"
                onClick={primaryAction.onClick}
                disabled={primaryAction.disabled}
                loading={primaryAction.loading}
                icon={primaryAction.icon}
                data-testid={primaryAction.testId}
              >
                {primaryAction.label}
              </Button>
            )}
            {toolbarRight}
          </div>
        </div>
      )}

      {/* Body */}
      {loading ? (
        <div className="flex items-center justify-center py-12" data-testid={rest['data-testid'] ? `${rest['data-testid']}-loading` : undefined}>
          <Loader2 size={20} className="animate-spin" style={{ color: 'var(--color-brand-cyan, #00D6E0)' }} />
        </div>
      ) : showEmpty ? (
        <EmptyState
          icon={empty.icon}
          title={empty.title}
          hint={empty.hint}
          primaryAction={empty.primaryAction}
          secondaryAction={empty.secondaryAction}
          testId={empty.testId}
        />
      ) : (
        <div className={bodyClassName}>
          {children}
        </div>
      )}
    </div>
  );
};

export default ListPanel;

/**
 * LocaleLanguageNudge — tiny, dismissible one-time banner.
 *
 * When an operator switches the UI to French or German but their org is still
 * billing in a non-EUR currency, we offer a one-tap switch to the matching
 * market (France / Germany → EUR + DD/MM/YYYY date formatting via the org
 * localization system). Owners / master admins only. Copy is inlined per
 * language because the banner only ever renders in that language.
 */
import { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import axios from 'axios';
import { Globe, X, Check, Loader2 } from 'lucide-react';
import { invalidateLocalization } from '@/utils/localization';
import { notify } from '@/components/notifications';

const API = process.env.REACT_APP_BACKEND_URL
  ? `${process.env.REACT_APP_BACKEND_URL}/api`
  : '/api';

// UI language → target org market.
const TARGET = { fr: { code: 'FR' }, de: { code: 'DE' } };

const COPY = {
  fr: {
    text: "Vous utilisez l'application en français. Passer la tarification en € et les dates au format JJ/MM/AAAA (France) ?",
    apply: 'Passer en €',
    dismiss: 'Plus tard',
    done: 'Marché défini sur la France — prix en € et dates en JJ/MM/AAAA.',
    err: "Impossible de mettre à jour le marché.",
  },
  de: {
    text: 'Sie nutzen die App auf Deutsch. Preise auf € und Datum auf TT.MM.JJJJ (Deutschland) umstellen?',
    apply: 'Auf € umstellen',
    dismiss: 'Später',
    done: 'Markt auf Deutschland gesetzt — Preise in € und Datum als TT.MM.JJJJ.',
    err: 'Markt konnte nicht aktualisiert werden.',
  },
};

export default function LocaleLanguageNudge() {
  const { i18n } = useTranslation();
  const lng = (i18n.resolvedLanguage || i18n.language || 'en').slice(0, 2);
  const target = TARGET[lng];
  const dismissKey = `locale_nudge_dismissed_${lng}`;

  const [show, setShow] = useState(false);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    let alive = true;
    if (!target) { setShow(false); return; }
    if (localStorage.getItem(dismissKey) === '1') { setShow(false); return; }
    const token = localStorage.getItem('token');
    if (!token) { setShow(false); return; }
    (async () => {
      try {
        const { data } = await axios.get(`${API}/org/localization`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        const loc = data?.localization || {};
        // Only nudge editors whose org isn't already on EUR / the target country.
        const eligible = Boolean(data?.can_edit)
          && (loc.currency || '').toUpperCase() !== 'EUR'
          && (loc.country_code || '').toUpperCase() !== target.code;
        if (alive) setShow(eligible);
      } catch {
        if (alive) setShow(false);
      }
    })();
    return () => { alive = false; };
  }, [target, dismissKey]);

  if (!show || !target) return null;
  const copy = COPY[lng];

  const dismiss = () => {
    localStorage.setItem(dismissKey, '1');
    setShow(false);
  };

  const apply = async () => {
    setBusy(true);
    try {
      const token = localStorage.getItem('token');
      await axios.put(`${API}/org/localization`, { country_code: target.code }, {
        headers: { Authorization: `Bearer ${token}` },
      });
      invalidateLocalization();
      localStorage.setItem(dismissKey, '1');
      notify.success(copy.done);
      // Reload so cached money/date formatters pick up the new market everywhere.
      setTimeout(() => window.location.reload(), 900);
    } catch {
      notify.error(copy.err);
      setBusy(false);
    }
  };

  return (
    <div
      className="flex items-center gap-3 px-4 py-2.5 text-sm border-b"
      style={{ background: 'rgba(25,205,255,0.08)', borderColor: 'var(--theme-border, #e0e0e0)', color: 'var(--theme-text, #1b1c1d)' }}
      data-testid="locale-language-nudge"
    >
      <Globe size={16} className="shrink-0" style={{ color: 'var(--color-brand-cyan, #19CDFF)' }} />
      <span className="flex-1 leading-snug">{copy.text}</span>
      <button
        type="button"
        onClick={apply}
        disabled={busy}
        className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold disabled:opacity-60"
        style={{ background: 'var(--color-brand-cyan, #19CDFF)', color: 'var(--color-ink, #1B1C1D)' }}
        data-testid="locale-nudge-apply"
      >
        {busy ? <Loader2 size={13} className="animate-spin" /> : <Check size={13} />} {copy.apply}
      </button>
      <button
        type="button"
        onClick={dismiss}
        className="inline-flex items-center gap-1 px-2 py-1.5 rounded-lg text-xs font-semibold opacity-70 hover:opacity-100"
        data-testid="locale-nudge-dismiss"
        aria-label={copy.dismiss}
      >
        <X size={14} />
      </button>
    </div>
  );
}

/**
 * MfaEnrolPanel — mandatory MFA enrolment during login (used inside the Navbar
 * auth dialog). Given a short-lived { temp_token, email } it walks the user
 * through: fetch QR (/auth/mfa/enrol/setup) → scan + enter first code
 * (/auth/mfa/enrol/complete) → save backup codes → onComplete(loginResponse).
 */
import { useEffect, useState } from 'react';
import axios from 'axios';
import { Loader2, ArrowRight, ShieldCheck } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';

const API = `${process.env.REACT_APP_BACKEND_URL}/api`;

export default function MfaEnrolPanel({
  enrol, setEnrol, code, setCode, backupCodes, setBackupCodes, onComplete,
}) {
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState('');
  const [saved, setSaved] = useState(false);

  // Fetch the QR/secret once for this temp_token.
  useEffect(() => {
    let alive = true;
    if (!enrol?.temp_token || enrol.secret) return () => {};
    (async () => {
      try {
        const { data } = await axios.post(`${API}/auth/mfa/enrol/setup`, { temp_token: enrol.temp_token });
        if (!alive) return;
        setEnrol((prev) => ({ ...prev, secret: data.secret, qrDataUrl: data.qrcode_data_url || '', provisioning_uri: data.provisioning_uri }));
      } catch {
        if (alive) setErr('Could not start MFA enrolment. Please try signing in again.');
      }
    })();
    return () => { alive = false; };
  }, [enrol, setEnrol]);

  const verify = async (e) => {
    e?.preventDefault?.();
    const c = (code || '').replace(/\D/g, '');
    if (busy || c.length !== 6) { setErr('Enter the 6-digit code from your authenticator app.'); return; }
    setBusy(true); setErr('');
    try {
      const { data } = await axios.post(`${API}/auth/mfa/enrol/complete`, { temp_token: enrol.temp_token, code: c });
      setBackupCodes({ codes: data.backup_codes || [], data });
    } catch (e2) {
      const s = e2?.response?.status;
      setErr((s === 400 || s === 401) ? 'That code did not match. Try the current code from your app.' : 'Could not complete enrolment.');
    } finally { setBusy(false); }
  };

  // Backup-codes acknowledgement step.
  if (backupCodes) {
    return (
      <div className="space-y-4" data-testid="nav-mfa-enrol-backup">
        <div className="flex items-start gap-2">
          <ShieldCheck className="text-emerald-400 mt-0.5" size={20} />
          <div>
            <p className="text-sm font-semibold text-white">Two-factor is now on</p>
            <p className="text-xs text-white/60 mt-0.5">Save these backup codes — each works once if you lose your authenticator. They won't be shown again.</p>
          </div>
        </div>
        <pre className="rounded-xl bg-black/40 border border-white/10 p-3 text-sm font-mono grid grid-cols-2 gap-1 text-emerald-300" data-testid="nav-mfa-enrol-codes">
          {(backupCodes.codes || []).join('\n')}
        </pre>
        <label className="flex items-center gap-2 text-sm text-white/80">
          <input type="checkbox" checked={saved} onChange={(e) => setSaved(e.target.checked)} data-testid="nav-mfa-enrol-saved" />
          I've saved my backup codes
        </label>
        <Button
          onClick={() => onComplete?.(backupCodes.data)}
          disabled={!saved}
          className="w-full"
          data-testid="nav-mfa-enrol-continue"
        >Continue <ArrowRight size={14} /></Button>
      </div>
    );
  }

  return (
    <form onSubmit={verify} className="space-y-4" data-testid="nav-mfa-enrol-form">
      <p className="text-sm text-white/80">
        Two-factor authentication is required for <span className="text-white">{enrol?.email}</span>.
        Scan the QR code in Google Authenticator, Authy or 1Password, then enter the 6-digit code.
      </p>
      {enrol?.qrDataUrl ? (
        <img src={enrol.qrDataUrl} alt="Scan in your authenticator app" className="w-40 h-40 mx-auto rounded-lg border border-white/10 p-2 bg-white" data-testid="nav-mfa-enrol-qr" />
      ) : (
        <div className="w-40 h-40 mx-auto flex items-center justify-center"><Loader2 className="animate-spin text-white/60" /></div>
      )}
      {enrol?.secret && (
        <div>
          <p className="text-xs text-white/60 mb-1">Can't scan? Enter this key:</p>
          <code className="block break-all rounded-lg bg-white/10 px-3 py-2 text-xs font-mono text-sky-300" data-testid="nav-mfa-enrol-secret">{enrol.secret}</code>
        </div>
      )}
      <Input
        placeholder="123456"
        value={code}
        onChange={(e) => setCode(e.target.value.replace(/\D/g, '').slice(0, 6))}
        maxLength={6}
        className="text-center tracking-[0.3em]"
        data-testid="nav-mfa-enrol-code"
      />
      {err && <div className="rounded-xl bg-red-500/10 border border-red-500/30 px-3 py-2 text-xs text-red-300" data-testid="nav-mfa-enrol-error">{err}</div>}
      <Button type="submit" disabled={busy || (code || '').length !== 6} className="w-full" data-testid="nav-mfa-enrol-submit">
        {busy ? <><Loader2 size={14} className="animate-spin" /> Verifying…</> : <>Verify &amp; enable <ArrowRight size={14} /></>}
      </Button>
    </form>
  );
}

/**
 * Modal — canonical modal/drawer primitive (single source of truth).
 *
 * Guarantees the content can NEVER be cut off behind the action footer:
 * the card is a fixed-height flex column, so the header and footer are
 * `flex-shrink-0` siblings and ONLY the body scrolls. A `sticky` footer
 * inside a scroll container (the old pattern) floats over the last field
 * at max scroll — this primitive makes that impossible by construction.
 *
 *   ┌───────────────┐  ← header  (flex-shrink-0, pinned)
 *   │  scroll body  │  ← children (flex-1 overflow-y-auto)
 *   └───────────────┘  ← footer  (flex-shrink-0, pinned)
 *
 * Usage:
 *   <Modal open={open} onClose={close} title="Add member" eyebrow="New record"
 *          size="lg" footer={<ModalFooter …/>}>
 *     …form fields…
 *   </Modal>
 *
 * Theme-aware via CSS vars (--theme-surface / --theme-border / --theme-text).
 * Renders through a portal so it escapes any transformed ancestor and the
 * fixed backdrop is measured against the viewport (not a tall <main>).
 */
import React, { useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { X } from 'lucide-react';

const SIZE = {
  sm: 'max-w-md',
  md: 'max-w-lg',
  lg: 'max-w-2xl',
  xl: 'max-w-3xl',
};

const FOCUSABLE = 'a[href],button:not([disabled]),textarea:not([disabled]),input:not([disabled]),select:not([disabled]),[tabindex]:not([tabindex="-1"])';

export function Modal({
  open = true,
  onClose,
  title,
  eyebrow,
  header,
  footer,
  children,
  size = 'md',
  variant = 'center',
  testId = 'modal',
  panelTestId,
  closeOnBackdrop = true,
  hideClose = false,
  backdropClassName = 'bg-black/40',
  bodyClassName = 'p-5 flex flex-col gap-3',
  panelClassName = '',
  panelStyle,
  zClassName = 'z-[100]',
}) {
  const cardRef = useRef(null);
  const restoreRef = useRef(null);

  useEffect(() => {
    if (!open) return undefined;
    const onKey = (e) => { if (e.key === 'Escape') onClose && onClose(); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [open, onClose]);

  useEffect(() => {
    if (!open || typeof document === 'undefined') return undefined;
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = prev; };
  }, [open]);

  // A11y: remember what was focused, move focus into the dialog on open,
  // and restore it when the dialog closes.
  useEffect(() => {
    if (!open || typeof document === 'undefined') return undefined;
    restoreRef.current = document.activeElement;
    const t = setTimeout(() => {
      const card = cardRef.current;
      if (!card) return;
      const first = card.querySelector(FOCUSABLE);
      (first || card).focus({ preventScroll: true });
    }, 30);
    return () => {
      clearTimeout(t);
      const el = restoreRef.current;
      if (el && typeof el.focus === 'function') {
        try { el.focus({ preventScroll: true }); } catch (_) { /* noop */ }
      }
    };
  }, [open]);

  // A11y: trap Tab / Shift+Tab focus within the dialog.
  const onKeyDownTrap = (e) => {
    if (e.key !== 'Tab') return;
    const card = cardRef.current;
    if (!card) return;
    const nodes = Array.from(card.querySelectorAll(FOCUSABLE))
      .filter((n) => n.offsetParent !== null || n === document.activeElement);
    if (nodes.length === 0) { e.preventDefault(); card.focus({ preventScroll: true }); return; }
    const first = nodes[0];
    const last = nodes[nodes.length - 1];
    if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
    else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
  };

  if (!open || typeof document === 'undefined') return null;

  const isDrawer = variant === 'drawer';

  const wrapClass = isDrawer
    ? 'absolute inset-0 flex justify-end'
    : 'absolute inset-x-0 top-16 bottom-16 sm:inset-0 flex items-stretch sm:items-center justify-center p-3 sm:p-4';

  const panelBase = isDrawer
    ? `relative w-full ${SIZE[size] || size || SIZE.md} h-full flex flex-col overflow-hidden border-l shadow-2xl focus:outline-none ${panelClassName}`
    : `relative w-full ${SIZE[size] || size || SIZE.md} h-full sm:h-auto sm:max-h-[calc(100vh-6rem)] bg-[color:var(--theme-surface)] border border-[color:var(--theme-border)] rounded-2xl shadow-xl flex flex-col overflow-hidden focus:outline-none ${panelClassName}`;

  const defaultHeader = (title || eyebrow || !hideClose) && (
    <div className={`flex-shrink-0 px-5 py-4 border-b border-[color:var(--theme-border)] bg-[color:var(--theme-surface)] ${isDrawer ? '' : 'rounded-t-2xl'} flex items-start justify-between gap-3`}>
      <div className="min-w-0">
        {eyebrow && <div className="text-[10px] font-bold uppercase tracking-[0.2em] text-[var(--color-brand-cyan)]">{eyebrow}</div>}
        {title && <h3 id={`${testId}-title`} className="font-extrabold text-lg mt-1 truncate" style={{ color: 'var(--theme-text)' }}>{title}</h3>}
      </div>
      {!hideClose && (
        <button
          type="button"
          onClick={onClose}
          className="h-9 w-9 rounded-full flex items-center justify-center border border-[color:var(--theme-border)] bg-[color:var(--theme-bg,transparent)] text-[color:var(--theme-text)] hover:bg-[color:var(--theme-surface-hover)] focus:outline-none focus:ring-2 focus:ring-[color:var(--color-brand-cyan)] focus:ring-offset-1 transition-colors shrink-0"
          aria-label="Close"
          data-testid={`${testId}-close`}
        >
          <X size={18} />
        </button>
      )}
    </div>
  );

  return createPortal((
    <div
      className={`fixed inset-0 ${zClassName} ${backdropClassName}`}
      onMouseDown={closeOnBackdrop ? (e) => { if (e.target === e.currentTarget) onClose && onClose(); } : undefined}
      data-testid={testId}
    >
      {/* center: card between fixed top/bottom navs · drawer: right-side sheet */}
      <div className={wrapClass}>
        <div
          ref={cardRef}
          tabIndex={-1}
          onKeyDown={onKeyDownTrap}
          className={panelBase}
          style={panelStyle}
          onClick={(e) => e.stopPropagation()}
          role="dialog"
          aria-modal="true"
          aria-labelledby={`${testId}-title`}
          data-testid={panelTestId}
        >
          {header ? <div className="flex-shrink-0">{header}</div> : defaultHeader}

          {/* Scroll body — the ONLY scrolling region. `min-h-0` lets it
              shrink inside the flex column so the footer stays visible. */}
          <div className={`flex-1 overflow-y-auto min-h-0 ${bodyClassName}`}>{children}</div>

          {footer && <div className="flex-shrink-0">{footer}</div>}
        </div>
      </div>
    </div>
  ), document.body);
}

/**
 * ModalFooter — standard Save / Cancel action row for the footer slot.
 * Owns its own top border so it hugs the card's bottom edge.
 */
export function ModalFooter({ onCancel, onSave, saving, saveLabel, cancelLabel = 'Cancel', testId, children }) {
  if (children) {
    return (
      <div className="px-5 py-3 bg-[color:var(--theme-surface)] border-t border-[color:var(--theme-border)] rounded-b-2xl flex gap-2">
        {children}
      </div>
    );
  }
  return (
    <div className="px-5 py-3 bg-[color:var(--theme-surface)] border-t border-[color:var(--theme-border)] rounded-b-2xl flex gap-2">
      <button
        onClick={onSave}
        disabled={saving}
        className="flex-1 rounded-lg py-2.5 text-sm font-extrabold disabled:opacity-60"
        style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-surface-darker)' }}
        data-testid={testId}
      >
        {saving ? 'Saving…' : (saveLabel || 'Save')}
      </button>
      <button
        onClick={onCancel}
        className="rounded-lg px-4 py-2.5 text-sm font-bold border border-[color:var(--theme-border)] text-[color:var(--theme-text-muted)] hover:bg-black/[0.04] dark:hover:bg-white/5"
      >
        {cancelLabel}
      </button>
    </div>
  );
}

export default Modal;

import { useState, useEffect } from 'react';
import { ShieldAlert, ArrowLeft } from 'lucide-react';

/**
 * Global friendly "module access needed" overlay.
 *
 * The axios response interceptor in App.js dispatches
 * `pulse:module-access-denied` whenever a backend module guard
 * (require_module / require_module_or_roles) returns a 403 tagged with the
 * `X-Module-Access-Denied` header. This is the safety net for the rare edge
 * case where a blocked API call slips past the UI route guards — instead of a
 * raw error/toast the user sees a clear "ask your administrator" screen with a
 * way back to an area they can use.
 */
export default function ModuleAccessDenied() {
  const [info, setInfo] = useState(null);

  useEffect(() => {
    const onDenied = (e) => {
      setInfo({
        modules: e?.detail?.modules || '',
        message: e?.detail?.message || '',
      });
    };
    window.addEventListener('pulse:module-access-denied', onDenied);
    return () => window.removeEventListener('pulse:module-access-denied', onDenied);
  }, []);

  if (!info) return null;

  const primary = (info.modules || '').split(',')[0] || '';
  const label = primary ? primary.charAt(0).toUpperCase() + primary.slice(1) : 'this';
  const message = info.message
    || `You don't have access to the ${label} module. Ask your administrator to grant you access.`;

  const goBack = () => { setInfo(null); window.location.assign('/launch'); };

  return (
    <div
      className="fixed inset-0 z-[400] flex items-center justify-center p-4"
      style={{ background: 'rgba(3, 7, 18, 0.72)', backdropFilter: 'blur(6px)' }}
      data-testid="module-access-denied"
      role="alertdialog"
      aria-modal="true"
    >
      <div
        className="w-full max-w-md rounded-2xl p-8 text-center"
        style={{
          background: 'var(--theme-surface, #fff)',
          border: '1px solid var(--theme-border, #e0e0e0)',
          boxShadow: '0 24px 60px rgba(0,0,0,0.35)',
        }}
      >
        <div
          className="w-14 h-14 rounded-2xl mx-auto flex items-center justify-center"
          style={{ background: '#f59e0b1f', color: '#d97706' }}
        >
          <ShieldAlert size={28} />
        </div>
        <h1
          className="mt-5 text-xl font-bold pulse-font-heading"
          style={{ color: 'var(--theme-text, #1b1c1d)' }}
          data-testid="module-access-denied-title"
        >
          Access needed
        </h1>
        <p
          className="mt-2 text-sm pulse-font-body"
          style={{ color: 'var(--theme-text-muted, #6e7476)' }}
          data-testid="module-access-denied-message"
        >
          {message}
        </p>
        <div className="mt-7 flex flex-col gap-2">
          <button
            onClick={goBack}
            data-testid="module-access-denied-back-btn"
            className="w-full inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold text-white transition-colors"
            style={{ background: 'var(--pulse-primary, #1b1c1d)' }}
          >
            <ArrowLeft size={16} /> Back to my area
          </button>
        </div>
      </div>
    </div>
  );
}

/**
 * Pulse Fitness Module Switcher
 *
 * A compact pill-shaped tab bar surfaced on every module's top bar so
 * operators with multi-module access can jump between:
 * • Operations — /pulse (Pulse Pro site operations / service desk)
 * • Memberships — /memberships (Studio / classes / revenue)
 * • Marketing — /marketing (Marketing Suite — campaigns, journeys, AI)
 * • CRM — /crm (Sales + contract pipeline)
 *
 * Renders only if the user has access to 2+ modules. Position and sizing
 * are identical across all modules so switching is visually stable — the
 * active pill slides to its slot via a smooth background transition.
 */
import React from 'react';
import axios from 'axios';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { Activity, Calendar, Briefcase, Rocket, MessagesSquare, ChevronLeft, ChevronRight } from 'lucide-react';
import { useTranslation } from 'react-i18next';

const API = process.env.REACT_APP_BACKEND_URL ? `${process.env.REACT_APP_BACKEND_URL}/api` : '/api';

const MODULES = [
 { id: 'operations', path: '/pulse', label: 'Operations', icon: Activity, accessKey: 'operations' },
 { id: 'memberships', path: '/memberships', label: 'Memberships', icon: Calendar, accessKey: 'memberships' },
 { id: 'crm', path: '/crm', label: 'CRM', icon: Briefcase, accessKey: 'crm' },
 { id: 'marketing', path: '/marketing', label: 'Marketing', icon: Rocket, accessKey: 'marketing' },
 // Comms Centre — the merged campaign system. Surfaced when the operator
 // has BOTH Marketing and CRM so members + B2B comms can be run together.
 { id: 'comms', path: '/comms', label: 'Comms Centre', icon: MessagesSquare, accessKey: 'comms' },
];

// Iter 215d5 — Operations module resolves to two different surfaces depending
// on which brand context the user is currently in:
//
//   • `/pulse`     — Pulse Fitness Pro self-service dashboard (cyan brand).
//   • `/dashboard` — Pulse Fitness operator / master-admin dashboard (blue brand).
//
// Previously the switcher always routed to `/pulse`, which dumped Pulse Fitness-
// branded users (master admin, Pulse Fitness operators) onto a Pulse Fitness screen
// when they clicked Operations. This helper picks the right path.
function resolveOperationsPath(user, pathname) {
  // Explicit Pulse tenancy wins — they belong on `/pulse`.
  const accountType = user?.account_type;
  if (accountType === 'pulse_pro' || accountType === 'lite') return '/pulse';
  // Already browsing the Pulse self-service surface — keep them there.
  if (pathname && pathname.startsWith('/pulse')) return '/pulse';
  // Master admins hitting `/dashboard` get auto-redirected to `/master-admin`
  // unless the `?as=operator` flag is set. Preserve that flag so Operations
  // shows the Pulse Fitness operator preview (the 9-tab surface) instead of the
  // Master Admin console, mirroring how the Pulse module works for them.
  const isMaster = user?.is_master_admin === true || user?.role === 'master_admin' || user?.role === 'master';
  if (isMaster) return '/dashboard?as=operator';
  // Everything else (Pulse Fitness `full` orgs, MOD) → Pulse Fitness portal.
  return '/dashboard';
}

function hasAccess(user, accessKey) {
 if (!user) return false;
 const isMaster = user.is_master_admin === true || user.role === 'master_admin' || user.role === 'master';
 if (isMaster) return true;
 // Service Desk + Inventory are per-user grants (not in the org module_access
 // dict), so resolve them from the user's own flags.
 if (accessKey === 'service_desk') return user.is_service_desk === true;
 if (accessKey === 'inventory') return user.is_inventory === true;
 // Comms Centre is a derived surface: visible only when the operator has
 // BOTH Marketing and CRM (members + B2B comms run together).
 if (accessKey === 'comms') return hasAccess(user, 'marketing') && hasAccess(user, 'crm');
 // Contract Coordinators / Finance use the Contract Management workspace, not
 // the sales CRM (backend-resolved workspace role).
 if (accessKey === 'crm' && user.crm_workspaces && user.crm_workspaces.crm === false) return false;
 const at = user.account_type;
 const isMod = at === 'mod_site' || at === 'mod_branch' || at === 'mod_org';

 const ma = user.moduleAccess || user.module_access;
 const hasExplicitFlag = ma && typeof ma === 'object' && accessKey in ma;

 // Iter 216c — respect explicit master-admin toggles FIRST.
 // Previous Iter 215dj guard hardcoded "Pulse Pro / Lite never get CRM"
 // which overrode the Master Admin Feature Control Panel even when the
 // operator had explicitly turned CRM on for that org. Now we trust the
 // explicit `module_access.<key>` flag (set by master admin in
 // FeatureControlPanel → saved to org.modules.<key>.enabled → resolved
 // by backend resolve_module_access on /auth/me).
 if (hasExplicitFlag) return !!ma[accessKey];

 // No explicit flag — fall back to historical defaults.
 if (isMod) return false;
 if (accessKey === 'crm') {
   // CRM not in module_access dict → only Pulse Fitness-internal `full` orgs get
   // it by default. Pulse customers must have it explicitly toggled on.
   return at === 'full';
 }
 if (accessKey === 'operations') return at === 'pulse_pro' || at === 'full' || at === 'lite';
 if (accessKey === 'memberships') return at === 'pulse_pro' || at === 'full';
 if (accessKey === 'marketing') return at === 'pulse_pro' || at === 'full';
 return false;
}

// Exposed so module shells can hide their embedded Comms views when the
// Comms Centre is available (user has both Marketing + CRM) — single source.
export function hasModuleAccess(user, accessKey) { return hasAccess(user, accessKey); }
export function hasCommsCentre(user) { return hasAccess(user, 'comms'); }

export default function ModuleSwitcher({ user, current }) {
 const location = useLocation();
 const navigate = useNavigate();
 const { t } = useTranslation();
 const wrapRef = React.useRef(null);
 const [edges, setEdges] = React.useState({ left: false, right: false });
 // Iter 215d5 — rewrite module paths per brand context so Operations
 // takes Pulse Fitness users to `/dashboard` and Pulse users to `/pulse`.
 const operationsPath = resolveOperationsPath(user, location.pathname);
 // Iter (Jul 2026) — Master Admin operator PREVIEW (?as=operator) must mirror
 // exactly what the customer sees, so it respects the org's real module flags
 // (user.modules — the raw org.modules dict) instead of the blanket
 // master-admin full-access bypass. Full access is retained everywhere else
 // (Master Admin console, real navigation).
 const asOperatorPreview = new URLSearchParams(location.search).get('as') === 'operator';
 const isMasterUser = user?.is_master_admin === true || user?.role === 'master_admin' || user?.role === 'master';
 // org_module_access = the org's real customer-visible access (backend, with
 // account-type defaults + trials, WITHOUT the master-admin bypass).
 const orgAccess = (user && typeof user.org_module_access === 'object' && user.org_module_access) || null;
 const previewRespectsOrg = asOperatorPreview && isMasterUser && orgAccess;
 const moduleOn = (accessKey) => {
   // Service Desk + Inventory are user-level grants, not org module flags —
   // always resolve them from the user (even in master-admin org preview).
   if (accessKey === 'service_desk' || accessKey === 'inventory') return hasAccess(user, accessKey);
   if (!previewRespectsOrg) return hasAccess(user, accessKey);
   if (accessKey === 'comms') return !!orgAccess.marketing && !!orgAccess.crm;
   return !!orgAccess[accessKey];
 };
 const available = MODULES
   .filter((m) => moduleOn(m.accessKey))
   .map((m) => (m.id === 'operations' ? { ...m, path: operationsPath } : m));

 // Toggle edge state on mount + resize + scroll so the fade only masks the
 // side that still has hidden pills — the active/last pill is never faded
 // once you swipe to that end.
 React.useEffect(() => {
 const el = wrapRef.current;
 if (!el) return;
 const check = () => {
   const maxScroll = el.scrollWidth - el.clientWidth;
   setEdges({
     left: el.scrollLeft > 1,
     right: maxScroll > 1 && el.scrollLeft < maxScroll - 1,
   });
 };
 check();
 el.addEventListener('scroll', check, { passive: true });
 const ro = new ResizeObserver(check);
 ro.observe(el);
 window.addEventListener('resize', check);
 return () => {
   el.removeEventListener('scroll', check);
   ro.disconnect();
   window.removeEventListener('resize', check);
 };
 }, [available.length]);

 // Bring the active module pill into view on mount / route change so users
 // arriving on an off-screen module (e.g. CRM at the far right on mobile)
 // always see where they are.
 React.useLayoutEffect(() => {
 const el = wrapRef.current;
 if (!el) return;
 const pill = el.querySelector('[aria-current="page"]');
 if (pill && typeof pill.scrollIntoView === 'function') {
   pill.scrollIntoView({ block: 'nearest', inline: 'center', behavior: 'smooth' });
 }
 // eslint-disable-next-line react-hooks/exhaustive-deps
 }, [current, location.pathname, available.length]);

 if (available.length < 2) return null;

 // SSO bridge: when the user clicks "CRM" from any other module, exchange
 // their main JWT for a CRM-scoped token via /crm/auth/cross-login, store
 // it in localStorage, THEN navigate. Without this the CRM app has no
 // `crm_token` and bounces the user to CRMLogin.
 const handleClick = async (e, m) => {
 if (m.id !== 'crm') return; // standard <Link> behaviour for everything else
 if (location.pathname.startsWith('/crm')) return;
 e.preventDefault();
 const mainToken = localStorage.getItem('token');
 if (mainToken) {
 try {
 const res = await axios.post(`${API}/crm/auth/cross-login`, {}, {
 headers: { Authorization: `Bearer ${mainToken}` },
 });
 if (res.data?.token) {
 localStorage.setItem('crm_token', res.data.token);
 sessionStorage.setItem('crm_active_session', '1');
 }
 } catch { /* fall through — CRMApp will redirect to login if needed */ }
 }
 navigate('/crm');
 };

 // Auto-derive current when not given via prop.
 let active = current;
 if (!active) {
   // Iter 215d5 — both `/dashboard` and `/pulse` map to the Operations
   // module, so check those two prefixes first before falling back to
   // the generic pathname-startswith match for the other modules.
   const p = location.pathname || '';
   if (p.startsWith('/dashboard') || p.startsWith('/pulse')) {
     active = 'operations';
   } else {
     const match = MODULES.find((m) => m.id !== 'operations' && p.startsWith(m.path));
     active = match?.id;
   }
 }
 // Back-compat — accept legacy prop values "pulse" / "mod".
 if (active === 'pulse') active = 'operations';

 const anyOverflow = edges.left || edges.right;
 const maskImage = edges.left && edges.right
   ? 'linear-gradient(to right, transparent 0, black 14px, black calc(100% - 14px), transparent 100%)'
   : edges.right
     ? 'linear-gradient(to right, black 0, black calc(100% - 14px), transparent 100%)'
     : edges.left
       ? 'linear-gradient(to right, transparent 0, black 14px, black 100%)'
       : undefined;

 const page = (dir) => {
   const el = wrapRef.current;
   if (!el) return;
   const amount = Math.max(120, Math.floor(el.clientWidth * 0.7));
   el.scrollBy({ left: dir * amount, behavior: 'smooth' });
 };

 return (
 <div className="relative">
 <div
 ref={wrapRef}
 className="gx-module-switcher-wrap max-w-full overflow-x-auto overflow-y-hidden -mx-1 px-1 scroll-smooth scrollbar-hide"
 style={{
 WebkitOverflowScrolling: 'touch',
 // Keep the horizontal swipe from triggering browser back/forward.
 overscrollBehaviorX: 'contain',
 touchAction: 'pan-x',
 // Iter 215c5 → c6 → 287: DIRECTIONAL fade. Only mask the side that still
 // has hidden pills, so the active/last pill is fully opaque once you swipe
 // to that end (never looks clipped off-screen). No mask when it all fits.
 maskImage,
 WebkitMaskImage: maskImage,
 }}
 data-scrollable={anyOverflow ? 'true' : 'false'}
 >
 <nav
 aria-label="Module switcher"
 data-testid="module-switcher"
 className="inline-flex items-center gap-1 p-1 rounded-full border shadow-sm whitespace-nowrap"
 style={{
 background: 'var(--theme-surface, rgba(255,255,255,0.05))',
 borderColor: 'var(--theme-border, rgba(255,255,255,0.1))',
 }}
 >
 {available.map((m) => {
 const Icon = m.icon;
 const on = active === m.id;
 return (
 <Link
 key={m.id}
 to={m.path}
 onClick={(e) => handleClick(e, m)}
 data-testid={`module-switcher-${m.id}`}
 aria-current={on ? 'page' : undefined}
 className={`flex-shrink-0 flex items-center gap-1.5 px-3.5 py-1.5 rounded-full text-[11px] font-extrabold uppercase tracking-wider transition-all duration-300 ease-out ${
 on
 ? 'bg-[var(--color-brand-cyan)] text-[var(--color-surface-darker)] shadow-md scale-[1.02]'
 : 'text-[color:var(--theme-text-muted,rgba(255,255,255,0.6))] hover:text-[color:var(--theme-text,#fff)] hover:bg-black/5 dark:hover:bg-white/5'
 }`}
 >
 <Icon size={12} />
 {t(`modules.${m.id}`, m.label)}
 </Link>
 );
 })}
 </nav>
 </div>
 {edges.left && (
 <button
 type="button"
 aria-label="Scroll modules left"
 onClick={() => page(-1)}
 className="sfb-chev sfb-chev-left"
 data-testid="module-switcher-chev-left"
 >
 <ChevronLeft size={15} />
 </button>
 )}
 {edges.right && (
 <button
 type="button"
 aria-label="Scroll modules right"
 onClick={() => page(1)}
 className="sfb-chev sfb-chev-right"
 data-testid="module-switcher-chev-right"
 >
 <ChevronRight size={15} />
 </button>
 )}
 </div>
 );
}

