export default Navbar;

/**
 * OfflineBanner (iter 215d9 → 215da → 216h46)
 *
 * Sticky pill below the Navbar that surfaces two signals:
 *   1. Connectivity state ("offline" / brief "back online") — 215d9.
 *   2. Offline mutation queue depth + a manual "Sync now" button — 215da.
 *
 * When the browser reports `navigator.onLine === false` we show
 * "You're offline — showing cached data." Optionally with an inline
 * pill showing how many edits are queued for sync.
 *
 * Iter 216h46 — auth-gated. The banner now ONLY renders when a user
 * is signed in (any scope — main/crm/member). Lee's iter 216h42 bug
 * reported the offline banner showing "on every screen even when I
 * log out" — even after the false-positive fix, the banner persisted
 * on public/marketing/login surfaces where it's useless and confusing.
 * Gating on `useUnifiedAuth().tokens` makes the banner an
 * authenticated-only concern, matching the rest of the operator
 * chrome (Navbar, GlobalCommandPalette, etc).
 */
import { useEffect, useState } from 'react';
import { WifiOff, CheckCircle2, RefreshCw, CloudOff } from 'lucide-react';
import useOnlineStatus from '../../hooks/useOnlineStatus';
import useOfflineQueue from '../../hooks/useOfflineQueue';
import { useUnifiedAuth } from './UnifiedAuthProvider';

export default function OfflineBanner() {
  const { online } = useOnlineStatus();
  const { count, flushing, flush } = useOfflineQueue();
  const { tokens } = useUnifiedAuth();
  const [showBackOnline, setShowBackOnline] = useState(false);
  const [wasOffline, setWasOffline] = useState(false);

  useEffect(() => {
    if (!online) {
      setWasOffline(true);
      setShowBackOnline(false);
      return;
    }
    if (wasOffline) {
      setShowBackOnline(true);
      const t = setTimeout(() => {
        setShowBackOnline(false);
        setWasOffline(false);
      }, 3000);
      return () => clearTimeout(t);
    }
    return undefined;
  }, [online, wasOffline]);

  const offline = !online;
  const syncing = online && (flushing || count > 0);
  const signedIn = !!(tokens.main || tokens.crm || tokens.member);

  // Iter 216h46 — public surfaces (marketing site, /pulse landing,
  // /crm login, member-app login) should NEVER show the offline
  // banner, regardless of network state. Those surfaces have no
  // cached data to fall back to, and the banner just looks broken
  // on a static page.
  if (!signedIn) return null;
  // The MOD/BFPO engineer app shows its own offline + saved-updates bar.
  if (typeof window !== 'undefined' && window.location.pathname.toLowerCase().startsWith('/bfpo')) return null;
  if (!offline && !showBackOnline && !syncing) return null;

  let background = '#26292B';
  let borderColor = '#393E41';
  let testid = 'offline-banner';
  let icon = <WifiOff size={14} />;
  let label = "You're offline — showing the last cached data.";

  if (!offline && showBackOnline) {
    background = '#065F46';
    borderColor = '#047857';
    testid = 'back-online-banner';
    icon = <CheckCircle2 size={14} />;
    label = 'Back online.';
  } else if (!offline && syncing) {
    background = '#0073A4';
    borderColor = '#0091CA';
    testid = 'sync-banner';
    icon = <RefreshCw size={14} className={flushing ? 'animate-spin' : ''} />;
    label = flushing ? `Syncing ${count} edit${count === 1 ? '' : 's'}…` : `${count} edit${count === 1 ? '' : 's'} waiting to sync`;
  }

  return (
    <div
      className="fixed left-1/2 -translate-x-1/2 z-[95] flex items-center gap-2 px-4 py-2 rounded-full shadow-lg border text-sm font-semibold animate-[slideDown_220ms_ease-out]"
      style={{
        top: 'calc(env(safe-area-inset-top, 0px) + 76px)',
        background,
        color: '#FFFFFF',
        borderColor,
      }}
      role="status"
      aria-live="polite"
      data-testid={testid}
    >
      {icon}
      <span data-testid="offline-banner-label">{label}</span>
      {offline && count > 0 && (
        <span className="ml-1 inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[11px] font-extrabold" style={{ background: '#1B1C1D', color: '#FDE68A' }} data-testid="offline-queue-pill">
          <CloudOff size={11} /> {count} pending
        </span>
      )}
      {!offline && count > 0 && !flushing && (
        <button
          type="button"
          onClick={flush}
          className="ml-1 text-[11px] font-extrabold px-2 py-0.5 rounded-full border border-white/40 hover:bg-white/10"
          data-testid="offline-retry-btn"
        >
          Retry
        </button>
      )}
    </div>
  );
}

/**
 * PulseProUpgradeCta (Iter 238c) — operator-facing conversion card.
 *
 * Renders a hero "Try Pulse Pro free for 3 days" banner on the Lite
 * dashboard so operators can self-serve unlock Memberships + CRM +
 * Marketing in one click. Backed by `/api/me/upgrade-to-pro` which
 * starts a 3-day free trial of every bolt-on.
 *
 * Visibility:
 *   • Hidden once `user.account_type === 'pulse_pro'` or master admin.
 *   • Owners see the live CTA. Non-owners see "Ask your owner" copy
 *     with the same module preview so they understand what's locked.
 */
import { useEffect, useState } from 'react';
import axios from 'axios';
import { useAuth } from '@/App';
import {
  Crown, Calendar, Briefcase, Rocket, Sparkles, ArrowRight,
  CheckCircle2, Loader2, Lock, X,
} from 'lucide-react';
import { notify } from '@/components/notifications';
import { notifyApiError } from '@/lib/formatApiError';

const API = process.env.REACT_APP_BACKEND_URL;

const BOLT_ONS = [
  {
    key: 'memberships',
    label: 'Memberships',
    icon: Calendar,
    accent: 'from-blue-400 to-blue-700',
    blurb: 'Member portal, class booking, kiosk check-in.',
  },
  {
    key: 'marketing',
    label: 'Marketing',
    icon: Rocket,
    accent: 'from-blue-400 to-blue-700',
    blurb: 'Email/SMS/push journeys + AI Creative Studio.',
  },
  {
    key: 'crm',
    label: 'CRM',
    icon: Briefcase,
    accent: 'from-blue-400 to-blue-700',
    blurb: 'Lead pipeline, deal flow, AI follow-ups.',
  },
];

// `inSettings` renders the same card inside Account settings → Plan & Billing,
// where it stays reachable after the dashboard banner has been closed.
export default function PulseProUpgradeCta({ inSettings = false }) {
  const { user, refreshMe } = useAuth();
  const [busy, setBusy] = useState(false);
  const [done, setDone] = useState(false);
  const [trial, setTrial] = useState(null);

  const accountType = (user?.account_type || '').toLowerCase();
  const eligible = !user?.is_master_admin && accountType === 'lite';
  const token = typeof window !== 'undefined' ? localStorage.getItem('token') : null;
  const headers = { Authorization: `Bearer ${token}` };

  useEffect(() => {
    if (!eligible) return;
    axios.get(`${API}/api/me/pro-trial`, { headers }).then((r) => setTrial(r.data)).catch(() => setTrial(null));
    // eslint-disable-next-line react-hooks/exhaustive-deps -- headers rebuilt each render; token read at call time
  }, [eligible]);

  // Master admin / Pro orgs / non-Lite operators don't see this. Once the
  // organisation has used its one free trial the card disappears everywhere;
  // a closed banner only hides the dashboard copy.
  if (!eligible || !trial || !trial.available) return null;
  if (!inSettings && trial.banner_dismissed) return null;

  const isOwner = (user?.role || '').toLowerCase() === 'owner';

  const dismiss = async () => {
    setTrial({ ...trial, banner_dismissed: true });
    try {
      await axios.post(`${API}/api/me/pro-trial/dismiss-banner`, {}, { headers });
      notify.success('Banner closed', 'You can still start your free trial from Account settings → Plan & Billing.');
    } catch (e) { notifyApiError(notify, e, 'Could not close the banner'); }
  };

  const startTrial = async () => {
    if (!isOwner) {
      notify.error('Owner-only', 'Ask the organisation owner to start your free Pro trial.');
      return;
    }
    setBusy(true);
    try {
      const r = await axios.post(
        `${API}/api/me/upgrade-to-pro`,
        { start_trials: ['memberships', 'crm', 'marketing'] },
        { headers },
      );
      const trials = r.data?.trials_started || [];
      notify.success(
        'Welcome to Pulse Pro',
        `Started ${trials.length} free trial${trials.length === 1 ? '' : 's'} — 3 days each. Tap any module in the switcher to dive in.`,
        { duration: 9000 },
      );
      setDone(true);
      // Refresh /api/auth/me so the rest of the app picks up the new
      // tier + module_access without a full reload.
      try { await refreshMe?.(); } catch (_) { /* fall back to reload */ }
      setTimeout(() => { window.location.reload(); }, 1200);
    } catch (e) {
      notifyApiError(notify, e, 'Could not start your free Pro trial');
    } finally {
      setBusy(false);
    }
  };

  return (
    <div
      className={`on-dark relative overflow-hidden rounded-2xl border border-blue-400/30 bg-gradient-to-br from-zinc-900 via-zinc-900 to-zinc-700 p-5 sm:p-6 ${inSettings ? '' : 'mb-6'}`}
      data-testid={inSettings ? 'pulse-pro-upgrade-cta-settings' : 'pulse-pro-upgrade-cta'}
    >
      {/* Subtle accent bloom */}
      <div className="pointer-events-none absolute -top-24 -right-24 w-72 h-72 rounded-full bg-gradient-to-br from-blue-400/30 to-blue-700/20 blur-3xl" />
      <div className="pointer-events-none absolute -bottom-32 -left-20 w-80 h-80 rounded-full bg-gradient-to-br from-blue-400/20 to-blue-700/10 blur-3xl" />

      {!inSettings && (
        <button
          type="button"
          onClick={dismiss}
          aria-label="Close trial banner"
          className="absolute top-3 right-3 z-10 w-7 h-7 rounded-full inline-flex items-center justify-center hover:bg-white/10"
          style={{ color: '#c9cbcc' }}
          data-testid="pulse-pro-cta-dismiss"
        >
          <X size={15} />
        </button>
      )}
      <div className={`relative flex flex-col gap-5 ${inSettings ? '' : 'lg:flex-row lg:items-center'}`}>
        <div className="flex-1 min-w-0">
          <div className="inline-flex items-center gap-2 px-2.5 py-1 rounded-full bg-blue-400/15 border border-blue-400/30 text-blue-200 text-[10px] uppercase tracking-wider font-bold mb-3">
            <Crown size={11} /> Pulse Lite · 3 modules locked
          </div>
          <h2 className="pulse-font-heading text-2xl sm:text-3xl font-bold text-white leading-tight">
            Unlock everything for <span className="bg-gradient-to-r from-blue-300 to-blue-400 bg-clip-text text-transparent">3 days, free</span>.
          </h2>
          <p className="text-sm text-zinc-300 mt-2 max-w-xl">
            Memberships, Marketing and CRM activate instantly — no card, no commitment. After 3 days, keep what you use and disable the rest.
          </p>

          <div className={`grid grid-cols-1 gap-2 mt-4 ${inSettings ? '' : 'sm:grid-cols-3'}`}>
            {BOLT_ONS.map((b) => {
              const Icon = b.icon;
              return (
                <div
                  key={b.key}
                  className="flex items-start gap-2.5 p-2.5 rounded-lg"
                  style={{ background: 'rgba(255,255,255,0.06)', border: '1px solid rgba(255,255,255,0.12)' }}
                  data-testid={`pulse-pro-cta-bolt-${b.key}`}
                >
                  <div className={`w-8 h-8 rounded-md bg-gradient-to-br ${b.accent} flex items-center justify-center text-white shrink-0`}>
                    <Icon size={14} />
                  </div>
                  <div className="min-w-0">
                    <p className="text-xs font-bold leading-tight" style={{ color: '#ffffff' }}>{b.label}</p>
                    <p className="text-[10px] leading-snug" style={{ color: '#9a9fa1' }}>{b.blurb}</p>
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        <div className={`flex flex-col gap-2 shrink-0 ${inSettings ? 'sm:w-64' : 'lg:w-56'}`}>
          {isOwner ? (
            <button
              onClick={startTrial}
              disabled={busy || done}
              className="group w-full px-5 py-3.5 rounded-xl bg-blue-400 text-zinc-900 text-sm font-extrabold uppercase tracking-wider shadow-lg shadow-blue-400/20 hover:shadow-blue-400/40 transition-all disabled:opacity-60 inline-flex items-center justify-center gap-2"
              data-testid="pulse-pro-cta-start-btn"
            >
              {busy ? <Loader2 size={16} className="animate-spin" /> : done ? <CheckCircle2 size={16} /> : <Sparkles size={16} />}
              {busy ? 'Starting…' : done ? 'Pro activated' : 'Try Pulse Pro free'}
              {!busy && !done && <ArrowRight size={14} className="group-hover:translate-x-0.5 transition-transform" />}
            </button>
          ) : (
            <button
              disabled
              className="w-full px-5 py-3.5 rounded-xl bg-white/10 border border-white/15 text-white text-xs font-bold cursor-not-allowed"
              data-testid="pulse-pro-cta-not-owner"
            >
              Owner can start trial
            </button>
          )}
          <p className="text-[10px] text-zinc-400 inline-flex items-center justify-center gap-1.5">
            <Lock size={9} /> No card · 3-day free trial · one per organisation
          </p>
        </div>
      </div>
    </div>
  );
}

/**
 * SiteSwitcher — header dropdown for multi-site Pulse Pro tenants
 * (Iter 216i).
 *
 * Behaviour:
 *   • Shown only when the org has ≥2 sites.
 *   • Lists every site + an "All sites" pseudo-entry that flips the
 *     dashboard into the multi-site overview (consumed by the parent
 *     via `onAllSites`).
 *   • Active site is sourced from the auth context (`activeSite`) and
 *     written back via `setActiveSite`. Persisted in localStorage by the
 *     parent so the choice survives reloads.
 *   • Pure presentational — no API calls; the sites list is whatever
 *     the auth context already loaded.
 */
import { useState, useRef, useEffect } from 'react';
import { ChevronDown, MapPin, Star, Globe2, Check } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { useAuth } from '@/App';

const SiteSwitcher = ({ onAllSites, onPickSite, allSitesActive = false }) => {
  const { t } = useTranslation();
  const { sites, activeSite, setActiveSite, allSitesMode, enableAllSites } = useAuth();
  const [open, setOpen] = useState(false);
  const ref = useRef(null);

  useEffect(() => {
    if (!open) return undefined;
    const handler = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [open]);

  // Hide the switcher entirely for single-site tenants — there's nothing
  // to switch to. The parent header still renders the company name.
  if (!sites || sites.length < 2) return null;

  // Effective "all sites" mode: either the parent controls it
  // (Operations) or the global isolation mode from the auth context.
  const allActive = allSitesActive || (allSitesMode && !activeSite);
  // When in global all-mode but a site is still cached for label, prefer
  // showing "All sites" if the context flag is set and parent isn't driving.
  const showAll = allSitesActive || allSitesMode;

  const label = showAll
    ? t('sites.all_sites', 'All Sites')
    : (activeSite?.name || t('sites.pick_site', 'Pick a site'));

  const handleAllSites = () => {
    if (onAllSites) onAllSites();
    else enableAllSites();
    setOpen(false);
  };

  /**
   * Iter 216bk — picking a specific site after the org was in "All sites"
   * mode used to leave `allSitesActive=true` on the parent, so the
   * dashboard stayed on the estate-wide overview and the click looked
   * dead. The new `onPickSite` callback lets the parent flip it back
   * to false. We still call `setActiveSite` (which the auth context
   * persists to localStorage) so the choice survives a reload.
   */
  const handlePickSite = (site) => {
    setActiveSite(site);
    if (onPickSite) onPickSite(site);
    setOpen(false);
  };

  return (
    <div ref={ref} className="relative" data-testid="site-switcher">
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold border transition-colors"
        style={{
          background: 'var(--theme-surface)',
          borderColor: 'var(--theme-border)',
          color: 'var(--theme-text)',
        }}
        data-testid="site-switcher-trigger"
      >
        {showAll ? <Globe2 size={13} /> : <MapPin size={13} className="text-[var(--color-brand-blue)]" />}
        <span className="max-w-[180px] truncate">{label}</span>
        <ChevronDown size={12} className="opacity-60" />
      </button>
      {open && (
        <div
          /* Iter 216bk — dropdown is now viewport-safe. On mobile (<640px)
             we anchor to the left edge of the trigger so the menu opens
             rightward and never clips off the left. On sm+ we keep the
             original right-aligned behaviour. Width caps at the viewport
             minus a 16px gutter so portrait phones never overflow. */
          className="absolute left-0 sm:left-auto sm:right-0 mt-2 rounded-lg shadow-xl z-30 overflow-hidden"
          style={{
            background: 'var(--theme-surface)',
            border: '1px solid var(--theme-border)',
            width: 'min(18rem, calc(100vw - 2rem))',
          }}
          data-testid="site-switcher-menu"
        >
          <div className="px-3 py-2 text-[10px] uppercase tracking-wider font-bold" style={{ color: 'var(--theme-text-muted)' }}>
            {t('sites.switch_site', 'Switch site')}
          </div>
          {/* All-sites aggregate — always available so users can return to
              the estate-wide / "all my sites" view from any module. */}
          <button
            type="button"
            onClick={handleAllSites}
            className="w-full flex items-center gap-2 px-3 py-2 text-sm text-left hover:bg-[var(--theme-hover-bg)]"
            style={{ color: 'var(--theme-text)' }}
            data-testid="site-switcher-all"
          >
            <Globe2 size={14} className="text-[var(--color-brand-blue)]" />
            <span className="flex-1 font-semibold">{t('sites.all_sites', 'All Sites')}</span>
            <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-[rgb(var(--rgb-brand-blue)/0.12)] text-[var(--color-brand-blue)] font-bold">overview</span>
            {showAll ? <Check size={14} className="text-emerald-500" /> : null}
          </button>
          <div className="border-t" style={{ borderColor: 'var(--theme-border-soft)' }} />
          <ul className="max-h-72 overflow-y-auto" data-testid="site-switcher-list">
            {sites.map((s) => {
              const active = !showAll && activeSite?.id === s.id;
              return (
                <li key={s.id}>
                  <button
                    type="button"
                    onClick={() => handlePickSite(s)}
                    className="w-full flex items-center gap-2 px-3 py-2 text-sm text-left hover:bg-[var(--theme-hover-bg)]"
                    style={{ color: 'var(--theme-text)' }}
                    data-testid={`site-switcher-item-${s.id}`}
                  >
                    {s.is_head_office
                      ? <Star size={13} className="text-amber-500 shrink-0" />
                      : <MapPin size={13} className="text-[var(--theme-text-muted)] shrink-0" />}
                    <span className="flex-1 truncate">{s.name}</span>
                    {s.equipment_count != null
                      ? <span className="text-[10px]" style={{ color: 'var(--theme-text-muted)' }}>{s.equipment_count} eq</span>
                      : null}
                    {active ? <Check size={14} className="text-emerald-500" /> : null}
                  </button>
                </li>
              );
            })}
          </ul>
        </div>
      )}
    </div>
  );
};

export default SiteSwitcher;

/**
 * UploadQueue — Iter 216h34
 *
 * Shared upload queue + bottom-right pinned drawer that surfaces every
 * in-flight file upload across the platform. Lee dropped 10 spec sheet
 * PDFs at once and couldn't tell which were done, which were stuck, and
 * which had failed — the legacy in-card "Processing... (3 remaining)"
 * pattern hides the per-file state. This component fixes that.
 *
 * Architecture:
 *   • `UploadQueueProvider` — wraps the app (mounted once in App.js).
 *     Owns an array of `UploadTask` objects.
 *   • `useUploadQueue()` — hook that returns `{ enqueue, retry, remove,
 *     cancel, tasks }`. Panels that own a dropzone call `enqueue(files,
 *     handler, { label, source })`.
 *   • `<UploadQueueDrawer>` — visual drawer pinned bottom-right. Auto-
 *     opens when the queue is non-empty; collapsible. Shows per-file
 *     name + progress bar + status (queued / uploading / done / failed)
 *     + per-file retry/dismiss actions.
 *
 * The handler signature is intentionally tiny so panels can adopt
 * without refactoring their existing upload code:
 *   handler(file, onProgress) => Promise<any>
 * Inside the handler you do your axios.post(...) — for per-file
 * progress, accept onProgress and pass it to `axios.onUploadProgress`.
 *
 * Drawer survives navigation (it's mounted at App.js level), so an
 * operator can flip tabs while large PDFs upload in the background.
 */
import React, {
  createContext, useCallback, useContext, useEffect, useMemo, useReducer, useState,
} from 'react';
import {
  Upload, X, ChevronDown, ChevronUp, RotateCw, CheckCircle2, AlertTriangle, Loader2,
} from 'lucide-react';

const UploadQueueCtx = createContext(null);

let _id = 0;
const nextId = () => {
  _id += 1;
  return `upl-${Date.now().toString(36)}-${_id}`;
};

const STATUS = {
  QUEUED: 'queued',
  UPLOADING: 'uploading',
  DONE: 'done',
  FAILED: 'failed',
};

function reducer(state, action) {
  switch (action.type) {
    case 'enqueue':
      return [...state, ...action.tasks];
    case 'patch':
      return state.map(t => (t.id === action.id ? { ...t, ...action.patch } : t));
    case 'remove':
      return state.filter(t => t.id !== action.id);
    case 'clear_done':
      return state.filter(t => t.status !== STATUS.DONE);
    default:
      return state;
  }
}

export function UploadQueueProvider({ children }) {
  const [tasks, dispatch] = useReducer(reducer, []);
  // Keep handler refs out of state so React doesn't re-render on every
  // progress tick. Indexed by task id.
  const handlersRef = React.useRef(new Map());
  // Iter 216h69 — per-source concurrency caps. Lee uploaded 9 spec
  // sheets in parallel; each PDF triggers an AI-extraction request
  // that takes 30-90s on the backend. With all 9 firing at once the
  // last few queued internally and exceeded the 120 s client timeout.
  // We now throttle starts per `source` so the AI extractor never
  // sees more than N concurrent requests.
  //
  // Layout: { [source]: { running: Set<taskId>, waiting: Array<taskId>, cap: number } }
  const slotsRef = React.useRef({});
  const SOURCE_CAP_DEFAULTS = {
    'spec-sheets': 3,         // each upload is a 30-90s AI call
    'equipment-photo': 4,
    upload: 8,                // generic — keeps the legacy "fire all" feel
  };

  const runTaskRaw = useCallback(async (taskId) => {
    const handler = handlersRef.current.get(taskId);
    if (!handler) return;
    dispatch({ type: 'patch', id: taskId, patch: { status: STATUS.UPLOADING, progress: 0, error: null, startedAt: Date.now() } });
    try {
      const file = handler.file;
      await handler.fn(file, (pct) => {
        dispatch({ type: 'patch', id: taskId, patch: { progress: Math.max(0, Math.min(100, pct)) } });
      });
      dispatch({ type: 'patch', id: taskId, patch: { status: STATUS.DONE, progress: 100 } });
      // Fire completion callback if the caller provided one.
      handler.onDone?.(file);
    } catch (e) {
      const msg = e?.response?.data?.detail || e?.message || 'Upload failed';
      dispatch({ type: 'patch', id: taskId, patch: { status: STATUS.FAILED, error: msg } });
    }
  }, []);

  // Iter 216h69 — slot-aware scheduler. Starts a queued task only when
  // the source's running set has room; otherwise the task waits and is
  // pulled the moment another task in the same source settles.
  const releaseSlot = useCallback((source, taskId) => {
    const slot = slotsRef.current[source];
    if (!slot) return;
    slot.running.delete(taskId);
    while (slot.waiting.length > 0 && slot.running.size < slot.cap) {
      const next = slot.waiting.shift();
      slot.running.add(next);
      // Fire-and-forget; releaseSlot pulls the next when done.
      runTaskRaw(next).finally(() => releaseSlot(source, next));
    }
  }, [runTaskRaw]);

  const runTask = useCallback((taskId, source) => {
    const src = source || 'upload';
    if (!slotsRef.current[src]) {
      slotsRef.current[src] = {
        running: new Set(),
        waiting: [],
        cap: SOURCE_CAP_DEFAULTS[src] || 6,
      };
    }
    const slot = slotsRef.current[src];
    if (slot.running.size < slot.cap) {
      slot.running.add(taskId);
      runTaskRaw(taskId).finally(() => releaseSlot(src, taskId));
    } else {
      slot.waiting.push(taskId);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps -- intentional: module-level constant; identity is stable across renders.
  }, [runTaskRaw, releaseSlot]);

  const enqueue = useCallback((files, fn, opts = {}) => {
    const list = Array.from(files || []);
    if (list.length === 0) return [];
    const source = opts.source || 'upload';
    // Allow caller to override the per-source cap explicitly.
    if (opts.maxConcurrent && slotsRef.current[source]) {
      slotsRef.current[source].cap = opts.maxConcurrent;
    } else if (opts.maxConcurrent) {
      slotsRef.current[source] = {
        running: new Set(), waiting: [], cap: opts.maxConcurrent,
      };
    }
    const newTasks = list.map(file => ({
      id: nextId(),
      name: file.name,
      size: file.size,
      label: opts.label || file.name,
      source,
      status: STATUS.QUEUED,
      progress: 0,
      error: null,
      createdAt: Date.now(),
    }));
    newTasks.forEach((t, i) => {
      handlersRef.current.set(t.id, { file: list[i], fn, onDone: opts.onDone });
    });
    dispatch({ type: 'enqueue', tasks: newTasks });
    // Schedule each task through the slot-aware runner — starts up to
    // `cap` concurrently and queues the rest.
    newTasks.forEach(t => runTask(t.id, source));
    return newTasks.map(t => t.id);
  }, [runTask]);

  const retry = useCallback((taskId) => {
    // Manual retry — fire through the same slot-aware scheduler so a
    // burst of retries doesn't blow past the cap.
    const task = tasks.find(t => t.id === taskId);
    runTask(taskId, task?.source);
  }, [tasks, runTask]);

  const remove = useCallback((taskId) => {
    handlersRef.current.delete(taskId);
    // Iter 216h69 — if the user dismisses a queued task we need to
    // pull it from the waiting array too, otherwise the slot stays
    // empty when the running set drains.
    Object.values(slotsRef.current).forEach((slot) => {
      slot.waiting = slot.waiting.filter((id) => id !== taskId);
    });
    dispatch({ type: 'remove', id: taskId });
  }, []);

  const clearDone = useCallback(() => {
    dispatch({ type: 'clear_done' });
  }, []);

  const value = useMemo(() => ({ tasks, enqueue, retry, remove, clearDone }), [tasks, enqueue, retry, remove, clearDone]);

  // Iter 216h49 — Page-leave guard. Lee reported losing an in-progress
  // manual upload because he clicked away from the page mid-transfer.
  // While any task is QUEUED or UPLOADING, attach a beforeunload handler
  // so the browser prompts before tab close / hard refresh / route
  // change. Auto-cleared the moment all tasks settle (done/failed) so
  // we don't pester operators once the work is finished.
  const inFlightCount = tasks.filter(
    t => t.status === STATUS.QUEUED || t.status === STATUS.UPLOADING,
  ).length;
  useEffect(() => {
    if (inFlightCount === 0) return undefined;
    const handler = (e) => {
      e.preventDefault();
      // Most modern browsers ignore custom messages and show a generic
      // "Leave site?" prompt — but setting returnValue is still required
      // to trigger the dialog at all.
      e.returnValue = `${inFlightCount} upload${inFlightCount === 1 ? '' : 's'} in progress — leaving will cancel them.`;
      return e.returnValue;
    };
    window.addEventListener('beforeunload', handler);
    return () => window.removeEventListener('beforeunload', handler);
  }, [inFlightCount]);

  return (
    <UploadQueueCtx.Provider value={value}>
      {children}
      <UploadQueueDrawer />
    </UploadQueueCtx.Provider>
  );
}

export function useUploadQueue() {
  const v = useContext(UploadQueueCtx);
  if (!v) {
    // Graceful no-op — code that calls enqueue() before the provider
    // mounts shouldn't crash. Falls back to a synchronous handler call.
    return {
      tasks: [],
      enqueue: async (files, fn) => {
        for (const f of Array.from(files || [])) {
          try { await fn(f, () => {}); } catch (e) { /* swallow */ }
        }
        return [];
      },
      retry: () => {},
      remove: () => {},
      clearDone: () => {},
    };
  }
  return v;
}

// ─── Drawer UI ──────────────────────────────────────────────────────
//
// Iter 216h36 — mobile-aware. The fixed bottom-right 340 px card is
// great on a laptop but collides with the iOS home indicator and the
// software keyboard on a phone. Now responsive:
//   • md+ (≥ 768 px) — unchanged: bottom-right floating card, 340 px wide.
//   • <md             — slide-up sheet pinned to the bottom, full-width
//                       minus 8 px margin. Collapsed state becomes a
//                       slim handle bar with a single-line summary so
//                       it never blocks page content. Expanded state
//                       respects `env(safe-area-inset-bottom)` so the
//                       footer "Clear complete" button stays above the
//                       iOS home indicator.
//   The list also grows tall enough on mobile to be usefully readable
//   (60 vh max instead of 280 px).

function UploadQueueDrawer() {
  const { tasks, retry, remove, clearDone } = useContext(UploadQueueCtx) || { tasks: [] };
  // Start collapsed on small viewports so the drawer doesn't eat half
  // the screen the moment a file upload starts.
  const [collapsed, setCollapsed] = useState(() => {
    if (typeof window !== 'undefined' && window.matchMedia) {
      return window.matchMedia('(max-width: 767px)').matches;
    }
    return false;
  });

  if (!tasks || tasks.length === 0) return null;

  // Iter 216h69 — split inFlight into "uploading right now" vs
  // "queued waiting for a slot" so the user can see throttling at
  // work instead of fearing their files are stuck.
  const uploading = tasks.filter(t => t.status === STATUS.UPLOADING).length;
  const queued = tasks.filter(t => t.status === STATUS.QUEUED).length;
  const inFlight = uploading + queued;
  const failed = tasks.filter(t => t.status === STATUS.FAILED).length;
  const done = tasks.filter(t => t.status === STATUS.DONE).length;

  return (
    <div
      className="
        fixed z-[200] rounded-t-2xl md:rounded-xl shadow-2xl border overflow-hidden
        bottom-0 left-2 right-2 md:bottom-4 md:left-auto md:right-4 md:w-[340px]
      "
      style={{
        background: 'var(--theme-surface, #fff)',
        borderColor: 'var(--theme-border, #E0E0E0)',
        paddingBottom: 'env(safe-area-inset-bottom)',
      }}
      data-testid="upload-queue-drawer"
    >
      {/* Mobile grab handle — hidden on desktop. */}
      <div className="md:hidden flex justify-center pt-1.5 pb-0.5">
        <div className="w-9 h-1 rounded-full" style={{ background: 'var(--theme-border, #E0E0E0)' }} aria-hidden />
      </div>
      {/* Header */}
      <button
        type="button"
        onClick={() => setCollapsed(c => !c)}
        className="w-full flex items-center gap-2 px-3 py-2.5 border-b text-left"
        style={{ borderColor: 'var(--theme-border, #E0E0E0)' }}
        data-testid="upload-queue-toggle"
      >
        <div className="w-7 h-7 rounded-md flex items-center justify-center shrink-0" style={{ background: 'rgb(var(--rgb-brand-cyan, 0 214 224) / 0.12)' }}>
          {inFlight > 0 ? (
            <Loader2 size={14} className="animate-spin" style={{ color: 'var(--color-brand-cyan, #00D6E0)' }} />
          ) : failed > 0 ? (
            <AlertTriangle size={14} className="text-amber-500" />
          ) : (
            <CheckCircle2 size={14} className="text-emerald-500" />
          )}
        </div>
        <div className="flex-1 min-w-0">
          <p className="text-sm font-bold tracking-tight" style={{ color: 'var(--theme-text, #1B1C1D)' }}>
            {inFlight > 0
              ? `Uploading ${uploading} of ${inFlight} file${inFlight === 1 ? '' : 's'}`
              : failed > 0
                ? `${failed} upload${failed === 1 ? '' : 's'} failed`
                : `${done} upload${done === 1 ? '' : 's'} complete`}
          </p>
          <p className="text-[10px] uppercase tracking-wider font-semibold" style={{ color: 'var(--theme-text-muted, #6E7476)' }}>
            {tasks.length} total · {done} done · {failed} failed{queued > 0 ? ` · ${queued} waiting` : ''}
          </p>
        </div>
        {collapsed ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
      </button>

      {/* Tasks — taller list on mobile so it's actually readable.
          280 px on desktop, 60 vh on mobile (still leaves header room). */}
      {!collapsed && (
        <div
          className="overflow-y-auto"
          style={{ maxHeight: 'min(60vh, 280px)' }}
          data-testid="upload-queue-list"
        >
          {tasks.map(t => (
            <UploadTaskRow key={t.id} task={t} onRetry={() => retry(t.id)} onRemove={() => remove(t.id)} />
          ))}
        </div>
      )}

      {/* Footer */}
      {!collapsed && done > 0 && (
        <div className="px-3 py-2 border-t flex items-center justify-between" style={{ borderColor: 'var(--theme-border, #E0E0E0)' }}>
          <span className="text-[10px] uppercase tracking-wider font-semibold" style={{ color: 'var(--theme-text-muted, #6E7476)' }}>
            {done} complete
          </span>
          <button
            type="button"
            onClick={clearDone}
            className="text-xs font-bold underline-offset-2 hover:underline"
            style={{ color: 'var(--theme-text-muted, #6E7476)' }}
            data-testid="upload-queue-clear-done"
          >
            Clear complete
          </button>
        </div>
      )}
    </div>
  );
}

function formatEta(seconds) {
  const s = Math.max(1, Math.round(seconds));
  if (s < 60) return `~${s}s`;
  const m = Math.floor(s / 60);
  const rem = s % 60;
  return rem ? `~${m}m ${rem}s` : `~${m}m`;
}

function UploadTaskRow({ task, onRetry, onRemove }) {
  const isFailed = task.status === STATUS.FAILED;
  const isDone = task.status === STATUS.DONE;
  const isUploading = task.status === STATUS.UPLOADING;

  // Iter 279 — surface a live "time left" estimate + percentage so
  // operators uploading large equipment manuals can see how long the
  // transfer will take (Craig: "add a timer or indicator of how long is
  // left of the upload"). ETA = elapsed × (100 − pct) / pct.
  const pct = Math.round(task.progress || 0);
  let etaLabel = '';
  if (isUploading && task.startedAt && pct > 2 && pct < 100) {
    const elapsed = (Date.now() - task.startedAt) / 1000;
    const remaining = (elapsed * (100 - pct)) / pct;
    if (remaining > 0 && Number.isFinite(remaining)) etaLabel = `${formatEta(remaining)} left`;
  }

  return (
    <div
      className="px-3 py-2 border-b last:border-b-0 flex items-start gap-2"
      style={{ borderColor: 'var(--theme-border-soft, #F0F0F0)' }}
      data-testid={`upload-task-${task.id}`}
    >
      <div className="mt-0.5 shrink-0">
        {isUploading && <Loader2 size={12} className="animate-spin" style={{ color: 'var(--color-brand-cyan, #00D6E0)' }} />}
        {task.status === STATUS.QUEUED && <Upload size={12} style={{ color: 'var(--theme-text-muted, #6E7476)' }} />}
        {isDone && <CheckCircle2 size={12} className="text-emerald-500" />}
        {isFailed && <AlertTriangle size={12} className="text-red-500" />}
      </div>
      <div className="flex-1 min-w-0">
        <p className="text-xs font-semibold truncate" style={{ color: 'var(--theme-text, #1B1C1D)' }} title={task.name}>
          {task.name}
        </p>
        {isFailed ? (
          <p className="text-[10px] text-red-500 truncate" title={task.error}>{task.error}</p>
        ) : (
          <>
            <div className="h-1 rounded-full mt-1 overflow-hidden" style={{ background: 'var(--theme-border-soft, #F0F0F0)' }}>
              <div
                className="h-full transition-all"
                style={{
                  width: `${task.progress || (isUploading ? 30 : 0)}%`,
                  background: isDone ? '#10B981' : 'var(--color-brand-cyan, #00D6E0)',
                }}
              />
            </div>
            <p
              className="text-[10px] mt-0.5 tabular-nums"
              style={{ color: 'var(--theme-text-muted, #6E7476)' }}
              data-testid={`upload-task-progress-${task.id}`}
            >
              {isDone
                ? 'Complete'
                : isUploading
                  ? `${pct}%${etaLabel ? ` · ${etaLabel}` : ''}`
                  : 'Waiting…'}
            </p>
          </>
        )}
      </div>
      <div className="flex items-center gap-1 shrink-0">
        {isFailed && (
          <button
            type="button"
            onClick={onRetry}
            className="p-1 rounded hover:bg-zinc-100 dark:bg-zinc-800"
            title="Retry"
            data-testid={`upload-task-retry-${task.id}`}
          >
            <RotateCw size={11} style={{ color: 'var(--theme-text-muted, #6E7476)' }} />
          </button>
        )}
        <button
          type="button"
          onClick={onRemove}
          className="p-1 rounded hover:bg-zinc-100 dark:bg-zinc-800"
          title={isUploading ? 'Cancel' : 'Dismiss'}
          data-testid={`upload-task-remove-${task.id}`}
        >
          <X size={11} style={{ color: 'var(--theme-text-muted, #6E7476)' }} />
        </button>
      </div>
    </div>
  );
}

