  Home, ClipboardList, MapPin, Package, History as HistoryIcon, Globe2,
  LayoutGrid, LogOut, Wifi, WifiOff, ClipboardCheck, BarChart3, Users,
} from 'lucide-react';

export default function BFPOApp() {
  const { user, loading: authLoading, logout: platformLogout } = useAuth();
  // Shared devices: a different person signed in → wipe the previous person's offline data.
  useEffect(() => {
    const key = (user?.email || user?.id || '').toLowerCase();
    if (!key) return;
    const last = localStorage.getItem('bfpo_last_user');
    const ready = last && last !== key ? clearOfflineData() : Promise.resolve();
    ready.finally(() => { localStorage.setItem('bfpo_last_user', key); setOutboxOwner(key); flushOutbox(); });
  }, [user?.email, user?.id]);
  // A Pulse Fitness staffer granted the MOD Operations module (platform admins
  // always qualify) gets the staff operations view even without a bfpo_role.
  const hasModOps = !!(user && (user.is_master_admin || user.is_pulse_admin
    || (user.module_overrides && user.module_overrides.mod_operations === true)));
  const rawRole = (user?.bfpo_role || '').toLowerCase();
  const role = ['engineer', 'lead', 'staff'].includes(rawRole) ? rawRole : (hasModOps ? 'staff' : '');
  const [view, setView] = useState('home');
  const [jobId, setJobId] = useState(null);
  const [jobFilter, setJobFilter] = useState('all_open');
  const [staffFilter, setStaffFilter] = useState({});
  const [ppmId, setPpmId] = useState(null);
  const [online, setOnline] = useState(typeof navigator === 'undefined' ? true : navigator.onLine);
  const [welcome, setWelcome] = useState(null);

  useEffect(() => {
    let alive = true;
    if (user && (role === 'engineer' || role === 'lead')) {
      bfpo.get('/me/welcome').then((r) => { if (alive && r.data.show) setWelcome(r.data); }).catch(() => {});
    }
    return () => { alive = false; };
  }, [user, role]);

  const dismissWelcome = async () => {
    try { await bfpo.post('/me/welcome/dismiss'); } catch { /* ignore */ }
    setWelcome(null);
  };

  useEffect(() => { setView(role === 'staff' ? 'dashboard' : 'home'); }, [role]);
  // Engineers arrive here by in-app navigation from /MODService — make sure offline mode is on.
  useEffect(() => { if ('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').catch(() => {}); }, []);

  useEffect(() => {
    const on = () => setOnline(true); const off = () => setOnline(false);
    window.addEventListener('online', on); window.addEventListener('offline', off);
    return () => { window.removeEventListener('online', on); window.removeEventListener('offline', off); };
  }, []);

  if (authLoading) return <div className="min-h-screen bg-[#F7F7F7]"><Spinner label="Loading portal…" /></div>;
  // Not signed in → send to the standard MOD service login screen.
  if (!user) return <Navigate to="/MODService" replace />;
  // Signed in but not a MOD/BFPO account → friendly no-access card.
  if (!['engineer', 'lead', 'staff'].includes(role)) {
    return (
      <div className="min-h-screen bg-[#F7F7F7] flex items-center justify-center p-6" data-testid="bfpo-no-access">
        <div className="text-center max-w-sm">
          <p className="text-lg font-bold text-[#1B1C1D]">This area is for MOD/BFPO personnel</p>
          <p className="text-sm text-[#565B5E] mt-1">Your account doesn't have access to the BFPO Engineer Portal.</p>
          <a href="/dashboard" className="inline-block mt-4"><Btn variant="primary">Go to your dashboard</Btn></a>
        </div>
      </div>
    );
  }
  // MOD Operations overview dashboard is module-gated to select Pulse staff.
  if (role === 'staff' && !hasModOps) {
    return (
      <div className="min-h-screen bg-[#F7F7F7] flex items-center justify-center p-6" data-testid="bfpo-no-modops">
        <div className="text-center max-w-sm">
          <p className="text-lg font-bold text-[#1B1C1D]">Pulse Fitness MOD Operations</p>
          <p className="text-sm text-[#565B5E] mt-1">Your account isn't enabled for the MOD Operations overview dashboard. Ask a Master Admin to grant you the <span className="font-semibold">Pulse Fitness MOD Operations</span> module.</p>
          <a href="/dashboard" className="inline-block mt-4"><Btn variant="primary">Go to your dashboard</Btn></a>
        </div>
      </div>
    );
  }

  const logout = () => {
    const n = outboxCount();
    if (n && !window.confirm(`${n} saved update${n === 1 ? ' has' : 's have'} not been sent yet and will be deleted from this device if you sign out. Sign out anyway?`)) return;
    if (platformLogout) platformLogout();
  };
  const openJob = (id) => { setJobId(id); setView('job'); };
  const openStaffJob = (id) => { setJobId(id); setView('staffjob'); };
  const openPpm = (id) => { setPpmId(id); setView('ppmdetail'); };

  const engNav = [
    { key: 'home', label: 'Home', icon: Home },
    { key: 'jobs', label: 'Jobs', icon: ClipboardList },
    { key: 'sites', label: 'Sites', icon: MapPin },
    { key: 'equipment', label: 'Kit', icon: Package },
    { key: 'history', label: 'History', icon: HistoryIcon },
  ];
  const staffNav = [
    { key: 'dashboard', label: 'Dashboard', icon: LayoutGrid },
    { key: 'sites', label: 'Sites', icon: Globe2 },
    { key: 'jobs', label: 'Jobs', icon: ClipboardList },
    { key: 'servicing', label: 'Servicing', icon: ClipboardCheck },
    { key: 'reports', label: 'Reports', icon: BarChart3 },
    { key: 'engineers', label: 'Engineers', icon: Users },
  ];

  const Header = role === 'staff' ? (
    <>
      <Navbar />
      <div className="pt-24 pulse-font" style={{ background: 'var(--theme-bg)' }}>
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <h1 className="text-2xl sm:text-4xl tracking-tight font-semibold pulse-font-heading leading-tight" style={{ color: 'var(--theme-text)' }}>MOD Operations</h1>
          <p className="mt-1 text-sm pulse-font-body" style={{ color: 'var(--theme-text-muted)' }} data-testid="staff-welcome">
            Welcome back, <span className="font-medium" style={{ color: 'var(--theme-text)' }}>{user.full_name || 'Operations'}</span> · Global oversight
          </p>
          <PillTabBar className="mt-6 mb-2 w-full" activeId={view} testId="staff-nav-tabs" ariaLabel="MOD Operations sections">
            {staffNav.map((n) => {
              const isActive = view === n.key;
              return (
                <button key={n.key} data-pill-id={n.key} onClick={() => setView(n.key)} data-testid={`staff-nav-${n.key}`}
                  className="flex-shrink-0 inline-flex items-center gap-2 px-4 py-2.5 rounded-full text-sm font-semibold transition-colors whitespace-nowrap"
                  style={isActive
                    ? { background: 'var(--color-brand-cyan)', color: 'var(--color-ink)' }
                    : { color: 'var(--theme-text-muted)', background: 'transparent' }}>
                  <n.icon size={14} /> {n.label}
                </button>
              );
            })}
          </PillTabBar>
        </div>
      </div>
    </>
  ) : (
    <header className="sticky top-0 z-30" style={{ fontFamily: "'Proxima Nova', system-ui, sans-serif" }}>
      <div className="on-dark text-white border-b border-white/10" style={{ backgroundColor: '#000000' }}>
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
          <div className="flex items-center gap-2.5">
            <img src={PULSE_LOGO} alt="Pulse Fitness" className="h-10 rounded-md object-cover"
              style={{ objectPosition: 'center', aspectRatio: '3.8/1', clipPath: 'inset(12% 3% 12% 3% round 6px)' }}
              data-testid="bfpo-logo" />
          </div>
          <AccountMenu user={user} role={role} online={online} onLogout={logout} showSync />
        </div>
      </div>
    </header>
  );

  return (
    <div className={`min-h-screen flex flex-col ${role === 'staff' ? 'pulse-font overflow-x-hidden' : 'bg-[#F7F7F7]'}`} style={role === 'staff' ? { background: 'var(--theme-bg)' } : undefined}>
      {welcome && <WelcomeKit data={welcome} onStart={dismissWelcome} onViewJobs={() => { dismissWelcome(); setJobFilter('all_open'); setView('jobs'); }} />}
      {Header}
      <OfflineSyncBar online={online} />
      <UrgentAlertBanner online={online} onOpen={role === 'staff' ? openStaffJob : openJob} />
      <main className="flex-1">
        {role === 'staff' ? (
          <>
            {view === 'dashboard' && <StaffDashboard userName={user.full_name} role={role} onOpenJobs={(f) => { setStaffFilter(f); setView('jobs'); }} onOpenJob={openStaffJob} />}
            {view === 'sites' && <StaffSites onOpenJobs={(f) => { setStaffFilter(f); setView('jobs'); }} />}
            {view === 'jobs' && <StaffJobs initialFilter={staffFilter} onOpenJob={openStaffJob} />}
            {view === 'visiting' && <StaffVisiting />}
            {view === 'engineers' && <StaffEngineers />}
            {view === 'servicing' && <PPMStaff onOpen={openPpm} />}
            {view === 'reports' && <PPMReports />}
            {view === 'staffjob' && <StaffJobDetail jobId={jobId} onBack={() => setView('jobs')} />}
            {view === 'ppmdetail' && <PPMServiceDetail serviceId={ppmId} onBack={() => setView('servicing')} />}
          </>
        ) : (
          <>
            {view === 'home' && <EngineerHome onOpenJobs={(f) => { setJobFilter(f); setView('jobs'); }} onOpenJob={openJob} onOpenServices={() => setView('ppm')} />}
            {view === 'jobs' && <JobList initialFilter={jobFilter} onOpenJob={openJob} />}
            {view === 'sites' && <Sites />}
            {view === 'equipment' && <Equipment />}
            {view === 'history' && <History onOpenJob={openJob} />}
            {view === 'job' && <JobDetail jobId={jobId} onBack={() => setView('jobs')} onOpenJob={openJob} />}
            {view === 'ppm' && <PPMEngineerList onOpen={openPpm} onBack={() => setView('home')} />}
            {view === 'ppmdetail' && <PPMServiceDetail serviceId={ppmId} onBack={() => setView('ppm')} />}
          </>
        )}
      </main>

      <div className={role !== 'staff' ? 'pb-16' : ''}><Footer /></div>

      {/* Engineer bottom nav */}
      {role !== 'staff' && (
        <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 z-30" data-testid="engineer-bottom-nav">
          <div className="max-w-2xl mx-auto grid grid-cols-5">
            {engNav.map((n) => {
              const active = view === n.key || (view === 'job' && n.key === 'jobs');
              return (
                <button key={n.key} onClick={() => setView(n.key)} data-testid={`eng-nav-${n.key}`}
                  className={`flex flex-col items-center gap-0.5 py-2.5 text-[11px] font-medium ${active ? 'text-cyan-600' : 'text-slate-400'}`}>
                  <n.icon className="w-5 h-5" /> {n.label}
                </button>
              );
            })}
          </div>
        </nav>
      )}
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { inviteStatus, acceptInvite } from './bfpoApi';
import { PULSE_LOGO, inputCls } from './ui';
import { Loader2, CheckCircle2, KeyRound } from 'lucide-react';

export default function BFPOInviteSetPassword() {
  const { token } = useParams();
  const [state, setState] = useState({ loading: true });
  const [pw, setPw] = useState('');
  const [confirm, setConfirm] = useState('');
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState('');
  const [done, setDone] = useState(false);

  useEffect(() => {
    let alive = true;
    inviteStatus(token)
      .then((d) => { if (alive) setState({ loading: false, ...d }); })
      .catch(() => { if (alive) setState({ loading: false, valid: false, reason: 'error' }); });
    return () => { alive = false; };
  }, [token]);

  const submit = async (e) => {
    e.preventDefault();
    setErr('');
    if (pw.length < 8) { setErr('Password must be at least 8 characters'); return; }
    if (pw !== confirm) { setErr('Passwords do not match'); return; }
    setBusy(true);
    try { await acceptInvite(token, pw); setDone(true); }
    catch (e2) { setErr(e2?.response?.data?.detail || 'Could not set your password'); }
    finally { setBusy(false); }
  };

  const Shell = ({ children }) => (
    <div className="min-h-screen bg-[#F7F7F7] flex flex-col" style={{ fontFamily: "'Proxima Nova', system-ui, sans-serif" }}>
      <div className="on-dark text-white" style={{ backgroundColor: '#000000' }}>
        <div className="max-w-6xl mx-auto px-4 h-20 flex items-center">
          <img src={PULSE_LOGO} alt="Pulse Fitness" className="h-10 rounded-md object-cover" style={{ objectPosition: 'center', aspectRatio: '3.8/1', clipPath: 'inset(12% 3% 12% 3% round 6px)' }} />
        </div>
      </div>
      <div className="flex-1 flex items-center justify-center p-4">{children}</div>
    </div>
  );

  if (state.loading) return <Shell><Loader2 className="w-6 h-6 animate-spin text-slate-400" /></Shell>;

  if (!state.valid) {
    const msg = state.reason === 'used' ? 'This invite has already been used. Please sign in instead.'
      : state.reason === 'expired' ? 'This invite link has expired. Ask your MOD Operations contact to resend it.'
      : 'This invite link is invalid.';
    return (
      <Shell>
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-8 max-w-md text-center" data-testid="invite-invalid">
          <p className="text-lg font-bold text-slate-900 mb-1">Invite unavailable</p>
          <p className="text-sm text-slate-500 mb-5">{msg}</p>
          <a href="/MODService"><button className="bg-cyan-600 hover:bg-cyan-700 text-white font-semibold rounded-xl px-5 py-3 text-sm">Go to sign in</button></a>
        </div>
      </Shell>
    );
  }

  if (done) {
    return (
      <Shell>
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-8 max-w-md text-center" data-testid="invite-done">
          <CheckCircle2 className="w-12 h-12 text-emerald-500 mx-auto mb-3" />
          <p className="text-lg font-bold text-slate-900 mb-1">You're all set</p>
          <p className="text-sm text-slate-500 mb-5">Your password has been created. Sign in to open the MOD / BFPO Engineer Portal.</p>
          <a href="/MODService"><button className="bg-cyan-600 hover:bg-cyan-700 text-white font-semibold rounded-xl px-5 py-3 text-sm" data-testid="invite-done-signin">Sign in</button></a>
        </div>
      </Shell>
    );
  }

  return (
    <Shell>
      <form onSubmit={submit} className="bg-white rounded-2xl shadow-sm border border-slate-200 p-8 max-w-md w-full" data-testid="invite-form">
        <p className="text-xs font-semibold text-cyan-700 uppercase tracking-wide mb-1">MOD / BFPO Engineer Portal</p>
        <h1 className="text-2xl font-bold text-slate-900 mb-1">Set your password</h1>
        <p className="text-sm text-slate-500 mb-5">Welcome{state.full_name ? `, ${state.full_name}` : ''}. Choose a password for <span className="font-medium">{state.email}</span>.</p>
        <div className="space-y-3">
          <label className="block">
            <span className="text-xs font-semibold text-slate-500 uppercase tracking-wide">New password</span>
            <input type="password" className={`${inputCls} mt-1`} value={pw} onChange={(e) => setPw(e.target.value)} required data-testid="invite-pw" />
          </label>
          <label className="block">
            <span className="text-xs font-semibold text-slate-500 uppercase tracking-wide">Confirm password</span>
            <input type="password" className={`${inputCls} mt-1`} value={confirm} onChange={(e) => setConfirm(e.target.value)} required data-testid="invite-pw-confirm" />
          </label>
          {err && <p className="text-sm text-red-600" data-testid="invite-error">{err}</p>}
          <button type="submit" disabled={busy} className="w-full inline-flex items-center justify-center gap-2 bg-cyan-600 hover:bg-cyan-700 disabled:opacity-50 text-white font-semibold rounded-xl px-5 py-3 text-sm" data-testid="invite-submit">
            {busy ? <Loader2 className="w-4 h-4 animate-spin" /> : <KeyRound className="w-4 h-4" />} Set password &amp; activate
          </button>
        </div>
      </form>
    </Shell>
  );
}

