function CompletePanel({ jobId, job, onDone, onCancel }) {
  const [summary, setSummary] = useState('');
  const [report, setReportState] = useState({});
  const setReport = (patch) => setReportState((r) => ({ ...r, ...patch }));
  const [partsUsed, setPartsUsed] = useState('');
  const [safe, setSafe] = useState(true);
  const [signoff, setSignoff] = useState({});
  const [contact, setContact] = useState(null);
  const [reopened, setReopened] = useState(false);
  const [saving, setSaving] = useState(false);
  const [err, setErr] = useState('');
  useEffect(() => { bfpo.get(`/jobs/${jobId}/signoff`).then((r) => { setContact(r.data?.site_contact); setReopened(!!r.data?.reopened_at); }).catch(() => {}); }, [jobId]);

  const submit = async () => {
    if (!summary.trim()) { setErr('Please describe the work completed'); return; }
    const rep = { ...withReportDefaults(report, job?.arrived_at), work_completed: summary.trim() };
    if (!rep.start_time || !rep.end_time) { setErr('Add the start and end time'); return; }
    if (reportTimeError(rep)) { setErr(reportTimeError(rep)); return; }
    const so = signoffBody(signoff);
    if (so.error) { setErr(so.error); return; }
    setSaving(true); setErr('');
    try {
      await bfpo.post(`/jobs/${jobId}/signature`, so.body);
      const done = await bfpo.post(`/jobs/${jobId}/complete`, { summary, parts_used: partsUsed, safe_and_working: safe, report: rep });
      onDone(!!done?.data?.queued);
    } catch (e) { setErr(e?.response?.data?.detail || 'Could not complete — try again'); }
    finally { setSaving(false); }
  };

  return (
    <Card className="p-4 space-y-3" data-testid="panel-complete">
      <p className="font-semibold text-slate-900">Complete job</p>
      <Field label="Description of Work Completed *"><textarea className={inputCls} rows={3} value={summary} onChange={(e) => setSummary(e.target.value)} data-testid="complete-summary" /></Field>
      <Field label="Parts used (optional)"><input className={inputCls} value={partsUsed} onChange={(e) => setPartsUsed(e.target.value)} data-testid="complete-parts" /></Field>
      <EngineerReportFields value={report} onChange={setReport} defaultStart={job?.arrived_at} />
      <label className="flex items-center gap-2 text-sm text-slate-700 font-medium"><input type="checkbox" checked={safe} onChange={(e) => setSafe(e.target.checked)} data-testid="complete-safe" /> I confirm the equipment is safe and working</label>
      <SignOffFields value={signoff} onChange={setSignoff} contact={contact} reopened={reopened} testid="complete-sig" />
      {err && <p className="text-sm text-red-600">{err}</p>}
      <div className="grid grid-cols-1 gap-2">
        <Btn variant="primary" full disabled={saving} onClick={submit} data-testid="complete-submit">{saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <CheckCircle2 className="w-4 h-4" />} Complete & generate job sheet</Btn>
        <Btn variant="ghost" full onClick={onCancel}>Back</Btn>
      </div>
    </Card>
  );
}

import React, { useEffect, useState } from 'react';
import { bfpo, pendingStatusFor } from '../bfpoApi';
import { Card, PriorityBadge, Spinner, Empty, Badge, STATUS_LABEL } from '../ui';
import { AlertTriangle, ChevronRight, ClipboardList } from 'lucide-react';

const FILTERS = [
  { key: 'all_open', label: 'All Open' },
  { key: 'new', label: 'New' },
  { key: 'in_progress', label: 'In Progress' },
  { key: 'waiting_parts', label: 'Waiting for Parts' },
  { key: 'return_visit', label: 'Return Visit' },
  { key: 'completed', label: 'Completed' },
];

export default function JobList({ initialFilter = 'all_open', onOpenJob }) {
  const [filter, setFilter] = useState(initialFilter);
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => { setFilter(initialFilter); }, [initialFilter]);

  useEffect(() => {
    let live = true;
    setLoading(true);
    bfpo.get(`/jobs?when=${filter}`).then((r) => { if (live) { setJobs(r.data.jobs); setLoading(false); } });
    return () => { live = false; };
  }, [filter]);

  return (
    <div className="p-4 max-w-2xl mx-auto" data-testid="engineer-joblist">
      <h1 className="text-2xl font-bold text-slate-900 mb-3">Jobs</h1>
      <div className="flex gap-2 overflow-x-auto pb-3 -mx-1 px-1">
        {FILTERS.map((f) => (
          <button key={f.key} onClick={() => setFilter(f.key)} data-testid={`joblist-filter-${f.key}`}
            className={`whitespace-nowrap px-3.5 py-2 rounded-full text-sm font-semibold border transition-colors ${filter === f.key ? 'bg-slate-900 text-white border-slate-900' : 'bg-white text-slate-600 border-slate-200'}`}>
            {f.label}
          </button>
        ))}
      </div>
      {loading ? <Spinner /> : jobs.length === 0 ? (
        <Empty icon={ClipboardList} title="No jobs here" sub="Nothing matches this filter." testid="joblist-empty" />
      ) : (
        <div className="space-y-2">
          {jobs.map((j) => (
            <button key={j.id} onClick={() => onOpenJob(j.id)} className="w-full text-left" data-testid={`joblist-job-${j.id}`}>
              <Card className="p-4 hover:shadow-md transition-shadow flex items-center gap-3">
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 flex-wrap">
                    <PriorityBadge p={j.priority} />
                    {j.safety_critical && <Badge className="bg-red-100 text-red-700 border-red-200"><AlertTriangle className="w-3 h-3" /> Safety</Badge>}
                    <Badge className="bg-slate-100 text-slate-600 border-slate-200">{STATUS_LABEL[pendingStatusFor(j.id, j.status)] || pendingStatusFor(j.id, j.status)}</Badge>
                  </div>
                  <p className="font-semibold text-slate-900 truncate mt-1.5">{j.title}</p>
                  <p className="text-sm text-slate-500 truncate">{j.reference} · {j.site_name} · {j.asset_name}</p>
                </div>
                <ChevronRight className="w-5 h-5 text-slate-300 shrink-0" />
              </Card>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { ClipboardList, ChevronDown, CheckCircle2 } from 'lucide-react';
import { bfpo } from '../bfpoApi';
import { Card, Btn, Badge, inputCls } from '../ui';

const LABEL = {
  name: 'Description', location: 'Location', sub_location: 'Sublocation', manufacturer: 'Make',
  model: 'Model', serial_number: 'Serial Number', install_date: 'Install Date',
  last_service_date: 'Last Service Date', id_number: 'ID Number',
  asset_number: 'Asset Tag', condition: 'Condition', manufacturing_date: 'Manufacture Date',
};
const DATES = new Set(['install_date', 'last_service_date', 'manufacturing_date']);
const CONDITIONS = ['New', 'Good', 'Fair', 'Poor', 'Out of Service'];
const PLACEHOLDER = /^\s*(unknown|n\/?a|tbc|tbd|none|null|-|0)\s*$/i;

function AssetForm({ jobId, item, onSaved }) {
  const [vals, setVals] = useState({});
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState('');
  const fields = [...new Set([...item.missing, 'sub_location', 'asset_number', 'condition'])];
  const save = async () => {
    setBusy(true); setErr('');
    try {
      const r = await bfpo.post(`/jobs/${jobId}/equipment/${item.id}/details`, vals);
      onSaved(item.id, r?.data?.queued);
    } catch (e) { setErr(e?.response?.data?.detail || 'Could not save'); }
    finally { setBusy(false); }
  };
  return (
    <div className="rounded-xl border border-slate-200 p-3 space-y-2" data-testid={`asset-gap-${item.id}`}>
      <div>
        <p className="font-semibold text-slate-900 text-sm">{item.name || 'Unnamed machine'}</p>
        <p className="text-xs text-slate-500">{[item.manufacturer, item.model, item.location].filter((v) => v && !PLACEHOLDER.test(v)).join(' · ') || 'No details yet'}</p>
      </div>
      {fields.map((f) => (
        <label key={f} className="block">
          <span className="text-xs font-semibold text-slate-600">{LABEL[f] || f}{item.missing.includes(f) && <span className="text-red-600"> *</span>}</span>
          {f === 'condition' ? (
            <select className={`${inputCls} mt-1`} defaultValue={item.condition || ''} onChange={(e) => setVals((v) => ({ ...v, condition: e.target.value }))} data-testid={`asset-gap-condition-${item.id}`}>
              <option value="">—</option>
              {CONDITIONS.map((c) => <option key={c} value={c}>{c}</option>)}
            </select>
          ) : (
            <input type={DATES.has(f) ? 'date' : 'text'} className={`${inputCls} mt-1`} defaultValue={item[f] && !PLACEHOLDER.test(item[f]) ? item[f] : ''}
              onChange={(e) => setVals((v) => ({ ...v, [f]: e.target.value }))} data-testid={`asset-gap-${f}-${item.id}`} />
          )}
        </label>
      ))}
      {err && <p className="text-xs text-red-600">{err}</p>}
      <Btn full onClick={save} disabled={busy || !Object.values(vals).some((v) => String(v).trim())} data-testid={`asset-gap-save-${item.id}`}>
        {busy ? 'Saving…' : 'Save details'}
      </Btn>
    </div>
  );
}

export default function MissingAssetDetails({ jobId }) {
  const [data, setData] = useState(null);
  const [open, setOpen] = useState(false);
  const [done, setDone] = useState({});
  useEffect(() => { bfpo.get(`/jobs/${jobId}/equipment-gaps`).then((r) => setData(r.data)).catch(() => {}); }, [jobId]);
  if (!data?.items?.length) return null;
  const left = data.items.filter((i) => !done[i.id]);
  return (
    <Card className="p-4 border-l-4 border-l-amber-500" data-testid="missing-asset-details">
      <button className="w-full flex items-center gap-3 text-left" onClick={() => setOpen((o) => !o)} data-testid="missing-asset-details-toggle">
        <ClipboardList className="w-5 h-5 text-amber-600 shrink-0" />
        <div className="flex-1 min-w-0">
          <p className="text-xs font-semibold text-amber-700 uppercase">While you're on site</p>
          <p className="font-semibold text-slate-900 text-sm">{left.length ? `${left.length} machine${left.length > 1 ? 's' : ''} here need details` : 'All captured — thank you'}</p>
        </div>
        <ChevronDown className={`w-5 h-5 text-slate-400 transition-transform duration-200 ${open ? 'rotate-180' : ''}`} />
      </button>
      {open && (
        <div className="mt-3 space-y-3">
          <p className="text-xs text-slate-500">Check the plate on each machine and fill in what's missing. Red * items are required for the service record.</p>
          {data.items.map((it) => (done[it.id]
            ? <Badge key={it.id} className="bg-emerald-50 text-emerald-700 border-emerald-200" data-testid={`asset-gap-done-${it.id}`}><CheckCircle2 className="w-3 h-3" /> {it.name} — {done[it.id] === 'queued' ? 'saved on phone' : 'saved'}</Badge>
            : <AssetForm key={it.id} jobId={jobId} item={it} onSaved={(id, q) => setDone((d) => ({ ...d, [id]: q ? 'queued' : 'sent' }))} />))}
        </div>
      )}
    </Card>
  );
}

import React from 'react';
import SignaturePad from './SignaturePad';
import { inputCls } from '../ui';

const EMAIL_RE = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;

// value: {name, email, role, image, unavailable, reason}
export const signoffBody = (v) => {
  if (v.unavailable) return (v.reason || '').trim() ? { body: { unavailable: true, reason: v.reason.trim() } } : { error: "Say why the customer couldn't sign" };
  if (!v.image) return { error: 'Customer signature is required' };
  if (!(v.name || '').trim()) return { error: "Enter the customer's printed name" };
  if (v.email && !EMAIL_RE.test(v.email.trim())) return { error: 'Enter a valid customer email' };
  return { body: { signed_by_name: v.name.trim(), signed_by_email: (v.email || '').trim(), signed_by_role: (v.role || '').trim(), image_data: v.image } };
};

export default function SignOffFields({ value, onChange, contact, reopened, testid = 'signoff' }) {
