            <label className="text-xs font-semibold text-slate-600">Role<input className={`${inputCls} mt-1`} placeholder="e.g. PTI" value={value.role || ''} onChange={(e) => set({ role: e.target.value })} data-testid={`${testid}-role`} /></label>
