import { Card, Btn, Badge, Spinner, Field, inputCls } from '../ui';
import SignOffFields, { signoffBody } from '../engineer/SignOffFields';
import { EngineerReportFields, withReportDefaults, reportTimeError } from '@/components/shared/EngineerReportFields';
import { EngineerReportView } from '@/components/shared/EngineerReportView';
import { ChevronLeft, CheckCircle2, XCircle, MinusCircle, Wrench, AlertTriangle, FileText, Loader2, ClipboardCheck } from 'lucide-react';

const STATUS_CHIP = {
  pending: { label: 'To check', cls: 'bg-slate-100 text-slate-600 border-slate-200' },
  passed: { label: 'Passed', cls: 'bg-emerald-50 text-emerald-700 border-emerald-200' },
  failed: { label: 'Fault raised', cls: 'bg-red-50 text-red-700 border-red-200' },
};

export default function PPMServiceDetail({ serviceId, onBack }) {
  const [svc, setSvc] = useState(null);
  const [active, setActive] = useState(null); // inspection being filled
  const [busy, setBusy] = useState(false);
  const [toast, setToast] = useState('');
  const [signoff, setSignoff] = useState({});
  const [report, setReportState] = useState({});
  const setReport = (patch) => setReportState((r) => ({ ...r, ...patch }));

  const load = useCallback(async () => {
    const r = await bfpo.get(`/ppm/services/${serviceId}`);
    setSvc(r.data);
  }, [serviceId]);
  useEffect(() => { load(); }, [load]);

  const flash = (m) => { setToast(m); setTimeout(() => setToast(''), 2600); };
  if (!svc) return <Spinner />;
  const p = svc.progress || {};
  const completed = svc.status === 'completed';

  const complete = async () => {
    const rep = withReportDefaults(report, svc.started_at);
    if (!(rep.work_completed || '').trim()) { flash('Add a description of the work completed'); return; }
    if (!rep.start_time || !rep.end_time) { flash('Add the start and end time'); return; }
    if (reportTimeError(rep)) { flash(reportTimeError(rep)); return; }
    const so = signoffBody(signoff);
    if (so.error) { flash(so.error); return; }
    setBusy(true);
    try { const r = await bfpo.post(`/ppm/services/${serviceId}/complete`, { signoff: so.body, report: rep, notes: rep.work_completed }); await load(); flash(r.data.emailed_to ? `Certificate issued & emailed to ${r.data.emailed_to}` : 'Service certificate issued'); }
    catch (e) { flash(e?.response?.data?.detail || 'Could not complete'); }
    finally { setBusy(false); }
  };

  return (
    <div className="pb-28 max-w-2xl mx-auto lg:max-w-4xl" data-testid="ppm-service-detail">
      <div className="sticky top-0 z-10 bg-white border-b border-slate-200 px-4 py-3 flex items-center gap-3">
        <button onClick={onBack} data-testid="ppm-back" className="p-1 -ml-1"><ChevronLeft className="w-6 h-6 text-slate-600" /></button>
        <div className="min-w-0 flex-1">
          <p className="font-bold text-slate-900 truncate">{svc.reference} · {svc.site_name}</p>
          <p className="text-xs text-slate-500">{svc.territory_name} · {svc.country}</p>
        </div>
        <Badge className={completed ? 'bg-emerald-50 text-emerald-700 border-emerald-200' : 'bg-cyan-50 text-cyan-700 border-cyan-200'}>{completed ? 'Completed' : (svc.status === 'due' ? 'Due' : 'In progress')}</Badge>
      </div>

      <div className="p-4 space-y-4">
        <Card className="p-4 flex items-center gap-4">
          <ClipboardCheck className="w-8 h-8 text-cyan-600" />
          <div className="flex-1">
            <p className="font-semibold text-slate-900" data-testid="ppm-progress">{p.done} of {p.total} checked</p>
            <div className="h-2 bg-slate-100 rounded-full mt-1.5 overflow-hidden">
              <div className="h-full bg-cyan-500" style={{ width: `${p.total ? (p.done / p.total) * 100 : 0}%` }} />
            </div>
            {p.failed > 0 && <p className="text-xs text-red-600 mt-1">{p.failed} fault(s) raised</p>}
          </div>
          {completed && (
            <a href={`${process.env.REACT_APP_BACKEND_URL}/api/bfpo/ppm/services/${serviceId}/certificate.pdf`} target="_blank" rel="noreferrer"
              className="text-cyan-600 font-semibold text-sm flex items-center gap-1" data-testid="ppm-cert-link"><FileText className="w-4 h-4" /> Certificate</a>
          )}
        </Card>

        {completed && svc.engineer_report && <EngineerReportView report={svc.engineer_report} signoff={svc.signoff} />}
        <div className="space-y-2">
          {(svc.inspections || []).map((i) => (
            <button key={i.id} disabled={completed} onClick={() => setActive(i)} className="w-full text-left disabled:opacity-70" data-testid={`ppm-asset-${i.id}`}>
              <Card className="p-4 flex items-center gap-3 hover:shadow-md transition-shadow">
                <Wrench className="w-5 h-5 text-slate-400 shrink-0" />
                <div className="flex-1 min-w-0">
                  <p className="font-semibold text-slate-900 truncate">{i.equipment_name}</p>
                  <p className="text-sm text-slate-500 truncate">{i.serial} · {i.results?.length || 0} checks</p>
                </div>
                <Badge className={(STATUS_CHIP[i.status] || STATUS_CHIP.pending).cls}>{(STATUS_CHIP[i.status] || STATUS_CHIP.pending).label}</Badge>
              </Card>
            </button>
          ))}
        </div>
      </div>

      {!completed && p.remaining === 0 && (
        <div className="px-4 pb-40 space-y-3"><EngineerReportFields value={report} onChange={setReport} defaultStart={svc.started_at} showWork /><Card className="p-4"><SignOffFields value={signoff} onChange={setSignoff} testid="ppm-signoff" /></Card></div>
      )}

      {active && <ChecklistPanel inspection={active} onClose={() => setActive(null)}
        onSaved={() => { setActive(null); load(); flash('Inspection saved'); }} onFlash={flash} />}

      {!completed && (
        <div className="fixed bottom-16 left-0 right-0 px-4 pb-3 pt-2 bg-gradient-to-t from-white via-white to-transparent max-w-2xl mx-auto">
          <Btn full variant="primary" disabled={busy || p.remaining > 0} onClick={complete} data-testid="ppm-complete" className="shadow-lg py-4 text-base">
            {busy ? <Loader2 className="w-5 h-5 animate-spin" /> : <CheckCircle2 className="w-5 h-5" />}
            {p.remaining > 0 ? `${p.remaining} asset(s) left to check` : 'Complete & issue certificate'}
          </Btn>
        </div>
      )}
      {toast && <div className="fixed bottom-32 left-1/2 -translate-x-1/2 bg-slate-900 text-white text-sm px-4 py-2 rounded-full shadow-lg z-20" data-testid="ppm-toast">{toast}</div>}
    </div>
  );
}

function ChecklistPanel({ inspection, onClose, onSaved, onFlash }) {
  const [results, setResults] = useState(inspection.results.map((r) => ({ ...r })));
  const [busy, setBusy] = useState(false);
  const [faultOpen, setFaultOpen] = useState(false);
  const [faultTitle, setFaultTitle] = useState(`PPM fault: ${inspection.equipment_name}`);
  const [faultPriority, setFaultPriority] = useState('p3');
  const [faultSafety, setFaultSafety] = useState(false);
  const [raised, setRaised] = useState(inspection.fault_reference || '');

  const setResult = (idx, val) => setResults((rs) => rs.map((r, i) => i === idx ? { ...r, result: val } : r));
  const setNote = (idx, val) => setResults((rs) => rs.map((r, i) => i === idx ? { ...r, note: val } : r));
  const anyFail = results.some((r) => r.result === 'fail');

  const save = async () => {
    setBusy(true);
    try { await bfpo.post(`/ppm/inspections/${inspection.id}`, { results }); if (!anyFail) onSaved(); else onFlash('Saved — raise a fault for the failed item(s)'); }
    catch (e) { onFlash(e?.response?.data?.detail || 'Could not save'); }
    finally { setBusy(false); }
  };
  const raiseFault = async () => {
    setBusy(true);
    try {
      await bfpo.post(`/ppm/inspections/${inspection.id}`, { results });
      const r = await bfpo.post(`/ppm/inspections/${inspection.id}/raise-fault`, { title: faultTitle, priority: faultPriority, safety_critical: faultSafety });
      setRaised(r.data.reference); setFaultOpen(false); onFlash(`Fault ${r.data.reference} created`); setTimeout(onSaved, 800);
    } catch (e) { onFlash(e?.response?.data?.detail || 'Could not raise fault'); }
    finally { setBusy(false); }
  };

  const OPTS = [
    { v: 'pass', label: 'Pass', icon: CheckCircle2, on: 'bg-emerald-600 text-white', off: 'text-emerald-700' },
    { v: 'fail', label: 'Fail', icon: XCircle, on: 'bg-red-600 text-white', off: 'text-red-700' },
    { v: 'na', label: 'N/A', icon: MinusCircle, on: 'bg-slate-600 text-white', off: 'text-slate-600' },
  ];

  return (
    <div className="fixed inset-0 z-50 bg-black/40 flex items-end sm:items-center justify-center" onMouseDown={onClose} data-testid="ppm-checklist">
      <div className="bg-white w-full sm:max-w-lg sm:rounded-2xl rounded-t-2xl max-h-[88vh] overflow-y-auto p-5" onMouseDown={(e) => e.stopPropagation()}>
        <h2 className="text-lg font-bold text-slate-900">{inspection.equipment_name}</h2>
        <p className="text-sm text-slate-500 mb-4">{inspection.serial} · {inspection.template_name || 'Inspection'}</p>
        <div className="space-y-3">
          {results.map((r, idx) => (
            <div key={r.item_id} className="border-b border-slate-100 pb-3" data-testid={`ppm-item-${idx}`}>
              <p className="text-sm font-medium text-slate-800 mb-2">{r.label}</p>
              <div className="flex gap-2">
                {OPTS.map((o) => (
                  <button key={o.v} onClick={() => setResult(idx, o.v)} data-testid={`ppm-item-${idx}-${o.v}`}
                    className={`flex-1 flex items-center justify-center gap-1 py-2 rounded-lg text-sm font-semibold border transition-colors ${r.result === o.v ? o.on + ' border-transparent' : 'bg-white border-slate-200 ' + o.off}`}>
                    <o.icon className="w-4 h-4" /> {o.label}
                  </button>
                ))}
              </div>
              {r.result === 'fail' && <input className={inputCls + ' mt-2'} placeholder="What's wrong?" value={r.note} onChange={(e) => setNote(idx, e.target.value)} data-testid={`ppm-item-${idx}-note`} />}
            </div>
          ))}
        </div>

        {raised ? (
          <p className="mt-4 text-sm text-red-700 flex items-center gap-1"><AlertTriangle className="w-4 h-4" /> Fault {raised} raised for this asset</p>
        ) : faultOpen ? (
          <div className="mt-4 space-y-2 border-t border-slate-100 pt-4">
            <Field label="Fault title"><input className={inputCls} value={faultTitle} onChange={(e) => setFaultTitle(e.target.value)} data-testid="ppm-fault-title" /></Field>
            <Field label="Priority">
              <select className={inputCls} value={faultPriority} onChange={(e) => setFaultPriority(e.target.value)} data-testid="ppm-fault-priority">
                <option value="p1">P1 · Critical</option><option value="p2">P2 · High</option><option value="p3">P3 · Medium</option><option value="p4">P4 · Low</option>
              </select>
            </Field>
            <label className="flex items-center gap-2 text-sm text-slate-700"><input type="checkbox" checked={faultSafety} onChange={(e) => setFaultSafety(e.target.checked)} data-testid="ppm-fault-safety" /> Safety critical</label>
            <Btn full variant="danger" disabled={busy} onClick={raiseFault} data-testid="ppm-fault-submit">{busy ? <Loader2 className="w-4 h-4 animate-spin" /> : <AlertTriangle className="w-4 h-4" />} Create fault & save</Btn>
          </div>
        ) : null}

        <div className="mt-5 grid grid-cols-1 gap-2">
          {anyFail && !faultOpen && !raised && <Btn full variant="outline" onClick={() => setFaultOpen(true)} data-testid="ppm-raise-fault"><AlertTriangle className="w-4 h-4" /> Raise a fault</Btn>}
          <Btn full variant="primary" disabled={busy} onClick={save} data-testid="ppm-save">{busy ? <Loader2 className="w-4 h-4 animate-spin" /> : null} Save inspection</Btn>
          <Btn full variant="ghost" onClick={onClose}>Close</Btn>
        </div>
      </div>
    </div>
  );
}

import React, { useEffect, useState, useCallback } from 'react';
import { bfpo } from '../bfpoApi';
import { Card, Btn, Badge, Spinner, Empty, Field, inputCls } from '../ui';
import { ClipboardCheck, Plus, FileText, Settings2, Trash2, Loader2, ChevronRight, X } from 'lucide-react';

export default function PPMStaff({ onOpen }) {
  const [tab, setTab] = useState('services');
  return (
    <div className="p-6 max-w-6xl mx-auto" data-testid="ppm-staff">
      <div className="flex items-center justify-start mb-4">
        <div className="flex gap-1 bg-slate-100 rounded-lg p-1">
          <button onClick={() => setTab('services')} data-testid="ppm-tab-services" className={`px-3 py-1.5 rounded-md text-sm font-semibold ${tab === 'services' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-500'}`}>Services</button>
          <button onClick={() => setTab('schedules')} data-testid="ppm-tab-schedules" className={`px-3 py-1.5 rounded-md text-sm font-semibold ${tab === 'schedules' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-500'}`}>Schedules</button>
          <button onClick={() => setTab('templates')} data-testid="ppm-tab-templates" className={`px-3 py-1.5 rounded-md text-sm font-semibold ${tab === 'templates' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-500'}`}>Checklists</button>
        </div>
      </div>
      {tab === 'services' ? <Services onOpen={onOpen} /> : tab === 'schedules' ? <Schedules /> : <Templates />}
    </div>
  );
}

function Services({ onOpen }) {
  const [rows, setRows] = useState(null);
  const [meta, setMeta] = useState({ sites: [], engineers: [] });
  const [form, setForm] = useState({ site_id: '', due_date: '', engineer_id: '' });
  const [busy, setBusy] = useState(false);
  const [creating, setCreating] = useState(false);
  const [err, setErr] = useState('');

  const load = useCallback(() => { bfpo.get('/ppm/services').then((r) => setRows(r.data.services)); }, []);
  useEffect(() => { load(); Promise.all([bfpo.get('/sites'), bfpo.get('/staff/engineers')]).then(([s, e]) => setMeta({ sites: s.data.sites, engineers: e.data.engineers })); }, [load]);

  const create = async () => {
    setBusy(true); setErr('');
    try { await bfpo.post('/ppm/services', form); setForm({ site_id: '', due_date: '', engineer_id: '' }); setCreating(false); load(); }
    catch (e) { setErr(e?.response?.data?.detail || 'Could not create'); }
    finally { setBusy(false); }
  };
  if (!rows) return <Spinner />;

  return (
    <>
      {creating ? (
        <Card className="p-4 mb-4" data-testid="ppm-create-form">
          <p className="font-semibold text-slate-900 mb-3">New service</p>
          <div className="grid md:grid-cols-3 gap-3">
            <Field label="Site"><select className={inputCls} value={form.site_id} onChange={(e) => setForm({ ...form, site_id: e.target.value })} data-testid="ppm-create-site"><option value="">— choose —</option>{meta.sites.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</select></Field>
            <Field label="Due date"><input type="date" className={inputCls} value={form.due_date} onChange={(e) => setForm({ ...form, due_date: e.target.value })} data-testid="ppm-create-due" /></Field>
            <Field label="Assign engineer (optional)"><select className={inputCls} value={form.engineer_id} onChange={(e) => setForm({ ...form, engineer_id: e.target.value })} data-testid="ppm-create-engineer"><option value="">Unallocated</option>{meta.engineers.map((e) => <option key={e.id} value={e.id}>{e.full_name}</option>)}</select></Field>
          </div>
          {err && <p className="text-sm text-red-600 mt-2">{err}</p>}
          <div className="flex gap-2 mt-3">
            <Btn variant="primary" disabled={busy || !form.site_id} onClick={create} data-testid="ppm-create-submit">{busy ? <Loader2 className="w-4 h-4 animate-spin" /> : <Plus className="w-4 h-4" />} Create service</Btn>
            <Btn variant="ghost" onClick={() => setCreating(false)}>Cancel</Btn>
          </div>
        </Card>
      ) : (
        <div className="mb-4"><Btn variant="primary" onClick={() => setCreating(true)} data-testid="ppm-new-service"><Plus className="w-4 h-4" /> New service</Btn></div>
      )}

      {rows.length === 0 ? <Empty icon={ClipboardCheck} title="No services yet" testid="ppm-staff-empty" /> : (
        <Card className="overflow-hidden">
          <table className="w-full text-sm">
            <thead className="bg-slate-50 text-slate-500 text-xs uppercase"><tr><th className="text-left p-3">Ref</th><th className="text-left p-3">Site</th><th className="text-left p-3 hidden md:table-cell">Engineer</th><th className="text-left p-3">Progress</th><th className="text-left p-3">Status</th><th className="p-3" /></tr></thead>
            <tbody>
              {rows.map((s) => (
                <tr key={s.id} className="border-t border-slate-100 hover:bg-slate-50" data-testid={`ppm-staff-row-${s.id}`}>
                  <td className="p-3 font-mono text-xs text-slate-500">{s.reference}</td>
                  <td className="p-3 font-medium text-slate-800">{s.site_name}</td>
                  <td className="p-3 hidden md:table-cell text-slate-500">{s.assigned_engineer_name || <span className="text-amber-600">Unallocated</span>}</td>
                  <td className="p-3 text-slate-600">{s.progress?.done}/{s.progress?.total}{s.progress?.failed ? ` · ${s.progress.failed} fault` : ''}</td>
                  <td className="p-3"><Badge className={s.status === 'completed' ? 'bg-emerald-50 text-emerald-700 border-emerald-200' : s.status === 'due' ? 'bg-amber-50 text-amber-700 border-amber-200' : 'bg-cyan-50 text-cyan-700 border-cyan-200'}>{s.status === 'in_progress' ? 'In progress' : s.status === 'due' ? 'Due' : 'Completed'}</Badge></td>
                  <td className="p-3 flex items-center gap-3">
                    {s.status === 'completed' && <a href={`${process.env.REACT_APP_BACKEND_URL}/api/bfpo/ppm/services/${s.id}/certificate.pdf`} target="_blank" rel="noreferrer" className="text-cyan-600" title="Certificate" data-testid={`ppm-cert-${s.id}`}><FileText className="w-4 h-4" /></a>}
                    <button onClick={() => onOpen(s.id)} className="text-slate-400 hover:text-slate-600" data-testid={`ppm-open-${s.id}`}><ChevronRight className="w-4 h-4" /></button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </Card>
      )}
    </>
  );
}

function Schedules() {
  const [rows, setRows] = useState(null);
  const [saving, setSaving] = useState('');
  const load = useCallback(() => { bfpo.get('/ppm/schedules').then((r) => setRows(r.data.schedules)); }, []);
  useEffect(() => { load(); }, [load]);
  const save = async (site_id, frequency) => {
    setSaving(site_id);
    try { await bfpo.post('/ppm/schedules', { site_id, frequency }); await load(); }
    finally { setSaving(''); }
  };
  if (!rows) return <Spinner />;
  return (
    <div data-testid="ppm-schedules">
      <p className="text-sm text-slate-500 mb-3">Services auto-generate as "due" on each site's cadence. The scheduler runs daily.</p>
      <Card className="overflow-hidden">
        <table className="w-full text-sm">
          <thead className="bg-slate-50 text-slate-500 text-xs uppercase"><tr><th className="text-left p-3">Site</th><th className="text-left p-3 hidden md:table-cell">Territory</th><th className="text-left p-3">Cadence</th><th className="text-left p-3">Next due</th></tr></thead>
          <tbody>
            {rows.map((s) => (
              <tr key={s.site_id} className="border-t border-slate-100" data-testid={`ppm-sched-${s.site_id}`}>
                <td className="p-3 font-medium text-slate-800">{s.site_name}</td>
                <td className="p-3 hidden md:table-cell text-slate-500">{s.territory_name}</td>
                <td className="p-3">
                  <select className={inputCls + ' max-w-[160px]'} value={s.frequency} disabled={saving === s.site_id}
                    onChange={(e) => save(s.site_id, e.target.value)} data-testid={`ppm-sched-freq-${s.site_id}`}>
                    <option value="none">None</option><option value="quarterly">Quarterly</option><option value="annual">Annual</option>
                  </select>
                </td>
                <td className="p-3 text-slate-600">{s.frequency === 'none' ? '—' : (s.next_due || '—')}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </Card>
    </div>
  );
}

function Templates() {
  const [rows, setRows] = useState(null);
  const [edit, setEdit] = useState(null);

  const load = useCallback(() => { bfpo.get('/ppm/templates').then((r) => setRows(r.data.templates)); }, []);
  useEffect(() => { load(); }, [load]);
  if (!rows) return <Spinner />;

  return (
    <div className="space-y-3" data-testid="ppm-templates">
      <p className="text-sm text-slate-500">Checklists applied to each asset by equipment category. Edit to add, rename or remove checks.</p>
      {rows.map((t) => (
        <Card key={t.id} className="p-4">
          <div className="flex items-center justify-between">
            <div><p className="font-semibold text-slate-900">{t.name}</p><p className="text-xs text-slate-500">{t.category} · {t.items.length} checks</p></div>
            <Btn variant="outline" onClick={() => setEdit({ ...t, items: t.items.map((i) => ({ ...i })) })} data-testid={`ppm-tpl-edit-${t.category}`}><Settings2 className="w-4 h-4" /> Edit</Btn>
          </div>
        </Card>
      ))}
      {edit && <TemplateEditor tpl={edit} onClose={() => setEdit(null)} onSaved={() => { setEdit(null); load(); }} />}
    </div>
  );
}

function TemplateEditor({ tpl, onClose, onSaved }) {
  const [items, setItems] = useState(tpl.items.map((i) => i.label));
  const [busy, setBusy] = useState(false);
  const save = async () => {
    setBusy(true);
    try { await bfpo.post('/ppm/templates', { category: tpl.category, name: tpl.name, items: items.filter((x) => x.trim()).map((label) => ({ label })) }); onSaved(); }
    finally { setBusy(false); }
  };
  return (
    <div className="fixed inset-0 z-50 bg-black/40 flex items-center justify-center p-4" onMouseDown={onClose} data-testid="ppm-tpl-editor">
      <div className="bg-white rounded-2xl w-full max-w-lg max-h-[88vh] overflow-y-auto p-5" onMouseDown={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between mb-3"><h2 className="text-lg font-bold text-slate-900">{tpl.name}</h2><button onClick={onClose} className="p-1 text-slate-400"><X className="w-5 h-5" /></button></div>
        <div className="space-y-2">
          {items.map((it, idx) => (
            <div key={idx} className="flex gap-2">
              <input className={inputCls} value={it} onChange={(e) => setItems((a) => a.map((x, i) => i === idx ? e.target.value : x))} data-testid={`ppm-tpl-item-${idx}`} />
              <button onClick={() => setItems((a) => a.filter((_, i) => i !== idx))} className="text-red-500 p-2 shrink-0" data-testid={`ppm-tpl-del-${idx}`}><Trash2 className="w-4 h-4" /></button>
            </div>
          ))}
        </div>
        <Btn variant="ghost" className="mt-2" onClick={() => setItems((a) => [...a, ''])} data-testid="ppm-tpl-add"><Plus className="w-4 h-4" /> Add check</Btn>
        <div className="grid grid-cols-1 gap-2 mt-4">
          <Btn variant="primary" disabled={busy} onClick={save} data-testid="ppm-tpl-save">{busy ? <Loader2 className="w-4 h-4 animate-spin" /> : null} Save checklist</Btn>
          <Btn variant="ghost" onClick={onClose}>Cancel</Btn>
        </div>
      </div>
    </div>
  );
}

