        {(i?.reporter_email || i?.reporter_phone) && <p className="text-slate-600">{[i.reporter_email, i.reporter_phone].filter(Boolean).join(' · ')}</p>}
        {i?.created_at && <p><span className="text-slate-500">Logged:</span> {localTime(i.created_at)}</p>}
