/* ═══ COMPANY LIST ═══ */
function CompanyList({ onSelect, c, isDark, API, headers }) {
  const [companies, setCompanies] = useState([]);
  const [total, setTotal] = useState(0);
  const [search, setSearch] = useState('');
  const [typeFilter, setTypeFilter] = useState('all');
  const [showCreate, setShowCreate] = useState(false);
  const [companyKind, setCompanyKind] = useState('commercial'); // commercial | mod
  const [modBranch, setModBranch] = useState('army'); // army | raf | navy
  const [modImportSite, setModImportSite] = useState(null); // launches the guided kit-import wizard
  const [form, setForm] = useState({ name: '', sector: '', type: 'prospect', phone: '', email: '', website: '', address: '', address_line1: '', address_line2: '', address_line3: '', city: '', county: '', postcode: '', country: 'United Kingdom', company_number: '', description: '', directors: [], account_owner_id: '', account_owner_name: '' });
  const [staffList, setStaffList] = useState([]);
  const [saving, setSaving] = useState(false);
  const [aiLookup, setAiLookup] = useState(false);
  // Iter 216h268 — website-first recognition. Sales reps prefer the
  // company's actual trading website over Companies House (which
  // usually points at an accountant's office).
  const [websiteLookupUrl, setWebsiteLookupUrl] = useState('');
  const [websiteLookup, setWebsiteLookup] = useState(false);
  const [websiteLookupError, setWebsiteLookupError] = useState('');
  const [websiteSummary, setWebsiteSummary] = useState(null);

  const load = useCallback(async () => {
    try {
      const params = new URLSearchParams({ search, skip: '0', limit: '50' });
      if (typeFilter !== 'all') params.set('type', typeFilter);
      const res = await axios.get(`${API}/crm/v2/companies?${params}`, { headers: headers() });
      setCompanies(res.data.companies);
      setTotal(res.data.total);
    } catch (e) { console.error(e); }
  }, [API, headers, search, typeFilter]);

  useEffect(() => { load(); }, [load]);

  // Load selectable account managers (CRM users) and default the new
  // company's account manager to the signed-in user.
  useEffect(() => {
    (async () => {
      try {
        const [sp, me] = await Promise.all([
          axios.get(`${API}/crm/territories/staff-palette`, { headers: headers() }).catch(() => null),
          axios.get(`${API}/auth/me`, { headers: headers() }).catch(() => null),
        ]);
        let staff = sp?.data?.staff || [];
        const meData = me?.data || null;
        const meId = meData?.id;
        const meName = meData?.full_name || meData?.name || '';
        if (meId && !staff.some((s) => s.id === meId)) {
          staff = [{ id: meId, full_name: meName || 'Me', role: meData?.role || 'me' }, ...staff];
        }
        setStaffList(staff);
        setForm((prev) => (prev.account_owner_id ? prev : { ...prev, account_owner_id: meId || '', account_owner_name: meName }));
      } catch { /* silent — the field stays optional */ }
    })();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const handleCreate = async () => {
    if (!form.name.trim()) return;
    setSaving(true);
    try {
      if (companyKind === 'mod') {
        // Provision a REAL MOD site into the estate (org tagged mod_site with
        // the chosen force) — same engine as the Onboarding wizard, so it shows
        // up in the MOD estate and can have equipment imported.
        const res = await axios.post(`${API}/master-admin/mod-estate/sites`, {
          site_name: form.name,
          force: modBranch,
          address_line1: form.address_line1,
          address_line2: form.address_line2,
          address_line3: form.address_line3,
          city: form.city,
          county: form.county,
          postcode: form.postcode,
          country: form.country || 'United Kingdom',
          phone: form.phone,
          email: form.email,
        }, { headers: headers() });
        toast.success(`MOD site "${form.name}" created (${modBranch.toUpperCase()}). Let's load its equipment.`);
        setShowCreate(false);
        const newSite = res.data?.site || { id: res.data?.id, name: form.name };
        setForm({ name: '', sector: '', type: 'prospect', phone: '', email: '', website: '', address: '', address_line1: '', address_line2: '', address_line3: '', city: '', county: '', postcode: '', country: 'United Kingdom', company_number: '', description: '', directors: [], account_owner_id: form.account_owner_id, account_owner_name: form.account_owner_name });
        setCompanyKind('commercial');
        // Dummy-proof: drop the user straight into the guided kit-import wizard
        // for the site they just created — no hunting for a button.
        setModImportSite(newSite);
        setSaving(false);
        return;
      }
      const res = await axios.post(`${API}/crm/v2/companies`, form, { headers: headers() });
      onSelect(res.data.id);
    } catch (e) {
      toast.error(e?.response?.data?.detail || 'Could not create — please try again.');
      console.error(e);
    }
    setSaving(false);
  };

  const _handleNameChange = (val) => {
    setForm({ ...form, name: val });
  };

  const autoRecognize = async (query) => {
    if (!query || query.length < 3) return;
    setAiLookup(true);
    try {
      const res = await axios.post(`${API}/crm/v2/companies/auto-recognize`, { query }, { headers: headers() });
      if (res.data.success && res.data.company_info) {
        const info = res.data.company_info;
        setForm(prev => ({
          ...prev,
          address: info.address || prev.address,
          // Iter 215eq — when CH gives us the structured shape, use it.
          address_line1: info.address_line1 || info.address || prev.address_line1,
          address_line2: info.address_line2 || prev.address_line2,
          address_line3: info.address_line3 || prev.address_line3,
          phone: info.phone || prev.phone,
          website: info.website || prev.website,
          sector: info.industry || prev.sector,
          city: info.city || prev.city,
          county: info.county || prev.county,
          country: info.country || prev.country,
          postcode: info.postcode || prev.postcode,
          company_number: info.company_number || prev.company_number,
          description: info.description || prev.description,
          directors: info.directors || prev.directors,
        }));
      }
    } catch (e) { /* silent */ }
    setAiLookup(false);
  };

  // Iter 216h268 — fetch company info from a homepage URL. This is now
  // the recommended primary source (trading address + decision-makers
  // live on the website, not on the Companies House registered office).
  const autoRecognizeFromWebsite = async () => {
    const url = (websiteLookupUrl || '').trim();
    if (!url) {
      setWebsiteLookupError('Paste the prospect\u2019s website URL first');
      return;
    }
    setWebsiteLookup(true);
    setWebsiteLookupError('');
    setWebsiteSummary(null);
    try {
      const res = await axios.post(
        `${API}/crm/v2/companies/recognize-from-website`,
        { url },
        { headers: headers() },
      );
      const info = res.data?.company_info || {};
      setForm(prev => ({
        ...prev,
        name: info.name || prev.name,
        phone: info.phone || prev.phone,
        email: info.email || prev.email,
        website: info.website || url,
        address_line1: info.address_line1 || prev.address_line1,
        city: info.city || prev.city,
        county: info.county || prev.county,
        postcode: info.postcode || prev.postcode,
        country: info.country || prev.country,
        description: info.description || prev.description,
      }));
      setWebsiteSummary({
        url: res.data?.url || url,
        pagesFetched: res.data?.pages_fetched || [],
        cached: !!res.data?.cached,
        filled: Object.keys(info).filter(k => info[k] && k !== 'source_url').length,
        socialLinks: info.social_links || [],
        blocked: !!res.data?.blocked,
        note: res.data?.note || '',
      });
    } catch (e) {
      setWebsiteLookupError(e?.response?.data?.detail || 'Could not read that website');
    }
    setWebsiteLookup(false);
  };

  // CRM MOD Sites management surface (list + Import-more + Remove).
  const [showModSites, setShowModSites] = useState(false);
  const [modSites, setModSites] = useState([]);
  const [modSitesLoading, setModSitesLoading] = useState(false);
  const [modErr, setModErr] = useState('');
  const [canManageMod, setCanManageMod] = useState(false);
  const [delSite, setDelSite] = useState(null);
  const [delConfirm, setDelConfirm] = useState('');
  const [deletingSite, setDeletingSite] = useState(false);

  const openModSites = async () => {
    setShowModSites(true); setModSitesLoading(true); setModErr('');
    try {
      const r = await axios.get(`${API}/master-admin/mod-estate/site-readiness`, { headers: headers() });
      setModSites(r.data?.sites || []);
      // Loading the estate already requires owner/manager/admin access; the
      // DELETE endpoint re-checks server-side, so surfacing Remove here is safe.
      setCanManageMod(true);
    } catch (e) {
      setCanManageMod(false);
      setModErr(e?.response?.status === 403 ? 'Only owners, managers or an admin can manage MOD sites.' : 'Could not load MOD sites.');
    }
    setModSitesLoading(false);
  };

  const doDeleteModSite = async () => {
    if (!delSite) return;
    setDeletingSite(true);
    try {
      const { data } = await axios.delete(
        `${API}/master-admin/mod-estate/sites/${encodeURIComponent(delSite.id)}`,
        { headers: headers(), params: { confirm_name: delConfirm } });
      toast.success(`Removed "${data.name}" (+${data.equipment_removed} items).`);
      setDelSite(null); setDelConfirm('');
      openModSites();
    } catch (e) {
      toast.error(e?.response?.data?.detail || 'Could not remove site.');
    } finally { setDeletingSite(false); }
  };

  return (
    <>
      <ListPanel
      data-testid="crm-companies-list"
      search={{ value: search, onChange: setSearch, placeholder: 'Search companies...', testId: 'company-search' }}
      count={{ value: total, label: 'account' }}
      primaryAction={{ label: 'New Company', icon: Plus, onClick: () => setShowCreate(true), testId: 'create-company-btn' }}
      empty={{
        when: companies.length === 0,
        icon: Building2,
        title: 'No companies yet',
        primaryAction: { label: 'Create your first company', onClick: () => setShowCreate(true) },
        testId: 'crm-companies-empty',
      }}
      toolbarRight={(
        <div className="flex gap-1 items-center">
          {TYPES.map(t => (
            <button key={t} onClick={() => setTypeFilter(t)} className={`px-3 py-1.5 text-xs font-medium rounded-md transition-all ${typeFilter === t ? 'bg-[var(--color-info-ios)] text-white' : ''}`}
              style={typeFilter !== t ? { background: isDark ? 'var(--color-surface-dark-2)' : 'var(--color-neutral-100)', color: c.textMuted } : {}}
              data-testid={`company-type-filter-${t}`}>
              {t === 'all' ? 'All' : t.charAt(0).toUpperCase() + t.slice(1)}
            </button>
          ))}
          <button onClick={() => setTypeFilter('mod_site')}
            className={`ml-1 px-3 py-1.5 text-xs font-semibold rounded-md inline-flex items-center gap-1.5 border ${typeFilter === 'mod_site' ? 'bg-[var(--color-info-ios)] text-white' : ''}`}
            style={typeFilter !== 'mod_site' ? { borderColor: c.border, color: c.text } : { borderColor: 'var(--color-info-ios)' }}
            data-testid="crm-mod-sites-btn">
            <ShieldCheck size={13} /> MOD Sites
          </button>
        </div>
      )}
    >
      {companies.map(co => (
        <div key={co.id} onClick={() => onSelect(co.id)} className="flex items-center gap-4 p-4 rounded-lg border cursor-pointer transition-all hover:scale-[1.005]"
          style={{ background: isDark ? 'var(--color-surface-dark-1)' : '#fff', borderColor: isDark ? 'var(--color-surface-dark-panel)' : 'var(--color-border-alt)' }} data-testid={`company-row-${co.id}`}>
          <div className="w-10 h-10 rounded-lg flex items-center justify-center shrink-0" style={{ background: `${TYPE_COLORS[co.type] || 'var(--color-text-faint-alt)'}15` }}>
            <Building2 size={18} style={{ color: TYPE_COLORS[co.type] || 'var(--color-text-faint-alt)' }} />
          </div>
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2">
              <p className="text-sm font-semibold truncate" style={{ color: c.text }}>{co.name}</p>
              <span className="text-[9px] font-bold uppercase px-1.5 py-0.5 rounded" style={{ background: `${TYPE_COLORS[co.type] || 'var(--color-text-faint-alt)'}20`, color: TYPE_COLORS[co.type] || 'var(--color-text-faint-alt)' }}>{co.type === 'mod_site' ? (co.mod_branch || 'MOD') : co.type}</span>
              {/* Iter 216h276 — visual badge so master admins can tell
                  Pulse-tenant mirrors apart from CRM-native rows. */}
              {co.source === 'tenant_mirror' && (
                <span
                  className="text-[9px] font-bold uppercase px-1.5 py-0.5 rounded inline-flex items-center gap-0.5"
                  style={{ background: 'rgba(99,102,241,0.15)', color: 'var(--color-accent-violet)' }}
                  data-testid={`company-tenant-mirror-badge-${co.id}`}
                  title="Auto-mirrored from a Pulse tenant org. Edits here don't push back to the tenant."
                >
                  ↺ Tenant
                </span>
              )}
              {co.status === 'former' && (
                <span className="text-[9px] font-bold uppercase px-1.5 py-0.5 rounded" style={{ background: 'rgba(113,113,122,0.15)', color: 'var(--color-text-dim)' }}>Former</span>
              )}
            </div>
            <div className="flex items-center gap-3 mt-0.5">
              {co.sector && <span className="text-[11px]" style={{ color: c.textDim }}>{co.sector}</span>}
              {co.city && <span className="text-[11px]" style={{ color: c.textDim }}>{co.city}</span>}
            </div>
          </div>
          <div className="flex items-center gap-4 shrink-0 text-xs">
            <div className="text-center hidden sm:block"><p className="font-bold" style={{ color: c.text }}>{co.contact_count || 0}</p><p style={{ color: c.textDim }}>contacts</p></div>
            <div className="text-center hidden sm:block"><p className="font-bold" style={{ color: 'var(--color-info-ios)' }}>{co.opportunity_count || 0}</p><p style={{ color: c.textDim }}>deals</p></div>
            <div className="text-center hidden md:block"><p className="font-bold" style={{ color: co.open_cases > 0 ? 'var(--color-accent-amber)' : 'var(--color-success-alt)' }}>{co.open_cases || 0}</p><p style={{ color: c.textDim }}>cases</p></div>
            <ChevronRight size={16} style={{ color: c.textDim }} />
          </div>
        </div>
      ))}
      </ListPanel>

      {/* Create Dialog */}
      {showCreate && (
        <div className="fixed inset-0 z-[80] flex items-center justify-center bg-black/50 backdrop-blur-sm" onClick={() => setShowCreate(false)}>
          <div className="w-full max-w-lg mx-4 rounded-xl p-6 shadow-2xl max-h-[90vh] overflow-y-auto" style={{ background: isDark ? 'var(--color-neutral-900)' : '#fff', border: `1px solid ${c.border}` }} onClick={e => e.stopPropagation()} data-testid="create-company-dialog">
            <h2 className="text-lg font-semibold mb-4" style={{ color: c.text }}>{companyKind === 'mod' ? 'New MOD Site' : 'New Company'}</h2>
            {/* Commercial / MOD switch — MOD provisions a real estate site. */}
            <div className="flex gap-1 mb-4 p-1 rounded-lg" style={{ background: isDark ? 'var(--color-ink-alt)' : 'var(--color-neutral-100)' }} data-testid="company-kind-tabs">
              {[['commercial', 'Commercial'], ['mod', 'MOD Site']].map(([k, lbl]) => (
                <button key={k} type="button" onClick={() => setCompanyKind(k)}
                  className="flex-1 px-3 py-1.5 text-xs font-semibold rounded-md transition-all"
                  style={companyKind === k
                    ? { background: 'var(--color-info-ios)', color: '#fff' }
                    : { color: c.textMuted }}
                  data-testid={`company-kind-${k}`}>
                  {lbl}
                </button>
              ))}
            </div>
            {companyKind === 'mod' && (
              <div className="mb-4">
                <label className="text-[10px] uppercase tracking-wider font-medium" style={{ color: c.textDim }}>Service branch *</label>
                <select value={modBranch} onChange={(e) => setModBranch(e.target.value)}
                  className="w-full mt-1 px-3 py-2 text-sm rounded-md"
                  style={{ background: c.inputBg || (isDark ? 'var(--color-ink-alt)' : '#fff'), border: `1px solid ${c.border}`, color: c.text }}
                  data-testid="company-mod-branch">
                  <option value="army">Army</option>
                  <option value="raf">RAF</option>
                  <option value="navy">Navy</option>
                </select>
                <p className="text-[9px] mt-1" style={{ color: c.textDim }}>Creates a live MOD site under the {modBranch.toUpperCase()} service HQ — it appears in the MOD estate ready for equipment import.</p>
              </div>
            )}
            {/* Iter 216h268 — website-first recognition. Recommended
                primary source: paste the prospect's actual trading
                website (not Companies House) so the right typing
                (trading address, switchboard, decision-makers) flows
                through to the rest of the CRM. */}
            <div
              className="mb-4 rounded-lg p-3"
              style={{ background: isDark ? 'var(--color-surface-dark-2)' : 'var(--color-neutral-25-alt)', border: `1px solid ${c.border}`, display: companyKind === 'mod' ? 'none' : 'block' }}
              data-testid="company-website-recognise-panel"
            >
              <label className="text-[10px] uppercase tracking-wider font-medium flex items-center gap-1.5" style={{ color: c.textDim }}>
                <Globe size={11} style={{ color: 'var(--color-info-ios)' }} />
                Start from website URL <span className="text-[9px] opacity-70">(recommended)</span>
              </label>
              <div className="flex gap-2 mt-1.5">
                <input
                  type="url"
                  value={websiteLookupUrl}
                  onChange={e => { setWebsiteLookupUrl(e.target.value); setWebsiteLookupError(''); }}
                  placeholder="https://acmegym.co.uk"
                  className="flex-1 px-3 py-2 text-sm rounded-md"
                  style={{ background: c.inputBg || (isDark ? 'var(--color-ink-alt)' : '#fff'), border: `1px solid ${c.border}`, color: c.text }}
                  data-testid="company-website-url-input"
                  onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); autoRecognizeFromWebsite(); } }}
                />
                <button
                  type="button"
                  onClick={autoRecognizeFromWebsite}
                  disabled={websiteLookup || !websiteLookupUrl.trim()}
                  className="px-3 py-2 text-xs font-medium rounded-md flex items-center gap-1.5 transition-all disabled:opacity-40 shrink-0"
                  style={{ background: 'var(--color-info-ios)', color: '#fff' }}
                  data-testid="company-website-lookup-btn"
                >
                  {websiteLookup ? <Loader2 size={12} className="animate-spin" /> : <Globe size={12} />}
                  {websiteLookup ? 'Reading…' : 'Fetch'}
                </button>
              </div>
              <p className="text-[9px] mt-1" style={{ color: c.textDim }}>
                We&apos;ll pull name, phone, email, address, description &amp; social links straight from the company&apos;s site. Cached for 24h.
              </p>
              {websiteLookupError && (
                <p className="text-[10px] mt-1.5" style={{ color: 'var(--color-danger-alt)' }} data-testid="company-website-lookup-error">{websiteLookupError}</p>
              )}
              {websiteSummary && (
                <div className="mt-2 text-[10px] flex items-center gap-2 flex-wrap" style={{ color: c.textDim }} data-testid="company-website-lookup-summary">
                  <span style={{ color: 'var(--color-success-alt)' }}>{websiteSummary.filled} fields filled</span>
                  <span>·</span>
                  <span>{websiteSummary.pagesFetched.length} page{websiteSummary.pagesFetched.length === 1 ? '' : 's'} read{websiteSummary.cached ? ' (cached)' : ''}</span>
                  {websiteSummary.socialLinks.length > 0 && (
                    <>
                      <span>·</span>
                      <span>{websiteSummary.socialLinks.length} social link{websiteSummary.socialLinks.length === 1 ? '' : 's'}</span>
                    </>
                  )}
                </div>
              )}
              {websiteSummary?.note && (
                <p className="text-[10px] mt-1.5 flex items-start gap-1" style={{ color: 'var(--color-warning-alt, #b45309)' }} data-testid="company-website-lookup-note">
                  <AlertTriangle size={11} className="mt-0.5 shrink-0" /> {websiteSummary.note}
                </p>
              )}
            </div>
            {aiLookup && (
              <div className="flex items-center gap-2 mb-3 px-3 py-2 rounded-md" style={{ background: 'var(--color-info-ios)08', border: '1px solid var(--color-info-ios)20' }}>
                <Loader2 size={14} className="animate-spin" style={{ color: 'var(--color-info-ios)' }} />
                <span className="text-xs" style={{ color: 'var(--color-info-ios)' }}>AI looking up company details...</span>
              </div>
            )}
            <div className="grid grid-cols-2 gap-3">
              <div className="col-span-2">
                <label className="text-[10px] uppercase tracking-wider font-medium flex items-center gap-1" style={{ color: c.textDim }}>
                  Company Name * <Sparkles size={10} style={{ color: 'var(--color-info-ios)' }} />
                </label>
                <div className="flex gap-2 mt-1">
                  <div className="flex-1">
                    <CompanyAutocomplete
                      value={form.name}
                      onChange={(v) => setForm(prev => ({ ...prev, name: v }))}
                      onPick={(picked) => {
                        // Iter 215et — pre-fill the CRM company form when
                        // the user picks a suggestion. CH picks set
                        // company_number + structured address; internal
                        // (existing-CRM) picks pull the full record.
                        const isCH = picked.source === 'companies_house';
                        setForm(prev => ({
                          ...prev,
                          name: (isCH ? picked.company_name : picked.name) || prev.name,
                          company_number: picked.company_number || prev.company_number,
                          phone: isCH ? prev.phone : (picked.phone || prev.phone),
                          address_line1: picked.address_line1 || prev.address_line1,
                          address_line2: picked.address_line2 || prev.address_line2,
                          address_line3: picked.address_line3 || prev.address_line3,
                          city: picked.city || prev.city,
                          county: picked.county || prev.county,
                          postcode: picked.postcode || prev.postcode,
                          country: picked.country || prev.country,
                        }));
                      }}
                      testIdPrefix="company-name-autocomplete"
                      includeInternal={false}
                      placeholder="Or type a name to search Companies House (UK)"
                      inputClassName="text-sm"
                    />
                  </div>
                  <button type="button" onClick={() => autoRecognize(form.name)} disabled={aiLookup || form.name.length < 3}
                    className="px-3 py-2 text-xs font-medium rounded-md flex items-center gap-1.5 transition-all disabled:opacity-40 shrink-0"
                    style={{ background: 'var(--color-info-ios)', color: '#fff' }} data-testid="company-lookup-btn">
                    {aiLookup ? <Loader2 size={12} className="animate-spin" /> : <Sparkles size={12} />}
                    {aiLookup ? 'Searching...' : 'AI fill'}
                  </button>
                </div>
                <p className="text-[9px] mt-0.5" style={{ color: c.textDim }}>Pick from the dropdown for instant fill, or click "AI fill" for fuzzy AI-powered enrichment</p>
              </div>
              <div className="col-span-2">
                <label className="text-[10px] uppercase tracking-wider font-medium" style={{ color: c.textDim }}>Account Manager</label>
                <select
                  value={form.account_owner_id || ''}
                  onChange={(e) => {
                    const s = staffList.find((x) => x.id === e.target.value);
                    setForm({ ...form, account_owner_id: e.target.value, account_owner_name: s ? s.full_name : '' });
                  }}
                  className="w-full mt-1 px-3 py-2 text-sm rounded-md"
                  style={{ background: c.inputBg || (isDark ? 'var(--color-ink-alt)' : '#fff'), border: `1px solid ${c.border}`, color: c.text }}
                  data-testid="company-account-manager-select"
                >
                  <option value="">Unassigned</option>
                  {staffList.map((s) => (
                    <option key={s.id} value={s.id}>{s.full_name}{s.role && s.role !== 'me' ? ` · ${s.role}` : ''}</option>
                  ))}
                </select>
                <p className="text-[9px] mt-0.5" style={{ color: c.textDim }}>Who owns this account. Defaults to you — change it to assign a colleague.</p>
              </div>
              {[
                { key: 'company_number', label: 'Company Number', readOnly: true },
                // Iter 216h195 — Wave 2 dropdown audit: sector is now a
                // curated UK fitness-industry taxonomy (Gym Chain,
                // Boutique Studio, Hotel Health Club, etc.) so reports
                // can slice the pipeline by segment without dirty data.
                { key: 'sector', label: 'Sector / Industry', type: 'select', options: FITNESS_SECTOR_OPTIONS },
                { key: 'type', label: 'Type', type: 'select', options: ['prospect', 'customer', 'partner'] },
                { key: 'phone', label: 'Phone' },
                { key: 'email', label: 'Email' },
                { key: 'website', label: 'Website', span: 2 },
                { key: 'address_line1', label: 'Address 1', span: 2 },
                { key: 'address_line2', label: 'Address 2', span: 2 },
                { key: 'address_line3', label: 'Address 3', span: 2 },
                { key: 'postcode', label: 'Post code', lookupPostcode: true },
                { key: 'city', label: 'City' },
                // County / Country use datalist so users get a typeahead
                // list yet can still enter bespoke values (overseas
                // territories, edge cases) without being blocked.
                { key: 'county', label: 'County', datalist: 'crm-county-presets' },
                { key: 'country', label: 'Country', datalist: 'crm-country-presets', lookupCountry: true },
              ].map(f => (
                <div key={f.key} className={f.span === 2 ? 'col-span-2' : ''}>
                  <label className="text-[10px] uppercase tracking-wider font-medium" style={{ color: c.textDim }}>{f.label}</label>
                  {f.type === 'select' ? (
                    <select value={form[f.key]} onChange={e => setForm({...form, [f.key]: e.target.value})} className="w-full mt-1 px-3 py-2 text-sm rounded-md" style={{ background: c.inputBg || (isDark ? 'var(--color-ink-alt)' : '#fff'), border: `1px solid ${c.border}`, color: c.text }}>
                      {f.options.map(o => <option key={o} value={o}>{o.charAt(0).toUpperCase() + o.slice(1)}</option>)}
                    </select>
                  ) : (
                    <input
                      value={form[f.key] || ''}
                      readOnly={f.readOnly}
                      list={f.datalist}
                      onChange={e => setForm({...form, [f.key]: e.target.value})}
                      onBlur={(f.lookupPostcode || f.lookupCountry) ? async (e) => {
                        // Iter 215eq — auto-fill city/county/country from
                        // postcodes.io (UK) / Zippopotam.us (international,
                        // routed by the Country field). Re-runs when either
                        // the postcode OR the country is committed, so an
                        // overseas postcode still resolves regardless of the
                        // order the fields are filled. Doesn't clobber typed
                        // City/County values.
                        const pc = (f.lookupPostcode ? (e.target.value || '') : (form.postcode || '')).trim();
                        const ctry = (f.lookupCountry ? (e.target.value || '') : (form.country || '')).trim();
                        if (!pc || pc.replace(/\s+/g, '').length < 3) return;
                        try {
                          const r = await axios.get(`${API}/integrations/postcode/lookup`, { headers: headers(), params: { postcode: pc, country: ctry || undefined } });
                          if (r.data?.found) {
                            setForm(prev => ({
                              ...prev,
                              postcode: r.data.postcode || prev.postcode,
                              city: prev.city || r.data.city || '',
                              county: prev.county || r.data.county || '',
                              country: prev.country || r.data.country || '',
                            }));
                          }
                        } catch { /* silent */ }
                      } : undefined}
                      className="w-full mt-1 px-3 py-2 text-sm rounded-md"
                      style={{ background: f.readOnly ? (isDark ? '#111' : 'var(--color-neutral-25-alt)') : (c.inputBg || (isDark ? 'var(--color-ink-alt)' : '#fff')), border: `1px solid ${c.border}`, color: c.text, opacity: f.readOnly ? 0.8 : 1 }}
                      data-testid={`company-field-${f.key}`}
                    />
                  )}
                </div>
              ))}
              {/* Iter 216h195 — shared datalists for County / Country
                  on this form. Rendered once, referenced by `list=` on
                  individual inputs above. */}
              <datalist id="crm-county-presets">
                {UK_COUNTIES.map((c) => <option key={c} value={c} />)}
              </datalist>
              <datalist id="crm-country-presets">
                {COUNTRIES.map((c) => <option key={c} value={c} />)}
              </datalist>
              {form.directors?.length > 0 && (
                <div className="col-span-2">
                  <label className="text-[10px] uppercase tracking-wider font-medium flex items-center gap-1" style={{ color: c.textDim }}>
                    Directors <Shield size={10} style={{ color: 'var(--color-success-alt)' }} />
                  </label>
                  <div className="flex flex-wrap gap-1.5 mt-1">
                    {form.directors.map((d, i) => (
                      <span key={i} className="px-2 py-1 text-xs rounded-md" style={{ background: isDark ? 'var(--color-navy-900)' : 'var(--color-info-bg)', color: 'var(--color-info-ios)', border: `1px solid ${isDark ? 'var(--color-navy-800)' : 'var(--color-blue-200)'}` }}>{d}</span>
                    ))}
                  </div>
                </div>
              )}
            </div>
            <div className="flex gap-2 mt-5 justify-end">
              <button onClick={() => setShowCreate(false)} className="px-4 py-2 text-sm rounded-md" style={{ color: c.textMuted }}>Cancel</button>
              <button onClick={handleCreate} disabled={saving || !form.name.trim()} className="px-4 py-2 bg-[var(--color-info-ios)] text-white text-sm font-medium rounded-md hover:bg-[var(--color-brand-blue-deep)] disabled:opacity-50" data-testid="company-create-submit">
                {saving ? (companyKind === 'mod' ? 'Creating site…' : 'Creating...') : (companyKind === 'mod' ? 'Create MOD Site' : 'Create Company')}
              </button>
            </div>
          </div>
        </div>
      )}

      {modImportSite && (
        <AIKitImportModal
          site={modImportSite}
          headers={headers()}
          guided
          onClose={() => setModImportSite(null)}
          onImported={() => { if (showModSites) openModSites(); }}
        />
      )}

      {showModSites && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4" style={{ background: 'rgba(0,0,0,0.6)' }} data-testid="crm-mod-sites-modal" onClick={() => setShowModSites(false)}>
          <div className="w-full max-w-2xl rounded-2xl shadow-2xl max-h-[85vh] flex flex-col" style={{ background: isDark ? 'var(--color-neutral-900)' : '#fff', border: `1px solid ${c.border}` }} onClick={e => e.stopPropagation()}>
            <div className="flex items-center justify-between px-5 py-4 border-b" style={{ borderColor: c.border }}>
              <div className="flex items-center gap-2">
                <ShieldCheck size={18} style={{ color: 'var(--color-info-ios)' }} />
                <h3 className="text-base font-bold" style={{ color: c.text }}>MOD Sites</h3>
              </div>
              <button onClick={() => setShowModSites(false)} className="p-1.5 rounded-md" style={{ color: c.textDim }} data-testid="crm-mod-sites-close"><X size={16} /></button>
            </div>
            <div className="flex-1 overflow-y-auto p-4 space-y-2">
              {modSitesLoading ? (
                <div className="py-10 text-center text-sm" style={{ color: c.textDim }}><Loader2 size={16} className="animate-spin inline mr-2" /> Loading sites…</div>
              ) : modErr ? (
                <div className="py-10 text-center text-sm" style={{ color: 'var(--color-warning)' }} data-testid="crm-mod-sites-error">{modErr}</div>
              ) : modSites.length === 0 ? (
                <div className="py-10 text-center text-sm" style={{ color: c.textDim }}>No MOD sites yet. Create one via New Company → MOD Site.</div>
              ) : modSites.map(s => (
                <div key={s.id} className="flex items-center gap-3 p-3 rounded-lg border" style={{ borderColor: c.border, background: isDark ? 'var(--color-surface-dark-1)' : 'var(--color-neutral-50)' }} data-testid={`crm-mod-site-row-${s.id}`}>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-semibold truncate" style={{ color: c.text }}>{s.name}</p>
                    <p className="text-[11px]" style={{ color: c.textDim }}>
                      {(s.force || '').toUpperCase() || '—'} · {s.steps?.equipment?.count ?? 0} items{s.fully_ready ? ' · ready' : ''}
                    </p>
                  </div>
                  <button onClick={() => setModImportSite(s)} className="px-2.5 py-1.5 text-xs font-semibold rounded-md inline-flex items-center gap-1.5 border" style={{ borderColor: c.border, color: c.text }} data-testid={`crm-mod-site-import-${s.id}`}>
                    <Upload size={12} /> Import more
                  </button>
                  {canManageMod && (
                    <button onClick={() => { setDelSite(s); setDelConfirm(''); }} className="px-2.5 py-1.5 text-xs font-semibold rounded-md inline-flex items-center gap-1.5 border text-red-600 border-red-200 hover:bg-red-50" data-testid={`crm-mod-site-delete-${s.id}`}>
                      <Trash2 size={12} /> Remove
                    </button>
                  )}
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {delSite && (
        <div className="fixed inset-0 z-[130] flex items-center justify-center p-4" style={{ background: 'rgba(0,0,0,0.7)' }} data-testid="crm-mod-site-delete-modal" onClick={() => !deletingSite && setDelSite(null)}>
          <div className="w-full max-w-md rounded-2xl p-5 shadow-2xl" style={{ background: isDark ? 'var(--color-neutral-900)' : '#fff', border: `1px solid ${c.border}` }} onClick={e => e.stopPropagation()}>
            <h3 className="text-base font-extrabold mb-2" style={{ color: c.text }}>Remove MOD site</h3>
            <p className="text-xs mb-3" style={{ color: c.textDim }}>Permanently removes <b>{delSite.name}</b> and all its equipment, staff logins and suppliers. This can’t be undone.</p>
            <label className="text-[11px] font-semibold" style={{ color: c.textDim }}>Type the site name to confirm</label>
            <input value={delConfirm} onChange={e => setDelConfirm(e.target.value)} placeholder={delSite.name} autoFocus
              className="w-full mt-1 px-3 py-2 text-sm rounded-md border" style={{ borderColor: c.border, background: isDark ? 'var(--color-ink-alt)' : '#fff', color: c.text }}
              data-testid="crm-mod-site-delete-input" />
            <div className="flex justify-end gap-2 mt-4">
              <button onClick={() => setDelSite(null)} disabled={deletingSite} className="px-3 py-1.5 text-xs font-semibold" style={{ color: c.textMuted }}>Cancel</button>
              <button onClick={doDeleteModSite} disabled={deletingSite || delConfirm.trim().toLowerCase() !== (delSite.name || '').trim().toLowerCase()}
                className="px-3 py-1.5 text-xs font-bold rounded-md bg-red-600 text-white disabled:opacity-40 inline-flex items-center gap-1.5" data-testid="crm-mod-site-delete-confirm">
                {deletingSite ? <Loader2 size={13} className="animate-spin" /> : <Trash2 size={13} />} Remove site
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

/* ═══ COMPANY FILE TAB (Drawings / Surveys / Invoices) ═══ */
function AssetReconcilePanel({ companyId, API, headers, c, isDark }) {
  const [data, setData] = useState(null);
  const [linking, setLinking] = useState('');
  const [promoting, setPromoting] = useState('');

  const load = React.useCallback(async () => {
    try {
      const res = await axios.get(`${API}/crm/v2/companies/${companyId}/asset-reconciliation`, { headers: headers() });
      setData(res.data);
    } catch (e) { setData(null); }
  }, [API, headers, companyId]);

  React.useEffect(() => { load(); }, [load]);

  if (!data) return null;
  const { duplicates = [], crm_only = [], register_count = 0, already_linked = 0, unlinked_register_count = 0 } = data;
  const border = isDark ? 'var(--color-surface-dark-panel)' : 'var(--color-border-alt)';

  const linkOne = async (assetId, equipmentId) => {
    setLinking(assetId);
    try {
      await axios.post(`${API}/crm/v2/assets/${assetId}/link-equipment`, { equipment_id: equipmentId }, { headers: headers() });
      toast.success('Linked to the register — no more duplicate');
      await load();
    } catch (e) { toast.error('Could not link asset'); }
    setLinking('');
  };

  const promoteOne = async (assetId) => {
    setPromoting(assetId);
    try {
      await axios.post(`${API}/crm/v2/assets/${assetId}/promote-to-register`, {}, { headers: headers() });
      toast.success('Promoted to the Operations register');
      await load();
    } catch (e) {
      toast.error(e?.response?.data?.detail || 'Could not promote asset');
    }
    setPromoting('');
  };

  const clean = duplicates.length === 0 && crm_only.length === 0;
  return (
    <div className="rounded-lg border p-3 mb-1" style={{ borderColor: border, background: isDark ? 'var(--color-surface-dark-1)' : 'var(--color-neutral-50)' }} data-testid="asset-reconcile-panel">
      <div className="flex items-center gap-2 mb-2">
        <Wrench size={14} style={{ color: 'var(--color-info-ios)' }} />
        <span className="text-xs font-semibold" style={{ color: c.text }}>Equipment source of truth</span>
        <span className="text-[10px] px-2 py-0.5 rounded-full" style={{ background: 'var(--color-info-ios)', color: '#fff' }}>Operations register: {register_count}</span>
        {already_linked > 0 && <span className="text-[10px]" style={{ color: c.textDim }}>· {already_linked} linked</span>}
      </div>

      {clean ? (
        <p className="text-[11px]" style={{ color: c.textDim }} data-testid="asset-reconcile-clean">No duplicate CRM assets — the Operations/Service register is the single source of truth{unlinked_register_count ? ` (${unlinked_register_count} register item(s) here)` : ''}.</p>
      ) : (
        <div className="space-y-2">
          {duplicates.length > 0 && (
            <div data-testid="asset-reconcile-duplicates">
              <p className="text-[11px] font-semibold mb-1" style={{ color: 'var(--color-accent-amber)' }}>{duplicates.length} possible duplicate(s) of register equipment — link to keep one source:</p>
              {duplicates.map((d) => (
                <div key={d.crm_asset.id} className="flex items-center gap-2 text-[11px] py-1 border-t" style={{ borderColor: border }} data-testid={`asset-dup-${d.crm_asset.id}`}>
                  <span className="flex-1 min-w-0 truncate" style={{ color: c.text }}>{d.crm_asset.name} <span style={{ color: c.textDim }}>(S/N {d.crm_asset.serial_number || 'N/A'} · matched by {d.matched_via})</span></span>
                  <button onClick={() => linkOne(d.crm_asset.id, d.register.id)} disabled={linking === d.crm_asset.id}
                    className="px-2 py-1 rounded-md font-semibold shrink-0" style={{ background: 'var(--color-info-ios)', color: '#fff' }}
                    data-testid={`asset-link-${d.crm_asset.id}`}>{linking === d.crm_asset.id ? '…' : 'Link'}</button>
                </div>
              ))}
            </div>
          )}
          {crm_only.length > 0 && (
            <div data-testid="asset-reconcile-crmonly">
              <p className="text-[11px] font-semibold mb-1" style={{ color: c.textDim }}>{crm_only.length} CRM-only asset(s) not in the register — promote to make the register the single source of truth:</p>
              {crm_only.map((a) => (
                <div key={a.id} className="flex items-center gap-2 text-[11px] py-1 border-t" style={{ borderColor: border }} data-testid={`asset-crmonly-${a.id}`}>
                  <span className="flex-1 min-w-0 truncate" style={{ color: c.text }}>{a.name} <span style={{ color: c.textDim }}>(S/N {a.serial_number || 'N/A'}{a.status ? ` · ${a.status}` : ''})</span></span>
                  <button onClick={() => promoteOne(a.id)} disabled={promoting === a.id}
                    className="px-2 py-1 rounded-md font-semibold shrink-0 inline-flex items-center gap-1" style={{ background: 'var(--color-success-ios, #34c759)', color: '#fff' }}
                    data-testid={`asset-promote-${a.id}`}>
                    {promoting === a.id ? '…' : (<><Plus size={11} /> Promote to register</>)}
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function ServiceActivityTab({ companyId, API, headers, c, isDark }) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);

  const load = React.useCallback(async () => {
    setLoading(true);
    try {
      const res = await axios.get(`${API}/crm/v2/companies/${companyId}/service-activity`, { headers: headers() });
      setData(res.data);
    } catch (e) { console.error(e); setData(null); }
    setLoading(false);
  }, [API, headers, companyId]);

  React.useEffect(() => { load(); }, [load]);

  const border = isDark ? 'var(--color-surface-dark-panel)' : 'var(--color-border-alt)';
  const fmtDate = (s) => { try { return new Date(s).toLocaleString('en-GB', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }); } catch { return s; } };
  const fmtAgo = (s) => {
    try {
      const mins = Math.round((Date.now() - new Date(s).getTime()) / 60000);
      if (mins < 1) return 'just now';
      if (mins < 60) return `${mins} min ago`;
      const h = Math.round(mins / 60);
      if (h < 24) return `${h}h ago`;
      return `${Math.round(h / 24)}d ago`;
    } catch { return ''; }
  };
  const PRIORITY = { p1: 'var(--color-danger-alt)', p2: 'var(--color-accent-amber)', p3: 'var(--color-info-ios)', p4: 'var(--color-text-faint-alt)' };
  const statusChip = (eng) => {
    if (eng.on_site) return { label: 'On site', bg: 'var(--color-success-alt)' };
    if (eng.en_route) return { label: 'En route', bg: 'var(--color-accent-amber)' };
    return { label: 'Assigned', bg: 'var(--color-info-ios)' };
  };

  if (loading) return <div className="py-10 text-center" data-testid="company-service-loading"><Loader2 size={20} className="animate-spin mx-auto" style={{ color: c.textDim }} /></div>;
  if (!data) return <p className="text-sm text-center py-6" style={{ color: c.textDim }}>Couldn't load service activity.</p>;

  const { open_cases = [], engineers = [], next_ppm, last_visit, linked, open_case_count } = data;

  return (
    <div className="space-y-5" data-testid="company-service-tab">
      {/* Summary tiles */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        {[
          { label: 'Open cases', value: open_case_count, icon: Wrench },
          { label: 'Engineers active', value: engineers.length, icon: Users },
          { label: 'Next PPM', value: next_ppm?.next_due_date ? new Date(next_ppm.next_due_date).toLocaleDateString('en-GB') : '—', icon: Calendar },
          { label: 'Last visit', value: last_visit?.closed_at ? new Date(last_visit.closed_at).toLocaleDateString('en-GB') : '—', icon: CheckCircle },
        ].map((t, i) => (
          <div key={i} className="p-3 rounded-lg border" style={{ background: isDark ? 'var(--color-surface-dark-1)' : '#fff', borderColor: border }} data-testid={`service-tile-${i}`}>
            <t.icon size={15} style={{ color: 'var(--color-info-ios)' }} />
            <p className="text-lg font-semibold mt-1" style={{ color: c.text }}>{t.value}</p>
            <p className="text-[11px]" style={{ color: c.textDim }}>{t.label}</p>
          </div>
        ))}
      </div>

      {!linked && (
        <div className="flex items-start gap-2 p-3 rounded-md text-xs" style={{ background: 'var(--color-warning-bg, #FEF3C7)', color: 'var(--color-warning, #92400E)' }} data-testid="service-not-linked">
          <AlertTriangle size={14} className="mt-0.5 shrink-0" />
          <span>This account isn't formally linked to a Service Desk customer yet — showing matches by name. Linking happens automatically when a maintenance contract is activated or an engineer saves the customer.</span>
        </div>
      )}

      {/* Where are the engineers */}
      <div>
        <h3 className="text-sm font-semibold mb-2 flex items-center gap-1.5" style={{ color: c.text }}><Navigation size={14} style={{ color: 'var(--color-info-ios)' }} /> Where engineers are</h3>
        {engineers.length === 0 ? (
          <p className="text-sm py-4 text-center rounded-md border border-dashed" style={{ color: c.textDim, borderColor: border }}>No engineers currently assigned to this account.</p>
        ) : (
          <div className="space-y-2">
            {engineers.map((eng) => {
              const chip = statusChip(eng);
              return (
                <div key={eng.id} className="p-3 rounded-md border" style={{ borderColor: border, background: isDark ? 'var(--color-surface-dark-1)' : '#fff' }} data-testid={`service-engineer-${eng.id}`}>
                  <div className="flex items-center gap-3">
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <p className="text-sm font-medium truncate" style={{ color: c.text }}>{eng.name}</p>
                        <span className="text-[10px] font-semibold px-2 py-0.5 rounded-full text-white" style={{ background: chip.bg }}>{chip.label}</span>
                      </div>
                      {eng.current_case && (
                        <p className="text-[11px] mt-0.5" style={{ color: c.textDim }}>
                          On {eng.current_case.reference || 'case'}{eng.current_case.site_name ? ` · ${eng.current_case.site_name}` : ''}{eng.current_case.scheduled_at ? ` · ${fmtDate(eng.current_case.scheduled_at)}` : ''}
                        </p>
                      )}
                      {eng.last_location?.recorded_at && (
                        <p className="text-[11px] flex items-center gap-1 mt-0.5" style={{ color: c.textDim }}>
                          <MapPin size={10} /> Location updated {fmtAgo(eng.last_location.recorded_at)}
                        </p>
                      )}
                    </div>
                    {eng.phone && (
                      <a href={`tel:${eng.phone}`} className="p-1.5 rounded-md shrink-0" style={{ color: 'var(--color-info-ios)' }} data-testid={`service-engineer-call-${eng.id}`}><Phone size={14} /></a>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Open service cases */}
      <div>
        <h3 className="text-sm font-semibold mb-2 flex items-center gap-1.5" style={{ color: c.text }}><Wrench size={14} style={{ color: 'var(--color-info-ios)' }} /> Open service cases</h3>
        {open_cases.length === 0 ? (
          <p className="text-sm py-4 text-center rounded-md border border-dashed" style={{ color: c.textDim, borderColor: border }}>No open service cases.</p>
        ) : (
          <div className="space-y-2">
            {open_cases.map((cs) => (
              <div key={cs.id} className="flex items-center gap-3 p-3 rounded-md border" style={{ borderColor: border, background: isDark ? 'var(--color-surface-dark-1)' : '#fff' }} data-testid={`service-case-${cs.id}`}>
                <span className="w-2 h-2 rounded-full shrink-0" style={{ background: PRIORITY[cs.priority] || 'var(--color-text-faint-alt)' }} />
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium truncate" style={{ color: c.text }}>{cs.reference ? `${cs.reference}: ` : ''}{cs.title || 'Service case'}</p>
                  <p className="text-[11px]" style={{ color: c.textDim }}>
                    {(cs.status || '').replace(/_/g, ' ')}{cs.assigned_engineer_name ? ` · ${cs.assigned_engineer_name}` : ' · unassigned'}{cs.site_name ? ` · ${cs.site_name}` : ''}{cs.scheduled_at ? ` · ${fmtDate(cs.scheduled_at)}` : ''}
                  </p>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {next_ppm?.next_due_date && (
        <div className="flex items-center gap-2 p-3 rounded-md text-xs border" style={{ borderColor: border, color: c.textDim }} data-testid="service-next-ppm">
          <Clock size={13} style={{ color: 'var(--color-info-ios)' }} />
          Next preventive maintenance due <strong style={{ color: c.text }}>{new Date(next_ppm.next_due_date).toLocaleDateString('en-GB')}</strong>
          {next_ppm.visits_per_year ? ` · ${next_ppm.visits_per_year} visit(s)/year` : ''}{next_ppm.tier ? ` · ${next_ppm.tier}` : ''}
        </div>
      )}
    </div>
  );
}

function CompanyFileTab({ companyId, category, label, accept, API, headers, c, isDark }) {
  const [files, setFiles] = useState([]);
  const [uploading, setUploading] = useState(false);
  const fileRef = React.useRef(null);

  const load = React.useCallback(async () => {
    try {
      const res = await axios.get(`${API}/crm/v2/companies/${companyId}/files?category=${category}`, { headers: headers() });
      setFiles(res.data.files);
    } catch (e) { console.error(e); }
  }, [API, headers, companyId, category]);

  React.useEffect(() => { load(); }, [load]);

  const handleUpload = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    try {
      const formData = new FormData();
      formData.append('file', file);
      await axios.post(`${API}/crm/v2/companies/${companyId}/files?category=${category}`, formData,
        { headers: { ...headers(), 'Content-Type': 'multipart/form-data' } });
      load();
    } catch (e) { console.error(e); }
    setUploading(false);
    if (fileRef.current) fileRef.current.value = '';
  };

  const handleDelete = async (fileId) => {
    try { await axios.delete(`${API}/crm/v2/companies/${companyId}/files/${fileId}`, { headers: headers() }); load(); } catch (e) { console.error(e); }
  };

  const formatSize = (b) => b < 1024 ? `${b} B` : b < 1048576 ? `${(b/1024).toFixed(1)} KB` : `${(b/1048576).toFixed(1)} MB`;

  return (
    <div data-testid={`company-files-${category}`}>
      <div className="flex items-center justify-between mb-3">
        <h3 className="text-sm font-semibold" style={{ color: c.text }}>{label}</h3>
        <div>
          <input type="file" accept={accept} onChange={handleUpload} ref={fileRef} className="hidden" id={`upload-${category}`} />
          <label htmlFor={`upload-${category}`} className="inline-flex items-center gap-1.5 px-3 py-1.5 bg-[var(--color-info-ios)] text-white text-xs font-medium rounded-md cursor-pointer hover:bg-[var(--color-brand-blue-deep)]">
            <Upload size={12} /> {uploading ? 'Uploading...' : 'Upload'}
          </label>
        </div>
      </div>
      {files.length > 0 ? (
        <div className="space-y-2">
          {files.map(f => (
            <div key={f.id} className="flex items-center gap-3 p-3 rounded-md border" style={{ borderColor: isDark ? 'var(--color-surface-dark-panel)' : 'var(--color-border-alt)' }}>
              <FileText size={16} style={{ color: category === 'drawings' ? 'var(--color-info-ios)' : category === 'surveys' ? 'var(--color-success-alt)' : 'var(--color-warning)' }} />
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium truncate" style={{ color: c.text }}>{f.original_filename}</p>
                <p className="text-[11px]" style={{ color: c.textDim }}>{formatSize(f.size)} &middot; {f.uploaded_by_name} &middot; {new Date(f.created_at).toLocaleDateString('en-GB')}</p>
              </div>
              <a href={`${API}/crm/v2/companies/${companyId}/files/${f.id}/download`} className="p-1.5 rounded-md" style={{ color: 'var(--color-info-ios)' }}>
                <Download size={14} />
              </a>
              <button onClick={() => handleDelete(f.id)} className="p-1.5 rounded-md" style={{ color: c.textDim }}>
                <Trash2 size={14} />
              </button>
            </div>
          ))}
        </div>
      ) : (
        <div className="text-center py-8 border border-dashed rounded-md" style={{ borderColor: isDark ? 'var(--color-surface-dark-panel)' : 'var(--color-border-alt)' }}>
          <Upload size={24} className="mx-auto mb-2" style={{ color: c.textDim }} />
          <p className="text-xs" style={{ color: c.textDim }}>No {label.toLowerCase()} uploaded yet</p>
        </div>
      )}
    </div>
  );
}

/* ═══ PORTAL EQUIPMENT TAB ═══ */
function PortalEquipmentTab({ companyId, API, headers, c, isDark }) {
  const [equipment, setEquipment] = useState([]);
  const [loading, setLoading] = useState(true);

  React.useEffect(() => {
    (async () => {
      try {
        const res = await axios.get(`${API}/crm/v2/companies/${companyId}/portal-equipment`, { headers: headers() });
        setEquipment(res.data.equipment || []);
      } catch (e) { console.error(e); }
      setLoading(false);
    })();
  }, [API, headers, companyId]);

  if (loading) return <div className="flex justify-center py-8"><div className="w-5 h-5 border-2 border-[var(--color-info-ios)] border-t-transparent rounded-full animate-spin" /></div>;

  return (
    <div data-testid="company-portal-equipment">
      <h3 className="text-sm font-semibold mb-3" style={{ color: c.text }}>Operations Portal Equipment</h3>
      {equipment.length > 0 ? (
        <div className="space-y-2">
          {equipment.map((eq, i) => (
            <div key={eq.id || i} className="flex items-center gap-3 p-3 rounded-md border" style={{ borderColor: isDark ? 'var(--color-surface-dark-panel)' : 'var(--color-border-alt)' }}>
              <Shield size={16} style={{ color: 'var(--color-accent-magenta)' }} />
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium truncate" style={{ color: c.text }}>{eq.name || eq.equipment_name || 'Equipment'}</p>
                <p className="text-[11px]" style={{ color: c.textDim }}>
                  {eq.model_code || eq.model || ''} {eq.serial_number ? `| S/N: ${eq.serial_number}` : ''} {eq.location ? `| ${eq.location}` : ''}
                </p>
              </div>
              <span className="text-[9px] font-bold uppercase px-1.5 py-0.5 rounded" style={{ background: 'var(--color-accent-magenta)20', color: 'var(--color-accent-magenta)' }}>
                {eq.status || 'Active'}
              </span>
            </div>
          ))}
        </div>
      ) : (
        <div className="text-center py-8">
          <Shield size={32} className="mx-auto mb-2" style={{ color: c.textDim }} />
          <p className="text-sm" style={{ color: c.textDim }}>No equipment found in Operations Portal for this company</p>
          <p className="text-xs mt-1" style={{ color: c.textDim }}>Equipment is matched by company name</p>
        </div>
      )}
    </div>
  );
}


/* ═══ SITES & EQUIPMENT TAB (Phase 1 of Ops↔CRM↔ServiceDesk link) ═══
   Iter 216h196 — Lee's ask: Pulse Fitness HQ wants its child sites
   (iGym Carshalton, iGym Congleton) surfaced inside CRM with each
   piece of equipment showing its live contract-coverage badge, plus a
   one-click "Add coverage" action to attach equipment to a new or
   existing aftersales contract. Backend endpoint:
     GET  /api/crm/v2/companies/{id}/sites-and-equipment
     POST /api/crm/v2/companies/{id}/equipment-coverage
     POST /api/crm/v2/companies/{id}/link-organization
   The link-organization endpoint is used when the company isn't
   auto-linked by name (returns linked_via='unlinked' from the GET). */
function SitesAndEquipmentTab({ companyId, companyName, API, headers, c, isDark, children }) {
  const [data, setData] = useState(null);
  const [newLoc, setNewLoc] = useState('');
  const [locMsg, setLocMsg] = useState('');
  const [loading, setLoading] = useState(true);
  const [expanded, setExpanded] = useState({});
  const [coverageModal, setCoverageModal] = useState(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const r = await axios.get(`${API}/crm/v2/companies/${companyId}/sites-and-equipment`, { headers: headers() });
      setData(r.data);
      if (r.data?.sites?.length) {
        setExpanded((prev) => ({ ...prev, [r.data.sites[0].id]: true }));
      }
    } catch {
      setData({ sites: [], totals: {}, linked_via: 'error' });
    }
    setLoading(false);
  }, [API, headers, companyId]);

  useEffect(() => { load(); }, [load]);

  const linkSelf = async () => {
    try {
      const meRes = await axios.get(`${API}/auth/me`, { headers: headers() }).catch(() => null);
      const orgId = meRes?.data?.organization_id || meRes?.data?.user?.organization_id;
      if (!orgId) {
        window.alert('Could not detect your organisation id — please contact support.');
        return;
      }
      await axios.post(`${API}/crm/v2/companies/${companyId}/link-organization`,
        { organization_id: orgId }, { headers: headers() });
      load();
    } catch (e) {
      window.alert(e?.response?.data?.detail || 'Link failed');
    }
  };

  if (loading) {
    return <div className="py-10 text-center text-xs" style={{ color: c.textDim }}>Loading sites & equipment…</div>;
  }

  if (!data || data.linked_via === 'unlinked') {
    return (
      <div className="rounded-xl p-8 text-center" style={{ background: isDark ? 'var(--color-surface-dark-2)' : 'var(--color-neutral-50)', border: `1px dashed ${c.border}` }} data-testid="sites-equipment-unlinked">
        <MapPin size={32} className="mx-auto mb-2" style={{ color: c.textDim }} />
        <p className="text-sm font-semibold mb-1" style={{ color: c.text }}>This company isn't linked to an operations estate yet</p>
        <p className="text-xs mb-4" style={{ color: c.textDim }}>
          Link "{companyName}" to your own organisation to surface its sites + equipment + active contract coverage here.
        </p>
        <button onClick={linkSelf}
          className="px-4 py-2 text-xs font-semibold rounded-md bg-[var(--color-info-ios)] text-white hover:bg-[var(--color-brand-blue-deep)]"
          data-testid="sites-equipment-link-self">
          Link to my organisation
        </button>
        {children && <div className="mt-4 text-left">{children}</div>}
      </div>
    );
  }

  const realLocations = (data.sites || []).filter((x) => !x.virtual && x.id !== '__unassigned__');
  const addLocation = async (name) => {
    const n = (name || '').trim();
    if (!n) return;
    setLocMsg('');
    try {
      await axios.post(`${API}/crm/v2/companies/${companyId}/locations`, { name: n }, { headers: headers() });
      setNewLoc(''); await load();
    } catch (e) { setLocMsg(e?.response?.data?.detail || 'Could not add location'); }
  };
  const renameLocation = async (loc) => {
    const name = window.prompt('Rename location', loc.name);
    if (!name || name.trim() === loc.name) return;
    setLocMsg('');
    try { await axios.put(`${API}/crm/v2/companies/${companyId}/locations/${loc.id}`, { name: name.trim() }, { headers: headers() }); await load(); }
    catch (e) { setLocMsg(e?.response?.data?.detail || 'Could not rename location'); }
  };
  const removeLocation = async (loc) => {
    setLocMsg('');
    try { await axios.delete(`${API}/crm/v2/companies/${companyId}/locations/${loc.id}`, { headers: headers() }); await load(); }
    catch (e) { setLocMsg(e?.response?.data?.detail || 'Could not remove location'); }
  };
  const moveEq = async (eqId, siteId) => {
    if (!siteId) return;
    setLocMsg('');
    try {
      await axios.post(`${API}/crm/v2/companies/${companyId}/equipment/${eqId}/move`, { site_id: siteId }, { headers: headers() });
      await load();
    } catch (e) { setLocMsg(e?.response?.data?.detail || 'Could not move equipment'); }
  };

  const { sites, totals, linked_via } = data;
  return (
    <div className="space-y-3" data-testid="sites-equipment-panel">
      <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
        {[
          { label: 'Sites', value: totals?.sites ?? 0, tint: 'var(--color-info-ios)' },
          { label: 'Equipment', value: totals?.equipment ?? 0, tint: 'var(--color-text-muted)' },
          { label: 'Covered', value: totals?.covered ?? 0, tint: 'var(--color-success-alt)' },
          { label: 'Expiring < 90d', value: totals?.expiring_soon ?? 0, tint: 'var(--color-warning)' },
        ].map((k) => (
          <div key={k.label} className="rounded-lg p-3 border" style={{ background: isDark ? 'var(--color-surface-dark-2)' : '#fff', borderColor: c.border }}>
            <p className="text-[10px] uppercase tracking-wider font-bold" style={{ color: c.textDim }}>{k.label}</p>
            <p className="text-xl font-bold mt-0.5" style={{ color: k.tint }}>{k.value}</p>
          </div>
        ))}
      </div>
      <div className="flex items-center gap-2 flex-wrap" data-testid="sites-equipment-add-location">
        <input value={newLoc} onChange={(e) => setNewLoc(e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter') addLocation(newLoc); }}
          placeholder="Add a location (e.g. Main Gym, Fitness Suite)" className="flex-1 min-w-[200px] px-3 py-1.5 text-xs rounded-md"
          style={{ background: isDark ? 'var(--color-ink-alt)' : '#fff', border: `1px solid ${c.border}`, color: c.text }} data-testid="sites-equipment-new-location" />
        <button type="button" onClick={() => addLocation(newLoc)} disabled={!newLoc.trim()}
          className="px-3 py-1.5 text-xs font-semibold rounded-md bg-[var(--color-info-ios)] text-white disabled:opacity-50" data-testid="sites-equipment-add-location-btn">
          <Plus size={12} className="inline -mt-0.5" /> Add location
        </button>
        {locMsg && <span className="text-xs text-red-600" data-testid="sites-equipment-msg">{locMsg}</span>}
      </div>
      {linked_via === 'name_match' && (
        <p className="text-[10px] italic" style={{ color: c.textDim }} data-testid="sites-equipment-linked-by-name">
          Auto-linked to your organisation by name match.
        </p>
      )}
      {sites.length === 0 && (
        <div className="rounded-xl p-6 text-center" style={{ background: isDark ? 'var(--color-surface-dark-2)' : 'var(--color-neutral-50)', border: `1px dashed ${c.border}` }}>
          <p className="text-sm" style={{ color: c.textDim }}>No sites yet — onboard a site in Operations to see it here.</p>
        </div>
      )}
      {sites.map((s) => (
        <div key={s.id} className="rounded-lg border" style={{ background: isDark ? 'var(--color-surface-dark-1)' : '#fff', borderColor: c.border }} data-testid={`sites-equipment-site-${s.id}`}>
          <button type="button" onClick={() => setExpanded((p) => ({ ...p, [s.id]: !p[s.id] }))}
            className="w-full px-3 py-2 flex items-center justify-between text-left">
            <div className="flex items-center gap-2">
              <ChevronRight size={14} style={{ color: c.textDim, transform: expanded[s.id] ? 'rotate(90deg)' : 'none', transition: 'transform 0.15s' }} />
              <MapPin size={13} style={{ color: 'var(--color-info-ios)' }} />
              <span className="text-sm font-semibold" style={{ color: c.text }}>{s.name}</span>
              <span className="text-[10px] px-1.5 py-0.5 rounded" style={{ background: isDark ? 'var(--color-surface-dark-3)' : 'var(--color-neutral-100)', color: c.textDim }}>
                {s.equipment_count} eq
              </span>
              {!s.virtual && s.id !== '__unassigned__' && (
                <>
                  <span role="button" tabIndex={0} onClick={(e) => { e.stopPropagation(); renameLocation(s); }} className="text-[10px] underline" style={{ color: c.textDim }} data-testid={`sites-equipment-rename-${s.id}`}>Rename</span>
                  {s.equipment_count === 0 && <span role="button" tabIndex={0} onClick={(e) => { e.stopPropagation(); removeLocation(s); }} className="text-[10px] underline text-red-600" data-testid={`sites-equipment-remove-${s.id}`}>Remove</span>}
                </>
              )}
              {s.virtual && (
                <span role="button" tabIndex={0} onClick={(e) => { e.stopPropagation(); addLocation(s.name); }}
                  className="text-[10px] px-1.5 py-0.5 rounded font-semibold" style={{ color: 'var(--color-info-ios)', border: '1px solid var(--color-info-ios)' }}
                  data-testid={`sites-equipment-make-location-${s.id}`}>
                  Save as location
                </span>
              )}
            </div>
          </button>
          {expanded[s.id] && (
            <div className="border-t" style={{ borderColor: c.border }}>
              {s.equipment.length === 0 && (
                <p className="px-3 py-3 text-xs" style={{ color: c.textDim }}>No equipment at this site yet.</p>
              )}
              {s.equipment.map((eq) => (
                <div key={eq.id} className="px-3 py-2 flex items-center justify-between gap-3 border-b last:border-b-0" style={{ borderColor: c.border }} data-testid={`sites-equipment-eq-${eq.id}`}>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium truncate" style={{ color: c.text }}>{eq.name || '(unnamed)'}</p>
                    <p className="text-[11px] truncate" style={{ color: c.textDim }}>
                      {[eq.manufacturer, eq.model, eq.serial_number && `S/N ${eq.serial_number}`].filter(Boolean).join(' · ')}
                    </p>
                  </div>
                  {realLocations.length > 0 && (
                    <select value="" onChange={(e) => moveEq(eq.id, e.target.value)} title="Move to another location"
                      className="text-[11px] px-1.5 py-1 rounded max-w-[150px]" style={{ background: isDark ? 'var(--color-ink-alt)' : '#fff', border: `1px solid ${c.border}`, color: c.text }}
                      data-testid={`sites-equipment-move-${eq.id}`}>
                      <option value="">Move to…</option>
                      {realLocations.filter((l) => l.id !== s.id).map((l) => <option key={l.id} value={l.id}>{l.name}</option>)}
                    </select>
                  )}
                  <CoverageBadge coverage={eq.coverage} isDark={isDark} />
                  <button type="button"
                    onClick={() => setCoverageModal({ equipment_id: eq.id, equipment_name: eq.name, site_id: s.id === '__unassigned__' ? '' : s.id, current_coverage: eq.coverage })}
                    className="text-[11px] px-2 py-1 rounded font-semibold"
                    style={{ background: eq.coverage.has_coverage ? 'transparent' : 'var(--color-info-ios)',
                             color: eq.coverage.has_coverage ? 'var(--color-info-ios)' : '#fff',
                             border: eq.coverage.has_coverage ? `1px solid var(--color-info-ios)` : 'none' }}
                    data-testid={`sites-equipment-add-cover-${eq.id}`}>
                    {eq.coverage.has_coverage ? 'Manage' : '+ Add coverage'}
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>
      ))}

      {coverageModal && (
        <AddCoverageModal
          companyId={companyId} state={coverageModal}
          onClose={() => setCoverageModal(null)} onSaved={() => { setCoverageModal(null); load(); }}
          API={API} headers={headers} c={c} isDark={isDark}
        />
      )}
    </div>
  );
}

function CoverageBadge({ coverage, isDark }) {
  if (!coverage?.has_coverage) {
    return (
      <span className="text-[10px] font-bold uppercase px-1.5 py-0.5 rounded shrink-0" data-testid="coverage-badge-none"
        style={{ background: isDark ? 'rgba(239, 68, 68, 0.15)' : '#FEE2E2', color: '#DC2626' }}>
        Not covered
      </span>
    );
  }
  const tier = coverage.tier || 'covered';
  const end = coverage.end_date || '';
  const endFmt = end ? end.split('-').reverse().join('/') : '';
  const today = new Date();
  const cutoff = new Date(today.getTime() + 90 * 86400000);
  const endDate = end ? new Date(end + 'T00:00:00Z') : null;
  const expiringSoon = endDate && endDate <= cutoff;
  const bg = expiringSoon ? (isDark ? 'rgba(245, 158, 11, 0.15)' : '#FEF3C7') : (isDark ? 'rgba(34, 197, 94, 0.15)' : '#DCFCE7');
  const fg = expiringSoon ? '#D97706' : '#16A34A';
  return (
    <span className="text-[10px] font-bold uppercase px-1.5 py-0.5 rounded shrink-0" data-testid="coverage-badge-active"
      style={{ background: bg, color: fg }} title={`${coverage.contract_title || ''} — ${coverage.coverage_type || ''}`}>
      {tier} · {endFmt || '—'}
    </span>
  );
}

function AddCoverageModal({ companyId, state, onClose, onSaved, API, headers, c, isDark }) {
  const [contracts, setContracts] = useState([]);
  const [form, setForm] = useState({
    contract_id: '',
    coverage_type: 'full',
    warranty_end: '',
    contract_title: `Aftersales — ${state.equipment_name || 'equipment'}`,
    tier: 'bronze',
    start_date: new Date().toISOString().slice(0, 10),
  });
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    axios.get(`${API}/crm/v2/contracts?company_id=${companyId}&status=active`, { headers: headers() })
      .then((r) => setContracts(r.data?.contracts || r.data || []))
      .catch(() => setContracts([]));
  }, [API, headers, companyId]);

  const submit = async () => {
    setSaving(true);
    try {
      const payload = {
        equipment_id: state.equipment_id,
        site_id: state.site_id,
        contract_id: form.contract_id || '',
        coverage_type: form.coverage_type,
        warranty_end: form.warranty_end || '',
      };
      if (!form.contract_id) {
        payload.contract_title = form.contract_title;
        payload.tier = form.tier;
        payload.start_date = form.start_date;
        payload.end_date = form.warranty_end || '';
      }
      await axios.post(`${API}/crm/v2/companies/${companyId}/equipment-coverage`, payload, { headers: headers() });
      onSaved();
    } catch (e) {
      window.alert(e?.response?.data?.detail || 'Save failed');
    }
    setSaving(false);
  };

  const inputStyle = { background: isDark ? 'var(--color-ink-alt)' : '#fff', border: `1px solid ${c.border}`, color: c.text };
  return (
    <div className="fixed inset-0 z-[90] flex items-center justify-center bg-black/50 backdrop-blur-sm" onClick={onClose}>
      <div className="w-full max-w-md mx-4 rounded-xl p-5 shadow-2xl"
        style={{ background: isDark ? 'var(--color-neutral-900)' : '#fff', border: `1px solid ${c.border}` }}
        onClick={(e) => e.stopPropagation()}
        data-testid="add-coverage-modal">
        <div className="flex items-center justify-between mb-3">
          <h3 className="text-sm font-bold" style={{ color: c.text }}>Add coverage — {state.equipment_name}</h3>
          <button onClick={onClose} style={{ color: c.textDim }}><X size={14} /></button>
        </div>
        <div className="space-y-2">
          <label className="block">
            <span className="text-[10px] font-bold uppercase tracking-wider" style={{ color: c.textDim }}>Contract</span>
            <select value={form.contract_id} onChange={(e) => setForm({ ...form, contract_id: e.target.value })}
              className="w-full mt-1 px-3 py-2 text-sm rounded-md" style={inputStyle} data-testid="add-coverage-contract">
              <option value="">+ Create a new aftersales contract</option>
              {contracts.map((ct) => (
                <option key={ct.id} value={ct.id}>{ct.contract_number || ct.title} — {ct.tier} {ct.end_date ? `(until ${ct.end_date})` : ''}</option>
              ))}
            </select>
          </label>
          {!form.contract_id && (
            <>
              <label className="block">
                <span className="text-[10px] font-bold uppercase tracking-wider" style={{ color: c.textDim }}>New contract title</span>
                <input value={form.contract_title} onChange={(e) => setForm({ ...form, contract_title: e.target.value })}
                  className="w-full mt-1 px-3 py-2 text-sm rounded-md" style={inputStyle} data-testid="add-coverage-title" />
              </label>
              <div className="grid grid-cols-2 gap-2">
                <label className="block">
                  <span className="text-[10px] font-bold uppercase tracking-wider" style={{ color: c.textDim }}>Tier</span>
                  <select value={form.tier} onChange={(e) => setForm({ ...form, tier: e.target.value })}
                    className="w-full mt-1 px-3 py-2 text-sm rounded-md" style={inputStyle} data-testid="add-coverage-tier">
                    {['warranty', 'bronze', 'silver', 'gold', 'platinum', 'bespoke'].map((t) => (
                      <option key={t} value={t}>{t.charAt(0).toUpperCase() + t.slice(1)}</option>
                    ))}
                  </select>
                </label>
                <label className="block">
                  <span className="text-[10px] font-bold uppercase tracking-wider" style={{ color: c.textDim }}>Start date</span>
                  <input type="date" value={form.start_date} onChange={(e) => setForm({ ...form, start_date: e.target.value })}
                    className="w-full mt-1 px-3 py-2 text-sm rounded-md" style={inputStyle} data-testid="add-coverage-start" />
                </label>
              </div>
            </>
          )}
          <div className="grid grid-cols-2 gap-2">
            <label className="block">
              <span className="text-[10px] font-bold uppercase tracking-wider" style={{ color: c.textDim }}>Coverage type</span>
              <select value={form.coverage_type} onChange={(e) => setForm({ ...form, coverage_type: e.target.value })}
                className="w-full mt-1 px-3 py-2 text-sm rounded-md" style={inputStyle} data-testid="add-coverage-type">
                <option value="full">Full (parts + labour)</option>
                <option value="parts_only">Parts only</option>
                <option value="labour_only">Labour only</option>
                <option value="inspection">Inspection only</option>
              </select>
            </label>
            <label className="block">
              <span className="text-[10px] font-bold uppercase tracking-wider" style={{ color: c.textDim }}>Cover until</span>
              <input type="date" value={form.warranty_end} onChange={(e) => setForm({ ...form, warranty_end: e.target.value })}
                className="w-full mt-1 px-3 py-2 text-sm rounded-md" style={inputStyle} data-testid="add-coverage-end" />
            </label>
          </div>
        </div>
        <div className="flex justify-end gap-2 mt-4">
          <button onClick={onClose} className="px-3 py-1.5 text-xs" style={{ color: c.textMuted }}>Cancel</button>
          <button onClick={submit} disabled={saving}
            className="px-4 py-1.5 bg-[var(--color-info-ios)] text-white text-xs font-semibold rounded-md disabled:opacity-50"
            data-testid="add-coverage-save">
            {saving ? 'Saving…' : 'Add coverage'}
          </button>
        </div>
      </div>
    </div>
  );
}

/* ═══ COMPANY DETAIL ═══ */
function CoordinatorField({ company, API, headers, c, isDark }) {
  const perms = useCRM().user?.crm_permissions || [];
  const canEdit = perms.includes('contracts.manage');
  const [list, setList] = useState(null);
  const [cur, setCur] = useState({ id: company.coordinator_id || '', name: company.coordinator_name || '' });
  const [busy, setBusy] = useState(false);
  useEffect(() => {
    if (!canEdit) return;
    axios.get(`${API}/crm/workspace/coordinators`, { headers: headers() }).then(r => setList(r.data.coordinators || [])).catch(() => setList([]));
  }, [API, headers, canEdit]);
  if (!canEdit && !cur.name) return null;
  const save = async (uid) => {
    setBusy(true);
    try {
      const r = await axios.put(`${API}/crm/workspace/customers/${company.id}/coordinator`, { user_id: uid || null }, { headers: headers() });
      setCur({ id: r.data.coordinator_id || '', name: r.data.coordinator_name || '' });
      toast.success(`${r.data.coordinator_name ? `Contract Coordinator: ${r.data.coordinator_name}` : 'Moved to the shared coordinator queue'}${r.data.tasks_reassigned ? ` · ${r.data.tasks_reassigned} open task(s) reassigned` : ''}`);
    } catch (e) { toast.error(e.response?.data?.detail || 'Could not update the coordinator'); }
    finally { setBusy(false); }
  };
  return (
    <div className="flex items-center gap-3" data-testid="company-coordinator">
      <Users size={14} style={{ color: c.textDim }} />
      <span className="text-xs" style={{ color: c.textDim }}>Contract Coordinator</span>
      {canEdit ? (
        <select data-testid="company-coordinator-select" value={cur.id} disabled={busy || list === null} onChange={e => save(e.target.value)}
          className="text-sm rounded-md px-2 py-1" style={{ background: isDark ? 'var(--color-surface-dark-1)' : '#fff', border: `1px solid ${c.border}`, color: c.text }}>
          <option value="">Shared coordinator queue</option>
          {cur.id && !(list || []).some(u => u.id === cur.id) && <option value={cur.id}>{cur.name}</option>}
          {(list || []).map(u => <option key={u.id} value={u.id}>{u.full_name || u.email}</option>)}
        </select>
      ) : <span className="text-sm" data-testid="company-coordinator-name" style={{ color: c.text }}>{cur.name}</span>}
    </div>
  );
}

function CompanyDetail({ companyId, onBack, c, isDark, API, headers, _setActiveTab, navigateTo }) {
  const { isMasterAdmin, isOwner } = useCRM();
  // Owners (and Master Admins) can delete a company. Delete lives at the
  // bottom of the Edit modal (owner-gated) with a confirmation prompt.
  const canDelete = isMasterAdmin || isOwner;
  const [company, setCompany] = useState(null);
  const [activeSection, setActiveSection] = useState('overview');
  const [showAddNote, setShowAddNote] = useState(false);
  const [noteForm, setNoteForm] = useState({ subject: '', body: '', type: 'note' });
  const [saving, setSaving] = useState(false);
  const [showAddContact, setShowAddContact] = useState(false);
  const [contactForm, setContactForm] = useState({ first_name: '', last_name: '', email: '', phone: '', job_title: '', is_decision_maker: false });
  // Iter 238h — email duplicate detection. Once the user types a
  // valid-looking email into the Add Contact form, we look it up
  // across the org's contacts. If a match exists, we surface the
  // existing record with a one-click "Link to this company" instead
  // of creating a duplicate.
  const [emailMatch, setEmailMatch] = useState(null); // matched contact or null
  const [emailLookupBusy, setEmailLookupBusy] = useState(false);
  const [contactErr, setContactErr] = useState('');
  const [jobTitles, setJobTitles] = useState([]);
  const [showAddQuote, setShowAddQuote] = useState(false);
  const [quoteLines, setQuoteLines] = useState([{ description: '', quantity: 1, unit_price: 0, discount: 0 }]);
  const [quoteNotes, setQuoteNotes] = useState('');
  // Iter 216h266 — 360° UI: case & deal create dialogs directly on
  // the company drawer. Customer feedback: "I didn't seem to be
  // able to log a case and have it appear against the company
  // record." Backend already supports company_id on cases; we just
  // needed the UI affordances.
  const [showAddCase, setShowAddCase] = useState(false);
  const [caseForm, setCaseForm] = useState({ subject: '', description: '', severity: 'medium' });
  const [showAddDeal, setShowAddDeal] = useState(false);
  const [dealForm, setDealForm] = useState({ title: '', value: '', stage: 'lead', close_date: '' });
  const [_contacts, _setContacts] = useState([]);
  const [showEdit, setShowEdit] = useState(false);
  const [editForm, setEditForm] = useState({});
  const [editStaff, setEditStaff] = useState([]);
  const [savingEdit, setSavingEdit] = useState(false);

  const load = useCallback(async () => {
    try {
      const res = await axios.get(`${API}/crm/v2/companies/${companyId}`, { headers: headers() });
      setCompany(res.data);
    } catch (e) { console.error(e); }
  }, [API, headers, companyId]);

  useEffect(() => { load(); }, [load]);

  // Pulse customer portal onboarding status ("Portal invite" chip + resend).
  const [invite, setInvite] = useState(null);
  const [inviteBusy, setInviteBusy] = useState(false);
  const showInvite = !!(company && (company.linked_operator_org_id || company.pulse_onboarding_state || company.company_type === 'dealer_customer'));
  const loadInvite = useCallback(async () => {
    try {
      const res = await axios.get(`${API}/crm/v2/companies/${companyId}/portal-invite`, { headers: headers() });
      setInvite(res.data);
    } catch (e) { /* non-blocking */ }
  }, [API, headers, companyId]);
  useEffect(() => { if (showInvite) loadInvite(); }, [showInvite, loadInvite]);
  const resendInvite = async () => {
    setInviteBusy(true);
    try {
      const res = await axios.post(`${API}/crm/v2/companies/${companyId}/portal-invite/resend`, {}, { headers: headers() });
      const st = res.data?.status;
      if (st === 'resent') toast.success(`Portal invite re-sent to ${res.data.email}`);
      else if (st === 'provisioned') toast.success(`Portal account created — invite sent to ${res.data.email}`);
      else if (st === 'linked_existing') toast.success('Linked to the customer\'s existing Pulse account.');
      else if (st === 'missing_email') toast.error('No contact email on this customer — add one first.');
      else if (st === 'already_active') toast.info('Customer has already set up their portal.');
      else toast.success('Portal invite processed.');
      loadInvite(); load();
    } catch (e) {
      toast.error(e?.response?.status === 403 ? 'Only owners or managers can resend invites.' : 'Could not resend the invite.');
    }
    setInviteBusy(false);
  };
  const INVITE_STYLES = {
    active: { bg: 'var(--color-success-bg, #dcfce7)', fg: 'var(--color-success-alt, #16a34a)', label: 'Portal: Active' },
    pending_setup: { bg: '#fef3c7', fg: '#b45309', label: 'Portal: Pending set-up' },
    email_failed: { bg: '#fee2e2', fg: '#dc2626', label: 'Portal: Send failed' },
    missing_email: { bg: '#fee2e2', fg: '#dc2626', label: 'Portal: No email' },
    not_invited: { bg: 'var(--color-neutral-100, #f0f0f0)', fg: 'var(--color-text-faint-alt, #6e7476)', label: 'Portal: Not invited' },
  };

  // Connect portal — link this customer to their own Pulse portal org
  // (linked_operator_org_id). Powers customer equipment handover + the
  // "how to log a fault" section of the branded handover pack.
  const [portalLink, setPortalLink] = useState(null); // { linked_org, can_manage }
  const [showConnectPortal, setShowConnectPortal] = useState(false);
  const [portalQuery, setPortalQuery] = useState('');
  const [portalCandidates, setPortalCandidates] = useState([]);
  const [portalBusy, setPortalBusy] = useState(false);
  const loadPortalLink = useCallback(async () => {
    try {
      const res = await axios.get(`${API}/crm/v2/companies/${companyId}/portal-link`, { headers: headers() });
      setPortalLink(res.data);
    } catch (e) { /* non-blocking */ }
  }, [API, headers, companyId]);
  useEffect(() => { loadPortalLink(); }, [loadPortalLink]);
  const searchPortalOrgs = useCallback(async (q) => {
    try {
      const res = await axios.get(`${API}/crm/v2/portal-link/candidates`, { headers: headers(), params: { q } });
      setPortalCandidates(res.data?.candidates || []);
    } catch (e) { setPortalCandidates([]); }
  }, [API, headers]);
  useEffect(() => {
    if (!showConnectPortal) return;
    const t = setTimeout(() => searchPortalOrgs(portalQuery), 250);
    return () => clearTimeout(t);
  }, [showConnectPortal, portalQuery, searchPortalOrgs]);
  const connectPortal = async (orgId) => {
    setPortalBusy(true);
    try {
      const res = await axios.post(`${API}/crm/v2/companies/${companyId}/portal-link`, { org_id: orgId || '' }, { headers: headers() });
      if (orgId) toast.success(`Connected to ${res.data.linked_org?.name || 'portal'}`);
      else toast.success('Portal disconnected');
      setShowConnectPortal(false);
      loadPortalLink();
    } catch (e) {
      toast.error(e?.response?.status === 403 ? 'Only owners / managers can connect a portal.' : (e?.response?.data?.detail || 'Could not update the portal link.'));
    }
    setPortalBusy(false);
  };
  const portalConnected = !!(portalLink && portalLink.linked_org);
  const canManagePortal = !!(portalLink && portalLink.can_manage);
  const createAndInvitePortal = async () => {
    setPortalBusy(true);
    try {
      const res = await axios.post(`${API}/crm/v2/companies/${companyId}/portal-invite/resend`, {}, { headers: headers() });
      const st = res.data?.status;
      if (st === 'provisioned') toast.success(`Portal created — invite sent to ${res.data.email}`);
      else if (st === 'linked_existing') toast.success('Linked to the customer\'s existing Pulse account.');
      else if (st === 'resent') toast.success(`Invite re-sent to ${res.data.email}`);
      else if (st === 'already_active') toast.info('This customer already has an active portal.');
      else if (st === 'missing_email') { toast.error('Add a contact email to this company first, then invite.'); setPortalBusy(false); return; }
      else toast.success('Portal invite processed.');
      setShowConnectPortal(false);
      loadPortalLink(); loadInvite(); load();
    } catch (e) {
      toast.error(e?.response?.status === 403 ? 'Only owners / managers can invite a portal.' : 'Could not create the portal invite.');
    }
    setPortalBusy(false);
  };

  const handleAddActivity = async () => {
    if (!noteForm.subject.trim()) return;
    setSaving(true);
    try {
      await axios.post(`${API}/crm/v2/activities`, { ...noteForm, company_id: companyId }, { headers: headers() });
      setShowAddNote(false);
      setNoteForm({ subject: '', body: '', type: 'note' });
      load();
    } catch (e) { console.error(e); }
    setSaving(false);
  };

  const handleAddContact = async () => {
    if (!contactForm.first_name.trim()) return;
    if (emailMatch) {
      // Email already exists — block create to prevent duplicates.
      // The dialog surfaces a "Link to this company" action instead.
      return;
    }
    setSaving(true); setContactErr('');
    try {
      await axios.post(`${API}/crm/v2/contacts`, {
        ...contactForm, company_id: companyId, company_name: company?.name || '',
      }, { headers: headers() });
      setShowAddContact(false);
      setContactForm({ first_name: '', last_name: '', email: '', phone: '', job_title: '', is_decision_maker: false });
      setEmailMatch(null);
      load();
    } catch (e) {
      const d = e?.response?.data?.detail;
      setContactErr(typeof d === 'string' ? d : (d?.field_label ? `${d.field_label}: "${d.received}" isn't an allowed value — pick one from the list.` : 'Could not save the contact — please check the details and try again.'));
    }
    setSaving(false);
  };

  // Iter 238h — link an already-existing contact (matched by email) to
  // this company. Uses the existing PUT endpoint so we keep all
  // historical activity / notes / deals.
  const handleAttachExistingContact = async () => {
    if (!emailMatch?.id) return;
    setSaving(true);
    try {
      await axios.put(
        `${API}/crm/v2/contacts/${emailMatch.id}`,
        { company_id: companyId, company_name: company?.name || '' },
        { headers: headers() },
      );
      setShowAddContact(false);
      setContactForm({ first_name: '', last_name: '', email: '', phone: '', job_title: '', is_decision_maker: false });
      setEmailMatch(null);
      load();
    } catch (e) { console.error(e); }
    setSaving(false);
  };

  useEffect(() => {
    if (!showAddContact || jobTitles.length) return;
    axios.get(`${API}/crm/picklists/job_title`, { headers: headers() })
      .then((r) => setJobTitles((r.data.values || []).map((v) => v.label || v.value || v).filter(Boolean)))
      .catch(() => {});
  }, [showAddContact, jobTitles.length, API, headers]);

  // Debounced email lookup. Fires 350ms after the user stops typing,
  // skips invalid-looking strings to avoid noise.
  useEffect(() => {
    const email = (contactForm.email || '').trim().toLowerCase();
    if (!email || !email.includes('@') || email.length < 5) {
      setEmailMatch(null);
      return undefined;
    }
    const t = setTimeout(async () => {
      setEmailLookupBusy(true);
      try {
        const res = await axios.get(
          `${API}/crm/v2/contacts?search=${encodeURIComponent(email)}&limit=5`,
          { headers: headers() },
        );
        const exact = (res.data?.contacts || []).find(
          (ct) => (ct.email || '').toLowerCase() === email,
        );
        setEmailMatch(exact || null);
      } catch (e) {
        // silent — duplicate detection is a nicety, not a hard requirement.
      }
      setEmailLookupBusy(false);
    }, 350);
    return () => clearTimeout(t);
  }, [contactForm.email, API, headers]);

  const handleAddQuote = async () => {
    if (quoteLines.every(l => !l.description.trim())) return;
    setSaving(true);
    try {
      // Load contacts for this company to pick a contact
      const ctRes = await axios.get(`${API}/crm/v2/contacts?limit=200`, { headers: headers() });
      const coContacts = (ctRes.data.contacts || []).filter(c => c.company_id === companyId);
      await axios.post(`${API}/crm/v2/quotes`, {
        company_id: companyId, contact_id: coContacts[0]?.id || '',
        lines: quoteLines, vat_rate: 20, notes: quoteNotes,
      }, { headers: headers() });
      setShowAddQuote(false);
      setQuoteLines([{ description: '', quantity: 1, unit_price: 0, discount: 0 }]);
      setQuoteNotes('');
      load();
    } catch (e) { console.error(e); }
    setSaving(false);
  };

  // Iter 216h266 — log a case directly from the company drawer.
  const handleAddCase = async () => {
    if (!caseForm.subject.trim()) return;
    setSaving(true);
    try {
      await axios.post(`${API}/crm/v2/cases`, {
        ...caseForm,
        company_id: companyId,
        contact_id: company?.contacts?.[0]?.id || undefined,
      }, { headers: headers() });
      setShowAddCase(false);
      setCaseForm({ subject: '', description: '', severity: 'medium' });
      load();
    } catch (e) { console.error(e); window.alert(e?.response?.data?.detail || 'Could not log case'); }
    setSaving(false);
  };

  const handleAddDeal = async () => {
    if (!dealForm.title.trim()) return;
    setSaving(true);
    try {
      await axios.post(`${API}/crm/v2/opportunities`, {
        title: dealForm.title,
        value: Number(dealForm.value) || 0,
        stage: dealForm.stage,
        close_date: dealForm.close_date || undefined,
        company_id: companyId,
        contact_id: company?.contacts?.[0]?.id || undefined,
      }, { headers: headers() });
      setShowAddDeal(false);
      setDealForm({ title: '', value: '', stage: 'lead', close_date: '' });
      load();
    } catch (e) { console.error(e); window.alert(e?.response?.data?.detail || 'Could not create deal'); }
    setSaving(false);
  };

  if (!company) return <div className="flex items-center justify-center h-64"><div className="w-5 h-5 border-2 border-[var(--color-info-ios)] border-t-transparent rounded-full animate-spin" /></div>;

  const openEdit = () => {
    setEditForm({
      name: company.name || '', sector: company.sector || '', type: company.type || 'prospect',
      phone: company.phone || '', email: company.email || '', website: company.website || '',
      address: company.address || '',
      address_line1: company.address_line1 || company.address || '',
      address_line2: company.address_line2 || '',
      address_line3: company.address_line3 || '',
      city: company.city || '',
      county: company.county || '',
      postcode: company.postcode || '',
      country: company.country || 'United Kingdom',
      account_owner_id: company.account_owner_id || '',
      account_owner_name: company.account_owner_name || '',
      sla_tier: company.sla_tier || 'standard', notes: company.notes || '',
    });
    setShowEdit(true);
    // Load selectable account managers (CRM users) for the dropdown.
    axios.get(`${API}/crm/territories/staff-palette`, { headers: headers() })
      .then((r) => setEditStaff(r.data?.staff || []))
      .catch(() => {});
  };

  const saveEdit = async () => {
    setSavingEdit(true);
    try {
      await axios.put(`${API}/crm/v2/companies/${companyId}`, editForm, { headers: headers() });
      setShowEdit(false);
      load();
    } catch (e) { console.error(e); }
    setSavingEdit(false);
  };

  const deleteCompany = async () => {
    if (!window.confirm(`Delete "${company.name}"?\n\nThis permanently removes the company and cannot be undone.`)) return;
    try {
      await axios.delete(`${API}/crm/v2/companies/${companyId}`, { headers: headers() });
      setShowEdit(false);
      onBack();
    } catch (e) { window.alert(e?.response?.data?.detail || 'Could not delete company'); }
  };

  // Iter (Jul 2026) — company tabs consolidated to a single source of truth.
  // Support Cases → Service & Engineers; Sites+Portal Equipment+CRM Assets →
  // "Equipment & Assets"; Drawings → Site Surveys; Activity+Timeline+Audit →
  // "Activity". Each merged tab keeps ALL original features behind an inner
  // sub-nav — the child ids below still drive the existing render blocks, so
  // no feature is lost, only regrouped.
  const hasService = !!company.has_service_ops;
  const sections = [
    { id: 'overview',         label: 'Overview' },
    { id: 'contacts',         label: `Contacts (${company.contacts?.length || 0})` },
    { id: 'opportunities',    label: `Deals (${company.opportunities?.length || 0})` },
    { id: 'quotes',           label: `Quotes (${company.quotes?.length || 0})` },
    { id: 'tenders',          label: `Tenders (${company.tenders?.length || 0})` },
    { id: 'invoices',         label: 'Invoices' },
    { id: 'equipment_assets', label: 'Equipment & Assets' },
    { id: 'service_hub',      label: 'Service & Engineers' },
    { id: 'site_surveys',     label: 'Site Surveys' },
    { id: 'activity',         label: 'Activity' },
  ];

  // Merged parent tab → inner sub-nav. Child ids match the existing render
  // blocks (cases/service, activities/timeline/audit, sites_equipment/
  // equipment/assets, surveys/drawings).
  const PARENT_SUBTABS = {
    service_hub: [
      ...(hasService ? [{ id: 'service', label: 'Service & engineers' }] : []),
      { id: 'cases', label: `Support cases (${company.cases?.length || 0})` },
    ],
    activity: [
      { id: 'activities', label: `Activity (${company.activities?.length || 0})` },
      { id: 'timeline',   label: 'Timeline' },
      { id: 'audit',      label: 'Audit' },
    ],
    equipment_assets: [
      { id: 'sites_equipment', label: 'Equipment register' },
      { id: 'assets',          label: `CRM assets (${company.assets?.length || 0})` },
    ],
    site_surveys: [
      { id: 'surveys',  label: 'Site surveys' },
      { id: 'drawings', label: 'Drawings' },
    ],
  };
  const CHILD_TO_PARENT = {};
  for (const [p, kids] of Object.entries(PARENT_SUBTABS)) for (const k of kids) CHILD_TO_PARENT[k.id] = p;
  const defaultChildFor = (pid) => (PARENT_SUBTABS[pid] ? PARENT_SUBTABS[pid][0].id : pid);
  const activeParent = CHILD_TO_PARENT[activeSection] || activeSection;
  const innerTabs = PARENT_SUBTABS[activeParent] || [];

  const _actIcons = { note: FileText, call: Phone, email: Mail, meeting: Calendar, task: CheckCircle, system: Activity, visit: MapPin };

  return (
    <div data-testid="crm-company-detail">
      {/* Header */}
      <div className="flex items-center gap-3 mb-4">
        <Button variant="ghost" size="iconSm" onClick={onBack} icon={ArrowLeft} title="Back" data-testid="crm-company-back" />
        <div className="w-10 h-10 rounded-lg flex items-center justify-center" style={{ background: `${TYPE_COLORS[company.type] || 'var(--color-text-faint-alt)'}15` }}>
          <Building2 size={20} style={{ color: TYPE_COLORS[company.type] || 'var(--color-text-faint-alt)' }} />
        </div>
        <div className="flex-1 min-w-0">
          <h1 className="text-lg font-bold truncate" style={{ color: c.text }}>{company.name}</h1>
          <div className="flex items-center gap-2 mt-0.5">
            <span className="text-[9px] font-bold uppercase px-1.5 py-0.5 rounded" style={{ background: `${TYPE_COLORS[company.type] || 'var(--color-text-faint-alt)'}20`, color: TYPE_COLORS[company.type] || 'var(--color-text-faint-alt)' }}>{company.type}</span>
            {company.sector && <span className="text-xs" style={{ color: c.textDim }}>{company.sector}</span>}
            {company.sla_tier && <span className="text-xs" style={{ color: c.textDim }}>SLA: {company.sla_tier}</span>}
            {showInvite && invite && (INVITE_STYLES[invite.status] || INVITE_STYLES.not_invited) && (
              <span className="text-[10px] font-semibold px-2 py-0.5 rounded-full inline-flex items-center gap-1"
                data-testid="portal-invite-chip"
                title={invite.email ? `Contact: ${invite.email}` : 'No contact email'}
                style={{ background: (INVITE_STYLES[invite.status] || INVITE_STYLES.not_invited).bg, color: (INVITE_STYLES[invite.status] || INVITE_STYLES.not_invited).fg }}>
                {(INVITE_STYLES[invite.status] || INVITE_STYLES.not_invited).label}
              </span>
            )}
            <span className="text-[10px] font-semibold px-2 py-0.5 rounded-full inline-flex items-center gap-1"
              data-testid="portal-link-chip"
              title={portalConnected ? `Fault-logging & handovers go to ${portalLink.linked_org.name}` : 'Not connected to a customer portal'}
              style={{ background: portalConnected ? 'var(--color-success-bg, #dcfce7)' : 'var(--color-neutral-100, #f0f0f0)', color: portalConnected ? 'var(--color-success-alt, #16a34a)' : 'var(--color-text-faint-alt, #6e7476)' }}>
              <Plug size={10} /> {portalConnected ? `Portal: ${portalLink.linked_org.name}` : 'Portal: Not connected'}
            </span>
          </div>
        </div>
        <div className="flex gap-2">
          {canManagePortal && (
            <button onClick={() => { setPortalQuery(''); setShowConnectPortal(true); }}
              className="px-3 py-1.5 text-xs font-medium rounded-md border transition-all hover:bg-white/5"
              style={{ borderColor: portalConnected ? 'var(--color-success-alt)' : c.border, color: portalConnected ? 'var(--color-success-alt)' : c.textMuted }}
              data-testid="company-connect-portal-btn">
              <Plug size={12} className="inline mr-1" /> {portalConnected ? 'Portal connected' : 'Connect portal'}
            </button>
          )}
          {showInvite && invite && invite.status !== 'active' && (
            <button onClick={resendInvite} disabled={inviteBusy}
              className="px-3 py-1.5 text-xs font-medium rounded-md border transition-all hover:bg-white/5 disabled:opacity-50"
              style={{ borderColor: c.border, color: c.textMuted }} data-testid="portal-invite-resend-btn">
              {inviteBusy ? <Loader2 size={12} className="inline mr-1 animate-spin" /> : <Send size={12} className="inline mr-1" />}
              {invite.status === 'not_invited' ? 'Send invite' : 'Resend invite'}
            </button>
          )}
          {company.website && <EnrichFromWebsiteButton companyId={companyId} onEnriched={() => load()} />}
          <button onClick={openEdit} className="px-3 py-1.5 text-xs font-medium rounded-md border transition-all hover:bg-white/5" style={{ borderColor: c.border, color: c.textMuted }} data-testid="company-edit-btn">
            <Edit2 size={12} className="inline mr-1" /> Edit
          </button>
          <button onClick={() => setShowAddNote(true)} className="px-3 py-1.5 bg-[var(--color-info-ios)] text-white text-xs font-medium rounded-md hover:bg-[var(--color-brand-blue-deep)]" data-testid="add-activity-btn">
            <Plus size={12} className="inline mr-1" /> Log Activity
          </button>
        </div>
      </div>

      {/* KPI Strip */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-4">
        <div className="p-3 rounded-lg border" style={{ background: isDark ? 'var(--color-surface-dark-1)' : '#fff', borderColor: isDark ? 'var(--color-surface-dark-panel)' : 'var(--color-border-alt)' }}>
          <p className="text-[10px] uppercase tracking-wider" style={{ color: c.textDim }}>Total Revenue</p>
          <p className="text-lg font-bold" style={{ color: 'var(--color-success-alt)' }}>£{(company.total_revenue || 0).toLocaleString()}</p>
        </div>
        <div className="p-3 rounded-lg border" style={{ background: isDark ? 'var(--color-surface-dark-1)' : '#fff', borderColor: isDark ? 'var(--color-surface-dark-panel)' : 'var(--color-border-alt)' }}>
