  FileText, Calendar, Activity, Target, CheckCircle, Star, Shield, Tag, Globe, Edit2, X, Loader2, Database, Sparkles,
  TrendingUp, Heart, Crown, Save, ChevronUp, Workflow, Check, Send, Dumbbell,
} from 'lucide-react';
