          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2">
              <p className="text-sm font-semibold truncate" style={{ color: c.text }}>{ct.first_name} {ct.last_name}</p>
              {ct.is_decision_maker && <Star size={12} className="text-amber-500 shrink-0" />}
              {ct.is_champion && <Shield size={12} className="text-green-500 shrink-0" />}
            </div>
            <div className="flex items-center gap-3 mt-0.5">
              {ct.job_title && <span className="text-[11px]" style={{ color: c.textDim }}>{ct.job_title}</span>}
            </div>
          </div>
          {ct.company_name && (
            <div className="flex items-center gap-1.5 px-2.5 py-1 rounded-md shrink-0" style={{ background: isDark ? 'var(--color-navy-900)' : 'var(--color-info-bg)', border: `1px solid ${isDark ? 'var(--color-navy-800)' : 'var(--color-blue-200)'}` }} data-testid={`contact-company-tag-${ct.id}`}>
              <Building2 size={11} style={{ color: 'var(--color-info-ios)' }} />
              <span className="text-[11px] font-medium" style={{ color: 'var(--color-info-ios)' }}>{ct.company_name}</span>
            </div>
          )}
          {!ct.company_name && (
            <span className="text-[10px] px-2 py-0.5 rounded shrink-0" style={{ background: isDark ? '#2D1B1B' : 'var(--color-rose-50)', color: 'var(--color-danger)' }}>Unassigned</span>
          )}
          <div className="flex items-center gap-3 shrink-0">
            {ct.email && <Mail size={14} style={{ color: c.textDim }} />}
            {ct.phone && <Phone size={14} style={{ color: c.textDim }} />}
            <ChevronRight size={16} style={{ color: c.textDim }} />
          </div>
        </div>
      ))}
      </ListPanel>

      {showCreate && createPortal((
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4" onClick={() => setShowCreate(false)} data-testid="crm-new-contact-backdrop">
          <div className="w-full max-w-lg mx-4 rounded-xl p-6 shadow-2xl relative max-h-[calc(100vh-8rem)] overflow-y-auto" style={{ background: isDark ? 'var(--color-neutral-900)' : '#fff', border: `1px solid ${c.border}` }} onClick={e => e.stopPropagation()} role="dialog" aria-modal="true" data-testid="create-contact-dialog">
            {/* Iter 215d7 — explicit X close button; CRM modals previously had no
                escape other than clicking the backdrop, which users couldn't see on mobile. */}
            <button
              type="button"
              onClick={() => setShowCreate(false)}
              className="absolute top-4 right-4 h-9 w-9 rounded-full flex items-center justify-center border shrink-0 transition-colors"
              style={{ borderColor: c.border, color: c.text, background: 'transparent' }}
              aria-label="Close"
              data-testid="create-contact-close"
            >
              <X size={18} />
            </button>
            <h2 className="text-lg font-semibold mb-4 flex items-center gap-1.5 pr-12" style={{ color: c.text }}>
              New Contact
              <HelpHint guideId="crm-add-contact" testId="help-hint-new-contact" />
            </h2>
            <div className="grid grid-cols-2 gap-3">
              <div className="col-span-2">
                <label className="text-[10px] uppercase tracking-wider font-medium" style={{ color: c.textDim }}>Company (optional)</label>
                <select value={form.company_id} onChange={e => {
                  const co = companies.find(cx => cx.id === e.target.value);
                  setForm({ ...form, company_id: e.target.value, company_name: co?.name || '' });
                }} className="w-full mt-1 px-3 py-2 text-sm rounded-md" style={{ background: isDark ? 'var(--color-ink-alt)' : '#fff', border: `1px solid ${c.border}`, color: c.text }} data-testid="contact-company-select">
                  <option value="">— No company (standalone contact)</option>
                  {companies.map(co => <option key={co.id} value={co.id}>{co.name}</option>)}
                </select>
              </div>
              {[
                { key: 'first_name', label: 'First Name *' },
                { key: 'last_name', label: 'Last Name *' },
                { key: 'email', label: 'Email *', span: 2 },
                { key: 'phone', label: 'Phone' },
              ].map(f => (
                <div key={f.key} className={f.span === 2 ? 'col-span-2' : ''}>
                  <label className="text-[10px] uppercase tracking-wider font-medium" style={{ color: c.textDim }}>{f.label}</label>
                  <input value={form[f.key]} onChange={e => setForm({...form, [f.key]: e.target.value})} className="w-full mt-1 px-3 py-2 text-sm rounded-md" style={{ background: isDark ? 'var(--color-ink-alt)' : '#fff', border: `1px solid ${c.border}`, color: c.text }} />
                </div>
              ))}
              {/* Iter 216h223 — Job Title now uses the centralised
                  picklist instead of a free-text input. Falls back to
                  free-text via the "Other" option so org-custom titles
                  still work. */}
              <div>
                <label className="text-[10px] uppercase tracking-wider font-medium" style={{ color: c.textDim }}>Job Title</label>
                <PicklistSelect
                  pickKey="job_title"
                  value={form.job_title}
                  onChange={v => setForm({ ...form, job_title: v })}
                  placeholder="Select a job title"
                  api={API}
                  headers={headers}
                  className="w-full mt-1 px-3 py-2 text-sm rounded-md"
                  style={{ background: isDark ? 'var(--color-ink-alt)' : '#fff', border: `1px solid ${c.border}`, color: c.text }}
                  testId="contact-job-title-picklist"
                />
              </div>
              <div className="col-span-2 flex items-center gap-3 flex-wrap">
                <label className="flex items-center gap-2 text-xs cursor-pointer" style={{ color: c.textMuted }}>
                  <input type="checkbox" checked={form.is_decision_maker} onChange={e => setForm({...form, is_decision_maker: e.target.checked})} className="rounded" /> Decision Maker
                </label>
                <div className="flex-1" />
                <label className="text-[10px] uppercase tracking-wider font-medium" style={{ color: c.textDim }}>Stage</label>
                <select
                  value={form.lifecycle}
                  onChange={e => setForm({...form, lifecycle: e.target.value})}
                  className="px-2 py-1 text-xs rounded-md"
                  style={{ background: isDark ? 'var(--color-ink-alt)' : '#fff', border: `1px solid ${c.border}`, color: c.text }}
                  data-testid="contact-lifecycle-select"
                >
                  <option value="lead">Lead</option>
                  <option value="prospect">Prospect</option>
                  <option value="customer">Customer</option>
                  <option value="champion">Champion</option>
                  <option value="lost">Lost</option>
                </select>
              </div>
              <div className="col-span-2 border-t border-zinc-200 pt-3 mt-1 dark:border-zinc-800">
                <div className="text-[10px] uppercase tracking-wider font-bold mb-2" style={{ color: c.textDim }}>
                  GDPR · marketing opt-outs
                </div>
                <div className="flex items-center gap-4 flex-wrap">
                  <label className="flex items-center gap-2 text-xs cursor-pointer" style={{ color: c.textMuted }}>
                    <input
                      type="checkbox"
                      checked={form.opt_out_email}
                      onChange={(e) => setForm({ ...form, opt_out_email: e.target.checked })}
                      className="rounded"
                      data-testid="contact-optout-email"
                    /> No marketing email
                  </label>
                  <label className="flex items-center gap-2 text-xs cursor-pointer" style={{ color: c.textMuted }}>
                    <input
                      type="checkbox"
                      checked={form.opt_out_sms}
                      onChange={(e) => setForm({ ...form, opt_out_sms: e.target.checked })}
                      className="rounded"
                      data-testid="contact-optout-sms"
                    /> No SMS
                  </label>
                  <label className="flex items-center gap-2 text-xs cursor-pointer" style={{ color: c.textMuted }}>
                    <input
                      type="checkbox"
                      checked={form.opt_out_phone}
                      onChange={(e) => setForm({ ...form, opt_out_phone: e.target.checked })}
                      className="rounded"
                      data-testid="contact-optout-phone"
                    /> No phone calls
                  </label>
                </div>
                <p className="text-[10px] mt-2" style={{ color: c.textDim }}>
                  Per-channel opt-outs override any marketing campaign — UK GDPR Article 21.
                </p>
              </div>
            </div>
            <div className="flex gap-2 mt-5 justify-end">
              <button onClick={() => setShowCreate(false)} className="px-4 py-2 text-sm" style={{ color: c.textMuted }}>Cancel</button>
              <button onClick={handleCreate} disabled={saving || !form.first_name.trim() || !!emailMatch} title={emailMatch ? 'Resolve the duplicate-email warning above first' : undefined} className="px-4 py-2 bg-[var(--color-info-ios)] text-white text-sm font-medium rounded-md disabled:opacity-50">{saving ? 'Creating...' : 'Create Contact'}</button>
            </div>
          </div>
        </div>
      ), document.body)}
    </>
  );
}

function StrategicSellingPanel({ contact, isDark, c, API, headers, onSaved }) {
  // Iter 216h270 — Miller Heiman / Strategic Selling "Blue Sheet"
  // scoring panel. Every field is optional, but populating them
  // drives the deal-review dashboards + coverage-gap alerts.
  const [cats, setCats] = useState(null);
  const [form, setForm] = useState({
    buying_influence_level: contact.buying_influence_level || '',
    adoption_sentiment: contact.adoption_sentiment || '',
    coverage_confidence: contact.coverage_confidence || '',
    reports_to_id: contact.reports_to_id || '',
    personal_wins: contact.personal_wins || '',
  });
  const [reportsTo, setReportsTo] = useState(contact.reports_to || null);
  const [companyContacts, setCompanyContacts] = useState([]);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const r = await axios.get(`${API}/crm/stakeholders/miller-heiman-catalogues`, { headers: headers() });
        if (alive) setCats(r.data);
        // Load other contacts at the same company for the reports-to picker.
        if (contact.company_id) {
          const r2 = await axios.get(`${API}/crm/v2/contacts?company_id=${contact.company_id}&limit=100`, { headers: headers() });
          if (alive) setCompanyContacts((r2.data.contacts || []).filter(x => x.id !== contact.id));
        }
      } catch (e) { console.error(e); }
    })();
    return () => { alive = false; };
  }, [API, headers, contact.id, contact.company_id]);

  const save = async () => {
    setSaving(true);
    setSaved(false);
    try {
      await axios.patch(
        `${API}/crm/contacts/${contact.id}/miller-heiman`,
        form,
        { headers: headers() },
      );
      setSaved(true);
      onSaved && onSaved();
      setTimeout(() => setSaved(false), 2400);
    } catch (e) {
      console.error('miller-heiman save failed', e);
    }
    setSaving(false);
  };

  if (!cats) {
    return (
      <div className="flex items-center justify-center py-10" style={{ color: c.textDim }} data-testid="strategic-selling-loading">
        <Loader2 size={14} className="animate-spin mr-2" /> Loading scoring catalogues…
      </div>
    );
  }

  const Pill = ({ active, label, tone, onClick, testid, score }) => (
    <button
      type="button"
      onClick={onClick}
      data-testid={testid}
      className={`px-2.5 py-1.5 text-[11px] font-medium rounded-md border transition-all flex items-center gap-1.5 ${active ? 'shadow-sm' : 'opacity-60 hover:opacity-100'}`}
      style={{
        borderColor: active ? `var(--color-${tone}-500, var(--color-info-ios))` : c.border,
        background: active ? `var(--color-${tone}-500, var(--color-info-ios))15` : 'transparent',
        color: active ? `var(--color-${tone}-500, var(--color-info-ios))` : c.textMuted,
      }}
    >
      {label}
      {typeof score === 'number' && (
        <span className="text-[9px] opacity-70 font-mono">{score > 0 ? `+${score}` : score}</span>
      )}
    </button>
  );

  return (
    <div className="space-y-5" data-testid="strategic-selling-panel">
      {/* Coverage confidence */}
      <div>
        <div className="flex items-center gap-1.5 mb-1.5">
          <Shield size={11} style={{ color: 'var(--color-info-ios)' }} />
          <label className="text-[10px] uppercase tracking-wider font-medium" style={{ color: c.textDim }}>Relationship — Coverage Confidence</label>
        </div>
        <div className="flex flex-wrap gap-1.5" data-testid="mh-coverage-row">
          {cats.coverage_confidences.map(o => (
            <Pill
              key={o.id}
              active={form.coverage_confidence === o.id}
              label={o.label}
              tone={o.tone}
              testid={`mh-coverage-${o.id}`}
              onClick={() => setForm(f => ({ ...f, coverage_confidence: f.coverage_confidence === o.id ? '' : o.id }))}
            />
          ))}
        </div>
      </div>

      {/* Adoption sentiment */}
      <div>
        <div className="flex items-center gap-1.5 mb-1.5">
          <Heart size={11} style={{ color: 'var(--color-info-ios)' }} />
          <label className="text-[10px] uppercase tracking-wider font-medium" style={{ color: c.textDim }}>Adoption Sentiment</label>
        </div>
        <div className="flex flex-wrap gap-1.5" data-testid="mh-sentiment-row">
          {cats.adoption_sentiments.map(o => (
            <Pill
              key={o.id}
              active={form.adoption_sentiment === o.id}
              label={o.label}
              tone={o.tone}
              score={o.score}
              testid={`mh-sentiment-${o.id}`}
              onClick={() => setForm(f => ({ ...f, adoption_sentiment: f.adoption_sentiment === o.id ? '' : o.id }))}
            />
          ))}
        </div>
      </div>

      {/* Buying influence */}
      <div>
        <div className="flex items-center gap-1.5 mb-1.5">
          <TrendingUp size={11} style={{ color: 'var(--color-info-ios)' }} />
          <label className="text-[10px] uppercase tracking-wider font-medium" style={{ color: c.textDim }}>Buying Influence Level</label>
        </div>
        <div className="flex flex-wrap gap-1.5" data-testid="mh-influence-row">
          {cats.buying_influence_levels.map(o => (
            <Pill
              key={o.id}
              active={form.buying_influence_level === o.id}
              label={o.label}
              tone={o.tone}
              testid={`mh-influence-${o.id}`}
              onClick={() => setForm(f => ({ ...f, buying_influence_level: f.buying_influence_level === o.id ? '' : o.id }))}
            />
          ))}
        </div>
      </div>

      {/* Reports-to (org-chart hierarchy) */}
      <div>
        <div className="flex items-center gap-1.5 mb-1.5">
          <ChevronUp size={11} style={{ color: 'var(--color-info-ios)' }} />
          <label className="text-[10px] uppercase tracking-wider font-medium" style={{ color: c.textDim }}>Reports To</label>
        </div>
        <select
          value={form.reports_to_id}
          onChange={e => {
            const id = e.target.value;
            setForm(f => ({ ...f, reports_to_id: id }));
            setReportsTo(companyContacts.find(x => x.id === id) || null);
          }}
          className="w-full max-w-md px-3 py-2 text-sm rounded-md"
          style={{ background: isDark ? 'var(--color-ink-alt)' : '#fff', border: `1px solid ${c.border}`, color: c.text }}
          data-testid="mh-reports-to-select"
          disabled={!contact.company_id}
        >
          <option value="">{contact.company_id ? '— No manager set —' : 'Link a company first to map org-chart'}</option>
          {companyContacts.map(p => (
            <option key={p.id} value={p.id}>{p.first_name} {p.last_name}{p.job_title ? ` · ${p.job_title}` : ''}</option>
          ))}
        </select>
        {reportsTo && (
          <p className="text-[11px] mt-1" style={{ color: c.textDim }} data-testid="mh-reports-to-hint">
            Reports to <span style={{ color: c.text }}>{reportsTo.first_name} {reportsTo.last_name}</span>
            {reportsTo.job_title ? ` (${reportsTo.job_title})` : ''}
          </p>
        )}
      </div>

      {/* Personal wins / motivations */}
      <div>
        <div className="flex items-center gap-1.5 mb-1.5">
          <Star size={11} style={{ color: 'var(--color-info-ios)' }} />
          <label className="text-[10px] uppercase tracking-wider font-medium" style={{ color: c.textDim }}>Personal Wins / Motivations</label>
        </div>
        <textarea
          rows={3}
          value={form.personal_wins}
          onChange={e => setForm(f => ({ ...f, personal_wins: e.target.value }))}
          placeholder="What does THIS person personally get out of the deal closing? (career visibility, KPI hit, reduced workload, recognition…)"
          className="w-full px-3 py-2 text-sm rounded-md"
          style={{ background: isDark ? 'var(--color-ink-alt)' : '#fff', border: `1px solid ${c.border}`, color: c.text }}
          data-testid="mh-personal-wins"
        />
      </div>

      {/* Save bar */}
      <div className="flex items-center gap-3 pt-2 border-t" style={{ borderColor: c.border }}>
        <button
          type="button"
          onClick={save}
          disabled={saving}
          className="px-4 py-2 text-xs font-medium rounded-md flex items-center gap-1.5 disabled:opacity-50"
          style={{ background: 'var(--color-info-ios)', color: '#fff' }}
          data-testid="mh-save-btn"
        >
          {saving ? <Loader2 size={12} className="animate-spin" /> : <Save size={12} />}
          {saving ? 'Saving…' : 'Save Strategic Selling fields'}
        </button>
        {saved && (
          <span className="text-[11px] flex items-center gap-1" style={{ color: 'var(--color-success-alt)' }} data-testid="mh-saved-hint">
            <CheckCircle size={11} /> Saved
          </span>
        )}
      </div>
    </div>
  );
}

function MemberIdentityCard({ contactId, API, headers, c, isDark, navigateTo }) {
  const [data, setData] = useState(null);

  useEffect(() => {
    let alive = true;
    axios.get(`${API}/crm/v2/contacts/${contactId}/member-identity`, { headers: headers() })
      .then((r) => { if (alive) setData(r.data); })
      .catch(() => { if (alive) setData(null); });
    return () => { alive = false; };
  }, [API, headers, contactId]);

  if (!data || !data.is_member) return null;
  const m = data.member || {};
  const statusColor = m.status === 'active' ? 'var(--color-success-alt)' : m.status === 'frozen' ? 'var(--color-accent-amber)' : 'var(--color-text-faint-alt)';
  return (
    <div className="mb-4 flex items-center gap-3 p-3 rounded-lg border" style={{ borderColor: isDark ? 'var(--color-surface-dark-panel)' : 'var(--color-border-alt)', background: isDark ? 'var(--color-surface-dark-1)' : 'var(--color-neutral-50)' }} data-testid="contact-member-identity">
      <div className="w-9 h-9 rounded-full flex items-center justify-center shrink-0" style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-ink)' }}>
        <Dumbbell size={16} />
      </div>
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2">
          <span className="text-sm font-semibold" style={{ color: c.text }}>Also a gym member</span>
          <span className="text-[10px] font-bold uppercase px-1.5 py-0.5 rounded-full text-white" style={{ background: statusColor }} data-testid="member-identity-status">{m.status || 'member'}</span>
        </div>
        <p className="text-[11px]" style={{ color: c.textDim }}>
          {m.plan ? `${m.plan}` : 'Membership'}{m.site ? ` · ${m.site}` : ''}{m.joined_at ? ` · joined ${new Date(m.joined_at).toLocaleDateString('en-GB')}` : ''} · matched by {data.matched_via}
        </p>
      </div>
      {navigateTo && (
        <button onClick={() => navigateTo(`/memberships?member=${m.id}`)} className="px-2.5 py-1.5 rounded-md text-xs font-semibold shrink-0" style={{ background: 'var(--color-info-ios)', color: '#fff' }} data-testid="member-identity-open">View member</button>
      )}
    </div>
  );
}

function ContactDetail({ contactId, onBack, c, isDark, API, headers, navigateTo }) {
  const [contact, setContact] = useState(null);
  const [activeTab, setActiveTab] = useState('overview');
  const [showAddNote, setShowAddNote] = useState(false);
  const [noteForm, setNoteForm] = useState({ subject: '', body: '', type: 'note' });
  const [saving, setSaving] = useState(false);
  const [showEdit, setShowEdit] = useState(false);
  const [editForm, setEditForm] = useState({});
  const [savingEdit, setSavingEdit] = useState(false);
  const [companies, setCompanies] = useState([]);
  const [showConvert, setShowConvert] = useState(false);

  const load = useCallback(async () => {
    try {
      const res = await axios.get(`${API}/crm/v2/contacts/${contactId}`, { headers: headers() });
      setContact(res.data);
    } catch (e) { console.error(e); }
  }, [API, headers, contactId]);
  useEffect(() => { load(); }, [load]);

  const openEdit = async () => {
    setEditForm({
      first_name: contact.first_name || '', last_name: contact.last_name || '',
      email: contact.email || '', phone: contact.phone || '',
      job_title: contact.job_title || '', is_decision_maker: contact.is_decision_maker || false,
      linkedin: contact.linkedin || '', source: contact.source || '',
      company_id: contact.company_id || '', company_name: contact.company_name || '',
    });
    try {
      const res = await axios.get(`${API}/crm/v2/companies?limit=500`, { headers: headers() });
      setCompanies(res.data.companies || []);
    } catch (e) { console.error(e); }
    setShowEdit(true);
  };

  const saveEdit = async () => {
    setSavingEdit(true);
    try {
      await axios.put(`${API}/crm/v2/contacts/${contactId}`, editForm, { headers: headers() });
      setShowEdit(false);
      load();
    } catch (e) { console.error(e); }
    setSavingEdit(false);
  };

  const addActivity = async () => {
    if (!noteForm.subject.trim()) return;
    setSaving(true);
    try {
      await axios.post(`${API}/crm/v2/activities`, { ...noteForm, contact_id: contactId, company_id: contact?.company_id }, { headers: headers() });
      setShowAddNote(false); setNoteForm({ subject: '', body: '', type: 'note' }); load();
    } catch (e) { console.error(e); }
    setSaving(false);
  };

  if (!contact) return <div className="flex items-center justify-center h-64"><div className="w-5 h-5 border-2 border-[var(--color-info-ios)] border-t-transparent rounded-full animate-spin" /></div>;

  const actIcons = { note: FileText, call: Phone, email: Mail, meeting: Calendar, task: CheckCircle, system: Activity };

  return (
    <div data-testid="crm-contact-detail">
      <div className="flex items-center gap-3 mb-4">
        <button onClick={onBack} className="p-1.5 rounded-md" style={{ color: c.textDim }}><ArrowLeft size={18} /></button>
        <div className="w-12 h-12 rounded-full bg-[var(--color-accent-indigo)]/15 flex items-center justify-center text-lg font-bold" style={{ color: 'var(--color-accent-indigo)' }}>
