        placeholder="Manager call £"
        className="w-full px-2 py-1 rounded border text-sm bg-transparent"
        style={{ borderColor: 'var(--theme-border)' }}
        data-testid={`call-input-${row.user_id}`}
      />
      <input
        value={notes}
        onChange={(e) => setNotes(e.target.value)}
