export default function CRMLogin({ onLogin }) {
  const [mode, setMode] = useState('login'); // login | signup
  const [step, setStep] = useState(1); // 1=plan, 2=details, 3=confirm
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPwd, setShowPwd] = useState(false);
  const [fullName, setFullName] = useState('');
  const [companyName, setCompanyName] = useState('');
  const [selectedPlan, setSelectedPlan] = useState('professional');
  const [teamSize, setTeamSize] = useState(1);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [needs2FA, setNeeds2FA] = useState(false);
  const [tempToken, setTempToken] = useState('');
  const [twoFACode, setTwoFACode] = useState('');
  const [twoFAUser, setTwoFAUser] = useState(null);

  const theme = localStorage.getItem('theme') || 'dark';

  // Clear any stale CRM token when on login page
  useEffect(() => {
    localStorage.removeItem('crm_token');
  }, []);
  const isDark = theme === 'dark';
  const bg = isDark ? 'var(--color-ink-alt)' : 'var(--color-neutral-25)';
  const surface = isDark ? 'var(--color-neutral-900)' : 'var(--color-white)';
  const border = isDark ? 'var(--color-surface-dark-3)' : 'var(--color-border-alt)';
  const txt = isDark ? 'var(--color-neutral-50)' : '#1B1C1D';
  const txtM = isDark ? 'var(--color-neutral-400)' : 'var(--color-text-faint-alt)';
  const inputBg = isDark ? 'var(--color-ink-alt)' : 'var(--color-white)';

  // Iter 216h101 — branding leak fix. The CRM is shared across Pulse Fitness
  // and Pulse Fitness deployments. Default brand label tracks the host
  // domain so a Pulse Fitness operator never sees "Pulse Fitness CRM" on the
  // login screen, and vice versa.
  const isPulseHost = typeof window !== 'undefined' && /pulsefitness|pulse-fitness|pulse\.local/i.test(window.location.hostname || '');
  const brandLabel = isPulseHost ? 'Pulse Fitness CRM' : 'Pulse Fitness CRM';
  const brandInitial = isPulseHost ? 'P' : 'G';

  const plan = PLANS[selectedPlan];
  const monthlyTotal = plan ? (plan.base + plan.perUser * teamSize).toFixed(2) : '0.00';

  const handleLogin = async (e) => {
    e.preventDefault();
    setError(''); setLoading(true);
    try {
      const { data } = await axios.post(`${API}/crm/auth/login`, { email, password });
      if (data.requires_2fa) {
        setNeeds2FA(true);
        setTempToken(data.temp_token);
        setTwoFAUser(data.user);
        setTwoFACode('');
      } else {
        onLogin(data.token, data.user);
      }
    } catch (err) {
      setError(err.response?.data?.detail || 'Invalid credentials');
    } finally { setLoading(false); }
  };

  const handle2FAVerify = async (e) => {
    e.preventDefault();
    setError(''); setLoading(true);
    try {
      const { data } = await axios.post(`${API}/crm/auth/2fa/validate`, { temp_token: tempToken, code: twoFACode });
      onLogin(data.token, data.user);
    } catch (err) {
      setError(err.response?.data?.detail || 'Invalid 2FA code');
    } finally { setLoading(false); }
  };

  const handleRegister = async () => {
    setError(''); setLoading(true);
    try {
      const { data } = await axios.post(`${API}/crm/auth/register`, {
        email, password, full_name: fullName,
        company_name: companyName, plan: selectedPlan, team_size: teamSize,
      });
      onLogin(data.token, data.user);
    } catch (err) {
      setError(err.response?.data?.detail || 'Registration failed');
    } finally { setLoading(false); }
  };

  const canProceedStep2 = fullName && email && password && password.length >= 6 && companyName;

  if (mode === 'login') {
    // 2FA Verification Screen
    if (needs2FA) {
      return (
        <div className="min-h-screen flex items-center justify-center px-4" style={{ background: bg }}>
          <div className="w-full max-w-sm" data-testid="crm-2fa-page">
            <div className="flex items-center gap-3 mb-8">
              <BrandWordmark height={36} />
            </div>
            <div className="w-12 h-12 rounded-full bg-[rgb(var(--rgb-info-ios)/0.1)] flex items-center justify-center mx-auto mb-4">
              <Shield size={24} style={{ color: 'var(--color-info-ios)' }} />
            </div>
            <h2 className="text-2xl font-semibold mb-1 text-center" style={{ color: txt }}>Two-Factor Authentication</h2>
            <p className="text-sm mb-6 text-center" style={{ color: txtM }}>
              Enter the 6-digit code from your authenticator app{twoFAUser?.full_name ? `, ${twoFAUser.full_name}` : ''}
            </p>
            {error && <div className="mb-4 px-4 py-3 bg-red-500/10 border border-red-500/30 rounded-lg text-red-500 text-sm" data-testid="crm-2fa-error">{error}</div>}
            <form onSubmit={handle2FAVerify} className="space-y-4">
              <div>
                <label className="block text-xs mb-1.5 uppercase tracking-wider font-medium" style={{ color: txtM }}>Verification Code</label>
                <input
                  type="text"
                  value={twoFACode}
                  onChange={e => setTwoFACode(e.target.value.replace(/\D/g, '').slice(0, 8))}
                  className="w-full px-4 py-3 text-lg font-mono text-center tracking-[0.4em] rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--color-info-ios)]"
                  style={{ background: inputBg, border: `1px solid ${border}`, color: txt }}
                  placeholder="000000"
                  autoFocus
                  required
                  data-testid="crm-2fa-code"
                />
                <p className="text-[11px] mt-2 text-center" style={{ color: txtM }}>Enter your 6-digit code or a backup code</p>
              </div>
              <button type="submit" disabled={loading || twoFACode.length < 6} className="w-full py-3 bg-[var(--color-info-ios)] text-white text-sm font-semibold rounded-lg disabled:opacity-50 flex items-center justify-center gap-2" data-testid="crm-2fa-submit">
                {loading ? <Loader2 size={16} className="animate-spin" /> : <Shield size={16} />}
                {loading ? 'Verifying...' : 'Verify'}
              </button>
              <button type="button" onClick={() => { setNeeds2FA(false); setTempToken(''); setTwoFACode(''); setError(''); }}
                className="w-full text-sm text-center hover:underline" style={{ color: txtM }}>
                Back to login
              </button>
            </form>
          </div>
        </div>
      );
    }

    return (
      <div className="min-h-screen flex items-center justify-center px-4" style={{ background: bg }}>
        <div className="w-full max-w-sm" data-testid="crm-login-page">
          <div className="flex items-center gap-3 mb-8">
            <BrandWordmark height={36} />
          </div>
          <h2 className="text-2xl font-semibold mb-1" style={{ color: txt }}>Welcome back</h2>
          <p className="text-sm mb-6" style={{ color: txtM }}>Sign in to your CRM account</p>
          {error && <div className="mb-4 px-4 py-3 bg-red-500/10 border border-red-500/30 rounded-lg text-red-500 text-sm" data-testid="crm-login-error">{error}</div>}
          <form onSubmit={handleLogin} className="space-y-4">
            <div>
              <label className="block text-xs mb-1.5 uppercase tracking-wider font-medium" style={{ color: txtM }}>Email</label>
              <input id="crm-login-email" name="username" autoComplete="username" type="email" value={email} onChange={e => setEmail(e.target.value)} className="w-full px-4 py-2.5 text-sm rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--color-info-ios)]" style={{ background: inputBg, border: `1px solid ${border}`, color: txt }} placeholder="you@company.com" required data-testid="crm-login-email" />
            </div>
            <div>
              <label className="block text-xs mb-1.5 uppercase tracking-wider font-medium" style={{ color: txtM }}>Password</label>
              <div className="relative">
                <input id="crm-login-password" name="password" autoComplete="current-password" type={showPwd ? 'text' : 'password'} value={password} onChange={e => setPassword(e.target.value)} className="w-full px-4 py-2.5 pr-10 text-sm rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--color-info-ios)]" style={{ background: inputBg, border: `1px solid ${border}`, color: txt }} placeholder="Your password" required data-testid="crm-login-password" />
                <button type="button" onClick={() => setShowPwd(!showPwd)} className="absolute right-3 top-1/2 -translate-y-1/2" style={{ color: txtM }}>{showPwd ? <EyeOff size={16} /> : <Eye size={16} />}</button>
              </div>
            </div>
            <button type="submit" disabled={loading} className="w-full flex items-center justify-center gap-2 py-2.5 bg-[var(--color-info-ios)] hover:bg-[var(--color-brand-blue-deep)] text-white text-sm font-medium rounded-lg transition-all disabled:opacity-50" data-testid="crm-login-submit">
              {loading ? <Loader2 size={16} className="animate-spin" /> : <>Sign In <ArrowRight size={16} /></>}
            </button>
          </form>
          <p className="mt-6 text-center text-sm" style={{ color: txtM }}>
            Don't have an account?{' '}
            <button onClick={() => { setMode('signup'); setStep(1); setError(''); }} className="text-[var(--color-info-ios)] hover:underline font-medium" data-testid="crm-toggle-mode">Start free trial</button>
          </p>
        </div>
      </div>
    );
  }

  // SIGNUP FLOW
  return (
    <div className="min-h-screen" style={{ background: bg }}>
      {/* Header */}
      <div className="border-b px-6 py-4 flex items-center justify-between" style={{ borderColor: border, background: surface }}>
        <div className="flex items-center gap-3">
          <BrandWordmark height={32} />
        </div>
        <button onClick={() => { setMode('login'); setError(''); }} className="text-sm font-medium text-[var(--color-info-ios)] hover:underline" data-testid="back-to-login">Already have an account? Sign in</button>
      </div>

      {/* Progress */}
      <div className="max-w-3xl mx-auto px-6 pt-8">
        <div className="flex items-center justify-center gap-2 mb-8">
          {[{ n: 1, label: 'Choose Plan' }, { n: 2, label: 'Your Details' }, { n: 3, label: 'Confirm' }].map((s, i) => (
            <React.Fragment key={s.n}>
              {i > 0 && <div className="w-12 h-0.5 rounded" style={{ background: step >= s.n ? 'var(--color-info-ios)' : border }} />}
              <div className="flex items-center gap-2">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold ${step >= s.n ? 'bg-[var(--color-info-ios)] text-white' : ''}`} style={step < s.n ? { background: isDark ? 'var(--color-surface-dark-3)' : 'var(--color-border-alt)', color: txtM } : {}}>
                  {step > s.n ? <Check size={14} /> : s.n}
                </div>
                <span className="text-xs font-medium hidden sm:inline" style={{ color: step >= s.n ? txt : txtM }}>{s.label}</span>
              </div>
            </React.Fragment>
          ))}
        </div>

        {error && <div className="mb-4 px-4 py-3 bg-red-500/10 border border-red-500/30 rounded-lg text-red-500 text-sm">{error}</div>}

        {/* Step 1: Plan Selection */}
        {step === 1 && (
          <div data-testid="signup-step-plan">
            <h2 className="text-2xl font-semibold text-center mb-2" style={{ color: txt }}>Choose your plan</h2>
            <p className="text-center mb-8 text-sm" style={{ color: txtM }}>All plans include a 14-day free trial. No credit card required.</p>
            <div className="grid md:grid-cols-3 gap-4">
              {Object.entries(PLANS).map(([key, p]) => (
                <div key={key} onClick={() => setSelectedPlan(key)}
                  className={`relative rounded-xl p-5 cursor-pointer transition-all ${selectedPlan === key ? 'ring-2 ring-[var(--color-info-ios)] scale-[1.02]' : 'hover:scale-[1.01]'}`}
                  style={{ background: surface, border: `1px solid ${selectedPlan === key ? 'var(--color-info-ios)' : border}` }}
                  data-testid={`plan-${key}`}>
                  {p.best && <div className="absolute -top-3 left-1/2 -translate-x-1/2 px-3 py-0.5 bg-[var(--color-success-alt)] text-white text-[10px] font-bold uppercase rounded-full tracking-wider">Most Popular</div>}
                  <div className="w-10 h-10 rounded-lg flex items-center justify-center mb-3" style={{ background: `${p.color}20` }}>
                    <CreditCard size={20} style={{ color: p.color }} />
                  </div>
                  <h3 className="text-lg font-semibold mb-1" style={{ color: txt }}>{p.name}</h3>
                  <div className="mb-4">
                    <span className="text-3xl font-bold" style={{ color: txt }}>£{p.base.toFixed(2)}</span>
                    <span className="text-sm" style={{ color: txtM }}>/mo + £{p.perUser.toFixed(2)}/user</span>
                  </div>
                  <ul className="space-y-2">
                    {p.features.map(f => (
                      <li key={f} className="flex items-start gap-2 text-sm" style={{ color: txtM }}>
                        <Check size={14} className="mt-0.5 flex-shrink-0" style={{ color: p.color }} />
                        {f}
                      </li>
                    ))}
                  </ul>
                </div>
              ))}
            </div>

            {/* Team size */}
            <div className="mt-6 p-4 rounded-xl flex flex-col sm:flex-row items-center gap-4 justify-between" style={{ background: surface, border: `1px solid ${border}` }}>
              <div className="flex items-center gap-3">
                <Users size={20} style={{ color: 'var(--color-info-ios)' }} />
                <div>
                  <p className="text-sm font-medium" style={{ color: txt }}>Team Size</p>
                  <p className="text-xs" style={{ color: txtM }}>How many people will use the CRM?</p>
                </div>
              </div>
              <div className="flex items-center gap-3">
                <button onClick={() => setTeamSize(Math.max(1, teamSize - 1))} className="w-8 h-8 rounded-lg flex items-center justify-center text-lg font-bold" style={{ background: isDark ? 'var(--color-surface-dark-3)' : 'var(--color-neutral-100)', color: txt }}>-</button>
                <span className="text-xl font-bold w-8 text-center" style={{ color: txt }}>{teamSize}</span>
                <button onClick={() => setTeamSize(Math.min(100, teamSize + 1))} className="w-8 h-8 rounded-lg flex items-center justify-center text-lg font-bold" style={{ background: isDark ? 'var(--color-surface-dark-3)' : 'var(--color-neutral-100)', color: txt }}>+</button>
              </div>
              <div className="text-right">
                <p className="text-lg font-bold" style={{ color: txt }}>£{monthlyTotal}</p>
                <p className="text-xs" style={{ color: txtM }}>per month</p>
              </div>
            </div>

            <button onClick={() => setStep(2)} className="w-full mt-6 py-3 bg-[var(--color-info-ios)] hover:bg-[var(--color-brand-blue-deep)] text-white font-medium rounded-lg flex items-center justify-center gap-2 transition-all" data-testid="signup-next-step2">
              Continue <ArrowRight size={16} />
            </button>
          </div>
        )}

        {/* Step 2: Details */}
        {step === 2 && (
          <div className="max-w-md mx-auto" data-testid="signup-step-details">
            <h2 className="text-2xl font-semibold text-center mb-2" style={{ color: txt }}>Your details</h2>
            <p className="text-center mb-6 text-sm" style={{ color: txtM }}>Set up your account</p>
            <div className="space-y-4">
              <div>
                <label className="block text-xs mb-1.5 uppercase tracking-wider font-medium" style={{ color: txtM }}>Full Name</label>
                <input type="text" value={fullName} onChange={e => setFullName(e.target.value)} className="w-full px-4 py-2.5 text-sm rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--color-info-ios)]" style={{ background: inputBg, border: `1px solid ${border}`, color: txt }} placeholder="John Smith" required data-testid="crm-register-name" />
              </div>
              <div>
                <label className="block text-xs mb-1.5 uppercase tracking-wider font-medium" style={{ color: txtM }}>Company Name</label>
                <input type="text" value={companyName} onChange={e => setCompanyName(e.target.value)} className="w-full px-4 py-2.5 text-sm rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--color-info-ios)]" style={{ background: inputBg, border: `1px solid ${border}`, color: txt }} placeholder="Acme Ltd" data-testid="crm-register-company" />
              </div>
              <div>
                <label className="block text-xs mb-1.5 uppercase tracking-wider font-medium" style={{ color: txtM }}>Email</label>
                <input type="email" value={email} onChange={e => setEmail(e.target.value)} className="w-full px-4 py-2.5 text-sm rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--color-info-ios)]" style={{ background: inputBg, border: `1px solid ${border}`, color: txt }} placeholder="you@company.com" required data-testid="crm-login-email" />
              </div>
              <div>
                <label className="block text-xs mb-1.5 uppercase tracking-wider font-medium" style={{ color: txtM }}>Password</label>
                <div className="relative">
                  <input type={showPwd ? 'text' : 'password'} value={password} onChange={e => setPassword(e.target.value)} className="w-full px-4 py-2.5 pr-10 text-sm rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--color-info-ios)]" style={{ background: inputBg, border: `1px solid ${border}`, color: txt }} placeholder="Min 6 characters" required minLength={6} data-testid="crm-login-password" />
                  <button type="button" onClick={() => setShowPwd(!showPwd)} className="absolute right-3 top-1/2 -translate-y-1/2" style={{ color: txtM }}>{showPwd ? <EyeOff size={16} /> : <Eye size={16} />}</button>
                </div>
              </div>
            </div>
            <div className="flex gap-3 mt-6">
              <button onClick={() => setStep(1)} className="flex-1 py-3 rounded-lg font-medium flex items-center justify-center gap-2 transition-all" style={{ background: isDark ? 'var(--color-surface-dark-3)' : 'var(--color-neutral-100)', color: txt }}>
                <ArrowLeft size={16} /> Back
              </button>
              <button onClick={() => { if (canProceedStep2) setStep(3); else setError('Please fill in all fields'); }} className="flex-1 py-3 bg-[var(--color-info-ios)] hover:bg-[var(--color-brand-blue-deep)] text-white font-medium rounded-lg flex items-center justify-center gap-2 transition-all disabled:opacity-50" disabled={!canProceedStep2} data-testid="signup-next-step3">
                Review <ArrowRight size={16} />
              </button>
            </div>
          </div>
        )}

        {/* Step 3: Confirmation */}
        {step === 3 && (
          <div className="max-w-md mx-auto" data-testid="signup-step-confirm">
            <h2 className="text-2xl font-semibold text-center mb-2" style={{ color: txt }}>Review & Start Trial</h2>
            <p className="text-center mb-6 text-sm" style={{ color: txtM }}>14-day free trial — no credit card required</p>

            <div className="rounded-xl overflow-hidden mb-4" style={{ background: surface, border: `1px solid ${border}` }}>
              <div className="p-4 border-b" style={{ borderColor: border }}>
                <p className="text-xs uppercase tracking-wider font-medium mb-2" style={{ color: txtM }}>Plan</p>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <CreditCard size={18} style={{ color: plan?.color || 'var(--color-info-ios)' }} />
                    <span className="font-semibold" style={{ color: txt }}>{plan?.name}</span>
                  </div>
                  <span className="font-bold" style={{ color: txt }}>£{monthlyTotal}/mo</span>
                </div>
                <p className="text-xs mt-1" style={{ color: txtM }}>£{plan?.base.toFixed(2)} base + £{plan?.perUser.toFixed(2)} x {teamSize} user{teamSize > 1 ? 's' : ''}</p>
              </div>
              <div className="p-4 border-b" style={{ borderColor: border }}>
                <p className="text-xs uppercase tracking-wider font-medium mb-2" style={{ color: txtM }}>Account</p>
                <p className="text-sm" style={{ color: txt }}>{fullName}</p>
                <p className="text-sm" style={{ color: txtM }}>{email}</p>
              </div>
              <div className="p-4">
                <p className="text-xs uppercase tracking-wider font-medium mb-2" style={{ color: txtM }}>Company</p>
                <div className="flex items-center gap-2">
                  <Building2 size={16} style={{ color: txtM }} />
                  <span className="text-sm" style={{ color: txt }}>{companyName || `${fullName}'s CRM`}</span>
                </div>
              </div>
            </div>

            <div className="p-3 rounded-lg mb-6 text-center text-sm" style={{ background: isDark ? '#1a2e1a' : '#F0FFF4', color: 'var(--color-success-alt)', border: '1px solid rgba(52,199,89,0.2)' }}>
              Your 14-day free trial starts today. You won't be charged until it ends.
            </div>

            <div className="flex gap-3">
              <button onClick={() => setStep(2)} className="flex-1 py-3 rounded-lg font-medium flex items-center justify-center gap-2" style={{ background: isDark ? 'var(--color-surface-dark-3)' : 'var(--color-neutral-100)', color: txt }}>
                <ArrowLeft size={16} /> Back
              </button>
              <button onClick={handleRegister} disabled={loading} className="flex-1 py-3 bg-[var(--color-info-ios)] hover:bg-[var(--color-brand-blue-deep)] text-white font-medium rounded-lg flex items-center justify-center gap-2 transition-all disabled:opacity-50" data-testid="signup-submit">
                {loading ? <Loader2 size={16} className="animate-spin" /> : <>Start Free Trial <ArrowRight size={16} /></>}
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * CRMPermissions — iter 215de.
 *
 * Admin/owner-only settings panel for two layered authorisation
 * primitives:
 *   1. Sharing rules (record-level access per role + entity type)
 *   2. Field-level security (which fields each role can NOT see)
 *
 * Backend API: /api/crm/permissions/{sharing-rules,field-perms,effective}.
 */
import { useCallback, useEffect, useMemo, useState } from 'react';
import axios from 'axios';
import { toast } from 'sonner';
import { Shield, EyeOff, Trash2, Plus, Lock } from 'lucide-react';
import Button from '@/components/shared/Button';

const API = process.env.REACT_APP_BACKEND_URL ? `${process.env.REACT_APP_BACKEND_URL}/api` : '/api';
const auth = () => { const _t = localStorage.getItem('crm_token'); return { headers: _t ? { Authorization: `Bearer ${_t}` } : {} }; };

const ROLES = ['staff', 'rep', 'sales_rep', 'manager', 'analyst', 'support', 'finance'];
const ACCESS_LABEL = {
  all: 'Full access',
  team: 'Team only (manager hierarchy)',
  owner: 'Own records only',
  none: 'No access',
};

function Section({ title, subtitle, icon: Icon, children, testid }) {
  return (
    <div className="rounded-xl border p-5" style={{ borderColor: 'var(--theme-border)', background: 'var(--theme-surface)' }} data-testid={testid}>
      <div className="flex items-start gap-3 mb-4">
        <div className="h-9 w-9 rounded-lg flex items-center justify-center" style={{ background: 'var(--color-brand-blue, #0091ca)', color: 'white' }}>
          <Icon size={16} />
        </div>
        <div className="flex-1">
          <h3 className="text-sm font-bold tracking-tight" style={{ color: 'var(--theme-text)' }}>{title}</h3>
          {subtitle ? <p className="text-xs mt-0.5 opacity-70">{subtitle}</p> : null}
        </div>
      </div>
      {children}
    </div>
  );
}

function SharingRules({ rules, entityTypes, accessLevels, onChange }) {
  const [draft, setDraft] = useState({ entity_type: 'contact', role: 'sales_rep', access: 'team' });
  const [saving, setSaving] = useState(false);

  const submit = async () => {
    setSaving(true);
    try {
      await axios.put(`${API}/crm/permissions/sharing-rules`, draft, auth());
      toast.success('Rule saved');
      onChange();
    } catch (e) {
      toast.error(e?.response?.data?.detail || 'Save failed');
    } finally { setSaving(false); }
  };

  const remove = async (r) => {
    if (!window.confirm(`Remove ${r.role} → ${r.entity_type} (${r.access})?`)) return;
    try {
      await axios.delete(`${API}/crm/permissions/sharing-rules?entity_type=${encodeURIComponent(r.entity_type)}&role=${encodeURIComponent(r.role)}`, auth());
      toast.success('Removed');
      onChange();
    } catch (e) { toast.error(e?.response?.data?.detail || 'Remove failed'); }
  };

  return (
    <Section
      title="Sharing rules"
      subtitle="Control which records each role can read. By default Companies, Contacts and Opportunities are visible org-wide (all staff see all accounts); other records default to Team only. Add a rule to tighten a role."
      icon={Shield}
      testid="permissions-sharing-rules"
    >
      <div className="overflow-x-auto -mx-2">
        <table className="w-full text-sm">
          <thead>
            <tr className="text-left opacity-60 text-[11px] uppercase tracking-wider">
              <th className="px-2 py-1.5">Role</th>
              <th className="px-2 py-1.5">Entity</th>
              <th className="px-2 py-1.5">Access</th>
              <th />
            </tr>
          </thead>
          <tbody>
            {rules.length === 0 ? (
              <tr><td colSpan="4" className="px-2 py-4 opacity-60 text-center">No custom rules — Companies, Contacts &amp; Opportunities are visible org-wide; other records default to Team-only.</td></tr>
            ) : null}
            {rules.map((r) => (
              <tr key={`${r.role}-${r.entity_type}`} className="border-t" style={{ borderColor: 'var(--theme-border)' }} data-testid={`rule-row-${r.role}-${r.entity_type}`}>
                <td className="px-2 py-2 font-semibold">{r.role}</td>
                <td className="px-2 py-2 capitalize">{r.entity_type}</td>
                <td className="px-2 py-2">{ACCESS_LABEL[r.access] || r.access}</td>
                <td className="px-2 py-2 text-right">
                  <Button variant="ghostDestructive" size="iconSm" onClick={() => remove(r)} icon={Trash2} title="Remove" aria-label="Remove" data-testid={`rule-remove-${r.role}-${r.entity_type}`} />
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="mt-4 grid grid-cols-1 sm:grid-cols-4 gap-2 items-end">
        <div>
          <label className="text-[10px] font-bold uppercase tracking-wider opacity-60">Role</label>
          <input
            list="roles-list"
            value={draft.role}
            onChange={(e) => setDraft({ ...draft, role: e.target.value })}
            className="mt-1 w-full px-2 py-1.5 rounded-md border bg-transparent text-sm"
            style={{ borderColor: 'var(--theme-border)' }}
            data-testid="rule-role-input"
          />
          <datalist id="roles-list">
            {ROLES.map((r) => <option key={r} value={r} />)}
          </datalist>
        </div>
        <div>
          <label className="text-[10px] font-bold uppercase tracking-wider opacity-60">Entity</label>
          <select value={draft.entity_type} onChange={(e) => setDraft({ ...draft, entity_type: e.target.value })} className="mt-1 w-full px-2 py-1.5 rounded-md border bg-transparent text-sm" style={{ borderColor: 'var(--theme-border)' }} data-testid="rule-entity-select">
            {entityTypes.map((t) => <option key={t} value={t}>{t}</option>)}
          </select>
        </div>
        <div>
          <label className="text-[10px] font-bold uppercase tracking-wider opacity-60">Access</label>
          <select value={draft.access} onChange={(e) => setDraft({ ...draft, access: e.target.value })} className="mt-1 w-full px-2 py-1.5 rounded-md border bg-transparent text-sm" style={{ borderColor: 'var(--theme-border)' }} data-testid="rule-access-select">
            {accessLevels.map((a) => <option key={a} value={a}>{ACCESS_LABEL[a] || a}</option>)}
          </select>
        </div>
        <button onClick={submit} disabled={saving} className="px-3 py-2 rounded-md text-sm font-bold text-white inline-flex items-center justify-center gap-1.5" style={{ background: 'var(--color-brand-blue, #0091ca)' }} data-testid="rule-save">
          <Plus size={13} /> {saving ? 'Saving…' : 'Save rule'}
        </button>
      </div>
    </Section>
  );
}

function FieldPerms({ perms, entityTypes, onChange }) {
  const [draft, setDraft] = useState({ entity_type: 'contact', role: 'sales_rep', field: '', access: 'hidden' });
  const [saving, setSaving] = useState(false);

  const submit = async () => {
    if (!draft.field.trim()) { toast.error('Enter a field name'); return; }
    setSaving(true);
    try {
      await axios.put(`${API}/crm/permissions/field-perms`, draft, auth());
      toast.success('Field permission saved');
      setDraft({ ...draft, field: '' });
      onChange();
    } catch (e) {
      toast.error(e?.response?.data?.detail || 'Save failed');
    } finally { setSaving(false); }
  };

  const remove = async (p) => {
    try {
      await axios.delete(`${API}/crm/permissions/field-perms?entity_type=${encodeURIComponent(p.entity_type)}&role=${encodeURIComponent(p.role)}&field=${encodeURIComponent(p.field)}`, auth());
      toast.success('Removed');
      onChange();
    } catch (e) { toast.error(e?.response?.data?.detail || 'Remove failed'); }
  };

  return (
    <Section
      title="Field-level security"
      subtitle="Hide sensitive fields from specific roles (e.g. hide 'notes' from sales_rep). Admins always see everything."
      icon={EyeOff}
      testid="permissions-field-perms"
    >
      <div className="overflow-x-auto -mx-2">
        <table className="w-full text-sm">
          <thead>
            <tr className="text-left opacity-60 text-[11px] uppercase tracking-wider">
              <th className="px-2 py-1.5">Role</th>
              <th className="px-2 py-1.5">Entity</th>
              <th className="px-2 py-1.5">Hidden field</th>
              <th />
            </tr>
          </thead>
          <tbody>
            {perms.length === 0 ? (
              <tr><td colSpan="4" className="px-2 py-4 opacity-60 text-center">No field-level rules. All fields visible to every role.</td></tr>
            ) : null}
            {perms.map((p) => (
              <tr key={`${p.role}-${p.entity_type}-${p.field}`} className="border-t" style={{ borderColor: 'var(--theme-border)' }} data-testid={`field-row-${p.role}-${p.entity_type}-${p.field}`}>
                <td className="px-2 py-2 font-semibold">{p.role}</td>
                <td className="px-2 py-2 capitalize">{p.entity_type}</td>
                <td className="px-2 py-2"><code className="text-xs">{p.field}</code></td>
                <td className="px-2 py-2 text-right">
                  <Button variant="ghostDestructive" size="iconSm" onClick={() => remove(p)} icon={Trash2} title="Remove" aria-label="Remove" data-testid={`field-remove-${p.role}-${p.entity_type}-${p.field}`} />
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="mt-4 grid grid-cols-1 sm:grid-cols-4 gap-2 items-end">
        <div>
          <label className="text-[10px] font-bold uppercase tracking-wider opacity-60">Role</label>
          <input
            list="roles-list"
            value={draft.role}
            onChange={(e) => setDraft({ ...draft, role: e.target.value })}
            className="mt-1 w-full px-2 py-1.5 rounded-md border bg-transparent text-sm"
            style={{ borderColor: 'var(--theme-border)' }}
            data-testid="field-role-input"
          />
        </div>
        <div>
          <label className="text-[10px] font-bold uppercase tracking-wider opacity-60">Entity</label>
          <select value={draft.entity_type} onChange={(e) => setDraft({ ...draft, entity_type: e.target.value })} className="mt-1 w-full px-2 py-1.5 rounded-md border bg-transparent text-sm" style={{ borderColor: 'var(--theme-border)' }} data-testid="field-entity-select">
            {entityTypes.map((t) => <option key={t} value={t}>{t}</option>)}
          </select>
        </div>
        <div>
          <label className="text-[10px] font-bold uppercase tracking-wider opacity-60">Field name</label>
          <input value={draft.field} onChange={(e) => setDraft({ ...draft, field: e.target.value })} placeholder="e.g. notes, phone, value" className="mt-1 w-full px-2 py-1.5 rounded-md border bg-transparent text-sm" style={{ borderColor: 'var(--theme-border)' }} data-testid="field-name-input" />
        </div>
        <button onClick={submit} disabled={saving} className="px-3 py-2 rounded-md text-sm font-bold text-white inline-flex items-center justify-center gap-1.5" style={{ background: 'var(--color-brand-blue, #0091ca)' }} data-testid="field-save">
          <Plus size={13} /> {saving ? 'Saving…' : 'Hide field'}
        </button>
      </div>
    </Section>
  );
}

function ProductCostPerms() {
  const [data, setData] = useState({ grants: [], privileged_roles: [], cost_fields: [] });
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState('');
  const GRANTABLE = ['rep', 'sales_rep', 'support', 'user'];

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const r = await axios.get(`${API}/crm/product-perms`, auth());
      setData(r.data);
    } catch (e) { /* admin-gated; parent handles 403 */ }
    setLoading(false);
  }, []);

  useEffect(() => { load(); }, [load]);

  const toggle = async (role, can) => {
    setSaving(role);
    try {
      await axios.put(`${API}/crm/product-perms`, { role, can_see_cost: can }, auth());
      toast.success(can ? `${role} can now see cost` : `${role} cost access removed`);
      load();
    } catch (e) { toast.error(e?.response?.data?.detail || 'Save failed'); }
    finally { setSaving(''); }
  };

  return (
    <Section
      title="Product cost & margin visibility"
      subtitle="Secure by default: only owner/admin/manager/finance/analyst see product cost & margin. Grant other roles access here."
      icon={Lock}
      testid="permissions-product-cost"
    >
      {loading ? <p className="text-sm opacity-60">Loading…</p> : (
        <>
          <div className="text-[11px] mb-3 opacity-70">
            Always-visible roles: {(data.privileged_roles || []).join(', ')}. Hidden fields: <code className="text-[10px]">{(data.cost_fields || []).join(', ')}</code>
          </div>
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left opacity-60 text-[11px] uppercase tracking-wider">
                <th className="px-2 py-1.5">Role</th>
                <th className="px-2 py-1.5">Can see cost / margin?</th>
              </tr>
            </thead>
            <tbody>
              {GRANTABLE.map((role) => {
                const granted = (data.grants || []).includes(role);
                return (
                  <tr key={role} className="border-t" style={{ borderColor: 'var(--theme-border)' }} data-testid={`product-cost-row-${role}`}>
                    <td className="px-2 py-2 font-semibold">{role}</td>
                    <td className="px-2 py-2">
                      <button
                        onClick={() => toggle(role, !granted)}
                        disabled={saving === role}
                        className="px-3 py-1 rounded-md text-xs font-bold"
                        style={{ background: granted ? 'var(--color-success-alt)' : 'var(--theme-surface)', color: granted ? '#fff' : 'var(--theme-text)', border: `1px solid ${granted ? 'transparent' : 'var(--theme-border)'}` }}
                        data-testid={`product-cost-toggle-${role}`}
                      >
                        {saving === role ? 'Saving…' : granted ? 'Allowed' : 'Hidden'}
                      </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </>
      )}
    </Section>
  );
}

export default function CRMPermissions() {
  const [rules, setRules] = useState([]);
  const [perms, setPerms] = useState([]);
  const [meta, setMeta] = useState({ entity_types: [], access_levels: [] });
  const [loading, setLoading] = useState(true);
  const [unauthorised, setUnauthorised] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const [r1, r2] = await Promise.all([
        axios.get(`${API}/crm/permissions/sharing-rules`, auth()),
        axios.get(`${API}/crm/permissions/field-perms`, auth()),
      ]);
      setRules(r1.data.rules || []);
      setPerms(r2.data.perms || []);
      setMeta({
        entity_types: r1.data.entity_types || [],
        access_levels: r1.data.access_levels || [],
      });
      setUnauthorised(false);
    } catch (e) {
      if (e?.response?.status === 403) setUnauthorised(true);
      else toast.error(e?.response?.data?.detail || 'Failed to load permissions');
    } finally { setLoading(false); }
  }, []);

  useEffect(() => { load(); }, [load]);

  const entityTypes = useMemo(() => (meta.entity_types.length ? meta.entity_types : ['contact', 'company', 'opportunity', 'contract']), [meta.entity_types]);
  const accessLevels = useMemo(() => (meta.access_levels.length ? meta.access_levels : ['all', 'team', 'owner', 'none']), [meta.access_levels]);

  if (unauthorised) {
    return (
      <div className="rounded-xl border p-6 text-center" style={{ borderColor: 'var(--theme-border)' }} data-testid="permissions-forbidden">
        <Lock size={20} className="mx-auto mb-2 opacity-50" />
        <p className="text-sm opacity-70">Only admins or owners can manage permissions.</p>
      </div>
    );
  }
  if (loading) {
    return <p className="text-sm opacity-60" data-testid="permissions-loading">Loading permissions…</p>;
  }

  return (
    <div className="space-y-5" data-testid="crm-permissions-page">
      <SharingRules rules={rules} entityTypes={entityTypes} accessLevels={accessLevels} onChange={load} />
      <FieldPerms perms={perms} entityTypes={entityTypes} onChange={load} />
      <ProductCostPerms />
    </div>
  );
}

/**
 * CRM Picklists admin panel — Iter 216h223.
 *
 * Drop-in section rendered inside CRMSettings.js. Lets admins manage
 * the centralised picklist vocabulary (job titles, industries, lead
 * sources, lost reasons, etc.) that drives every CRM dropdown.
 *
 * The panel reads `/api/crm/picklists` for the key catalogue and
 * `/api/crm/picklists/{key}` for the merged value list. Master admins
 * can edit global defaults; per-org admins can only add to / edit
 * their own org's values. Soft-deprecate (PATCH deprecated=true) is
 * preferred over hard-delete so existing records keep their labels.
 */
import { useCallback, useEffect, useState } from 'react';
import axios from 'axios';
import { List, Plus, Loader2, Trash2, EyeOff, Eye, Save } from 'lucide-react';

export default function CRMPicklistsSection({ API, headers, user, c, isDark }) {
  const [keys, setKeys] = useState([]);
  const [activeKey, setActiveKey] = useState(null);
  const [values, setValues] = useState([]);
  const [loadingKeys, setLoadingKeys] = useState(true);
  const [loadingValues, setLoadingValues] = useState(false);
  const [newLabel, setNewLabel] = useState('');
  const [adding, setAdding] = useState(false);
  const [error, setError] = useState('');
  const [editingId, setEditingId] = useState(null);
  const [editLabel, setEditLabel] = useState('');
  const isMasterAdmin = Boolean(user?.is_master_admin);

  const fetchKeys = useCallback(async () => {
    setLoadingKeys(true);
    try {
      const r = await axios.get(`${API}/crm/picklists`, { headers: headers() });
      const arr = r.data.keys || [];
      setKeys(arr);
      if (!activeKey && arr.length) setActiveKey(arr[0].key);
    } catch (e) {
      setError('Failed to load picklists');
    }
    setLoadingKeys(false);
  }, [API, headers, activeKey]);

  const fetchValues = useCallback(async () => {
    if (!activeKey) return;
    setLoadingValues(true);
    setError('');
    try {
      const r = await axios.get(`${API}/crm/picklists/${activeKey}`, { headers: headers() });
      setValues(r.data.values || []);
    } catch (e) {
      setError('Failed to load values');
    }
    setLoadingValues(false);
  }, [API, activeKey, headers]);

  useEffect(() => { fetchKeys(); }, [fetchKeys]);
  useEffect(() => { fetchValues(); }, [fetchValues]);

  const addValue = async (e) => {
    e?.preventDefault?.();
    const lbl = newLabel.trim();
    if (!lbl || !activeKey) return;
    setAdding(true);
    setError('');
    try {
      await axios.post(`${API}/crm/picklists/${activeKey}`, { label: lbl }, { headers: headers() });
      setNewLabel('');
      fetchValues();
      fetchKeys();
    } catch (err) {
      setError(err?.response?.data?.detail || 'Failed to add value');
    }
    setAdding(false);
  };

  const toggleDeprecated = async (v) => {
    try {
      await axios.patch(
        `${API}/crm/picklists/${activeKey}/${v.id}`,
        { deprecated: !v.deprecated },
        { headers: headers() },
      );
      fetchValues();
      fetchKeys();
    } catch (err) {
      setError(err?.response?.data?.detail || 'Failed to update');
    }
  };

  const saveRename = async (v) => {
    const lbl = editLabel.trim();
    if (!lbl || lbl === v.label) { setEditingId(null); return; }
    try {
      await axios.patch(
        `${API}/crm/picklists/${activeKey}/${v.id}`,
        { label: lbl },
        { headers: headers() },
      );
      setEditingId(null);
      fetchValues();
    } catch (err) {
      setError(err?.response?.data?.detail || 'Failed to rename');
    }
  };

  const hardDelete = async (v) => {
    if (!window.confirm(`Hard-delete "${v.label}"? This is refused if the value is still referenced anywhere.`)) return;
    try {
      await axios.delete(
        `${API}/crm/picklists/${activeKey}/${v.id}`,
        { headers: headers() },
      );
      fetchValues();
      fetchKeys();
    } catch (err) {
      setError(err?.response?.data?.detail || 'Failed to delete');
    }
  };

  return (
    <div
      className="rounded-lg border p-5"
      style={{ background: isDark ? 'var(--color-surface-dark-1)' : '#fff', borderColor: isDark ? 'var(--color-surface-dark-panel)' : 'var(--color-border-alt)' }}
      data-testid="settings-picklists"
    >
      <div className="flex items-start justify-between mb-4">
        <div>
          <h3 className="text-sm font-semibold flex items-center gap-2" style={{ color: c.text }}>
            <List size={14} /> Picklists
          </h3>
          <p className="text-xs mt-0.5" style={{ color: c.textDim }}>
            Centralised editable dropdowns. Global defaults are managed by the master admin;
            anything you add here is scoped to your organisation only.
          </p>
        </div>
        <span className="text-[10px] px-2 py-0.5 rounded-full uppercase tracking-wider font-bold" style={{ background: isMasterAdmin ? 'rgba(25, 205, 255,0.15)' : 'rgba(120,120,120,0.1)', color: isMasterAdmin ? '#0091ca' : c.textDim }} data-testid="picklists-role-badge">
          {isMasterAdmin ? 'Master · Global edit' : 'Org · Local edit'}
        </span>
      </div>

      {loadingKeys ? (
        <div className="flex items-center gap-2 text-sm py-6" style={{ color: c.textMuted }}><Loader2 size={14} className="animate-spin" /> Loading picklists…</div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          {/* Key sidebar */}
          <div className="space-y-1" data-testid="picklists-keys">
            {keys.map(k => {
              const active = activeKey === k.key;
              return (
                <button
                  key={k.key}
                  type="button"
                  onClick={() => setActiveKey(k.key)}
                  className="w-full text-left flex items-center justify-between gap-2 px-3 py-2 rounded-md text-xs transition"
                  style={{
                    background: active ? 'rgba(25,205,255,0.1)' : 'transparent',
                    color: active ? 'var(--color-info-ios)' : c.textMuted,
                    fontWeight: active ? 600 : 500,
                  }}
                  data-testid={`picklists-key-${k.key}`}
                >
                  <span>{k.label}</span>
                  <span className="text-[10px] opacity-60">{k.value_count}</span>
                </button>
              );
            })}
          </div>

          {/* Values column */}
          <div className="md:col-span-3 space-y-3">
            {error && (
              <div className="text-xs px-3 py-2 rounded-md border" style={{ background: 'rgba(239,68,68,0.06)', borderColor: 'rgba(239,68,68,0.25)', color: 'var(--color-danger-alt)' }} data-testid="picklists-error">
                {error}
              </div>
            )}

            {/* Add new value */}
            <form onSubmit={addValue} className="flex items-center gap-2" data-testid="picklists-add-form">
              <input
                type="text"
                value={newLabel}
                onChange={e => setNewLabel(e.target.value)}
                placeholder={`Add a new ${activeKey?.replace('_', ' ') || 'value'}…`}
                className="flex-1 h-9 px-3 text-xs rounded-md border focus:outline-none focus:ring-2 focus:ring-[var(--color-info-ios)]/30"
                style={{ background: isDark ? 'var(--color-surface-dark-2)' : '#fff', borderColor: isDark ? 'var(--color-surface-dark-panel)' : 'var(--color-border-alt)', color: c.text }}
                data-testid="picklists-add-input"
              />
              <button
                type="submit"
                disabled={adding || !newLabel.trim()}
                className="inline-flex items-center gap-1.5 h-9 px-3 text-xs font-semibold rounded-md text-white disabled:opacity-50"
                style={{ background: 'var(--color-info-ios)' }}
                data-testid="picklists-add-btn"
              >
                {adding ? <Loader2 size={12} className="animate-spin" /> : <Plus size={12} />} Add
              </button>
            </form>

            {/* Values list */}
            {loadingValues ? (
              <div className="text-xs py-4 flex items-center gap-2" style={{ color: c.textMuted }}><Loader2 size={12} className="animate-spin" /> Loading…</div>
            ) : (
              <ul className="divide-y rounded-md border" style={{ borderColor: isDark ? 'var(--color-surface-dark-panel)' : 'var(--color-border-alt)' }} data-testid="picklists-values">
                {values.map(v => {
                  const isGlobal = !v.organization_id;
                  const canEdit = isMasterAdmin || !isGlobal;
                  const editing = editingId === v.id;
                  return (
                    <li
                      key={v.id}
                      className="flex items-center gap-2 px-3 py-2 text-xs"
                      style={{ color: v.deprecated ? c.textDim : c.text, opacity: v.deprecated ? 0.6 : 1 }}
                      data-testid={`picklists-row-${v.id}`}
                    >
                      <span className="text-[10px] px-1.5 py-0.5 rounded-full font-bold tracking-wider uppercase" style={{ background: isGlobal ? 'rgba(25, 205, 255,0.12)' : 'rgba(25,205,255,0.10)', color: isGlobal ? '#0091ca' : 'var(--color-info-ios)' }}>
                        {isGlobal ? 'Global' : 'Org'}
                      </span>
                      {editing ? (
                        <input
                          autoFocus
                          value={editLabel}
                          onChange={e => setEditLabel(e.target.value)}
                          onKeyDown={e => { if (e.key === 'Enter') saveRename(v); if (e.key === 'Escape') setEditingId(null); }}
                          onBlur={() => saveRename(v)}
                          className="flex-1 h-7 px-2 text-xs rounded border focus:outline-none focus:ring-1 focus:ring-[var(--color-info-ios)]"
                          style={{ background: isDark ? 'var(--color-surface-dark-2)' : '#fff', borderColor: isDark ? 'var(--color-surface-dark-panel)' : 'var(--color-border-alt)', color: c.text }}
                          data-testid={`picklists-edit-input-${v.id}`}
                        />
                      ) : (
                        <button
                          type="button"
                          disabled={!canEdit}
                          onClick={() => { setEditingId(v.id); setEditLabel(v.label); }}
                          className="flex-1 text-left truncate hover:underline disabled:cursor-default disabled:no-underline"
                          style={{ textDecoration: v.deprecated ? 'line-through' : 'none' }}
                          data-testid={`picklists-label-${v.id}`}
                        >
                          {v.label}
                        </button>
                      )}
                      {canEdit && (
                        <>
                          {editing && (
                            <button
                              type="button"
                              onClick={() => saveRename(v)}
                              className="p-1.5 rounded text-xs"
                              style={{ color: 'var(--color-success-alt)' }}
                              title="Save"
                              data-testid={`picklists-save-${v.id}`}
                            ><Save size={12} /></button>
                          )}
                          <button
                            type="button"
                            onClick={() => toggleDeprecated(v)}
                            className="p-1.5 rounded text-xs"
                            style={{ color: v.deprecated ? 'var(--color-success-alt)' : c.textMuted }}
                            title={v.deprecated ? 'Restore' : 'Hide from new forms'}
                            data-testid={`picklists-deprecate-${v.id}`}
                          >
                            {v.deprecated ? <Eye size={12} /> : <EyeOff size={12} />}
                          </button>
                          <button
                            type="button"
                            onClick={() => hardDelete(v)}
                            className="p-1.5 rounded text-xs"
                            style={{ color: 'var(--color-danger-alt)' }}
                            title="Hard delete (only if not referenced)"
                            data-testid={`picklists-delete-${v.id}`}
                          ><Trash2 size={12} /></button>
                        </>
                      )}
                    </li>
                  );
                })}
                {values.length === 0 && !loadingValues && (
                  <li className="px-3 py-4 text-xs" style={{ color: c.textDim }}>No values yet — add one above.</li>
                )}
              </ul>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import axios from 'axios';
import { useCRM } from './CRMApp';
import { GitCompareArrows, TrendingUp, TrendingDown, Minus, ArrowLeft } from 'lucide-react';

/**
 * CRMQuoteCompare — standalone "Compare Quotes" view.
 *
 * Pick a customer (company) and see a like-for-like comparison of every
 * item they have been quoted, matched on manufacturer + model, with the
 * net unit price in each quote plus latest-vs-previous price movement.
 * Backed by GET /crm/v2/quotes/compare?company_id=...
 */
const fmt = (n, cur = 'GBP') => {
  if (n === null || n === undefined) return '\u2014';
  const sym = cur === 'USD' ? '$' : cur === 'EUR' ? '\u20AC' : '\u00A3';
  return `${sym}${Number(n).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
};

function DeltaBadge({ delta, pct, cur, c }) {
  if (delta === null || delta === undefined) return <span style={{ color: c.textDim }}>{'\u2014'}</span>;
  const up = delta > 0;
  const flat = delta === 0;
  const col = flat ? c.textMuted : up ? 'var(--color-danger, #dc2626)' : 'var(--color-success, #16a34a)';
  const Icon = flat ? Minus : up ? TrendingUp : TrendingDown;
  return (
    <span className="inline-flex items-center gap-1 font-semibold text-sm" style={{ color: col }}>
      <Icon size={13} /> {up ? '+' : ''}{fmt(delta, cur)}{pct !== null && pct !== undefined ? ` (${up ? '+' : ''}${pct}%)` : ''}
    </span>
  );
}

export default function CRMQuoteCompare() {
  const { API, headers, c, isDark, setActiveTab } = useCRM();
  const [companies, setCompanies] = useState([]);
  const [companyId, setCompanyId] = useState('');
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    (async () => {
      try {
        const r = await axios.get(`${API}/crm/v2/companies?limit=300`, { headers: headers() });
        setCompanies(r.data?.companies || r.data || []);
      } catch { /* ignore */ }
    })();
  }, [API, headers]);

  const load = useCallback(async (cid) => {
    if (!cid) { setData(null); return; }
    setLoading(true);
    try {
      const r = await axios.get(`${API}/crm/v2/quotes/compare?company_id=${cid}`, { headers: headers() });
      setData(r.data);
    } catch {
      setData(null);
    }
    setLoading(false);
  }, [API, headers]);

  useEffect(() => { load(companyId); }, [companyId, load]);

  const card = { background: c.surface, border: `1px solid ${c.border}`, color: c.text };
  const cur = data?.quotes?.[0]?.currency || 'GBP';

  return (
    <div className="p-4 sm:p-6 max-w-[1400px] mx-auto" data-testid="crm-quote-compare">
