function RegionDrawer({ region, staff, coverage, offices = [], onClose, onSave }) {
  const current = coverage[region?.code] || [];
  const [selected, setSelected] = useState(() => current.map((m) => m.user_id));
  const [saving, setSaving] = useState(false);
  const [query, setQuery] = useState('');
  useEffect(() => { setSelected(current.map((m) => m.user_id)); }, [region]); // eslint-disable-line react-hooks/exhaustive-deps

  const toggle = (uid) => setSelected((cur) => (cur.includes(uid) ? cur.filter((x) => x !== uid) : [...cur, uid]));
  const visible = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return staff;
    return staff.filter((s) => (s.full_name || s.email || '').toLowerCase().includes(q));
  }, [staff, query]);

  // Nearest office to this region — great-circle distance (miles) from the
  // region centroid to every pinned office. Helps planners pick the
  // closest depot when allocating coverage.
  const nearest = useMemo(() => {
    if (!region?.centroid || !offices.length) return null;
    const [lng, lat] = region.centroid;
    const R = 3958.8; // Earth radius, miles
    const toRad = (d) => (d * Math.PI) / 180;
    let best = null;
    offices.forEach((o) => {
      if (typeof o.lat !== 'number' || typeof o.lng !== 'number') return;
      const dLat = toRad(o.lat - lat);
      const dLng = toRad(o.lng - lng);
      const a = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(lat)) * Math.cos(toRad(o.lat)) * Math.sin(dLng / 2) ** 2;
      const dist = R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
      if (!best || dist < best.dist) best = { office: o, dist };
    });
    return best;
  }, [region, offices]);

  if (!region) return null;
  const save = async () => {
    setSaving(true);
    try {
      await onSave(region, selected);
    } finally { setSaving(false); }
  };

  return (
    <div className="fixed inset-y-0 right-0 z-40 w-full sm:w-[420px] bg-white dark:bg-zinc-900 border-l border-zinc-200 dark:border-zinc-800 shadow-xl flex flex-col" data-testid="region-drawer">
      <div className="px-5 py-4 border-b border-zinc-200 dark:border-zinc-800 flex items-center justify-between">
        <div className="min-w-0">
          <p className="text-[10px] uppercase tracking-wider text-zinc-500 font-bold">
            {region.type === 'county' ? 'County' : 'Postcode area'}
          </p>
          <h3 className="text-lg font-bold text-zinc-900 dark:text-zinc-100 truncate">{region.label}</h3>
        </div>
        <button onClick={onClose} className="p-1 text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-100" data-testid="region-drawer-close">
          <X size={18} />
        </button>
      </div>
      <div className="px-5 py-3 border-b border-zinc-100 dark:border-zinc-800">
        <div className="relative">
          <Search size={13} className="absolute left-2.5 top-2.5 text-zinc-400" />
          <input
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Filter people..."
            className="w-full pl-7 pr-2 py-1.5 text-sm border border-zinc-200 dark:border-zinc-700 rounded-md bg-white dark:bg-zinc-900 focus:outline-none focus:ring-2 focus:ring-blue-500/30 focus:border-blue-500"
            data-testid="region-drawer-search"
          />
        </div>
        <p className="mt-2 text-[11px] text-zinc-500">
          {selected.length} assigned · click anyone to toggle them on or off this region.
        </p>
        {nearest && (
          <div className="mt-2 flex items-center gap-1.5 text-[11px] font-semibold text-zinc-700 dark:text-zinc-300" data-testid="region-nearest-office">
            <Building2 size={12} className="text-zinc-500" />
            Nearest office:
            <span className="inline-flex items-center gap-1">
              <span className="w-2.5 h-2.5 rounded-full border border-zinc-300" style={{ backgroundColor: nearest.office.colour_hex }} />
              {nearest.office.name}
            </span>
            <span className="text-zinc-400 font-normal">· {Math.round(nearest.dist)} mi</span>
          </div>
        )}
      </div>
      <div className="flex-1 overflow-y-auto px-3 py-2 space-y-1">
        {visible.length === 0 && <p className="text-sm text-zinc-400 text-center py-6">No matching people.</p>}
        {visible.map((s) => {
          const on = selected.includes(s.id);
          const Icon = ROLE_ICONS[s.territory_role] || UserCog;
          return (
            <button
              type="button"
              key={s.id}
              onClick={() => toggle(s.id)}
              className={`w-full flex items-center gap-2 px-2 py-1.5 rounded-md border text-left ${on ? 'border-zinc-900 bg-zinc-50 dark:bg-zinc-800 dark:border-zinc-200' : 'border-transparent hover:bg-zinc-50 dark:hover:bg-zinc-800/60'}`}
              data-testid={`region-drawer-staff-${s.id}`}
            >
              <span className="w-3 h-3 rounded border border-zinc-300" style={{ backgroundColor: s.colour_hex }} />
              <span className="flex-1 min-w-0">
                <span className="block text-sm font-semibold text-zinc-900 dark:text-zinc-100 truncate">{s.full_name || s.email}</span>
                <span className="block text-[10px] text-zinc-500 flex items-center gap-1">
                  <Icon size={9} /> {ROLE_LABELS[s.territory_role]}
                </span>
              </span>
              {on && <CheckCircle2 size={15} className="text-emerald-600" />}
            </button>
          );
        })}
      </div>
      <div className="px-5 py-3 border-t border-zinc-200 dark:border-zinc-800 flex items-center gap-3 bg-zinc-50 dark:bg-zinc-900/60">
        <button
          onClick={() => onSave(region, [])}
          disabled={saving || current.length === 0}
          className="px-3 py-2 text-xs font-bold text-rose-700 hover:bg-rose-50 rounded-md disabled:opacity-40"
          data-testid="region-drawer-clear"
        >
          Clear region
        </button>
        <div className="flex-1" />
        <button onClick={onClose} className="px-3 py-2 text-sm font-bold text-zinc-700 dark:text-zinc-300 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-md" data-testid="region-drawer-cancel">
          Cancel
        </button>
        <button
          onClick={save}
          disabled={saving}
          className="px-4 py-2 text-sm font-bold text-white rounded-md disabled:opacity-50"
          style={{ background: 'var(--color-brand-blue, #2563EB)' }}
          data-testid="region-drawer-save"
        >
          {saving ? 'Saving…' : 'Save assignment'}
        </button>
      </div>
    </div>
  );
}

export default function CRMTerritoryMap() {
  const [layer, setLayer] = useState('county'); // 'county' | 'postcode_area'
  const [counties, setCounties] = useState([]);
  const [postcodes, setPostcodes] = useState([]);
  const [coverage, setCoverage] = useState({ counties: {}, postcode_areas: {} });
  const [heatmap, setHeatmap] = useState({ counties: {}, postcode_areas: {} });
  const [showHeatmap, setShowHeatmap] = useState(false);
  const [showOverlaps, setShowOverlaps] = useState(false); // flag double-covered regions
  const [roleFilter, setRoleFilter] = useState('all'); // 'all' | 'sales_manager' | 'engineer'
  const [offices, setOffices] = useState([]);
  const [showOffices, setShowOffices] = useState(true);
  const [staffLocations, setStaffLocations] = useState([]);
  const [showStaffPins, setShowStaffPins] = useState(true);
  const [pinCard, setPinCard] = useState(null); // { staff, left, top, above }
  const mapWrapRef = useRef(null);
  const pinCardRef = useRef(null);
  const [autoAssigning, setAutoAssigning] = useState(false);
  const [staff, setStaff] = useState([]);
  const [focusedUser, setFocusedUser] = useState(null);
  const [activeRegion, setActiveRegion] = useState(null);
  const [loading, setLoading] = useState(true);
  const svgRef = useRef(null);

  // ── Data loading ─────────────────────────────────────────────────
  const loadCoverage = useCallback(async () => {
    try {
      const [cov, palette, heat] = await Promise.all([
        axios.get(`${API}/crm/territories/coverage-map`, auth()),
        axios.get(`${API}/crm/territories/staff-palette`, auth()),
        axios.get(`${API}/crm/territories/coverage-heatmap`, auth()).catch(() => ({ data: { counties: {}, postcode_areas: {} } })),
      ]);
      setCoverage({
        counties: cov.data.counties || {},
        postcode_areas: cov.data.postcode_areas || {},
      });
      setHeatmap({
        counties: heat.data.counties || {},
        postcode_areas: heat.data.postcode_areas || {},
      });
      // Auto-assign default colours to staff who haven't picked one.
      const pal = (palette.data.staff || []).map((s, i) => ({
        ...s,
        colour_hex: s.colour_hex && s.colour_hex !== '#94A3B8' ? s.colour_hex : DEFAULT_PALETTE[i % DEFAULT_PALETTE.length],
      }));
      setStaff(pal);
    } catch (e) {
      toast.error(e?.response?.data?.detail || 'Failed to load coverage');
    }
  }, []);

  const loadOffices = useCallback(async () => {
    try {
      const r = await axios.get(`${API}/crm/territories/offices`, auth());
      setOffices(r.data.offices || []);
    } catch (e) { /* offices are optional; ignore load errors */ }
  }, []);

  const loadStaffLocations = useCallback(async () => {
    try {
      const r = await axios.get(`${API}/crm/territories/staff-locations`, auth());
      setStaffLocations(r.data.staff || []);
    } catch (e) { /* staff pins are optional; ignore load errors */ }
  }, []);

  const loadMaps = useCallback(async () => {
    setLoading(true);
    try {
      const [c, p] = await Promise.all([
        fetch('/maps/uk_counties.topojson').then((r) => r.json()),
        fetch('/maps/uk_postcodes.topojson').then((r) => r.json()),
      ]);
      const countiesFC = feature(c, c.objects.eng_ceremonial);
      const postcodesFC = feature(p, p.objects.uk_postcode_areas);
      setCounties(countiesFC.features || []);
      // The postcode dataset only covers GB (120 areas, no BT), so Northern
      // Ireland vanished in postcode mode. Synthesise a single "BT" postcode
      // area by merging the six NI ceremonial counties from the counties
      // topology so NI stays visible and paintable in postcode mode too.
      const postcodeFeatures = postcodesFC.features || [];
      try {
        const NI = new Set(['Antrim', 'Armagh', 'Down', 'Londonderry', 'Tyrone', 'Fermanagh']);
        const niGeoms = (c.objects.eng_ceremonial.geometries || [])
          .filter((g) => NI.has(g.properties && g.properties.county));
        if (niGeoms.length && !postcodeFeatures.some((f) => f.properties && f.properties.area === 'BT')) {
          const btGeometry = merge(c, niGeoms);
          postcodeFeatures.push({ type: 'Feature', properties: { area: 'BT' }, geometry: btGeometry });
        }
      } catch { /* non-fatal — GB postcode areas still render */ }
      setPostcodes(postcodeFeatures);
    } catch (e) {
      toast.error('Could not load UK map data');
    }
    setLoading(false);
  }, []);

  useEffect(() => {
    loadMaps();
    loadCoverage();
    loadOffices();
    loadStaffLocations();
  }, [loadMaps, loadCoverage, loadOffices, loadStaffLocations]);

  // ── Save handlers ─────────────────────────────────────────────────
  const saveRegion = async (region, assignedIds) => {
    try {
      await axios.put(
        `${API}/crm/territories/region/${region.type}/${encodeURIComponent(region.code)}`,
        { assigned_rep_ids: assignedIds },
        auth(),
      );
      toast.success(assignedIds.length === 0 ? `Cleared ${region.label}` : `Saved ${region.label}`);
      setActiveRegion(null);
      loadCoverage();
    } catch (e) {
      toast.error(e?.response?.data?.detail || 'Save failed');
    }
  };

  // Iter 220ea·41 — "paint mode": once a staff member is selected in the
  // sidebar (focusedUser), clicking a county/postcode area directly
  // allocates them to it (paints their colour) — or removes them if they
  // already cover it. No drawer needed. Optimistic + auto-saved. This is
  // the intuitive "pick a person, click the map to allocate" flow.
  const paintRegion = async (region, uid) => {
    const key = region.type === 'county' ? 'counties' : 'postcode_areas';
    const current = coverage[key][region.code] || [];
    const has = current.some((m) => m.user_id === uid);
    const nextIds = has
      ? current.filter((m) => m.user_id !== uid).map((m) => m.user_id)
      : [...current.map((m) => m.user_id), uid];
    const s = staffById[uid];
    const optimistic = has
      ? current.filter((m) => m.user_id !== uid)
      : [...current, { user_id: uid, full_name: s?.full_name, colour_hex: s?.colour_hex, role: s?.territory_role }];
    // Optimistically recolour the region so painting feels instant.
    setCoverage((cur) => ({ ...cur, [key]: { ...cur[key], [region.code]: optimistic } }));
    try {
      await axios.put(
        `${API}/crm/territories/region/${region.type}/${encodeURIComponent(region.code)}`,
        { assigned_rep_ids: nextIds },
        auth(),
      );
    } catch (e) {
      toast.error(e?.response?.data?.detail || 'Could not save assignment');
      loadCoverage(); // revert to server truth on failure
    }
  };

  const saveStaffColour = async (uid, hex) => {
    setStaff((cur) => cur.map((s) => (s.id === uid ? { ...s, colour_hex: hex.toUpperCase() } : s)));
    try {
      await axios.put(`${API}/crm/territories/staff/${uid}/style`, { colour_hex: hex }, auth());
      loadCoverage();
    } catch (e) {
      toast.error(e?.response?.data?.detail || 'Could not save colour');
    }
  };

  const saveStaffRole = async (uid, role) => {
    setStaff((cur) => cur.map((s) => (s.id === uid ? { ...s, territory_role: role } : s)));
    try {
      await axios.put(`${API}/crm/territories/staff/${uid}/style`, { territory_role: role }, auth());
      loadCoverage();
    } catch (e) {
      toast.error(e?.response?.data?.detail || 'Could not save role');
    }
  };

  // Iter 216h279 — push every region's coverage onto unassigned
  // companies + opportunities + tenders in one click. Heaviest write
  // op on this page so we lock the button + show a spinner; the
  // backend already short-circuits on records that already carry a
  // territory_id so re-runs are cheap and idempotent.
  const runAutoAssign = async () => {
    setAutoAssigning(true);
    try {
      const r = await axios.post(
        `${API}/crm/territories/map-auto-assign`,
        { dry_run: false, only_unassigned: true },
        auth(),
      );
      const tot = r.data?.totals || {};
      toast.success(
        `Auto-assigned ${r.data.total} records · ${tot.company || 0} companies · ${tot.opportunity || 0} deals · ${tot.tender || 0} tenders`,
      );
      loadCoverage();
    } catch (e) {
      toast.error(e?.response?.data?.detail || 'Auto-assign failed');
    } finally { setAutoAssigning(false); }
  };

  // ── Region fill resolver — colour-mix when N reps cover the same area ──
  const staffById = useMemo(() => Object.fromEntries(staff.map((s) => [s.id, s])), [staff]);
  // Role filter: a member with role 'both' always matches. This lets an
  // admin view Engineer coverage and Sales-Manager coverage independently
  // while allowing the two to overlap on the same region.
  const roleMatch = useCallback(
    (r) => roleFilter === 'all' || r === roleFilter || r === 'both',
    [roleFilter],
  );
  // County ↔ postcode-area bridge. The two topojson layers share no key, so
  // we map each county to the postcode area that geographically contains its
  // centroid (and the inverse). This lets coverage assigned on ONE layer show
  // on the OTHER — a county painted for a rep also lights up the postcode
  // area(s) over it, and vice versa. Built once when both layers are loaded.
  const areaCountyMap = useMemo(() => {
    const countyToArea = {};
    const areaToCounties = {};
    if (!counties.length || !postcodes.length) return { countyToArea, areaToCounties };
    // Pre-compute postcode-area centroids for the nearest-area fallback.
    const areaCentroids = postcodes.map((pf) => {
      let c = null;
      try { c = geoCentroid(pf); } catch { c = null; }
      return { area: pf.properties && pf.properties.area, c };
    }).filter((x) => x.area && x.c && !Number.isNaN(x.c[0]));
    const assign = (cc, ac) => {
      if (!cc || !ac) return;
      countyToArea[cc] = ac;
      (areaToCounties[ac] = areaToCounties[ac] || []).push(cc);
    };
    for (const cf of counties) {
      const cc = cf.properties && cf.properties.county;
      if (!cc) continue;
      let centroid;
      try { centroid = geoCentroid(cf); } catch { centroid = null; }
      if (!centroid || Number.isNaN(centroid[0])) continue;
      let matched = false;
      for (const pf of postcodes) {
        let inside = false;
        try { inside = geoContains(pf, centroid); } catch { inside = false; }
        if (inside) { assign(cc, pf.properties && pf.properties.area); matched = true; break; }
      }
      // Fallback (islands): snap to the nearest postcode-area centroid, but
      // only if reasonably close (< ~1 deg²). This keeps Shetland → ZE while
      // NOT mis-mapping Northern Ireland (no NI postcode area exists on this
      // layer) across the Irish Sea to Scotland.
      if (!matched && areaCentroids.length) {
        let best = null; let bestD = Infinity;
        for (const a of areaCentroids) {
          const dx = a.c[0] - centroid[0]; const dy = a.c[1] - centroid[1];
          const d = dx * dx + dy * dy;
          if (d < bestD) { bestD = d; best = a.area; }
        }
        if (best && bestD < 1.0) assign(cc, best);
      }
    }
    return { countyToArea, areaToCounties };
  }, [counties, postcodes]);

  // Effective coverage for a region = its own assignments UNION the
  // assignments inherited from the bridged layer (deduped by rep). This is
  // what makes coverage appear on BOTH the county and postcode-area maps.
  const effectiveList = useCallback((type, code) => {
    const byUser = new Map();
    const add = (arr) => (arr || []).forEach((m) => {
      if (m && m.user_id && !byUser.has(m.user_id)) byUser.set(m.user_id, m);
    });
    if (type === 'county') {
      add(coverage.counties[code]);
      const area = areaCountyMap.countyToArea[code];
      if (area) add(coverage.postcode_areas[area]);
    } else {
      add(coverage.postcode_areas[code]);
      (areaCountyMap.areaToCounties[code] || []).forEach((cc) => add(coverage.counties[cc]));
    }
    return Array.from(byUser.values());
  }, [coverage, areaCountyMap]);

  // Same union as effectiveList, but tagged with provenance so tooltips can
  // explain WHY a region is covered when no one painted it directly on this
  // layer (e.g. "(via county Greater Manchester)" while viewing postcode M).
  const coverageDetail = useCallback((type, code) => {
    const byUser = new Map();
    const put = (m, direct, viaLabel) => {
      if (!m || !m.user_id) return;
      const e = byUser.get(m.user_id) || { ...m, direct: false, via: null };
      if (direct) e.direct = true;
      else if (!e.via) e.via = viaLabel;
      byUser.set(m.user_id, e);
    };
    if (type === 'county') {
      (coverage.counties[code] || []).forEach((m) => put(m, true));
      const area = areaCountyMap.countyToArea[code];
      if (area) (coverage.postcode_areas[area] || []).forEach((m) => put(m, false, `postcode ${area}`));
    } else {
      (coverage.postcode_areas[code] || []).forEach((m) => put(m, true));
      (areaCountyMap.areaToCounties[code] || []).forEach((cc) => {
        (coverage.counties[cc] || []).forEach((m) => put(m, false, `county ${cc}`));
      });
    }
    return Array.from(byUser.values());
  }, [coverage, areaCountyMap]);


  const membersFor = useCallback(
    (type, code) => effectiveList(type, code).filter((m) => roleMatch(m.role)),
    [effectiveList, roleMatch],
  );
  const visibleStaff = useMemo(
    () => staff.filter((s) => roleMatch(s.territory_role)),
    [staff, roleMatch],
  );
  // Pre-compute the heatmap normalisation range for the active layer so
  // opacity scales sensibly across whatever range the org has.
  const heatRange = useMemo(() => {
    const vals = Object.values(heatmap[layer === 'county' ? 'counties' : 'postcode_areas']).filter((v) => v > 0);
    if (!vals.length) return { max: 0 };
    return { max: Math.max(...vals) };
  }, [heatmap, layer]);
  const fillForRegion = useCallback((type, code) => {
    const list = membersFor(type, code);
    if (!list.length) return roleFilter !== 'all' ? '#F1F5F9' : '#FFFFFF';
    // Keep EVERY assigned region coloured — even while painting (focusedUser
    // set) — so overlaps between engineers / sales managers stay visible and
    // the operator can avoid double-covering an area. When a rep is focused,
    // prefer their colour on regions they cover; other regions keep their
    // existing owner colour. Focus emphasis is conveyed by the stroke below.
    const focusMember = focusedUser ? list.find((m) => m.user_id === focusedUser) : null;
    const pick = focusMember || list[0];
    const s = staffById[pick.user_id] || pick;
    return s.colour_hex || '#94A3B8';
  }, [membersFor, focusedUser, roleFilter, staffById]);
  const opacityForRegion = useCallback((type, code) => {
    if (!showHeatmap) return 1;
    if (!heatRange.max) return 0.18;
    const v = (heatmap[type === 'county' ? 'counties' : 'postcode_areas'][code]) || 0;
    if (!v) return 0.18; // empty regions stay readable, never invisible
    return 0.2 + 0.8 * (v / heatRange.max);
  }, [showHeatmap, heatmap, heatRange]);

  // ── Double-coverage detector ──────────────────────────────────────
  // An "overlap" = 2+ reps of the SAME role cover one region (true
  // double-coverage). A rep with role 'both' counts toward BOTH roles.
  // Computed on the full (unfiltered) coverage so the warning is honest
  // regardless of the current role filter.
  const isOverlap = useCallback((type, code) => {
    const list = effectiveList(type, code);
    if (list.length < 2) return false;
    return ['sales_manager', 'engineer'].some(
      (role) => list.filter((m) => m.role === role || m.role === 'both').length >= 2,
    );
  }, [effectiveList]);
  const overlapRegions = useMemo(() => {
    const list = layer === 'county' ? counties : postcodes;
    const codeKey = layer === 'county' ? 'county' : 'area';
    return list
      .map((g) => g.properties && g.properties[codeKey])
      .filter((code) => code && isOverlap(layer, code));
  }, [layer, counties, postcodes, isOverlap]);

  // ── Geometries to render ─────────────────────────────────────────
  const features = layer === 'county' ? counties : postcodes;
  const regionFor = (geo) => {
    const code = layer === 'county' ? geo.properties.county : geo.properties.area;
    return { type: layer, code, label: code };
  };

  const openStaffPinCard = (e, s) => {
    e.stopPropagation();
    const wrap = mapWrapRef.current;
    if (!wrap) return;
    const wrapRect = wrap.getBoundingClientRect();
    const pinRect = e.currentTarget.getBoundingClientRect();
    const left = pinRect.left + pinRect.width / 2 - wrapRect.left;
    const pinTop = pinRect.top - wrapRect.top;
    const above = pinTop > 170; // enough room to show the card above the pin
    setPinCard({
      staff: s,
      left: Math.max(90, Math.min(left, wrapRect.width - 90)),
      top: above ? pinTop - 8 : pinRect.bottom - wrapRect.top + 8,
      above,
    });
  };

  // Close the pin card on outside click or Escape.
  useEffect(() => {
    if (!pinCard) return undefined;
    const onDown = (e) => { if (pinCardRef.current && !pinCardRef.current.contains(e.target)) setPinCard(null); };
    const onKey = (e) => { if (e.key === 'Escape') setPinCard(null); };
    document.addEventListener('mousedown', onDown);
    document.addEventListener('keydown', onKey);
    return () => { document.removeEventListener('mousedown', onDown); document.removeEventListener('keydown', onKey); };
  }, [pinCard]);

  const downloadPng = async () => {
    if (!svgRef.current) return;
    const svg = svgRef.current.querySelector('svg');
    if (!svg) return;
    const xml = new window.XMLSerializer().serializeToString(svg);
    const blob = new Blob([xml], { type: 'image/svg+xml' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    const stamp = new Date().toISOString().slice(0, 10);
    a.href = url; a.download = `uk-territory-coverage-${stamp}.svg`;
    a.click(); URL.revokeObjectURL(url);
  };

  // ── Render ───────────────────────────────────────────────────────
  const focusedCount = focusedUser ? (() => {
    let n = 0;
    Object.values(coverage[layer === 'county' ? 'counties' : 'postcode_areas']).forEach((list) => {
      if (list.some((m) => m.user_id === focusedUser)) n += 1;
    });
    return n;
  })() : null;

  return (
    <div className="max-w-7xl mx-auto px-4 py-3 space-y-3" data-testid="crm-territory-map">
      <header className="flex flex-wrap items-center justify-between gap-2">
        <div className="flex items-center gap-2">
          <div className="inline-flex border border-zinc-200 dark:border-zinc-800 rounded-lg overflow-hidden bg-white dark:bg-zinc-900" data-testid="layer-toggle">
            <button
              type="button"
              onClick={() => setLayer('county')}
              className={`px-3 py-1.5 text-xs font-bold inline-flex items-center gap-1.5 ${layer === 'county' ? 'seg-active' : 'text-zinc-900 dark:text-zinc-100 hover:bg-zinc-100 dark:hover:bg-zinc-800/60'}`}
              data-testid="layer-county"
            >
              <MapIcon size={12} /> Counties
            </button>
            <button
              type="button"
              onClick={() => setLayer('postcode_area')}
              className={`px-3 py-1.5 text-xs font-bold inline-flex items-center gap-1.5 ${layer === 'postcode_area' ? 'seg-active' : 'text-zinc-900 dark:text-zinc-100 hover:bg-zinc-100 dark:hover:bg-zinc-800/60'}`}
              data-testid="layer-postcode"
            >
              <Layers size={12} /> Postcode areas
            </button>
          </div>
          {focusedUser && (
            <span className="inline-flex items-center gap-1.5 text-xs font-semibold text-white bg-blue-600 border border-blue-700 px-2 py-1 rounded-md shadow-sm" data-testid="focus-indicator" title={`Click any county or postcode area to allocate it to ${staffById[focusedUser]?.full_name || 'this person'}. Click an allocated area again to remove them.`}>
              <Paintbrush size={12} /> Painting: {staffById[focusedUser]?.full_name || '?'} · {focusedCount} {layer === 'county' ? 'counties' : 'areas'}
              <button onClick={() => setFocusedUser(null)} className="ml-1 text-blue-100 hover:text-white" data-testid="focus-clear">
                <X size={11} />
              </button>
            </span>
          )}
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          <div className="inline-flex border border-zinc-200 dark:border-zinc-800 rounded-lg overflow-hidden bg-white dark:bg-zinc-900" data-testid="role-filter">
            {[
              { v: 'all', label: 'All roles', Icon: Users },
              { v: 'sales_manager', label: 'Managers', Icon: UserCog },
              { v: 'engineer', label: 'Engineers', Icon: Hammer },
            ].map(({ v, label, Icon }) => (
              <button
                key={v}
                type="button"
                onClick={() => setRoleFilter(v)}
                className={`px-3 py-1.5 text-xs font-bold inline-flex items-center gap-1.5 ${roleFilter === v ? 'seg-active' : 'text-zinc-900 dark:text-zinc-100 hover:bg-zinc-100 dark:hover:bg-zinc-800/60'}`}
                data-testid={`role-filter-${v}`}
              >
                <Icon size={12} /> {label}
              </button>
            ))}
          </div>
          <button
            onClick={() => setShowOffices((v) => !v)}
            className={`px-3 py-1.5 text-xs font-bold border rounded-md inline-flex items-center gap-1.5 ${showOffices ? 'seg-active' : 'border-zinc-200 dark:border-zinc-800 hover:bg-zinc-50 dark:hover:bg-zinc-800/60'}`}
            title="Show or hide office pins on the map."
            data-testid="map-offices-toggle"
          >
            <Building2 size={12} /> Offices
          </button>
          <button
            onClick={() => setShowStaffPins((v) => !v)}
            className={`px-3 py-1.5 text-xs font-bold border rounded-md inline-flex items-center gap-1.5 ${showStaffPins ? 'seg-active' : 'border-zinc-200 dark:border-zinc-800 hover:bg-zinc-50 dark:hover:bg-zinc-800/60'}`}
            title="Show or hide staff location pins (from each person's postcode in the staffing file)."
            data-testid="map-staff-pins-toggle"
          >
            <Users size={12} /> Staff pins
          </button>
          <button
            onClick={runAutoAssign}
            disabled={autoAssigning}
            className="px-3 py-1.5 text-xs font-bold border border-zinc-200 dark:border-zinc-800 rounded-md hover:bg-zinc-50 dark:hover:bg-zinc-800/60 inline-flex items-center gap-1.5 disabled:opacity-50"
            title="Push every region's coverage onto unassigned companies, deals and tenders."
            data-testid="map-auto-assign"
          >
            <Zap size={12} className={autoAssigning ? 'animate-pulse' : ''} /> {autoAssigning ? 'Assigning…' : 'Auto-assign'}
          </button>
          <button
            onClick={() => setShowHeatmap((v) => !v)}
            className={`px-3 py-1.5 text-xs font-bold border rounded-md inline-flex items-center gap-1.5 ${showHeatmap ? 'bg-amber-500 border-amber-500 text-white' : 'border-zinc-200 dark:border-zinc-800 hover:bg-zinc-50 dark:hover:bg-zinc-800/60'}`}
            title="Shade regions by open pipeline + tender value."
            data-testid="map-heatmap-toggle"
          >
            <Flame size={12} /> {showHeatmap ? 'Heatmap on' : 'Heatmap'}
          </button>
          <button
            onClick={() => setShowOverlaps((v) => !v)}
            className={`px-3 py-1.5 text-xs font-bold border rounded-md inline-flex items-center gap-1.5 ${showOverlaps ? 'bg-rose-600 border-rose-600 text-white' : 'border-zinc-200 dark:border-zinc-800 hover:bg-zinc-50 dark:hover:bg-zinc-800/60'}`}
            title="Flag regions covered by 2 or more reps of the same role (double-coverage)."
            data-testid="map-overlaps-toggle"
          >
            <AlertTriangle size={12} /> {showOverlaps ? 'Overlaps on' : 'Overlaps'}
            {overlapRegions.length > 0 && (
              <span
                className={`ml-0.5 inline-flex items-center justify-center min-w-[16px] h-4 px-1 rounded-full text-[10px] font-extrabold ${showOverlaps ? 'bg-white text-rose-700' : 'bg-rose-600 text-white'}`}
                data-testid="overlap-count"
              >
                {overlapRegions.length}
              </span>
            )}
          </button>
          <button
            onClick={loadCoverage}
            className="px-3 py-1.5 text-xs font-bold border border-zinc-200 dark:border-zinc-800 rounded-md hover:bg-zinc-50 dark:hover:bg-zinc-800/60 inline-flex items-center gap-1.5"
            data-testid="map-refresh"
          >
            <RefreshCw size={12} /> Refresh
          </button>
          <button
            onClick={downloadPng}
            className="px-3 py-1.5 text-xs font-bold border border-zinc-200 dark:border-zinc-800 rounded-md hover:bg-zinc-50 dark:hover:bg-zinc-800/60 inline-flex items-center gap-1.5"
            data-testid="map-download"
          >
            <Download size={12} /> Export SVG
          </button>
        </div>
      </header>

      <div className="grid lg:grid-cols-[1fr_320px] gap-4">
        <div className="relative" ref={mapWrapRef}>
        <div className="rounded-xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 overflow-hidden" ref={svgRef} data-testid="territory-map-svg">
          {loading ? (
            <div className="h-[600px] flex items-center justify-center text-zinc-400 text-sm">Loading map…</div>
          ) : (
            <ComposableMap
              projection="geoMercator"
              projectionConfig={{ center: [-3.5, 54.5], scale: 2400 }}
              width={720} height={780}
              style={{ width: '100%', height: 'auto' }}
            >
              <defs>
                <pattern id="overlap-hatch" width="6" height="6" patternTransform="rotate(45)" patternUnits="userSpaceOnUse">
                  {/* eslint-disable-next-line gymaxis/no-inline-hex */}
                  <rect width="6" height="6" fill="#DC2626" fillOpacity="0.08" />
                  {/* eslint-disable-next-line gymaxis/no-inline-hex */}
                  <line x1="0" y1="0" x2="0" y2="6" stroke="#DC2626" strokeWidth="1.5" strokeOpacity="0.6" />
                </pattern>
              </defs>
              <Geographies geography={{ type: 'FeatureCollection', features }}>
                {({ geographies }) => geographies.map((geo) => {
                  const region = regionFor(geo);
                  const fill = fillForRegion(region.type, region.code);
                  const list = membersFor(region.type, region.code);
                  const hasAssignees = list.length > 0;
                  const overlap = showOverlaps && isOverlap(region.type, region.code);
                  // Highlight the regions the focused rep covers with a bolder,
                  // darker outline so you can tell "theirs" apart while still
                  // seeing everyone else's colours.
                  const isFocus = focusedUser && list.some((m) => m.user_id === focusedUser);
                  const detail = hasAssignees
                    ? coverageDetail(region.type, region.code).filter((m) => roleMatch(m.role))
                    : [];
                  const tooltip = hasAssignees
                    ? `${region.label} — ${detail.map((m) => (m.direct ? m.full_name : `${m.full_name} (via ${m.via})`)).join(', ')}${overlap ? ' ⚠ double-covered' : ''}`
                    : region.label;
                  return (
                    <g key={geo.rsmKey}>
                      <Geography
                        geography={geo}
                        onClick={() => { if (focusedUser) paintRegion(region, focusedUser); else setActiveRegion({ ...region, centroid: geoCentroid(geo) }); }}
                        style={{
                          // SVG stroke colours — visual data, not theme tokens.
                          /* eslint-disable gymaxis/no-inline-hex -- SVG stroke literals */
                          default:  { fill, fillOpacity: opacityForRegion(region.type, region.code), stroke: overlap ? '#DC2626' : (isFocus ? '#0F172A' : '#94A3B8'), strokeWidth: overlap ? 1.6 : (isFocus ? 1.3 : 0.4), outline: 'none', cursor: 'pointer' },
                          hover:    { fill: hasAssignees ? fill : '#E2E8F0', fillOpacity: 1, stroke: overlap ? '#B91C1C' : '#1E293B', strokeWidth: overlap ? 1.8 : 0.9, outline: 'none', cursor: 'pointer' },
                          pressed:  { fill, fillOpacity: 1, stroke: '#0F172A', strokeWidth: 1.1, outline: 'none' },
                          /* eslint-enable gymaxis/no-inline-hex */
                        }}
                        data-testid={`region-${region.type}-${region.code}`}
                      >
                        <title>{tooltip}</title>
                      </Geography>
                      {overlap && (
                        <Geography
                          geography={geo}
                          style={{
                            /* eslint-disable gymaxis/no-inline-hex */
                            default: { fill: 'url(#overlap-hatch)', stroke: '#DC2626', strokeWidth: 1.6, outline: 'none', pointerEvents: 'none' },
                            hover:   { fill: 'url(#overlap-hatch)', stroke: '#B91C1C', strokeWidth: 1.8, outline: 'none', pointerEvents: 'none' },
                            pressed: { fill: 'url(#overlap-hatch)', stroke: '#DC2626', strokeWidth: 1.6, outline: 'none', pointerEvents: 'none' },
                            /* eslint-enable gymaxis/no-inline-hex */
                          }}
                          data-testid={`region-overlap-${region.type}-${region.code}`}
                        />
                      )}
                    </g>
                  );
                })}
              </Geographies>
              {showOffices && offices.map((o) => (
                <Marker key={o.id} coordinates={[o.lng, o.lat]} data-testid={`office-marker-${o.id}`}>
                  <g style={{ pointerEvents: 'none' }}>
                    <circle r={5} fill={o.colour_hex || '#0F172A'} stroke="#FFFFFF" strokeWidth={1.4} />
                    <text textAnchor="middle" y={-9} fontSize={9} fontWeight="700" fill="#0F172A" stroke="#FFFFFF" strokeWidth={2.4} paintOrder="stroke">{o.name}</text>
                  </g>
                </Marker>
              ))}
              {showStaffPins && staffLocations.filter((s) => roleMatch(s.territory_role)).map((s) => {
                const dim = focusedUser && focusedUser !== s.id;
                const firstName = (s.full_name || '').split(' ')[0] || s.full_name;
                return (
                  <Marker key={s.id} coordinates={[s.lng, s.lat]} data-testid={`staff-marker-${s.id}`}>
                    <g
                      style={{ pointerEvents: 'auto', cursor: 'pointer', opacity: dim ? 0.35 : 1 }}
                      onClick={(e) => openStaffPinCard(e, s)}
                    >
                      {/* Teardrop pin — distinct from the circular office pins */}
                      <path
                        d="M0 0 C-4.4 -6 -6 -8.4 -6 -11.4 A6 6 0 1 1 6 -11.4 C6 -8.4 4.4 -6 0 0 Z"
                        fill={s.colour_hex || '#2563EB'}
                        stroke="#FFFFFF"
                        strokeWidth={1.4}
                      />
                      <circle cy={-11.4} r={2.4} fill="#FFFFFF" />
                      <text textAnchor="middle" y={9} fontSize={8.5} fontWeight="700" fill="#0F172A" stroke="#FFFFFF" strokeWidth={2.2} paintOrder="stroke">{firstName}</text>
                    </g>
                  </Marker>
                );
              })}
            </ComposableMap>
          )}
        </div>
        {pinCard && (() => {
          const s = pinCard.staff;
          const RoleIcon = ROLE_ICONS[s.territory_role] || UserCog;
          return (
            <div
              ref={pinCardRef}
              className="absolute z-30 w-60 rounded-xl border border-zinc-200 dark:border-zinc-700 bg-white dark:bg-zinc-900 shadow-2xl p-3"
              style={{
                left: pinCard.left,
                top: pinCard.top,
                transform: pinCard.above ? 'translate(-50%, -100%)' : 'translate(-50%, 0)',
              }}
              data-testid="staff-pin-card"
            >
              <button
                onClick={() => setPinCard(null)}
                className="absolute top-2 right-2 text-zinc-400 hover:text-zinc-700 dark:hover:text-zinc-200"
                aria-label="Close"
                data-testid="staff-pin-card-close"
              >
                <X size={14} />
              </button>
              <div className="flex items-center gap-2 pr-5">
                <span className="h-3.5 w-3.5 rounded-full flex-shrink-0" style={{ backgroundColor: s.colour_hex || '#2563EB' }} />
                <p className="text-sm font-bold text-zinc-900 dark:text-zinc-100 truncate" data-testid="staff-pin-card-name">{s.full_name}</p>
              </div>
              <div className="mt-2 flex items-center gap-1.5 text-xs text-zinc-600 dark:text-zinc-300">
                <RoleIcon size={13} className="text-zinc-400" />
                <span data-testid="staff-pin-card-role">{ROLE_LABELS[s.territory_role] || s.territory_role}</span>
              </div>
              {s.postcode && (
                <div className="mt-1 flex items-center gap-1.5 text-xs text-zinc-600 dark:text-zinc-300">
                  <MapPin size={13} className="text-zinc-400" />
                  <span data-testid="staff-pin-card-postcode">{s.postcode}</span>
                </div>
              )}
              {s.email && (
                <a href={`mailto:${s.email}`} className="mt-1 block text-xs text-blue-600 hover:underline truncate" data-testid="staff-pin-card-email">{s.email}</a>
              )}
              <button
                onClick={() => window.open('/platform/staffing', '_blank', 'noopener')}
                className="mt-3 w-full inline-flex items-center justify-center gap-1.5 rounded-lg bg-zinc-900 dark:bg-zinc-100 dark:text-zinc-900 text-white text-xs font-bold py-1.5 hover:opacity-90"
                data-testid="staff-pin-card-profile"
              >
                View profile <ExternalLink size={12} />
              </button>
            </div>
          );
        })()}
        </div>

        <aside className="space-y-3">
          <div className="rounded-xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 p-3">
            <div className="flex items-center justify-between mb-2">
              <p className="text-[10px] uppercase tracking-wider text-zinc-500 font-bold">Sales team · {staff.length}</p>
              {focusedUser && (
                <button onClick={() => setFocusedUser(null)} className="text-[10px] text-blue-600 hover:underline font-semibold" data-testid="clear-focus-side">
                  Clear focus
                </button>
              )}
            </div>
            <p className="text-[11px] text-zinc-500 mb-2">
              Click a person to select them, then click counties or postcode areas on the map to allocate that area to them. Click an allocated area again to remove it. Click a colour swatch to recolour a person.
            </p>
            <div className="space-y-1 max-h-[520px] overflow-y-auto" data-testid="staff-list">
              {visibleStaff.length === 0 && <p className="text-xs text-zinc-400 italic py-2">{staff.length === 0 ? 'No CRM users yet — add reps in People first.' : 'No people match this role filter.'}</p>}
              {visibleStaff.map((s) => (
                <StaffRow
                  key={s.id}
                  s={s}
                  focused={focusedUser === s.id}
                  onFocus={(uid) => setFocusedUser(uid)}
                  onColour={saveStaffColour}
                  onRole={saveStaffRole}
                />
              ))}
            </div>
          </div>
          <OfficesPanel offices={offices} onChange={loadOffices} />
          <div className="rounded-xl border border-dashed border-zinc-200 dark:border-zinc-800 bg-zinc-50/60 dark:bg-zinc-900/60 p-3 text-[11px] text-zinc-500 dark:text-zinc-400 leading-relaxed">
            <p className="font-semibold text-zinc-700 dark:text-zinc-300 mb-1">How coverage resolves</p>
            <p>
              Postcode-area assignments override county assignments — so you can paint Greater London to
              one manager, then override SW1 to a different engineer for that single postcode area.
            </p>
          </div>
        </aside>
      </div>

      <RegionDrawer
        region={activeRegion}
        staff={staff}
        offices={offices}
        coverage={layer === 'county' ? coverage.counties : coverage.postcode_areas}
        onClose={() => setActiveRegion(null)}
        onSave={saveRegion}
      />
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import axios from 'axios';
import {
  Radio, Save, Search, Download, Filter, MapPin, Gauge, AlertTriangle,
  CheckCircle, Clock, CalendarClock, FileCheck2, ChevronUp, ChevronDown, ClipboardList,
  FileSpreadsheet,
} from 'lucide-react';
import Button from '@/components/shared/Button';
import BlueLightImportPanel from './BlueLightImportPanel';

const STATUS_META = {
  not_planned: { label: 'Not Planned', color: 'var(--color-text-faint-alt)' },
  planned: { label: 'Planned', color: 'var(--color-accent-violet)' },
  scheduled: { label: 'Scheduled', color: 'var(--color-info-ios)' },
  travelling: { label: 'Travelling', color: 'var(--color-accent-amber)' },
  on_site: { label: 'On Site', color: 'var(--color-accent-amber)' },
  in_progress: { label: 'In Progress', color: 'var(--color-accent-amber)' },
  awaiting_information: { label: 'Awaiting Info', color: 'var(--color-accent-amber)' },
  follow_up_required: { label: 'Follow-up', color: 'var(--color-warning)' },
  completed: { label: 'Completed', color: 'var(--color-success-alt)' },
  certificate_generated: { label: 'Cert Generated', color: 'var(--color-success-alt-2)' },
  certificate_sent: { label: 'Cert Sent', color: 'var(--color-success-alt)' },
  overdue: { label: 'Overdue', color: 'var(--color-danger)' },
};

const StatusPill = ({ status }) => {
  const m = STATUS_META[status] || { label: status || '—', color: 'var(--color-text-faint-alt)' };
  return (
    <span data-testid={`bl-status-${status}`} className="px-2 py-0.5 rounded-full text-[11px] font-semibold whitespace-nowrap"
      style={{ background: m.color + '22', color: m.color }}>{m.label}</span>
  );
};

const CELL_META = {
  'n/a': { label: 'N/A', color: 'var(--color-text-faint-alt)' },
  pending: { label: 'Pending', color: 'var(--color-accent-amber)' },
  in_progress: { label: 'In progress', color: 'var(--color-accent-amber)' },
  complete: { label: 'Complete', color: 'var(--color-success-alt)' },
  passed: { label: 'Passed', color: 'var(--color-success-alt)' },
  outstanding: { label: 'Outstanding', color: 'var(--color-text-faint-alt)' },
  generated: { label: 'Generated', color: 'var(--color-success-alt-2)' },
  sent: { label: 'Sent', color: 'var(--color-success-alt)' },
  awaiting_review: { label: 'Awaiting review', color: 'var(--color-accent-amber)' },
  send_failed: { label: 'Send failed', color: 'var(--color-danger)' },
  approved: { label: 'Approved', color: 'var(--color-success-alt)' },
  reverted: { label: 'Reverted', color: 'var(--color-text-faint-alt)' },
  removed: { label: 'Removed', color: 'var(--color-danger)' },
  rejected: { label: 'Rejected', color: 'var(--color-text-faint-alt)' },
};

const CellPill = ({ value }) => {
  const m = CELL_META[value] || { label: value || '—', color: 'var(--color-text-faint-alt)' };
  return (
    <span className="px-2 py-0.5 rounded-full text-[11px] font-medium whitespace-nowrap"
      style={{ background: m.color + '1f', color: m.color }}>{m.label}</span>
  );
};

function StatTile({ label, value, sub, icon: Icon, color, testId }) {
  return (
    <div data-testid={testId} className="rounded-xl p-3 border" style={{ borderColor: 'var(--color-border)', background: 'var(--color-surface)' }}>
      <div className="flex items-center justify-between">
        <span className="text-[11px] uppercase tracking-wide" style={{ color: 'var(--color-text-muted)' }}>{label}</span>
        {Icon && <Icon size={14} style={{ color: color || 'var(--color-text-muted)' }} />}
      </div>
      <div className="text-2xl font-bold mt-1" style={{ color: color || 'var(--color-text)' }}>{value}</div>
      {sub && <div className="text-[11px] mt-0.5" style={{ color: 'var(--color-text-muted)' }}>{sub}</div>}
    </div>
  );
}

export default function BlueLightTab({ contract, contractId, API, headers, c, reload }) {
  const [overview, setOverview] = useState(null);
  const [stations, setStations] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [certStatusFilter, setCertStatusFilter] = useState('');
  const [sort, setSort] = useState('station_name');
  const [direction, setDirection] = useState('asc');
  const [saving, setSaving] = useState(false);
  const [showConfig, setShowConfig] = useState(false);
  const [meta, setMeta] = useState(null);
  const [cfg, setCfg] = useState(null);
  const [certs, setCerts] = useState(null);
  const [showCerts, setShowCerts] = useState(false);
  const [recon, setRecon] = useState(null);
  const [showRecon, setShowRecon] = useState(false);
  const [showImport, setShowImport] = useState(false);
  const [engineers, setEngineers] = useState([]);
  const [selected, setSelected] = useState(() => new Set());
  const [planDate, setPlanDate] = useState('');
  const [planWindowEnd, setPlanWindowEnd] = useState('');
  const [planEngineer, setPlanEngineer] = useState('');
  const [planning, setPlanning] = useState(false);
  const [planMsg, setPlanMsg] = useState(null);

  const isBL = !!(contract?.is_blue_light);

  const loadOverview = useCallback(async () => {
    try {
      const [ov, mt] = await Promise.all([
        axios.get(`${API}/crm/v2/contracts/${contractId}/overview`, { headers: headers() }),
        axios.get(`${API}/crm/v2/blue-light/customer-types`, { headers: headers() }),
      ]);
      setOverview(ov.data);
      setMeta(mt.data);
      setCfg({ ...(mt.data.defaults || {}), ...(ov.data.contract?.blue_light || {}) });
    } catch (e) { /* noop */ }
  }, [API, headers, contractId]);

  const loadStations = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams({ search: debouncedSearch, status: statusFilter, cert_status: certStatusFilter, sort, direction });
      const res = await axios.get(`${API}/crm/v2/contracts/${contractId}/stations?${params}`, { headers: headers() });
      setStations(res.data.stations || []);
    } catch (e) { setStations([]); } finally { setLoading(false); }
  }, [API, headers, contractId, debouncedSearch, statusFilter, certStatusFilter, sort, direction]);

  useEffect(() => { loadOverview(); }, [loadOverview]);
  useEffect(() => {
    const t = setTimeout(() => setDebouncedSearch(search), 300);
    return () => clearTimeout(t);
  }, [search]);
  useEffect(() => { if (isBL) loadStations(); }, [isBL, loadStations]);
  const loadEngineers = useCallback(() => {
    axios.get(`${API}/crm/v2/contracts/${contractId}/engineers`, { headers: headers() })
      .then(r => setEngineers(r.data.engineers || [])).catch(() => setEngineers([]));
  }, [API, headers, contractId]);
  useEffect(() => { if (isBL) loadEngineers(); }, [isBL, loadEngineers]);

  const toggleRow = (id) => setSelected(prev => {
    const n = new Set(prev); n.has(id) ? n.delete(id) : n.add(id); return n;
  });
  const allSelected = stations.length > 0 && stations.every(r => selected.has(r.site_id));
  const toggleAll = () => setSelected(allSelected ? new Set() : new Set(stations.map(r => r.site_id)));
  const clearSel = () => setSelected(new Set());

  const refreshAll = async () => { await Promise.all([loadOverview(), loadStations()]); loadEngineers(); loadCerts(); };

  const loadCerts = useCallback(() => {
    axios.get(`${API}/crm/v2/contracts/${contractId}/certificates`, { headers: headers() })
      .then(r => setCerts(r.data)).catch(() => setCerts({ certificates: [], by_status: {} }));
  }, [API, headers, contractId]);
  useEffect(() => { if (isBL) loadCerts(); }, [isBL, loadCerts]);

  const loadRecon = useCallback(() => {
    axios.get(`${API}/crm/v2/contracts/${contractId}/asset-changes`, { headers: headers() })
      .then(r => setRecon(r.data)).catch(() => setRecon({ items: [], counts: {} }));
  }, [API, headers, contractId]);
  useEffect(() => { if (isBL) loadRecon(); }, [isBL, loadRecon]);

  const reviewChange = async (item, action) => {
    try {
      const r = await axios.post(`${API}/crm/v2/contracts/${contractId}/asset-changes/review`,
        { item_id: item.id, action }, { headers: headers() });
      const n = r.data?.notification;
      if (n) {
        if (n.ok) alert(`Transfer approved. Office notified: ${(n.recipients || []).join(', ')}`);
        else alert(`Transfer approved and stations updated. Email could not be sent (${n.error || 'unknown'}) — it will send once a live email key is configured.`);
      }
      loadRecon(); loadOverview();
    } catch (e) { alert(e.response?.data?.detail || 'Review failed'); }
  };

  const downloadCert = (cert) => {
    axios.get(`${API}/crm/v2/certificates/${cert.id}/download`, { headers: headers(), responseType: 'blob' })
      .then(res => {
        const a = document.createElement('a');
        a.href = URL.createObjectURL(new Blob([res.data], { type: 'application/pdf' }));
        a.download = cert.filename || 'certificate.pdf'; a.click(); URL.revokeObjectURL(a.href);
      }).catch(() => alert('Could not download the certificate.'));
  };
  const approveCert = async (cert) => {
    try {
      const r = await axios.post(`${API}/crm/v2/certificates/${cert.id}/approve`, {}, { headers: headers() });
      alert(r.data.success ? `Certificate sent to ${(r.data.recipients || []).join(', ')}.` : `Send failed: ${r.data.error || 'unknown'}`);
      loadCerts(); loadOverview();
    } catch (e) { alert(e.response?.data?.detail || 'Approve/send failed'); }
  };

  const planVisits = async (force = false) => {
    if (!planDate) { alert('Choose a scheduled date first.'); return; }
    setPlanning(true); setPlanMsg(null);
    try {
      const eng = engineers.find(e => e.id === planEngineer);
      const res = await axios.post(`${API}/crm/v2/contracts/${contractId}/plan-visits`, {
        site_ids: Array.from(selected), scheduled_date: planDate,
        service_window_end: planWindowEnd, engineer_id: planEngineer,
        engineer_name: eng?.full_name || '', force,
      }, { headers: headers() });
      const d = res.data;
      setPlanMsg({ created: d.created_count, skipped: d.skipped || [], cycle: d.cycle_label });
      clearSel();
      await refreshAll();
    } catch (e) { alert(e.response?.data?.detail || 'Failed to plan visits'); }
    finally { setPlanning(false); }
  };

  const reassign = async () => {
    if (!planEngineer) { alert('Pick an engineer to reassign to.'); return; }
    setPlanning(true); setPlanMsg(null);
    try {
      const eng = engineers.find(e => e.id === planEngineer);
      const res = await axios.post(`${API}/crm/v2/contracts/${contractId}/reassign-visits`, {
        site_ids: Array.from(selected), engineer_id: planEngineer, engineer_name: eng?.full_name || '',
      }, { headers: headers() });
      setPlanMsg({ reassigned: res.data.updated, engineer: res.data.engineer_name });
      clearSel();
      await refreshAll();
    } catch (e) { alert(e.response?.data?.detail || 'Failed to reassign'); }
    finally { setPlanning(false); }
  };

  const saveConfig = async (extra = {}) => {
    setSaving(true);
    try {
      await axios.put(`${API}/crm/v2/contracts/${contractId}/blue-light-config`,
        { ...cfg, ...extra }, { headers: headers() });
      await loadOverview();
      if (reload) await reload();
      setShowConfig(false);
    } catch (e) { alert(e.response?.data?.detail || 'Failed to save configuration'); }
    finally { setSaving(false); }
  };

  const setSortCol = (col) => {
    if (sort === col) setDirection(direction === 'asc' ? 'desc' : 'asc');
    else { setSort(col); setDirection('asc'); }
  };

  const exportCsv = () => {
    axios.get(`${API}/crm/v2/contracts/${contractId}/stations.csv`, { headers: headers(), responseType: 'blob' }).then(res => {
      const blob = new Blob([res.data], { type: 'text/csv' });
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = `stations-${contractId.slice(0, 8)}.csv`;
      a.click();
      URL.revokeObjectURL(a.href);
    }).catch(() => alert('Could not export the station list. Please try again.'));
  };

  const s = overview?.stats || {};
  const stationCols = [
    ['station_name', 'Station'], ['address', 'Address'], ['contact_name', 'Contact'],
    ['telephone', 'Tel'], ['asset_count', 'Assets'], ['treadmill_count', 'Treadmills'],
    ['next_service_due', 'Next Due'], ['scheduled_date', 'Scheduled'],
    ['assigned_engineer_name', 'Engineer'], ['visit_status', 'Visit'],
    ['calibration_status', 'Calibration'], ['faults_raised', 'Faults'],
    ['certificate_status', 'Certificate'],
  ];

  if (!isBL) {
    return (
      <div data-testid="bl-enable-panel" className="max-w-2xl mx-auto text-center py-10">
        <Radio size={40} className="mx-auto mb-4" style={{ color: 'var(--color-info-ios)' }} />
        <h3 className="text-lg font-bold mb-2" style={{ color: c.text }}>Blue Light / Multi-Site PTE Service</h3>
        <p className="text-sm mb-6" style={{ color: c.textMuted }}>
          Turn this contract into a multi-site physical training equipment service programme — station
          service matrix, treadmill calibration and automatic certificates. Configurable per contract.
        </p>
        {meta && cfg && (
          <div className="text-left rounded-xl border p-4 mb-4" style={{ borderColor: c.border, background: 'var(--color-surface)' }}>
            <ConfigForm cfg={cfg} setCfg={setCfg} meta={meta} c={c} API={API} headers={headers} contractId={contractId} />
          </div>
        )}
        <Button onClick={() => saveConfig()} disabled={saving} icon={CheckCircle} data-testid="bl-enable-btn">
          {saving ? 'Enabling…' : 'Enable Blue Light Service'}
        </Button>
        <div className="mt-3">
          <button className="text-[12px] underline" data-testid="bl-enable-import"
            style={{ color: 'var(--color-info-ios)' }}
            onClick={async () => { await saveConfig(); setShowImport(true); }}>
            or enable &amp; import stations &amp; assets from a spreadsheet
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-5" data-testid="bl-tab">
      {/* Overview stats */}
      <div className="flex items-center justify-between">
        <h3 className="text-sm font-bold flex items-center gap-2" style={{ color: c.text }}>
          <Radio size={16} style={{ color: 'var(--color-info-ios)' }} /> Contract Overview
          <span className="text-[11px] font-normal" style={{ color: c.textMuted }}>
            · {meta?.customer_types?.find(t => t.id === overview?.contract?.customer_type)?.name || 'Blue Light'}
          </span>
        </h3>
        <Button variant="ghost" size="sm" icon={Filter} onClick={() => setShowConfig(v => !v)} data-testid="bl-config-toggle">
          Configure
        </Button>
      </div>

      <div className="flex justify-end -mt-2 gap-2">
        <Button variant="ghost" size="sm" icon={FileSpreadsheet} onClick={() => setShowImport(v => !v)} data-testid="bl-import-toggle">
          Import
        </Button>
        <Button variant="ghost" size="sm" icon={ClipboardList} onClick={() => setShowRecon(v => !v)} data-testid="bl-recon-toggle">
          Asset Changes{recon?.counts?.pending ? ` (${recon.counts.pending})` : ''}
        </Button>
        <Button variant="ghost" size="sm" icon={FileCheck2} onClick={() => setShowCerts(v => !v)} data-testid="bl-certs-toggle">
          Certificates{certs?.count ? ` (${certs.count})` : ''}
        </Button>
      </div>

      {showImport && (
        <BlueLightImportPanel API={API} headers={headers} contractId={contractId} c={c}
          onImported={() => { refreshAll(); }} />
      )}

      {showRecon && (
        <div className="rounded-xl border p-4" style={{ borderColor: c.border, background: 'var(--color-surface)' }} data-testid="bl-recon-panel">
          <div className="flex items-center gap-2 mb-2 text-sm font-bold" style={{ color: c.text }}>
            <ClipboardList size={15} style={{ color: 'var(--color-accent-violet)' }} /> Asset Changes From Service Visits
          </div>
          <div className="flex flex-wrap gap-3 mb-3">
            {[['new', 'New found'], ['correction', 'Corrections'], ['not_found', 'Not found'], ['transfer', 'Transfers'], ['pending', 'Awaiting review']].map(([k, l]) => (
              <div key={k} className="text-center px-3 py-1.5 rounded-lg" style={{ background: 'var(--color-bg)' }} data-testid={`bl-recon-count-${k}`}>
                <div className="text-lg font-bold" style={{ color: c.text }}>{recon?.counts?.[k] || 0}</div>
                <div className="text-[10px]" style={{ color: c.textMuted }}>{l}</div>
              </div>
            ))}
          </div>
          {(!recon || recon.items.length === 0) ? (
            <div className="text-sm text-center py-4" style={{ color: c.textMuted }} data-testid="bl-recon-empty">No asset changes recorded yet.</div>
          ) : (
            <div className="divide-y" style={{ borderColor: c.border }}>
              {recon.items.map(it => {
                const kindColor = { new: 'var(--color-success-alt-2)', correction: 'var(--color-accent-amber)', not_found: 'var(--color-danger)', transfer: 'var(--color-info-ios)' }[it.kind];
                return (
                  <div key={it.id} className="flex items-center justify-between py-2 gap-2" data-testid={`bl-recon-row-${it.id}`}>
                    <div className="min-w-0">
                      <div className="flex items-center gap-2">
                        <span className="text-[10px] px-1.5 py-0.5 rounded-full font-semibold uppercase" style={{ background: kindColor + '22', color: kindColor }}>{it.kind.replace('_', ' ')}</span>
                        <span className="text-sm font-medium truncate" style={{ color: c.text }}>{it.station_name}</span>
                      </div>
                      <div className="text-[11px] mt-0.5 truncate" style={{ color: c.textMuted }}>{it.detail}</div>
                    </div>
                    <div className="flex items-center gap-2 flex-shrink-0">
                      {['pending', 'auto_approved'].includes(it.review_status) ? (
                        <>
                          <Button size="sm" onClick={() => reviewChange(it, 'approve')} data-testid={`bl-recon-approve-${it.id}`}>Approve</Button>
                          <Button size="sm" variant="outline" onClick={() => reviewChange(it, 'revert')} data-testid={`bl-recon-revert-${it.id}`}>Revert</Button>
                        </>
                      ) : <CellPill value={it.review_status} />}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {showCerts && (
        <div className="rounded-xl border p-4" style={{ borderColor: c.border, background: 'var(--color-surface)' }} data-testid="bl-certs-panel">
          <div className="flex flex-wrap gap-3 mb-3">
            {[['generated', 'Generated'], ['sent', 'Sent'], ['awaiting_review', 'Awaiting review'], ['send_failed', 'Failed to send']].map(([k, l]) => (
              <div key={k} className="text-center px-3 py-1.5 rounded-lg" style={{ background: 'var(--color-bg)' }} data-testid={`bl-cert-count-${k}`}>
                <div className="text-lg font-bold" style={{ color: c.text }}>{certs?.by_status?.[k] || 0}</div>
                <div className="text-[10px]" style={{ color: c.textMuted }}>{l}</div>
              </div>
            ))}
          </div>
          {(!certs || certs.certificates.length === 0) ? (
            <div className="text-sm text-center py-4" style={{ color: c.textMuted }} data-testid="bl-certs-empty">No certificates yet — complete a station visit to generate one.</div>
          ) : (
            <div className="divide-y" style={{ borderColor: c.border }}>
              {certs.certificates.map(cert => (
                <div key={cert.id} className="flex items-center justify-between py-2 gap-2" data-testid={`bl-cert-row-${cert.id}`}>
                  <div className="min-w-0">
                    <div className="text-sm font-medium truncate" style={{ color: c.text }}>{cert.station_name}</div>
                    <div className="text-[11px]" style={{ color: c.textMuted }}>{cert.filename}</div>
                  </div>
                  <div className="flex items-center gap-2 flex-shrink-0">
                    <CellPill value={cert.status} />
                    <Button variant="ghost" size="sm" icon={Download} onClick={() => downloadCert(cert)} data-testid={`bl-cert-download-${cert.id}`}>PDF</Button>
                    {cert.status === 'awaiting_review' && (
                      <Button size="sm" onClick={() => approveCert(cert)} data-testid={`bl-cert-approve-${cert.id}`}>Approve &amp; send</Button>
                    )}
                    {cert.status === 'send_failed' && (
                      <Button size="sm" variant="outline" onClick={() => approveCert(cert)} data-testid={`bl-cert-retry-${cert.id}`}>Retry send</Button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {showConfig && meta && cfg && (
        <div className="rounded-xl border p-4" style={{ borderColor: c.border, background: 'var(--color-surface)' }} data-testid="bl-config-panel">
          <ConfigForm cfg={cfg} setCfg={setCfg} meta={meta} c={c} API={API} headers={headers} contractId={contractId} />
          <div className="flex justify-end mt-3">
            <Button onClick={() => saveConfig()} disabled={saving} icon={Save} data-testid="bl-config-save">
              {saving ? 'Saving…' : 'Save Configuration'}
            </Button>
          </div>
        </div>
      )}

      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        <StatTile label="Stations" value={s.sites || 0} icon={MapPin} testId="bl-stat-sites"
          sub={`${s.assets || 0} assets · ${s.treadmills || 0} treadmills`} />
        <StatTile label="Completed" value={s.visits_completed || 0} icon={CheckCircle} color="var(--color-success-alt)"
          sub={`${s.completion_pct || 0}% of programme`} testId="bl-stat-completed" />
        <StatTile label="Scheduled" value={s.visits_scheduled || 0} icon={CalendarClock} color="var(--color-info-ios)"
          sub={`${s.visits_awaiting_booking || 0} awaiting booking`} testId="bl-stat-scheduled" />
        <StatTile label="Overdue" value={s.visits_overdue || 0} icon={AlertTriangle} color="var(--color-danger)"
          sub={s.next_planned_service_date ? `next ${s.next_planned_service_date}` : 'none planned'} testId="bl-stat-overdue" />
        <StatTile label="Certificates" value={`${s.certificates_completed || 0}/${s.sites || 0}`} icon={FileCheck2}
          color="var(--color-success-alt-2)" sub={`${s.certificates_sent || 0} sent`} testId="bl-stat-certs" />
        <StatTile label="Open Faults" value={s.open_faults || 0} icon={AlertTriangle} color="var(--color-warning)" testId="bl-stat-faults" />
        <StatTile label="Follow-ups" value={s.follow_ups_required || 0} icon={Clock} color="var(--color-accent-amber)" testId="bl-stat-followups" />
        <StatTile label="Service Every" value={`${s.service_frequency_months || 6} mo`} icon={Gauge} testId="bl-stat-freq" />
      </div>

      {/* Certificate tracker (§33) — click a tile to filter the matrix */}
      {(() => {
        const cb = s.certificates_breakdown || {};
        const tiles = [
          ['', 'All stations', cb.total_stations ?? s.sites ?? 0, 'var(--color-text)'],
          ['generated', 'Generated', cb.generated || 0, 'var(--color-success-alt-2)'],
          ['sent', 'Sent', cb.sent || 0, 'var(--color-success-alt)'],
          ['awaiting_review', 'Awaiting review', cb.awaiting_review || 0, 'var(--color-accent-amber)'],
          ['send_failed', 'Failed to send', cb.send_failed || 0, 'var(--color-danger)'],
          ['outstanding', 'No certificate', cb.outstanding || 0, 'var(--color-danger)'],
        ];
        return (
          <div className="rounded-xl border p-3" style={{ borderColor: c.border, background: 'var(--color-surface)' }} data-testid="bl-cert-tracker">
            <div className="flex items-center gap-2 mb-2 text-sm font-bold" style={{ color: c.text }}>
              <FileCheck2 size={15} style={{ color: 'var(--color-success-alt-2)' }} /> Certificate Tracker
              <span className="text-[11px] font-normal" style={{ color: c.textMuted }}>· click to find stations instantly</span>
            </div>
            <div className="grid grid-cols-3 md:grid-cols-6 gap-2">
              {tiles.map(([key, label, val, color]) => (
                <button key={key || 'all'} data-testid={`bl-cert-track-${key || 'all'}`}
                  onClick={() => { setCertStatusFilter(key); setStatusFilter(''); }}
                  className="rounded-lg p-2 text-center transition-transform active:scale-95"
                  style={{ background: certStatusFilter === key ? color + '26' : 'var(--color-bg)', border: certStatusFilter === key ? `1px solid ${color}` : '1px solid transparent' }}>
                  <div className="text-xl font-bold" style={{ color }}>{val}</div>
                  <div className="text-[10px] leading-tight" style={{ color: c.textMuted }}>{label}</div>
                </button>
              ))}
            </div>
          </div>
        );
      })()}

      {/* Bulk planning bar */}
      <div className="rounded-xl border p-3 flex flex-wrap items-end gap-3" style={{ borderColor: c.border, background: 'var(--color-surface)' }} data-testid="bl-plan-bar">
        <div className="flex items-center gap-2 text-sm font-semibold" style={{ color: c.text }}>
          <CalendarClock size={16} style={{ color: 'var(--color-info-ios)' }} />
          {selected.size > 0 ? `${selected.size} station${selected.size > 1 ? 's' : ''} selected` : 'Bulk plan visits'}
        </div>
        <label className="text-[11px]" style={{ color: c.textMuted }}>Scheduled date
          <input data-testid="bl-plan-date" type="date" value={planDate} onChange={e => setPlanDate(e.target.value)}
            className="block px-2 py-1.5 text-sm rounded-md border bg-transparent" style={{ borderColor: c.border, color: c.text }} />
        </label>
        <label className="text-[11px]" style={{ color: c.textMuted }}>Window end (optional)
          <input data-testid="bl-plan-window" type="date" value={planWindowEnd} onChange={e => setPlanWindowEnd(e.target.value)}
            className="block px-2 py-1.5 text-sm rounded-md border bg-transparent" style={{ borderColor: c.border, color: c.text }} />
        </label>
        <label className="text-[11px]" style={{ color: c.textMuted }}>Engineer
          <select data-testid="bl-plan-engineer" value={planEngineer} onChange={e => setPlanEngineer(e.target.value)}
            className="block px-2 py-1.5 text-sm rounded-md border bg-transparent min-w-[180px]" style={{ borderColor: c.border, color: c.text }}>
            <option value="">— Unallocated —</option>
            {engineers.map(e => <option key={e.id} value={e.id}>{e.full_name}{typeof e.planned_visits === 'number' ? ` (${e.planned_visits})` : ''}</option>)}
          </select>
        </label>
        <Button onClick={() => planVisits(false)} disabled={planning || selected.size === 0} icon={CalendarClock} data-testid="bl-plan-btn">
          {planning ? 'Planning…' : `Plan ${selected.size || ''} visit${selected.size === 1 ? '' : 's'}`}
        </Button>
        <Button variant="ghost" size="sm" onClick={reassign} disabled={planning || selected.size === 0} data-testid="bl-reassign-btn">Reassign engineer</Button>
        {selected.size > 0 && <Button variant="ghost" size="sm" onClick={clearSel} data-testid="bl-clear-sel">Clear</Button>}
      </div>
      {planMsg && (
        <div className="rounded-lg border p-3 text-sm" style={{ borderColor: c.border, background: 'var(--color-surface)' }} data-testid="bl-plan-result">
          {planMsg.reassigned != null ? (
            <span style={{ color: 'var(--color-success-alt)' }}><CheckCircle size={14} className="inline mr-1" />Reassigned {planMsg.reassigned} visit(s) to {planMsg.engineer || 'Unallocated'}.</span>
          ) : (
            <>
              {planMsg.created > 0 ? (
                <span style={{ color: 'var(--color-success-alt)' }}><CheckCircle size={14} className="inline mr-1" />Planned {planMsg.created} visit(s) for the {planMsg.cycle} service cycle.</span>
              ) : (
                <span style={{ color: 'var(--color-accent-amber)' }}><AlertTriangle size={14} className="inline mr-1" />No new visits planned — every selected station already has a {planMsg.cycle} visit.</span>
              )}
              {planMsg.skipped?.length > 0 && (
                <div className="mt-1" style={{ color: 'var(--color-accent-amber)' }}>
                  <AlertTriangle size={14} className="inline mr-1" />{planMsg.skipped.length} skipped (duplicate protection): {planMsg.skipped.slice(0, 3).map(s => s.station_name || s.site_id).join(', ')}{planMsg.skipped.length > 3 ? '…' : ''}{' '}
                  <button className="ml-2 underline" data-testid="bl-plan-force" onClick={() => { setSelected(new Set(planMsg.skipped.map(s => s.site_id))); }}>re-select skipped</button>
                </div>
              )}
            </>
          )}
        </div>
      )}

      {/* Station matrix */}
      <div className="rounded-xl border" style={{ borderColor: c.border }}>
        <div className="flex flex-wrap items-center gap-2 p-3 border-b" style={{ borderColor: c.border }}>
          <div className="relative flex-1 min-w-[180px]">
            <Search size={14} className="absolute left-2.5 top-1/2 -translate-y-1/2" style={{ color: c.textMuted }} />
            <input data-testid="bl-station-search" value={search} onChange={e => setSearch(e.target.value)}
              placeholder="Search station, town, contact…"
              className="w-full pl-8 pr-3 py-1.5 text-sm rounded-md border bg-transparent"
              style={{ borderColor: c.border, color: c.text }} />
          </div>
          <select data-testid="bl-station-status-filter" value={statusFilter} onChange={e => setStatusFilter(e.target.value)}
            className="px-2 py-1.5 text-sm rounded-md border bg-transparent" style={{ borderColor: c.border, color: c.text }}>
            <option value="">All statuses</option>
            {Object.entries(STATUS_META).map(([k, m]) => <option key={k} value={k}>{m.label}</option>)}
          </select>
          <Button variant="ghost" size="sm" icon={Download} onClick={exportCsv} data-testid="bl-station-export">Export</Button>
          {certStatusFilter && (
            <button data-testid="bl-cert-filter-clear" onClick={() => setCertStatusFilter('')}
              className="text-xs px-2 py-1 rounded-full flex items-center gap-1"
              style={{ background: 'var(--color-info-ios)22', color: 'var(--color-info-ios)' }}>
              Certificate: {certStatusFilter.replace(/_/g, ' ')} ✕
            </button>
          )}
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr style={{ color: c.textMuted }} className="text-[11px] uppercase">
                <th className="px-3 py-2 w-8">
                  <input type="checkbox" checked={allSelected} onChange={toggleAll} data-testid="bl-select-all" aria-label="Select all stations" />
                </th>
                {stationCols.map(([col, label]) => (
                  <th key={col} className="text-left font-semibold px-3 py-2 cursor-pointer whitespace-nowrap"
                    onClick={() => setSortCol(col)} data-testid={`bl-sort-${col}`}>
                    <span className="inline-flex items-center gap-1">{label}
                      {sort === col && (direction === 'asc' ? <ChevronUp size={12} /> : <ChevronDown size={12} />)}</span>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr><td colSpan={stationCols.length + 1} className="px-3 py-8 text-center" style={{ color: c.textMuted }}>Loading…</td></tr>
              ) : stations.length === 0 ? (
                <tr><td colSpan={stationCols.length + 1} className="px-3 py-8 text-center" style={{ color: c.textMuted }} data-testid="bl-station-empty">No stations match.</td></tr>
              ) : stations.map(r => (
                <tr key={r.site_id} className="border-t" style={{ borderColor: c.border }} data-testid={`bl-station-row-${r.site_id}`}>
                  <td className="px-3 py-2">
                    <input type="checkbox" checked={selected.has(r.site_id)} onChange={() => toggleRow(r.site_id)}
                      data-testid={`bl-select-${r.site_id}`} aria-label={`Select ${r.station_name}`} />
                  </td>
                  <td className="px-3 py-2 font-medium whitespace-nowrap" style={{ color: c.text }}>
                    {r.visit_id && ['scheduled', 'in_progress', 'travelling', 'on_site', 'follow_up_required'].includes(r.visit_status) ? (
                      <a href={`/blue-light/visit/${r.visit_id}`} target="_blank" rel="noreferrer"
                        data-testid={`bl-open-visit-${r.site_id}`} className="underline decoration-dotted"
                        style={{ color: 'var(--color-info-ios)' }}>{r.station_name}</a>
                    ) : r.station_name}
                  </td>
                  <td className="px-3 py-2 whitespace-nowrap" style={{ color: c.textDim }}>{r.address}</td>
                  <td className="px-3 py-2 whitespace-nowrap" style={{ color: c.textDim }}>{r.contact_name}</td>
                  <td className="px-3 py-2 whitespace-nowrap" style={{ color: c.textDim }}>{r.telephone}</td>
                  <td className="px-3 py-2 text-center" style={{ color: c.text }}>{r.asset_count}</td>
                  <td className="px-3 py-2 text-center" style={{ color: r.treadmill_count ? 'var(--color-info-ios)' : c.textMuted }}>{r.treadmill_count}</td>
                  <td className="px-3 py-2 whitespace-nowrap" style={{ color: c.textDim }}>{r.next_service_due || '—'}</td>
                  <td className="px-3 py-2 whitespace-nowrap" style={{ color: c.textDim }}>{r.scheduled_date || '—'}</td>
                  <td className="px-3 py-2 whitespace-nowrap" style={{ color: c.textDim }}>{r.assigned_engineer_name || '—'}</td>
                  <td className="px-3 py-2"><StatusPill status={r.visit_status} /></td>
                  <td className="px-3 py-2"><CellPill value={r.calibration_status} /></td>
                  <td className="px-3 py-2 text-center" style={{ color: r.faults_raised ? 'var(--color-danger)' : c.textMuted }}>{r.faults_raised}</td>
                  <td className="px-3 py-2"><CellPill value={r.certificate_status} /></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

function ConfigForm({ cfg, setCfg, meta, c, API, headers, contractId }) {
  const set = (k, v) => setCfg(p => ({ ...p, [k]: v }));
  const [uploadingLogo, setUploadingLogo] = useState(false);
  const numList = (str) => str.split(',').map(x => parseFloat(x.trim())).filter(x => !isNaN(x));
  const inp = 'w-full px-2 py-1.5 text-sm rounded-md border bg-transparent';
  const origin = (API || '').replace(/\/api$/, '');
  const logoSrc = cfg.customer_logo_url
    ? (/^(https?:|data:)/.test(cfg.customer_logo_url) ? cfg.customer_logo_url : origin + cfg.customer_logo_url)
    : '';
  const onLogoFile = async (e) => {
    const f = e.target.files?.[0];
    if (!f) return;
    setUploadingLogo(true);
    try {
      const fd = new FormData(); fd.append('file', f);
      const r = await axios.post(`${API}/crm/v2/contracts/${contractId}/blue-light/logo`, fd, { headers: headers() });
      set('customer_logo_url', r.data.customer_logo_url);
    } catch (err) { alert(err.response?.data?.detail || 'Logo upload failed'); }
    finally { setUploadingLogo(false); e.target.value = ''; }
  };
  const removeLogo = async () => {
    try {
      await axios.delete(`${API}/crm/v2/contracts/${contractId}/blue-light/logo`, { headers: headers() });
      set('customer_logo_url', ''); set('customer_logo_path', null);
    } catch (err) { alert(err.response?.data?.detail || 'Could not remove the logo — please try again'); }
  };
  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
      <label className="text-xs" style={{ color: c.textMuted }}>Customer type
        <select data-testid="bl-cfg-customer-type" className={inp} style={{ borderColor: c.border, color: c.text }}
          value={cfg.customer_type} onChange={e => set('customer_type', e.target.value)}>
          {meta.customer_types.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
        </select>
      </label>
      <label className="text-xs" style={{ color: c.textMuted }}>Service frequency (months)
        <input data-testid="bl-cfg-frequency" type="number" min="1" className={inp} style={{ borderColor: c.border, color: c.text }}
          value={cfg.service_frequency_months} onChange={e => set('service_frequency_months', parseInt(e.target.value || '6', 10))} />
      </label>
      <label className="text-xs" style={{ color: c.textMuted }}>Speed points (mph, comma-separated)
        <input data-testid="bl-cfg-speed" className={inp} style={{ borderColor: c.border, color: c.text }}
          defaultValue={(cfg.speed_points_mph || []).join(', ')} onBlur={e => set('speed_points_mph', numList(e.target.value))} />
      </label>
      <label className="text-xs" style={{ color: c.textMuted }}>Incline points (%, comma-separated)
        <input data-testid="bl-cfg-incline" className={inp} style={{ borderColor: c.border, color: c.text }}
          defaultValue={(cfg.incline_points_pct || []).join(', ')} onBlur={e => set('incline_points_pct', numList(e.target.value))} />
      </label>
      <label className="text-xs" style={{ color: c.textMuted }}>Failure tolerance (% of target)
        <input data-testid="bl-cfg-tolerance" type="number" step="0.1" className={inp} style={{ borderColor: c.border, color: c.text }}
          value={cfg.tolerance_pct} onChange={e => set('tolerance_pct', parseFloat(e.target.value || '5'))} />
      </label>
      <label className="text-xs" style={{ color: c.textMuted }}>Certificate approval
        <select data-testid="bl-cfg-approval" className={inp} style={{ borderColor: c.border, color: c.text }}
          value={cfg.certificate_approval_mode} onChange={e => set('certificate_approval_mode', e.target.value)}>
          <option value="auto_send">Auto-send after completion</option>
          <option value="office_review">Office review before send</option>
          <option value="manager_approval">Manager approval</option>
        </select>
      </label>
      <label className="text-xs md:col-span-2" style={{ color: c.textMuted }}>Certificate recipients (emails, comma-separated)
        <input data-testid="bl-cfg-recipients" className={inp} style={{ borderColor: c.border, color: c.text }}
          defaultValue={(cfg.certificate_recipients || []).join(', ')}
          onBlur={e => set('certificate_recipients', e.target.value.split(',').map(x => x.trim()).filter(Boolean))} />
      </label>
      <label className="text-xs md:col-span-2" style={{ color: c.textMuted }}>Office notification emails (asset-transfer alerts, comma-separated — defaults to the approver)
        <input data-testid="bl-cfg-office-emails" className={inp} style={{ borderColor: c.border, color: c.text }}
          defaultValue={(cfg.office_notification_emails || []).join(', ')}
          onBlur={e => set('office_notification_emails', e.target.value.split(',').map(x => x.trim()).filter(Boolean))} />
      </label>
      <label className="text-xs md:col-span-2" style={{ color: c.textMuted }}>Customer logo / crest (shown on the certificate — everything else stays the same)
        <div className="flex items-center gap-3 mt-1 flex-wrap">
          {logoSrc
            ? <img data-testid="bl-cfg-logo-preview" src={logoSrc} alt="Customer logo"
                className="h-12 rounded border p-1 bg-white object-contain" style={{ borderColor: c.border }} />
            : <span className="text-xs italic" style={{ color: c.textMuted }}>No logo yet — the certificate shows the Pulse header only</span>}
          <label className="text-xs px-3 py-1.5 rounded-md border cursor-pointer" data-testid="bl-cfg-logo-upload"
            style={{ borderColor: c.border, color: c.text }}>
            {uploadingLogo ? 'Uploading…' : (logoSrc ? 'Replace logo' : 'Upload logo')}
            <input type="file" accept="image/png,image/jpeg" className="hidden" onChange={onLogoFile} disabled={uploadingLogo} />
          </label>
          {logoSrc && <button type="button" data-testid="bl-cfg-logo-remove" onClick={removeLogo}
            className="text-xs underline" style={{ color: 'var(--color-danger)' }}>Remove</button>}
        </div>
        <span className="text-[11px]" style={{ color: c.textMuted }}>PNG or JPG, up to 8 MB. Stored securely.</span>
      </label>
      <label className="text-xs md:col-span-2 flex items-center gap-2 mt-1" style={{ color: c.textMuted }}>
        <input data-testid="bl-cfg-calibration-required" type="checkbox" checked={!!cfg.calibration_required}
          onChange={e => set('calibration_required', e.target.checked)} />
        Treadmill calibration required on this contract
      </label>
    </div>
  );
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';
import {
  MapPin, CheckCircle, XCircle, RefreshCw, Plus, Wrench, Gauge, AlertTriangle,
  ClipboardCheck, PenTool, ChevronRight, ChevronLeft, Loader2, Radio, Save,
} from 'lucide-react';

const API = `${process.env.REACT_APP_BACKEND_URL}/api`;
const authHeaders = () => ({ Authorization: `Bearer ${localStorage.getItem('crm_token') || ''}` });

const STEPS = [
  { id: 'asset_check', label: 'Asset Check', icon: ClipboardCheck },
  { id: 'service', label: 'Service', icon: Wrench },
  { id: 'calibration', label: 'Calibration', icon: Gauge },
  { id: 'faults', label: 'Faults', icon: AlertTriangle },
  { id: 'review', label: 'Review', icon: ClipboardCheck },
  { id: 'sign', label: 'Sign & Complete', icon: PenTool },
];

const RESULT_COLOR = { pass: '#16a34a', review: '#d97706', fail: '#dc2626', incomplete: '#9a9fa1' };

const BigButton = ({ onClick, children, color = '#0091ca', icon: Icon, testId, disabled, variant }) => (
  <button data-testid={testId} onClick={onClick} disabled={disabled}
    className="flex items-center justify-center gap-2 rounded-2xl px-5 py-4 text-base font-semibold transition-transform active:scale-95 disabled:opacity-40 w-full"
    style={variant === 'outline'
      ? { border: `2px solid ${color}`, color, background: 'transparent' }
      : { background: color, color: '#fff' }}>
    {Icon && <Icon size={20} />}{children}
  </button>
);

// ── Numeric keypad for calibration entry (§15/§16) ──────────────────
function NumPad({ value, onChange, onDone }) {
  const press = (k) => {
    if (k === 'del') return onChange(value.slice(0, -1));
    if (k === '.' && value.includes('.')) return;
    onChange((value + k).slice(0, 6));
  };
  const keys = ['1', '2', '3', '4', '5', '6', '7', '8', '9', '.', '0', 'del'];
  return (
    <div className="grid grid-cols-3 gap-2 mt-3" data-testid="calib-numpad">
      {keys.map(k => (
        <button key={k} onClick={() => press(k)} data-testid={`numpad-${k}`}
          className="rounded-xl py-4 text-xl font-bold bg-slate-100 active:bg-slate-200">
          {k === 'del' ? '⌫' : k}</button>
      ))}
      <button onClick={onDone} data-testid="numpad-done"
        className="col-span-3 rounded-xl py-3 text-base font-semibold bg-blue-600 text-white">Done</button>
    </div>
  );
}

export default function BlueLightVisitWizard() {
  const { visitId } = useParams();
  const nav = useNavigate();
  const [state, setState] = useState(null);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [step, setStep] = useState(0);
  const [activeAsset, setActiveAsset] = useState(null); // for audit/service/calibration modal
  const [mode, setMode] = useState(null); // 'audit' | 'service' | 'calibration' | 'fault' | 'addAsset'
  const [toast, setToast] = useState(null);

  const load = useCallback(async () => {
    try {
      const r = await axios.get(`${API}/crm/v2/visits/${visitId}`, { headers: authHeaders() });
      setState(r.data);
    } catch (e) { setToast({ err: e.response?.data?.detail || 'Could not load the visit' }); }
    finally { setLoading(false); }
  }, [visitId]);

  useEffect(() => { load(); }, [load]);

  const post = async (path, body) => {
    setBusy(true);
    try {
      const r = await axios.post(`${API}/crm/v2/visits/${visitId}${path}`, body, { headers: authHeaders() });
      if (r.data.visit || r.data.progress) setState(r.data);
      else await load();
      return r.data;
    } catch (e) { setToast({ err: e.response?.data?.detail || 'Something went wrong' }); return null; }
    finally { setBusy(false); }
  };

  const lookupAsset = async ({ serial, model, name }) => {
    try {
      const params = new URLSearchParams();
      if (serial) params.set('serial', serial);
      if (model) params.set('model', model);
      if (name) params.set('name', name);
      const r = await axios.get(`${API}/crm/v2/visits/${visitId}/assets/lookup?${params.toString()}`, { headers: authHeaders() });
      return r.data.matches || [];
    } catch { return []; }
  };

  if (loading) return <div className="min-h-screen grid place-items-center bg-slate-50"><Loader2 className="animate-spin text-blue-600" /></div>;
  if (!state) return <div className="min-h-screen grid place-items-center bg-slate-50 text-slate-500">Visit not found.</div>;

  const { pack, assets, progress, completion_blockers, can_complete, contract, visit, calibrations } = state;
  const notStarted = !visit.started_at && visit.status !== 'in_progress' && visit.status !== 'completed';
  const treadmills = assets.filter(a => a.is_treadmill && a.audit && a.audit !== 'not_found');
  const presentAssets = assets.filter(a => ['present', 'update', 'replaced', 'add'].includes(a.audit));

  // ── START SCREEN (§6) ──
  if (notStarted) {
    return (
      <div className="min-h-screen bg-slate-50 pb-10">
        <div className="bg-blue-700 text-white px-5 pt-8 pb-6">
          <div className="flex items-center gap-2 text-blue-200 text-sm"><Radio size={16} /> Blue Light Service</div>
          <h1 className="text-2xl font-bold mt-1" data-testid="visit-station-name">{pack.station_name}</h1>
          <p className="text-blue-100 text-sm mt-1">{pack.station?.address}, {pack.station?.city} {pack.station?.postcode}</p>
        </div>
        <div className="p-5 space-y-4">
          <div className="rounded-2xl bg-white shadow p-4 grid grid-cols-3 text-center">
            <div><div className="text-2xl font-bold">{pack.expected_asset_count}</div><div className="text-xs text-slate-500">Machines</div></div>
            <div><div className="text-2xl font-bold text-blue-600">{pack.treadmill_count}</div><div className="text-xs text-slate-500">Treadmills</div></div>
            <div><div className="text-2xl font-bold">{contract.contract_number || '—'}</div><div className="text-xs text-slate-500">Contract</div></div>
          </div>
          <div className="rounded-2xl bg-white shadow p-4 text-sm text-slate-600 space-y-1">
            <div><b>Contact:</b> {pack.station?.contact_name} · {pack.station?.telephone}</div>
            {pack.station?.access_instructions && <div><b>Access:</b> {pack.station.access_instructions}</div>}
            {pack.station?.parking_info && <div><b>Parking:</b> {pack.station.parking_info}</div>}
          </div>
          <label className="flex items-start gap-3 rounded-2xl bg-white shadow p-4 text-sm">
            <input type="checkbox" id="confirm-site" data-testid="confirm-on-site" className="mt-1 w-5 h-5" />
            <span>I confirm I am at the correct station: <b>{pack.station_name}</b></span>
          </label>
          <BigButton testId="start-visit-btn" icon={MapPin} disabled={busy} color="#0091ca"
            onClick={async () => {
              const ok = document.getElementById('confirm-site')?.checked;
              if (!ok) { setToast({ err: 'Please tick the box to confirm you are at the correct station.' }); return; }
              await post('/start', { confirmed_on_site: true });
            }}>Start Station Service</BigButton>
        </div>
        {toast && <Toast toast={toast} onClose={() => setToast(null)} />}
      </div>
    );
  }

  if (visit.status === 'completed') {
    return (
      <div className="min-h-screen bg-slate-50 grid place-items-center p-6">
        <div className="rounded-2xl bg-white shadow p-8 text-center max-w-sm" data-testid="visit-completed">
          <CheckCircle size={56} className="mx-auto text-green-600" />
          <h2 className="text-xl font-bold mt-3">Visit Completed</h2>
          <p className="text-slate-600 mt-1">{pack.station_name}</p>
          <p className="text-sm text-slate-500 mt-2">Next service due: <b>{visit.next_service_due}</b></p>
          <p className="text-xs text-slate-400 mt-1">Certificate: {visit.certificate_status?.replace(/_/g, ' ')}</p>
          {visit.certificate_id && (
            <button data-testid="download-cert-btn" onClick={() => {
              axios.get(`${API}/crm/v2/certificates/${visit.certificate_id}/download`, { headers: authHeaders(), responseType: 'blob' })
                .then(res => { const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([res.data], { type: 'application/pdf' })); a.download = 'certificate.pdf'; a.click(); URL.revokeObjectURL(a.href); })
                .catch(() => {});
            }} className="mt-3 text-sm underline text-blue-600">Download certificate</button>
          )}
          <BigButton testId="back-to-matrix" color="#0091ca" onClick={() => nav('/crm?tab=contracts')}>Back to contracts</BigButton>
        </div>
      </div>
    );
  }

  const curStep = STEPS[step].id;

  return (
    <div className="min-h-screen bg-slate-50 pb-28">
      {/* Header + progress */}
      <div className="bg-blue-700 text-white px-5 pt-6 pb-4 sticky top-0 z-20">
        <div className="flex items-center justify-between">
          <div>
            <div className="text-blue-200 text-xs flex items-center gap-1"><Radio size={13} /> Blue Light Service</div>
            <h1 className="text-lg font-bold" data-testid="wizard-station-name">{pack.station_name}</h1>
          </div>
          <div className="text-right text-xs text-blue-100">
            <div data-testid="wizard-asset-progress">{progress.accounted} / {progress.expected_assets} assets</div>
            <div>{progress.treadmills_calibrated}/{progress.treadmills_required} treadmills</div>
          </div>
        </div>
        <div className="flex gap-1 mt-3 overflow-x-auto no-scrollbar">
          {STEPS.map((s, i) => (
            <button key={s.id} onClick={() => setStep(i)} data-testid={`step-tab-${s.id}`}
              className="flex-shrink-0 flex items-center gap-1 px-2.5 py-1 rounded-full text-[11px] font-semibold whitespace-nowrap"
              style={{ background: i === step ? '#fff' : 'rgba(255,255,255,0.15)', color: i === step ? '#0091ca' : '#dbeafe' }}>
              <s.icon size={12} />{i + 1}. {s.label}
            </button>
          ))}
        </div>
      </div>

      <div className="p-4 space-y-3">
        {curStep === 'asset_check' && (
          <AssetList assets={assets} title="Confirm every asset" emptyDone={progress.assets_remaining === 0}
            onPick={(a) => { setActiveAsset(a); setMode('audit'); }}
            badge={(a) => a.audit ? { text: AUDIT_LABEL[a.audit], color: a.audit === 'not_found' ? '#dc2626' : '#16a34a' } : { text: 'Pending', color: '#9a9fa1' }}
            footer={<BigButton testId="add-asset-btn" variant="outline" color="#0091ca" icon={Plus}
              onClick={() => { setActiveAsset(null); setMode('addAsset'); }}>Add machine not on list</BigButton>} />
        )}
        {curStep === 'service' && (
          <AssetList assets={presentAssets} title="Service each machine" emptyDone={progress.serviced === progress.to_service}
            onPick={(a) => { setActiveAsset(a); setMode('service'); }}
            badge={(a) => a.service_outcome ? { text: SERVICE_LABEL[a.service_outcome] || 'Done', color: '#16a34a' } : { text: 'To service', color: '#9a9fa1' }} />
        )}
        {curStep === 'calibration' && (
          <div className="space-y-3">
            <StepTitle>{progress.treadmills_calibrated}/{progress.treadmills_required} treadmills calibrated</StepTitle>
            {treadmills.length === 0 && <Empty>No treadmills requiring calibration at this station.</Empty>}
            {treadmills.map(t => {
              const cal = calibrations[t.asset_key];
              return (
                <button key={t.asset_key} data-testid={`calib-asset-${t.asset_key}`}
                  onClick={() => { setActiveAsset(t); setMode('calibration'); }}
                  className="w-full text-left rounded-2xl bg-white shadow p-4 flex items-center justify-between">
                  <div>
                    <div className="font-semibold">{t.asset_name}</div>
                    <div className="text-xs text-slate-500">Serial: {t.serial_number || '—'}</div>
                  </div>
                  {cal?.overall
                    ? <span className="px-3 py-1 rounded-full text-xs font-bold text-white" style={{ background: RESULT_COLOR[cal.overall] }}>{cal.overall.toUpperCase()}</span>
                    : <span className="px-3 py-1 rounded-full text-xs font-bold bg-amber-100 text-amber-700">CALIBRATION REQUIRED</span>}
                </button>
              );
            })}
          </div>
        )}
        {curStep === 'faults' && (
          <div className="space-y-3">
            <StepTitle>Faults & actions</StepTitle>
            {(state.faults || []).length === 0 && <Empty>No faults raised yet.</Empty>}
            {(state.faults || []).map(f => (
              <div key={f.id} className="rounded-2xl bg-white shadow p-4" data-testid={`fault-row-${f.id}`}>
                <div className="font-semibold text-sm">{f.reference} · {f.title}</div>
                <div className="text-xs text-slate-500 mt-0.5">Priority {f.priority?.toUpperCase()}{f.out_of_service ? ' · OUT OF SERVICE' : ''}</div>
              </div>
            ))}
            <BigButton testId="raise-fault-btn" variant="outline" color="#dc2626" icon={AlertTriangle}
              onClick={() => { setActiveAsset(null); setMode('fault'); }}>Raise a fault</BigButton>
          </div>
        )}
        {curStep === 'review' && <ReviewPanel state={state} />}
        {curStep === 'sign' && (
          <SignPanel busy={busy} blockers={completion_blockers} canComplete={can_complete}
            onGoTo={(b) => { const idx = STEPS.findIndex(s => s.id === (b.type === 'calibration' ? 'calibration' : b.type === 'service' ? 'service' : 'asset_check')); setStep(idx >= 0 ? idx : 0); }}
            onComplete={async (sig, name, override) => {
              const r = await post('/complete', { signature_data: sig, engineer_name: name, override_reason: override });
              if (r?.success) { setToast({ ok: `Visit complete. Next service ${r.next_service_due}.` }); await load(); }
              else if (r?.blocked) setToast({ err: r.message });
            }}
            onPartial={async (reason) => { const r = await post('/partial', { reason }); if (r?.success) { setToast({ ok: 'Saved as partial visit.' }); nav('/crm?tab=contracts'); } }} />
        )}
      </div>

      {/* Sticky footer nav */}
      <div className="fixed bottom-0 inset-x-0 bg-white border-t p-3 flex gap-2 z-20">
        <button data-testid="wizard-prev" disabled={step === 0} onClick={() => setStep(s => Math.max(0, s - 1))}
          className="flex-1 rounded-xl py-3 font-semibold border disabled:opacity-30 flex items-center justify-center gap-1"><ChevronLeft size={18} />Back</button>
        <button data-testid="wizard-next" disabled={step === STEPS.length - 1} onClick={() => setStep(s => Math.min(STEPS.length - 1, s + 1))}
          className="flex-1 rounded-xl py-3 font-semibold bg-blue-600 text-white disabled:opacity-30 flex items-center justify-center gap-1">Next<ChevronRight size={18} /></button>
      </div>

      {/* Modals */}
      {mode === 'audit' && activeAsset && <AuditSheet asset={activeAsset} busy={busy} onClose={() => setMode(null)}
        onSubmit={async (payload) => { await post(`/assets/${activeAsset.asset_key}/audit`, payload); setMode(null); }} />}
      {mode === 'addAsset' && <AddAssetSheet busy={busy} onClose={() => setMode(null)}
        onLookup={lookupAsset}
        onRequestTransfer={async (assetId, reason) => {
          const r = await post(`/assets/${assetId}/transfer-request`, { reason });
          if (r) { setMode(null); setToast({ ok: 'Transfer requested — the office will review it.' }); }
        }}
        onSubmit={async (na) => { await post(`/assets/new-${Date.now()}/audit`, { action: 'add', new_asset: na }); setMode(null); }} />}
      {mode === 'service' && activeAsset && <ServiceSheet asset={activeAsset} busy={busy} onClose={() => setMode(null)}
        onSubmit={async (payload) => { await post(`/assets/${activeAsset.asset_key}/service`, payload); setMode(null); }}
        onRaiseFault={() => setMode('fault')} />}
      {mode === 'calibration' && activeAsset && <CalibrationSheet asset={activeAsset} config={contract.blue_light} busy={busy}
        existing={calibrations[activeAsset.asset_key]} onClose={() => setMode(null)}
        onSubmit={async (payload) => await post(`/treadmills/${activeAsset.asset_key}/calibration`, payload)} />}
      {mode === 'fault' && <FaultSheet asset={activeAsset} busy={busy} onClose={() => setMode(null)}
        onSubmit={async (payload) => { const r = await post('/faults', payload); if (r?.success) { setToast({ ok: `Fault ${r.fault.reference} raised.` }); setMode(null); await load(); } }} />}

      {toast && <Toast toast={toast} onClose={() => setToast(null)} />}
    </div>
  );
}

const AUDIT_LABEL = { present: 'Present', update: 'Updated', not_found: 'Not found', replaced: 'Replaced', add: 'New' };
const SERVICE_LABEL = {
  serviced_operational: 'Operational', serviced_minor_issue: 'Minor issue', serviced_fault_raised: 'Fault raised',
  out_of_service: 'Out of service', unable_to_service: 'Unable', asset_not_present: 'Not present', further_visit_required: 'Follow-up',
};

const StepTitle = ({ children }) => <h2 className="font-bold text-slate-700 px-1">{children}</h2>;
const Empty = ({ children }) => <div className="rounded-2xl bg-white shadow p-6 text-center text-slate-400 text-sm">{children}</div>;

function AssetList({ assets, title, onPick, badge, footer, emptyDone }) {
  return (
    <div className="space-y-3">
      <StepTitle>{title}{emptyDone && <span className="ml-2 text-green-600 text-sm">✓ all done</span>}</StepTitle>
      {assets.length === 0 && <Empty>Nothing here.</Empty>}
      {assets.map(a => {
        const b = badge(a);
        return (
          <button key={a.asset_key} onClick={() => onPick(a)} data-testid={`asset-row-${a.asset_key}`}
            className="w-full text-left rounded-2xl bg-white shadow p-4 flex items-center justify-between active:scale-[0.99] transition-transform">
            <div className="min-w-0">
              <div className="font-semibold truncate">{a.asset_name} {a.is_treadmill && <span className="text-blue-600 text-xs">· treadmill</span>}</div>
              <div className="text-xs text-slate-500 truncate">{a.equipment_type} · {a.serial_number || 'no serial'}</div>
            </div>
            <span className="px-3 py-1 rounded-full text-xs font-semibold flex-shrink-0" style={{ background: b.color + '22', color: b.color }}>{b.text}</span>
          </button>
        );
      })}
      {footer}
    </div>
  );
}

function Sheet({ title, children, onClose }) {
  return (
    <div className="fixed inset-0 z-[300] flex items-end sm:items-center justify-center bg-black/40" onClick={onClose}>
      <div className="bg-white w-full sm:max-w-md rounded-t-3xl sm:rounded-3xl p-5 max-h-[90vh] overflow-y-auto" onClick={e => e.stopPropagation()}>
        <div className="flex items-center justify-between mb-3">
          <h3 className="font-bold text-lg">{title}</h3>
          <button onClick={onClose} className="text-slate-400 p-1"><XCircle size={22} /></button>
        </div>
        {children}
      </div>
    </div>
  );
}

function AuditSheet({ asset, onSubmit, onClose, busy }) {
  const [view, setView] = useState('actions');
  const [changes, setChanges] = useState({ asset_name: asset.asset_name, model_code: asset.model_code || '', serial_number: asset.serial_number || '', location: asset.location || '' });
  const [reason, setReason] = useState('');
  const inp = 'w-full border rounded-xl px-3 py-2.5 mt-1';
  return (
    <Sheet title={asset.asset_name} onClose={onClose}>
      {view === 'actions' && (
        <div className="space-y-2">
          <BigButton testId="audit-present" icon={CheckCircle} color="#16a34a" disabled={busy} onClick={() => onSubmit({ action: 'present' })}>Confirm present</BigButton>
          <BigButton testId="audit-update" icon={PenTool} color="#0091ca" variant="outline" onClick={() => setView('update')}>Update details</BigButton>
          <BigButton testId="audit-notfound" icon={XCircle} color="#dc2626" variant="outline" onClick={() => setView('notfound')}>Machine not found</BigButton>
        </div>
      )}
      {view === 'update' && (
        <div className="space-y-2">
          {['asset_name', 'model_code', 'serial_number', 'location'].map(f => (
            <label key={f} className="block text-xs text-slate-500 capitalize">{f.replace('_', ' ')}
              <input className={inp} data-testid={`audit-field-${f}`} value={changes[f]} onChange={e => setChanges(c => ({ ...c, [f]: e.target.value }))} /></label>
          ))}
          <BigButton testId="audit-save-update" icon={Save} disabled={busy} onClick={() => onSubmit({ action: 'update', changes })}>Save changes</BigButton>
        </div>
      )}
      {view === 'notfound' && (
        <div className="space-y-2">
          <select className={inp} data-testid="audit-notfound-reason" value={reason} onChange={e => setReason(e.target.value)}>
            <option value="">Select a reason…</option>
            {['Removed from station', 'Disposed', 'Transferred', 'Temporarily away', 'Unable to locate', 'Unknown'].map(r => <option key={r} value={r}>{r}</option>)}
          </select>
          <BigButton testId="audit-save-notfound" color="#dc2626" disabled={busy || !reason} onClick={() => onSubmit({ action: 'not_found', reason })}>Mark not found</BigButton>
        </div>
      )}
    </Sheet>
  );
}

function AddAssetSheet({ onSubmit, onClose, busy, onLookup, onRequestTransfer }) {
  const [na, setNa] = useState({ asset_name: '', equipment_type: '', model_code: '', serial_number: '' });
  const [match, setMatch] = useState(null);
  const [ignore, setIgnore] = useState(false);
  const [checking, setChecking] = useState(false);
  const timer = useRef();
  const inp = 'w-full border rounded-xl px-3 py-2.5 mt-1';

  const runLookup = (next) => {
    clearTimeout(timer.current);
    const hasSignal = next.serial_number || (next.model_code && next.asset_name);
    if (!hasSignal || !onLookup) { setMatch(null); return; }
    timer.current = setTimeout(async () => {
      setChecking(true);
      const matches = await onLookup({ serial: next.serial_number, model: next.model_code, name: next.asset_name });
      setChecking(false);
      setMatch(matches[0] || null);
      setIgnore(false);
    }, 400);
  };

  const setField = (f, v) => {
    const next = { ...na, [f]: v };
    setNa(next);
    if (['serial_number', 'model_code', 'asset_name'].includes(f)) runLookup(next);
  };

  const showTransfer = match && !ignore;
  return (
    <Sheet title="Add machine" onClose={onClose}>
      <div className="space-y-2">
        {[['asset_name', 'Name / make+model'], ['equipment_type', 'Equipment type'], ['model_code', 'Model code'], ['serial_number', 'Serial number']].map(([f, l]) => (
          <label key={f} className="block text-xs text-slate-500">{l}
            <input className={inp} data-testid={`add-field-${f}`} value={na[f]} onChange={e => setField(f, e.target.value)} /></label>
        ))}
        {checking && <p className="text-xs text-slate-400" data-testid="add-lookup-checking">Checking the register…</p>}

        {showTransfer ? (
          <div className="rounded-2xl border-2 p-3 mt-1" data-testid="transfer-banner"
            style={{ borderColor: '#d97706', background: '#fffbeb' }}>
            <div className="flex items-start gap-2">
              <AlertTriangle size={18} className="text-amber-600 mt-0.5" />
              <div className="text-sm text-amber-900">
                This {match.match === 'serial' ? 'serial' : 'machine'} is already registered at{' '}
                <b>{match.station_name || 'another station'}</b>{match.serial_number ? <> ({match.serial_number})</> : null}.
                It looks like it may have been moved here.
              </div>
            </div>
            <div className="mt-3 space-y-2">
              <BigButton testId="transfer-request-btn" icon={RefreshCw} color="#d97706" disabled={busy}
                onClick={() => onRequestTransfer(match.asset_id, '')}>Request transfer to this station</BigButton>
              <button data-testid="transfer-add-anyway" className="w-full text-sm text-slate-500 underline py-1"
                onClick={() => setIgnore(true)}>No — add as a new machine anyway</button>
            </div>
          </div>
        ) : (
          <>
            <p className="text-xs text-slate-400">Unknown fields can be left blank — the office will review.</p>
