      style={{ background: toast.err ? '#dc2626' : '#16a34a' }}>{toast.err || toast.ok}</div>
  );
}

import React, { useCallback, useEffect, useState } from 'react';
import axios from 'axios';
import { Plus, Trash2, Pencil, Shield, X } from 'lucide-react';

const BASIS_LABEL = { annual: 'per year', per_visit: 'per visit', quoted: 'quoted amount' };
const STATUS = ['draft', 'active', 'expired', 'cancelled'];
const emptyForm = { company_id: '', reference: '', title: 'MOD PTE Service Contract', authority: '', start_date: '', end_date: '', status: 'draft', notes: '', lines: [] };

// MOD aftersales contracts — per-site locations × service type (A / B / C / repairs / refurbishment).
export default function ModContractsTab({ API, headers, c, isDark }) {
  const [rows, setRows] = useState([]);
  const [catalog, setCatalog] = useState([]);
  const [companies, setCompanies] = useState([]);
  const [form, setForm] = useState(null);
  const [editId, setEditId] = useState(null);
  const [err, setErr] = useState('');

  const load = useCallback(async () => {
    const [r, cat] = await Promise.all([
      axios.get(`${API}/crm/v2/mod-contracts`, { headers: headers() }),
      axios.get(`${API}/crm/v2/mod-contracts/catalog`, { headers: headers() }),
    ]);
    setRows(r.data.contracts || []); setCatalog(cat.data.service_types || []);
  }, [API, headers]);
  useEffect(() => { load().catch(() => setErr('Could not load MOD contracts')); }, [load]);

  const openForm = async (row) => {
    setErr('');
    if (!companies.length) {
      const r = await axios.get(`${API}/crm/v2/companies?type=mod_site&limit=500`, { headers: headers() });
      setCompanies(r.data.companies || r.data.items || []);
    }
    setEditId(row?.id || null);
    setForm(row ? { ...emptyForm, ...row } : { ...emptyForm });
  };

  const remove = async (id) => {
    if (!window.confirm('Delete this MOD contract?')) return;
    setErr('');
    try { await axios.delete(`${API}/crm/v2/mod-contracts/${id}`, { headers: headers() }); await load(); }
    catch (e) { setErr(e?.response?.data?.detail || 'Could not delete the contract'); }
  };

  const card = { background: isDark ? 'var(--color-surface-dark-1)' : '#fff', border: `1px solid ${c.border}` };
  const label = (k) => catalog.find((x) => x.key === k)?.label || k;

  return (
    <div className="space-y-3" data-testid="mod-contracts-tab">
      <div className="flex items-center justify-between gap-2">
        <p className="text-xs" style={{ color: c.textDim }}>Ministry of Defence PTE service contracts — set the service type and price for each location on a site.</p>
        <button onClick={() => openForm(null)} className="px-3 py-1.5 text-xs font-semibold rounded-md bg-[var(--color-info-ios)] text-white" data-testid="mod-contract-new">
          <Plus size={12} className="inline -mt-0.5" /> New MOD contract
        </button>
      </div>
      {err && <p className="text-xs text-red-600" data-testid="mod-contract-error">{err}</p>}
      {!rows.length && <div className="rounded-lg p-6 text-center text-sm" style={{ ...card, color: c.textDim }} data-testid="mod-contracts-empty">No MOD contracts yet.</div>}
      {rows.map((r) => (
        <div key={r.id} className="rounded-lg p-3" style={card} data-testid={`mod-contract-${r.id}`}>
          <div className="flex items-start justify-between gap-2">
            <div className="min-w-0">
              <p className="text-sm font-semibold" style={{ color: c.text }}><Shield size={13} className="inline -mt-0.5 mr-1 text-emerald-600" />{r.company_name} {r.reference && <span className="font-mono text-xs" style={{ color: c.textDim }}>· {r.reference}</span>}</p>
              <p className="text-[11px]" style={{ color: c.textDim }}>{r.title} · {r.start_date || '—'} → {r.end_date || '—'} · <span className="capitalize">{r.status}</span></p>
            </div>
            <div className="flex items-center gap-1 shrink-0">
              <span className="text-xs font-bold mr-2" style={{ color: c.text }}>£{Number(r.annual_value || 0).toLocaleString('en-GB')}/yr</span>
              <button onClick={() => openForm(r)} className="p-1.5 rounded hover:opacity-70" aria-label="Edit" data-testid={`mod-contract-edit-${r.id}`}><Pencil size={13} /></button>
              <button onClick={() => remove(r.id)} className="p-1.5 rounded hover:opacity-70 text-red-600" aria-label="Delete" data-testid={`mod-contract-delete-${r.id}`}><Trash2 size={13} /></button>
            </div>
          </div>
          <div className="mt-2 flex flex-wrap gap-1.5">
            {(r.lines || []).map((ln) => (
              <span key={ln.id} className="text-[10px] px-2 py-0.5 rounded-full" style={{ background: isDark ? 'var(--color-surface-dark-3)' : 'var(--color-neutral-100)', color: c.textMuted }}>
                {ln.location_name}: {label(ln.service_type).split(' — ')[0]} · £{Number(ln.price).toLocaleString('en-GB')} {BASIS_LABEL[ln.price_basis]}
              </span>
            ))}
          </div>
        </div>
      ))}
      {form && <ModContractForm {...{ API, headers, c, isDark, catalog, companies, form, setForm, editId }} onClose={() => setForm(null)} onSaved={() => { setForm(null); load(); }} />}
    </div>
  );
}

function ModContractForm({ API, headers, c, isDark, catalog, companies, form, setForm, editId, onClose, onSaved }) {
  const [locations, setLocations] = useState([]);
  const [linked, setLinked] = useState(true);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState('');
  useEffect(() => {
    if (!form.company_id) { setLocations([]); return; }
    axios.get(`${API}/crm/v2/mod-contracts/locations?company_id=${form.company_id}`, { headers: headers() })
      .then((r) => { setLocations(r.data.locations || []); setLinked(r.data.linked); }).catch(() => setLocations([]));
  }, [form.company_id, API, headers]);

  const set = (k, v) => setForm({ ...form, [k]: v });
  const setLine = (i, patch) => set('lines', form.lines.map((l, k) => (k === i ? { ...l, ...patch } : l)));
  const addLine = () => set('lines', [...form.lines, { location_id: '', service_type: 'A', price: '' }]);
  const save = async () => {
    setErr(''); setBusy(true);
    try {
      const body = { ...form, lines: form.lines.map((l) => ({ ...l, price: Number(l.price || 0) })) };
      if (editId) await axios.put(`${API}/crm/v2/mod-contracts/${editId}`, body, { headers: headers() });
      else await axios.post(`${API}/crm/v2/mod-contracts`, body, { headers: headers() });
      onSaved();
    } catch (e) { setErr(e?.response?.data?.detail || 'Could not save the contract'); }
    setBusy(false);
  };
  const input = { background: isDark ? 'var(--color-ink-alt)' : '#fff', border: `1px solid ${c.border}`, color: c.text };
  const fld = 'w-full mt-1 px-2.5 py-1.5 text-sm rounded-md';
  const lbl = 'text-[10px] uppercase tracking-wider font-medium';

  return (
    <div className="fixed inset-0 z-[80] flex items-center justify-center bg-black/50 p-4" onClick={onClose}>
      <div className="w-full max-w-2xl max-h-[90vh] overflow-y-auto rounded-xl p-5" style={{ background: isDark ? 'var(--color-neutral-900)' : '#fff' }} onClick={(e) => e.stopPropagation()} data-testid="mod-contract-form">
        <div className="flex items-center justify-between mb-3">
          <h2 className="text-lg font-semibold" style={{ color: c.text }}>{editId ? 'Edit MOD contract' : 'New MOD contract'}</h2>
          <button onClick={onClose} aria-label="Close"><X size={16} /></button>
        </div>
        <div className="grid grid-cols-2 gap-3">
          <label className="col-span-2"><span className={lbl} style={{ color: c.textDim }}>MOD site *</span>
            <select value={form.company_id} disabled={!!editId} onChange={(e) => set('company_id', e.target.value)} className={fld} style={input} data-testid="mod-contract-company">
              <option value="">— Select a MOD site —</option>
              {companies.map((co) => <option key={co.id} value={co.id}>{co.name}</option>)}
            </select>
          </label>
          <label><span className={lbl} style={{ color: c.textDim }}>Contract reference</span><input value={form.reference} onChange={(e) => set('reference', e.target.value)} className={fld} style={input} data-testid="mod-contract-reference" /></label>
          <label><span className={lbl} style={{ color: c.textDim }}>MoD contracting authority</span><input value={form.authority} onChange={(e) => set('authority', e.target.value)} className={fld} style={input} data-testid="mod-contract-authority" /></label>
          <label><span className={lbl} style={{ color: c.textDim }}>Start date</span><input type="date" value={form.start_date} onChange={(e) => set('start_date', e.target.value)} className={fld} style={input} data-testid="mod-contract-start" /></label>
          <label><span className={lbl} style={{ color: c.textDim }}>End date</span><input type="date" value={form.end_date} onChange={(e) => set('end_date', e.target.value)} className={fld} style={input} data-testid="mod-contract-end" /></label>
          <label><span className={lbl} style={{ color: c.textDim }}>Status</span>
            <select value={form.status} onChange={(e) => set('status', e.target.value)} className={fld} style={input} data-testid="mod-contract-status">
              {STATUS.map((st) => <option key={st} value={st}>{st[0].toUpperCase() + st.slice(1)}</option>)}
            </select>
          </label>
        </div>

        <div className="mt-4">
          <div className="flex items-center justify-between">
            <p className={lbl} style={{ color: c.textDim }}>Services by location</p>
            <button onClick={addLine} disabled={!form.company_id} className="text-xs font-semibold disabled:opacity-40" style={{ color: 'var(--color-info-ios)' }} data-testid="mod-contract-add-line"><Plus size={12} className="inline -mt-0.5" /> Add service</button>
          </div>
          {form.company_id && !linked && <p className="text-[11px] mt-1 text-amber-600">This site isn't linked to a MOD portal account yet — services can only cover the whole site.</p>}
          {form.company_id && linked && !locations.length && <p className="text-[11px] mt-1" style={{ color: c.textDim }}>No locations set up yet — add them under the site's Equipment register, or cover the whole site.</p>}
          {form.lines.map((ln, i) => {
            const st = catalog.find((x) => x.key === ln.service_type);
            return (
              <div key={ln.id || i} className="mt-2 p-2.5 rounded-lg" style={{ border: `1px solid ${c.border}` }} data-testid={`mod-contract-line-${i}`}>
                <div className="grid grid-cols-12 gap-2 items-end">
                  <label className="col-span-4"><span className={lbl} style={{ color: c.textDim }}>Location</span>
                    <select value={ln.location_id} onChange={(e) => setLine(i, { location_id: e.target.value })} className={fld} style={input} data-testid={`mod-contract-line-location-${i}`}>
                      <option value="">Whole site</option>
                      {locations.map((l) => <option key={l.id} value={l.id}>{l.name}</option>)}
                    </select>
                  </label>
                  <label className="col-span-4"><span className={lbl} style={{ color: c.textDim }}>Service type</span>
                    <select value={ln.service_type} onChange={(e) => setLine(i, { service_type: e.target.value })} className={fld} style={input} data-testid={`mod-contract-line-type-${i}`}>
                      {catalog.map((t) => <option key={t.key} value={t.key}>{t.label}</option>)}
                    </select>
                  </label>
                  <label className="col-span-3"><span className={lbl} style={{ color: c.textDim }}>£ {BASIS_LABEL[st?.price_basis] || ''}</span>
                    <input type="number" min="0" step="0.01" value={ln.price} onChange={(e) => setLine(i, { price: e.target.value })} className={fld} style={input} data-testid={`mod-contract-line-price-${i}`} />
                  </label>
                  <button onClick={() => set('lines', form.lines.filter((_, k) => k !== i))} className="col-span-1 pb-2 text-red-600" aria-label="Remove service" data-testid={`mod-contract-line-remove-${i}`}><Trash2 size={14} /></button>
                </div>
                {ln.service_type === 'C' && (
                  <label className="mt-1.5 flex items-center gap-1.5 text-xs" style={{ color: c.textMuted }}>
                    <input type="checkbox" checked={!!ln.quarterly_inspections} onChange={(e) => setLine(i, { quarterly_inspections: e.target.checked })} /> Include quarterly inspections
                  </label>
                )}
                {st && <p className="mt-1.5 text-[10px]" style={{ color: c.textDim }}>Includes: {st.includes.join(', ')} · Excludes: {st.excludes.join(', ')}</p>}
              </div>
            );
          })}
        </div>
        <label className="block mt-3"><span className={lbl} style={{ color: c.textDim }}>Notes</span><textarea value={form.notes} onChange={(e) => set('notes', e.target.value)} rows={2} className={fld} style={input} /></label>
        {err && <p className="mt-2 text-xs text-red-600" data-testid="mod-contract-form-error">{typeof err === 'string' ? err : 'Could not save'}</p>}
        <div className="mt-4 flex justify-end gap-2">
          <button onClick={onClose} className="px-4 py-2 text-sm" style={{ color: c.textMuted }}>Cancel</button>
          <button onClick={save} disabled={busy || !form.company_id} className="px-4 py-2 text-sm font-semibold rounded-md bg-[var(--color-info-ios)] text-white disabled:opacity-50" data-testid="mod-contract-save">{busy ? 'Saving…' : 'Save contract'}</button>
        </div>
      </div>
    </div>
  );
}

/**
 * Iter 220e3 — Public Contract Accept page (Phase D).
 *
 * Routed at /contracts/accept/:token (set up in routes module).
 * Customer reviews the contract snapshot and signs via the existing
 * in-page canvas; the backend marks the contract Active.
 */
import { useEffect, useRef, useState } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import { CheckCircle, ShieldCheck, Calendar } from 'lucide-react';

const API = process.env.REACT_APP_BACKEND_URL + '/api';

function fmtDate(d) {
  return d ? new Date(d).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }) : '—';
}

export default function PublicContractAcceptPage() {
  const { token } = useParams();
  const [data, setData] = useState(null);
  const [error, setError] = useState(null);
  const [signerName, setSignerName] = useState('');
  const [signing, setSigning] = useState(false);
  const [signed, setSigned] = useState(false);
  const canvasRef = useRef(null);
  const drawing = useRef(false);

  useEffect(() => {
    axios.get(`${API}/crm/v2/public/contracts/${token}`)
      .then(res => {
        setData(res.data);
        if (res.data.status === 'active' || res.data.signed_at) setSigned(true);
      })
      .catch(() => setError('This link is invalid or has expired.'));
  }, [token]);

  useEffect(() => {
    if (!canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = 150;
    ctx.fillStyle = '#fff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.lineWidth = 2;
    ctx.lineCap = 'round';
    ctx.strokeStyle = '#1B1C1D';
  }, [data]);

  const pos = (e) => {
    const rect = canvasRef.current.getBoundingClientRect();
    const t = e.touches ? e.touches[0] : e;
    return { x: t.clientX - rect.left, y: t.clientY - rect.top };
  };
  const start = (e) => { e.preventDefault(); drawing.current = true; const p = pos(e); const ctx = canvasRef.current.getContext('2d'); ctx.beginPath(); ctx.moveTo(p.x, p.y); };
  const move = (e) => { if (!drawing.current) return; e.preventDefault(); const p = pos(e); const ctx = canvasRef.current.getContext('2d'); ctx.lineTo(p.x, p.y); ctx.stroke(); };
  const end = () => { drawing.current = false; };

  const submit = async () => {
    if (!signerName.trim()) { alert('Enter your full name to sign.'); return; }
    setSigning(true);
    try {
      const signature = canvasRef.current.toDataURL('image/png');
      await axios.post(`${API}/crm/v2/public/contracts/${token}/sign`, {
        signer_name: signerName, signature,
      });
      setSigned(true);
    } catch (e) {
      alert(e.response?.data?.detail || 'Sign failed.');
    }
    setSigning(false);
  };

  if (error) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-[var(--theme-canvas)]">
      <div className="p-6 max-w-md rounded-2xl border bg-white dark:bg-[var(--theme-surface)] text-center">
        <p className="text-base font-semibold text-rose-700" data-testid="accept-error">{error}</p>
      </div>
    </div>
  );
  if (!data) return <div className="min-h-screen flex items-center justify-center text-sm text-slate-500">Loading contract…</div>;

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-[var(--theme-canvas)] py-8 px-4" data-testid="public-accept-page">
      <div className="max-w-3xl mx-auto bg-white dark:bg-[var(--theme-surface)] rounded-2xl border shadow-sm overflow-hidden">
        {/* Brand header */}
        <header className="px-6 py-4 border-b flex items-center justify-between"
                style={{ background: 'linear-gradient(135deg, #19CDFF, #003db8)' }}>
          <div>
            <p className="text-[10px] uppercase tracking-widest text-white/70 font-bold">Service Contract</p>
            <h1 className="text-lg font-extrabold text-white">{data.title}</h1>
            <p className="text-[11px] text-white/80">{data.contract_number} · {data.organization.name}</p>
          </div>
          <span className="text-[10px] uppercase font-extrabold px-2.5 py-1 rounded-full bg-white/15 text-white">{data.tier}</span>
        </header>
        <section className="px-6 py-5 space-y-5">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3 text-xs">
            <Stat label="Customer"  value={data.company_name || '—'} />
            <Stat label="Site"      value={data.site_name || 'All sites'} />
            <Stat label="Starts"    value={fmtDate(data.start_date)} />
            <Stat label="Ends"      value={fmtDate(data.end_date)} />
          </div>
          {data.pricing?.annual_value > 0 && (
            <div className="rounded-xl border bg-emerald-50 p-3" data-testid="accept-pricing">
              <p className="text-[10px] uppercase text-emerald-700 font-bold tracking-wider">Annual value</p>
              <p className="text-2xl font-extrabold text-emerald-900">£{data.pricing.annual_value.toLocaleString('en-GB')}</p>
              <p className="text-[11px] text-emerald-700/80">Billed {data.billing_frequency || 'annually'} · VAT {data.pricing.vat_percent}%</p>
            </div>
          )}
          <div>
            <p className="text-[10px] uppercase tracking-wider font-bold text-slate-500 mb-1.5">Inclusions</p>
            <CoverSummary inclusions={data.inclusions || {}} />
          </div>
          {(data.exclusions_structured || []).length > 0 && (
            <div data-testid="accept-exclusions">
              <p className="text-[10px] uppercase tracking-wider font-bold text-rose-700 mb-1.5">Exclusions</p>
              <p className="text-xs text-rose-800/90">{data.exclusions_structured.join(' · ')}</p>
            </div>
          )}
          {data.terms_md && (
            <details className="rounded border" data-testid="accept-terms">
              <summary className="px-3 py-2 text-xs font-bold uppercase tracking-wider text-slate-500 cursor-pointer">Terms & Conditions</summary>
              <pre className="px-3 py-2 text-[11px] whitespace-pre-wrap text-slate-700 font-sans">{data.terms_md}</pre>
            </details>
          )}
        </section>
        {/* Sign block */}
        <section className="px-6 py-5 border-t bg-slate-50/60">
          {signed ? (
            <div className="text-center py-4" data-testid="accept-signed-confirmation">
              <CheckCircle size={32} className="mx-auto text-emerald-500 mb-2" />
              <p className="text-base font-bold text-emerald-900">Contract accepted</p>
              <p className="text-xs text-slate-500 mt-1">Signed by {data.signed_by || signerName}</p>
              <p className="text-[10px] text-slate-400 mt-1 flex items-center justify-center gap-1">
                <Calendar size={10} /> {fmtDate(data.signed_at || new Date().toISOString())}
              </p>
            </div>
          ) : (
            <div className="space-y-3">
              <p className="text-xs font-bold uppercase tracking-wider text-slate-500 flex items-center gap-1.5">
                <ShieldCheck size={12} /> Sign & accept
              </p>
              <input value={signerName} onChange={e => setSignerName(e.target.value)}
                     placeholder="Your full legal name"
                     data-testid="accept-signer-name"
                     className="w-full px-3 py-2 rounded border text-sm" />
              <canvas ref={canvasRef} data-testid="accept-canvas"
                      className="w-full rounded border cursor-crosshair touch-none"
                      style={{ height: 150, backgroundColor: '#FFFFFF' }}
                      onMouseDown={start} onMouseMove={move} onMouseUp={end} onMouseLeave={end}
                      onTouchStart={start} onTouchMove={move} onTouchEnd={end} />
              <button onClick={submit} disabled={signing || !signerName.trim()}
                      data-testid="accept-sign-btn"
                      className="w-full py-2 rounded-md bg-emerald-600 text-white text-sm font-bold disabled:opacity-50">
                {signing ? 'Signing…' : 'Accept & sign contract'}
              </button>
            </div>
          )}
        </section>
      </div>
    </div>
  );
}

function Stat({ label, value }) {
  return (
    <div>
      <p className="text-[9px] uppercase tracking-wider font-bold text-slate-400">{label}</p>
      <p className="font-semibold text-slate-800 text-sm">{value}</p>
    </div>
  );
}
Stat.displayName = 'Stat';

function CoverSummary({ inclusions }) {
  const entries = Object.entries(inclusions || {}).filter(([, v]) => (v || []).length);
  if (!entries.length) return <p className="text-xs text-slate-400 italic">No structured inclusions configured.</p>;
  return (
    <div className="space-y-1">
      {entries.map(([groupKey, items]) => (
        <div key={groupKey} className="text-xs" data-testid={`accept-inc-${groupKey}`}>
          <p className="font-semibold text-slate-700 capitalize">{groupKey.replace(/_/g, ' ')}</p>
          <p className="text-slate-500">{items.join(' · ')}</p>
        </div>
      ))}
    </div>
  );
}
CoverSummary.displayName = 'CoverSummary';

/**
 * ForecastLeaderboard — iter 215di.
 *
 * "Top callers" widget. Ranks reps by average forecast accuracy across the
 * last N snapshotted periods. Highlights:
 *   - Gold/Silver/Bronze podium icons for the top 3.
 *   - Discreet bottom-quartile flag on the lowest 25% of reps.
 *   - Org-wide footer hint "X reps below 70% — might be worth a 1:1".
 *
 * Backend: GET /api/crm/forecast/leaderboard?periods=4
 */
import { useCallback, useEffect, useState } from 'react';
import axios from 'axios';
import { toast } from 'sonner';
import { Trophy, Medal, Award, ChevronDown, ChevronRight } from 'lucide-react';

const API = process.env.REACT_APP_BACKEND_URL ? `${process.env.REACT_APP_BACKEND_URL}/api` : '/api';
const auth = () => { const _t = localStorage.getItem('crm_token'); return { headers: _t ? { Authorization: `Bearer ${_t}` } : {} }; };

const PODIUM_ICONS = {
  gold: { Icon: Trophy, colour: '#d4af37' },
  silver: { Icon: Medal, colour: '#9a9fa1' },
  bronze: { Icon: Award, colour: '#a16207' },
};

function pctColour(pct) {
  if (pct >= 90) return 'var(--color-success-green, #10b981)';
  if (pct >= 70) return 'var(--color-brand-blue, #0091ca)';
  if (pct >= 50) return 'var(--color-warning, #f59e0b)';
  return 'var(--color-danger-red, #ef4444)';
}

export default function ForecastLeaderboard({ periods = 4, limit = 10 }) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [collapsed, setCollapsed] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const r = await axios.get(`${API}/crm/forecast/leaderboard?periods=${periods}`, auth());
      setData(r.data);
    } catch (e) {
      if (e?.response?.status !== 403) {
        toast.error(e?.response?.data?.detail || 'Failed to load leaderboard');
      }
      setData({ rows: [], summary: {} });
    } finally { setLoading(false); }
  }, [periods]);

  useEffect(() => { load(); }, [load]);

  if (loading) return <p className="text-sm opacity-60" data-testid="leaderboard-loading">Loading leaderboard…</p>;
  const rows = (data?.rows || []).slice(0, limit);
  const summary = data?.summary || {};
  if (!rows.length) {
    return (
      <div className="rounded-xl border p-5 text-center" style={{ borderColor: 'var(--theme-border)', background: 'var(--theme-surface)' }} data-testid="leaderboard-empty">
        <Trophy size={20} className="mx-auto mb-2 opacity-50" />
        <p className="text-sm opacity-70">No leaderboard yet — take a snapshot to start scoring forecast accuracy.</p>
      </div>
    );
  }

  return (
    <div className="rounded-xl border overflow-hidden" style={{ borderColor: 'var(--theme-border)', background: 'var(--theme-surface)' }} data-testid="forecast-leaderboard">
      <button
        onClick={() => setCollapsed((c) => !c)}
        className="w-full flex items-center justify-between gap-3 px-4 py-3 text-left"
        data-testid="leaderboard-toggle"
      >
        <div className="flex items-center gap-2 min-w-0">
          <Trophy size={16} style={{ color: '#d4af37' }} />
          <p className="text-sm font-bold tracking-tight" style={{ color: 'var(--theme-text)' }}>Top callers</p>
          <span className="text-[11px] opacity-60">· last {summary.periods || periods} {summary.period_type || 'quarter'}{(summary.periods || periods) !== 1 ? 's' : ''}</span>
        </div>
        {collapsed ? <ChevronRight size={14} className="opacity-50" /> : <ChevronDown size={14} className="opacity-50" />}
      </button>

      {!collapsed ? (
        <>
          <div className="divide-y" style={{ borderColor: 'var(--theme-border)' }}>
            {rows.map((r) => {
              const podium = PODIUM_ICONS[r.podium];
              const PIcon = podium?.Icon;
              return (
                <div key={r.user_id} className="px-4 py-2.5 flex items-center gap-3" data-testid={`leaderboard-row-${r.user_id}`}>
                  <div className="w-7 text-center text-xs font-extrabold tabular-nums" style={{ color: 'var(--theme-text-muted)' }}>
                    {podium ? <PIcon size={16} style={{ color: podium.colour }} /> : `#${r.rank}`}
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-semibold truncate" style={{ color: 'var(--theme-text)' }}>{r.owner_name}</p>
                    <p className="text-[11px] opacity-60">
                      {r.periods_scored} period{r.periods_scored !== 1 ? 's' : ''} scored · best {r.best_pct}% · worst {r.worst_pct}%
                    </p>
                  </div>
                  <div className="text-right shrink-0">
                    <p className="text-base font-extrabold tabular-nums" style={{ color: pctColour(r.average_accuracy_pct) }}>
                      {r.average_accuracy_pct}%
                    </p>
                    {r.bottom_quartile && r.average_accuracy_pct < 70 ? (
                      <p className="text-[10px] font-bold uppercase tracking-wider" style={{ color: 'var(--color-danger-red, #ef4444)' }} data-testid={`leaderboard-bottom-${r.user_id}`}>
                        Coach
                      </p>
                    ) : null}
                  </div>
                </div>
              );
            })}
          </div>
          {summary.below_70_count > 0 ? (
            <div className="px-4 py-2.5 text-[11px] border-t" style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text-muted)' }} data-testid="leaderboard-coach-hint">
              <span className="opacity-80">
                <strong style={{ color: 'var(--color-danger-red, #ef4444)' }}>{summary.below_70_count}</strong> rep{summary.below_70_count !== 1 ? 's' : ''} below {summary.below_70_threshold}% accuracy — might be worth a 1:1.
              </span>
            </div>
          ) : null}
        </>
      ) : null}
    </div>
  );
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import axios from 'axios';
import { toast } from 'sonner';
import {
  Plus, ArrowLeft, FileText, Upload, Download, Trash2, ShieldAlert,
  CheckCircle2, Circle, ClipboardList, History, AlertTriangle, Loader2, X,
  Sparkles, ClipboardCopy, GitCompare, Layers, WifiOff, CloudOff, RefreshCw, Cloud,
} from 'lucide-react';

const draftKey = (id) => `pis_survey_draft_${id}`;

const REPEATABLE = { site_contacts: 'Contact', rooms: 'Room / Area', equipment: 'Equipment', existing_equipment: 'Existing item', risks: 'Risk' };
const UNITS = ['m', 'cm', 'mm', 'ft/in'];

const fmtDiffVal = (v) => {
  if (v === true) return 'Yes';
  if (v === false) return 'No';
  if (v === null || v === undefined || v === '') return '—';
  if (Array.isArray(v)) return `${v.length} item${v.length === 1 ? '' : 's'}`;
  if (typeof v === 'object') return JSON.stringify(v);
  return String(v);
};

const statusColor = (s) => {
  if (['approved_for_installation', 'completed'].includes(s)) return 'var(--color-success-alt)';
  if (['installation_risk_identified'].includes(s)) return 'var(--color-error-ios, #ef4444)';
  if (['approved_for_quote', 'awaiting_installation_review', 'awaiting_design_review'].includes(s)) return 'var(--color-accent-amber)';
  if (['archived', 'superseded'].includes(s)) return 'var(--color-text-faint-alt)';
  return 'var(--color-info-ios)';
};
const readinessColor = (s) => {
  if (['ready_for_installation', 'installation_approved'].includes(s)) return 'var(--color-success-alt)';
