    if (!name.trim() || !sig || !agree) return;
    setSigning(true);
    try {
      await axios.post(`${API}/public/mod-quote/${token}/sign`, { signer_name: name.trim(), signature: sig });
      setDone(true);
    } catch (e) {
      setError(e.response?.data?.detail || 'Could not record your signature. Please try again.');
    }
    setSigning(false);
  };

  if (loading) return <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: '#F0F0F0' }}><Loader2 className="animate-spin" size={28} color="#6E7476" /></div>;

  if (error && !quote) return (
    <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: '#F0F0F0', padding: 24 }}>
      <div style={{ maxWidth: 420, textAlign: 'center', background: '#fff', padding: 40, borderRadius: 16, border: '1px solid #E0E0E0' }} data-testid="esign-error">
        <p style={{ fontSize: 16, fontWeight: 600, color: '#1B1C1D' }}>Link unavailable</p>
        <p style={{ fontSize: 14, color: '#6E7476', marginTop: 8 }}>{error}</p>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight: '100vh', background: '#F0F0F0', fontFamily: "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif" }}>
      {/* Header */}
      <div style={{ background: '#fff', borderBottom: '1px solid #E0E0E0' }}>
        <div style={{ maxWidth: 720, margin: '0 auto', padding: '18px 24px', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          {quote?.logo_url
            ? <img src={quote.logo_url} alt={quote.org_name} style={{ height: 36, maxWidth: 170, objectFit: 'contain' }} />
            : <span style={{ fontSize: 18, fontWeight: 700, color: '#1B1C1D' }}>{quote?.org_name}</span>}
          <a href={`${API}/public/mod-quote/${token}/pdf`} target="_blank" rel="noreferrer" data-testid="esign-pdf"
            style={{ fontSize: 13, color: brand, display: 'inline-flex', alignItems: 'center', gap: 6, fontWeight: 600 }}>
            <FileText size={15} /> PDF
          </a>
        </div>
      </div>

      <div style={{ maxWidth: 720, margin: '0 auto', padding: '28px 24px 60px' }}>
        {/* Title */}
        <div style={{ height: 4, background: brand, borderRadius: 999, width: 56, marginBottom: 16 }} />
        <p style={{ fontSize: 12, fontWeight: 700, letterSpacing: '0.06em', textTransform: 'uppercase', color: brand }}>
          Quote {quote?.quote_number}{quote?.mod_contract_type ? ` · MOD Contract Type ${quote.mod_contract_type}` : ''}
        </p>
        <h1 style={{ fontSize: 26, fontWeight: 800, color: '#1B1C1D', margin: '6px 0 4px' }}>{quote?.title}</h1>
        <p style={{ fontSize: 14, color: '#6E7476' }}>{quote?.mod_site_name || quote?.company_name}</p>

        {/* Line items */}
        <div style={{ background: '#fff', border: '1px solid #E0E0E0', borderRadius: 14, marginTop: 20, overflow: 'hidden' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 14 }}>
            <thead>
              <tr style={{ background: '#F7F7F7', color: '#6E7476', fontSize: 12, textAlign: 'left' }}>
                <th style={{ padding: '10px 16px' }}>Description</th>
                <th style={{ padding: '10px 8px', textAlign: 'center', width: 50 }}>Qty</th>
                <th style={{ padding: '10px 16px', textAlign: 'right', width: 110 }}>Amount</th>
              </tr>
            </thead>
            <tbody>
              {(quote?.lines || []).map((l, i) => (
                <tr key={i} style={{ borderTop: '1px solid #F0F0F0' }}>
                  <td style={{ padding: '10px 16px', color: '#1B1C1D' }}>{l.description || l.product_name}</td>
                  <td style={{ padding: '10px 8px', textAlign: 'center', color: '#6E7476' }}>{l.quantity}</td>
                  <td style={{ padding: '10px 16px', textAlign: 'right', color: '#1B1C1D' }}>{money((Number(l.unit_price) || 0) * (Number(l.quantity) || 1), cur)}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <div style={{ padding: '14px 16px', borderTop: '1px solid #E0E0E0', background: '#FAFCFF' }}>
            <Row label="Net" val={money(quote?.subtotal, cur)} />
            <Row label={`VAT (${quote?.vat_rate ?? 20}%)`} val={money(quote?.vat_amount, cur)} />
            <Row label="Total" val={money(quote?.total, cur)} bold color={brand} />
          </div>
        </div>
        {quote?.notes && <p style={{ fontSize: 13, color: '#6E7476', marginTop: 14 }}>{quote.notes}</p>}

        {/* Sign / done */}
        {done ? (
          <div style={{ marginTop: 24, background: '#fff', border: '1px solid #BBF7D0', borderRadius: 14, padding: 28, textAlign: 'center' }} data-testid="esign-done">
            <CheckCircle2 size={40} color="#16A34A" style={{ margin: '0 auto' }} />
            <p style={{ fontSize: 18, fontWeight: 700, color: '#1B1C1D', marginTop: 10 }}>Quote accepted</p>
            <p style={{ fontSize: 14, color: '#6E7476', marginTop: 4 }}>
              Signed by {quote?.signer_name || name}{quote?.signed_at ? ` on ${new Date(quote.signed_at).toLocaleDateString('en-GB')}` : ''}. Thank you — {quote?.org_name} has been notified.
            </p>
          </div>
        ) : (
          <div style={{ marginTop: 24, background: '#fff', border: '1px solid #E0E0E0', borderRadius: 14, padding: 24 }}>
            <p style={{ fontSize: 15, fontWeight: 700, color: '#1B1C1D', display: 'flex', alignItems: 'center', gap: 8 }}>
              <PenLine size={17} color={brand} /> Accept &amp; sign this quote
            </p>
            <label style={{ display: 'block', fontSize: 12, color: '#6E7476', margin: '16px 0 4px', fontWeight: 600 }}>Full name</label>
            <input value={name} onChange={e => setName(e.target.value)} placeholder="e.g. Maj. A. Smith" data-testid="esign-name"
              style={{ width: '100%', padding: '10px 12px', border: '1px solid #C9CBCC', borderRadius: 8, fontSize: 14, color: '#1B1C1D', outline: 'none' }} />
            <label style={{ display: 'block', fontSize: 12, color: '#6E7476', margin: '16px 0 4px', fontWeight: 600 }}>Signature</label>
            <SignaturePad onChange={setSig} />
            <label style={{ display: 'flex', alignItems: 'flex-start', gap: 8, marginTop: 14, fontSize: 13, color: '#565B5E' }}>
              <input type="checkbox" checked={agree} onChange={e => setAgree(e.target.checked)} data-testid="esign-agree" style={{ marginTop: 2 }} />
              I confirm I am authorised to accept this quote and agree to its terms on behalf of {quote?.mod_site_name || quote?.company_name || 'the customer'}.
            </label>
            {error && <p style={{ color: '#DC2626', fontSize: 13, marginTop: 10 }}>{error}</p>}
            <button onClick={sign} disabled={!name.trim() || !sig || !agree || signing} data-testid="esign-submit"
              style={{ marginTop: 18, width: '100%', padding: '13px', background: (!name.trim() || !sig || !agree) ? '#9A9FA1' : brand, color: '#fff', border: 'none', borderRadius: 10, fontSize: 15, fontWeight: 700, cursor: (!name.trim() || !sig || !agree) ? 'not-allowed' : 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8 }}>
              {signing ? <Loader2 size={17} className="animate-spin" /> : <ShieldCheck size={17} />} Accept &amp; Sign
            </button>
          </div>
        )}
        <p style={{ textAlign: 'center', fontSize: 11, color: '#9A9FA1', marginTop: 24 }}>Secured by {quote?.org_name} · Pulse Fitness</p>
      </div>
    </div>
  );
}

function Row({ label, val, bold, color }) {
  return (
    <div style={{ display: 'flex', justifyContent: 'space-between', padding: '3px 0' }}>
      <span style={{ fontSize: bold ? 15 : 13, color: bold ? '#1B1C1D' : '#6E7476', fontWeight: bold ? 700 : 500 }}>{label}</span>
      <span style={{ fontSize: bold ? 16 : 13, color: color || (bold ? '#1B1C1D' : '#393E41'), fontWeight: bold ? 800 : 600 }}>{val}</span>
    </div>
  );
}

/**
 * RepTrackRecord — iter 215dh.
 *
 * Per-rep "Your forecast track record" widget. Renders the last N
 * snapshotted periods for one rep with:
 *   - sparkline of accuracy %
 *   - row-by-row breakdown (period / call / actual / Δ / verdict)
 *   - summary tiles: average / best / worst / trend
 *
 * Used in two places:
 *   1. Rep self-view on the CRM start dashboard (no userId prop → defaults to me).
 *   2. Drill-down on the Accuracy tab (userId prop set to the row's rep).
 *
 * Backend: GET /api/crm/forecast/track-record?user_id=&periods=
 */
import { useCallback, useEffect, useMemo, useState } from 'react';
import { formatMoneySync } from '@/utils/localization';
import axios from 'axios';
import { toast } from 'sonner';
import { Award, AlertTriangle, Target, TrendingUp, TrendingDown, Activity } from 'lucide-react';

const API = process.env.REACT_APP_BACKEND_URL ? `${process.env.REACT_APP_BACKEND_URL}/api` : '/api';
const auth = () => { const _t = localStorage.getItem('crm_token'); return { headers: _t ? { Authorization: `Bearer ${_t}` } : {} }; };

function fmtMoney(n) {
  const v = Number(n) || 0;
  return formatMoneySync(v, { maximumFractionDigits: 0 });
}

const VERDICT_META = {
  on_call: { label: 'On call', icon: Target, colour: 'var(--color-success-green, #10b981)' },
  under: { label: 'Missed', icon: AlertTriangle, colour: 'var(--color-danger-red, #ef4444)' },
  over: { label: 'Sandbagger', icon: Award, colour: 'var(--color-warning, #f59e0b)' },
};

function Sparkline({ points, height = 36 }) {
  if (!points.length) return null;
  const w = 200;
  const max = 100; // accuracy is 0-100
  const stepX = w / Math.max(1, points.length - 1);
  const path = points
    .map((p, i) => `${i === 0 ? 'M' : 'L'} ${i * stepX},${height - (p / max) * (height - 4) - 2}`)
    .join(' ');
  return (
    <svg width={w} height={height} className="overflow-visible" data-testid="track-record-sparkline">
      <path d={path} fill="none" stroke="var(--color-brand-blue, #0091ca)" strokeWidth="2" />
      {points.map((p, i) => (
        <circle key={i} cx={i * stepX} cy={height - (p / 100) * (height - 4) - 2} r="3" fill="var(--color-brand-blue, #0091ca)" />
      ))}
    </svg>
  );
}

export default function RepTrackRecord({ userId = '', periods = 4, compact = false }) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams({ periods: String(periods) });
      if (userId) params.set('user_id', userId);
      const r = await axios.get(`${API}/crm/forecast/track-record?${params.toString()}`, auth());
      setData(r.data);
    } catch (e) {
      if (e?.response?.status !== 403) toast.error(e?.response?.data?.detail || 'Failed to load track record');
      setData({ rows: [], summary: {} });
    } finally { setLoading(false); }
  }, [userId, periods]);

  useEffect(() => { load(); }, [load]);

  // eslint-disable-next-line react-hooks/exhaustive-deps -- intentional: reviewed in iter 216h226-deps-walk — effect either runs once on mount or re-fires on the listed trigger deps; omitted refs are stable identities or fetcher closures that read live state at call time, so including them would re-fire without changing semantics.
  const rows = data?.rows || [];
  const summary = data?.summary || {};
  const sparkPoints = useMemo(() => rows.map(r => r.call_accuracy_pct ?? 0), [rows]);

  const trendIcon = summary.trend === 'improving' ? TrendingUp : summary.trend === 'declining' ? TrendingDown : Activity;
  const trendColour = summary.trend === 'improving' ? 'var(--color-success-green, #10b981)' : summary.trend === 'declining' ? 'var(--color-danger-red, #ef4444)' : 'var(--theme-text-muted, #6e7476)';
  const TrendIcon = trendIcon;

  if (loading) return <p className="text-sm opacity-60" data-testid="track-record-loading">Loading track record…</p>;
  if (!rows.length) {
    return (
      <div className="rounded-xl border p-5 text-center" style={{ borderColor: 'var(--theme-border)', background: 'var(--theme-surface)' }} data-testid="track-record-empty">
        <Activity size={20} className="mx-auto mb-2 opacity-50" />
        <p className="text-sm opacity-70">No forecast snapshots yet — your manager hasn't frozen any periods.</p>
        <p className="text-xs opacity-50 mt-1">Once a snapshot is taken at period close, your accuracy track record will start filling in here.</p>
      </div>
    );
  }

  return (
    <div className={compact ? 'space-y-3' : 'space-y-4'} data-testid="rep-track-record">
      {!compact ? (
        <div className="flex items-start justify-between gap-3 flex-wrap">
          <div>
            <p className="text-[10px] font-bold uppercase tracking-[0.2em]" style={{ color: 'var(--color-brand-blue, #0091ca)' }}>Your forecast track record</p>
            <h3 className="text-lg font-extrabold" style={{ color: 'var(--theme-text)' }}>
              {data?.owner_name ? `${data.owner_name}'s call accuracy` : 'Call accuracy over time'}
            </h3>
          </div>
          <Sparkline points={sparkPoints} />
        </div>
      ) : (
        <Sparkline points={sparkPoints} />
      )}

      <div className="grid grid-cols-2 md:grid-cols-4 gap-2" data-testid="track-record-tiles">
        <div className="rounded-lg border p-3" style={{ borderColor: 'var(--theme-border)' }}>
          <p className="text-[10px] font-bold uppercase tracking-wider opacity-60">Average</p>
          <p className="text-lg font-extrabold tabular-nums mt-0.5" style={{ color: 'var(--color-brand-blue, #0091ca)' }}>
            {summary.average_accuracy_pct != null ? `${summary.average_accuracy_pct}%` : '—'}
          </p>
        </div>
        <div className="rounded-lg border p-3" style={{ borderColor: 'var(--theme-border)' }}>
          <p className="text-[10px] font-bold uppercase tracking-wider opacity-60">Best</p>
          <p className="text-lg font-extrabold tabular-nums mt-0.5" style={{ color: 'var(--color-success-green, #10b981)' }}>
            {summary.best_pct != null ? `${summary.best_pct}%` : '—'}
          </p>
        </div>
        <div className="rounded-lg border p-3" style={{ borderColor: 'var(--theme-border)' }}>
          <p className="text-[10px] font-bold uppercase tracking-wider opacity-60">Worst</p>
          <p className="text-lg font-extrabold tabular-nums mt-0.5" style={{ color: 'var(--color-danger-red, #ef4444)' }}>
            {summary.worst_pct != null ? `${summary.worst_pct}%` : '—'}
          </p>
        </div>
        <div className="rounded-lg border p-3" style={{ borderColor: 'var(--theme-border)' }}>
          <p className="text-[10px] font-bold uppercase tracking-wider opacity-60">Trend</p>
          <p className="text-base font-extrabold capitalize mt-0.5 inline-flex items-center gap-1" style={{ color: trendColour }}>
            <TrendIcon size={14} /> {summary.trend || 'stable'}
          </p>
        </div>
      </div>

      <div className="rounded-xl border overflow-hidden" style={{ borderColor: 'var(--theme-border)' }} data-testid="track-record-table">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead style={{ background: 'var(--theme-surface)' }}>
              <tr className="text-left text-[11px] uppercase tracking-wider opacity-70">
                <th className="px-3 py-2">Period</th>
                <th className="px-3 py-2 text-right">Call / Commit</th>
                <th className="px-3 py-2 text-right">Actual won</th>
                <th className="px-3 py-2 text-right">Δ</th>
                <th className="px-3 py-2 text-right">Accuracy</th>
                <th className="px-3 py-2">Verdict</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((r) => {
                const v = VERDICT_META[r.verdict] || VERDICT_META.on_call;
                const VIcon = v.icon;
                return (
                  <tr key={r.period_key} className="border-t" style={{ borderColor: 'var(--theme-border)' }} data-testid={`track-record-row-${r.period_key}`}>
                    <td className="px-3 py-2 font-semibold" style={{ color: 'var(--theme-text)' }}>{r.period_key}</td>
                    <td className="px-3 py-2 text-right tabular-nums">
                      {r.manager_call > 0 ? fmtMoney(r.manager_call) : fmtMoney(r.commit_at_snapshot)}
                    </td>
                    <td className="px-3 py-2 text-right tabular-nums" style={{ color: 'var(--color-success-green, #10b981)', fontWeight: 700 }}>{fmtMoney(r.actual_closed_won)}</td>
                    <td className="px-3 py-2 text-right tabular-nums" style={{ color: r.delta >= 0 ? 'var(--color-success-green, #10b981)' : 'var(--color-danger-red, #ef4444)' }}>
                      {r.delta >= 0 ? '+' : ''}{fmtMoney(r.delta)}
                    </td>
                    <td className="px-3 py-2 text-right tabular-nums font-semibold">{r.call_accuracy_pct != null ? `${r.call_accuracy_pct}%` : '—'}</td>
                    <td className="px-3 py-2">
                      <span className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full text-[11px] font-bold" style={{ background: `${v.colour}22`, color: v.colour }}>
                        <VIcon size={11} /> {v.label}
                      </span>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

/**
 * Dedicated "Choose your plan" checkout page (iter 221).
 *
 * Where trial-ending emails now land. Unlike the public marketing pricing
 * page, this surface is login-gated and shows NO free-trial offer — the
 * visitor already has an account, so we get them straight to picking a
 * paid plan and into Stripe Checkout. On successful payment the backend
 * webhook converts the trial to paid automatically.
 *
 * Reuses the existing self-serve flow:
 *   GET  /api/payments/pricing        → bundle + module catalogue
 *   POST /api/payments/checkout/flex  → Stripe Checkout session
 */
import { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import { motion } from 'framer-motion';
import { toast } from 'sonner';
import {
  Check, ArrowRight, Loader2, Minus, Plus, ShieldCheck, Sparkles, MessageCircle,
} from 'lucide-react';
import { useAuth } from '@/App';

const MODULE_BLURB = {
  operations: 'Equipment, faults, check sheets, AI triage & engineer ops.',
  crm: 'Pipeline, quoting, contracts & customer relationships.',
  marketing: 'Campaigns, social autopilot & growth tooling.',
  memberships: 'Members, plans, timetables & the member app.',
};

export default function ChoosePlanPage() {
  const { API, token, user, logout } = useAuth();
  const [pricing, setPricing] = useState(null);
  const [live, setLive] = useState(null);
  const [currency, setCurrency] = useState('gbp');
  const [cycle, setCycle] = useState('monthly');
  const [siteCount, setSiteCount] = useState(1);
  const [busy, setBusy] = useState(null);

  useEffect(() => {
    let cancelled = false;
    axios.get(`${API}/payments/pricing`)
      .then((r) => { if (!cancelled) setPricing(r.data); })
      .catch(() => { if (!cancelled) setPricing(null); });
    axios.get(`${API}/payments/pricing/live`)
      .then((r) => { if (!cancelled) { setLive(r.data); if (r.data?.detected_currency) setCurrency(r.data.detected_currency); } })
      .catch(() => { if (!cancelled) setLive(null); });
    return () => { cancelled = true; };
  }, [API]);

  const CCY = { gbp: '£', eur: '€', usd: '$' };
  const annual = cycle === 'annual';
  const priceFor = (moduleId) => {
    const node = live?.pricing?.[moduleId]?.[currency];
    if (!node) return null;
    const minor = annual ? node.annual : node.monthly;
    return minor == null ? null : minor / 100;
  };
  const fmtPrice = (moduleId) => {
    const v = priceFor(moduleId);
    if (v == null) return null;
    return `${CCY[currency] || ''}${Math.round(v)}${annual ? '/yr' : '/mo'}`;
  };

  const startCheckout = async (plan, opts = {}) => {
    setBusy(opts.module_id || plan);
    try {
      const body = {
        plan,
        origin_url: window.location.origin,
        currency: opts.currency || currency,
        billing_cycle: opts.cycle || cycle,
      };
      if (opts.module_id) body.module_id = opts.module_id;
      const { data } = await axios.post(
        `${API}/payments/checkout/flex`,
        body,
        { headers: { Authorization: `Bearer ${token}` } },
      );
      if (data?.url) {
        window.location.href = data.url;
      } else {
        toast.error('Could not open checkout');
        setBusy(null);
      }
    } catch (e) {
      toast.error(e.response?.data?.detail || 'Could not open checkout');
      setBusy(null);
    }
  };

  // Deep-link from the pricing page: /choose-plan?module=crm&billing=annual&currency=eur
  // pre-selects the currency/cycle and takes the (now signed-in) customer
  // straight into Stripe checkout for the module they chose.
  const autoCheckoutRef = useRef(false);
  useEffect(() => {
    if (autoCheckoutRef.current || !token || !live) return;
    const p = new URLSearchParams(window.location.search);
    const qCcy = (p.get('currency') || '').toLowerCase();
    const qCycle = p.get('billing');
    const mod = (p.get('module') || '').toLowerCase();
    const validCcy = ['gbp', 'eur', 'usd'].includes(qCcy) ? qCcy : null;
    const validCycle = (qCycle === 'annual' || qCycle === 'monthly') ? qCycle : null;
    if (validCcy) setCurrency(validCcy);
    if (validCycle) setCycle(validCycle);
    if (['operations', 'crm', 'marketing', 'memberships'].includes(mod)) {
      autoCheckoutRef.current = true;
      startCheckout('module', { module_id: mod, currency: validCcy || undefined, cycle: validCycle || undefined });
    }
  }, [token, live]); // eslint-disable-line react-hooks/exhaustive-deps

  const bundle = pricing?.bundle;
  const modules = pricing?.modules || [];
  const bundleTotal = bundle ? bundle.monthly + (siteCount - 1) * bundle.per_site : 0;

  return (
    <div className="min-h-screen bg-zinc-50" data-testid="choose-plan-page">
      {/* Top bar */}
      <header className="border-b border-zinc-200 bg-white">
        <div className="max-w-5xl mx-auto px-6 h-16 flex items-center justify-between">
          <span className="font-extrabold tracking-tight text-zinc-900 text-lg">
            Pulse Fitness<span className="text-[#19CDFF]">.AI</span>
          </span>
          <button
            type="button"
            onClick={logout}
            className="text-sm text-zinc-500 hover:text-zinc-900 transition-colors"
            data-testid="choose-plan-signout"
          >
            Sign out
          </button>
        </div>
      </header>

      <main className="max-w-5xl mx-auto px-6 py-12 sm:py-16">
        {/* Hero */}
        <motion.div
          initial={{ opacity: 0, y: 14 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5, ease: [0.16, 1, 0.3, 1] }}
          className="max-w-2xl"
        >
          <div className="inline-flex items-center gap-2 text-xs uppercase tracking-[0.18em] text-[#0073A4] font-semibold mb-4">
            <Sparkles size={13} /> Keep your account active
          </div>
          <h1 className="text-3xl sm:text-4xl lg:text-5xl font-extrabold tracking-tight text-zinc-900 leading-[1.08]">
            {user?.full_name ? `Welcome back, ${user.full_name.split(' ')[0]}.` : 'Choose your plan.'}
          </h1>
          <p className="mt-4 text-base text-zinc-500 leading-relaxed">
            Your trial has ended. Pick the plan that fits and keep everything you&apos;ve already set up —
            no re-import, instant access. Choose the modules you need — each one is a standalone subscription.
          </p>
          <div className="mt-5 inline-flex items-center gap-2 text-xs text-zinc-500">
            <ShieldCheck size={14} className="text-emerald-500" />
            Secure checkout via Stripe · cancel anytime
          </div>
        </motion.div>

        {/* Currency + billing controls */}
        <div className="mt-8 flex flex-wrap items-center gap-3" data-testid="choose-plan-controls">
          <div className="inline-flex rounded-full border border-zinc-200 bg-white p-1" data-testid="currency-toggle">
            {['gbp', 'eur', 'usd'].map((c) => (
              <button
                key={c}
                type="button"
                onClick={() => setCurrency(c)}
                className={`px-3.5 h-8 rounded-full text-sm font-semibold transition-colors ${currency === c ? 'bg-[#19CDFF] text-[#1B1C1D]' : 'text-zinc-500 hover:text-zinc-900'}`}
                data-testid={`currency-${c}`}
              >
                {CCY[c]} {c.toUpperCase()}
              </button>
            ))}
          </div>
          <div className="inline-flex items-center rounded-full border border-zinc-200 bg-white p-1" data-testid="billing-toggle">
            {[['monthly', 'Monthly'], ['annual', 'Annual']].map(([v, label]) => (
              <button
                key={v}
                type="button"
                onClick={() => setCycle(v)}
                className={`px-3.5 h-8 rounded-full text-sm font-semibold transition-colors ${cycle === v ? 'bg-[#19CDFF] text-[#1B1C1D]' : 'text-zinc-500 hover:text-zinc-900'}`}
                data-testid={`billing-${v}`}
              >
                {label}
              </button>
            ))}
            {live?.annual_discount_pct ? (
              <span className="px-2.5 text-xs font-semibold text-[#0073A4]">Save {live.annual_discount_pct}%</span>
            ) : null}
          </div>
        </div>


        {!pricing && (
          <div className="mt-12 flex items-center gap-2 text-sm text-zinc-400" data-testid="choose-plan-loading">
            <Loader2 size={16} className="animate-spin" /> Loading plans…
          </div>
        )}

        {pricing && (
          <>
            {/* Individual modules */}
            <div className="mt-12">
              <h3 className="text-lg font-bold text-zinc-900" style={{ fontFamily: 'Proxima Nova, sans-serif' }}>Choose your modules</h3>
              <p className="text-sm text-zinc-500 mt-1">Every module is a standalone subscription — mix and match, cancel anytime.</p>
              <div className="mt-4 grid gap-3 sm:grid-cols-2">
                {[...modules].sort((a, b) => (a.id === 'operations' ? -1 : b.id === 'operations' ? 1 : 0)).map((m) => {
                  const featured = m.id === 'operations';
                  return (
                  <div
                    key={m.id}
                    className={`relative rounded-xl bg-white p-5 flex flex-col justify-between gap-4 transition-colors ${featured ? 'border-2 border-[#19CDFF] shadow-lg' : 'border border-zinc-200 hover:border-[#19CDFF]'}`}
                    data-testid={`choose-plan-module-${m.id}`}
                  >
                    {featured ? (
                      <span className="absolute -top-2.5 left-5 bg-[#19CDFF] text-[#1B1C1D] text-[10px] font-bold uppercase tracking-[0.14em] px-2.5 py-0.5 rounded-full" data-testid="choose-plan-flagship-badge">Recommended</span>
                    ) : null}
                    <div>
                      <div className="flex items-baseline justify-between gap-2">
                        <span className="font-semibold text-zinc-900 capitalize">{featured ? 'Operations — Pulse Fitness Pro' : m.name}</span>
                        <span className="text-sm text-zinc-500" data-testid={`choose-plan-module-price-${m.id}`}><strong className="text-zinc-900">{fmtPrice(m.id) || `£${m.monthly.toFixed(0)}/mo`}</strong></span>
                      </div>
                      <p className="text-xs text-zinc-500 mt-1 leading-relaxed">{MODULE_BLURB[m.id] || ''}</p>
                    </div>
                    <button
                      type="button"
                      onClick={() => startCheckout('module', { module_id: m.id })}
                      disabled={busy === m.id}
                      className={`w-full h-10 rounded-full font-medium text-sm flex items-center justify-center gap-2 transition-colors disabled:opacity-60 ${featured ? 'bg-[#19CDFF] hover:bg-[#4DDBFF] text-[#1B1C1D]' : 'border border-zinc-300 text-zinc-800 hover:border-[#19CDFF] hover:bg-[#E6F9FF]'}`}
                      data-testid={`choose-plan-module-checkout-${m.id}`}
                    >
                      {busy === m.id ? <Loader2 size={14} className="animate-spin" /> : null}
                      Choose {featured ? 'Pulse Fitness Pro' : m.name} <ArrowRight size={14} />
                    </button>
                  </div>
                  );
                })}
              </div>
            </div>

            {/* Talk to us */}
            <div className="mt-12 rounded-xl border border-zinc-200 bg-white p-6 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
              <div className="flex items-start gap-3">
                <div className="w-10 h-10 rounded-lg bg-[#E6F9FF] flex items-center justify-center flex-shrink-0">
                  <MessageCircle size={18} className="text-[#0073A4]" />
                </div>
                <div>
                  <p className="font-semibold text-zinc-900 text-sm">Prefer to talk it through first?</p>
                  <p className="text-sm text-zinc-500">Not sure which plan fits? Our team will help you pick the right setup.</p>
                </div>
              </div>
              <a
                href="mailto:support@pulsefitness.ai?subject=Help%20choosing%20a%20PulseFitness%20plan"
                className="flex-shrink-0 h-10 px-5 rounded-lg border border-zinc-300 text-zinc-800 font-medium text-sm flex items-center justify-center hover:bg-zinc-50 transition-colors"
                data-testid="choose-plan-talk-to-us"
              >
                Talk to us
              </a>
            </div>
          </>
        )}
      </main>
    </div>
  );
}

/**
 * Pulse Fitness AI — campaign analytics modal: rates, click map, bot
 * filtering toggle, conversions and an AI "why did this perform?" summary.
 */
import React, { useCallback, useEffect, useState } from 'react';
import axios from 'axios';
import { toast } from 'sonner';
import { X, Wand2, Loader2, MousePointerClick } from 'lucide-react';

const apiRoot = (API) => (API || process.env.REACT_APP_BACKEND_URL || '').replace(/\/api\/?$/, '');
const card = { background: 'var(--theme-surface)', borderColor: 'var(--theme-border)' };
const muted = { color: 'var(--theme-text-muted)' };
const txt = { color: 'var(--theme-text)' };

function Metric({ label, value, suffix }) {
  return (
    <div className="rounded-xl border p-3" style={card}>
      <p className="text-[11px] font-bold uppercase tracking-wide" style={muted}>{label}</p>
      <p className="text-xl font-extrabold pulse-font-heading" style={txt}>{value}{suffix}</p>
    </div>
  );
}

export default function CampaignAnalytics({ campaign, API, headers, onClose }) {
  const [bots, setBots] = useState('exclude');
  const [data, setData] = useState(null);
  const [ai, setAi] = useState(null);
  const [aiBusy, setAiBusy] = useState(false);

  const load = useCallback(async () => {
    try {
      const r = await axios.get(`${apiRoot(API)}/api/comms/campaigns/${campaign.id}/analytics?bots=${bots}`, { headers });
      setData(r.data);
    } catch { toast.error('Failed to load analytics'); }
  }, [API, headers, campaign.id, bots]);
  useEffect(() => { load(); }, [load]);

  const analyse = async () => {
    setAiBusy(true);
    try {
      const r = await axios.post(`${apiRoot(API)}/api/comms/campaigns/${campaign.id}/ai-analyse`, {}, { headers });
      setAi(r.data.analysis);
    } catch (e) { toast.error(e?.response?.data?.detail || 'AI is unavailable right now'); }
    finally { setAiBusy(false); }
  };

  return (
    <div className="fixed inset-0 z-[160] bg-black/50 flex items-center justify-center p-4" onClick={onClose}>
      <div className="rounded-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto border" style={card} onClick={(e) => e.stopPropagation()} data-testid="campaign-analytics-modal">
        <div className="flex items-center justify-between px-6 py-4 border-b sticky top-0" style={{ ...card, borderColor: 'var(--theme-border)' }}>
          <h3 className="font-bold text-lg pulse-font-heading" style={txt}>{campaign.name} — analytics</h3>
          <button onClick={onClose} className="p-1.5 rounded-lg hover:bg-black/5" style={muted}><X size={18} /></button>
        </div>
        <div className="p-6">
          {!data ? <p className="text-sm" style={muted}>Loading…</p> : (
            <>
              <div className="flex items-center justify-end gap-2 mb-3">
                <span className="text-xs font-semibold" style={muted}>Bot filtering</span>
                <select value={bots} onChange={(e) => setBots(e.target.value)} className="px-2 py-1 rounded-lg text-xs border" style={{ ...card, ...txt }} data-testid="analytics-bots">
                  <option value="exclude">Exclude bots ({data.bot_opens})</option>
                  <option value="include">Include bots</option>
                </select>
              </div>
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-4">
                <Metric label="Sent" value={data.totals.sent} />
                <Metric label="Open rate" value={data.rates.open_rate} suffix="%" />
                <Metric label="Click rate" value={data.rates.click_rate} suffix="%" />
                <Metric label="Bounce rate" value={data.rates.bounce_rate} suffix="%" />
              </div>

              {data.conversions && (
                <div className="grid grid-cols-3 gap-3 mb-4" data-testid="analytics-conversions">
                  <Metric label="Conversions" value={data.conversions.count} />
                  <Metric label="Conv. rate" value={data.conversions.conversion_rate} suffix="%" />
                  <Metric label="Revenue" value={`£${data.conversions.revenue_gbp}`} />
                </div>
              )}
              {data.conversions && Object.keys(data.conversions.by_type || {}).length > 0 && (
                <div className="flex flex-wrap gap-2 mb-4">
                  {Object.entries(data.conversions.by_type).map(([t, n]) => (
                    <span key={t} className="text-xs font-bold px-2.5 py-1 rounded-full" style={{ background: 'var(--theme-bg)', ...txt }}>{t.replace(/_/g, ' ')}: {n}</span>
                  ))}
                </div>
              )}

              <div className="mb-4">
                <p className="flex items-center gap-1.5 text-xs font-bold uppercase tracking-wide mb-2" style={muted}><MousePointerClick size={13} />Click map</p>
                {data.click_map.length === 0 ? <p className="text-sm" style={muted}>No link clicks recorded yet.</p> : (
                  <div className="space-y-1.5">
                    {data.click_map.map((c, i) => (
                      <div key={i} className="flex items-center justify-between gap-2 text-sm px-3 py-2 rounded-lg" style={{ background: 'var(--theme-bg)' }}>
                        <span className="truncate" style={txt}>{c.url}</span><span className="font-bold shrink-0" style={{ color: 'var(--color-brand-cyan)' }}>{c.clicks}</span>
                      </div>
                    ))}
                  </div>
                )}
              </div>

              <button onClick={analyse} disabled={aiBusy} className="w-full flex items-center justify-center gap-1.5 px-4 py-2.5 rounded-xl text-sm font-bold text-white disabled:opacity-50 mb-3" style={{ backgroundImage: 'linear-gradient(135deg,#0091CA,#19CDFF)' }} data-testid="analytics-ai-analyse">
                {aiBusy ? <Loader2 size={15} className="animate-spin" /> : <Wand2 size={15} />}Analyse with AI
              </button>
              {ai && (
                <div className="rounded-xl border p-4 text-sm" style={card} data-testid="ai-analysis">
                  <p className="font-semibold mb-2" style={txt}>{ai.summary}</p>
                  {ai.what_worked?.length > 0 && <><p className="text-xs font-bold uppercase tracking-wide mt-2 mb-1" style={muted}>What worked</p><ul className="list-disc pl-5 space-y-0.5" style={muted}>{ai.what_worked.map((x, i) => <li key={i}>{x}</li>)}</ul></>}
                  {ai.what_to_improve?.length > 0 && <><p className="text-xs font-bold uppercase tracking-wide mt-2 mb-1" style={muted}>To improve</p><ul className="list-disc pl-5 space-y-0.5" style={muted}>{ai.what_to_improve.map((x, i) => <li key={i}>{x}</li>)}</ul></>}
                  {ai.recommendations?.length > 0 && <><p className="text-xs font-bold uppercase tracking-wide mt-2 mb-1" style={muted}>Recommendations</p><ul className="list-disc pl-5 space-y-0.5" style={muted}>{ai.recommendations.map((x, i) => <li key={i}>{x}</li>)}</ul></>}
                </div>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
}

/**
 * CampaignsPanel — the shared Comms campaign surface, themed with the
 * platform design tokens so it looks identical whether it's mounted as the
 * Comms Centre module, the Memberships → Emails tab, or the CRM →
 * Communications view. Pass a fixed `module` to scope it to that context;
 * all three read the SAME `/api/comms/campaigns` records.
 */
import React, { useCallback, useEffect, useMemo, useState } from 'react';
import axios from 'axios';
import { toast } from 'sonner';
import {
  Megaphone, Send, Copy, Archive, Pencil, Plus, Eye, MousePointerClick, X, BarChart3,
} from 'lucide-react';
import EmailBuilder from './EmailBuilder';
import CampaignAnalytics from './CampaignAnalytics';

const STATUS_STYLE = {
  draft: 'bg-slate-500/15 text-slate-500',
  in_review: 'bg-amber-500/15 text-amber-600',
  changes_requested: 'bg-orange-500/15 text-orange-600',
  approved: 'bg-blue-500/15 text-blue-600',
  scheduled: 'bg-violet-500/15 text-violet-600',
  sending: 'bg-cyan-500/15 text-cyan-600',
  sent: 'bg-emerald-500/15 text-emerald-600',
  paused: 'bg-yellow-500/15 text-yellow-700',
  cancelled: 'bg-rose-500/15 text-rose-600',
  archived: 'bg-slate-500/10 text-slate-400',
};
const MODULE_BADGE = {
  marketing: 'bg-fuchsia-500/12 text-fuchsia-600',
  memberships: 'bg-cyan-500/12 text-cyan-700',
  crm: 'bg-indigo-500/12 text-indigo-600',
};

function StatCard({ label, value, icon: Icon, suffix }) {
  return (
    <div
      className="rounded-2xl p-4 border"
      style={{ background: 'var(--theme-surface)', borderColor: 'var(--theme-border)' }}
      data-testid={`stat-${label.toLowerCase().replace(/\s+/g, '-')}`}
    >
      <div className="flex items-center gap-2 mb-1" style={{ color: 'var(--theme-text-muted)' }}>
        <Icon size={15} /><span className="text-xs font-bold uppercase tracking-wide">{label}</span>
      </div>
      <p className="text-2xl font-extrabold pulse-font-heading" style={{ color: 'var(--theme-text)' }}>{value}{suffix}</p>
    </div>
  );
}

export default function CampaignsPanel({ API, headers, module = 'all', testIdPrefix = 'comms' }) {
  // Callers pass either a bare backend URL (Comms Centre / CRM) or the
  // useAuth().API which already includes "/api" (Memberships). Normalise so
  // we always hit "<root>/api/comms/*" exactly once.
  const apiRoot = useMemo(() => (API || process.env.REACT_APP_BACKEND_URL || '').replace(/\/api\/?$/, ''), [API]);
  const [meta, setMeta] = useState(null);
  const [dash, setDash] = useState(null);
  const [campaigns, setCampaigns] = useState([]);
  const [statusFilter, setStatusFilter] = useState('');
  const [q, setQ] = useState('');
  const [loading, setLoading] = useState(true);
  const [showCreate, setShowCreate] = useState(false);
  const [editing, setEditing] = useState(null);
  const [analytics, setAnalytics] = useState(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const [d, c] = await Promise.all([
        axios.get(`${apiRoot}/api/comms/dashboard`, { params: { module }, headers }),
        axios.get(`${apiRoot}/api/comms/campaigns`, { params: { module, status: statusFilter || undefined, q: q || undefined }, headers }),
      ]);
      setDash(d.data);
      setCampaigns(c.data.campaigns || []);
    } catch (e) {
      toast.error(e?.response?.data?.detail || 'Failed to load campaigns');
    } finally { setLoading(false); }
  }, [apiRoot, headers, module, statusFilter, q]);

  useEffect(() => { axios.get(`${apiRoot}/api/comms/meta`, { headers }).then((r) => setMeta(r.data)).catch(() => {}); }, [apiRoot, headers]);
  useEffect(() => { load(); }, [load]);

  const typeLabel = (id) => meta?.campaign_types.find((t) => t.id === id)?.label || id;

  const duplicate = async (c) => {
    try { await axios.post(`${apiRoot}/api/comms/campaigns/${c.id}/duplicate`, {}, { headers }); toast.success('Campaign duplicated'); load(); }
    catch { toast.error('Duplicate failed'); }
  };
  const archive = async (c) => {
    try { await axios.delete(`${apiRoot}/api/comms/campaigns/${c.id}`, { headers }); toast.success('Archived'); load(); }
    catch { toast.error('Archive failed'); }
  };

  return (
    <div data-testid={`${testIdPrefix}-panel`}>
      {/* Dashboard */}
      {dash && (
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 mb-6">
          <StatCard label="Campaigns" value={dash.total_campaigns} icon={Megaphone} />
          <StatCard label="Emails sent" value={dash.totals.sent} icon={Send} />
          <StatCard label="Open rate" value={dash.open_rate} suffix="%" icon={Eye} />
          <StatCard label="Click rate" value={dash.click_rate} suffix="%" icon={MousePointerClick} />
        </div>
      )}

      {/* Toolbar */}
      <div className="flex items-center justify-between gap-3 flex-wrap mb-3">
        <div className="flex items-center gap-2">
          <input
            value={q}
            onChange={(e) => setQ(e.target.value)}
            placeholder="Search campaigns…"
            className="px-3 py-2 rounded-full text-sm border focus:outline-none"
            style={{ background: 'var(--theme-surface)', borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }}
            data-testid={`${testIdPrefix}-search`}
          />
          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            className="px-3 py-2 rounded-full text-sm border"
            style={{ background: 'var(--theme-surface)', borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }}
            data-testid={`${testIdPrefix}-status-filter`}
          >
            <option value="">All statuses</option>
            {(meta?.statuses || []).map((s) => <option key={s} value={s}>{s.replace(/_/g, ' ')}</option>)}
          </select>
        </div>
        <button
          onClick={() => setShowCreate(true)}
          className="flex items-center gap-1.5 px-4 py-2 rounded-full text-sm font-bold"
          style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-ink, #1B1C1D)' }}
          data-testid={`${testIdPrefix}-create-btn`}
        >
          <Plus size={15} />New campaign
        </button>
      </div>

      {/* List */}
      <div className="rounded-2xl border overflow-hidden" style={{ background: 'var(--theme-surface)', borderColor: 'var(--theme-border)' }} data-testid={`${testIdPrefix}-campaign-list`}>
        {loading ? (
          <div className="p-10 text-center text-sm" style={{ color: 'var(--theme-text-muted)' }}>Loading…</div>
        ) : campaigns.length === 0 ? (
          <div className="p-12 text-center">
            <Megaphone size={28} className="mx-auto mb-2" style={{ color: 'var(--theme-text-muted)' }} />
            <p className="font-semibold" style={{ color: 'var(--theme-text)' }}>No campaigns yet</p>
            <p className="text-sm mb-4" style={{ color: 'var(--theme-text-muted)' }}>Create your first campaign.</p>
            <button onClick={() => setShowCreate(true)} className="px-4 py-2 rounded-full text-sm font-bold" style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-ink, #1B1C1D)' }} data-testid={`${testIdPrefix}-empty-create`}>Create campaign</button>
          </div>
        ) : (
          <table className="w-full text-sm">
            <thead style={{ background: 'var(--theme-bg)', color: 'var(--theme-text-muted)' }} className="text-xs uppercase tracking-wide">
              <tr>
                <th className="text-left font-bold px-4 py-3">Campaign</th>
                <th className="text-left font-bold px-4 py-3 hidden md:table-cell">Type</th>
                <th className="text-left font-bold px-4 py-3">Status</th>
                <th className="text-left font-bold px-4 py-3 hidden sm:table-cell">Sent</th>
                <th className="text-right font-bold px-4 py-3">Actions</th>
              </tr>
            </thead>
            <tbody>
              {campaigns.map((c) => (
                <tr key={c.id} className="border-t" style={{ borderColor: 'var(--theme-border)' }} data-testid={`campaign-row-${c.id}`}>
                  <td className="px-4 py-3">
                    <div className="font-semibold" style={{ color: 'var(--theme-text)' }}>{c.name}</div>
                    {module === 'all' && (
                      <span className={`inline-block mt-1 text-[10px] font-bold px-2 py-0.5 rounded-full ${MODULE_BADGE[c.related_module] || 'bg-slate-500/12 text-slate-500'}`}>{c.related_module}</span>
                    )}
                  </td>
                  <td className="px-4 py-3 hidden md:table-cell" style={{ color: 'var(--theme-text-muted)' }}>{typeLabel(c.campaign_type)}</td>
                  <td className="px-4 py-3"><span className={`text-[11px] font-bold px-2 py-1 rounded-full ${STATUS_STYLE[c.status] || 'bg-slate-500/15'}`}>{(c.status || 'draft').replace(/_/g, ' ')}</span></td>
                  <td className="px-4 py-3 hidden sm:table-cell" style={{ color: 'var(--theme-text-muted)' }}>{c.metrics?.sent || 0}</td>
                  <td className="px-4 py-3">
                    <div className="flex items-center justify-end gap-1">
                      <button onClick={() => setEditing(c)} title="Edit" className="p-1.5 rounded-lg hover:bg-black/5 dark:hover:bg-white/5" style={{ color: 'var(--theme-text-muted)' }} data-testid={`campaign-edit-${c.id}`}><Pencil size={15} /></button>
                      <button onClick={() => setAnalytics(c)} title="Analytics" className="p-1.5 rounded-lg hover:bg-black/5 dark:hover:bg-white/5" style={{ color: 'var(--theme-text-muted)' }} data-testid={`campaign-analytics-${c.id}`}><BarChart3 size={15} /></button>
                      <button onClick={() => duplicate(c)} title="Duplicate" className="p-1.5 rounded-lg hover:bg-black/5 dark:hover:bg-white/5" style={{ color: 'var(--theme-text-muted)' }} data-testid={`campaign-dup-${c.id}`}><Copy size={15} /></button>
                      <button onClick={() => archive(c)} title="Archive" className="p-1.5 rounded-lg hover:bg-black/5 dark:hover:bg-white/5" style={{ color: 'var(--theme-text-muted)' }} data-testid={`campaign-archive-${c.id}`}><Archive size={15} /></button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {showCreate && meta && (
        <CreateModal
          API={apiRoot} headers={headers} meta={meta} defaultModule={module}
          onClose={() => setShowCreate(false)}
          onCreated={(c) => { setShowCreate(false); load(); setEditing(c); }}
        />
      )}

      {editing && (
        <EmailBuilder
          campaign={editing} API={apiRoot} headers={headers}
          onClose={() => { setEditing(null); load(); }}
          onSaved={(c) => setEditing(c)}
        />
      )}

      {analytics && (
        <CampaignAnalytics campaign={analytics} API={apiRoot} headers={headers} onClose={() => setAnalytics(null)} />
      )}
    </div>
  );
}

function CreateModal({ API, headers, meta, defaultModule, onClose, onCreated }) {
  const [name, setName] = useState('');
  const types = meta.campaign_types.filter((t) => defaultModule === 'all' || t.module === defaultModule);
  const [type, setType] = useState(types[0]?.id || 'regular');
  const [goal, setGoal] = useState('');
  const [busy, setBusy] = useState(false);
  const [segments, setSegments] = useState([]);
  const [segmentId, setSegmentId] = useState('');

  useEffect(() => {
    axios.get(`${API}/api/comms/segments`, { headers }).then((r) => setSegments(r.data.segments || [])).catch(() => {});
  }, [API, headers]);

  const grouped = useMemo(() => {
    const g = {};
    types.forEach((t) => { (g[t.group] = g[t.group] || []).push(t); });
    return g;
  }, [types]);

  const create = async () => {
    if (!name.trim()) { toast.error('Give your campaign a name'); return; }
    setBusy(true);
    try {
      const r = await axios.post(`${API}/api/comms/campaigns`, { name, campaign_type: type, conversion_goal: goal, segment_id: segmentId || undefined }, { headers });
      toast.success('Campaign created');
      onCreated(r.data.campaign);
    } catch (e) {
      toast.error(e?.response?.data?.detail || 'Create failed');
    } finally { setBusy(false); }
  };

  const inputStyle = { background: 'var(--theme-bg)', borderColor: 'var(--theme-border)', color: 'var(--theme-text)' };
  return (
    <div className="fixed inset-0 z-[150] bg-black/50 flex items-center justify-center p-4" onClick={onClose}>
      <div className="rounded-2xl p-6 w-full max-w-lg border" style={{ background: 'var(--theme-surface)', borderColor: 'var(--theme-border)' }} onClick={(e) => e.stopPropagation()} data-testid="comms-create-modal">
        <div className="flex items-center justify-between mb-4">
          <h3 className="font-bold text-xl pulse-font-heading" style={{ color: 'var(--theme-text)' }}>New campaign</h3>
          <button onClick={onClose} className="p-1.5 rounded-lg hover:bg-black/5 dark:hover:bg-white/5" style={{ color: 'var(--theme-text-muted)' }}><X size={18} /></button>
        </div>
        <label className="block text-[11px] uppercase tracking-wider font-bold mb-1" style={{ color: 'var(--theme-text-muted)' }}>Name</label>
        <input value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. October member newsletter" className="w-full px-4 py-3 rounded-xl border mb-4 focus:outline-none" style={inputStyle} data-testid="create-name" autoFocus />
        <label className="block text-[11px] uppercase tracking-wider font-bold mb-1" style={{ color: 'var(--theme-text-muted)' }}>Campaign type</label>
        <select value={type} onChange={(e) => setType(e.target.value)} className="w-full px-4 py-3 rounded-xl border mb-4" style={inputStyle} data-testid="create-type">
          {Object.entries(grouped).map(([g, items]) => (
            <optgroup key={g} label={g}>
              {items.map((t) => <option key={t.id} value={t.id}>{t.label}</option>)}
            </optgroup>
          ))}
        </select>
        <label className="block text-[11px] uppercase tracking-wider font-bold mb-1" style={{ color: 'var(--theme-text-muted)' }}>Audience segment (optional)</label>
        <select value={segmentId} onChange={(e) => setSegmentId(e.target.value)} className="w-full px-4 py-3 rounded-xl border mb-4" style={inputStyle} data-testid="create-segment">
          <option value="">No segment yet — choose later</option>
          {segments.map((s) => <option key={s.id} value={s.id}>{s.name} ({s.member_count})</option>)}
        </select>
        <label className="block text-[11px] uppercase tracking-wider font-bold mb-1" style={{ color: 'var(--theme-text-muted)' }}>Conversion goal (optional)</label>
        <input value={goal} onChange={(e) => setGoal(e.target.value)} placeholder="e.g. renewals, bookings, quote approvals" className="w-full px-4 py-3 rounded-xl border mb-5 focus:outline-none" style={inputStyle} data-testid="create-goal" />
        <div className="flex justify-end gap-2">
          <button onClick={onClose} className="px-4 py-2 rounded-full text-sm font-semibold hover:bg-black/5 dark:hover:bg-white/5" style={{ color: 'var(--theme-text-muted)' }}>Cancel</button>
          <button onClick={create} disabled={busy} className="px-5 py-2 rounded-full text-sm font-bold disabled:opacity-50" style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-ink, #1B1C1D)' }} data-testid="create-confirm">{busy ? 'Creating…' : 'Create & build'}</button>
        </div>
      </div>
    </div>
  );
}

/**
 * Pulse Fitness AI — Comms Centre.
 *
 * The central, merged campaign + intelligence module. Layout mirrors the
 * other modules (unified header + ModuleSwitcher + canonical PillTabBar).
 * Main tabs: Campaigns / Flows / Segments / Analytics / Inactive.
 * Analytics groups Engagement / Best Send Time / Benchmarks behind a
 * sub-tab row; Deliverability / Import / API & Webhooks live behind a
 * Settings menu. A module-scope control (All / Marketing / Members / CRM)
 * filters the shared records — no duplication.
 */
import React, { useMemo, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Megaphone, TrendingUp, Clock, Award, ShieldCheck, Users, Filter, Workflow, Upload, Webhook, Settings, ChevronDown, Check } from 'lucide-react';

import { useAuth } from '@/App';
import Navbar from '@/components/shared/Navbar';
import ModuleSwitcher from '@/components/shared/ModuleSwitcher';
import ModulePageHeader from '@/components/shared/ModulePageHeader';
import PillTabBar from '@/components/shared/PillTabBar';
import CrossModuleTipsBanner from '@/components/shared/CrossModuleTipsBanner';
import { DropdownMenu, DropdownMenuTrigger, DropdownMenuContent, DropdownMenuItem } from '@/components/ui/dropdown-menu';
import CampaignsPanel from './CampaignsPanel';
import { EngagementView, InactiveView, BestTimeView, BenchmarksView, DeliverabilityView } from './Intelligence';
import { SegmentsView } from './Segments';
import { FlowsView } from './Flows';
import { MigrateView } from './Migrate';
import { DeveloperView } from './Developer';

const SECTIONS = [
  { id: 'campaigns', label: 'Campaigns', icon: Megaphone },
  { id: 'flows', label: 'Flows', icon: Workflow },
  { id: 'segments', label: 'Segments', icon: Filter },
  { id: 'analytics', label: 'Analytics', icon: TrendingUp },
  { id: 'inactive', label: 'Inactive', icon: Users },
];

const ANALYTICS_TABS = [
  { id: 'engagement', label: 'Engagement', icon: TrendingUp },
  { id: 'best-time', label: 'Best Send Time', icon: Clock },
  { id: 'benchmarks', label: 'Benchmarks', icon: Award },
];

const SETTINGS_ITEMS = [
  { id: 'deliverability', label: 'Deliverability', icon: ShieldCheck },
  { id: 'migrate', label: 'Import', icon: Upload },
  { id: 'developer', label: 'API & Webhooks', icon: Webhook },
];

const ANALYTICS_IDS = ANALYTICS_TABS.map((t) => t.id);
const SETTINGS_IDS = SETTINGS_ITEMS.map((s) => s.id);
const LEAF_VIEWS = [
  ...SECTIONS.map((s) => s.id).filter((id) => id !== 'analytics'),
  ...ANALYTICS_IDS,
  ...SETTINGS_IDS,
];

const SCOPES = [
  { id: 'all', label: 'All' },
  { id: 'marketing', label: 'Marketing' },
  { id: 'memberships', label: 'Members' },
  { id: 'crm', label: 'CRM & B2B' },
];

export default function CommsCentre() {
  const { user, logout, theme, toggleTheme } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const API = process.env.REACT_APP_BACKEND_URL;
  const token = useMemo(() => localStorage.getItem('token'), []);
  const headers = useMemo(() => ({ Authorization: `Bearer ${token}` }), [token]);

  const sp = new URLSearchParams(location.search);
  const requested = sp.get('view');
  const initialView = requested === 'analytics'
    ? 'engagement'
    : (LEAF_VIEWS.includes(requested) ? requested : 'campaigns');

  const [view, setView] = useState(initialView);
  const [scope, setScope] = useState('all');

  const isPulseBranded = user?.account_type === 'pulse_pro' || user?.account_type === 'lite';

  if (!user) { navigate('/'); return null; }

  const analyticsActive = ANALYTICS_IDS.includes(view);
  const settingsActive = SETTINGS_IDS.includes(view);

  const go = (id) => { setView(id); navigate(`/comms?view=${id}`, { replace: true }); };

  const activeStyle = isPulseBranded
    ? { background: 'var(--color-brand-cyan)', color: 'var(--color-ink)' }
    : { background: 'var(--color-brand-cyan)', color: 'var(--color-ink)', boxShadow: '0 6px 16px -6px rgba(25, 205, 255, 0.35)' };

  const renderSection = () => {
    switch (view) {
      case 'flows': return <FlowsView API={API} headers={headers} />;
      case 'migrate': return <MigrateView API={API} headers={headers} />;
      case 'developer': return <DeveloperView API={API} headers={headers} />;
      case 'segments': return <SegmentsView API={API} headers={headers} />;
      case 'engagement': return <EngagementView API={API} headers={headers} module={scope} />;
      case 'inactive': return <InactiveView API={API} headers={headers} module={scope} />;
      case 'best-time': return <BestTimeView API={API} headers={headers} module={scope} />;
      case 'benchmarks': return <BenchmarksView API={API} headers={headers} module={scope} />;
      case 'deliverability': return <DeliverabilityView API={API} headers={headers} />;
      default: return <CampaignsPanel key={scope} API={API} headers={headers} module={scope} testIdPrefix="comms" />;
    }
  };

  const SettingsMenu = ({ testId }) => (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <button
          data-testid={testId}
          className="flex-shrink-0 inline-flex items-center gap-2 px-4 py-2.5 rounded-full text-sm font-semibold transition-all whitespace-nowrap"
          style={settingsActive ? activeStyle : { color: 'var(--theme-text-muted)', background: 'var(--theme-surface)', border: '1px solid var(--theme-border)' }}
        >
          <Settings size={14} /> Settings <ChevronDown size={14} />
        </button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-52" data-testid="comms-settings-menu">
        {SETTINGS_ITEMS.map(({ id, label, icon: Icon }) => (
          <DropdownMenuItem key={id} onClick={() => go(id)} data-testid={`comms-settings-${id}`} className="gap-2 cursor-pointer">
            <Icon size={15} className="text-slate-500" />
            <span className="flex-1">{label}</span>
            {view === id && <Check size={14} className="text-[#0091ca]" />}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );

  const mainTab = ({ id, label, icon: Icon }, isMobile) => {
    const isActive = id === 'analytics' ? analyticsActive : view === id;
    const onClick = () => go(id === 'analytics' ? 'engagement' : id);
    if (isMobile) {
      return (
        <button key={id} onClick={onClick}
          className="flex-shrink-0 px-4 py-2 rounded-full text-xs font-semibold whitespace-nowrap"
          style={isActive ? { background: 'var(--color-brand-cyan)', color: 'var(--color-ink)' } : { color: 'var(--theme-text-muted)', background: 'var(--theme-surface)', border: '1px solid var(--theme-border)' }}
          data-testid={`comms-section-pill-${id}`}>{label}</button>
      );
    }
    return (
      <button
        key={id}
        data-pill-id={id}
        onClick={onClick}
        className="flex-shrink-0 inline-flex items-center gap-2 px-4 py-2.5 rounded-full text-sm font-semibold transition-all whitespace-nowrap"
        style={isActive ? activeStyle : { color: 'var(--theme-text-muted)', background: 'transparent' }}
        data-testid={`comms-section-${id}`}
      >
        <Icon size={14} /> {label}
      </button>
    );
  };

  return (
    <div
      className={`min-h-screen ${!isPulseBranded && theme === 'light' ? 'theme-gymaxis' : ''}`}
      style={{ background: 'var(--theme-bg)', color: 'var(--theme-text)' }}
      data-testid="comms-centre"
    >
      <Navbar user={user} logout={logout} theme={theme} toggleTheme={toggleTheme} />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-24 pb-24 md:pb-8 module-fade-in">
        <div className="mb-6" data-testid="comms-app-header">
          <ModulePageHeader
            moduleName="Comms Centre"
            tenantName={user?.company_name}
            subtitle="One connected campaign & intelligence system across Marketing, Memberships and CRM."
            isPulseBranded={isPulseBranded}
          />
          <ModuleSwitcher user={user} current="comms" />
        </div>

        <CrossModuleTipsBanner mode="marketing" />

        {/* Section tabs (desktop) — main tabs + Settings menu */}
        <div className="hidden md:flex items-center gap-2 mb-4">
          <PillTabBar className="flex-1 min-w-0" activeId={analyticsActive ? 'analytics' : view} testId="comms-sections-desktop" ariaLabel="Comms sections">
            {SECTIONS.map((s) => mainTab(s, false))}
          </PillTabBar>
          <SettingsMenu testId="comms-settings-btn" />
        </div>

        {/* Mobile section pills */}
        <div className="md:hidden mb-4 flex gap-2 overflow-x-auto scrollbar-hide pb-1 -mx-1 px-1" style={{ WebkitOverflowScrolling: 'touch' }}>
          {SECTIONS.map((s) => mainTab(s, true))}
          <SettingsMenu testId="comms-settings-btn-mobile" />
        </div>

        {/* Analytics sub-tabs */}
        {analyticsActive && (
          <div className="mb-4 inline-flex items-center gap-1 p-1 rounded-full flex-wrap" style={{ background: 'var(--theme-surface)', border: '1px solid var(--theme-border)' }} data-testid="comms-analytics-tabs">
            {ANALYTICS_TABS.map(({ id, label, icon: Icon }) => (
              <button key={id} onClick={() => go(id)}
                className="inline-flex items-center gap-1.5 px-3.5 py-1.5 rounded-full text-xs font-bold transition-all"
                style={view === id ? { background: 'var(--color-brand-cyan)', color: 'var(--color-ink)' } : { color: 'var(--theme-text-muted)' }}
                data-testid={`comms-analytics-${id}`}><Icon size={13} />{label}</button>
            ))}
          </div>
        )}

        {/* Module scope (hidden for org-wide / source views) */}
        {!['deliverability', 'segments', 'flows', 'migrate', 'developer'].includes(view) && (
          <div className="mb-5 inline-flex items-center gap-1 p-1 rounded-full" style={{ background: 'var(--theme-surface)', border: '1px solid var(--theme-border)' }} data-testid="comms-scope">
            {SCOPES.map((s) => (
              <button key={s.id} onClick={() => setScope(s.id)}
                className="px-3.5 py-1.5 rounded-full text-xs font-bold transition-all"
                style={scope === s.id ? { background: 'var(--color-brand-cyan)', color: 'var(--color-ink)' } : { color: 'var(--theme-text-muted)' }}
                data-testid={`comms-scope-${s.id}`}>{s.label}</button>
            ))}
          </div>
        )}

        {renderSection()}
      </main>
    </div>
  );
}

/**
 * Developer — webhooks, API keys and public API reference for the Comms Centre.
 * Self-hosted automation: subscribe endpoints to comms events and call the
 * /api/v1/comms REST API with an X-API-Key.
 */
import React, { useCallback, useEffect, useMemo, useState } from 'react';
import axios from 'axios';
import { toast } from 'sonner';
import { Webhook, KeyRound, Plus, Trash2, Send, Copy, Power, Code2, CheckCircle2 } from 'lucide-react';

export function DeveloperView({ API, headers }) {
  const apiRoot = useMemo(() => (API || process.env.REACT_APP_BACKEND_URL || '').replace(/\/api\/?$/, ''), [API]);
  const [tab, setTab] = useState('webhooks');
  const card = { background: 'var(--theme-surface)', borderColor: 'var(--theme-border)' };

  return (
    <div data-testid="comms-developer">
      <div className="flex items-center gap-1.5 mb-4">
        {[['webhooks', 'Webhooks', Webhook], ['keys', 'API keys', KeyRound], ['docs', 'API reference', Code2]].map(([id, label, Icon]) => (
          <button key={id} onClick={() => setTab(id)} className={`flex items-center gap-1.5 px-3.5 py-2 rounded-full text-sm font-semibold border ${tab === id ? '' : 'opacity-70'}`} style={{ borderColor: 'var(--theme-border)', background: tab === id ? 'var(--color-brand-cyan)' : 'transparent', color: tab === id ? 'var(--color-ink, #1B1C1D)' : 'var(--theme-text)' }} data-testid={`dev-tab-${id}`}>
            <Icon size={14} />{label}
          </button>
        ))}
      </div>
      {tab === 'webhooks' && <Webhooks apiRoot={apiRoot} headers={headers} card={card} />}
      {tab === 'keys' && <ApiKeys apiRoot={apiRoot} headers={headers} card={card} />}
      {tab === 'docs' && <ApiDocs apiRoot={apiRoot} card={card} />}
    </div>
  );
}

function Webhooks({ apiRoot, headers, card }) {
  const [hooks, setHooks] = useState([]);
  const [events, setEvents] = useState([]);
  const [creating, setCreating] = useState(false);
  const [url, setUrl] = useState('');
  const [sel, setSel] = useState([]);

  const load = useCallback(async () => {
    try {
      const r = await axios.get(`${apiRoot}/api/comms/webhooks`, { headers });
      setHooks(r.data.webhooks || []); setEvents(r.data.events || []);
    } catch { toast.error('Failed to load webhooks'); }
  }, [apiRoot, headers]);
  useEffect(() => { load(); }, [load]);

  const create = async () => {
    if (!url.startsWith('http')) { toast.error('Enter a valid https URL'); return; }
    try {
      await axios.post(`${apiRoot}/api/comms/webhooks`, { url, events: sel.length ? sel : events }, { headers });
      toast.success('Webhook added'); setUrl(''); setSel([]); setCreating(false); load();
    } catch (e) { toast.error(e?.response?.data?.detail || 'Failed'); }
  };
  const toggle = async (h) => { await axios.put(`${apiRoot}/api/comms/webhooks/${h.id}`, { active: !h.active }, { headers }); load(); };
  const remove = async (h) => { await axios.delete(`${apiRoot}/api/comms/webhooks/${h.id}`, { headers }); load(); };
  const test = async (h) => { await axios.post(`${apiRoot}/api/comms/webhooks/${h.id}/test`, {}, { headers }); toast.success('Test event sent'); };

  return (
    <div>
      <div className="flex justify-between items-center mb-3">
        <p className="text-sm" style={{ color: 'var(--theme-text-muted)' }}>Get notified at your endpoint when comms events happen (HMAC-signed).</p>
        <button onClick={() => setCreating((v) => !v)} className="flex items-center gap-1.5 px-4 py-2 rounded-full text-sm font-bold" style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-ink, #1B1C1D)' }} data-testid="webhook-add-btn"><Plus size={15} />Add endpoint</button>
      </div>
      {creating && (
        <div className="rounded-2xl border p-4 mb-3" style={card} data-testid="webhook-form">
          <input value={url} onChange={(e) => setUrl(e.target.value)} placeholder="https://your-app.com/webhooks/pulse" className="w-full px-3 py-2 rounded-lg border text-sm mb-3" style={{ background: 'var(--theme-bg)', borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }} data-testid="webhook-url" />
          <div className="flex flex-wrap gap-2 mb-3">
            {events.map((e) => (
              <button key={e} onClick={() => setSel((s) => s.includes(e) ? s.filter((x) => x !== e) : [...s, e])} className={`px-2.5 py-1 rounded-full text-xs font-semibold border ${sel.includes(e) ? 'bg-cyan-500/15 border-cyan-400 text-cyan-600' : ''}`} style={!sel.includes(e) ? { borderColor: 'var(--theme-border)', color: 'var(--theme-text-muted)' } : {}}>{e}</button>
            ))}
          </div>
          <p className="text-xs mb-2" style={{ color: 'var(--theme-text-muted)' }}>No events selected = all events.</p>
          <button onClick={create} className="px-4 py-2 rounded-full text-sm font-bold" style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-ink, #1B1C1D)' }} data-testid="webhook-save">Create webhook</button>
        </div>
      )}
      <div className="space-y-2">
        {hooks.length === 0 && <div className="rounded-2xl border p-8 text-center text-sm" style={{ ...card, color: 'var(--theme-text-muted)' }}>No webhooks yet.</div>}
        {hooks.map((h) => (
          <div key={h.id} className="rounded-2xl border p-4" style={card} data-testid={`webhook-row-${h.id}`}>
            <div className="flex items-center justify-between gap-3">
              <div className="min-w-0">
                <div className="font-semibold text-sm truncate flex items-center gap-2" style={{ color: 'var(--theme-text)' }}><Webhook size={14} />{h.url}</div>
                <div className="text-xs mt-1" style={{ color: 'var(--theme-text-muted)' }}>{(h.events || []).length} events · {h.active ? 'active' : 'paused'}{h.last_delivery ? ` · last ${h.last_delivery.status_code}` : ''}</div>
                <div className="text-[11px] mt-1 font-mono" style={{ color: 'var(--theme-text-muted)' }}>{h.secret}</div>
              </div>
              <div className="flex items-center gap-1 shrink-0">
                <button onClick={() => test(h)} className="p-2 rounded-lg hover:bg-black/5 dark:hover:bg-white/5" title="Send test" style={{ color: 'var(--theme-text-muted)' }} data-testid={`webhook-test-${h.id}`}><Send size={15} /></button>
                <button onClick={() => toggle(h)} className="p-2 rounded-lg hover:bg-black/5 dark:hover:bg-white/5" title="Toggle" style={{ color: h.active ? '#10b981' : 'var(--theme-text-muted)' }}><Power size={15} /></button>
                <button onClick={() => remove(h)} className="p-2 rounded-lg hover:bg-black/5 dark:hover:bg-white/5 text-rose-500" data-testid={`webhook-delete-${h.id}`}><Trash2 size={15} /></button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function ApiKeys({ apiRoot, headers, card }) {
  const [keys, setKeys] = useState([]);
  const [name, setName] = useState('');
  const [fresh, setFresh] = useState(null);

  const load = useCallback(async () => {
    try { const r = await axios.get(`${apiRoot}/api/comms/api-keys`, { headers }); setKeys(r.data.api_keys || []); } catch { toast.error('Failed to load keys'); }
  }, [apiRoot, headers]);
  useEffect(() => { load(); }, [load]);

  const create = async () => {
    try { const r = await axios.post(`${apiRoot}/api/comms/api-keys`, { name }, { headers }); setFresh(r.data.key); setName(''); load(); }
    catch { toast.error('Failed'); }
  };
  const revoke = async (k) => { await axios.delete(`${apiRoot}/api/comms/api-keys/${k.id}`, { headers }); load(); };
  const copy = (t) => { navigator.clipboard?.writeText(t); toast.success('Copied'); };

  return (
    <div>
      {fresh && (
        <div className="rounded-2xl border p-4 mb-3" style={{ background: 'var(--theme-bg)', borderColor: 'var(--color-brand-cyan)' }} data-testid="apikey-fresh">
          <div className="flex items-center gap-2 mb-2 text-sm font-bold" style={{ color: 'var(--theme-text)' }}><CheckCircle2 size={15} className="text-emerald-500" />Copy your key now — it won't be shown again</div>
          <div className="flex items-center gap-2">
            <code className="flex-1 text-xs font-mono px-3 py-2 rounded-lg break-all" style={{ background: 'var(--theme-surface)', color: 'var(--theme-text)' }}>{fresh}</code>
            <button onClick={() => copy(fresh)} className="p-2 rounded-lg" style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-ink, #1B1C1D)' }}><Copy size={15} /></button>
          </div>
          <button onClick={() => setFresh(null)} className="mt-2 text-xs underline" style={{ color: 'var(--theme-text-muted)' }}>Done</button>
        </div>
      )}
      <div className="rounded-2xl border p-4 mb-3 flex items-center gap-2" style={card}>
        <input value={name} onChange={(e) => setName(e.target.value)} placeholder="Key name (e.g. Zapier)" className="flex-1 px-3 py-2 rounded-lg border text-sm" style={{ background: 'var(--theme-bg)', borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }} data-testid="apikey-name" />
        <button onClick={create} className="flex items-center gap-1.5 px-4 py-2 rounded-full text-sm font-bold" style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-ink, #1B1C1D)' }} data-testid="apikey-create"><Plus size={15} />Generate</button>
      </div>
      <div className="space-y-2">
        {keys.length === 0 && <div className="rounded-2xl border p-8 text-center text-sm" style={{ ...card, color: 'var(--theme-text-muted)' }}>No API keys yet.</div>}
        {keys.map((k) => (
          <div key={k.id} className="rounded-2xl border p-4 flex items-center justify-between" style={card} data-testid={`apikey-row-${k.id}`}>
            <div>
              <div className="font-semibold text-sm flex items-center gap-2" style={{ color: 'var(--theme-text)' }}><KeyRound size={14} />{k.name}</div>
              <div className="text-xs mt-1 font-mono" style={{ color: 'var(--theme-text-muted)' }}>{k.key_masked} · {k.active ? 'active' : 'revoked'}</div>
            </div>
            {k.active && <button onClick={() => revoke(k)} className="p-2 rounded-lg hover:bg-black/5 dark:hover:bg-white/5 text-rose-500" data-testid={`apikey-revoke-${k.id}`}><Trash2 size={15} /></button>}
          </div>
        ))}
      </div>
    </div>
  );
}

