              </div>
            ))}
          </div>
        </main>

        {/* Properties */}
        <aside className="w-72 bg-white border-l border-slate-200 p-4 overflow-y-auto hidden lg:block shrink-0" data-testid="builder-props">
          {!sel && <p className="text-sm text-slate-400">Select a block to edit it.</p>}
