      {showAB && (
        <div className="fixed inset-0 z-[210] bg-black/40 flex items-center justify-center p-4" onClick={() => setShowAB(false)}>
          <div className="bg-white rounded-2xl p-6 w-full max-w-md max-h-[90vh] overflow-y-auto" onClick={(e) => e.stopPropagation()} data-testid="ab-modal">
            <h3 className="flex items-center gap-2 font-bold text-lg text-slate-900 mb-1 pulse-font-heading"><FlaskConical size={18} className="text-violet-600" />A/B test</h3>
            <p className="text-sm text-slate-500 mb-4">Send variants to a small test group, then auto-send the winner to everyone else.</p>
            <label className="flex items-center gap-2 mb-4 cursor-pointer">
              <input type="checkbox" checked={ab.enabled} onChange={(e) => { const en = e.target.checked; setAb((a) => ({ ...a, enabled: en })); if (en && variants.length < 2) addVariant(); }} className="w-4 h-4 accent-violet-600" data-testid="ab-enable" />
              <span className="text-sm font-semibold text-slate-700">Enable A/B testing</span>
            </label>
            {ab.enabled && (
              <div className="space-y-3" data-testid="ab-settings">
                <div>
                  <label className="block text-[11px] uppercase tracking-wider font-bold text-slate-400 mb-1">Test group size: {ab.test_percentage}%</label>
                  <input type="range" min="5" max="50" value={ab.test_percentage} onChange={(e) => setAb((a) => ({ ...a, test_percentage: Number(e.target.value) }))} className="w-full accent-violet-600" data-testid="ab-percentage" />
                  <p className="text-xs text-slate-400">{ab.test_percentage}% split across {variants.length} variants; the winning {100 - ab.test_percentage}% gets the best performer.</p>
                </div>
                <div>
                  <label className="block text-[11px] uppercase tracking-wider font-bold text-slate-400 mb-1">Pick winner by</label>
                  <select value={ab.winner_metric} onChange={(e) => setAb((a) => ({ ...a, winner_metric: e.target.value }))} className="w-full px-3 py-2 rounded-lg border border-slate-200 text-sm" data-testid="ab-metric">
                    <option value="opens">Most opens</option>
                    <option value="clicks">Most clicks</option>
                  </select>
                </div>
                <div>
                  <label className="block text-[11px] uppercase tracking-wider font-bold text-slate-400 mb-1">Decide after (hours)</label>
                  <input type="number" min="1" max="72" value={ab.decision_hours} onChange={(e) => setAb((a) => ({ ...a, decision_hours: Number(e.target.value) || 4 }))} className="w-full px-3 py-2 rounded-lg border border-slate-200 text-sm" data-testid="ab-hours" />
                </div>
                <p className="text-xs text-slate-500 bg-violet-50 rounded-lg p-2.5">Edit each variant's subject + content using the <strong>Variant</strong> tabs above the canvas. Variant A is the control.</p>
              </div>
            )}
            <div className="flex justify-end gap-2 mt-5">
              <button onClick={() => setShowAB(false)} className="px-4 py-2 rounded-full text-sm font-semibold text-slate-600 hover:bg-slate-100">Cancel</button>
              <button onClick={() => { setShowAB(false); save(); }} className="px-4 py-2 rounded-full text-sm font-bold text-white" style={{ background: '#7C3AED' }} data-testid="ab-save">Save A/B settings</button>
            </div>
          </div>
        </div>
      )}
    </div>
  ), document.body);
}

function ImportModal({ API, headers, onClose, onImported }) {
  const [busy, setBusy] = useState(false);
  const [elapsed, setElapsed] = useState(0);
  const [dragOver, setDragOver] = useState(false);
  const [file, setFile] = useState(null);
  const [pasted, setPasted] = useState('');
  const inputRef = useRef(null);

  useEffect(() => {
    if (!busy) { setElapsed(0); return; }
    const t = setInterval(() => setElapsed((s) => s + 1), 1000);
    return () => clearInterval(t);
  }, [busy]);

  const ACCEPT = '.eml,.msg,.html,.htm,.txt,.pdf,.png,.jpg,.jpeg,.webp,.gif,message/rfc822';

  const onDrop = (e) => {
    e.preventDefault();
    setDragOver(false);
    const f = e.dataTransfer.files?.[0];
    if (f) { setFile(f); setPasted(''); }
  };

  const submit = async () => {
    if (!file && !pasted.trim()) { toast.error('Drop an email file or paste the content'); return; }
    setBusy(true);
    try {
      const form = new FormData();
      if (file) form.append('file', file);
      if (pasted.trim()) form.append('text', pasted);
      const r = await axios.post(`${API}/api/comms/ai/import-email`, form, {
        headers: { ...headers, 'Content-Type': 'multipart/form-data' },
      });
      if (!(r.data.blocks || []).length) {
        toast.error('Could not detect any content in that email');
      } else {
        onImported(r.data);
      }
    } catch (e) {
      toast.error(e?.response?.data?.detail || 'Import failed — try pasting the email text instead');
    } finally { setBusy(false); }
  };

  return (
    <div className="fixed inset-0 z-[210] bg-black/40 flex items-center justify-center p-4" onClick={onClose}>
      <div className="bg-white rounded-2xl p-6 w-full max-w-lg max-h-[90vh] overflow-y-auto" onClick={(e) => e.stopPropagation()} data-testid="import-email-modal">
        <h3 className="flex items-center gap-2 font-bold text-lg text-slate-900 mb-1 pulse-font-heading"><FileUp size={18} className="text-[#0891b2]" />Import an email</h3>
        <p className="text-sm text-slate-500 mb-4">Drop any email and AI will rebuild it into editable, on-brand blocks. Supports <strong>.eml, .msg, HTML, .txt, PDF</strong> and <strong>screenshots</strong>.</p>

        <div
          onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
          onDragLeave={() => setDragOver(false)}
          onDrop={onDrop}
          onClick={() => inputRef.current?.click()}
          data-testid="import-dropzone"
          className={`rounded-2xl border-2 border-dashed p-8 text-center cursor-pointer transition-colors ${dragOver ? 'border-[#19CDFF] bg-cyan-50' : 'border-slate-300 hover:border-slate-400 bg-slate-50'}`}
        >
          <Upload size={26} className="mx-auto text-slate-400 mb-2" />
          {file ? (
            <p className="text-sm font-semibold text-slate-700 flex items-center justify-center gap-1.5"><Mail size={14} />{file.name}</p>
          ) : (
            <>
              <p className="text-sm font-semibold text-slate-700">Drag &amp; drop an email here</p>
              <p className="text-xs text-slate-400 mt-0.5">or click to browse</p>
            </>
          )}
          <input ref={inputRef} type="file" accept={ACCEPT} className="hidden" data-testid="import-file-input"
            onChange={(e) => { const f = e.target.files?.[0]; if (f) { setFile(f); setPasted(''); } }} />
        </div>

        <div className="flex items-center gap-2 my-3 text-[11px] uppercase tracking-wider font-bold text-slate-300">
          <div className="flex-1 h-px bg-slate-200" />or paste<div className="flex-1 h-px bg-slate-200" />
        </div>

        <textarea
          value={pasted}
          onChange={(e) => { setPasted(e.target.value); if (e.target.value) setFile(null); }}
          rows={5}
          placeholder="Paste the email body or HTML here…"
          data-testid="import-paste"
          className="w-full px-4 py-3 rounded-xl border border-slate-200 text-sm focus:border-[#19CDFF] focus:outline-none"
        />

        <div className="flex items-start gap-1.5 mt-3 text-xs text-slate-500 bg-slate-50 rounded-lg p-2.5">
          <Info size={13} className="mt-0.5 shrink-0 text-slate-400" />
          <span>Linked images are pulled in automatically. Embedded or screenshot images can't be hosted — we'll add a placeholder and flag it so you can upload them.</span>
        </div>

        {busy && (() => {
          const estSec = file ? Math.max(12, Math.min(60, Math.round((file.size / 1048576) * 10) + 8)) : 12;
          const pct = Math.min(92, Math.round((elapsed / estSec) * 92));
          return (
            <div className="mt-3 rounded-lg p-2.5" style={{ background: 'rgba(8,145,178,0.08)' }} data-testid="import-progress-note">
              <div className="flex items-center gap-2 text-xs text-[#0e7490] mb-1.5">
                <Loader2 size={13} className="animate-spin shrink-0" />
                <span className="flex-1">{elapsed < 5
                  ? 'Rebuilding your email with AI…'
                  : 'Large email — this can take up to a minute. Hang tight, no need to retry.'}</span>
                <span className="font-semibold tabular-nums" data-testid="import-progress-pct">{pct}%</span>
              </div>
              <div className="h-1.5 w-full rounded-full overflow-hidden" style={{ background: 'rgba(8,145,178,0.15)' }}>
                <div className="h-full rounded-full transition-all duration-700 ease-out" style={{ width: `${pct}%`, background: CYAN }} data-testid="import-progress-bar" />
              </div>
            </div>
          );
        })()}

        <div className="flex justify-end gap-2 mt-5">
          <button onClick={onClose} disabled={busy} className="px-4 py-2 rounded-full text-sm font-semibold text-slate-600 hover:bg-slate-100 disabled:opacity-50">Cancel</button>
          <button onClick={submit} disabled={busy} className="flex items-center gap-1.5 px-5 py-2 rounded-full text-sm font-bold text-[#03212b] disabled:opacity-50" style={{ background: CYAN }} data-testid="import-submit">
            {busy ? <Loader2 size={14} className="animate-spin" /> : <Wand2 size={14} />}{busy ? 'Rebuilding…' : 'Rebuild with AI'}
          </button>
        </div>
      </div>
    </div>
  );
}

function SendModal({ campaign, API, headers, onClose, onDone }) {
  const [segments, setSegments] = useState([]);
  const [segmentId, setSegmentId] = useState(campaign?.segment_id || '');
  const [audienceMode, setAudienceMode] = useState(
    (campaign?.audience_inline && campaign.audience_inline.length && !campaign?.segment_id) ? 'people' : 'segment');
  const [people, setPeople] = useState(
    (campaign?.audience_inline || []).map((e) => ({ email: e, name: e, source: 'email' })));
  const [peopleQuery, setPeopleQuery] = useState('');
  const [peopleResults, setPeopleResults] = useState([]);
  const [searching, setSearching] = useState(false);
  const [strategy, setStrategy] = useState('immediate');
  const [sendAt, setSendAt] = useState('');
  const [tzMode, setTzMode] = useState('fixed');
  const [localHour, setLocalHour] = useState(9);
  const [batchSize, setBatchSize] = useState(0);
  const [batchInterval, setBatchInterval] = useState(0);
  const [busy, setBusy] = useState(false);

  React.useEffect(() => {
    axios.get(`${API}/api/comms/segments`, { headers }).then((r) => setSegments(r.data.segments || [])).catch(() => {});
  }, [API, headers]);

  React.useEffect(() => {
    const q = peopleQuery.trim();
    if (audienceMode !== 'people' || q.length < 2) { setPeopleResults([]); return; }
    let cancelled = false;
    setSearching(true);
    const t = setTimeout(() => {
      axios.get(`${API}/api/comms/audience/search`, { params: { q }, headers })
        .then((r) => { if (!cancelled) setPeopleResults(r.data.results || []); })
        .catch(() => { if (!cancelled) setPeopleResults([]); })
        .finally(() => { if (!cancelled) setSearching(false); });
    }, 250);
    return () => { cancelled = true; clearTimeout(t); };
  }, [peopleQuery, audienceMode, API, headers]);

  const seg = segments.find((s) => s.id === segmentId);

  const addPerson = (p) => {
    const email = (p.email || '').trim().toLowerCase();
    if (!email || !email.includes('@')) { toast.error('Enter a valid email'); return; }
    if (people.some((x) => x.email === email)) return;
    setPeople((prev) => [...prev, { email, name: p.name || email, source: p.source || 'email' }]);
    setPeopleQuery(''); setPeopleResults([]);
  };
  const removePerson = (email) => setPeople((prev) => prev.filter((x) => x.email !== email));

  const go = async () => {
    if (audienceMode === 'segment' && !segmentId) { toast.error('Choose an audience segment'); return; }
    if (audienceMode === 'people' && people.length === 0) { toast.error('Add at least one recipient'); return; }
    if (strategy === 'scheduled' && !sendAt) { toast.error('Pick a send date/time'); return; }
    setBusy(true);
    try {
      const audiencePatch = audienceMode === 'people'
        ? { audience_inline: people.map((p) => p.email), segment_id: null }
        : { segment_id: segmentId, audience_inline: null };
      await axios.put(`${API}/api/comms/campaigns/${campaign.id}`, audiencePatch, { headers });
      const payload = {
        strategy,
        send_at: strategy === 'scheduled' ? new Date(sendAt).toISOString() : undefined,
        timezone_mode: tzMode, local_hour: Number(localHour),
        batch_size: Number(batchSize), batch_interval_minutes: Number(batchInterval),
      };
      const r = await axios.post(`${API}/api/comms/campaigns/${campaign.id}/schedule`, payload, { headers });
      toast.success(r.data.status === 'sending' ? `Sending to ${r.data.recipients} recipients` : 'Campaign scheduled');
      onClose();
      onDone && onDone();
    } catch (e) {
      toast.error(e?.response?.data?.detail || 'Could not schedule');
    } finally { setBusy(false); }
  };

  const inputCls = 'w-full px-3 py-2 rounded-lg border border-slate-200 text-sm focus:border-[#19CDFF] focus:outline-none';
  return (
    <div className="fixed inset-0 z-[210] bg-black/40 flex items-center justify-center p-4" onClick={onClose}>
      <div className="bg-white rounded-2xl p-6 w-full max-w-md max-h-[90vh] overflow-y-auto" onClick={(e) => e.stopPropagation()} data-testid="send-modal">
        <h3 className="flex items-center gap-2 font-bold text-lg text-slate-900 mb-1 pulse-font-heading"><Rocket size={18} className="text-[#0891b2]" />Send campaign</h3>
        <p className="text-sm text-slate-500 mb-4">Batch + timezone-aware delivery via Pulse Fitness AI.</p>

        <label className="block text-[11px] uppercase tracking-wider font-bold text-slate-400 mb-1">Audience</label>
        <div className="flex gap-2 mb-3">
          {[['segment', 'A segment'], ['people', 'Specific people']].map(([v, l]) => (
            <button key={v} onClick={() => setAudienceMode(v)} className={`flex-1 px-3 py-2 rounded-lg text-sm font-semibold border ${audienceMode === v ? 'border-[#19CDFF] bg-cyan-50 text-slate-900' : 'border-slate-200 text-slate-500'}`} data-testid={`audience-mode-${v}`}>{l}</button>
          ))}
        </div>

        {audienceMode === 'segment' && (
          <>
            <select value={segmentId} onChange={(e) => setSegmentId(e.target.value)} className={`${inputCls} mb-1`} data-testid="send-segment">
              <option value="">Choose a segment…</option>
              {segments.map((s) => <option key={s.id} value={s.id}>{s.name} ({s.member_count})</option>)}
            </select>
            {seg && <p className="flex items-center gap-1 text-xs text-slate-500 mb-3"><Users size={12} />{seg.member_count} recipients</p>}
          </>
        )}

        {audienceMode === 'people' && (
          <div className="mb-3">
            <div className="relative">
              <input
                value={peopleQuery}
                onChange={(e) => setPeopleQuery(e.target.value)}
                onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); if (peopleQuery.includes('@')) addPerson({ email: peopleQuery }); } }}
                placeholder="Search members/contacts, or type an email + Enter"
                className={inputCls}
                data-testid="audience-people-search"
              />
              {(searching || peopleResults.length > 0) && peopleQuery.trim().length >= 2 && (
                <div className="absolute z-10 left-0 right-0 mt-1 bg-white border border-slate-200 rounded-lg shadow-lg max-h-52 overflow-y-auto" data-testid="audience-people-results">
                  {searching && <div className="px-3 py-2 text-xs text-slate-400">Searching…</div>}
                  {!searching && peopleResults.length === 0 && (
                    <div className="px-3 py-2 text-xs text-slate-400">No matches. {peopleQuery.includes('@') ? 'Press Enter to add this email.' : ''}</div>
                  )}
                  {peopleResults.map((p) => (
                    <button key={p.email} onClick={() => addPerson(p)} className="w-full text-left px-3 py-2 hover:bg-slate-50 flex items-center justify-between" data-testid={`audience-result-${p.email}`}>
                      <span className="text-sm text-slate-800">{p.name}<span className="text-slate-400 ml-1 text-xs">{p.email}</span></span>
                      <span className="text-[10px] uppercase font-bold text-slate-400">{p.source}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>
            {people.length > 0 && (
              <div className="flex flex-wrap gap-1.5 mt-2" data-testid="audience-people-chips">
                {people.map((p) => (
                  <span key={p.email} className="inline-flex items-center gap-1 px-2 py-1 rounded-full bg-cyan-50 border border-cyan-200 text-xs text-slate-700" data-testid={`audience-chip-${p.email}`}>
                    {p.name}
                    <button onClick={() => removePerson(p.email)} className="text-slate-400 hover:text-slate-700" data-testid={`audience-chip-remove-${p.email}`}><X size={12} /></button>
                  </span>
                ))}
              </div>
            )}
            <p className="flex items-center gap-1 text-xs text-slate-500 mt-2"><Users size={12} />{people.length} recipient{people.length === 1 ? '' : 's'}</p>
          </div>
        )}

        <label className="block text-[11px] uppercase tracking-wider font-bold text-slate-400 mb-1 mt-2">When</label>
        <div className="flex gap-2 mb-3">
          {[['immediate', 'Send now'], ['scheduled', 'Schedule']].map(([v, l]) => (
            <button key={v} onClick={() => setStrategy(v)} className={`flex-1 px-3 py-2 rounded-lg text-sm font-semibold border ${strategy === v ? 'border-[#19CDFF] bg-cyan-50 text-slate-900' : 'border-slate-200 text-slate-500'}`} data-testid={`send-strategy-${v}`}>{l}</button>
          ))}
        </div>
        {strategy === 'scheduled' && (
          <input type="datetime-local" value={sendAt} onChange={(e) => setSendAt(e.target.value)} className={`${inputCls} mb-3`} data-testid="send-at" />
        )}

        <label className="block text-[11px] uppercase tracking-wider font-bold text-slate-400 mb-1">Timezone</label>
        <select value={tzMode} onChange={(e) => setTzMode(e.target.value)} className={`${inputCls} mb-2`} data-testid="send-tzmode">
          <option value="fixed">Fixed timezone (Europe/London)</option>
          <option value="recipient_local">Each recipient's local time</option>
        </select>
        {tzMode === 'recipient_local' && (
          <div className="flex items-center gap-2 mb-3 text-sm text-slate-600"><Clock size={14} />Send around
            <input type="number" min="0" max="23" value={localHour} onChange={(e) => setLocalHour(e.target.value)} className="w-16 px-2 py-1 rounded-lg border border-slate-200" data-testid="send-localhour" />:00 local</div>
        )}

        <label className="block text-[11px] uppercase tracking-wider font-bold text-slate-400 mb-1 mt-1">Batch delivery (optional)</label>
        <div className="grid grid-cols-2 gap-2 mb-4">
          <div><span className="text-xs text-slate-400">Batch size</span><input type="number" min="0" value={batchSize} onChange={(e) => setBatchSize(e.target.value)} placeholder="All at once" className={inputCls} data-testid="send-batch-size" /></div>
          <div><span className="text-xs text-slate-400">Every (mins)</span><input type="number" min="0" value={batchInterval} onChange={(e) => setBatchInterval(e.target.value)} className={inputCls} data-testid="send-batch-interval" /></div>
        </div>

        <div className="flex justify-end gap-2">
          <button onClick={onClose} className="px-4 py-2 rounded-full text-sm font-semibold text-slate-600 hover:bg-slate-100">Cancel</button>
          <button onClick={go} disabled={busy} className="flex items-center gap-1.5 px-5 py-2 rounded-full text-sm font-bold text-[#03212b] disabled:opacity-50" style={{ background: CYAN }} data-testid="send-confirm">{busy ? <Loader2 size={14} className="animate-spin" /> : <Rocket size={14} />}{strategy === 'immediate' ? 'Send now' : 'Schedule'}</button>
        </div>
      </div>
    </div>
  );
}

function Field({ label, children }) {
  return (
    <div className="mb-3">
      <label className="block text-[11px] uppercase tracking-wider font-bold text-slate-400 mb-1">{label}</label>
      {children}
    </div>
  );
}
const inputCls = 'w-full px-3 py-2 rounded-lg border border-slate-200 text-sm focus:border-[#19CDFF] focus:outline-none';

function MergeTags({ onInsert }) {
  return (
    <div className="mb-3">
      <p className="flex items-center gap-1 text-[11px] uppercase tracking-wider font-bold text-slate-400 mb-1"><Sparkles size={11} />Merge tags</p>
      {Object.entries(MERGE_GROUPS).map(([g, tags]) => (
        <div key={g} className="mb-1.5">
          <span className="text-[10px] text-slate-400">{g}</span>
          <div className="flex flex-wrap gap-1 mt-0.5">
            {tags.map((t) => (
              <button key={t} onClick={() => onInsert(t)} className="text-[11px] px-1.5 py-0.5 rounded bg-slate-100 text-slate-600 hover:bg-[#19CDFF22] font-mono" data-testid={`merge-${t.replace(/[{}]/g, '')}`}>{t}</button>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}

function BlockProps({ block, update }) {
  const p = block.props || {};
  const appendText = (key) => (t) => update({ [key]: (p[key] || '') + ' ' + t });
  switch (block.type) {
    case 'heading':
      return (
        <div data-testid="props-heading">
          <Field label="Text"><input className={inputCls} value={p.text || ''} onChange={(e) => update({ text: e.target.value })} /></Field>
          <Field label="Size"><input type="number" className={inputCls} value={p.size || 24} onChange={(e) => update({ size: parseInt(e.target.value, 10) || 24 })} /></Field>
          <Field label="Align"><AlignSelect value={p.align} onChange={(v) => update({ align: v })} /></Field>
          <Field label="Colour"><input type="color" className="w-full h-9 rounded-lg border border-slate-200" value={p.color || '#0B1220'} onChange={(e) => update({ color: e.target.value })} /></Field>
          <MergeTags onInsert={appendText('text')} />
        </div>
      );
    case 'text':
      return (
        <div data-testid="props-text">
          <Field label="Text"><textarea rows={5} className={inputCls} value={p.text || ''} onChange={(e) => update({ text: e.target.value })} /></Field>
          <Field label="Align"><AlignSelect value={p.align} onChange={(v) => update({ align: v })} /></Field>
          <MergeTags onInsert={appendText('text')} />
        </div>
      );
    case 'button':
      return (
        <div data-testid="props-button">
          <Field label="Label"><input className={inputCls} value={p.text || ''} onChange={(e) => update({ text: e.target.value })} /></Field>
          <Field label="URL"><input className={inputCls} value={p.url || ''} onChange={(e) => update({ url: e.target.value })} /></Field>
          <Field label="Align"><AlignSelect value={p.align} onChange={(v) => update({ align: v })} /></Field>
          <Field label="Colour"><input type="color" className="w-full h-9 rounded-lg border border-slate-200" value={p.color || CYAN} onChange={(e) => update({ color: e.target.value })} /></Field>
          <MergeTags onInsert={appendText('url')} />
        </div>
      );
    case 'image':
      return (
        <div data-testid="props-image">
          <Field label="Image URL"><input className={inputCls} value={p.src || ''} onChange={(e) => update({ src: e.target.value })} /></Field>
          <Field label="Alt text"><input className={inputCls} value={p.alt || ''} onChange={(e) => update({ alt: e.target.value })} /></Field>
        </div>
      );
    case 'logo':
      return (
        <div data-testid="props-logo">
          <Field label="Logo URL"><input className={inputCls} value={p.src || ''} onChange={(e) => update({ src: e.target.value })} /></Field>
          <Field label="Align"><AlignSelect value={p.align} onChange={(v) => update({ align: v })} /></Field>
        </div>
      );
    case 'spacer':
      return <div data-testid="props-spacer"><Field label="Height (px)"><input type="number" className={inputCls} value={p.height || 24} onChange={(e) => update({ height: parseInt(e.target.value, 10) || 24 })} /></Field></div>;
    case 'video':
      return (
        <div data-testid="props-video">
          <Field label="Video URL"><input className={inputCls} value={p.url || ''} onChange={(e) => update({ url: e.target.value })} /></Field>
          <Field label="Thumbnail URL"><input className={inputCls} value={p.thumbnail || ''} onChange={(e) => update({ thumbnail: e.target.value })} /></Field>
        </div>
      );
    case 'html':
      return <div data-testid="props-html"><Field label="HTML"><textarea rows={8} className={`${inputCls} font-mono text-xs`} value={p.html || ''} onChange={(e) => update({ html: e.target.value })} /></Field></div>;
    case 'footer':
      return <div data-testid="props-footer"><Field label="Footer text"><textarea rows={4} className={inputCls} value={p.text || ''} onChange={(e) => update({ text: e.target.value })} /></Field><p className="text-[11px] text-slate-400">Unsubscribe & preference links are added automatically.</p></div>;
    case 'social':
      return (
        <div data-testid="props-social">
          {(p.links || []).map((l, i) => (
            <div key={i} className="flex gap-1 mb-2">
              <input className={inputCls} value={l.label} placeholder="Label" onChange={(e) => { const links = [...p.links]; links[i] = { ...l, label: e.target.value }; update({ links }); }} />
              <input className={inputCls} value={l.url} placeholder="URL" onChange={(e) => { const links = [...p.links]; links[i] = { ...l, url: e.target.value }; update({ links }); }} />
            </div>
          ))}
          <button onClick={() => update({ links: [...(p.links || []), { label: 'Link', url: '#' }] })} className="text-xs font-semibold text-[#0891b2]">+ Add link</button>
        </div>
      );
    default:
      return <p className="text-sm text-slate-400">No options for this block.</p>;
  }
}

function AlignSelect({ value, onChange }) {
  return (
    <select className={inputCls} value={value || 'left'} onChange={(e) => onChange(e.target.value)}>
      <option value="left">Left</option>
      <option value="center">Center</option>
      <option value="right">Right</option>
    </select>
  );
}

/**
 * Flows — automation / lifecycle journey builder for the Comms Centre.
 * Surfaces the shared marketing journeys engine (triggers + ordered nodes,
 * omnichannel dispatch) as a structured, step-based builder.
 */
import React, { useCallback, useEffect, useMemo, useState } from 'react';
import axios from 'axios';
import { toast } from 'sonner';
import {
  Workflow, Plus, Mail, MessageSquare, Clock, Tag, Bell, Trash2, ArrowUp, ArrowDown, Save, Send, Zap, X,
} from 'lucide-react';

const TRIGGERS = [
  { id: 'member_signed_up', label: 'Member signs up' },
  { id: 'member_renewed', label: 'Membership renewed' },
  { id: 'membership_expiring', label: 'Membership expiring soon' },
  { id: 'payment_failed', label: 'Payment failed' },
  { id: 'trial_started', label: 'Trial started' },
  { id: 'quote_sent', label: 'Quote sent' },
  { id: 'contact_created', label: 'New CRM contact' },
  { id: 'manual', label: 'Manual enrolment only' },
];

const NODE_TYPES = [
  { type: 'send_email', label: 'Send email', icon: Mail },
  { type: 'send_sms', label: 'Send SMS', icon: MessageSquare },
  { type: 'wait', label: 'Wait', icon: Clock },
  { type: 'tag', label: 'Add tag', icon: Tag },
  { type: 'notify_staff', label: 'Notify staff', icon: Bell },
];
const NODE_META = Object.fromEntries(NODE_TYPES.map((n) => [n.type, n]));
const uid = () => Math.random().toString(36).slice(2, 10);

export function FlowsView({ API, headers }) {
  const apiRoot = useMemo(() => (API || process.env.REACT_APP_BACKEND_URL || '').replace(/\/api\/?$/, ''), [API]);
  const [journeys, setJourneys] = useState([]);
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const r = await axios.get(`${apiRoot}/api/marketing/journeys`, { headers });
      setJourneys(r.data.journeys || []);
    } catch (e) {
      if (e?.response?.status === 403) toast.error('Flows need the Marketing module enabled.');
      else toast.error('Failed to load flows');
    } finally { setLoading(false); }
  }, [apiRoot, headers]);

  useEffect(() => { load(); }, [load]);

  const newFlow = () => setEditing({
    name: 'New flow', status: 'draft', trigger: { event: 'member_signed_up' }, nodes: [],
  });

  if (editing) {
    return <FlowEditor flow={editing} apiRoot={apiRoot} headers={headers} onClose={() => { setEditing(null); load(); }} />;
  }

  return (
    <div data-testid="comms-flows">
      <div className="flex items-center justify-between mb-4">
        <p className="text-sm" style={{ color: 'var(--theme-text-muted)' }}>Automated, trigger-based journeys across email &amp; SMS.</p>
        <button onClick={newFlow} className="flex items-center gap-1.5 px-4 py-2 rounded-full text-sm font-bold" style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-ink, #1B1C1D)' }} data-testid="flow-create-btn"><Plus size={15} />New flow</button>
      </div>
      <div className="rounded-2xl border overflow-hidden" style={{ background: 'var(--theme-surface)', borderColor: 'var(--theme-border)' }}>
        {loading ? (
          <div className="p-10 text-center text-sm" style={{ color: 'var(--theme-text-muted)' }}>Loading…</div>
        ) : journeys.length === 0 ? (
          <div className="p-12 text-center">
            <Workflow size={28} className="mx-auto mb-2" style={{ color: 'var(--theme-text-muted)' }} />
            <p className="font-semibold" style={{ color: 'var(--theme-text)' }}>No flows yet</p>
            <p className="text-sm mb-4" style={{ color: 'var(--theme-text-muted)' }}>Automate welcome series, renewals and win-backs.</p>
            <button onClick={newFlow} className="px-4 py-2 rounded-full text-sm font-bold" style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-ink, #1B1C1D)' }} data-testid="flow-empty-create">Create flow</button>
          </div>
        ) : (
          <div>
            {journeys.map((j) => (
              <button key={j.id} onClick={() => setEditing(j)} className="w-full text-left flex items-center justify-between gap-3 px-5 py-4 border-t hover:bg-black/[0.02] dark:hover:bg-white/[0.02]" style={{ borderColor: 'var(--theme-border)' }} data-testid={`flow-row-${j.id}`}>
                <div className="min-w-0">
                  <div className="font-semibold flex items-center gap-2" style={{ color: 'var(--theme-text)' }}><Workflow size={15} />{j.name}</div>
                  <div className="text-xs mt-0.5 flex items-center gap-2" style={{ color: 'var(--theme-text-muted)' }}>
                    <Zap size={11} />{TRIGGERS.find((t) => t.id === j.trigger?.event)?.label || j.trigger?.event} · {(j.nodes || []).length} steps
                  </div>
                </div>
                <span className={`text-[11px] font-bold px-2 py-1 rounded-full ${j.status === 'active' ? 'bg-emerald-500/15 text-emerald-600' : 'bg-slate-500/15 text-slate-500'}`}>{j.status}</span>
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

function FlowEditor({ flow, apiRoot, headers, onClose }) {
  const [name, setName] = useState(flow.name || '');
  const [status, setStatus] = useState(flow.status || 'draft');
  const [trigger, setTrigger] = useState(flow.trigger?.event || 'member_signed_up');
  const [nodes, setNodes] = useState(() => (flow.nodes || []).map((n) => ({ ...n, id: n.id || uid() })));
  const [saving, setSaving] = useState(false);
  const [id, setId] = useState(flow.id || null);
  const [testContact, setTestContact] = useState('');

  const addNode = (type) => setNodes((prev) => [...prev, { id: uid(), type, title: '', subject: '', body: '', hours: 24, tag: '' }]);
  const updateNode = (nid, patch) => setNodes((prev) => prev.map((n) => (n.id === nid ? { ...n, ...patch } : n)));
  const removeNode = (nid) => setNodes((prev) => prev.filter((n) => n.id !== nid));
  const move = (idx, dir) => setNodes((prev) => {
    const j = idx + dir; if (j < 0 || j >= prev.length) return prev;
    const next = [...prev]; [next[idx], next[j]] = [next[j], next[idx]]; return next;
  });

  const save = async () => {
    setSaving(true);
    try {
      const r = await axios.post(`${apiRoot}/api/marketing/journeys`, {
        id: id || undefined, name, status, trigger: { event: trigger }, nodes,
      }, { headers });
      setId(r.data.journey?.id);
      toast.success('Flow saved');
      return r.data.journey?.id;
    } catch (e) {
      toast.error(e?.response?.data?.detail || 'Save failed');
      return null;
    } finally { setSaving(false); }
  };

  const testSend = async () => {
    const jid = id || await save();
    if (!jid) return;
    if (!testContact.trim()) { toast.error('Enter a CRM contact id to test'); return; }
    try {
      const r = await axios.post(`${apiRoot}/api/marketing/journeys/${jid}/test-send`, { contact_id: testContact.trim() }, { headers });
      toast.success(`Test: ${r.data.sent} sent, ${r.data.skipped} skipped`);
    } catch (e) {
      toast.error(e?.response?.data?.detail || 'Test send failed');
    }
  };

  const inputStyle = { background: 'var(--theme-bg)', borderColor: 'var(--theme-border)', color: 'var(--theme-text)' };
  return (
    <div data-testid="flow-editor">
      <div className="flex items-center justify-between gap-3 mb-4 flex-wrap">
        <button onClick={onClose} className="flex items-center gap-1.5 text-sm font-semibold" style={{ color: 'var(--theme-text-muted)' }} data-testid="flow-back"><X size={16} />Back to flows</button>
        <div className="flex items-center gap-2">
          <input value={testContact} onChange={(e) => setTestContact(e.target.value)} placeholder="Test contact id" className="px-3 py-2 rounded-full text-sm border" style={inputStyle} data-testid="flow-test-contact" />
          <button onClick={testSend} className="flex items-center gap-1.5 px-3 py-2 rounded-full text-sm font-semibold border" style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }} data-testid="flow-test-send"><Send size={14} />Test</button>
          <button onClick={save} disabled={saving} className="flex items-center gap-1.5 px-4 py-2 rounded-full text-sm font-bold disabled:opacity-50" style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-ink, #1B1C1D)' }} data-testid="flow-save"><Save size={14} />{saving ? 'Saving…' : 'Save'}</button>
        </div>
      </div>

      <div className="rounded-2xl border p-5 mb-4" style={{ background: 'var(--theme-surface)', borderColor: 'var(--theme-border)' }}>
        <div className="grid sm:grid-cols-3 gap-3">
          <div className="sm:col-span-1">
            <label className="block text-[11px] uppercase tracking-wider font-bold mb-1" style={{ color: 'var(--theme-text-muted)' }}>Name</label>
            <input value={name} onChange={(e) => setName(e.target.value)} className="w-full px-3 py-2 rounded-xl border text-sm" style={inputStyle} data-testid="flow-name" />
          </div>
          <div>
            <label className="block text-[11px] uppercase tracking-wider font-bold mb-1" style={{ color: 'var(--theme-text-muted)' }}>Trigger</label>
            <select value={trigger} onChange={(e) => setTrigger(e.target.value)} className="w-full px-3 py-2 rounded-xl border text-sm" style={inputStyle} data-testid="flow-trigger">
              {TRIGGERS.map((t) => <option key={t.id} value={t.id}>{t.label}</option>)}
            </select>
          </div>
          <div>
            <label className="block text-[11px] uppercase tracking-wider font-bold mb-1" style={{ color: 'var(--theme-text-muted)' }}>Status</label>
            <select value={status} onChange={(e) => setStatus(e.target.value)} className="w-full px-3 py-2 rounded-xl border text-sm" style={inputStyle} data-testid="flow-status">
              <option value="draft">Draft</option>
              <option value="active">Active</option>
              <option value="paused">Paused</option>
            </select>
          </div>
        </div>
      </div>

      {/* Steps */}
      <div className="space-y-3">
        {nodes.map((n, i) => {
          const Meta = NODE_META[n.type] || { label: n.type, icon: Workflow };
          const Icon = Meta.icon;
          return (
            <div key={n.id} className="rounded-2xl border p-4" style={{ background: 'var(--theme-surface)', borderColor: 'var(--theme-border)' }} data-testid={`flow-node-${i}`}>
              <div className="flex items-center justify-between mb-3">
                <div className="flex items-center gap-2 font-bold text-sm" style={{ color: 'var(--theme-text)' }}><Icon size={15} />{Meta.label}</div>
                <div className="flex items-center gap-1">
                  <button onClick={() => move(i, -1)} className="p-1.5 rounded-lg hover:bg-black/5 dark:hover:bg-white/5" style={{ color: 'var(--theme-text-muted)' }}><ArrowUp size={14} /></button>
                  <button onClick={() => move(i, 1)} className="p-1.5 rounded-lg hover:bg-black/5 dark:hover:bg-white/5" style={{ color: 'var(--theme-text-muted)' }}><ArrowDown size={14} /></button>
                  <button onClick={() => removeNode(n.id)} className="p-1.5 rounded-lg hover:bg-black/5 dark:hover:bg-white/5 text-rose-500" data-testid={`flow-node-remove-${i}`}><Trash2 size={14} /></button>
                </div>
              </div>
              {n.type === 'send_email' && (
                <div className="space-y-2">
                  <input value={n.subject || ''} onChange={(e) => updateNode(n.id, { subject: e.target.value })} placeholder="Subject line" className="w-full px-3 py-2 rounded-lg border text-sm" style={inputStyle} data-testid={`flow-node-subject-${i}`} />
                  <textarea value={n.body || ''} onChange={(e) => updateNode(n.id, { body: e.target.value })} rows={3} placeholder="Email body (HTML supported). Use {{first_name}} to personalise." className="w-full px-3 py-2 rounded-lg border text-sm" style={inputStyle} data-testid={`flow-node-body-${i}`} />
                </div>
              )}
              {n.type === 'send_sms' && (
                <textarea value={n.body || ''} onChange={(e) => updateNode(n.id, { body: e.target.value })} rows={2} placeholder="SMS message (160 chars)" className="w-full px-3 py-2 rounded-lg border text-sm" style={inputStyle} data-testid={`flow-node-body-${i}`} />
              )}
              {n.type === 'wait' && (
                <div className="flex items-center gap-2 text-sm" style={{ color: 'var(--theme-text)' }}>Wait <input type="number" min="1" value={n.hours || 24} onChange={(e) => updateNode(n.id, { hours: Number(e.target.value) || 24 })} className="w-20 px-2 py-1.5 rounded-lg border" style={inputStyle} data-testid={`flow-node-hours-${i}`} /> hours</div>
              )}
              {n.type === 'tag' && (
                <input value={n.tag || ''} onChange={(e) => updateNode(n.id, { tag: e.target.value })} placeholder="Tag to add (e.g. engaged)" className="w-full px-3 py-2 rounded-lg border text-sm" style={inputStyle} data-testid={`flow-node-tag-${i}`} />
              )}
              {n.type === 'notify_staff' && (
                <input value={n.body || ''} onChange={(e) => updateNode(n.id, { body: e.target.value })} placeholder="Internal note for staff" className="w-full px-3 py-2 rounded-lg border text-sm" style={inputStyle} data-testid={`flow-node-note-${i}`} />
              )}
            </div>
          );
        })}
      </div>

      {/* Add step */}
      <div className="mt-4 rounded-2xl border border-dashed p-4" style={{ borderColor: 'var(--theme-border)' }}>
        <p className="text-[11px] uppercase tracking-wider font-bold mb-2" style={{ color: 'var(--theme-text-muted)' }}>Add a step</p>
        <div className="flex flex-wrap gap-2">
          {NODE_TYPES.map(({ type, label, icon: Icon }) => (
            <button key={type} onClick={() => addNode(type)} className="flex items-center gap-1.5 px-3 py-2 rounded-full text-sm font-semibold border" style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }} data-testid={`flow-add-${type}`}><Icon size={14} />{label}</button>
          ))}
        </div>
      </div>
    </div>
  );
}

