/**
 * Migrate — ESP migration / CSV import for the Comms Centre.
 * Upload any ESP export (Mailchimp/Klaviyo/generic), auto-map columns,
 * import contacts and carry over unsubscribe status to the suppression list.
 */
import React, { useRef, useState } from 'react';
import axios from 'axios';
import { toast } from 'sonner';
import { Upload, FileSpreadsheet, ArrowRight, CheckCircle2, Loader2, ShieldOff, UserPlus, RefreshCw, SkipForward } from 'lucide-react';

const FIELDS = [
  { key: 'email', label: 'Email address', required: true },
  { key: 'first_name', label: 'First name' },
  { key: 'last_name', label: 'Last name' },
  { key: 'company', label: 'Company' },
  { key: 'status', label: 'Subscription status' },
];

export function MigrateView({ API, headers }) {
  const apiRoot = (API || process.env.REACT_APP_BACKEND_URL || '').replace(/\/api\/?$/, '');
  const fileRef = useRef(null);
  const [file, setFile] = useState(null);
  const [preview, setPreview] = useState(null);
  const [mapping, setMapping] = useState({});
  const [busy, setBusy] = useState(false);
  const [summary, setSummary] = useState(null);

  const onPick = async (f) => {
    if (!f) return;
    setFile(f); setSummary(null); setBusy(true);
    try {
      const fd = new FormData();
      fd.append('file', f);
      const r = await axios.post(`${apiRoot}/api/comms/import/preview`, fd, { headers });
      setPreview(r.data);
      setMapping(r.data.suggested_mapping || {});
    } catch (e) {
      toast.error(e?.response?.data?.detail || 'Could not read that file');
      setPreview(null);
    } finally { setBusy(false); }
  };

  const commit = async () => {
    if (!mapping.email) { toast.error('Map the email column first'); return; }
    setBusy(true);
    try {
      const fd = new FormData();
      fd.append('file', file);
      fd.append('mapping', JSON.stringify(mapping));
      const r = await axios.post(`${apiRoot}/api/comms/import/commit`, fd, { headers });
      setSummary(r.data);
      toast.success('Import complete');
    } catch (e) {
      toast.error(e?.response?.data?.detail || 'Import failed');
    } finally { setBusy(false); }
  };

  const reset = () => { setFile(null); setPreview(null); setMapping({}); setSummary(null); if (fileRef.current) fileRef.current.value = ''; };

  const card = { background: 'var(--theme-surface)', borderColor: 'var(--theme-border)' };
  const input = { background: 'var(--theme-bg)', borderColor: 'var(--theme-border)', color: 'var(--theme-text)' };

  if (summary) {
    const stats = [
      { label: 'Created', value: summary.created, icon: UserPlus, color: '#10b981' },
      { label: 'Updated', value: summary.updated, icon: RefreshCw, color: '#19cdff' },
      { label: 'Suppressed', value: summary.suppressed, icon: ShieldOff, color: '#f59e0b' },
      { label: 'Skipped', value: summary.skipped, icon: SkipForward, color: '#9a9fa1' },
    ];
    return (
      <div data-testid="migrate-summary">
        <div className="rounded-2xl border p-8 text-center" style={card}>
          <CheckCircle2 size={40} className="mx-auto mb-3 text-emerald-500" />
          <h3 className="text-lg font-bold" style={{ color: 'var(--theme-text)' }}>Import complete</h3>
          <p className="text-sm mb-6" style={{ color: 'var(--theme-text-muted)' }}>{summary.total} rows processed from your export.</p>
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 max-w-2xl mx-auto">
            {stats.map((s) => (
              <div key={s.label} className="rounded-xl border p-4" style={{ borderColor: 'var(--theme-border)' }}>
                <s.icon size={18} style={{ color: s.color }} className="mx-auto mb-1" />
                <div className="text-2xl font-bold" style={{ color: 'var(--theme-text)' }} data-testid={`migrate-stat-${s.label.toLowerCase()}`}>{s.value}</div>
                <div className="text-xs" style={{ color: 'var(--theme-text-muted)' }}>{s.label}</div>
              </div>
            ))}
          </div>
          <button onClick={reset} className="mt-6 px-4 py-2 rounded-full text-sm font-bold" style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-ink, #1B1C1D)' }} data-testid="migrate-again">Import another file</button>
        </div>
      </div>
    );
  }

  return (
    <div data-testid="comms-migrate">
      <div className="rounded-2xl border p-5 mb-4" style={card}>
        <p className="text-sm mb-3" style={{ color: 'var(--theme-text-muted)' }}>
          Moving from Mailchimp, Klaviyo or another tool? Export your audience as CSV and drop it here — we'll map the columns, import your contacts and honour anyone who'd already unsubscribed.
        </p>
        <input ref={fileRef} type="file" accept=".csv,text/csv" className="hidden" onChange={(e) => onPick(e.target.files?.[0])} data-testid="migrate-file-input" />
        <button onClick={() => fileRef.current?.click()} disabled={busy} className="w-full rounded-xl border-2 border-dashed py-10 flex flex-col items-center gap-2 hover:bg-black/[0.02] dark:hover:bg-white/[0.02] transition-colors disabled:opacity-50" style={{ borderColor: 'var(--theme-border)' }} data-testid="migrate-upload-btn">
          {busy && !preview ? <Loader2 size={26} className="animate-spin text-cyan-500" /> : <Upload size={26} style={{ color: 'var(--theme-text-muted)' }} />}
          <span className="text-sm font-semibold" style={{ color: 'var(--theme-text)' }}>{file ? file.name : 'Choose a CSV file'}</span>
          <span className="text-xs" style={{ color: 'var(--theme-text-muted)' }}>{file ? 'Click to replace' : 'Up to ~50k rows'}</span>
        </button>
      </div>

      {preview && (
        <div className="rounded-2xl border p-5" style={card} data-testid="migrate-mapping">
          <div className="flex items-center gap-2 mb-1"><FileSpreadsheet size={16} style={{ color: 'var(--theme-text)' }} /><h3 className="font-bold" style={{ color: 'var(--theme-text)' }}>Map your columns</h3></div>
          <p className="text-xs mb-4" style={{ color: 'var(--theme-text-muted)' }}>{preview.total_rows} rows · {preview.columns.length} columns detected. We auto-matched what we could.</p>
          <div className="grid sm:grid-cols-2 gap-3 mb-5">
            {FIELDS.map((f) => (
              <div key={f.key}>
                <label className="block text-[11px] uppercase tracking-wider font-bold mb-1" style={{ color: 'var(--theme-text-muted)' }}>{f.label}{f.required && <span className="text-rose-500"> *</span>}</label>
                <select value={mapping[f.key] || ''} onChange={(e) => setMapping((m) => ({ ...m, [f.key]: e.target.value || null }))} className="w-full px-3 py-2 rounded-lg border text-sm" style={input} data-testid={`migrate-map-${f.key}`}>
                  <option value="">— Not mapped —</option>
                  {preview.columns.map((c) => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
            ))}
          </div>
          <p className="text-xs mb-4 rounded-lg p-2.5" style={{ background: 'var(--theme-bg)', color: 'var(--theme-text-muted)' }}>
            Tip: map <strong>Subscription status</strong> so unsubscribed/cleaned contacts are added to your suppression list automatically.
          </p>
          <button onClick={commit} disabled={busy || !mapping.email} className="flex items-center gap-2 px-5 py-2.5 rounded-full text-sm font-bold disabled:opacity-50" style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-ink, #1B1C1D)' }} data-testid="migrate-commit">
            {busy ? <Loader2 size={15} className="animate-spin" /> : <ArrowRight size={15} />}Import {preview.total_rows} contacts
          </button>
        </div>
      )}
    </div>
  );
}

/**
 * Hosted email archive — routed at /c/view/:id (no auth).
 * Renders a previously-sent campaign email as a standalone web page
 * (the {{view_in_browser_link}} target).
 */
import { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import { Loader2, MailX } from 'lucide-react';

const API = process.env.REACT_APP_BACKEND_URL + '/api';

export default function PublicEmailViewPage() {
  const { id } = useParams();
  const [data, setData] = useState(null);
  const [error, setError] = useState(false);

  useEffect(() => {
    axios.get(`${API}/comms/public/view/${id}`)
      .then(res => { setData(res.data); document.title = res.data.subject || 'Email'; })
      .catch(() => setError(true));
  }, [id]);

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center" style={{ background: '#0A0C12' }} data-testid="view-error">
        <div className="text-center">
          <MailX className="w-10 h-10 mx-auto mb-4 text-rose-400" />
          <p className="text-slate-300">This email is no longer available.</p>
        </div>
      </div>
    );
  }

  if (!data) {
    return (
      <div className="min-h-screen flex items-center justify-center" style={{ background: '#0A0C12' }} data-testid="view-loading">
        <Loader2 className="w-6 h-6 animate-spin text-cyan-400" />
      </div>
    );
  }

  return (
    <div className="min-h-screen" style={{ background: '#F0F0F0' }} data-testid="email-view-page">
      <div className="text-center py-3 text-xs text-slate-500 bg-white border-b border-slate-200">
        Viewing in browser · {data.subject}
      </div>
      {/* eslint-disable-next-line react/no-danger */}
      <div dangerouslySetInnerHTML={{ __html: data.html }} />
    </div>
  );
}

/**
 * Pulse Fitness AI — audience segment builder (Phase 2).
 * Saved + dynamic segments across contacts and members, using the shared
 * rule engine. Live preview count as you build.
 */
import React, { useCallback, useEffect, useMemo, useState } from 'react';
import axios from 'axios';
import { toast } from 'sonner';
import { Plus, Trash2, X, Users, Filter, RefreshCw, Pencil, Wand2, Loader2 } from 'lucide-react';

const apiRoot = (API) => (API || process.env.REACT_APP_BACKEND_URL || '').replace(/\/api\/?$/, '');
const card = { background: 'var(--theme-surface)', borderColor: 'var(--theme-border)' };
const muted = { color: 'var(--theme-text-muted)' };
const txt = { color: 'var(--theme-text)' };
const inputCls = 'px-2.5 py-2 rounded-lg border text-sm focus:outline-none';
const inputStyle = { background: 'var(--theme-bg)', borderColor: 'var(--theme-border)', color: 'var(--theme-text)' };

export function SegmentsView({ API, headers }) {
  const root = apiRoot(API);
  const [meta, setMeta] = useState(null);
  const [segments, setSegments] = useState(null);
  const [editing, setEditing] = useState(null);
  const [showAI, setShowAI] = useState(false);
  const [aiDesc, setAiDesc] = useState('');
  const [aiBusy, setAiBusy] = useState(false);

  const aiSuggest = async () => {
    if (!aiDesc.trim()) { toast.error('Describe the audience'); return; }
    setAiBusy(true);
    try {
      const r = await axios.post(`${root}/api/comms/segments/ai-suggest`, { description: aiDesc }, { headers });
      setShowAI(false); setAiDesc('');
      setEditing({ name: r.data.name, source: r.data.source, type: 'dynamic', rules: r.data.rules });
      toast.success(`Suggested segment (~${r.data.count} matches) — review & save`);
    } catch (e) { toast.error(e?.response?.data?.detail || 'AI is unavailable right now'); }
    finally { setAiBusy(false); }
  };

  const load = useCallback(async () => {
    try { const r = await axios.get(`${root}/api/comms/segments`, { headers }); setSegments(r.data.segments); }
    catch { toast.error('Failed to load segments'); }
  }, [root, headers]);

  useEffect(() => { axios.get(`${root}/api/comms/segments/fields`, { headers }).then((r) => setMeta(r.data)).catch(() => {}); }, [root, headers]);
  useEffect(() => { load(); }, [load]);

  const del = async (s) => {
    try { await axios.delete(`${root}/api/comms/segments/${s.id}`, { headers }); toast.success('Segment deleted'); load(); }
    catch { toast.error('Delete failed'); }
  };

  return (
    <div data-testid="segments-view">
      <div className="flex items-center justify-between mb-4">
        <p className="text-sm" style={muted}>Saved &amp; dynamic audiences — reusable across every campaign.</p>
        <div className="flex gap-2">
          <button onClick={() => setShowAI(true)} className="flex items-center gap-1.5 px-4 py-2 rounded-full text-sm font-bold text-white" style={{ backgroundImage: 'linear-gradient(135deg,#0091CA,#19CDFF)' }} data-testid="segment-ai-btn"><Wand2 size={15} />AI suggest</button>
          <button onClick={() => setEditing({})} className="flex items-center gap-1.5 px-4 py-2 rounded-full text-sm font-bold" style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-ink)' }} data-testid="segment-create-btn"><Plus size={15} />New segment</button>
        </div>
      </div>

      {showAI && (
        <div className="fixed inset-0 z-[160] bg-black/50 flex items-center justify-center p-4" onClick={() => setShowAI(false)}>
          <div className="rounded-2xl p-6 w-full max-w-md border" style={card} onClick={(e) => e.stopPropagation()} data-testid="segment-ai-modal">
            <h3 className="flex items-center gap-2 font-bold text-lg pulse-font-heading mb-1" style={txt}><Wand2 size={18} className="text-violet-500" />AI segment builder</h3>
            <p className="text-sm mb-4" style={muted}>Describe the audience in plain English — we'll build the rules for you to review.</p>
            <textarea value={aiDesc} onChange={(e) => setAiDesc(e.target.value)} rows={3} placeholder="e.g. lapsed members who haven't visited in 90 days" className={`w-full ${inputCls} mb-4`} style={inputStyle} data-testid="segment-ai-desc" />
            <div className="flex justify-end gap-2">
              <button onClick={() => setShowAI(false)} className="px-4 py-2 rounded-full text-sm font-semibold hover:bg-black/5" style={muted}>Cancel</button>
              <button onClick={aiSuggest} disabled={aiBusy} className="flex items-center gap-1.5 px-4 py-2 rounded-full text-sm font-bold text-white disabled:opacity-50" style={{ backgroundImage: 'linear-gradient(135deg,#0091CA,#19CDFF)' }} data-testid="segment-ai-go">{aiBusy ? <Loader2 size={14} className="animate-spin" /> : <Wand2 size={14} />}Build it</button>
            </div>
          </div>
        </div>
      )}

      {!segments ? <p className="text-sm" style={muted}>Loading…</p>
        : segments.length === 0 ? (
          <div className="rounded-2xl border p-12 text-center" style={card}>
            <Filter size={28} className="mx-auto mb-2" style={muted} />
            <p className="font-semibold" style={txt}>No segments yet</p>
            <p className="text-sm mb-4" style={muted}>Build a targeted audience once and reuse it everywhere.</p>
            <button onClick={() => setEditing({})} className="px-4 py-2 rounded-full text-sm font-bold" style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-ink)' }} data-testid="segment-empty-create">Create segment</button>
          </div>
        ) : (
          <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-3" data-testid="segment-list">
            {segments.map((s) => (
              <div key={s.id} className="rounded-2xl border p-4" style={card} data-testid={`segment-card-${s.id}`}>
                <div className="flex items-start justify-between gap-2">
                  <div className="min-w-0">
                    <p className="font-bold truncate" style={txt}>{s.name}</p>
                    <p className="text-xs" style={muted}>{s.source === 'members' ? 'Members' : 'Contacts'} · {s.type}</p>
                  </div>
                  <div className="flex gap-1 shrink-0">
                    <button onClick={() => setEditing(s)} className="p-1 rounded hover:bg-black/5" style={muted} data-testid={`segment-edit-${s.id}`}><Pencil size={14} /></button>
                    <button onClick={() => del(s)} className="p-1 rounded hover:bg-black/5 text-rose-500" data-testid={`segment-del-${s.id}`}><Trash2 size={14} /></button>
                  </div>
                </div>
                <div className="flex items-center gap-1.5 mt-3"><Users size={16} style={{ color: 'var(--color-brand-cyan)' }} /><span className="text-2xl font-extrabold pulse-font-heading" style={txt}>{s.member_count}</span><span className="text-xs" style={muted}>members</span></div>
              </div>
            ))}
          </div>
        )}

      {editing && meta && (
        <SegmentEditor root={root} headers={headers} meta={meta} segment={editing} onClose={() => setEditing(null)} onSaved={() => { setEditing(null); load(); }} />
      )}
    </div>
  );
}

function SegmentEditor({ root, headers, meta, segment, onClose, onSaved }) {
  const isEdit = !!segment.id;
  const [name, setName] = useState(segment.name || '');
  const [source, setSource] = useState(segment.source || 'contacts');
  const [type, setType] = useState(segment.type || 'dynamic');
  const [matchOp, setMatchOp] = useState(segment.rules?.op || 'and');
  const [conditions, setConditions] = useState(segment.rules?.conditions?.length ? segment.rules.conditions : [{ field: meta.fields[segment.source || 'contacts'][0].field, op: '==', value: '' }]);
  const [preview, setPreview] = useState(null);
  const [busy, setBusy] = useState(false);

  const fields = meta.fields[source] || [];
  const fieldDef = (f) => fields.find((x) => x.field === f) || fields[0];

  const rules = useMemo(() => ({
    op: matchOp,
    conditions: conditions
      .filter((c) => c.field && c.value !== '')
      .map((c) => ({ field: c.field, op: c.op, value: c.op === 'in' ? String(c.value).split(',').map((x) => x.trim()).filter(Boolean) : c.value })),
  }), [matchOp, conditions]);

  useEffect(() => {
    const t = setTimeout(async () => {
      try { const r = await axios.post(`${root}/api/comms/segments/preview`, { source, rules }, { headers }); setPreview(r.data); }
      catch { setPreview(null); }
    }, 400);
    return () => clearTimeout(t);
  }, [root, headers, source, rules]);

  const setCond = (i, patch) => setConditions((prev) => prev.map((c, idx) => (idx === i ? { ...c, ...patch } : c)));
  const addCond = () => setConditions((prev) => [...prev, { field: fields[0].field, op: '==', value: '' }]);
  const rmCond = (i) => setConditions((prev) => prev.filter((_, idx) => idx !== i));

  const save = async () => {
    if (!name.trim()) { toast.error('Name your segment'); return; }
    setBusy(true);
    try {
      const payload = { name, source, type, rules };
      if (isEdit) await axios.put(`${root}/api/comms/segments/${segment.id}`, payload, { headers });
      else await axios.post(`${root}/api/comms/segments`, payload, { headers });
      toast.success('Segment saved');
      onSaved();
    } catch (e) { toast.error(e?.response?.data?.detail || 'Save failed'); }
    finally { setBusy(false); }
  };

  return (
    <div className="fixed inset-0 z-[160] bg-black/50 flex items-center justify-center p-4" onClick={onClose}>
      <div className="rounded-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto border" style={card} onClick={(e) => e.stopPropagation()} data-testid="segment-editor">
        <div className="flex items-center justify-between px-6 py-4 border-b sticky top-0" style={{ ...card, borderColor: 'var(--theme-border)' }}>
          <h3 className="font-bold text-lg pulse-font-heading" style={txt}>{isEdit ? 'Edit segment' : 'New segment'}</h3>
          <button onClick={onClose} className="p-1.5 rounded-lg hover:bg-black/5" style={muted}><X size={18} /></button>
        </div>
        <div className="p-6">
          <div className="grid sm:grid-cols-2 gap-3 mb-4">
            <div>
              <label className="block text-[11px] uppercase tracking-wider font-bold mb-1" style={muted}>Name</label>
              <input value={name} onChange={(e) => setName(e.target.value)} className={`w-full ${inputCls}`} style={inputStyle} placeholder="e.g. Lapsed premium members" data-testid="segment-name" />
            </div>
            <div className="grid grid-cols-2 gap-2">
              <div>
                <label className="block text-[11px] uppercase tracking-wider font-bold mb-1" style={muted}>Audience</label>
                <select value={source} onChange={(e) => { const s = e.target.value; setSource(s); setConditions([{ field: meta.fields[s][0].field, op: '==', value: '' }]); }} className={`w-full ${inputCls}`} style={inputStyle} data-testid="segment-source">
                  {meta.sources.map((s) => <option key={s.id} value={s.id}>{s.label}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-[11px] uppercase tracking-wider font-bold mb-1" style={muted}>Type</label>
                <select value={type} onChange={(e) => setType(e.target.value)} className={`w-full ${inputCls}`} style={inputStyle} data-testid="segment-type">
                  <option value="dynamic">Dynamic</option>
                  <option value="saved">Saved (snapshot)</option>
                </select>
              </div>
            </div>
          </div>

          <div className="rounded-xl border p-4 mb-4" style={{ ...card, background: 'var(--theme-bg)' }}>
            <div className="flex items-center gap-2 mb-3 text-sm" style={txt}>
              Match
              <select value={matchOp} onChange={(e) => setMatchOp(e.target.value)} className={inputCls} style={inputStyle} data-testid="segment-match">
                <option value="and">all</option>
                <option value="or">any</option>
              </select>
              of these conditions
            </div>
            <div className="space-y-2">
              {conditions.map((c, i) => {
                const def = fieldDef(c.field);
                return (
                  <div key={i} className="flex flex-wrap items-center gap-2" data-testid={`segment-condition-${i}`}>
                    <select value={c.field} onChange={(e) => setCond(i, { field: e.target.value, value: '' })} className={inputCls} style={inputStyle} data-testid={`condition-field-${i}`}>
                      {fields.map((f) => <option key={f.field} value={f.field}>{f.label}</option>)}
                    </select>
                    <select value={c.op} onChange={(e) => setCond(i, { op: e.target.value })} className={inputCls} style={inputStyle} data-testid={`condition-op-${i}`}>
                      {meta.operators.map((o) => <option key={o.id} value={o.id}>{o.label}</option>)}
                    </select>
                    {def?.kind === 'select' ? (
                      <select value={c.value} onChange={(e) => setCond(i, { value: e.target.value })} className={`flex-1 min-w-[120px] ${inputCls}`} style={inputStyle} data-testid={`condition-value-${i}`}>
                        <option value="">Choose…</option>
                        {def.options.map((o) => <option key={o} value={o}>{o}</option>)}
                      </select>
                    ) : def?.kind === 'date' ? (
                      <select value={c.value} onChange={(e) => setCond(i, { value: e.target.value })} className={`flex-1 min-w-[120px] ${inputCls}`} style={inputStyle} data-testid={`condition-value-${i}`}>
                        <option value="">Choose…</option>
                        {meta.date_sentinels.map((d) => <option key={d} value={d}>{d.replace('d_ago', ' days ago')}</option>)}
                      </select>
                    ) : (
                      <input value={c.value} onChange={(e) => setCond(i, { value: e.target.value })} type={def?.kind === 'number' ? 'number' : 'text'} placeholder={def?.kind === 'tag' ? 'tag value' : 'value'} className={`flex-1 min-w-[120px] ${inputCls}`} style={inputStyle} data-testid={`condition-value-${i}`} />
                    )}
                    <button onClick={() => rmCond(i)} className="p-1.5 rounded hover:bg-black/5 text-rose-500" data-testid={`condition-remove-${i}`}><Trash2 size={14} /></button>
                  </div>
                );
              })}
            </div>
            <button onClick={addCond} className="mt-3 text-xs font-bold" style={{ color: 'var(--color-brand-cyan)' }} data-testid="segment-add-condition">+ Add condition</button>
          </div>

          <div className="flex items-center justify-between rounded-xl border p-4" style={card}>
            <div className="flex items-center gap-2">
              <Users size={18} style={{ color: 'var(--color-brand-cyan)' }} />
              <span className="text-2xl font-extrabold pulse-font-heading" style={txt} data-testid="segment-preview-count">{preview ? preview.count : '…'}</span>
              <span className="text-sm" style={muted}>matching {source === 'members' ? 'members' : 'contacts'}</span>
            </div>
            <RefreshCw size={14} style={muted} />
          </div>

          <div className="flex justify-end gap-2 mt-5">
            <button onClick={onClose} className="px-4 py-2 rounded-full text-sm font-semibold hover:bg-black/5" style={muted}>Cancel</button>
            <button onClick={save} disabled={busy} className="px-5 py-2 rounded-full text-sm font-bold disabled:opacity-50" style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-ink)' }} data-testid="segment-save">{busy ? 'Saving…' : 'Save segment'}</button>
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * EquipmentTransfersInbox (Iter 337) — gym Operations side.
 *
 * Surfaces equipment that an engineer wants to hand over to this gym's
 * Operations portal, plus a discovery row for equipment an engineer
 * already holds on file for this gym. The gym admin approves before
 * anything moves; transferred assets keep their QR codes and history.
 * Self-hides when there's nothing to action.
 */
import { useCallback, useEffect, useState } from 'react';
import { api } from '@/lib/api';
import { notify } from '@/components/notifications';
import { ArrowRightLeft, CheckCircle2, X, Loader2, PackagePlus } from 'lucide-react';

export default function EquipmentTransfersInbox({ onImported }) {
  const [pending, setPending] = useState([]);
  const [available, setAvailable] = useState([]);
  const [loading, setLoading] = useState(true);
  const [busyId, setBusyId] = useState(null);

  const load = useCallback(async () => {
    try {
      const [p, a] = await Promise.all([
        api.get('/operations/equipment-transfers', { params: { status: 'pending' } }),
        api.get('/operations/equipment-transfers/available'),
      ]);
      setPending((p.data?.transfers || []).filter((t) => t.awaiting === 'gym'));
      setAvailable(a.data?.available || []);
    } catch (_e) {
      /* non-blocking */
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { load(); }, [load]);

  const approve = async (t) => {
    setBusyId(t.id);
    try {
      const r = await api.post(`/operations/equipment-transfers/${t.id}/approve`);
      notify.success(`${r.data.moved_count} machine(s) imported into your Operations portal.`);
      await load();
      onImported?.();
    } catch (e) {
      notify.error(e?.response?.data?.detail || 'Could not approve transfer');
    } finally {
      setBusyId(null);
    }
  };

  const decline = async (t) => {
    setBusyId(t.id);
    try {
      await api.post(`/operations/equipment-transfers/${t.id}/decline`);
      await load();
    } catch (e) {
      notify.error(e?.response?.data?.detail || 'Could not decline transfer');
    } finally {
      setBusyId(null);
    }
  };

  const requestPull = async (a) => {
    setBusyId(a.source_customer_id);
    try {
      await api.post('/operations/equipment-transfers/request', {
        source_org_id: a.source_org_id,
        source_customer_id: a.source_customer_id,
      });
      notify.success('Import requested — your engineer will approve the handover.');
      await load();
    } catch (e) {
      notify.error(e?.response?.data?.detail || 'Could not request import');
    } finally {
      setBusyId(null);
    }
  };

  if (loading || (pending.length === 0 && available.length === 0)) return null;

  return (
    <div className="mb-6 rounded-2xl border border-orange-200 bg-orange-50/60 p-5" data-testid="eq-transfers-inbox">
      <div className="flex items-center gap-2 mb-3">
        <span className="w-8 h-8 rounded-xl bg-orange-500 text-white flex items-center justify-center"><ArrowRightLeft size={16} /></span>
        <h3 className="font-bold text-slate-900">Equipment from your engineer</h3>
      </div>

      {pending.map((t) => (
        <div key={t.id} className="rounded-xl border border-slate-200 bg-white p-4 mb-2 flex flex-wrap items-center justify-between gap-3" data-testid={`eq-transfer-pending-${t.id}`}>
          <div className="min-w-0">
            <p className="text-sm font-bold text-slate-900">{t.equipment_count} machine{t.equipment_count === 1 ? '' : 's'} ready to import</p>
            <p className="text-xs text-slate-500 mt-0.5">From {t.engineer_name || 'your engineer'}{t.engineer_company ? ` · ${t.engineer_company}` : ''} · QR codes & service history included</p>
          </div>
          <div className="flex items-center gap-2">
            <button type="button" onClick={() => decline(t)} disabled={busyId === t.id} className="inline-flex items-center gap-1 px-3 py-2 rounded-lg border border-slate-300 text-slate-600 text-xs font-bold hover:bg-slate-50" data-testid={`eq-transfer-decline-${t.id}`}>
              <X size={13} /> Decline
            </button>
            <button type="button" onClick={() => approve(t)} disabled={busyId === t.id} className="inline-flex items-center gap-1 px-4 py-2 rounded-lg bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-bold disabled:opacity-50" data-testid={`eq-transfer-approve-${t.id}`}>
              {busyId === t.id ? <Loader2 size={13} className="animate-spin" /> : <CheckCircle2 size={13} />} Approve & import
            </button>
          </div>
        </div>
      ))}

      {available.map((a) => (
        <div key={a.source_customer_id} className="rounded-xl border border-slate-200 bg-white p-4 mb-2 flex flex-wrap items-center justify-between gap-3" data-testid={`eq-transfer-available-${a.source_customer_id}`}>
          <div className="min-w-0">
            <p className="text-sm font-bold text-slate-900">{a.equipment_count} machine{a.equipment_count === 1 ? '' : 's'} on file with {a.engineer_org_name}</p>
            <p className="text-xs text-slate-500 mt-0.5">Request to import these into your Operations portal.</p>
          </div>
          <button type="button" onClick={() => requestPull(a)} disabled={busyId === a.source_customer_id} className="inline-flex items-center gap-1 px-4 py-2 rounded-lg bg-orange-500 hover:bg-orange-600 text-white text-xs font-bold disabled:opacity-50" data-testid={`eq-transfer-request-${a.source_customer_id}`}>
            {busyId === a.source_customer_id ? <Loader2 size={13} className="animate-spin" /> : <PackagePlus size={13} />} Request import
          </button>
        </div>
      ))}
    </div>
  );
}

import React, { Suspense, lazy, useState, useEffect } from 'react';
import { useAuth } from '@/App';
import { useSearchParams } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import axios from 'axios';
import { Loader2 } from 'lucide-react';

import { useUserPref } from '@/utils/userPrefs';

import Navbar from '../components/shared/Navbar';
import ModuleSwitcher from '../components/shared/ModuleSwitcher';
import ModulePageHeader from '../components/shared/ModulePageHeader';
import { Tabs, TabsContent } from '@/components/ui/tabs';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Badge } from '@/components/ui/badge';

// Iter 216h173 — Heavy per-tab dashboards (GymDesign 1,353 LoC, Settings
// 1,198 LoC, etc.) are lazy-loaded. Operators land on Start/Overview;
// every other tab fetches on first visit, shrinking the initial JS
// bundle parsed during the operator's first login.
const GymDesignTab = lazy(() => import('./GymDesignTab'));
const EquipmentInfoTab = lazy(() => import('./EquipmentInfoTab'));
const SettingsTab = lazy(() => import('./SettingsTab'));
const WeeklyDigest = lazy(() => import('./WeeklyDigest'));
const DocumentsTab = lazy(() => import('./DocumentsTab'));
const SupplierDashboardTab = lazy(() => import('./SupplierDashboardTab'));
const MasterAdminPage = lazy(() => import('./MasterAdminPage'));
const FaultsTab = lazy(() => import('./Dashboard/FaultsTab'));
const ReportsSection = lazy(() => import('./Dashboard/ReportsSection'));
const MaintenanceTab = lazy(() => import('./Dashboard/MaintenanceTab'));
const AdminDashboardTab = lazy(() => import('./Dashboard/AdminAnalytics/AdminDashboardTab'));
const AdminEquipmentTab = lazy(() => import('./Dashboard/AdminAnalytics/AdminEquipmentTab'));
const AdminFaultsTab = lazy(() => import('./Dashboard/AdminAnalytics/AdminFaultsTab'));
const AdminCheckSheetsTab = lazy(() => import('./Dashboard/AdminAnalytics/AdminCheckSheetsTab'));
const GlobalDocumentsTab = lazy(() => import('./Dashboard/AdminAnalytics/GlobalDocumentsTab'));
const OperationsStartTab = lazy(() => import('./LiteDashboard/OperationsStartTab'));
const StaffingConsole = lazy(() => import('./LiteDashboard/StaffingConsole'));
const InvoiceImportWizard = lazy(() => import('./InvoiceImportWizard'));
const OnboardingWizard = lazy(() => import('./OnboardingWizard'));

const DashboardTabFallback = () => (
  <div className="flex items-center justify-center py-16 text-zinc-400" data-testid="dashboard-tab-loading">
    <Loader2 size={18} className="animate-spin" />
  </div>
);

import MobileBottomNav from '../components/shared/MobileBottomNav';
import OverviewTab from './Dashboard/OverviewTab';
import DashboardTabs from './Dashboard/DashboardTabs';
import CustomerDeliveriesTab from './Deliveries/CustomerDeliveriesTab';
import FaultDialogs from './Dashboard/FaultDialogs';
import DocumentQA from '../components/shared/DocumentQA';
import PullToRefresh from '../components/shared/PullToRefresh';
import ProductTour from '../components/shared/ProductTour';

import useDashboardData from './Dashboard/hooks/useDashboardData';
import useIssueWorkflow from './Dashboard/hooks/useIssueWorkflow';
import { getSeverityColor, getSeverityLabel, getStatusColor } from './Dashboard/utils/severity';
import GamifiedOnboarding from './Dashboard/GamifiedOnboarding';
import WelcomeHero from './Dashboard/WelcomeHero';
import NudgeBanner from '../components/shared/NudgeBanner';
import { useSeo } from '../utils/seo';
import { can } from '../utils/capabilities';

const DashboardPage = () => {
  const { user, API, theme } = useAuth();
  // Iter 216o-6 — owns its own document.title so navigating from a SEO
  // page (e.g. /pricing) back to /dashboard correctly resets the tab.
  useSeo({ title: 'Dashboard · Pulse Fitness AI' });
  const { t, i18n } = useTranslation();
  const [searchParams] = useSearchParams();

  // Iter 216c — match LiteDashboardPage: first-time users land on the
  // guided "Start" tab (which now hosts the "Your first wins" card);
  // returning users who completed onboarding (or dismissed Start) land
  // on Dashboard / Overview directly.
  const [activeTab, setActiveTab] = useState(() => {
    try {
      const prefs = JSON.parse(localStorage.getItem('gymaxis_prefs') || '{}');
      return prefs.hideStartTabs ? 'overview' : 'start';
    } catch { return 'overview'; }
  });
  // Iter 216c — when ActivationMilestonesCard auto-completes (all 8 wins
  // hit) it flips `hideStartTabs=true`. If the user happened to be on the
  // Start tab at that moment, snap them to Overview so they don't see a
  // blank tab content.
  const [hideStartTabs] = useUserPref('hideStartTabs', false);
  useEffect(() => {
    if (hideStartTabs && activeTab === 'start') setActiveTab('overview');
  }, [hideStartTabs, activeTab]);
  const [reportSubTab, setReportSubTab] = useState('performance');
  const [hasDeliveries, setHasDeliveries] = useState(false);
  useEffect(() => {
    axios.get(`${process.env.REACT_APP_BACKEND_URL}/api/customer/deliveries/summary`, { headers: { Authorization: `Bearer ${localStorage.getItem('token') || ''}` } })
      .then((r) => setHasDeliveries(!!r.data?.has_deliveries))
      .catch(() => setHasDeliveries(false));
  }, []);
  const [showSettingsDialog, setShowSettingsDialog] = useState(false);
  const [showMasterAdmin, setShowMasterAdmin] = useState(false);
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [showGamifiedOnboarding, setShowGamifiedOnboarding] = useState(false);
  const [onboardingStatus, setOnboardingStatus] = useState(null);
  const [showInvoiceImport, setShowInvoiceImport] = useState(false);
  const [viewAudit, setViewAudit] = useState(null);
  const [expiryFilterIds, setExpiryFilterIds] = useState(null);
  const [taskFrequencyFilter, setTaskFrequencyFilter] = useState('all');

  // Fault list filters (dashboard-scoped)
  const [faultFilterMachine, setFaultFilterMachine] = useState('all');
  const [faultFilterStatus, setFaultFilterStatus] = useState('all');
  const [faultFilterSeverity, setFaultFilterSeverity] = useState('all');

  const tourRef = React.useRef(null);

  const {
    issues, setIssues, auditHistory, maintenanceTasks, refreshMaintenanceTasks, suppliers,
    allEquipment, healthScore, urgentExpiryAlerts,
    loadData, checkPaymentStatus,
  } = useDashboardData(API);

  // Iter 292 — Master admins see the Global (cross-gym) dashboard by default.
  // The "Pulse Fitness Portal" button appends ?as=operator so the operator
  // (e.g. Lee at Pulse Fitness Ltd) lands on their OWN Operations dashboard
  // without self-impersonation. The "Global Dashboard" button omits it.
  const previewAsOperator = searchParams.get('as') === 'operator';
  const showGlobal = user?.is_master_admin && !previewAsOperator;

  // Check payment status once on mount (Stripe redirect)
  React.useEffect(() => {
    const sessionId = searchParams.get('session_id');
    if (sessionId) checkPaymentStatus(sessionId, t('dashboard.payment_success'));
    // Iter 216h193 — handle deep-link query params from the "Your first wins"
    // CTA on the Start tab.
    //   ?tab=…           → switch the active tab (equipment / staffing / …)
    //   ?onboarding=1    → open the equipment OnboardingWizard immediately
    const tab = searchParams.get('tab');
    if (tab) setActiveTab(tab);
    const onboarding = searchParams.get('onboarding');
    if (onboarding === '1') setShowOnboarding(true);
    // Test/deep-link: ?settings=1 opens the Settings dialog (Sicon section reachable via testid).
    const settingsQ = searchParams.get('settings');
    if (settingsQ) setShowSettingsDialog(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- intentional: reviewed in iter 216h226-deps-walk — effect either runs once on mount or re-fires on the listed trigger deps; omitted refs are stable identities or fetcher closures that read live state at call time, so including them would re-fire without changing semantics.
  }, []);

  // Load onboarding status — drives the welcome hero visibility
  const loadOnboardingStatus = React.useCallback(async () => {
    if (user?.is_master_admin) return;
    try {
      const token = localStorage.getItem('token');
      const res = await axios.get(`${API}/onboarding/status`, { headers: { Authorization: `Bearer ${token}` } });
      setOnboardingStatus(res.data);
      // Iter 215bz — auto-open the OnboardingWizard for brand-new operator
      // accounts (no equipment yet, banner not dismissed, onboarding never
      // completed). Suppressed by `onboarding_wizard_seen:<userId>` localStorage
      // flag so closing once = never auto-shown again on this browser.
      try {
        const data = res.data || {};
        const seenKey = `onboarding_wizard_seen:${user?.id || 'anon'}`;
        const alreadySeen = localStorage.getItem(seenKey);
        const shouldShow = !alreadySeen
          && !data.dismissed
          && !data.completed_at
          && data.percent === 0
          && (data.counts?.equipment_count ?? 0) === 0;
        if (shouldShow) {
          setShowOnboarding(true);
          localStorage.setItem(seenKey, '1');
        }
      } catch (_) { /* localStorage may be unavailable */ }
    } catch { /* ignored */ }
  }, [API, user?.is_master_admin, user?.id]);

  React.useEffect(() => { loadOnboardingStatus(); }, [loadOnboardingStatus]);

  const dismissWelcomeHero = async () => {
    setOnboardingStatus(prev => prev ? { ...prev, dismissed: true } : prev);
    try {
      const token = localStorage.getItem('token');
      await axios.post(`${API}/onboarding/dismiss`, {}, { headers: { Authorization: `Bearer ${token}` } });
    } catch { /* silent */ }
  };

  const handleOnboardingComplete = (nextAction) => {
    loadOnboardingStatus();
    loadData();
    if (nextAction === 'log_fault') wf.setShowIssueDialog(true);
  };

  const wf = useIssueWorkflow({ API, i18n, t, setIssues, loadData, allEquipment, user });

  const filteredIssues = issues.filter(i => {
    if (faultFilterMachine !== 'all' && i.machine_type !== faultFilterMachine) return false;
    if (faultFilterStatus !== 'all' && i.status !== faultFilterStatus) return false;
    if (faultFilterSeverity !== 'all') {
      const legacyMap = { operational_minor: 'low', operational_fault: 'medium', out_of_order: 'critical' };
      const legacy = legacyMap[faultFilterSeverity];
      if (i.severity !== faultFilterSeverity && i.severity !== legacy) return false;
    }
    return true;
  });

  if (showMasterAdmin && (user?.is_master_admin || user?.is_pulse_admin)) {
    return (
      <Suspense fallback={<DashboardTabFallback />}>
        <MasterAdminPage onBack={() => setShowMasterAdmin(false)} />
      </Suspense>
    );
  }

  const showSuppliersTab = can(user, 'view_suppliers');
  const showReportsTab = can(user, 'view_reports');
  const showStaffingTab = can(user, 'view_staffing');

  return (
    <div
      className={`min-h-screen overflow-x-hidden ${user?.account_type !== 'pulse_pro' && user?.account_type !== 'lite' && theme === 'light' ? 'theme-gymaxis' : ''}`}
      style={{ background: 'var(--theme-bg)' }}
    >
      <Navbar
        onOpenSettings={() => setShowSettingsDialog(true)}
        onOpenMasterAdmin={() => setShowMasterAdmin(true)}
        onStartTour={() => tourRef.current?.resetTour()}
      />

      <div className="pt-24 pb-12 module-fade-in">
        <PullToRefresh
          onRefresh={async () => {
            // Iter 215d8 — user pulls down to refresh the Operations dashboard.
            await loadData();
          }}
        >
        <div className="max-w-7xl mx-auto px-4">
          {showGlobal ? (
            <div className="mb-8" data-testid="dashboard-header">
              <h1 className="text-3xl sm:text-4xl tracking-tight font-bold mb-1 pulse-font-heading leading-tight" style={{ color: 'var(--theme-text)' }} data-testid="dashboard-title">
                <span className="gx-grad-text">Global</span> Dashboard
              </h1>
              <p style={{ color: 'var(--theme-text-muted)' }} data-testid="dashboard-subtitle">Cross-gym analytics, documents & management</p>
            </div>
          ) : (
            <ModulePageHeader
              moduleName="Operations"
              tenantName={user?.company_name}
              subtitle="Equipment, faults, maintenance & compliance — your whole estate in one place."
              isPulseBranded={user?.account_type === 'pulse_pro' || user?.account_type === 'lite'}
            />
          )}

          <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
            {/* Iter 215d1 — module switcher sits *between* the header and
                sub-tabs so Pulse Fitness matches Pulse Fitness Pro's established
                visual order (title → welcome → module pills → sub-tabs). */}
            <div className="mb-4 flex justify-start" data-testid="gymaxis-module-switcher-wrap">
              <ModuleSwitcher user={user} current="operations" />
            </div>
            <DashboardTabs activeTab={activeTab} setActiveTab={setActiveTab} showSuppliers={showSuppliersTab} showReports={showReportsTab} showStaffing={showStaffingTab} hasDeliveries={hasDeliveries} t={t} />

            {/* Proactive nudges (warranty, PPM, supplier SLA drift) */}
            {!showGlobal && (
              <NudgeBanner canDismiss={can(user, 'dismiss_nudges')} />
            )}

            {/* Welcome hero (gamified onboarding) — shown for non-master-admin users who haven't dismissed or completed onboarding.
                Iter 216h249 — suppressed for trial operators whose declared primary module is NOT Operations.
                A Memberships / CRM / Marketing trial user landing on /dashboard should never see the
                Equipment / Suppliers wizard meant for gym operators. */}
            {!user?.is_master_admin && onboardingStatus && !onboardingStatus.dismissed && !onboardingStatus.stages?.live && !(user?.primary_module && user.primary_module !== 'operations') && (
              <WelcomeHero
                gymName={user?.organization_name || user?.gym_name || ''}
                status={onboardingStatus}
                onStart={() => setShowGamifiedOnboarding(true)}
                onDismiss={dismissWelcomeHero}
              />
            )}

            <TabsContent value="overview" data-testid="overview-content">
              <Suspense fallback={<DashboardTabFallback />}>
              {showGlobal ? (
                <AdminDashboardTab />
              ) : (
                <OverviewTab
                  healthScore={healthScore}
                  issues={issues}
                  auditHistory={auditHistory}
                  maintenanceTasks={maintenanceTasks}
                  urgentExpiryAlerts={urgentExpiryAlerts}
                  onLogIssue={() => wf.setShowIssueDialog(true)}
                  onNavigateTab={setActiveTab}
                  onViewExpiryAlerts={() => { setExpiryFilterIds(urgentExpiryAlerts.map(a => a.equipment_id)); setActiveTab('equipment'); }}
                  getStatusColor={getStatusColor}
                  t={t}
                />
              )}
              </Suspense>
            </TabsContent>

            {hasDeliveries && (
              <TabsContent value="deliveries" data-testid="deliveries-content">
                <CustomerDeliveriesTab />
              </TabsContent>
            )}

            {/* Iter 215d2 — Start tab mirrors Pulse Fitness Pro: guided onboarding
                surface for first-time operators. Reuses OperationsStartTab so
                both brands share one implementation. */}
            <TabsContent value="start" data-testid="start-content">
              <Suspense fallback={<DashboardTabFallback />}>
              <OperationsStartTab
                setTab={setActiveTab}
                onLogFault={() => wf.setShowIssueDialog(true)}
                onOpenEquipmentImport={() => setShowOnboarding(true)}
              />
              </Suspense>
            </TabsContent>

            {/* Iter 215d2 — Staffing tab matches Pulse Fitness Pro. StaffingConsole
                is already brand-agnostic (reads the active org) so master admins
                and operators see the right workforce data. */}
            <TabsContent value="staffing" data-testid="staffing-content">
              <Suspense fallback={<DashboardTabFallback />}>
              <StaffingConsole />
              </Suspense>
            </TabsContent>

            <TabsContent value="issues" data-testid="issues-content">
              <Suspense fallback={<DashboardTabFallback />}>
              {showGlobal ? (
                <AdminFaultsTab />
              ) : (
                <FaultsTab
                  issues={issues}
                  filteredIssues={filteredIssues}
                  faultFilterMachine={faultFilterMachine}
                  faultFilterStatus={faultFilterStatus}
                  faultFilterSeverity={faultFilterSeverity}
                  selectedIssue={wf.selectedIssue}
                  suppliers={suppliers}
                  onLogIssue={() => wf.setShowIssueDialog(true)}
                  onSelectIssue={wf.setSelectedIssue}
                  onUpdateStatus={wf.handleUpdateIssueStatus}
                  onFilterMachine={setFaultFilterMachine}
                  onFilterStatus={setFaultFilterStatus}
                  onFilterSeverity={setFaultFilterSeverity}
                  getSeverityColor={getSeverityColor}
                  getSeverityLabel={getSeverityLabel}
                  getStatusColor={getStatusColor}
                  t={t}
                />
              )}
              </Suspense>
            </TabsContent>

            <TabsContent value="maintenance" data-testid="maintenance-content">
              <Suspense fallback={<DashboardTabFallback />}>
              {showGlobal ? (
                <AdminCheckSheetsTab />
              ) : (
                <MaintenanceTab
                  maintenanceTasks={maintenanceTasks}
                  taskFrequencyFilter={taskFrequencyFilter}
                  setTaskFrequencyFilter={setTaskFrequencyFilter}
                  API={API}
                  onTasksChanged={refreshMaintenanceTasks}
                  t={t}
                />
              )}
              </Suspense>
            </TabsContent>

            <TabsContent value="gym-design" data-testid="gym-design-content">
              <Suspense fallback={<DashboardTabFallback />}>
              <GymDesignTab allEquipment={allEquipment} />
              </Suspense>
            </TabsContent>

            <TabsContent value="documents" data-testid="documents-content">
              <Suspense fallback={<DashboardTabFallback />}>
              {showGlobal ? <GlobalDocumentsTab /> : <DocumentsTab />}
              </Suspense>
            </TabsContent>

            <TabsContent value="suppliers" data-testid="suppliers-content">
              <Suspense fallback={<DashboardTabFallback />}>
              <SupplierDashboardTab />
              </Suspense>
            </TabsContent>

            <TabsContent value="equipment" data-testid="equipment-content">
              <Suspense fallback={<DashboardTabFallback />}>
              {showGlobal ? (
                <AdminEquipmentTab />
              ) : (
                <>
                  {/* Iter 216o-8 — Lifecycle Alerts have moved to the
                      CAPEX Intelligence tab (Reports → CAPEX). The
                      Equipment page is now a clean asset list, matching
                      the Pulse Fitness Operations layout. */}
                  <EquipmentInfoTab
                    expiryFilterIds={expiryFilterIds}
                    onClearExpiryFilter={() => setExpiryFilterIds(null)}
                    onOpenInvoiceImport={() => setShowInvoiceImport(true)}
                    onLogFault={(eq) => {
                      const name = (eq.name || '').trim();
                      const groupKey = name ? (name.includes(',') ? name.split(',')[0].trim() : name) : (eq.equipment_type || '').trim();
                      wf.setSelectedMachineType && wf.setSelectedMachineType(groupKey);
                      wf.setIssueForm((f) => ({
                        ...f,
                        serial_number: eq.serial_number || '',
                        machine_type: groupKey || eq.equipment_type || eq.machine_type || '',
                        supplier: eq.manufacturer || eq.supplier || f.supplier || '',
                      }));
                      wf.setShowIssueDialog(true);
                    }}
                  />
                </>
              )}
              </Suspense>
            </TabsContent>

            <Suspense fallback={null}>
            <OnboardingWizard open={showOnboarding} onClose={() => setShowOnboarding(false)} onComplete={loadData} />
            </Suspense>

            <Dialog open={showSettingsDialog} onOpenChange={setShowSettingsDialog}>
              <DialogContent
                className="border max-w-4xl max-h-[90vh] overflow-y-auto"
                style={{ background: 'var(--theme-surface)', color: 'var(--theme-text)', borderColor: 'var(--theme-border)' }}
                data-testid="settings-dialog"
              >
                <DialogHeader>
                  <DialogTitle className="text-xl" style={{ color: 'var(--theme-text)' }}>Settings</DialogTitle>
                </DialogHeader>
                <Suspense fallback={<DashboardTabFallback />}>
                <SettingsTab />
                </Suspense>
              </DialogContent>
            </Dialog>

            <TabsContent value="digest" data-testid="digest-content">
              <Suspense fallback={<DashboardTabFallback />}>
              <WeeklyDigest />
              </Suspense>
            </TabsContent>

            <TabsContent value="reports" data-testid="reports-content">
              <Suspense fallback={<DashboardTabFallback />}>
              <ReportsSection
                reportSubTab={reportSubTab}
                onSubTabChange={setReportSubTab}
                auditHistory={auditHistory}
                viewAudit={viewAudit}
                onViewAudit={setViewAudit}
                user={user}
                t={t}
              />
              </Suspense>
            </TabsContent>
          </Tabs>
        </div>
        </PullToRefresh>
      </div>

      <FaultDialogs
        showIssueDialog={wf.showIssueDialog}
        issueStep={wf.issueStep}
        issueForm={wf.issueForm}
        setIssueForm={wf.setIssueForm}
        requireReporter={wf.requireReporter}
        siteStaff={wf.siteStaff}
        reporterStaffId={wf.reporterStaffId}
        setReporterStaffId={wf.setReporterStaffId}
        allowOtherStaff={wf.allowOtherStaff}
        requireStaffPin={wf.requireStaffPin}
        reporterPin={wf.reporterPin}
        setReporterPin={wf.setReporterPin}
        reporterOther={wf.reporterOther}
        setReporterOther={wf.setReporterOther}
        selectedMachineType={wf.selectedMachineType}
        setSelectedMachineType={wf.setSelectedMachineType}
        allEquipment={allEquipment}
        issueLoading={wf.issueLoading}
        issueMedia={wf.issueMedia}
        setIssueMedia={wf.setIssueMedia}
        faultMachines={wf.faultMachines}
        submitCount={wf.submitCount}
        activeMachineIdx={wf.activeMachineIdx}
        setActiveMachineIdx={wf.setActiveMachineIdx}
        triageResult={wf.triageResult}
        setTriageResult={wf.setTriageResult}
        machineTriageResults={wf.machineTriageResults}
        resolutionNote={wf.resolutionNote}
        setResolutionNote={wf.setResolutionNote}
        selectedFixStep={wf.selectedFixStep}
        setSelectedFixStep={wf.setSelectedFixStep}
        equipmentCoverage={wf.equipmentCoverage}
        coverageLoading={wf.coverageLoading}
        existingFaultWarning={wf.existingFaultWarning}
        setExistingFaultWarning={wf.setExistingFaultWarning}
        onResetDialog={wf.resetIssueDialog}
        onIssueSubmit={wf.handleIssueSubmit}
        onAddMachine={wf.addMachineToFault}
        onRemoveMachine={wf.removeMachineFromFault}
        fetchCoverage={wf.fetchCoverage}
        onResolution={wf.handleResolution}
        onEngineerClick={wf.handleEngineerClick}
        setIssueStep={wf.setIssueStep}
        setIssues={setIssues}
        showPOPrompt={wf.showPOPrompt}
        setShowPOPrompt={wf.setShowPOPrompt}
        poForm={wf.poForm}
        setPOForm={wf.setPOForm}
        poCreating={wf.poCreating}
        onCreatePOAndLog={wf.handleCreatePOAndLog}
        onSkipPOAndLog={wf.handleSkipPOAndLog}
        showFaultSuccess={wf.showFaultSuccess}
        setShowFaultSuccess={wf.setShowFaultSuccess}
        faultSuccessType={wf.faultSuccessType}
        lastIssue={wf.lastIssue}
        showServiceDialog={wf.showServiceDialog}
        setShowServiceDialog={wf.setShowServiceDialog}
        serviceForm={wf.serviceForm}
        setServiceForm={wf.setServiceForm}
        onServiceSubmit={wf.handleServiceRequest}
        getSeverityColor={getSeverityColor}
        getSeverityLabel={getSeverityLabel}
        t={t}
        i18n={i18n}
        issues={issues}
        API={API}
        canManageOrgTemplates={can(user, 'manage_fault_templates')}
      />

      <MobileBottomNav
        activeTab={activeTab}
        setActiveTab={setActiveTab}
        onReportFault={() => wf.setShowIssueDialog(true)}
        variant="gymaxis"
      />

      {/* Bottom spacer for mobile nav */}
      <div className="h-20 md:hidden" />

      {activeTab !== 'documents' && <DocumentQA />}

      <ProductTour variant="gymaxis" ref={tourRef} />

      <GamifiedOnboarding
        open={showGamifiedOnboarding}
        onClose={() => setShowGamifiedOnboarding(false)}
        API={API}
        user={user}
        onComplete={handleOnboardingComplete}
      />

      {showInvoiceImport && (
        <Dialog open={showInvoiceImport} onOpenChange={setShowInvoiceImport}>
          <DialogContent className="max-w-5xl max-h-[90vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle className="text-xl font-semibold" style={{ fontFamily: 'Proxima Nova' }}>AI Equipment Import</DialogTitle>
            </DialogHeader>
            <Suspense fallback={<DashboardTabFallback />}>
            <InvoiceImportWizard
              onComplete={() => { setShowInvoiceImport(false); window.location.reload(); }}
              onClose={() => setShowInvoiceImport(false)}
            />
            </Suspense>
          </DialogContent>
        </Dialog>
      )}
    </div>
  );
};

export default DashboardPage;

import { useEffect, useState, useCallback, useRef } from 'react';
import { Wand2, Plus, Trash2, ChevronRight, ChevronLeft, ChevronDown, CheckCircle2, AlertTriangle, PackageCheck, Building2, UploadCloud, Sparkles, FileText, Search, X, Loader2, Brain, TrendingUp } from 'lucide-react';
import { notify } from '@/components/notifications';
import { dpApi } from './api';
import { Spinner, StatCard, input, inputTight, money } from './shared';
import { useDealerPartsNav } from './navGuard';
import PlanVsActualsPanel from './PlanVsActualsPanel';

const PRIORITY_TONE = {
  critical: 'bg-red-50 text-red-700 border-red-200',
  recommended: 'bg-emerald-50 text-emerald-700 border-emerald-200',
  optional: 'bg-blue-50 text-blue-700 border-blue-200',
  low: 'bg-slate-100 text-slate-600 border-slate-200',
  manual: 'bg-[var(--gx-brand-from)]/10 text-[var(--gx-brand-from)] border-[var(--gx-brand-from)]/20',
};

function StepDots({ step }) {
  const labels = ['Dealer & Invoice', 'Recommendation', 'Approve & Allocate'];
  return (
    <div className="flex items-center gap-2 mb-5">
      {labels.map((l, i) => (
        <div key={l} className="flex items-center gap-2">
          <div className={`w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold ${step >= i ? 'bg-[var(--gx-brand-from)] text-white' : 'bg-slate-100 text-slate-400'}`}>{i + 1}</div>
          <span className={`text-sm font-medium ${step >= i ? 'text-slate-900' : 'text-slate-400'}`}>{l}</span>
          {i < labels.length - 1 && <ChevronRight size={15} className="text-slate-300" />}
        </div>
      ))}
    </div>
  );
}

function MachinePicker({ onPick, onClose }) {
  const [q, setQ] = useState('');
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  useEffect(() => {
    if (!q.trim()) { setResults([]); return; }
    const t = setTimeout(() => {
      setLoading(true);
      dpApi.listDataMachines({ q, limit: 8 }).then((d) => setResults(d.machines || [])).finally(() => setLoading(false));
    }, 250);
    return () => clearTimeout(t);
  }, [q]);
  return (
    <div className="mt-1 mb-2 rounded-lg border border-[var(--gx-brand-from)]/40 bg-white shadow-sm p-2" data-testid="dp-wiz-machine-picker">
      <div className="flex items-center gap-2">
        <div className="relative flex-1">
          <Search size={14} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400" />
          <input autoFocus data-testid="dp-wiz-picker-search" value={q} onChange={(e) => setQ(e.target.value)}
            placeholder="Search BOM machines by ref, stock code or name…"
            className="w-full rounded-md border border-slate-200 pl-8 pr-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-[var(--gx-brand-from)]/30" />
        </div>
        <button onClick={onClose} className="text-slate-400 hover:text-slate-700"><X size={16} /></button>
      </div>
      {loading ? <div className="text-xs text-slate-400 px-2 py-2">Searching…</div> : results.length > 0 ? (
        <div className="mt-1.5 max-h-52 overflow-y-auto divide-y divide-slate-50">
          {results.map((m) => (
            <button key={m.id} data-testid={`dp-wiz-picker-result-${m.id}`} onClick={() => onPick(m)}
              className="w-full text-left px-2 py-1.5 hover:bg-slate-50 rounded-md">
              <span className="font-mono text-xs font-semibold text-slate-800">{m.top_level_ref}</span>
              <span className="text-xs text-slate-500"> · {m.component_count} components</span>
              <div className="text-xs text-slate-500 truncate">{m.description || 'No description'}</div>
            </button>
          ))}
        </div>
      ) : q.trim() ? <div className="text-xs text-slate-400 px-2 py-2">No machines found.</div> : null}
    </div>
  );
}

export default function AllocationWizardTab() {
  const [step, setStep] = useState(0);
  const [dealers, setDealers] = useState([]);
  const [dealerId, setDealerId] = useState('');
  const [recipientType, setRecipientType] = useState('dealer'); // 'dealer' | 'customer'
  const [customers, setCustomers] = useState([]);
  const [customerId, setCustomerId] = useState('');
  const [orderValue, setOrderValue] = useState('');
  const [pct, setPct] = useState('');
  const [coverYears, setCoverYears] = useState(5);
  const [lines, setLines] = useState([{ machine_ref: '', quantity: 1 }]);
  const [rec, setRec] = useState(null);
  const [busy, setBusy] = useState(false);
  const [qtyOverrides, setQtyOverrides] = useState({});
  const [aiBusy, setAiBusy] = useState(false);
  const [aiProgress, setAiProgress] = useState(0);
  const [aiInfo, setAiInfo] = useState(null);
  const [dragOver, setDragOver] = useState(false);
  const [resolving, setResolving] = useState(null);
  const [resolvingUnmatched, setResolvingUnmatched] = useState(null); // step-1 unmatched input_ref being mapped
  const [manualParts, setManualParts] = useState({}); // `${ref}||${code}` -> {part_sku, part_name, machine_model, quantity, unit_value}
  const [bomOpen, setBomOpen] = useState(null);        // machine ref whose BOM is expanded
  const [bomData, setBomData] = useState({});          // ref -> {loading, components}
  const [bomQuery, setBomQuery] = useState('');
  const [invoiceRef, setInvoiceRef] = useState('');   // Iter 282 — invoice number for the allocation log + dedupe
  const [dupInfo, setDupInfo] = useState(null);        // duplicate-invoice warning from the parser
  const [aiReview, setAiReview] = useState(null);      // parsed invoice awaiting explicit confirm before it fills the form
  const [dupAck, setDupAck] = useState(false);         // user has acknowledged a duplicate-invoice warning in the review panel
  const [dataSettings, setDataSettings] = useState(null);  // recommendation-intelligence settings (blend / trend)
  const [intelOpen, setIntelOpen] = useState(false);
  const [savingIntel, setSavingIntel] = useState(false);
  const fileRef = useRef(null);

  const loadBom = (ref) => {
    if (bomOpen === ref) { setBomOpen(null); return; }
    setBomOpen(ref); setBomQuery('');
    if (bomData[ref]?.components) return;
    setBomData((s) => ({ ...s, [ref]: { loading: true } }));
    dpApi.machineParts(ref)
      .then((d) => setBomData((s) => ({ ...s, [ref]: { loading: false, components: d.components || [] } })))
      .catch(() => setBomData((s) => ({ ...s, [ref]: { loading: false, components: [] } })));
  };

  const manualKey = (ref, code) => `${ref}||${code}`;
  const setManualQty = (ref, c, qty) => {
    const q = Math.max(0, Number(qty) || 0);
    setManualParts((s) => {
      const n = { ...s };
      const k = manualKey(ref, c.code);
      if (q <= 0) delete n[k];
      else n[k] = { part_sku: c.code, part_name: c.description, machine_model: ref, quantity: q, unit_value: c.unit_value || 0 };
      return n;
    });
  };
  const manualQtyOf = (ref, code) => manualParts[manualKey(ref, code)]?.quantity || 0;

  useEffect(() => { dpApi.listDealers().then((d) => setDealers(d.dealers || [])); }, []);
  useEffect(() => { dpApi.listRecommendCustomers().then((d) => setCustomers(d.customers || [])).catch(() => {}); }, []);
  useEffect(() => { dpApi.getDataSettings().then(setDataSettings).catch(() => {}); }, []);

  const saveIntel = async (patch) => {
    setDataSettings((s) => ({ ...(s || {}), ...patch }));
    setSavingIntel(true);
    try { const saved = await dpApi.saveDataSettings(patch); setDataSettings(saved); }
    catch { notify.error('Could not save recommendation settings'); }
    finally { setSavingIntel(false); }
  };

  // Iter 282 — report unsaved-work state so the page can warn before the
  // user navigates away mid-allocation. Step 2 is the completed screen.
  const { setDirty } = useDealerPartsNav();
  const isDirty = step === 1 || (step === 0 && (
    !!dealerId || !!customerId || !!orderValue || !!invoiceRef || !!rec || !!aiInfo || !!aiReview ||
    lines.some((l) => (l.machine_ref || '').trim())
  ));
  useEffect(() => { setDirty(isDirty); }, [isDirty, setDirty]);
  useEffect(() => () => setDirty(false), [setDirty]);

  const setLine = (i, k, v) => { const n = [...lines]; n[i][k] = v; setLines(n); };

  const pickMachine = async (i, m) => {
    const origRef = (lines[i].input_ref || lines[i].machine_ref || '').trim();
    const n = [...lines];
    n[i] = { ...n[i], machine_ref: m.top_level_ref, matched: true, description: m.description || '', input_ref: origRef };
    setLines(n);
    setResolving(null);
    notify.success(`Matched to ${m.top_level_ref}`);
    // Remember the mapping so this invoice ref auto-resolves next time.
    const differs = origRef && origRef.replace(/\s/g, '').toLowerCase() !== (m.top_level_ref || '').replace(/\s/g, '').toLowerCase();
    if (differs) {
      try {
        await dpApi.createMachineAlias({ input_ref: origRef, top_level_ref: m.top_level_ref });
        notify.success(`Remembered — “${origRef}” will map to ${m.top_level_ref} automatically next time.`);
      } catch {
        notify.error(`Matched for this order, but couldn’t save “${origRef}” for next time.`);
      }
    }
  };

  const parseInvoice = async (file) => {
    if (!file) return;
    setAiBusy(true); setAiInfo(null); setAiReview(null); setDupAck(false); setAiProgress(0);
    try {
      const res = await dpApi.aiParseInvoiceFile(file, setAiProgress);
      if (!res.available) { notify.error(res.error || 'AI could not read this invoice'); return; }
      const newLines = (res.lines || []).map((l) => ({
        machine_ref: l.top_level_ref || l.input_ref || '',
        quantity: l.quantity || 1,
        matched: l.matched,
        input_ref: l.input_ref,
        description: l.machine_description || '',
        unit_value: l.unit_value,
      }));
      setAiReview({
        lines: newLines,
        order_value: res.order_value,
        order_reference: res.order_reference,
        currency: res.currency,
        matched: res.matched_count,
        total: res.lines?.length || 0,
        note: res.note,
        machinesTotal: res.machines_total,
        machinesMatched: res.machines_matched,
        source: res.source,
        duplicate: res.duplicate_invoice ? { dealer: res.duplicate_dealer_name, at: res.duplicate_allocated_at } : null,
      });
      const machineMsg = res.machines_total != null
        ? `AI found ${res.machines_total} machines — ${res.machines_matched} matched to BOM. Review before applying.`
        : `AI read the invoice — ${res.matched_count}/${res.lines?.length || 0} machines matched. Review before applying.`;
      notify.success(machineMsg);
    } catch (e) { notify.error(e?.response?.data?.detail || 'AI parsing failed'); }
    finally { setAiBusy(false); }
  };

  const setReviewQty = (i, v) => setAiReview((r) => {
    if (!r) return r;
    const lines = [...r.lines]; lines[i] = { ...lines[i], quantity: Math.max(1, Number(v) || 1) };
    return { ...r, lines };
  });
  const removeReviewLine = (i) => setAiReview((r) => (r ? { ...r, lines: r.lines.filter((_, x) => x !== i) } : r));

  const applyAiReview = () => {
    if (!aiReview) return;
    if (aiReview.lines.length) setLines(aiReview.lines);
    if (aiReview.order_value) setOrderValue(String(aiReview.order_value));
    if (aiReview.order_reference) setInvoiceRef(aiReview.order_reference);
    if (aiReview.duplicate) {
      setDupInfo(aiReview.duplicate);
      notify.error(`Invoice ${aiReview.order_reference} has already been allocated${aiReview.duplicate.dealer ? ` to ${aiReview.duplicate.dealer}` : ''}.`);
    } else { setDupInfo(null); }
    setAiInfo({ ref: aiReview.order_reference, currency: aiReview.currency, matched: aiReview.matched,
      total: aiReview.total, note: aiReview.note, machinesTotal: aiReview.machinesTotal,
      machinesMatched: aiReview.machinesMatched, source: aiReview.source });
    setAiReview(null);
    notify.success('Applied to the form — review the machine lines below, then generate a recommendation.');
  };

  const generate = async () => {
    if (recipientType === 'dealer' && !dealerId) { notify.error('Select a dealer'); return; }
    if (recipientType === 'customer' && !customerId) { notify.error('Select a customer'); return; }
    const validLines = lines.filter((l) => l.machine_ref.trim());
    if (validLines.length === 0) { notify.error('Add at least one machine line'); return; }
    setBusy(true);
    try {
      const r = await dpApi.recommendFromInvoice({
        ...(recipientType === 'dealer' ? { dealer_id: dealerId } : { customer_id: customerId }),
        order_value: Number(orderValue) || 0,
        spare_parts_percentage: pct === '' ? undefined : Number(pct),
        cover_years: coverYears,
        lines: validLines.map((l) => ({ machine_ref: l.machine_ref, quantity: Number(l.quantity) || 1 })),
      });
      setRec(r);
      setQtyOverrides({});
      setStep(1);
    } catch (e) { notify.error(e?.response?.data?.detail || 'Failed to generate'); } finally { setBusy(false); }
  };

  const resolveUnmatched = async (inputRef, m) => {
    setResolvingUnmatched(null);
    try {
      await dpApi.createMachineAlias({ input_ref: inputRef, top_level_ref: m.top_level_ref });
      notify.success(`Remembered — “${inputRef}” maps to ${m.top_level_ref}. Updating recommendation…`);
      await generate();
    } catch (e) {
      notify.error(e?.response?.data?.detail || 'Could not save the mapping');
    }
  };

  const qtyFor = (grpIdx, itemIdx, def) => {
    const k = `${grpIdx}-${itemIdx}`;
    return qtyOverrides[k] !== undefined ? qtyOverrides[k] : def;
  };

  const selectedItems = () => {
    const out = [];
    (rec?.pack || []).forEach((grp, gi) => grp.items.forEach((it, ii) => {
      const q = Number(qtyFor(gi, ii, it.recommended_qty));
      if (q > 0) out.push({ part_sku: it.part_sku, part_name: it.part_name, machine_model: it.machine_model, quantity: q, unit_value: it.unit_value, reason: it.reason });
    }));
    Object.values(manualParts).forEach((m) => { if (m.quantity > 0) out.push({ ...m, reason: `Manually selected from ${m.machine_model} BOM` }); });
    return out;
  };

  const approve = async () => {
    const items = selectedItems();
    if (items.length === 0) { notify.error('No items to allocate'); return; }
    if (dupInfo) { notify.error('This invoice has already been allocated — change the invoice number to continue.'); return; }
    setBusy(true);
    try {
      const alloc = await dpApi.createAllocation({ ...(recipientType === 'dealer' ? { dealer_id: dealerId } : { customer_id: customerId }), items, invoice_reference: invoiceRef.trim() });
      notify.success(`Allocation created — ${items.length} parts (draft). Open the Allocations tab to submit & dispatch.`);
      setRec({ ...rec, _createdAllocId: alloc.id });
      setStep(2);
    } catch (e) {
      if (e?.response?.status === 409) {
        setDupInfo({ dealer: '', at: null });
        notify.error(e?.response?.data?.detail || 'This invoice has already been allocated.');
      } else {
        notify.error('Failed to create allocation');
      }
    } finally { setBusy(false); }
  };

  const reset = () => { setStep(0); setRec(null); setLines([{ machine_ref: '', quantity: 1 }]); setOrderValue(''); setPct(''); setCoverYears(5); setCustomerId(''); setRecipientType('dealer'); setQtyOverrides({}); setManualParts({}); setBomOpen(null); setBomData({}); setInvoiceRef(''); setDupInfo(null); setAiReview(null); setAiInfo(null); };

  const liveTotal = () => {
    let t = 0;
    (rec?.pack || []).forEach((grp, gi) => grp.items.forEach((it, ii) => { t += Number(qtyFor(gi, ii, it.recommended_qty)) * (it.unit_value || 0); }));
    Object.values(manualParts).forEach((m) => { t += m.quantity * (m.unit_value || 0); });
    return Math.round(t * 100) / 100;
  };

  const consolidatedParts = () => {
    const map = {};
    const add = (sku, name, priority, q, unit, machine) => {
      if (q <= 0) return;
      if (!map[sku]) map[sku] = { sku, name, priority: priority || 'low', qty: 0, unit: unit || 0, value: 0, machines: new Set() };
      map[sku].qty += q; map[sku].value += q * (unit || 0);
      if (machine) map[sku].machines.add(machine);
    };
    (rec?.pack || []).forEach((grp, gi) => grp.items.forEach((it, ii) => add(it.part_sku, it.part_name, it.priority, Number(qtyFor(gi, ii, it.recommended_qty)), it.unit_value, it.machine_model)));
    Object.values(manualParts).forEach((m) => add(m.part_sku, m.part_name, 'manual', m.quantity, m.unit_value, m.machine_model));
    return Object.values(map).sort((a, b) => b.value - a.value);
  };

  return (
    <div className="space-y-4" data-testid="dp-allocation-wizard-tab">
      <div className="flex items-center gap-2">
        <Wand2 size={18} className="text-[var(--gx-brand-from)]" />
        <h3 className="font-semibold text-slate-900">Dealer Allocation Wizard</h3>
        {step > 0 && <button onClick={reset} className="ml-auto text-xs text-slate-500 hover:text-slate-800">Start over</button>}
      </div>
      <StepDots step={step} />

      {step === 0 && (
        <div className="space-y-4 max-w-3xl" data-testid="dp-wiz-step0">
          <div className="rounded-xl border border-slate-200 bg-white p-4 space-y-3">
            <div className="inline-flex rounded-lg border border-slate-200 p-0.5 bg-slate-50" data-testid="dp-wiz-recipient-toggle">
              {['dealer', 'customer'].map((rt) => (
                <button key={rt} type="button" data-testid={`dp-wiz-recipient-${rt}`}
                  onClick={() => setRecipientType(rt)}
                  className={`px-3 py-1.5 text-xs font-bold rounded-md transition-colors ${recipientType === rt ? 'bg-[var(--gx-brand-from)] text-white' : 'text-slate-600 hover:text-slate-900'}`}>
                  {rt === 'dealer' ? 'Dealer' : 'Customer'}
                </button>
              ))}
            </div>
            {recipientType === 'dealer' ? (
              <label className="block">
                <span className="text-xs font-semibold text-slate-500 mb-1 flex items-center gap-1"><Building2 size={13} /> Dealer *</span>
                <select data-testid="dp-wiz-dealer" className={input} value={dealerId} onChange={(e) => setDealerId(e.target.value)}>
                  <option value="">Select dealer…</option>
                  {dealers.map((d) => <option key={d.id} value={d.id}>{d.name} · {d.country}</option>)}
                </select>
              </label>
            ) : (
              <label className="block">
                <span className="text-xs font-semibold text-slate-500 mb-1 flex items-center gap-1"><Building2 size={13} /> Customer *</span>
                <select data-testid="dp-wiz-customer" className={input} value={customerId} onChange={(e) => setCustomerId(e.target.value)}>
                  <option value="">Select customer…</option>
                  {customers.map((c) => <option key={c.id} value={c.id}>{c.name}{c.city ? ` · ${c.city}` : ''}{c.country ? ` · ${c.country}` : ''}</option>)}
                </select>
                <span className="text-[10px] text-slate-400 mt-1 block">Orders sent direct to a customer — the spare-parts % applies to their order too.</span>
              </label>
            )}
            <div className="grid grid-cols-2 gap-3">
              <label className="block"><span className="text-xs font-semibold text-slate-500 mb-1 block">Order / invoice value (£)</span>
                <input data-testid="dp-wiz-value" type="number" className={input} value={orderValue} onChange={(e) => setOrderValue(e.target.value)} placeholder="50000" /></label>
              <label className="block"><span className="text-xs font-semibold text-slate-500 mb-1 block">Spare parts % (blank = dealer/global default)</span>
                <input data-testid="dp-wiz-pct" type="number" className={input} value={pct} onChange={(e) => setPct(e.target.value)} placeholder="2.5" /></label>
            </div>
            <div>
              <span className="text-xs font-semibold text-slate-500 mb-1 block">Cover period <span className="text-slate-400 font-normal">— how many years of expected failures to pack</span></span>
              <div className="flex gap-1.5" data-testid="dp-wiz-cover-years">
                {[1, 2, 3, 4, 5].map((y) => (
                  <button key={y} type="button" data-testid={`dp-wiz-cover-${y}`} onClick={() => setCoverYears(y)}
                    className={`flex-1 py-2 rounded-lg text-sm font-semibold border transition-colors ${coverYears === y ? 'bg-[var(--gx-brand-from)] text-white border-[var(--gx-brand-from)]' : 'bg-white text-slate-600 border-slate-200 hover:border-[var(--gx-brand-from)]/40'}`}>
                    {y} {y === 1 ? 'yr' : 'yrs'}
                  </button>
                ))}
              </div>
            </div>
            <label className="block"><span className="text-xs font-semibold text-slate-500 mb-1 block">Invoice number <span className="text-slate-400 font-normal">— logged against the dealer; each invoice can only be allocated once</span></span>
              <input data-testid="dp-wiz-invoice-ref" className={`${input} font-mono ${dupInfo ? 'border-red-300 bg-red-50/50' : ''}`} value={invoiceRef}
                onChange={(e) => { setInvoiceRef(e.target.value); setDupInfo(null); }} placeholder="e.g. INV-2051 (auto-filled from the invoice)" /></label>
            {dupInfo && (
              <div className="rounded-lg bg-red-50 border border-red-200 p-3 text-xs text-red-700 flex items-start gap-2" data-testid="dp-wiz-duplicate-warning">
                <AlertTriangle size={14} className="mt-0.5 shrink-0" />
                <div><b>Invoice already used.</b> Invoice <span className="font-mono">{invoiceRef}</span> has already had parts allocated{dupInfo.dealer ? ` to ${dupInfo.dealer}` : ''}. Change the invoice number to continue — an invoice can only be allocated once.</div>
              </div>
            )}
          </div>

          <div className="rounded-xl border border-slate-200 bg-white overflow-hidden" data-testid="dp-wiz-intel-card">
