                    <td className="tabular-nums text-slate-400">{s.qty_in_transit || 0}</td>
                    <td className="text-right tabular-nums">{money((s.qty_on_hand || 0) * (s.unit_value || 0))}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
