      <div className="rounded-xl border border-slate-200 bg-white p-5" data-testid="dp-dealer-logins">
        <div className="flex items-center mb-3">
          <h3 className="text-sm font-bold text-slate-900 flex items-center gap-2"><KeyRound size={15} /> Dealer portal logins ({users.length})</h3>
          <button data-testid="dp-create-login-btn" onClick={() => { setModal(true); setTempPw(null); }} className="ml-auto text-xs font-semibold text-[var(--gx-brand-from)]">+ Create login</button>
        </div>
        {users.length === 0 ? <p className="text-sm text-slate-400">No portal logins yet — create one so this dealer can access their own store.</p> : (
          <div className="space-y-1.5">
            {users.map((u) => (
              <div key={u.id} className="flex items-center justify-between text-sm py-1 border-b border-slate-50 last:border-0">
                <span className="text-slate-700">{u.email}</span>
                <span className="text-xs text-slate-400">{u.must_change_password ? 'Awaiting first login' : 'Active'}</span>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="rounded-xl border border-slate-200 bg-white p-5" data-testid="dp-dealer-invoices">
        <h3 className="text-sm font-bold text-slate-900 mb-3 flex items-center gap-2"><FileText size={15} /> Invoices with parts allocated ({(data.invoices || []).length})</h3>
        {(data.invoices || []).length === 0 ? (
          <p className="text-sm text-slate-400">No invoices have had parts allocated yet. Each invoice can only be allocated once.</p>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead><tr className="text-left text-xs text-slate-400 border-b border-slate-100">
                <th className="py-2">Invoice #</th><th>Allocated</th><th>Parts</th><th>Status</th><th className="text-right">Value</th>
              </tr></thead>
              <tbody>
                {data.invoices.map((inv) => (
                  <tr key={inv.allocation_id} className="border-b border-slate-50" data-testid={`dp-invoice-row-${inv.invoice_reference}`}>
                    <td className="py-2 font-mono text-xs font-semibold text-slate-700">{inv.invoice_reference}</td>
                    <td className="text-xs text-slate-500">{inv.allocated_at ? String(inv.allocated_at).slice(0, 10) : '—'}</td>
                    <td className="tabular-nums text-slate-500">{inv.parts_count}</td>
                    <td><StatusBadge status={inv.status} /></td>
                    <td className="text-right tabular-nums">{money(inv.value)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      <div className="rounded-xl border border-slate-200 bg-white p-5">
        <h3 className="text-sm font-bold text-slate-900 mb-3 flex items-center gap-2"><Package size={15} /> Allocations ({data.allocations.length})</h3>
        {data.allocations.length === 0 && <p className="text-sm text-slate-400">No allocations yet.</p>}
        <div className="space-y-2">
          {data.allocations.map((a) => (
            <div key={a.id} className="flex items-center justify-between text-sm py-1.5 border-b border-slate-50 last:border-0">
              <span className="text-slate-600">{money(a.recommended_value)} · {(a.items || []).length} parts</span>
              <StatusBadge status={a.status} />
            </div>
          ))}
        </div>
      </div>

      <Modal open={modal} onClose={() => setModal(false)} title="Create dealer portal login" testid="dp-login-modal"
        footer={tempPw ? <button onClick={() => setModal(false)} className="px-4 py-2 text-sm font-semibold bg-[var(--gx-brand-from)] text-white rounded-lg">Done</button> : <>
          <button onClick={() => setModal(false)} className="px-4 py-2 text-sm text-slate-500">Cancel</button>
          <button data-testid="dp-login-save" onClick={createLogin} className="px-4 py-2 text-sm font-semibold bg-[var(--gx-brand-from)] text-white rounded-lg">Create login</button>
        </>}>
        {tempPw ? (
          <div className="space-y-2" data-testid="dp-login-temp">
            <p className="text-sm text-slate-600">Login created for <strong>{tempPw.email}</strong>. Share this temporary password securely — they'll be asked to change it on first login.</p>
            <div className="font-mono text-sm bg-slate-100 rounded-lg px-3 py-2 select-all">{tempPw.password}</div>
          </div>
        ) : (
          <>
            <Field label="Email *"><input data-testid="dp-login-email" className={input} value={uform.email} onChange={(e) => setUform({ ...uform, email: e.target.value })} placeholder="portal@dealer.com" /></Field>
            <Field label="Contact name"><input className={input} value={uform.full_name} onChange={(e) => setUform({ ...uform, full_name: e.target.value })} /></Field>
            <p className="text-xs text-slate-400">A temporary password will be generated. The dealer sees only their own store.</p>
          </>
        )}
      </Modal>
    </div>
  );
}

const CURRENCIES = ['GBP', 'EUR', 'USD', 'AUD', 'CAD', 'NZD', 'AED', 'ZAR', 'SGD', 'HKD', 'JPY', 'CHF', 'SEK', 'NOK', 'DKK', 'PLN', 'INR'];

export default function DealersTab() {
  const [dealers, setDealers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [q, setQ] = useState('');
  const [selected, setSelected] = useState(null);
  const [modal, setModal] = useState(false);
  const [companies, setCompanies] = useState([]);
  const [staff, setStaff] = useState([]);
  const [companyMode, setCompanyMode] = useState('existing'); // 'existing' | 'new'
  const emptyForm = { company_id: '', name: '', country: '', region: '', currency: 'GBP', default_percentage: '', account_manager: '' };
  const [form, setForm] = useState(emptyForm);

  const load = useCallback(() => {
    setLoading(true);
    dpApi.listDealers({ search: q }).then((d) => setDealers(d.dealers || [])).finally(() => setLoading(false));
  }, [q]);
  useEffect(() => { load(); }, [load]);

  const openAdd = () => {
    setForm(emptyForm); setCompanyMode('existing'); setModal(true);
    dpApi.listCrmCompanies().then((d) => setCompanies(d.companies || [])).catch(() => setCompanies([]));
    dpApi.listOrgStaff().then((d) => setStaff(d.staff || [])).catch(() => setStaff([]));
  };

  const onPickCompany = (v) => {
    if (v === '__new__') { setCompanyMode('new'); setForm({ ...form, company_id: '', name: '' }); return; }
    const c = companies.find((x) => x.id === v);
    setForm({ ...form, company_id: v, name: c?.name || '', country: c?.country || form.country });
  };

  const save = async () => {
    let { company_id, name } = form;
    // Create-new-company path (option 1b): create the CRM company, then link it.
    if (companyMode === 'new') {
      if (!name.trim()) { notify.error('Company name required'); return; }
      try {
        const c = await dpApi.createCrmCompany({ name: name.trim(), country: form.country });
        company_id = c.id;
      } catch { notify.error('Failed to create CRM company'); return; }
    }
    if (!name.trim()) { notify.error('Select or create a company'); return; }
    try {
      await dpApi.createDealer({
        ...form, company_id, name: name.trim(),
        default_percentage: form.default_percentage === '' ? null : Number(form.default_percentage),
      });
      notify.success('Dealer added');
      setModal(false); setForm(emptyForm);
      load();
    } catch { notify.error('Failed to save dealer'); }
  };

  if (selected) return <DealerDetail dealerId={selected} onBack={() => { setSelected(null); load(); }} />;

  return (
    <div className="space-y-4" data-testid="dp-dealers-tab">
      <div className="flex items-center gap-2">
        <div className="relative flex-1 max-w-xs">
          <Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
          <input data-testid="dp-dealer-search" value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search dealers…" className={`${input} pl-9`} />
        </div>
        <button data-testid="dp-add-dealer-btn" onClick={openAdd} className="ml-auto inline-flex items-center gap-1.5 bg-[var(--gx-brand-from)] text-white text-sm font-semibold px-3.5 py-2 rounded-lg hover:opacity-90">
          <Plus size={15} /> Add dealer
        </button>
      </div>

      {loading ? <Spinner /> : dealers.length === 0 ? (
        <div className="text-center py-16 text-slate-400 text-sm">No dealers yet. Add your first international dealer.</div>
      ) : (
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-3">
          {dealers.map((d) => (
            <button key={d.id} data-testid={`dp-dealer-card-${d.id}`} onClick={() => setSelected(d.id)} className="text-left rounded-xl border border-slate-200 bg-white p-4 hover:shadow-md hover:border-[var(--gx-brand-from)]/40 transition-all">
              <div className="flex items-center gap-2 mb-1">
                <Building2 size={16} className="text-[var(--gx-brand-from)]" />
                <span className="font-semibold text-slate-900 truncate">{d.name}</span>
              </div>
              <div className="text-xs text-slate-400">{[d.country, d.region].filter(Boolean).join(' · ') || 'No location'}</div>
              <div className="text-xs text-slate-500 mt-2">{d.default_percentage ?? '—'}% allowance · {d.currency}</div>
            </button>
          ))}
        </div>
      )}

      <Modal open={modal} onClose={() => setModal(false)} title="Add dealer" testid="dp-dealer-modal"
        footer={<>
          <button onClick={() => setModal(false)} className="px-4 py-2 text-sm text-slate-500">Cancel</button>
          <button data-testid="dp-dealer-save" onClick={save} className="px-4 py-2 text-sm font-semibold bg-[var(--gx-brand-from)] text-white rounded-lg">Save dealer</button>
        </>}>
        <Field label="Dealer (CRM company) *">
          {companyMode === 'existing' ? (
            <select data-testid="dp-dealer-company" className={input} value={form.company_id} onChange={(e) => onPickCompany(e.target.value)}>
              <option value="">Select a company…</option>
              {companies.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
              <option value="__new__">+ Set up a new company…</option>
            </select>
          ) : (
            <div className="flex gap-2">
              <input data-testid="dp-dealer-name" className={`${input} flex-1`} value={form.name} placeholder="New company name" onChange={(e) => setForm({ ...form, name: e.target.value })} />
              <button type="button" onClick={() => { setCompanyMode('existing'); setForm({ ...form, name: '', company_id: '' }); }} className="text-xs text-slate-500 hover:text-slate-800 px-2">Cancel</button>
            </div>
          )}
        </Field>
        <div className="grid grid-cols-2 gap-3">
          <Field label="Country"><input className={input} value={form.country} onChange={(e) => setForm({ ...form, country: e.target.value })} /></Field>
          <Field label="Region"><input className={input} value={form.region} onChange={(e) => setForm({ ...form, region: e.target.value })} /></Field>
        </div>
        <div className="grid grid-cols-2 gap-3">
          <Field label="Currency">
            <select data-testid="dp-dealer-currency" className={input} value={form.currency} onChange={(e) => setForm({ ...form, currency: e.target.value })}>
              {CURRENCIES.map((c) => <option key={c} value={c}>{c}</option>)}
            </select>
          </Field>
          <Field label="Spare parts %"><input type="number" step="0.1" className={input} value={form.default_percentage} onChange={(e) => setForm({ ...form, default_percentage: e.target.value })} placeholder="2.5" /></Field>
        </div>
        <Field label="Account manager (Pulse Fitness Ltd)">
          <select data-testid="dp-dealer-account-manager" className={input} value={form.account_manager} onChange={(e) => setForm({ ...form, account_manager: e.target.value })}>
            <option value="">Select account manager…</option>
            {staff.map((s) => <option key={s.id} value={s.full_name || s.email}>{s.full_name || s.email}</option>)}
          </select>
        </Field>
      </Modal>
    </div>
  );
}

import { useEffect, useState, useCallback } from 'react';
import { Check, X, ShieldCheck, GitMerge, Plus } from 'lucide-react';
import { notify } from '@/components/notifications';
import { dpApi } from './api';
import { Spinner, StatCard, Modal, Field, input, CONFIDENCE_TONE } from './shared';

function ConfBadge({ c }) {
  return <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-[11px] font-semibold border capitalize ${CONFIDENCE_TONE[c] || CONFIDENCE_TONE.none}`}>{String(c || '').replace(/_/g, ' ')}</span>;
}

export default function MatchReviewTab() {
  const [tab, setTab] = useState('pending');
  const [matches, setMatches] = useState([]);
  const [aliases, setAliases] = useState([]);
  const [loading, setLoading] = useState(true);
  const [aliasModal, setAliasModal] = useState(false);
  const [aliasForm, setAliasForm] = useState({ from_code: '', to_code: '', note: '' });

  const load = useCallback(() => {
    setLoading(true);
    Promise.all([
      tab === 'aliases' ? Promise.resolve({ matches: [] }) : dpApi.listDataMatches({ review_status: tab === 'all' ? '' : tab }),
      dpApi.listAliases(),
    ]).then(([m, a]) => { setMatches(m.matches || []); setAliases(a.aliases || []); }).finally(() => setLoading(false));
  }, [tab]);
  useEffect(() => { load(); }, [load]);

  const review = async (id, action) => {
    try { await dpApi.reviewMatch(id, action); notify.success(action === 'approve' ? 'Match approved' : 'Match rejected'); load(); }
    catch { notify.error('Failed'); }
  };
  const reviewAlias = async (id, action) => {
    try { await dpApi.reviewAlias(id, action); notify.success('Alias ' + action + 'd'); load(); }
    catch { notify.error('Failed'); }
  };
  const saveAlias = async () => {
    if (!aliasForm.from_code.trim() || !aliasForm.to_code.trim()) { notify.error('Both codes required'); return; }
    try { await dpApi.createAlias(aliasForm); notify.success('Alias submitted for approval'); setAliasModal(false); setAliasForm({ from_code: '', to_code: '', note: '' }); load(); }
    catch { notify.error('Failed'); }
  };

  const pendingAliases = aliases.filter((a) => a.status === 'pending').length;

  return (
    <div className="space-y-4" data-testid="dp-match-review-tab">
      <div className="flex items-center gap-2">
        <div className="flex gap-1 bg-slate-100 rounded-lg p-1">
          {['pending', 'approved', 'rejected', 'all', 'aliases'].map((t) => (
            <button key={t} data-testid={`dp-match-filter-${t}`} onClick={() => setTab(t)}
              className={`px-3 py-1.5 text-xs font-semibold rounded-md capitalize ${tab === t ? 'bg-white shadow-sm text-slate-900' : 'text-slate-500'}`}>
              {t}{t === 'aliases' && pendingAliases ? ` (${pendingAliases})` : ''}
            </button>
          ))}
        </div>
        {tab === 'aliases' && (
          <button data-testid="dp-add-alias-btn" onClick={() => setAliasModal(true)} className="ml-auto inline-flex items-center gap-1.5 bg-[var(--gx-brand-from)] text-white text-sm font-semibold px-3.5 py-2 rounded-lg hover:opacity-90">
            <Plus size={15} /> New alias
          </button>
        )}
      </div>

      {loading ? <Spinner /> : tab === 'aliases' ? (
        aliases.length === 0 ? <div className="text-center py-16 text-slate-400 text-sm">No aliases yet. Map superseded/old codes to current BOM codes.</div> : (
          <div className="overflow-x-auto rounded-xl border border-slate-200 bg-white">
            <table className="w-full text-sm">
              <thead><tr className="text-left text-xs text-slate-400 border-b border-slate-100 bg-slate-50/50">
                <th className="py-2.5 px-4">From (old)</th><th></th><th>To (current)</th><th>Note</th><th>Status</th><th></th>
              </tr></thead>
              <tbody>
                {aliases.map((a) => (
                  <tr key={a.id} data-testid={`dp-alias-row-${a.id}`} className="border-b border-slate-50">
                    <td className="py-2.5 px-4 font-mono text-xs text-slate-600">{a.from_code}</td>
                    <td><GitMerge size={13} className="text-slate-300" /></td>
                    <td className="font-mono text-xs text-slate-600">{a.to_code}</td>
                    <td className="text-xs text-slate-500 max-w-[220px] truncate">{a.note || '—'}</td>
                    <td><span className={`text-[11px] font-semibold px-2 py-0.5 rounded-full border ${a.status === 'approved' ? 'bg-emerald-50 text-emerald-700 border-emerald-200' : a.status === 'rejected' ? 'bg-red-50 text-red-600 border-red-200' : 'bg-amber-50 text-amber-700 border-amber-200'}`}>{a.status}</span></td>
                    <td className="text-right pr-3">
                      {a.status === 'pending' && (
                        <span className="inline-flex gap-1">
                          <button onClick={() => reviewAlias(a.id, 'approve')} className="p-1.5 rounded-md bg-emerald-50 text-emerald-600 hover:bg-emerald-100"><Check size={14} /></button>
                          <button onClick={() => reviewAlias(a.id, 'reject')} className="p-1.5 rounded-md bg-red-50 text-red-500 hover:bg-red-100"><X size={14} /></button>
                        </span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )
      ) : matches.length === 0 ? (
        <div className="text-center py-16 text-slate-400 text-sm">No {tab} matches. Run matching from Data Imports.</div>
      ) : (
        <div className="overflow-x-auto rounded-xl border border-slate-200 bg-white">
          <table className="w-full text-sm">
            <thead><tr className="text-left text-xs text-slate-400 border-b border-slate-100 bg-slate-50/50">
              <th className="py-2.5 px-4">Used part</th><th>Matched BOM component</th><th>Confidence</th><th>Machines</th><th>Status</th><th></th>
            </tr></thead>
            <tbody>
              {matches.map((m) => (
                <tr key={m.id} data-testid={`dp-match-row-${m.id}`} className="border-b border-slate-50">
                  <td className="py-2.5 px-4 max-w-[240px]"><span className="font-mono text-xs text-slate-500">{m.used_code}</span><div className="text-xs text-slate-500 truncate">{m.used_description}</div></td>
                  <td className="max-w-[240px]"><span className="font-mono text-xs text-slate-500">{m.bom_code}</span><div className="text-xs text-slate-500 truncate">{m.bom_description}</div></td>
                  <td><ConfBadge c={m.confidence} /></td>
                  <td className="text-xs text-slate-500">{(m.models || []).slice(0, 2).join(', ')}{m.models?.length > 2 ? ` +${m.models.length - 2}` : ''}</td>
                  <td>{m.approved ? <span className="inline-flex items-center gap-1 text-[11px] font-semibold text-emerald-600"><ShieldCheck size={12} /> approved</span> : <span className="text-[11px] text-amber-600 capitalize">{m.review_status}</span>}</td>
                  <td className="text-right pr-3">
                    {m.review_status === 'pending' && (
                      <span className="inline-flex gap-1">
                        <button data-testid={`dp-match-approve-${m.id}`} onClick={() => review(m.id, 'approve')} className="p-1.5 rounded-md bg-emerald-50 text-emerald-600 hover:bg-emerald-100"><Check size={14} /></button>
                        <button data-testid={`dp-match-reject-${m.id}`} onClick={() => review(m.id, 'reject')} className="p-1.5 rounded-md bg-red-50 text-red-500 hover:bg-red-100"><X size={14} /></button>
                      </span>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      <Modal open={aliasModal} onClose={() => setAliasModal(false)} title="Create part alias" testid="dp-alias-modal"
        footer={<>
          <button onClick={() => setAliasModal(false)} className="px-4 py-2 text-sm text-slate-500">Cancel</button>
          <button data-testid="dp-alias-save" onClick={saveAlias} className="px-4 py-2 text-sm font-semibold bg-[var(--gx-brand-from)] text-white rounded-lg">Submit</button>
        </>}>
        <p className="text-xs text-slate-500 mb-3">Map an old / superseded part code to the current BOM component code. Requires approval before it affects matching.</p>
        <div className="grid grid-cols-2 gap-3">
          <Field label="From (old / used code) *"><input className={`${input} font-mono`} value={aliasForm.from_code} onChange={(e) => setAliasForm({ ...aliasForm, from_code: e.target.value })} /></Field>
          <Field label="To (current BOM code) *"><input className={`${input} font-mono`} value={aliasForm.to_code} onChange={(e) => setAliasForm({ ...aliasForm, to_code: e.target.value })} /></Field>
        </div>
        <Field label="Note"><input className={input} value={aliasForm.note} onChange={(e) => setAliasForm({ ...aliasForm, note: e.target.value })} /></Field>
      </Modal>
    </div>
  );
}

import { useEffect, useState, useCallback } from 'react';
import { Plus, Trash2, Star, Search } from 'lucide-react';
import { notify } from '@/components/notifications';
import { dpApi } from './api';
import { Spinner, Modal, Field, input, money } from './shared';

const PRIORITY_TONE = {
  critical: 'bg-red-50 text-red-700 border-red-200',
  high: 'bg-amber-50 text-amber-700 border-amber-200',
  medium: 'bg-blue-50 text-blue-700 border-blue-200',
  low: 'bg-slate-100 text-slate-600 border-slate-200',
  optional: 'bg-slate-100 text-slate-500 border-slate-200',
};

export default function MostUsedTab() {
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [q, setQ] = useState('');
  const [modal, setModal] = useState(false);
  const [form, setForm] = useState({ machine_model: '', part_number: '', part_description: '', priority: 'high', recommended_dealer_stock_quantity: '', avg_usage_per_year: '', failure_frequency: '', cost: '', lead_time_days: '' });

  const load = useCallback(() => {
    setLoading(true);
    dpApi.listMostUsed(q ? { machine_model: q } : {}).then((d) => setRows(d.most_used || [])).finally(() => setLoading(false));
  }, [q]);
  useEffect(() => { load(); }, [load]);

  const save = async () => {
    if (!form.machine_model.trim() || !form.part_number.trim()) { notify.error('Model and part number required'); return; }
    try {
      await dpApi.upsertMostUsed({
        ...form,
        recommended_dealer_stock_quantity: form.recommended_dealer_stock_quantity === '' ? null : Number(form.recommended_dealer_stock_quantity),
        avg_usage_per_year: Number(form.avg_usage_per_year) || 0,
        failure_frequency: Number(form.failure_frequency) || 0,
        cost: Number(form.cost) || 0,
        lead_time_days: Number(form.lead_time_days) || 0,
      });
      notify.success('Most-used part saved');
      setModal(false);
      setForm({ machine_model: '', part_number: '', part_description: '', priority: 'high', recommended_dealer_stock_quantity: '', avg_usage_per_year: '', failure_frequency: '', cost: '', lead_time_days: '' });
      load();
    } catch { notify.error('Failed to save'); }
  };

  const remove = async (id) => { await dpApi.deleteMostUsed(id); notify.success('Removed'); load(); };

  return (
    <div className="space-y-4" data-testid="dp-most-used-tab">
