              <Field label="Bank holiday region"><select value={editing.bank_holiday_region || ''} data-testid="attendance-profile-region"
                onChange={(e) => setEditing({ ...editing, bank_holiday_region: e.target.value })} className="w-full rounded-lg border border-slate-300 dark:border-slate-600 px-3 py-2 text-sm">
                {(data.regions || []).map((r) => <option key={r} value={r}>{REGION_LABEL[r] || r}</option>)}
              </select></Field>
              <Field label="Time entry method"><select value={editing.time_entry_method || ''} data-testid="attendance-profile-time-entry"
                onChange={(e) => setEditing({ ...editing, time_entry_method: e.target.value })} className="w-full rounded-lg border border-slate-300 dark:border-slate-600 px-3 py-2 text-sm">
                {TIME_ENTRY.map(([k, l]) => <option key={k} value={k}>{l}</option>)}
              </select></Field>
              <Field label="Overtime rule"><select value={editing.overtime_rule || ''}
                onChange={(e) => setEditing({ ...editing, overtime_rule: e.target.value })} className="w-full rounded-lg border border-slate-300 dark:border-slate-600 px-3 py-2 text-sm">
                {OT_RULES.map(([k, l]) => <option key={k} value={k}>{l}</option>)}
              </select></Field>
              <Field label="Employment status"><select value={editing.employment_status || 'active'}
                onChange={(e) => setEditing({ ...editing, employment_status: e.target.value })} className="w-full rounded-lg border border-slate-300 dark:border-slate-600 px-3 py-2 text-sm">
                {['active', 'probation', 'leaver', 'on_leave'].map((s) => <option key={s} value={s}>{s}</option>)}
              </select></Field>
              <label className="col-span-2 flex items-center gap-2 text-xs font-semibold text-slate-600 dark:text-slate-300">
                <input type="checkbox" checked={!!editing.overtime_eligibility} data-testid="attendance-profile-ot-eligible"
                  onChange={(e) => setEditing({ ...editing, overtime_eligibility: e.target.checked })} /> Eligible for overtime</label>
            </div>
            <div className="flex justify-end gap-2 mt-4">
              <button onClick={() => setEditing(null)} className="px-3 py-2 rounded-lg text-sm font-semibold text-slate-600 dark:text-slate-300">Cancel</button>
              <button onClick={save} data-testid="attendance-profile-save" className="inline-flex items-center gap-1.5 px-4 py-2 rounded-lg bg-cyan-600 text-white text-sm font-semibold"><Save size={14} /> Save profile</button>
            </div>
          </div>
        </div>, document.body)}
    </div>
  );
}

function Field({ label, children }) {
  return (
    <label className="block text-xs font-semibold text-slate-600 dark:text-slate-300">
      <span className="block mb-1">{label}</span>{children}
    </label>
  );
}

/* ─────────────── Migration / Import (§74–§76) ─────────────── */
function MigrationView({ headers }) {
  return (
    <div className="space-y-4" data-testid="attendance-import">
      <p className="text-sm text-slate-500 dark:text-slate-400">Import your legacy spreadsheets into the single source of truth. Preview first — nothing is written until you commit, and existing employees are matched, never duplicated.</p>
      <div className="grid md:grid-cols-2 gap-4">
        <ImportCard headers={headers} kind="attendance"
          title="Attendance Request" hint="The year grid of IN / HOL / BH / SICK / COMP / OFF." />
        <ImportCard headers={headers} kind="timesheet"
          title="Timesheets" hint="One employee's month sheets (start/finish/break/PT/classes)." />
      </div>
    </div>
  );
}

function ImportCard({ headers, kind, title, hint }) {
  const [file, setFile] = useState(null);
  const [preview, setPreview] = useState(null);
  const [result, setResult] = useState(null);
  const [busy, setBusy] = useState('');
  const [err, setErr] = useState('');
  const base = kind === 'attendance' ? 'attendance' : 'timesheets';

  const call = async (action) => {
    if (!file) { setErr('Choose a file first.'); return; }
    setBusy(action); setErr('');
    const fd = new FormData(); fd.append('file', file);
    try {
      const r = await axios.post(`${API}/migration/${base}/${action}`, fd,
        { headers: { ...headers, 'Content-Type': 'multipart/form-data' } });
      if (action === 'preview') { setPreview(r.data); setResult(null); }
      else { setResult(r.data); }
    } catch (e) { setErr(e?.response?.data?.detail || 'Failed'); }
    setBusy('');
  };

  return (
    <div className="rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 p-4" data-testid={`import-card-${kind}`}>
      <div className="flex items-center gap-2 mb-1"><FileSpreadsheet size={16} className="text-cyan-600" /><h3 className="font-bold text-slate-900 dark:text-slate-100">{title}</h3></div>
      <p className="text-xs text-slate-500 dark:text-slate-400 mb-3">{hint}</p>
      <input type="file" accept=".xlsx" onChange={(e) => { setFile(e.target.files[0]); setPreview(null); setResult(null); }} data-testid={`import-file-${kind}`}
        className="block w-full text-xs text-slate-600 dark:text-slate-300 file:mr-3 file:py-1.5 file:px-3 file:rounded-lg file:border-0 file:bg-slate-100 file:text-slate-700 dark:text-slate-200 file:font-semibold" />
      <div className="mt-3 flex gap-2">
        <button onClick={() => call('preview')} disabled={busy} data-testid={`import-preview-${kind}`}
          className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg border border-slate-300 dark:border-slate-600 text-slate-700 dark:text-slate-200 text-xs font-semibold">
          {busy === 'preview' ? <Loader2 size={13} className="animate-spin" /> : <Upload size={13} />} Preview</button>
        {preview && <button onClick={() => call('commit')} disabled={busy} data-testid={`import-commit-${kind}`}
          className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg bg-cyan-600 text-white text-xs font-semibold">
          {busy === 'commit' ? <Loader2 size={13} className="animate-spin" /> : <Check size={13} />} Commit import</button>}
      </div>
      {err && <div className="mt-2 text-xs text-rose-600" data-testid={`import-error-${kind}`}>{err}</div>}

      {preview && (
        <div className="mt-3 rounded-lg bg-slate-50 dark:bg-slate-800 p-3 text-xs" data-testid={`import-preview-result-${kind}`}>
          {kind === 'attendance' ? (
            <>
              <div className="font-semibold text-slate-700 dark:text-slate-200">{preview.rows_parsed} rows · {preview.date_range?.from} → {preview.date_range?.to}</div>
              <div className="mt-1 text-emerald-700">Matched employees: {preview.employees_matched.length}</div>
              {preview.employees_unmatched.length > 0 && <div className="text-amber-700">Unmatched (will be skipped): {preview.employees_unmatched.join(', ')}</div>}
              <div className="mt-1 flex gap-2 flex-wrap">{Object.entries(preview.by_status).map(([k, v]) => <span key={k} className="px-1.5 py-0.5 rounded bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700">{k}: {v}</span>)}</div>
            </>
          ) : (
            <>
              <div className="font-semibold text-slate-700 dark:text-slate-200">{preview.employee_name || 'No name found'} {preview.employee_matched ? <span className="text-emerald-600">✓ matched</span> : <span className="text-amber-600">not matched</span>}</div>
              <div className="mt-1">{preview.days_parsed} days · {preview.totals?.hours}h · PT {preview.totals?.pt} · Classes {preview.totals?.classes}</div>
              {preview.conflicts?.length > 0 && (
                <div className="mt-2 text-rose-600 font-semibold" data-testid="import-conflicts">⚠ {preview.conflicts.length} conflict(s) — review required:</div>
              )}
              {(preview.conflicts || []).slice(0, 5).map((c) => (
                <div key={c.date} className="text-rose-600">{c.date}: attendance {c.attendance} vs timesheet {c.timesheet_hours}h</div>
              ))}
            </>
          )}
        </div>
      )}

      {result && (
        <div className="mt-2 rounded-lg bg-emerald-50 border border-emerald-200 p-3 text-xs text-emerald-800" data-testid={`import-commit-result-${kind}`}>
          {kind === 'attendance'
            ? <>Imported {result.written} records. Skipped {result.skipped}{result.unmatched?.length ? ` · unmatched: ${result.unmatched.join(', ')}` : ''}.</>
            : <>Imported {result.written} days for {result.employee}{result.skipped_conflicts ? ` · ${result.skipped_conflicts} conflict day(s) skipped` : ''}.</>}
        </div>
      )}
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';
import axios from 'axios';
import {
  ShieldCheck, IdCard, Receipt, RefreshCw, Loader2, AlertTriangle,
  CheckCircle2, Clock, HelpCircle,
} from 'lucide-react';

const API = `${process.env.REACT_APP_BACKEND_URL}/api`;

const PILL = {
  expired:   { cls: 'bg-rose-100 text-rose-700 border-rose-200',       label: 'Expired' },
  expiring:  { cls: 'bg-amber-100 text-amber-700 border-amber-200',    label: 'Expiring' },
  missing:   { cls: 'bg-slate-100 text-slate-600 border-slate-200',    label: 'Not on file' },
  ok:        { cls: 'bg-emerald-100 text-emerald-700 border-emerald-200', label: 'Valid' },
  attention: { cls: 'bg-rose-100 text-rose-700 border-rose-200',       label: 'Check needed' },
};

function StatusPill({ status, children, testid }) {
  const p = PILL[status] || PILL.missing;
  return (
    <span data-testid={testid}
      className={`inline-flex items-center gap-1 rounded-full border px-2.5 py-0.5 text-xs font-semibold ${p.cls}`}>
      {children || p.label}
    </span>
  );
}

function SummaryCard({ testid, icon: Icon, tint, title, urgent, urgentLabel, breakdown }) {
  const clear = urgent === 0;
  return (
    <div data-testid={testid}
      className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm">
      <div className="flex items-start justify-between">
        <div className="flex h-11 w-11 items-center justify-center rounded-xl"
          style={{ background: `${tint}1f`, color: tint }}>
          <Icon size={22} />
        </div>
        <span className={`inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-xs font-bold ${clear ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>
          {clear ? <CheckCircle2 size={13} /> : <AlertTriangle size={13} />}
          {clear ? 'All clear' : `${urgent} ${urgentLabel}`}
        </span>
      </div>
      <h3 className="mt-4 text-base font-bold text-slate-800">{title}</h3>
      <div className="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-sm text-slate-500">
        {breakdown.map((b) => (
          <span key={b.label}><span className="font-bold text-slate-700">{b.value}</span> {b.label}</span>
        ))}
      </div>
    </div>
  );
}

function SectionCard({ title, icon: Icon, count, children }) {
  return (
    <div className="rounded-2xl border border-slate-200 bg-white shadow-sm">
      <div className="flex items-center gap-2 border-b border-slate-100 px-5 py-3.5">
        <Icon size={18} className="text-slate-400" />
        <h3 className="text-sm font-bold uppercase tracking-wide text-slate-700">{title}</h3>
        <span className="ml-auto text-xs font-semibold text-slate-400">{count} to review</span>
      </div>
      <div className="divide-y divide-slate-100">{children}</div>
    </div>
  );
}

function EmptyRow({ text }) {
  return (
    <div className="flex items-center gap-2 px-5 py-6 text-sm text-slate-400">
      <CheckCircle2 size={16} className="text-emerald-500" /> {text}
    </div>
  );
}

export default function ComplianceTab({ headers }) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const load = useCallback(async () => {
    setLoading(true); setError(null);
    try {
      const { data } = await axios.get(`${API}/staffing/compliance`, { headers });
      setData(data);
    } catch (e) {
      setError(e?.response?.data?.detail || 'Could not load compliance data.');
    } finally {
      setLoading(false);
    }
  }, [headers]);

  useEffect(() => { load(); }, [load]);

  if (loading && !data) {
    return (
      <div className="flex items-center justify-center py-24 text-slate-400" data-testid="compliance-loading">
        <Loader2 className="animate-spin" size={22} />
      </div>
    );
  }
  if (error) {
    return (
      <div className="rounded-2xl border border-rose-200 bg-rose-50 p-6 text-rose-700" data-testid="compliance-error">
        {error} <button onClick={load} className="ml-2 underline">Retry</button>
      </div>
    );
  }

  const s = data.summary;
  const dbsUrgent = s.dbs.expired + s.dbs.expiring + s.dbs.missing;
  const rtwUrgent = s.right_to_work.attention + s.right_to_work.missing;
  const dbsNeed = data.dbs.filter((r) => r.status !== 'ok');
  const rtwNeed = data.right_to_work.filter((r) => r.status !== 'ok');

  return (
    <div className="space-y-6" data-testid="compliance-tab">
      <div className="flex items-center justify-between">
        <div>
          <p className="text-sm text-slate-500">
            DBS certificates, Right-to-Work checks and outstanding vehicle fines across {s.staff_count} staff.
          </p>
        </div>
        <button onClick={load} data-testid="compliance-refresh"
          className="inline-flex items-center gap-1.5 rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm font-semibold text-slate-600 hover:bg-slate-50">
          {loading ? <Loader2 size={15} className="animate-spin" /> : <RefreshCw size={15} />} Refresh
        </button>
      </div>

      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
        <SummaryCard testid="compliance-card-dbs" icon={IdCard} tint="#0091ca"
          title="Enhanced DBS" urgent={dbsUrgent} urgentLabel="need action"
          breakdown={[
            { label: 'valid', value: s.dbs.ok },
            { label: 'expiring', value: s.dbs.expiring },
            { label: 'expired', value: s.dbs.expired },
            { label: 'not on file', value: s.dbs.missing },
          ]} />
        <SummaryCard testid="compliance-card-rtw" icon={ShieldCheck} tint="#0091ca"
          title="Right to Work" urgent={rtwUrgent} urgentLabel="need action"
          breakdown={[
            { label: 'verified', value: s.right_to_work.ok },
            { label: 'to check', value: s.right_to_work.attention },
            { label: 'not on file', value: s.right_to_work.missing },
          ]} />
        <SummaryCard testid="compliance-card-fines" icon={Receipt} tint="#e11d48"
          title="Outstanding Fines" urgent={s.fines.unpaid_count} urgentLabel="unpaid"
          breakdown={[
            { label: `unpaid (£${s.fines.unpaid_total.toFixed(2)})`, value: s.fines.unpaid_count },
            { label: '14+ days overdue', value: s.fines.overdue_count },
          ]} />
      </div>

      <SectionCard title="DBS — needs attention" icon={IdCard} count={dbsNeed.length}>
        {dbsNeed.length === 0 ? <EmptyRow text="Every DBS certificate on file is valid." /> :
          dbsNeed.map((r) => (
            <div key={r.staff_id} data-testid="compliance-dbs-row"
              className="flex items-center justify-between gap-3 px-5 py-3">
              <div className="min-w-0">
                <div className="truncate font-semibold text-slate-800">{r.name}</div>
                <div className="text-xs text-slate-400">
                  {r.expiry_date ? `Expires ${r.expiry_date}` : 'No DBS on file'}
                  {typeof r.days === 'number' && r.status === 'expiring' && ` · in ${r.days} day${r.days === 1 ? '' : 's'}`}
                  {typeof r.days === 'number' && r.status === 'expired' && ` · ${Math.abs(r.days)} day${Math.abs(r.days) === 1 ? '' : 's'} ago`}
                </div>
              </div>
              <StatusPill status={r.status} testid="compliance-dbs-status">
                {r.status === 'expiring' && <Clock size={12} />}
                {r.status === 'expired' && <AlertTriangle size={12} />}
                {r.status === 'missing' && <HelpCircle size={12} />}
                {PILL[r.status]?.label}
              </StatusPill>
            </div>
          ))}
      </SectionCard>

      <SectionCard title="Right to Work — needs attention" icon={ShieldCheck} count={rtwNeed.length}>
        {rtwNeed.length === 0 ? <EmptyRow text="Every Right-to-Work check is verified." /> :
          rtwNeed.map((r) => (
            <div key={r.staff_id} data-testid="compliance-rtw-row"
              className="flex items-center justify-between gap-3 px-5 py-3">
              <div className="min-w-0">
                <div className="truncate font-semibold text-slate-800">{r.name}</div>
                <div className="text-xs text-slate-400">{r.raw_status ? `Status: ${r.raw_status}` : 'No status recorded'}</div>
              </div>
              <StatusPill status={r.status} testid="compliance-rtw-status" />
            </div>
          ))}
      </SectionCard>

      <SectionCard title="Outstanding vehicle fines" icon={Receipt} count={data.fines.length}>
        {data.fines.length === 0 ? <EmptyRow text="No unpaid fines across the fleet." /> :
          data.fines.map((f, i) => (
            <div key={`${f.vehicle_id}-${i}`} data-testid="compliance-fine-row"
              className="flex items-center justify-between gap-3 px-5 py-3">
              <div className="min-w-0">
                <div className="truncate font-semibold text-slate-800">
                  {f.reg_no} <span className="font-normal text-slate-400">{f.vehicle ? `· ${f.vehicle}` : ''}</span>
                </div>
                <div className="text-xs text-slate-400">
                  {f.kind || 'Fine'}{f.date ? ` · ${f.date}` : ''}
                  {typeof f.age_days === 'number' && ` · ${f.age_days} day${f.age_days === 1 ? '' : 's'} outstanding`}
                </div>
              </div>
              <div className="flex items-center gap-2">
                <span className="font-bold text-slate-800">£{f.value.toFixed(2)}</span>
                {f.overdue && (
                  <span className="inline-flex items-center gap-1 rounded-full border border-rose-200 bg-rose-100 px-2.5 py-0.5 text-xs font-semibold text-rose-700">
                    <AlertTriangle size={12} /> Overdue
                  </span>
                )}
              </div>
            </div>
          ))}
      </SectionCard>
    </div>
  );
}

/**
 * CrashPacksManager — Operations > Staffing > Vehicles > Crash Packs.
 * Lists submitted crash packs and opens a clean, printable A4 incident report
 * assembling every captured field + photos. Managers can also edit the
 * per-organisation insurance/broker details shown to drivers.
 */
import { useCallback, useEffect, useState } from 'react';
import axios from 'axios';
import { Loader2, ShieldAlert, Printer, X, Settings, Car, FileDown, MapPin } from 'lucide-react';

const API = `${process.env.REACT_APP_BACKEND_URL}/api`;
const jwt = () => (typeof window !== 'undefined' ? localStorage.getItem('token') : '');
const fmt = (s) => (s ? new Date(s).toLocaleString('en-GB', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '—');
const img = (fid) => `${API}/vehicle-checks/photo/${fid}?auth=${jwt()}`;

async function downloadPdf(id, headers, label) {
  const r = await axios.get(`${API}/crash-packs/${id}/pdf`, { headers, responseType: 'blob' });
  const url = URL.createObjectURL(r.data);
  const a = document.createElement('a');
  a.href = url; a.download = `${label || 'Crash Pack'}.pdf`;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

export default function CrashPacksManager({ headers }) {
  const [packs, setPacks] = useState(null);
  const [openId, setOpenId] = useState(null);
  const [settings, setSettings] = useState(null);

  const load = useCallback(() => {
    axios.get(`${API}/crash-packs`, { headers }).then((r) => setPacks(r.data.packs || [])).catch(() => setPacks([]));
  }, [headers]);
  useEffect(() => { load(); }, [load]);

  if (!packs) return <div className="p-6"><Loader2 className="animate-spin" style={{ color: 'var(--color-brand-cyan)' }} /></div>;

  return (
    <div className="space-y-3" data-testid="manager-crash-packs-view">
      <div className="flex items-center justify-between gap-2">
        <h3 className="font-bold" style={{ color: 'var(--theme-text)' }}>Crash Packs</h3>
        <button onClick={() => setSettings(true)} data-testid="crash-insurance-settings-btn"
          className="inline-flex items-center gap-1 text-xs font-semibold rounded-full px-3 py-1.5 border" style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }}><Settings size={13} /> Insurance details</button>
      </div>
      {packs.length === 0 ? (
        <div className="rounded-xl border p-10 text-center" style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text-muted)' }} data-testid="crash-packs-empty">
          <ShieldAlert size={28} className="mx-auto mb-2 opacity-40" /><p className="text-sm font-semibold">No crash packs submitted</p>
          <p className="text-xs mt-1">When a driver reports a crash from their Staff Portal, it appears here to review and print.</p>
        </div>
      ) : (
        <div className="rounded-xl border overflow-hidden" style={{ borderColor: 'var(--theme-border)' }}>
          <table className="w-full text-sm">
            <thead><tr style={{ background: 'var(--theme-bg)' }}>
              {['Driver', 'Vehicle', 'Submitted', ''].map((h) => <th key={h} className="text-left px-4 py-2.5 text-[11px] font-bold uppercase tracking-wide" style={{ color: 'var(--theme-text-muted)' }}>{h}</th>)}
            </tr></thead>
            <tbody>
              {packs.map((p) => (
                <tr key={p.id} className="border-t" style={{ borderColor: 'var(--theme-border)' }} data-testid={`crash-pack-row-${p.id}`}>
                  <td className="px-4 py-3 font-semibold" style={{ color: 'var(--theme-text)' }}>{p.reporter_name}</td>
                  <td className="px-4 py-3" style={{ color: 'var(--theme-text)' }}><span className="font-mono font-bold uppercase">{p.reg_no}</span> <span style={{ color: 'var(--theme-text-muted)' }}>{p.make_model}</span></td>
                  <td className="px-4 py-3" style={{ color: 'var(--theme-text-muted)' }}>{fmt(p.submitted_at)}</td>
                  <td className="px-4 py-3 text-right whitespace-nowrap">
                    <button onClick={() => downloadPdf(p.id, headers, `Crash Pack - ${p.reporter_name} - ${p.reg_no}`)} data-testid={`crash-pack-pdf-${p.id}`} className="text-xs font-semibold px-2.5 py-1.5 rounded-lg border mr-2" style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }} title="Download PDF"><FileDown size={13} className="inline" /> PDF</button>
                    <button onClick={() => setOpenId(p.id)} data-testid={`crash-pack-open-${p.id}`} className="text-xs font-bold px-3 py-1.5 rounded-lg" style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-ink)' }}>View / Print</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
