}
const RTW_STATUSES = ['', 'verified', 'pending', 'expired'];
const DOC_KINDS = ['contract', 'id', 'onboarding', 'training', 'policy', 'other'];
const SEVERITIES = ['informal', 'verbal', 'written', 'final', 'suspension', 'dismissal'];
const SEVERITY_TINT = {
  informal: '#9A9FA1',
  verbal: '#10B981',
  written: '#F59E0B',
  final: '#EF4444',
