// ─────────────────────── Job Roles manager ───────────────────────
function JobRolesModal({ headers, onClose, onChanged }) {
  const { t } = useTranslation();
  const [defaults, setDefaults] = useState([]);
  const [custom, setCustom] = useState([]);
  const [loading, setLoading] = useState(true);
  const [adding, setAdding] = useState('');
  const [editing, setEditing] = useState(null); // { role, value }
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const { data } = await axios.get(`${API}/staffing/roles`, { headers });
      setDefaults(data?.platform_defaults || []);
      setCustom(data?.custom || []);
    } catch { /* noop */ }
    setLoading(false);
  }, [headers]);
  useEffect(() => { load(); }, [load]);

  const refresh = async () => { await load(); onChanged?.(); };

  const addRole = async () => {
    const name = adding.trim();
    if (!name) return;
    setBusy(true); setError('');
    try {
      await axios.post(`${API}/staffing/roles`, { role: name }, { headers });
      setAdding('');
      await refresh();
    } catch (err) { setError(err.response?.data?.detail || t('staffing.hr_could_not_add_role', 'Could not add role')); }
    setBusy(false);
  };

  const saveRename = async () => {
    if (!editing) return;
    const next = (editing.value || '').trim();
    if (!next || next === editing.role) { setEditing(null); return; }
    setBusy(true); setError('');
    try {
      await axios.put(`${API}/staffing/roles/${encodeURIComponent(editing.role)}`, { new_name: next }, { headers });
      setEditing(null);
      await refresh();
    } catch (err) { setError(err.response?.data?.detail || t('staffing.hr_could_not_rename', 'Could not rename role')); }
    setBusy(false);
  };

  const removeRole = async (role) => {
    if (!window.confirm(`${t('staffing.hr_delete_role_q', 'Delete the')} "${humanizeRole(role)}" ${t('staffing.hr_delete_role_q2', 'role? Staff already assigned to it keep the label.')}`)) return;
    setBusy(true); setError('');
    try {
      await axios.delete(`${API}/staffing/roles/${encodeURIComponent(role)}`, { headers });
      await refresh();
    } catch (err) { setError(err.response?.data?.detail || t('staffing.hr_could_not_delete_role', 'Could not delete role')); }
    setBusy(false);
  };

  return createPortal((
    <div className="fixed inset-0 z-[300] flex items-center justify-center p-4" style={{ background: 'rgba(0,0,0,0.45)' }} data-testid="job-roles-modal">
      <div className="w-full max-w-md rounded-2xl border shadow-xl flex flex-col max-h-[85vh]"
        style={{ background: 'var(--theme-surface)', borderColor: 'var(--theme-border)' }}>
        <div className="flex items-center justify-between p-4 border-b" style={{ borderColor: 'var(--theme-border)' }}>
          <div className="inline-flex items-center gap-2">
            <Briefcase size={16} style={{ color: 'var(--color-brand-cyan)' }} />
            <h3 className="text-sm font-bold" style={{ color: 'var(--theme-text)' }}>{t('staffing.hr_job_roles', 'Job roles')}</h3>
          </div>
          <button type="button" onClick={onClose} data-testid="job-roles-close" style={{ color: 'var(--theme-text-muted)' }}><X size={16} /></button>
        </div>

        <div className="p-4 space-y-4 overflow-y-auto">
          {error && (
            <p className="text-xs px-2 py-1 rounded-md" style={{ background: 'rgba(239,68,68,0.12)', color: '#EF4444' }} data-testid="job-roles-error">{error}</p>
          )}

          <div className="flex flex-col gap-1">
            <span className="text-[10px] font-bold uppercase tracking-wider" style={{ color: 'var(--theme-text-muted)' }}>{t('staffing.hr_add_a_role', 'Add a role')}</span>
            <div className="flex gap-1.5">
              <input
                value={adding}
                onChange={(e) => setAdding(e.target.value)}
                onKeyDown={(e) => { if (e.key === 'Enter') addRole(); }}
                placeholder={t('staffing.hr_role_pm_ph', 'e.g. Project Manager')}
                maxLength={60}
                className="flex-1 h-9 rounded-md bg-transparent border px-2 text-sm"
                style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }}
                data-testid="job-roles-add-input"
              />
              <button type="button" onClick={addRole} disabled={busy || !adding.trim()}
                className="h-9 px-3 rounded-md text-xs font-bold inline-flex items-center gap-1 disabled:opacity-50"
                style={{ background: 'var(--color-brand-cyan)', color: '#1B1C1D' }} data-testid="job-roles-add-btn">
                <Plus size={13} /> {t('staffing.hr_add', 'Add')}
              </button>
            </div>
          </div>

          <div className="flex flex-col gap-1">
            <span className="text-[10px] font-bold uppercase tracking-wider" style={{ color: 'var(--theme-text-muted)' }}>{t('staffing.hr_custom_roles', 'Your custom roles')}</span>
            {loading ? (
              <p className="text-xs inline-flex items-center gap-1.5" style={{ color: 'var(--theme-text-muted)' }}><Loader2 size={12} className="animate-spin" /> {t('staffing.hr_loading', 'Loading…')}</p>
            ) : custom.length === 0 ? (
              <p className="text-xs" style={{ color: 'var(--theme-text-muted)' }}>{t('staffing.hr_no_custom_roles', 'No custom roles yet. The defaults below cover most companies.')}</p>
            ) : (
              <div className="rounded-lg border divide-y" style={{ borderColor: 'var(--theme-border)' }}>
                {custom.map((r) => (
                  <div key={r} className="flex items-center gap-2 px-2.5 py-2" data-testid={`job-roles-custom-${r}`}>
                    {editing?.role === r ? (
                      <>
                        <input autoFocus value={editing.value} maxLength={60}
                          onChange={(e) => setEditing({ role: r, value: e.target.value })}
                          onKeyDown={(e) => { if (e.key === 'Enter') saveRename(); if (e.key === 'Escape') setEditing(null); }}
                          className="flex-1 h-8 rounded-md bg-transparent border px-2 text-sm"
                          style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }}
                          data-testid="job-roles-rename-input" />
                        <button type="button" onClick={saveRename} disabled={busy} style={{ color: 'var(--color-brand-cyan)' }} data-testid="job-roles-rename-save"><Check size={15} /></button>
                        <button type="button" onClick={() => setEditing(null)} style={{ color: 'var(--theme-text-muted)' }}><X size={15} /></button>
                      </>
                    ) : (
                      <>
                        <span className="flex-1 text-sm" style={{ color: 'var(--theme-text)' }}>{humanizeRole(r)}</span>
                        <button type="button" onClick={() => setEditing({ role: r, value: r })} title={t('staffing.hr_rename', 'Rename')} style={{ color: 'var(--theme-text-muted)' }} data-testid={`job-roles-rename-${r}`}><Pencil size={14} /></button>
                        <button type="button" onClick={() => removeRole(r)} title={t('staffing.hr_delete', 'Delete')} style={{ color: '#EF4444' }} data-testid={`job-roles-delete-${r}`}><Trash2 size={14} /></button>
                      </>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>

          <div className="flex flex-col gap-1">
            <span className="text-[10px] font-bold uppercase tracking-wider" style={{ color: 'var(--theme-text-muted)' }}>{t('staffing.hr_builtin_roles', 'Built-in roles')}</span>
            <div className="flex flex-wrap gap-1.5">
              {defaults.map((r) => (
                <button
                  key={r}
                  type="button"
                  onClick={() => setAdding(humanizeRole(r))}
                  title={t('staffing.hr_use_role_tip', 'Click to use this role name')}
                  className="text-[11px] px-2 py-1 rounded-full border transition-colors cursor-pointer hover:border-[var(--color-brand-cyan)] hover:text-[var(--color-brand-cyan)]"
                  style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text-muted)' }}
                  data-testid={`job-roles-builtin-${r}`}
                >{humanizeRole(r)}</button>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  ), document.body);
}


// ─────────────────────── Hub ─────────────────────────────────────
function DetailChangeRequestsPanel({ headers, isManager }) {
  const [reqs, setReqs] = useState([]);
  const [busy, setBusy] = useState(null);
  const load = useCallback(() => {
    axios.get(`${API}/staffing/detail-change-requests?status=pending`, { headers })
      .then((r) => setReqs(r.data?.requests || [])).catch(() => setReqs([]));
  }, [headers]);
  useEffect(() => { load(); }, [load]);
  if (!isManager || reqs.length === 0) return null;

  const act = async (id, action) => {
    let body = {};
    if (action === 'reject') {
      const reason = window.prompt('Reason for rejecting this change request (optional):', '');
      if (reason === null) return;
      body = { reason };
    }
    setBusy(id);
    try {
      await axios.post(`${API}/staffing/detail-change-requests/${id}/${action}`, body, { headers });
      load();
    } catch (e) {
      window.alert(e.response?.data?.detail || 'Could not update request');
    } finally { setBusy(null); }
  };

  return (
    <div className="rounded-xl border p-4" style={{ borderColor: 'var(--theme-border)', background: 'var(--theme-surface)' }} data-testid="detail-change-requests-panel">
      <div className="flex items-center gap-2 mb-3">
        <AlertTriangle size={15} className="text-amber-500" />
        <p className="text-sm font-bold" style={{ color: 'var(--theme-text)' }}>Staff detail change requests</p>
        <span className="text-xs font-semibold px-2 py-0.5 rounded-full bg-amber-100 text-amber-700" data-testid="detail-requests-count">{reqs.length} pending</span>
      </div>
      <div className="space-y-2">
        {reqs.map((r) => (
          <div key={r.id} className="rounded-lg border p-3" style={{ borderColor: 'var(--theme-border)' }} data-testid={`detail-request-${r.id}`}>
            <div className="flex items-start justify-between gap-3 flex-wrap">
              <div className="min-w-0">
                <p className="text-sm font-semibold" style={{ color: 'var(--theme-text)' }}>{r.person?.full_name || 'Staff member'}</p>
                <p className="text-[11px]" style={{ color: 'var(--theme-text-muted)' }}>{r.person?.email}</p>
              </div>
              <div className="flex gap-2 shrink-0">
                <button type="button" disabled={busy === r.id} onClick={() => act(r.id, 'approve')}
                  className="h-8 px-3 rounded-md text-xs font-bold inline-flex items-center gap-1.5 disabled:opacity-50"
                  style={{ background: '#10B981', color: '#00121a' }} data-testid={`detail-approve-${r.id}`}>
                  {busy === r.id ? <Loader2 size={12} className="animate-spin" /> : <Check size={12} />} Approve & update
                </button>
                <button type="button" disabled={busy === r.id} onClick={() => act(r.id, 'reject')}
                  className="h-8 px-3 rounded-md text-xs font-bold inline-flex items-center gap-1.5 border disabled:opacity-50"
                  style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text-muted)' }} data-testid={`detail-reject-${r.id}`}>
                  <X size={12} /> Reject
                </button>
              </div>
            </div>
            <div className="mt-2 grid grid-cols-1 sm:grid-cols-2 gap-2">
              {Object.entries(r.changes || {}).map(([k, c]) => (
                <div key={k} className="rounded-md bg-slate-50 border border-slate-200 px-3 py-2 text-xs">
                  <div className="text-[10px] uppercase tracking-wide text-slate-400">{c.label}</div>
                  <div className="text-slate-500 line-through">{c.old || '—'}</div>
                  <div className="text-slate-800 font-semibold">{c.new}</div>
                </div>
              ))}
            </div>
            {r.note && <p className="mt-2 text-xs italic" style={{ color: 'var(--theme-text-muted)' }}>“{r.note}”</p>}
          </div>
        ))}
      </div>
    </div>
  );
}

export default function HRTab({ headers, isManager, canGrant = false, scopedViewer = false }) {
  const { t } = useTranslation();
  const [staffList, setStaffList] = useState([]);
  const [activeId, setActiveId] = useState(null);
  const [search, setSearch] = useState('');
  const [sub, setSub] = useState(() => localStorage.getItem('staffing.hr.sub') || 'profile');
  const [loading, setLoading] = useState(true);
  const [rolesOpen, setRolesOpen] = useState(false);
  const [showAdd, setShowAdd] = useState(false);
  const [showBulk, setShowBulk] = useState(false);
  const [credsDialog, setCredsDialog] = useState(null);
  const [credsBusy, setCredsBusy] = useState(null);
  const [reconciling, setReconciling] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const { data } = await axios.get(`${API}/staffing/staff`, { headers });
      const list = data.staff || [];
      setStaffList(list);
      if (!activeId && list.length > 0) setActiveId(list[0].id);
    } catch { /* noop */ }
    setLoading(false);
  }, [headers, activeId]);
  useEffect(() => { load(); }, [load]);

  useEffect(() => { localStorage.setItem('staffing.hr.sub', sub); }, [sub]);

  const [departments, setDepartments] = useState([]);
  const [deptFilter, setDeptFilter] = useState('');
  useEffect(() => {
    axios.get(`${API}/staffing/departments`, { headers })
      .then((r) => setDepartments(r.data.departments || [])).catch(() => {});
  }, [headers]);

  // Invite a staff member to the platform login (issues an invite link if they
  // have an email, otherwise a one-shot temp password). Their Staffing job role
  // is cross-synced to the platform login role by the backend.
  const issueCredentials = useCallback(async (s) => {
    if (!s) return;
    if (!window.confirm(t('staffing.hr_invite_confirm', `Invite ${s.full_name} to the platform as "${humanizeRole(s.primary_role || 'staff')}"?`))) return;
    const useLink = s.email
      ? window.confirm(t('staffing.hr_invite_link_q', `Send a "set your password" link to ${s.email}?\n\nOK = email a set-password link\nCancel = generate a temporary password instead`))
      : false;
    setCredsBusy(s.id);
    try {
      const { data } = await axios.post(`${API}/staffing/staff/${s.id}/issue-credentials`,
        { delivery: useLink ? 'reset_link' : 'temp_password' }, { headers });
      setCredsDialog({ ...data, staffName: s.full_name });
      load();
    } catch (err) {
      window.alert(err.response?.data?.detail || t('staffing.hr_creds_failed', 'Could not issue credentials'));
    } finally {
      setCredsBusy(null);
    }
  }, [headers, load, t]);

  const reconcileRoles = useCallback(async () => {
    if (!window.confirm(t('staffing.hr_reconcile_confirm', 'Align every staff login role with their Staffing job role? This fixes mismatches (e.g. an Engineer showing as a sales rep in Master Admin).'))) return;
    setReconciling(true);
    try {
      const { data } = await axios.post(`${API}/staffing/reconcile-roles`, {}, { headers });
      window.alert(t('staffing.hr_reconcile_done', `Done — ${data.updated} of ${data.checked} logins updated to match their job role.`));
      load();
    } catch (e) {
      window.alert(e.response?.data?.detail || t('staffing.hr_reconcile_failed', 'Reconcile failed'));
    } finally {
      setReconciling(false);
    }
  }, [headers, load, t]);

  const removeStaff = useCallback(async (s) => {
    if (!s) return;
    if (!window.confirm(t('staffing.hr_remove_confirm',
      `Remove ${s.full_name} from staff?\n\nThey'll be taken off the active staff list, rota and payroll. Their historical records are kept and this can be reversed by re-adding them.`))) return;
    try {
      await axios.delete(`${API}/staffing/staff/${s.id}`, { headers });
      setActiveId(null);
      await load();
    } catch (e) {
      window.alert(e.response?.data?.detail || t('staffing.hr_remove_failed', 'Could not remove staff member'));
    }
  }, [headers, load, t]);

  const filtered = useMemo(() => {
    let list = staffList;
    if (deptFilter) list = list.filter((s) => (s.department || '') === deptFilter);
    if (search.trim()) {
      const q = search.toLowerCase();
      list = list.filter((s) => (s.full_name || '').toLowerCase().includes(q) || (s.email || '').toLowerCase().includes(q));
    }
    return list;
  }, [staffList, search, deptFilter]);

  const active = filtered.find((s) => s.id === activeId) || filtered[0];

  return (
    <div className="space-y-3" data-testid="hr-tab">

      <DetailChangeRequestsPanel headers={headers} isManager={isManager} />

      {isManager && (
        <div className="flex items-center justify-end gap-2 flex-wrap">
          <div className="flex items-center gap-2 shrink-0">
            <button type="button" onClick={reconcileRoles} disabled={reconciling}
              className="h-8 px-3 rounded-md text-xs font-bold inline-flex items-center gap-1.5 border disabled:opacity-50"
              style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }}
              data-testid="staff-reconcile-roles-btn"
              title={t('staffing.hr_reconcile_title', 'Align every staff login role with their Staffing job role')}>
              {reconciling ? <Loader2 size={13} className="animate-spin" /> : <Check size={13} />}
              {reconciling ? t('staffing.hr_fixing', 'Fixing…') : t('staffing.hr_fix_login_roles', 'Fix login roles')}
            </button>
            <button type="button" onClick={() => setRolesOpen(true)}
              className="h-8 px-3 rounded-md text-xs font-bold inline-flex items-center gap-1.5 border shrink-0"
              style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }}
              data-testid="hr-manage-roles-btn">
              <Briefcase size={13} /> {t('staffing.hr_manage_roles', 'Manage job roles')}
            </button>
          </div>
        </div>
      )}

      {rolesOpen && (
        <JobRolesModal headers={headers} onClose={() => setRolesOpen(false)} onChanged={load} />
      )}

      {credsDialog && (
        <CredsDialog creds={credsDialog} onClose={() => setCredsDialog(null)} />
      )}

      {showAdd && (
        <AddStaffDialog
          headers={headers}
          onClose={() => setShowAdd(false)}
          onCreated={async (newId) => { await load(); if (newId) setActiveId(newId); }}
        />
      )}
      {showBulk && (
        <BulkModulesDialog
          headers={headers}
          staff={staffList}
          onClose={() => setShowBulk(false)}
          onApplied={async () => { await load(); }}
        />
      )}

      <div className="grid grid-cols-1 lg:grid-cols-[260px_1fr] gap-3 rounded-xl border overflow-hidden"
        style={{ borderColor: 'var(--theme-border)', background: 'var(--theme-surface)', minHeight: '600px' }}>
        {/* Staff list */}
        <div className="border-r flex flex-col" style={{ borderColor: 'var(--theme-border)' }}>
          <div className="p-2 border-b flex items-center gap-2" style={{ borderColor: 'var(--theme-border)' }}>
            <div className="relative flex-1">
              <Search size={11} className="absolute left-2 top-1/2 -translate-y-1/2 opacity-50" />
              <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder={t('staffing.hr_search_staff', 'Search staff…')}
                className="w-full h-8 rounded-md bg-transparent border pl-6 pr-2 text-xs"
                style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }}
                data-testid="hr-search" />
            </div>
            {isManager && (
              <button type="button" onClick={() => setShowBulk(true)}
                className="h-8 px-2.5 rounded-md text-xs font-bold inline-flex items-center gap-1 shrink-0 border"
                style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }}
                data-testid="hr-bulk-modules-btn" title={t('staffing.hr_bulk_modules', 'Bulk module access')}>
                <ShieldAlert size={13} /> {t('staffing.hr_bulk', 'Bulk')}
              </button>
            )}
            {isManager && (
              <button type="button" onClick={() => setShowAdd(true)}
                className="h-8 px-2.5 rounded-md text-xs font-bold inline-flex items-center gap-1 shrink-0"
                style={{ background: 'var(--color-brand-cyan)', color: '#1B1C1D' }}
                data-testid="hr-add-staff-btn" title={t('staffing.hr_add_staff', 'Add staff')}>
                <UserPlus size={13} /> {t('staffing.hr_add', 'Add')}
              </button>
            )}
          </div>
          <div className="px-2 pb-2 border-b" style={{ borderColor: 'var(--theme-border)' }}>
            <select value={deptFilter} onChange={(e) => setDeptFilter(e.target.value)}
              className="w-full h-8 rounded-md bg-transparent border px-2 text-xs"
              style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }}
              data-testid="hr-dept-filter">
              <option value="">{t('staffing.hr_all_departments', 'All departments')}</option>
              {departments.map((d) => <option key={d} value={d}>{d}</option>)}
            </select>
          </div>
          <div className="flex-1 overflow-y-auto" data-testid="hr-staff-list">
            {loading && (
              <div className="p-3 inline-flex items-center gap-2 text-xs" style={{ color: 'var(--theme-text-muted)' }}>
                <Loader2 size={12} className="animate-spin" /> {t('staffing.hr_loading', 'Loading…')}
              </div>
            )}
            {!loading && filtered.length === 0 && (
              <p className="p-4 text-center text-xs" style={{ color: 'var(--theme-text-muted)' }}>{t('staffing.hr_no_staff_match', 'No staff match.')}</p>
            )}
            {filtered.map((s) => {
              const on = s.id === active?.id;
              return (
                <button key={s.id} type="button" onClick={() => setActiveId(s.id)}
                  className="relative w-full text-left px-3 py-2 border-b transition-colors"
                  style={{
                    background: on ? 'rgba(25,205,255,0.10)' : 'transparent',
                    borderColor: 'var(--theme-border)',
                  }}
                  data-testid={`hr-staff-row-${s.id}`}>
                  {(() => {
                    const active = !!(s.has_login || s.portal_credentials_issued_at);
                    return (
                      <span
                        className="absolute top-2 right-2 h-2.5 w-2.5 rounded-full ring-2 ring-white dark:ring-black/40"
                        title={active ? t('staffing.hr_login_active', 'Login active') : t('staffing.hr_not_invited', 'Not invited')}
                        style={{ background: active ? '#10b981' : 'transparent', border: active ? 'none' : '1.5px solid var(--theme-text-muted)', boxShadow: active ? '0 0 0 3px rgba(16,185,129,0.18)' : 'none' }}
                        data-testid={`hr-staff-login-badge-${s.id}`}
                      />
                    );
                  })()}
                  <div className="flex items-center gap-2.5 pr-4">
                    <div className="h-8 w-8 rounded-full overflow-hidden shrink-0 flex items-center justify-center border" style={{ borderColor: 'var(--theme-border)', background: 'rgba(25,205,255,0.12)' }}>
                      {s.photo_url
                        ? <img src={hrPhotoSrc(s.photo_url)} alt="" className="h-full w-full object-cover" data-testid={`hr-staff-avatar-${s.id}`} />
                        : <span className="text-[10px] font-bold" style={{ color: 'var(--color-brand-cyan)' }}>{(s.full_name || '?').split(' ').map((p) => p[0]).slice(0, 2).join('').toUpperCase()}</span>}
                    </div>
                    <div className="min-w-0">
                      <p className="text-sm font-bold truncate" style={{ color: 'var(--theme-text)' }}>{s.full_name}</p>
                      <p className="text-[10px] uppercase tracking-wider flex items-center gap-1.5 flex-wrap" style={{ color: 'var(--theme-text-muted)' }}>
                        {humanizeRole(s.primary_role)}
                        {s.department && <span className="normal-case text-[9px] px-1 rounded" style={{ background: 'rgba(25,205,255,0.15)', color: 'var(--color-brand-cyan)' }}>{s.department}</span>}
                        {(s.dept_visibility?.all || s.dept_visibility?.departments?.length > 0) && (
                          <span className="normal-case text-[9px] px-1 rounded" style={{ background: 'rgba(245,158,11,0.15)', color: '#d97706' }}
                            title={s.dept_visibility.all ? 'Sees all departments' : `Also sees: ${s.dept_visibility.departments.join(', ')}`}
                            data-testid={`hr-staff-dept-grant-${s.id}`}>
                            {s.dept_visibility.all ? 'Sees all depts' : `+${s.dept_visibility.departments.length} dept${s.dept_visibility.departments.length > 1 ? 's' : ''}`}
                          </span>
                        )}
                      </p>
                    </div>
                  </div>
                </button>
              );
            })}
          </div>
        </div>

        {/* Detail */}
        <div className="p-4 space-y-3">
          {!active ? (
            <p className="text-xs" style={{ color: 'var(--theme-text-muted)' }}>{t('staffing.hr_pick_staff', 'Pick a staff member.')}</p>
          ) : (
            <>
              <div className="inline-flex rounded-full border overflow-hidden" style={{ borderColor: 'var(--theme-border)' }}>
                {SUB_TABS.filter((st) => !scopedViewer || st.id === 'profile').map((st) => {
                  const Icon = st.icon;
                  const on = sub === st.id;
                  return (
                    <button key={st.id} type="button" onClick={() => setSub(st.id)}
                      className="h-8 px-3 text-xs font-bold inline-flex items-center gap-1.5"
                      style={{
                        background: on ? 'var(--color-brand-cyan)' : 'transparent',
                        color: on ? '#1B1C1D' : 'var(--theme-text-muted)',
                        borderLeft: st.id !== SUB_TABS[0].id ? '1px solid var(--theme-border)' : 'none',
                      }}
                      data-testid={`hr-sub-${st.id}`}>
                      <Icon size={11} /> {t(st.labelKey, st.labelDefault)}
                    </button>
                  );
                })}
              </div>
              {(sub === 'profile' || scopedViewer) && <ProfilePanel staffId={active.id} headers={headers} isManager={isManager} canGrant={canGrant} onUpdated={load} onInvite={issueCredentials} inviteBusy={credsBusy === active.id} onDelete={() => removeStaff(active)} departments={departments} photoUrl={active.photo_url} />}
              {!scopedViewer && sub === 'documents'    && <DocumentsPanel    staffId={active.id} headers={headers} isManager={isManager} />}
              {!scopedViewer && sub === 'disciplinary' && <DisciplinaryPanel staffId={active.id} headers={headers} isManager={isManager} />}
              {!scopedViewer && sub === 'training'     && <TrainingPanel     staffId={active.id} headers={headers} isManager={isManager} />}
            </>
          )}
        </div>
      </div>
    </div>
  );
}

/**
 * PayrollWorkspaceTab — configurable pay periods + exception-based Payroll
 * Workspace on the Attendance Spine. Submit → approve → lock (immutable
 * snapshot) → export with field mapping. Payroll resolves exceptions, not
 * spreadsheets.
 */
import { useCallback, useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import axios from 'axios';
import {
  Plus, Lock, Download, CheckCircle2, RotateCcw, AlertTriangle, X, Save,
  Loader2, FileSpreadsheet, ShieldCheck, ChevronRight, BarChart3, Table2,
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid } from 'recharts';

const API = `${process.env.REACT_APP_BACKEND_URL}/api`;
const token = () => localStorage.getItem('token');

const STATUS_STYLE = {
  draft: ['#9a9fa1', 'Draft'], returned: ['#b45309', 'Returned'],
  submitted: ['#0091ca', 'Submitted'], approved: ['#16a34a', 'Approved'],
  locked: ['#0091ca', 'Locked'],
};
const EX_LABEL = {
  missing_entry: 'Missing entry', unapproved_overtime: 'Unapproved OT',
  unpaid_leave: 'Unpaid leave', no_payroll_id: 'No payroll ID',
  above_contract: 'Above contract', below_contract: 'Below contract',
  missing_approval: 'Awaiting approval',
};

function Pill({ status }) {
  const [c, l] = STATUS_STYLE[status] || ['#9a9fa1', status];
  return <span className="px-2 py-0.5 rounded-full text-[11px] font-bold" style={{ background: `${c}1a`, color: c }}>{l}</span>;
}

export default function PayrollWorkspaceTab({ headers }) {
  const [periods, setPeriods] = useState([]);
  const [sel, setSel] = useState(null);
  const [ws, setWs] = useState(null);
  const [loading, setLoading] = useState(false);
  const [showNew, setShowNew] = useState(false);
  const [adj, setAdj] = useState(null);
  const [ret, setRet] = useState(null);
  const [busy, setBusy] = useState(false);
  const [view, setView] = useState('workspace');

  const loadPeriods = useCallback(async () => {
    const r = await axios.get(`${API}/payroll/periods`, { headers });
    setPeriods(r.data.periods || []);
    if (!sel && r.data.periods?.length) setSel(r.data.periods[0].id);
  }, [headers, sel]);
  useEffect(() => { loadPeriods(); }, [loadPeriods]);

  const loadWs = useCallback(async () => {
    if (!sel) { setWs(null); return; }
    setLoading(true);
    try { const r = await axios.get(`${API}/payroll/periods/${sel}/workspace`, { headers }); setWs(r.data); }
    catch { setWs(null); }
    setLoading(false);
  }, [sel, headers]);
  useEffect(() => { loadWs(); }, [loadWs]);

  const act = async (fn) => { setBusy(true); try { await fn(); await loadWs(); await loadPeriods(); } catch (e) { alert(e?.response?.data?.detail || 'Action failed'); } setBusy(false); };
  const approve = (staff_id) => act(() => axios.post(`${API}/payroll/periods/${sel}/approve`, { staff_id }, { headers }));
  const submitBehalf = (staff_id) => act(() => axios.post(`${API}/payroll/periods/${sel}/submit`, { staff_id, declaration: true }, { headers }));
  const lock = () => { if (window.confirm('Lock this period? A permanent payroll snapshot is created and it can no longer be edited without an adjustment.')) act(() => axios.post(`${API}/payroll/periods/${sel}/lock`, {}, { headers })); };
  const approveReady = () => act(async () => {
    const r = await axios.post(`${API}/payroll/periods/${sel}/approve-ready`, {}, { headers });
    alert(`Approved ${r.data.approved} clean employee${r.data.approved === 1 ? '' : 's'}. ${r.data.skipped_count} left as exception${r.data.skipped_count === 1 ? '' : 's'} to review.`);
  });

  const exportCsv = async () => {
    const res = await fetch(`${API}/payroll/periods/${sel}/export`, { headers: { Authorization: `Bearer ${token()}` } });
    const blob = await res.blob();
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a'); a.href = url; a.download = `payroll-${sel}.csv`; a.click(); URL.revokeObjectURL(url);
  };

  const period = ws?.period;
  const locked = period?.status === 'locked';
  const s = ws?.summary || {};

  return (
    <div className="space-y-4" data-testid="payroll-workspace">
      <div className="flex items-center gap-1.5">
        {[['workspace', 'Workspace', Table2], ['reports', 'Reports', BarChart3]].map(([id, label, Icon]) => (
          <button key={id} onClick={() => setView(id)} data-testid={`payroll-view-${id}`}
            className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold border ${view === id ? 'border-cyan-500 text-cyan-700 bg-cyan-50' : 'border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400'}`}>
            <Icon size={13} /> {label}
          </button>
        ))}
      </div>

      {view === 'reports' && <PayrollReports headers={headers} />}

      {view === 'workspace' && (<>
      <div className="flex items-center gap-2 flex-wrap">
        <select value={sel || ''} onChange={(e) => setSel(e.target.value)} data-testid="payroll-period-select"
          className="rounded-lg border border-slate-300 dark:border-slate-600 px-3 py-2 text-sm min-w-[240px]">
          <option value="">Select a pay period…</option>
          {periods.map((p) => <option key={p.id} value={p.id}>{p.name} {p.status === 'locked' ? '🔒' : ''}</option>)}
        </select>
        <button onClick={() => setShowNew(true)} data-testid="payroll-new-period"
          className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg bg-cyan-600 text-white text-xs font-semibold"><Plus size={13} /> New period</button>
      </div>

      {!sel && <div className="text-sm text-slate-400">Create a pay period to open the workspace.</div>}
      {loading && <Loader2 className="animate-spin text-cyan-500" />}

      {ws && !loading && (
        <>
          <div className="rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 p-4">
            <div className="flex items-start justify-between flex-wrap gap-2">
              <div>
                <div className="flex items-center gap-2"><h3 className="font-bold text-slate-900 dark:text-slate-100">{period.name}</h3><Pill status={period.status} /></div>
                <div className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">{period.start_date} → {period.end_date} · pay date {period.payroll_date || '—'}</div>
              </div>
              <div className="flex gap-2">
                <button onClick={exportCsv} data-testid="payroll-export"
                  className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg border border-slate-300 dark:border-slate-600 text-slate-700 dark:text-slate-200 text-xs font-semibold"><Download size={13} /> Export CSV</button>
                {!locked && s.awaiting_approval > 0 && <button onClick={approveReady} disabled={busy} data-testid="payroll-approve-ready"
                  className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg bg-emerald-600 text-white text-xs font-semibold"><CheckCircle2 size={13} /> Approve all ready</button>}
                {!locked && <button onClick={lock} disabled={busy} data-testid="payroll-lock"
                  className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg bg-violet-600 text-white text-xs font-semibold"><Lock size={13} /> Lock period</button>}
                {locked && <span className="inline-flex items-center gap-1.5 px-3 py-2 text-xs font-semibold text-violet-700"><ShieldCheck size={14} /> Snapshot locked</span>}
              </div>
            </div>
          </div>

          <div className="grid grid-cols-2 md:grid-cols-4 gap-2" data-testid="payroll-summary">
            {[['Ready for payroll', s.ready, '#16a34a'], ['Awaiting approval', s.awaiting_approval, '#0091ca'], ['Missing timesheet', s.missing_timesheet, '#b45309'], ['Exceptions', s.exceptions, '#f59e0b']].map(([l, v, c]) => (
              <div key={l} className="rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 p-3">
                <div className="text-2xl font-bold" style={{ color: c }}>{v ?? 0}</div>
                <div className="text-[11px] font-semibold uppercase tracking-wide text-slate-500 dark:text-slate-400">{l}</div>
              </div>
            ))}
          </div>

          <div className="overflow-x-auto rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900">
            <table className="w-full text-sm">
              <thead className="bg-slate-50 dark:bg-slate-800 text-slate-500 dark:text-slate-400 text-xs uppercase tracking-wide">
                <tr>
                  <th className="text-left px-3 py-2">Employee</th>
                  <th className="text-left px-3 py-2">Status</th>
                  <th className="text-right px-3 py-2">Regular</th>
                  <th className="text-right px-3 py-2">OT</th>
                  <th className="text-right px-3 py-2">Hol</th>
                  <th className="text-right px-3 py-2">Sick</th>
                  <th className="text-left px-3 py-2">Exceptions</th>
                  <th className="px-3 py-2"></th>
                </tr>
              </thead>
              <tbody>
                {ws.rows.map((r) => (
                  <tr key={r.staff_id} className={`border-t border-slate-100 dark:border-slate-700 ${r.exceptions.length ? 'bg-amber-50/30' : ''}`} data-testid={`payroll-row-${r.staff_id}`}>
                    <td className="px-3 py-2 font-semibold text-slate-800 dark:text-slate-100">{r.full_name}
                      {r.payroll_number ? <span className="ml-2 text-[11px] text-slate-400">#{r.payroll_number}</span> : <span className="ml-2 text-[11px] text-rose-400">no ID</span>}</td>
                    <td className="px-3 py-2"><Pill status={r.status} /></td>
                    <td className="px-3 py-2 text-right">{r.totals.regular}h</td>
                    <td className="px-3 py-2 text-right">{r.totals.overtime_approved || r.totals.overtime_raw || 0}h</td>
                    <td className="px-3 py-2 text-right">{r.totals.holiday}h</td>
                    <td className="px-3 py-2 text-right">{r.totals.sick}h</td>
                    <td className="px-3 py-2">
                      <div className="flex gap-1 flex-wrap">
                        {r.exceptions.map((e) => <span key={e} className="text-[10px] px-1.5 py-0.5 rounded bg-amber-100 text-amber-700 font-semibold">{EX_LABEL[e] || e}</span>)}
                      </div>
                    </td>
                    <td className="px-3 py-2 text-right whitespace-nowrap">
                      {!locked && r.status === 'draft' && <button onClick={() => submitBehalf(r.staff_id)} data-testid={`payroll-submit-${r.staff_id}`} className="text-xs font-semibold text-slate-600 dark:text-slate-300 hover:underline mr-2">Submit</button>}
                      {!locked && (r.status === 'submitted' || r.status === 'returned') && <>
                        <button onClick={() => approve(r.staff_id)} data-testid={`payroll-approve-${r.staff_id}`} className="text-xs font-semibold text-emerald-600 hover:underline mr-2">Approve</button>
                        <button onClick={() => setRet({ staff_id: r.staff_id, name: r.full_name, reason: '' })} className="text-xs font-semibold text-amber-600 hover:underline">Return</button>
                      </>}
                      {locked && <button onClick={() => setAdj({ staff_id: r.staff_id, name: r.full_name, category: 'overtime', new_value: '', reason: '' })} data-testid={`payroll-adjust-${r.staff_id}`} className="text-xs font-semibold text-violet-600 hover:underline">Adjust</button>}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}
      </>)}

      {showNew && <NewPeriodModal headers={headers} onClose={() => setShowNew(false)} onCreated={(id) => { setShowNew(false); setSel(id); loadPeriods(); }} />}
      {ret && <ReturnModal onClose={() => setRet(null)} onSubmit={async (reason) => { await act(() => axios.post(`${API}/payroll/periods/${sel}/return`, { staff_id: ret.staff_id, reason }, { headers })); setRet(null); }} name={ret.name} />}
      {adj && <AdjustModal periodId={sel} headers={headers} adj={adj} onClose={() => setAdj(null)} onSaved={() => { setAdj(null); }} />}
    </div>
  );
}

function NewPeriodModal({ headers, onClose, onCreated }) {
  const [mode, setMode] = useState('generate');
  const [freq, setFreq] = useState('month');
  const [anchor, setAnchor] = useState(() => new Date().toISOString().slice(0, 10));
  const [custom, setCustom] = useState({ name: '', start_date: '', end_date: '' });
  const [busy, setBusy] = useState(false);
  const create = async () => {
    setBusy(true);
    try {
      let res;
      if (mode === 'generate') res = await axios.post(`${API}/payroll/periods/generate`, { frequency: freq, anchor }, { headers });
      else res = await axios.post(`${API}/payroll/periods`, { ...custom, frequency: 'custom' }, { headers });
      onCreated(res.data.id);
    } catch (e) { alert(e?.response?.data?.detail || 'Failed'); setBusy(false); }
  };
  return createPortal(
    <div className="fixed inset-0 z-[120] flex items-center justify-center bg-black/40 p-4" data-testid="payroll-new-modal">
      <div className="w-full max-w-md rounded-2xl bg-white dark:bg-slate-900 p-5 shadow-2xl">
        <div className="flex items-center justify-between mb-3"><h3 className="font-bold text-slate-900 dark:text-slate-100">New pay period</h3><button onClick={onClose}><X size={18} className="text-slate-400" /></button></div>
        <div className="flex gap-1.5 mb-3">
          {[['generate', 'Quick generate'], ['custom', 'Custom dates']].map(([k, l]) => (
            <button key={k} onClick={() => setMode(k)} className={`px-3 py-1.5 rounded-lg text-xs font-semibold border ${mode === k ? 'border-cyan-500 text-cyan-700 bg-cyan-50' : 'border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400'}`}>{l}</button>
          ))}
        </div>
        {mode === 'generate' ? (
          <div className="space-y-2">
            <label className="block text-xs font-semibold text-slate-600 dark:text-slate-300">Frequency
              <select value={freq} onChange={(e) => setFreq(e.target.value)} data-testid="payroll-gen-freq" className="mt-1 w-full rounded-lg border border-slate-300 dark:border-slate-600 px-3 py-2 text-sm">
                <option value="month">Calendar month</option><option value="4_week">4-week</option><option value="5_week">5-week</option>
              </select></label>
            <label className="block text-xs font-semibold text-slate-600 dark:text-slate-300">{freq === 'month' ? 'Any date in the month' : 'Start date'}
              <input type="date" value={anchor} onChange={(e) => setAnchor(e.target.value)} data-testid="payroll-gen-anchor" className="mt-1 w-full rounded-lg border border-slate-300 dark:border-slate-600 px-3 py-2 text-sm" /></label>
          </div>
        ) : (
          <div className="space-y-2">
            <input placeholder="Period name" value={custom.name} onChange={(e) => setCustom({ ...custom, name: e.target.value })} className="w-full rounded-lg border border-slate-300 dark:border-slate-600 px-3 py-2 text-sm" />
            <div className="grid grid-cols-2 gap-2">
              <input type="date" value={custom.start_date} onChange={(e) => setCustom({ ...custom, start_date: e.target.value })} className="rounded-lg border border-slate-300 dark:border-slate-600 px-3 py-2 text-sm" />
              <input type="date" value={custom.end_date} onChange={(e) => setCustom({ ...custom, end_date: e.target.value })} className="rounded-lg border border-slate-300 dark:border-slate-600 px-3 py-2 text-sm" />
            </div>
          </div>
        )}
        <div className="flex justify-end gap-2 mt-4">
          <button onClick={onClose} className="px-3 py-2 rounded-lg text-sm font-semibold text-slate-500 dark:text-slate-400">Cancel</button>
          <button onClick={create} disabled={busy} data-testid="payroll-create-period" className="inline-flex items-center gap-1.5 px-4 py-2 rounded-lg bg-cyan-600 text-white text-sm font-semibold">{busy ? <Loader2 size={14} className="animate-spin" /> : <FileSpreadsheet size={14} />} Create</button>
        </div>
      </div>
    </div>, document.body);
}

function ReturnModal({ onClose, onSubmit, name }) {
  const [reason, setReason] = useState('');
  return createPortal(
    <div className="fixed inset-0 z-[120] flex items-center justify-center bg-black/40 p-4" data-testid="payroll-return-modal">
      <div className="w-full max-w-md rounded-2xl bg-white dark:bg-slate-900 p-5 shadow-2xl">
        <h3 className="font-bold text-slate-900 dark:text-slate-100 mb-2">Return to {name} for correction</h3>
        <textarea value={reason} onChange={(e) => setReason(e.target.value)} data-testid="payroll-return-reason" placeholder="What needs fixing?" rows={3} className="w-full rounded-lg border border-slate-300 dark:border-slate-600 px-3 py-2 text-sm" />
        <div className="flex justify-end gap-2 mt-3">
          <button onClick={onClose} className="px-3 py-2 rounded-lg text-sm font-semibold text-slate-500 dark:text-slate-400">Cancel</button>
          <button onClick={() => reason.trim() && onSubmit(reason.trim())} data-testid="payroll-return-save" className="px-4 py-2 rounded-lg bg-amber-500 text-white text-sm font-semibold">Return</button>
        </div>
      </div>
    </div>, document.body);
}

function AdjustModal({ periodId, headers, adj, onClose, onSaved }) {
  const [f, setF] = useState(adj);
  const [busy, setBusy] = useState(false);
  const save = async () => {
    if (!f.reason.trim() || f.new_value === '') return;
    setBusy(true);
    try { await axios.post(`${API}/payroll/periods/${periodId}/adjustment`, { staff_id: f.staff_id, category: f.category, old_value: null, new_value: Number(f.new_value), reason: f.reason }, { headers }); onSaved(); }
    catch (e) { alert(e?.response?.data?.detail || 'Failed'); setBusy(false); }
  };
  return createPortal(
    <div className="fixed inset-0 z-[120] flex items-center justify-center bg-black/40 p-4" data-testid="payroll-adjust-modal">
      <div className="w-full max-w-md rounded-2xl bg-white dark:bg-slate-900 p-5 shadow-2xl">
        <h3 className="font-bold text-slate-900 dark:text-slate-100 mb-1">Payroll adjustment — {f.name}</h3>
        <p className="text-[11px] text-slate-500 dark:text-slate-400 mb-3">The locked snapshot stays intact; this is recorded as an authorised adjustment.</p>
        <div className="grid grid-cols-2 gap-2">
          <label className="text-xs font-semibold text-slate-600 dark:text-slate-300">Category
            <input value={f.category} onChange={(e) => setF({ ...f, category: e.target.value })} className="mt-1 w-full rounded-lg border border-slate-300 dark:border-slate-600 px-3 py-2 text-sm" /></label>
          <label className="text-xs font-semibold text-slate-600 dark:text-slate-300">New value
            <input type="number" value={f.new_value} onChange={(e) => setF({ ...f, new_value: e.target.value })} data-testid="payroll-adjust-value" className="mt-1 w-full rounded-lg border border-slate-300 dark:border-slate-600 px-3 py-2 text-sm" /></label>
        </div>
        <label className="block text-xs font-semibold text-slate-600 dark:text-slate-300 mt-2">Reason
          <input value={f.reason} onChange={(e) => setF({ ...f, reason: e.target.value })} data-testid="payroll-adjust-reason" className="mt-1 w-full rounded-lg border border-slate-300 dark:border-slate-600 px-3 py-2 text-sm" /></label>
        <div className="flex justify-end gap-2 mt-3">
          <button onClick={onClose} className="px-3 py-2 rounded-lg text-sm font-semibold text-slate-500 dark:text-slate-400">Cancel</button>
          <button onClick={save} disabled={busy} data-testid="payroll-adjust-save" className="inline-flex items-center gap-1.5 px-4 py-2 rounded-lg bg-violet-600 text-white text-sm font-semibold"><Save size={14} /> Record</button>
        </div>
      </div>
    </div>, document.body);
}

/* ─────────────── Payroll Reports (§43) ─────────────── */
function monthBounds() {
  const n = new Date();
  const first = new Date(n.getFullYear(), n.getMonth(), 1);
  const last = new Date(n.getFullYear(), n.getMonth() + 1, 0);
  const iso = (d) => d.toISOString().slice(0, 10);
  return [iso(first), iso(last)];
}

function PayrollReports({ headers }) {
  const [mb] = useState(monthBounds);
  const [from, setFrom] = useState(mb[0]);
  const [to, setTo] = useState(mb[1]);
  const [d, setD] = useState(null);
  const [loading, setLoading] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    try { const r = await axios.get(`${API}/payroll/reports?date_from=${from}&date_to=${to}`, { headers }); setD(r.data); }
    catch { setD(null); }
    setLoading(false);
  }, [from, to, headers]);
  useEffect(() => { load(); }, [load]);

  const t = d?.totals || {};
  const sub = d?.submissions || {};
  const tiles = [
    ['Hours worked', `${t.worked ?? 0}h`, '#1b1c1d'],
    ['Overtime', `${t.overtime ?? 0}h`, '#0091ca'],
    ['Holiday', `${t.holiday ?? 0}h`, '#0091ca'],
    ['Sick', `${t.sick ?? 0}h`, '#dc2626'],
    ['Attendance rate', `${t.attendance_rate ?? 0}%`, '#16a34a'],
    ['Adjustments', d?.adjustments ?? 0, '#0091ca'],
  ];

  return (
    <div className="space-y-4" data-testid="payroll-reports">
      <div className="flex items-end gap-3 flex-wrap">
        <label className="text-xs font-semibold text-slate-600 dark:text-slate-300">From
          <input type="date" value={from} onChange={(e) => setFrom(e.target.value)} data-testid="payroll-report-from" className="mt-1 block rounded-lg border border-slate-300 dark:border-slate-600 px-3 py-2 text-sm" /></label>
        <label className="text-xs font-semibold text-slate-600 dark:text-slate-300">To
          <input type="date" value={to} onChange={(e) => setTo(e.target.value)} data-testid="payroll-report-to" className="mt-1 block rounded-lg border border-slate-300 dark:border-slate-600 px-3 py-2 text-sm" /></label>
        {loading && <Loader2 className="animate-spin text-cyan-500 mb-2" />}
      </div>

      <div className="grid grid-cols-2 md:grid-cols-6 gap-2" data-testid="payroll-report-tiles">
        {tiles.map(([l, v, c]) => (
          <div key={l} className="rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 p-3">
            <div className="text-xl font-bold" style={{ color: c }}>{v}</div>
            <div className="text-[11px] font-semibold uppercase tracking-wide text-slate-500 dark:text-slate-400">{l}</div>
          </div>
        ))}
      </div>

      <div className="rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 p-4">
        <h3 className="font-bold text-slate-900 dark:text-slate-100 mb-3">Hours by department</h3>
        <div style={{ width: '100%', height: 240 }}>
          <ResponsiveContainer>
            <BarChart data={d?.by_department || []} margin={{ top: 4, right: 8, left: -12, bottom: 4 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
              <XAxis dataKey="department" tick={{ fontSize: 11 }} />
              <YAxis tick={{ fontSize: 11 }} />
              <Tooltip />
              <Bar dataKey="worked" name="Worked" fill="#0091ca" radius={[4, 4, 0, 0]} />
              <Bar dataKey="overtime" name="Overtime" fill="#f59e0b" radius={[4, 4, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="grid md:grid-cols-3 gap-2" data-testid="payroll-report-submissions">
        {[['On-time submissions', sub.on_time, '#16a34a'], ['Late submissions', sub.late, '#b45309'], ['Missing submissions', sub.missing, '#dc2626']].map(([l, v, c]) => (
          <div key={l} className="rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 p-3">
            <div className="text-lg font-bold" style={{ color: c }}>{v ?? 0}</div>
            <div className="text-[11px] font-semibold uppercase tracking-wide text-slate-500 dark:text-slate-400">{l}</div>
          </div>
        ))}
      </div>

      <div className="overflow-x-auto rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900">
        <table className="w-full text-sm">
          <thead className="bg-slate-50 dark:bg-slate-800 text-slate-500 dark:text-slate-400 text-xs uppercase tracking-wide">
            <tr>
              <th className="text-left px-3 py-2">Employee</th>
              <th className="text-left px-3 py-2">Dept</th>
              <th className="text-right px-3 py-2">Worked</th>
              <th className="text-right px-3 py-2">OT</th>
              <th className="text-right px-3 py-2">Holiday</th>
              <th className="text-right px-3 py-2">Sick</th>
              <th className="text-right px-3 py-2">Missing</th>
              <th className="text-right px-3 py-2">Attendance</th>
            </tr>
          </thead>
          <tbody>
            {(d?.by_employee || []).map((r) => (
              <tr key={r.staff_id} className="border-t border-slate-100 dark:border-slate-700" data-testid={`payroll-report-emp-${r.staff_id}`}>
                <td className="px-3 py-2 font-semibold text-slate-800 dark:text-slate-100">{r.full_name}</td>
                <td className="px-3 py-2 text-slate-500 dark:text-slate-400">{r.department}</td>
                <td className="px-3 py-2 text-right">{r.worked}h</td>
                <td className="px-3 py-2 text-right">{r.overtime}h</td>
                <td className="px-3 py-2 text-right">{r.holiday}h</td>
                <td className="px-3 py-2 text-right">{r.sick}h</td>
                <td className="px-3 py-2 text-right">{r.missing}</td>
                <td className="px-3 py-2 text-right font-semibold" style={{ color: r.attendance_rate >= 90 ? '#16a34a' : r.attendance_rate >= 70 ? '#b45309' : '#dc2626' }}>{r.attendance_rate}%</td>
              </tr>
            ))}
            {d && !d.by_employee?.length && <tr><td colSpan={8} className="px-3 py-6 text-center text-slate-400">No data in this range.</td></tr>}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/**
 * StaffOnboarding — HR console for the Staff Onboarding, Offer & Contract wizard.
 * Mounted at Operations → Staffing → People → Staff Onboarding.
 * Single person record (staff_members) progresses candidate→…→employee.
 */
import { useCallback, useEffect, useState, useRef } from 'react';
import { createPortal } from 'react-dom';
import axios from 'axios';
import { useTranslation } from 'react-i18next';
import {
  UserPlus, Loader2, X, FileText, FileSignature, CheckCircle2, ShieldCheck,
  ClipboardList, ScrollText, ArrowRight, AlertTriangle, History, Bell,
  Download, Pencil, RotateCcw, Plus, ShieldAlert, Settings, Mail,
} from 'lucide-react';

const API = `${process.env.REACT_APP_BACKEND_URL}/api`;

async function openPdf(url, headers) {
  const r = await axios.get(url, { headers, responseType: 'blob' });
  const blobUrl = URL.createObjectURL(new Blob([r.data], { type: 'application/pdf' }));
  window.open(blobUrl, '_blank');
}

const surface = { background: 'var(--theme-surface)', borderColor: 'var(--theme-border)' };
const STATUS_LABELS_EN = {
  not_started: 'Not Started', in_progress: 'In Progress', awaiting_hr_review: 'Awaiting HR Review',
  awaiting_offer: 'Awaiting Offer', offer_issued: 'Offer Issued', offer_accepted: 'Offer Accepted',
  offer_declined: 'Offer Declined', contract_issued: 'Contract Issued',
  awaiting_employer_signature: 'Awaiting Employer Signature', ready_to_activate: 'Ready to Activate',
  complete: 'Complete',
};
function statusLabel(t, s) {
  return t(`staffing.onb_status_${s}`, STATUS_LABELS_EN[s] || s);
}

function Pill({ children, tone = 'slate' }) {
  const tones = {
    slate: 'bg-slate-500/15 text-slate-300', blue: 'bg-cyan-500/15 text-cyan-300',
    green: 'bg-emerald-500/15 text-emerald-300', amber: 'bg-amber-500/15 text-amber-300',
    red: 'bg-red-500/15 text-red-300',
  };
  return <span className={`px-2 py-0.5 rounded-full text-[11px] font-semibold ${tones[tone]}`}>{children}</span>;
}

export default function StaffOnboarding({ headers }) {
  const { t } = useTranslation();
  const [cards, setCards] = useState({});
  const [cases, setCases] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showWizard, setShowWizard] = useState(false);
  const [openCase, setOpenCase] = useState(null);
  const [notifs, setNotifs] = useState({ notifications: [], unread: 0 });
  const [showNotifs, setShowNotifs] = useState(false);
  const [showTemplates, setShowTemplates] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const [d, c, n] = await Promise.all([
        axios.get(`${API}/staff-onboarding/dashboard`, { headers }),
        axios.get(`${API}/staff-onboarding/cases`, { headers }),
        axios.get(`${API}/staff-onboarding/notifications`, { headers }).catch(() => ({ data: { notifications: [], unread: 0 } })),
      ]);
      setCards(d.data.cards || {});
      setCases(c.data.cases || []);
      setNotifs(n.data || { notifications: [], unread: 0 });
    } catch (e) { /* noop */ } finally { setLoading(false); }
  }, [headers]);

  const openNotifs = async () => {
    setShowNotifs((v) => !v);
    if (!showNotifs && notifs.unread > 0) {
      try { await axios.post(`${API}/staff-onboarding/notifications/read`, {}, { headers }); setNotifs((p) => ({ ...p, unread: 0 })); } catch (e) {}
    }
  };

  useEffect(() => { load(); }, [load]);

  const CARD_DEFS = [
    ['paperwork_awaiting_review', t('staffing.onb_card_awaiting_review', 'Awaiting review'), 'amber'],
    ['ready_for_offer', t('staffing.onb_card_ready_offer', 'Ready for offer'), 'blue'],
    ['offers_issued', t('staffing.onb_card_offers_issued', 'Offers issued'), 'blue'],
    ['offers_accepted', t('staffing.onb_card_offers_accepted', 'Offers accepted'), 'green'],
    ['contracts_awaiting_signature', t('staffing.onb_card_contracts_sign', 'Contracts to sign'), 'amber'],
    ['contracts_fully_signed', t('staffing.onb_card_fully_signed', 'Fully signed'), 'green'],
    ['ready_to_activate', t('staffing.onb_card_ready_activate', 'Ready to activate'), 'green'],
    ['total_cases', t('staffing.onb_card_total', 'Total cases'), 'slate'],
  ];

  return (
    <div className="space-y-5" data-testid="staff-onboarding-console">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h2 className="text-xl font-bold" style={{ color: 'var(--theme-text)' }}>{t('staffing.onb_title', 'Staff Onboarding')}</h2>
          <p className="text-sm opacity-70" style={{ color: 'var(--theme-text)' }}>
            {t('staffing.onb_subtitle', 'Paperless recruitment-to-employment — one person record, offer letter, contract & e-signature.')}
          </p>
        </div>
        <div className="flex items-center gap-2">
          <div className="relative">
            <button onClick={openNotifs} data-testid="notifications-bell"
              className="relative p-2 rounded-xl border" style={{ color: 'var(--theme-text)', borderColor: 'var(--theme-border)' }}>
              <Bell size={18} />
              {notifs.unread > 0 && <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] rounded-full w-4 h-4 flex items-center justify-center">{notifs.unread}</span>}
            </button>
            {showNotifs && (
              <div className="absolute right-0 mt-2 w-80 max-h-96 overflow-auto rounded-xl border shadow-xl z-50 p-2" data-testid="notifications-panel"
                style={{ background: 'var(--theme-bg,#0f1417)', borderColor: 'var(--theme-border)' }}>
                {notifs.notifications.length === 0 ? (
                  <div className="p-4 text-sm opacity-60 text-center" style={{ color: 'var(--theme-text)' }}>{t('staffing.onb_no_notifs', 'No notifications')}</div>
                ) : notifs.notifications.map((n) => (
                  <div key={n.id} className="px-3 py-2 rounded-lg text-sm" style={{ color: 'var(--theme-text)' }}>
                    <div className="font-medium">{n.message}</div>
                    <div className="text-xs opacity-50">{new Date(n.created_at).toLocaleString()}</div>
                  </div>
                ))}
              </div>
            )}
          </div>
          <button onClick={() => setShowTemplates(true)} data-testid="open-templates-btn"
            className="inline-flex items-center gap-2 px-4 py-2 rounded-xl font-semibold border"
            style={{ color: 'var(--theme-text)', borderColor: 'var(--theme-border)' }}>
            <ScrollText size={16} /> {t('staffing.onb_templates', 'Templates')}
          </button>
          <button onClick={() => setShowSettings(true)} data-testid="open-settings-btn"
            className="inline-flex items-center gap-2 px-4 py-2 rounded-xl font-semibold border"
            style={{ color: 'var(--theme-text)', borderColor: 'var(--theme-border)' }}>
            <Settings size={16} /> {t('staffing.onb_settings', 'Settings')}
          </button>
          <button onClick={() => setShowWizard(true)} data-testid="new-onboarding-case-btn"
            className="inline-flex items-center gap-2 px-4 py-2 rounded-xl font-semibold text-slate-900"
            style={{ background: 'var(--color-brand-cyan, #19CDFF)' }}>
            <UserPlus size={16} /> {t('staffing.onb_create_case', 'Create Onboarding Case')}
          </button>
        </div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        {CARD_DEFS.map(([k, label, tone]) => (
          <div key={k} className="rounded-2xl p-4 border" style={surface} data-testid={`card-${k}`}>
            <div className="text-3xl font-bold" style={{ color: 'var(--theme-text)' }}>{cards[k] ?? 0}</div>
            <div className="mt-1"><Pill tone={tone}>{label}</Pill></div>
          </div>
        ))}
      </div>

      <div className="rounded-2xl border overflow-hidden" style={surface}>
        <div className="px-4 py-3 border-b flex items-center gap-2" style={{ borderColor: 'var(--theme-border)' }}>
          <ClipboardList size={16} style={{ color: 'var(--theme-text)' }} />
          <span className="font-semibold" style={{ color: 'var(--theme-text)' }}>{t('staffing.onb_cases', 'Onboarding Cases')}</span>
        </div>
        {loading ? (
          <div className="p-8 flex justify-center"><Loader2 className="animate-spin" style={{ color: 'var(--theme-text)' }} /></div>
        ) : cases.length === 0 ? (
          <div className="p-8 text-center opacity-70 text-sm" style={{ color: 'var(--theme-text)' }}>
            {t('staffing.onb_no_cases', 'No onboarding cases yet. Create one to invite a new recruit.')}
          </div>
        ) : (
          <div className="divide-y" style={{ borderColor: 'var(--theme-border)' }}>
            {cases.map((c) => (
              <button key={c.id} onClick={() => setOpenCase(c.id)} data-testid={`case-row-${c.id}`}
                className="w-full text-left px-4 py-3 hover:bg-white/[0.03] transition-colors flex items-center justify-between gap-3">
                <div className="min-w-0">
                  <div className="font-semibold truncate" style={{ color: 'var(--theme-text)' }}>
                    {c.person?.full_name || t('staffing.onb_new_recruit', 'New recruit')}
                  </div>
                  <div className="text-xs opacity-60 truncate" style={{ color: 'var(--theme-text)' }}>
                    {c.employment_proposal?.job_title || c.employment_proposal?.position || '—'} · {c.package || t('staffing.onb_no_package', 'no package')}
                  </div>
                </div>
                <div className="flex items-center gap-2 shrink-0">
                  <Pill tone={c.status === 'complete' ? 'green' : c.status?.includes('offer') ? 'blue' : 'amber'}>
                    {statusLabel(t, c.status)}
                  </Pill>
                  <ArrowRight size={16} style={{ color: 'var(--theme-text)' }} />
                </div>
              </button>
            ))}
          </div>
        )}
      </div>

      {showWizard && <CaseWizard headers={headers} onClose={() => setShowWizard(false)}
        onCreated={(id) => { setShowWizard(false); load(); setOpenCase(id); }} />}
      {showTemplates && <TemplateManager headers={headers} onClose={() => setShowTemplates(false)} />}
      {showSettings && <PackSettings headers={headers} onClose={() => setShowSettings(false)} />}
      {openCase && <CaseDetail headers={headers} caseId={openCase}
        onClose={() => { setOpenCase(null); load(); }} />}
    </div>
  );
}

function WizardField({ label, k, on, val, type = 'text' }) {
  return (
    <label className="block">
      <span className="text-xs opacity-70" style={{ color: 'var(--theme-text)' }}>{label}</span>
      <input type={type} value={val} onChange={on} data-testid={`wizard-${k}`}
        className="mt-1 w-full rounded-lg px-3 py-2 text-sm border bg-transparent"
        style={{ color: 'var(--theme-text)', borderColor: 'var(--theme-border)' }} />
    </label>
  );
}

function WizardSelect({ label, k, val, on, options, placeholder }) {
  const { t } = useTranslation();
  const ph = placeholder || t('staffing.onb_select', 'Select…');
  return (
    <label className="block">
      <span className="text-xs opacity-70" style={{ color: 'var(--theme-text)' }}>{label}</span>
      <select value={val} onChange={on} data-testid={`wizard-${k}`}
        className="mt-1 w-full rounded-lg px-3 py-2 text-sm border bg-transparent"
        style={{ color: 'var(--theme-text)', borderColor: 'var(--theme-border)' }}>
        <option value="" style={{ color: '#111' }}>{ph}</option>
        {options.map((o) => <option key={o} value={o} style={{ color: '#111' }}>{o}</option>)}
      </select>
    </label>
  );
}

// Editable dropdown (native datalist) — HR can pick a suggestion or type a custom value.
function WizardCombo({ label, k, val, on, options, placeholder }) {
  const listId = `dl-${k}`;
  return (
    <label className="block">
      <span className="text-xs opacity-70" style={{ color: 'var(--theme-text)' }}>{label}</span>
      <input list={listId} value={val} onChange={on} data-testid={`wizard-${k}`} placeholder={placeholder}
        className="mt-1 w-full rounded-lg px-3 py-2 text-sm border bg-transparent"
        style={{ color: 'var(--theme-text)', borderColor: 'var(--theme-border)' }} />
      <datalist id={listId}>{options.map((o) => <option key={o} value={o} />)}</datalist>
    </label>
  );
}

const DEPARTMENTS = ['Service', 'Sales', 'Operations', 'Installation', 'Warehouse / Stores',
  'Finance', 'HR', 'Marketing', 'IT', 'Customer Support', 'Management', 'Admin'];
const EMPLOYMENT_TYPES = ['Permanent full time', 'Permanent part time', 'Fixed-term contract',
  'Temporary', 'Apprenticeship', 'Zero-hours', 'Consultant / Contractor'];
const PROBATION_PERIODS = ['None', '1 month', '3 months', '6 months', '12 months'];
const NOTICE_PERIODS = ['1 week', '2 weeks', '1 month', '2 months', '3 months', '6 months'];
const HOLIDAY_OPTIONS = ['20 days', '22 days', '25 days', '28 days (incl. bank holidays)',
  '30 days', '33 days (incl. bank holidays)'];
const SITE_OPTIONS = ['Head Office', 'Remote', 'Field-based', 'Hybrid'];
const COMPANY_OPTIONS = ['Pulse Fitness'];

/* ───────────────── Create Onboarding Case Wizard ───────────────── */
function CaseWizard({ headers, onClose, onCreated }) {
  const { t } = useTranslation();
  const [step, setStep] = useState(1);
  const [f, setF] = useState({ legal_first_name: '', surname: '', preferred_name: '', personal_email: '', mobile: '', position: '', proposed_start_date: '' });
  const [prop, setProp] = useState({ employing_company: 'Pulse Fitness', job_title: '', department: '', site: '', line_manager: '', salary: '', hours_per_week: '', employment_type: 'Permanent full time', probation_period: '', notice_period: '', holiday_entitlement: '', authorised_signatory: '' });
  const [pkg, setPkg] = useState('standard');
  const [packages, setPackages] = useState([]);
  const [staffNames, setStaffNames] = useState([]);
  const [dup, setDup] = useState(null);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState('');
  const set = (k) => (e) => setF((p) => ({ ...p, [k]: e.target.value }));
  const setP = (k) => (e) => setProp((p) => ({ ...p, [k]: e.target.value }));

  useEffect(() => {
    axios.get(`${API}/staff-onboarding/packages`, { headers }).then(r => setPackages(r.data.packages || [])).catch(() => {});
    axios.get(`${API}/staffing/staff`, { headers }).then(r => setStaffNames((r.data.staff || []).map(s => s.full_name).filter(Boolean))).catch(() => {});
  }, [headers]);

  const checkDup = async () => {
    if (!f.personal_email && !f.mobile) { setStep(2); return; }
    setBusy(true);
    try {
      const r = await axios.post(`${API}/staff-onboarding/cases/duplicate-check`,
        { personal_email: f.personal_email, mobile: f.mobile, legal_name: `${f.legal_first_name} ${f.surname}`.trim() }, { headers });
      setDup(r.data);
      setStep(2);
    } catch (e) { setStep(2); } finally { setBusy(false); }
  };

  const create = async () => {
    setBusy(true); setErr('');
    try {
      const c = await axios.post(`${API}/staff-onboarding/cases`, { ...f }, { headers });
      const id = c.data.id;
      await axios.patch(`${API}/staff-onboarding/cases/${id}`, { package: pkg, employment_proposal: { ...prop, proposed_start_date: f.proposed_start_date, preferred_name: f.preferred_name } }, { headers });
      onCreated(id);
    } catch (e) {
      setErr(e?.response?.data?.detail?.message || e?.response?.data?.detail || t('staffing.onb_create_failed', 'Could not create case'));
      setBusy(false);
    }
  };

  const Field = WizardField;

  return (
    <Modal onClose={onClose} title={t('staffing.onb_create_case', 'Create Onboarding Case')} testId="case-wizard">
      <div className="flex gap-2 mb-4 text-xs">
        {[t('staffing.onb_step_recruit', 'Select Recruit'), t('staffing.onb_step_proposal', 'Employment Proposal'), t('staffing.onb_step_package', 'Package')].map((s, i) => (
          <div key={s} className={`px-2 py-1 rounded-full ${step === i + 1 ? 'bg-cyan-500/20 text-cyan-300' : 'opacity-50'}`}
            style={{ color: step === i + 1 ? undefined : 'var(--theme-text)' }}>{i + 1}. {s}</div>
        ))}
      </div>

      {step === 1 && (
        <div className="space-y-3">
          <div className="grid grid-cols-2 gap-3">
            <Field label={t('staffing.onb_legal_first', 'Legal first name')} k="legal_first_name" on={set('legal_first_name')} val={f.legal_first_name} />
            <Field label={t('staffing.onb_surname', 'Surname')} k="surname" on={set('surname')} val={f.surname} />
            <Field label={t('staffing.onb_preferred', 'Preferred name')} k="preferred_name" on={set('preferred_name')} val={f.preferred_name} />
            <Field label={t('staffing.onb_personal_email', 'Personal email')} k="personal_email" on={set('personal_email')} val={f.personal_email} />
            <Field label={t('staffing.onb_mobile', 'Mobile')} k="mobile" on={set('mobile')} val={f.mobile} />
            <Field label={t('staffing.onb_position', 'Position')} k="position" on={set('position')} val={f.position} />
            <Field label={t('staffing.onb_start_date', 'Proposed start date')} k="proposed_start_date" on={set('proposed_start_date')} val={f.proposed_start_date} type="date" />
          </div>
          {dup?.has_active_employee && (
            <div className="flex items-center gap-2 text-amber-300 text-sm" data-testid="dup-warning">
              <AlertTriangle size={16} /> {t('staffing.onb_dup_warning', 'An active staff record already exists — avoid duplicates.')}
            </div>
          )}
          <div className="flex justify-end">
            <button onClick={checkDup} disabled={busy} data-testid="wizard-next-1"
              className="px-4 py-2 rounded-lg text-slate-900 font-semibold" style={{ background: 'var(--color-brand-cyan,#19CDFF)' }}>
              {busy ? '…' : t('staffing.onb_next', 'Next')}
            </button>
          </div>
        </div>
      )}

      {step === 2 && (
        <div className="space-y-3">
          <div className="grid grid-cols-2 gap-3">
            <WizardCombo label={t('staffing.onb_employing_company', 'Employing company')} k="ec" on={setP('employing_company')} val={prop.employing_company} options={COMPANY_OPTIONS} />
            <Field label={t('staffing.onb_job_title', 'Job title')} k="job_title" on={setP('job_title')} val={prop.job_title} />
            <WizardSelect label={t('staffing.onb_department', 'Department')} k="department" on={setP('department')} val={prop.department} options={DEPARTMENTS} />
            <WizardCombo label={t('staffing.onb_site', 'Site / place of work')} k="site" on={setP('site')} val={prop.site} options={SITE_OPTIONS} placeholder={t('staffing.onb_select_type', 'Select or type…')} />
            <WizardCombo label={t('staffing.onb_line_manager', 'Line manager')} k="line_manager" on={setP('line_manager')} val={prop.line_manager} options={staffNames} placeholder={t('staffing.onb_select_type', 'Select or type…')} />
            <Field label={t('staffing.onb_salary', 'Salary')} k="salary" on={setP('salary')} val={prop.salary} />
            <Field label={t('staffing.onb_hours', 'Hours per week')} k="hours" on={setP('hours_per_week')} val={prop.hours_per_week} type="number" />
            <WizardSelect label={t('staffing.onb_employment_type', 'Employment type')} k="etype" on={setP('employment_type')} val={prop.employment_type} options={EMPLOYMENT_TYPES} />
            <WizardSelect label={t('staffing.onb_probation', 'Probation period')} k="probation" on={setP('probation_period')} val={prop.probation_period} options={PROBATION_PERIODS} />
            <WizardSelect label={t('staffing.onb_notice', 'Notice period')} k="notice" on={setP('notice_period')} val={prop.notice_period} options={NOTICE_PERIODS} />
            <WizardSelect label={t('staffing.onb_holiday', 'Holiday entitlement')} k="holiday" on={setP('holiday_entitlement')} val={prop.holiday_entitlement} options={HOLIDAY_OPTIONS} />
            <WizardCombo label={t('staffing.onb_signatory', 'Authorised signatory')} k="signatory" on={setP('authorised_signatory')} val={prop.authorised_signatory} options={staffNames} placeholder={t('staffing.onb_select_type', 'Select or type…')} />
          </div>
          <div className="flex justify-between">
            <button onClick={() => setStep(1)} className="px-4 py-2 rounded-lg border" style={{ color: 'var(--theme-text)', borderColor: 'var(--theme-border)' }}>{t('staffing.onb_back', 'Back')}</button>
            <button onClick={() => setStep(3)} data-testid="wizard-next-2" className="px-4 py-2 rounded-lg text-slate-900 font-semibold" style={{ background: 'var(--color-brand-cyan,#19CDFF)' }}>{t('staffing.onb_next', 'Next')}</button>
          </div>
        </div>
      )}

      {step === 3 && (
        <div className="space-y-3">
          <span className="text-xs opacity-70" style={{ color: 'var(--theme-text)' }}>{t('staffing.onb_package', 'Onboarding package')}</span>
          <div className="grid grid-cols-3 gap-2">
            {packages.map((p) => (
              <button key={p.id} onClick={() => setPkg(p.id)} data-testid={`pkg-${p.id}`}
                className={`px-3 py-2 rounded-lg border text-sm text-left ${pkg === p.id ? 'ring-2 ring-cyan-400' : ''}`}
                style={{ color: 'var(--theme-text)', borderColor: 'var(--theme-border)' }}>{p.name}</button>
            ))}
          </div>
          {err && <div className="text-red-400 text-sm">{err}</div>}
          <div className="flex justify-between">
            <button onClick={() => setStep(2)} className="px-4 py-2 rounded-lg border" style={{ color: 'var(--theme-text)', borderColor: 'var(--theme-border)' }}>{t('staffing.onb_back', 'Back')}</button>
            <button onClick={create} disabled={busy} data-testid="wizard-create-case"
              className="px-4 py-2 rounded-lg text-slate-900 font-semibold" style={{ background: 'var(--color-brand-cyan,#19CDFF)' }}>
              {busy ? t('staffing.onb_creating', 'Creating…') : t('staffing.onb_create_case_btn', 'Create case')}
            </button>
          </div>
        </div>
      )}
    </Modal>
  );
}

/* ───────────────── Case Detail ───────────────── */
function CaseDetail({ headers, caseId, onClose }) {
  const { t } = useTranslation();
  const [data, setData] = useState(null);
  const [tab, setTab] = useState('overview');
  const [busy, setBusy] = useState(false);
  const [invite, setInvite] = useState(null);
  const [templates, setTemplates] = useState({ offer: [], contract: [] });
  const [audit, setAudit] = useState([]);
  const [msg, setMsg] = useState('');
  const [dupResult, setDupResult] = useState(null);
  const [consResult, setConsResult] = useState(null);
  const [aiBusy, setAiBusy] = useState('');

  const load = useCallback(async () => {
    const [d, tRes] = await Promise.all([
      axios.get(`${API}/staff-onboarding/cases/${caseId}`, { headers }),
      axios.get(`${API}/staff-onboarding/templates`, { headers }),
    ]);
    setData(d.data); setTemplates(tRes.data);
  }, [caseId, headers]);
  useEffect(() => { load(); }, [load]);

  const act = async (fn, ok) => {
    setBusy(true); setMsg('');
    try { await fn(); setMsg(ok || t('staffing.onb_done', 'Done')); await load(); }
    catch (e) { setMsg('⚠ ' + (e?.response?.data?.detail?.message || e?.response?.data?.detail || t('staffing.onb_action_failed', 'Action failed'))); }
    finally { setBusy(false); }
  };

  const doInvite = () => act(async () => {
    const r = await axios.post(`${API}/staff-onboarding/cases/${caseId}/invite`, { expiry_days: 14 }, { headers });
    setInvite(r.data);
  }, t('staffing.onb_invite_created', 'Invitation created'));
  const setRTW = () => act(() => axios.post(`${API}/staff-onboarding/cases/${caseId}/right-to-work`, { method: 'share_code', result: 'verified' }, { headers }), t('staffing.onb_rtw_verified', 'Right to Work verified'));
  const paperworkComplete = () => act(() => axios.post(`${API}/staff-onboarding/cases/${caseId}/paperwork-complete`, { comment: 'Reviewed & ready for offer' }, { headers }), t('staffing.onb_paperwork_complete_msg', 'Paperwork marked complete'));
  const createOffer = (tid) => act(() => axios.post(`${API}/staff-onboarding/cases/${caseId}/offer`, { template_id: tid, conditions: [{ label: 'Satisfactory Right to Work', required: true, status: 'pending' }] }, { headers }), t('staffing.onb_offer_drafted', 'Offer drafted'));
  const approveOffer = () => act(() => axios.post(`${API}/staff-onboarding/cases/${caseId}/offer/approve`, {}, { headers }), t('staffing.onb_offer_approved', 'Offer approved'));
  const issueOffer = () => act(() => axios.post(`${API}/staff-onboarding/cases/${caseId}/offer/issue`, {}, { headers }), t('staffing.onb_offer_issued_msg', 'Offer issued to portal'));
  const createContract = (tid) => act(() => axios.post(`${API}/staff-onboarding/cases/${caseId}/contract`, { template_id: tid }, { headers }), t('staffing.onb_contract_drafted', 'Contract drafted'));
  const approveContract = () => act(() => axios.post(`${API}/staff-onboarding/cases/${caseId}/contract/approve`, {}, { headers }), t('staffing.onb_contract_approved', 'Contract approved'));
  const issueContract = () => act(() => axios.post(`${API}/staff-onboarding/cases/${caseId}/contract/issue`, {}, { headers }), t('staffing.onb_contract_issued_msg', 'Contract issued to portal'));
  const countersign = () => act(() => axios.post(`${API}/staff-onboarding/cases/${caseId}/contract/countersign`, { signature_name: 'Authorised Signatory', signature_method: 'typed' }, { headers }), t('staffing.onb_countersigned', 'Contract countersigned & locked'));
  const activate = () => act(() => axios.post(`${API}/staff-onboarding/cases/${caseId}/activate`, {}, { headers }), t('staffing.onb_activated', 'Employee activated'));
  const loadAudit = () => axios.get(`${API}/staff-onboarding/cases/${caseId}/audit`, { headers }).then(r => setAudit(r.data.events || []));
  const dupScan = async () => { setAiBusy('dup'); setDupResult(null); try { const r = await axios.post(`${API}/staff-onboarding/cases/${caseId}/ai/duplicate-scan`, {}, { headers }); setDupResult(r.data); } catch (e) { setDupResult({ error: e?.response?.data?.detail || t('staffing.onb_ai_scan_failed', 'AI scan failed') }); } finally { setAiBusy(''); } };
  const aiConsistency = async () => { setAiBusy('cons'); setConsResult(null); try { const r = await axios.post(`${API}/staff-onboarding/cases/${caseId}/ai/consistency`, {}, { headers }); setConsResult(r.data); } catch (e) { setConsResult({ error: e?.response?.data?.detail || t('staffing.onb_ai_check_failed', 'AI check failed') }); } finally { setAiBusy(''); } };

  if (!data) return <Modal onClose={onClose} title={t('staffing.onb_loading', 'Loading…')} testId="case-detail-loading"><Loader2 className="animate-spin mx-auto" style={{ color: 'var(--theme-text)' }} /></Modal>;

  const c = data.case, offer = c.offer, contract = c.contract;
  const TABS = [['overview', t('staffing.onb_tab_overview', 'Overview'), FileText], ['paperwork', t('staffing.onb_tab_paperwork', 'Paperwork'), ClipboardList],
    ['checks', t('staffing.onb_tab_checks', 'DBS / RTW'), ShieldCheck],
    ['offer', t('staffing.onb_tab_offer', 'Offer Letter'), ScrollText], ['contract', t('staffing.onb_tab_contract', 'Contract'), FileSignature],
    ['activate', t('staffing.onb_tab_activate', 'Activate'), CheckCircle2], ['audit', t('staffing.onb_tab_audit', 'Audit'), History]];

  return (
    <Modal onClose={onClose} title={`${data.person?.full_name || t('staffing.onb_recruit', 'Recruit')} — ${statusLabel(t, c.status)}`} testId="case-detail" wide>
      <div className="flex gap-1 mb-4 flex-wrap">
        {TABS.map(([id, label, Icon]) => (
          <button key={id} onClick={() => { setTab(id); if (id === 'audit') loadAudit(); }} data-testid={`case-tab-${id}`}
            className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm ${tab === id ? 'bg-cyan-500/20 text-cyan-300' : 'opacity-70'}`}
            style={{ color: tab === id ? undefined : 'var(--theme-text)' }}><Icon size={14} /> {label}</button>
        ))}
      </div>
      {msg && <div className="mb-3 text-sm px-3 py-2 rounded-lg" data-testid="case-action-msg"
        style={{ background: 'var(--theme-surface)', color: 'var(--theme-text)' }}>{msg}</div>}

      {tab === 'overview' && (
        <div className="space-y-3 text-sm" style={{ color: 'var(--theme-text)' }}>
          <Row k={t('staffing.onb_position', 'Position')} v={c.employment_proposal?.job_title || c.employment_proposal?.position} />
          <Row k={t('staffing.onb_company_site', 'Company / site')} v={`${c.employment_proposal?.employing_company || '—'} · ${c.employment_proposal?.site || '—'}`} />
          <Row k={t('staffing.onb_salary', 'Salary')} v={c.employment_proposal?.salary} />
          <Row k={t('staffing.onb_package_label', 'Package')} v={c.package} />
          <Row k={t('staffing.onb_docs_uploaded', 'Documents uploaded')} v={data.documents?.length} />
          <div className="pt-2 flex gap-2 flex-wrap">
            <Btn onClick={doInvite} busy={busy} testId="btn-invite">{t('staffing.onb_send_invite', 'Send portal invitation')}</Btn>
            {invite && (
              <div className="w-full mt-2 p-3 rounded-lg text-xs" style={{ background: 'var(--theme-surface)', color: 'var(--theme-text)' }} data-testid="invite-link">
                {t('staffing.onb_portal_link', 'New Starter Portal link (share securely):')}<br />
                <code className="text-cyan-300 break-all">{window.location.origin}/new-starter/{invite.invite_token}</code>
              </div>
            )}
          </div>

          <div className="pt-3 border-t" style={{ borderColor: 'var(--theme-border)' }}>
            <div className="text-xs opacity-70 mb-2">{t('staffing.onb_documents_pdf', 'Documents (PDF)')}</div>
            <div className="flex gap-2 flex-wrap">
              <Btn onClick={() => openPdf(`${API}/staff-onboarding/cases/${caseId}/forms.pdf`, headers)} testId="btn-forms-pdf"><Download size={13} /> {t('staffing.onb_completed_forms', 'Completed forms')}</Btn>
              <Btn onClick={() => openPdf(`${API}/staff-onboarding/cases/${caseId}/pack.pdf`, headers)} testId="btn-pack-pdf" primary><Download size={13} /> {t('staffing.onb_onboarding_pack', 'Onboarding pack')}</Btn>
            </div>
          </div>

          <div className="pt-3 border-t" style={{ borderColor: 'var(--theme-border)' }}>
            <div className="flex items-center gap-2 mb-2"><span className="text-xs opacity-70">{t('staffing.onb_ai_assist', 'AI assist')}</span></div>
            <Btn onClick={dupScan} busy={aiBusy === 'dup'} testId="btn-ai-duplicate-scan"><ShieldAlert size={13} /> {t('staffing.onb_ai_dup_scan', 'AI duplicate scan')}</Btn>
            {dupResult && (
              <div className="mt-2 p-3 rounded-lg text-xs" data-testid="ai-duplicate-result" style={{ background: 'var(--theme-surface)' }}>
                {dupResult.error ? <span className="text-red-400">{dupResult.error}</span> : (
                  <>
                    <div className="opacity-80 mb-1">{dupResult.summary || `${(dupResult.matches || []).length} ${t('staffing.onb_possible_matches', 'possible match(es)')}`}</div>
                    {(dupResult.matches || []).map((m, i) => (
                      <div key={i} className="flex items-start gap-2 py-1">
                        <Pill tone={m.confidence >= 75 ? 'red' : 'amber'}>{m.confidence}%</Pill>
                        <div><span className="font-medium">{m.full_name}</span>{m.active_employee && <span className="ml-1 text-emerald-400">{t('staffing.onb_active_paren', '(active)')}</span>}
                          <div className="opacity-60">{(m.reasons || []).join('; ')}</div></div>
                      </div>
                    ))}
                    {(dupResult.matches || []).length === 0 && <div className="text-emerald-400">{t('staffing.onb_no_dups', 'No likely duplicates found ✓')}</div>}
                  </>
                )}
              </div>
            )}
          </div>
        </div>
      )}

      {tab === 'paperwork' && (
        <div className="space-y-3 text-sm" style={{ color: 'var(--theme-text)' }}>
          <PaperworkChecks headers={headers} caseId={caseId} />
          <div className="flex gap-2 flex-wrap pt-2">
            <Btn onClick={setRTW} busy={busy} testId="btn-verify-rtw"><ShieldCheck size={14} /> {t('staffing.onb_verify_rtw', 'Verify Right to Work')}</Btn>
            <Btn onClick={paperworkComplete} busy={busy} testId="btn-paperwork-complete" primary>{t('staffing.onb_mark_paperwork', 'Mark Paperwork Complete')}</Btn>
          </div>
        </div>
      )}

      {tab === 'checks' && (
        <ChecksPanel headers={headers} caseId={caseId} />
      )}

      {tab === 'offer' && (
        <div className="space-y-3 text-sm" style={{ color: 'var(--theme-text)' }}>
          {!offer && (
            <>
              <div className="opacity-70">{t('staffing.onb_create_offer', 'Create an offer from an approved template (paperwork must be complete):')}</div>
              <div className="grid grid-cols-2 gap-2">
                {templates.offer.map((tpl) => (
                  <button key={tpl.id} onClick={() => createOffer(tpl.id)} data-testid={`offer-tmpl-${tpl.key}`}
                    className="px-3 py-2 rounded-lg border text-left" style={{ color: 'var(--theme-text)', borderColor: 'var(--theme-border)' }}>
                    {tpl.title}{tpl.is_sample && <span className="ml-1 text-[10px] text-amber-300">{t('staffing.onb_sample', 'SAMPLE')}</span>}
                  </button>
                ))}
              </div>
            </>
          )}
          {offer && (
            <>
              <div className="flex items-center gap-2"><Pill tone="blue">{offer.status}</Pill>{offer.conditional && <Pill tone="amber">{t('staffing.onb_conditional', 'Conditional')}</Pill>}
                <button onClick={() => openPdf(`${API}/staff-onboarding/cases/${caseId}/offer.pdf`, headers)} data-testid="btn-offer-pdf"
                  className="ml-auto inline-flex items-center gap-1.5 text-xs px-3 py-1.5 rounded-lg border" style={{ color: 'var(--theme-text)', borderColor: 'var(--theme-border)' }}>
                  <Download size={13} /> {t('staffing.onb_pdf', 'PDF')}</button></div>
              <pre className="whitespace-pre-wrap p-3 rounded-lg text-xs max-h-64 overflow-auto" data-testid="offer-preview"
                style={{ background: 'var(--theme-surface)' }}>{offer.rendered}</pre>
              <div className="flex gap-2 flex-wrap">
                {offer.status === 'draft' && <Btn onClick={approveOffer} busy={busy} testId="btn-approve-offer">{t('staffing.onb_approve', 'Approve')}</Btn>}
                {(offer.status === 'approved') && <Btn onClick={issueOffer} busy={busy} testId="btn-issue-offer" primary>{t('staffing.onb_issue_portal', 'Issue to portal')}</Btn>}
                {offer.status === 'issued' && <Pill tone="amber">{t('staffing.onb_awaiting_response', 'Awaiting recruit response')}</Pill>}
                {offer.status === 'accepted' && <Pill tone="green">{t('staffing.onb_accepted', 'Accepted ✓')}</Pill>}
              </div>
            </>
          )}
        </div>
      )}

      {tab === 'contract' && (
        <div className="space-y-3 text-sm" style={{ color: 'var(--theme-text)' }}>
          {!contract && (
            <>
              {offer?.status !== 'accepted'
                ? <div className="text-amber-300">{t('staffing.onb_offer_first', 'The offer must be accepted before creating the contract.')}</div>
                : <>
                    <div className="opacity-70">{t('staffing.onb_create_contract', 'Create the contract from the accepted offer:')}</div>
                    <div className="grid grid-cols-2 gap-2">
                      {templates.contract.map((tpl) => (
                        <button key={tpl.id} onClick={() => createContract(tpl.id)} data-testid={`contract-tmpl-${tpl.key}`}
                          className="px-3 py-2 rounded-lg border text-left" style={{ color: 'var(--theme-text)', borderColor: 'var(--theme-border)' }}>
                          {tpl.title}{tpl.is_sample && <span className="ml-1 text-[10px] text-amber-300">{t('staffing.onb_sample', 'SAMPLE')}</span>}
                        </button>
                      ))}
                    </div>
                  </>}
            </>
          )}
          {contract && (
            <>
              <div className="flex items-center gap-2"><Pill tone="blue">{contract.status}</Pill>
                {contract.differences?.length > 0
                  ? <Pill tone="red">{t('staffing.onb_contract_differs', 'Contract differs from offer')} ({contract.differences.length})</Pill>
                  : <Pill tone="green">{t('staffing.onb_matches_offer', 'Matches accepted offer')}</Pill>}
                <button onClick={() => openPdf(`${API}/staff-onboarding/cases/${caseId}/contract.pdf`, headers)} data-testid="btn-contract-pdf"
                  className="ml-auto inline-flex items-center gap-1.5 text-xs px-3 py-1.5 rounded-lg border" style={{ color: 'var(--theme-text)', borderColor: 'var(--theme-border)' }}>
                  <Download size={13} /> {t('staffing.onb_pdf', 'PDF')}</button></div>
              <pre className="whitespace-pre-wrap p-3 rounded-lg text-xs max-h-64 overflow-auto" data-testid="contract-preview"
                style={{ background: 'var(--theme-surface)' }}>{contract.rendered}</pre>
              <div className="flex gap-2 flex-wrap">
                {contract.status === 'draft' && <Btn onClick={approveContract} busy={busy} testId="btn-approve-contract">{t('staffing.onb_approve', 'Approve')}</Btn>}
                {contract.status === 'approved' && <Btn onClick={issueContract} busy={busy} testId="btn-issue-contract" primary>{t('staffing.onb_issue_portal', 'Issue to portal')}</Btn>}
                {contract.status === 'issued' && <Pill tone="amber">{t('staffing.onb_awaiting_signature', 'Awaiting recruit signature')}</Pill>}
                {(contract.status === 'employee_signed' || c.status === 'awaiting_employer_signature') && <Btn onClick={countersign} busy={busy} testId="btn-countersign" primary>{t('staffing.onb_employer_countersign', 'Employer countersign')}</Btn>}
                {contract.status === 'fully_signed' && <Pill tone="green">{t('staffing.onb_fully_signed', 'Fully signed & locked ✓')}</Pill>}
              </div>
              <div className="pt-1">
                <Btn onClick={aiConsistency} busy={aiBusy === 'cons'} testId="btn-ai-consistency"><ShieldAlert size={13} /> {t('staffing.onb_ai_consistency', 'AI consistency check')}</Btn>
                {consResult && (
                  <div className="mt-2 p-3 rounded-lg text-xs" data-testid="ai-consistency-result" style={{ background: 'var(--theme-surface)' }}>
                    {consResult.error ? <span className="text-red-400">{consResult.error}</span> : (
                      <>
                        <div className="flex items-center gap-2 mb-1">{t('staffing.onb_risk', 'Risk:')}
                          <Pill tone={consResult.risk_level === 'high' ? 'red' : consResult.risk_level === 'medium' ? 'amber' : 'green'}>{consResult.risk_level || 'n/a'}</Pill></div>
                        <div className="opacity-80">{consResult.summary}</div>
                        {(consResult.inconsistencies || []).map((x, i) => (
                          <div key={i} className="opacity-70 mt-1">• <b>{x.field}</b>: {t('staffing.onb_offer_lc', 'offer')} “{x.offer}” {t('staffing.onb_vs_contract', 'vs contract')} “{x.contract}” — {x.note}</div>
                        ))}
                      </>
                    )}
                  </div>
                )}
              </div>
            </>
          )}
        </div>
      )}

      {tab === 'activate' && (
        <div className="space-y-4">
          <ActivatePanel headers={headers} caseId={caseId} onActivate={activate} busy={busy} status={c.status} />
          <LineManagerPanel headers={headers} caseId={caseId} />
        </div>
      )}

      {tab === 'audit' && (
        <div className="space-y-1.5 text-sm max-h-96 overflow-auto" data-testid="audit-trail" style={{ color: 'var(--theme-text)' }}>
          {audit.length === 0 && <div className="opacity-60">{t('staffing.onb_no_events', 'No events.')}</div>}
          {audit.map((e) => (
            <div key={e.id} className="flex items-center justify-between gap-2 px-3 py-2 rounded-lg" style={{ background: 'var(--theme-surface)' }}>
              <span className="font-medium">{e.event.replace(/_/g, ' ')}</span>
              <span className="text-xs opacity-60">{e.user_name || '—'} · {new Date(e.at).toLocaleString()}</span>
            </div>
          ))}
        </div>
      )}
    </Modal>
  );
}

function PaperworkChecks({ headers, caseId }) {
  const [st, setSt] = useState(null);
  useEffect(() => { axios.get(`${API}/staff-onboarding/cases/${caseId}/paperwork-state`, { headers }).then(r => setSt(r.data)).catch(() => {}); }, [caseId, headers]);
  if (!st) return <Loader2 className="animate-spin" style={{ color: 'var(--theme-text)' }} />;
  return (
    <div className="grid grid-cols-2 gap-2" data-testid="paperwork-checks">
      {Object.entries(st.checks).map(([k, v]) => (
        <div key={k} className="flex items-center gap-2 px-3 py-2 rounded-lg" style={{ background: 'var(--theme-surface)' }}>
          {v ? <CheckCircle2 size={15} className="text-emerald-400" /> : <X size={15} className="text-red-400" />}
          <span className="text-xs capitalize" style={{ color: 'var(--theme-text)' }}>{k.replace(/_/g, ' ')}</span>
        </div>
      ))}
    </div>
  );
}

function ActivatePanel({ headers, caseId, onActivate, busy, status }) {
  const { t } = useTranslation();
  const [st, setSt] = useState(null);
  useEffect(() => { axios.get(`${API}/staff-onboarding/cases/${caseId}/activation-state`, { headers }).then(r => setSt(r.data)).catch(() => {}); }, [caseId, headers, status]);
  return (
    <div className="space-y-3 text-sm" style={{ color: 'var(--theme-text)' }} data-testid="activate-panel">
      {st && Object.entries(st.checks).map(([k, v]) => (
        <div key={k} className="flex items-center gap-2">
          {v ? <CheckCircle2 size={15} className="text-emerald-400" /> : <X size={15} className="text-red-400" />}
          <span className="capitalize">{k.replace(/_/g, ' ')}</span>
        </div>
      ))}
      {status === 'complete'
        ? <Pill tone="green">{t('staffing.onb_activated_pill', 'Employee activated — staff portal enabled ✓')}</Pill>
        : <Btn onClick={onActivate} busy={busy} testId="btn-activate" primary disabled={!st?.ready}>{t('staffing.onb_activate_member', 'Activate Staff Member')}</Btn>}
    </div>
  );
}

function LineManagerPanel({ headers, caseId }) {
  const { t } = useTranslation();
  const [managers, setManagers] = useState([]);
  const [current, setCurrent] = useState(null);
  const [sel, setSel] = useState('');
  const [busy, setBusy] = useState(false);
  const [ok, setOk] = useState(false);
  useEffect(() => {
    axios.get(`${API}/staff-onboarding/managers`, { headers }).then(r => setManagers(r.data.managers || [])).catch(() => {});
    axios.get(`${API}/staff-onboarding/cases/${caseId}/line-manager`, { headers })
      .then(r => { setCurrent(r.data); setSel(r.data.line_manager_staff_id || ''); }).catch(() => {});
  }, [caseId, headers]);
  const save = async () => {
    if (!sel) return;
    setBusy(true); setOk(false);
    try {
      const r = await axios.post(`${API}/staff-onboarding/cases/${caseId}/line-manager`, { line_manager_staff_id: sel }, { headers });
      setCurrent({ line_manager_staff_id: sel, line_manager_name: r.data.line_manager_name }); setOk(true);
    } finally { setBusy(false); }
  };
  return (
    <div className="rounded-xl p-4 border" style={{ borderColor: 'var(--theme-border)' }} data-testid="line-manager-panel">
      <div className="text-sm font-semibold mb-1" style={{ color: 'var(--theme-text)' }}>{t('staffing.onb_line_manager_access', 'Line manager (system access)')}</div>
      <p className="text-xs mb-3" style={{ color: 'var(--theme-text-muted)' }}>{t('staffing.onb_line_manager_note', 'Assign a line manager — they approve which modules this employee can use, in Staffing → People → Team Access.')}</p>
      <div className="flex flex-wrap items-center gap-2">
        <select value={sel} onChange={(e) => setSel(e.target.value)} data-testid="line-manager-select"
          className="rounded-lg border px-3 py-2 text-sm" style={{ borderColor: 'var(--theme-border)', background: 'var(--theme-surface)', color: 'var(--theme-text)' }}>
          <option value="">{t('staffing.onb_select_line_manager', 'Select a line manager…')}</option>
          {managers.map((m) => <option key={m.staff_id} value={m.staff_id}>{m.full_name}{m.role ? ` — ${m.role}` : ''}</option>)}
        </select>
        <Btn onClick={save} busy={busy} testId="line-manager-save" primary disabled={!sel}>{t('staffing.onb_assign', 'Assign')}</Btn>
        {ok && <span className="text-xs text-emerald-400" data-testid="line-manager-ok">{t('staffing.onb_assigned', 'Assigned ✓')}</span>}
      </div>
      {current?.line_manager_name && !ok && <div className="text-xs mt-2" style={{ color: 'var(--theme-text-muted)' }}>{t('staffing.onb_current', 'Current:')} {current.line_manager_name}</div>}
    </div>
  );
}

/* ───────────────── Checks: DBS + Right to Work ───────────────── */
function ChecksPanel({ headers, caseId }) {
  const { t } = useTranslation();
  const [opts, setOpts] = useState(null);
  const [state, setState] = useState(null);
  const [providers, setProviders] = useState([]);
  const [busy, setBusy] = useState('');
  const [msg, setMsg] = useState('');
  const [rtw, setRtw] = useState({ method: 'share_code', result: 'verified', document_type: '', share_code: '', expiry: '', notes: '', provider: 'manual', provider_reference: '' });
  const [dbs, setDbs] = useState({ level: 'basic', status: 'requested', certificate_number: '', issue_date: '', notes: '', provider: 'manual', provider_reference: '' });

  const load = useCallback(async () => {
    const [o, s, p] = await Promise.all([
      axios.get(`${API}/staff-onboarding/checks/options`, { headers }),
      axios.get(`${API}/staff-onboarding/cases/${caseId}/checks`, { headers }),
      axios.get(`${API}/staff-onboarding/verification/providers`, { headers }).catch(() => ({ data: { providers: [] } })),
    ]);
    setOpts(o.data); setState(s.data); setProviders(p.data.providers || []);
    if (s.data.right_to_work) setRtw((pv) => ({ ...pv, ...pick(s.data.right_to_work, ['result', 'document_type', 'share_code', 'expiry', 'notes', 'provider', 'provider_reference']), method: s.data.right_to_work.check_method || pv.method }));
    if (s.data.dbs) setDbs((pv) => ({ ...pv, ...pick(s.data.dbs, ['level', 'status', 'certificate_number', 'issue_date', 'notes', 'provider', 'provider_reference']) }));
  }, [caseId, headers]);
  useEffect(() => { load(); }, [load]);

  const run = async (fn, ok) => { setBusy(ok); setMsg(''); try { await fn(); setMsg(ok); await load(); } catch (e) { setMsg('⚠ ' + (e?.response?.data?.detail || t('staffing.onb_failed', 'Failed'))); } finally { setBusy(''); } };
  const saveRtw = () => run(() => axios.post(`${API}/staff-onboarding/cases/${caseId}/right-to-work`, rtw, { headers }), t('staffing.onb_rtw_saved', 'Right to Work saved'));
  const saveDbs = () => run(() => axios.post(`${API}/staff-onboarding/cases/${caseId}/dbs`, dbs, { headers }), t('staffing.onb_dbs_saved', 'DBS check saved'));
  const toggleReq = (v) => run(() => axios.post(`${API}/staff-onboarding/cases/${caseId}/dbs-required?required=${v}`, {}, { headers }), v ? t('staffing.onb_dbs_required', 'DBS marked required') : t('staffing.onb_dbs_not_required', 'DBS not required'));

  if (!opts || !state) return <Loader2 className="animate-spin" style={{ color: 'var(--theme-text)' }} />;
  const cur = state.right_to_work, curD = state.dbs;

  return (
    <div className="space-y-5 text-sm" style={{ color: 'var(--theme-text)' }} data-testid="checks-panel">
      {msg && <div className="text-xs px-3 py-2 rounded-lg" style={{ background: 'var(--theme-surface)' }} data-testid="checks-msg">{msg}</div>}

      {/* Right to Work */}
      <div className="rounded-xl border p-4" style={surface}>
        <div className="flex items-center gap-2 mb-3"><ShieldCheck size={16} className="text-cyan-400" />
          <span className="font-semibold">{t('staffing.onb_rtw_title', 'Right to Work')}</span>
          {cur && <Pill tone={['verified', 'time_limited'].includes(cur.result) ? 'green' : cur.result === 'follow_up' ? 'amber' : 'red'}>{cur.result}</Pill>}
        </div>
        <div className="grid grid-cols-2 gap-3">
          <Select label={t('staffing.onb_method', 'Method')} testId="rtw-method" value={rtw.method} onChange={(v) => setRtw((p) => ({ ...p, method: v }))} options={opts.rtw_methods} />
          <Select label={t('staffing.onb_result', 'Result')} testId="rtw-result" value={rtw.result} onChange={(v) => setRtw((p) => ({ ...p, result: v }))} options={opts.rtw_results} />
          <TextIn label={t('staffing.onb_doc_type', 'Document type')} testId="rtw-doc" value={rtw.document_type} onChange={(v) => setRtw((p) => ({ ...p, document_type: v }))} />
          <TextIn label={t('staffing.onb_share_code', 'Share code')} testId="rtw-share" value={rtw.share_code} onChange={(v) => setRtw((p) => ({ ...p, share_code: v }))} />
          <TextIn label={t('staffing.onb_expiry_tl', 'Expiry (if time-limited)')} testId="rtw-expiry" type="date" value={rtw.expiry} onChange={(v) => setRtw((p) => ({ ...p, expiry: v }))} />
          <Select label={t('staffing.onb_provider', 'Provider')} testId="rtw-provider" value={rtw.provider} onChange={(v) => setRtw((p) => ({ ...p, provider: v }))} options={providers.filter((p) => p.types.includes('rtw')).map((p) => ({ id: p.key, label: p.name + (p.configured ? '' : ` ${t('staffing.onb_manual_paren', '(manual)')}`) }))} />
          <TextIn label={t('staffing.onb_provider_ref', 'Provider reference')} testId="rtw-provider-ref" value={rtw.provider_reference} onChange={(v) => setRtw((p) => ({ ...p, provider_reference: v }))} />
          <TextIn label={t('staffing.onb_notes', 'Notes')} testId="rtw-notes" value={rtw.notes} onChange={(v) => setRtw((p) => ({ ...p, notes: v }))} />
        </div>
        <Btn onClick={saveRtw} busy={busy === t('staffing.onb_rtw_saved', 'Right to Work saved')} testId="btn-save-rtw" primary>{t('staffing.onb_save_rtw', 'Save Right to Work')}</Btn>
      </div>

      {/* DBS */}
      <div className="rounded-xl border p-4" style={surface}>
        <div className="flex items-center gap-2 mb-3"><ShieldAlert size={16} className="text-cyan-400" />
          <span className="font-semibold">{t('staffing.onb_dbs_title', 'DBS (Disclosure & Barring)')}</span>
          {curD && <Pill tone={curD.status === 'clear' ? 'green' : curD.status === 'not_clear' ? 'red' : 'amber'}>{curD.status}</Pill>}
          <label className="ml-auto inline-flex items-center gap-2 text-xs cursor-pointer" data-testid="dbs-required-toggle">
            <input type="checkbox" checked={!!state.dbs_required} onChange={(e) => toggleReq(e.target.checked)} />
            {t('staffing.onb_required_role', 'Required for this role')}
          </label>
        </div>
        <div className="grid grid-cols-2 gap-3">
          <Select label={t('staffing.onb_level', 'Level')} testId="dbs-level" value={dbs.level} onChange={(v) => setDbs((p) => ({ ...p, level: v }))} options={opts.dbs_levels} />
          <Select label={t('staffing.onb_status_label', 'Status')} testId="dbs-status" value={dbs.status} onChange={(v) => setDbs((p) => ({ ...p, status: v }))} options={opts.dbs_statuses} />
          <TextIn label={t('staffing.onb_cert_number', 'Certificate number')} testId="dbs-cert" value={dbs.certificate_number} onChange={(v) => setDbs((p) => ({ ...p, certificate_number: v }))} />
          <TextIn label={t('staffing.onb_issue_date', 'Issue date')} testId="dbs-issue" type="date" value={dbs.issue_date} onChange={(v) => setDbs((p) => ({ ...p, issue_date: v }))} />
          <Select label={t('staffing.onb_provider', 'Provider')} testId="dbs-provider" value={dbs.provider} onChange={(v) => setDbs((p) => ({ ...p, provider: v }))} options={providers.filter((p) => p.types.includes('dbs')).map((p) => ({ id: p.key, label: p.name + (p.configured ? '' : ` ${t('staffing.onb_manual_paren', '(manual)')}`) }))} />
          <TextIn label={t('staffing.onb_provider_ref', 'Provider reference')} testId="dbs-provider-ref" value={dbs.provider_reference} onChange={(v) => setDbs((p) => ({ ...p, provider_reference: v }))} />
          <TextIn label={t('staffing.onb_notes', 'Notes')} testId="dbs-notes" value={dbs.notes} onChange={(v) => setDbs((p) => ({ ...p, notes: v }))} />
        </div>
        <Btn onClick={saveDbs} busy={busy === t('staffing.onb_dbs_saved', 'DBS check saved')} testId="btn-save-dbs" primary>{t('staffing.onb_save_dbs', 'Save DBS Check')}</Btn>
      </div>
    </div>
  );
}

function pick(o, keys) { const r = {}; keys.forEach((k) => { if (o[k] != null) r[k] = o[k]; }); return r; }

function Select({ label, value, onChange, options, testId }) {
  return (
    <label className="block"><span className="text-xs opacity-70" style={{ color: 'var(--theme-text)' }}>{label}</span>
      <select value={value} onChange={(e) => onChange(e.target.value)} data-testid={testId}
        className="mt-1 w-full rounded-lg px-3 py-2 text-sm border bg-transparent"
        style={{ color: 'var(--theme-text)', borderColor: 'var(--theme-border)' }}>
        {options.map((o) => <option key={o.id} value={o.id} style={{ color: '#111' }}>{o.label}</option>)}
      </select></label>
  );
}
function TextIn({ label, value, onChange, testId, type = 'text' }) {
  return (
    <label className="block"><span className="text-xs opacity-70" style={{ color: 'var(--theme-text)' }}>{label}</span>
      <input type={type} value={value || ''} onChange={(e) => onChange(e.target.value)} data-testid={testId}
        className="mt-1 w-full rounded-lg px-3 py-2 text-sm border bg-transparent"
        style={{ color: 'var(--theme-text)', borderColor: 'var(--theme-border)' }} /></label>
  );
}

/* ───────────────── Template Builder (offer & contract) ───────────────── */
function TemplateManager({ headers, onClose }) {
  const { t } = useTranslation();
  const [kind, setKind] = useState('offer');
  const [templates, setTemplates] = useState({ offer: [], contract: [] });
  const [fields, setFields] = useState([]);
  const [sel, setSel] = useState(null);
  const [draft, setDraft] = useState({ title: '', target_roles: '', body: '' });
  const [preview, setPreview] = useState('');
  const [busy, setBusy] = useState('');
  const [msg, setMsg] = useState('');
  const taRef = useRef(null);

  const load = useCallback(async () => {
    const [tRes, f] = await Promise.all([
      axios.get(`${API}/staff-onboarding/templates`, { headers }),
      axios.get(`${API}/staff-onboarding/merge-fields`, { headers }),
    ]);
    setTemplates({ offer: tRes.data.offer || [], contract: tRes.data.contract || [] });
    setFields(f.data.fields || []);
  }, [headers]);
  useEffect(() => { load(); }, [load]);

  const openTmpl = (tpl) => { setSel(tpl); setPreview(''); setMsg(''); setDraft({ title: tpl.title || '', target_roles: (tpl.target_roles || []).join(', '), body: tpl.body || '' }); };
  const newTmpl = () => { setSel({ id: null, key: 'new' }); setPreview(''); setMsg(''); setDraft({ title: '', target_roles: '', body: kind === 'offer' ? 'Dear {{preferred_name}},\n\n' : 'CONTRACT OF EMPLOYMENT\n\n' }); };

  const insertField = (token) => {
    const ta = taRef.current;
    if (!ta) { setDraft((p) => ({ ...p, body: p.body + token })); return; }
    const s = ta.selectionStart, e = ta.selectionEnd;
    const nv = draft.body.slice(0, s) + token + draft.body.slice(e);
    setDraft((p) => ({ ...p, body: nv }));
    setTimeout(() => { ta.focus(); ta.selectionStart = ta.selectionEnd = s + token.length; }, 0);
  };

  const doPreview = async () => {
    setBusy('preview');
    try { const r = await axios.post(`${API}/staff-onboarding/templates/preview`, { body: draft.body }, { headers }); setPreview(r.data.rendered); }
    finally { setBusy(''); }
  };
  const save = async () => {
    setBusy('save'); setMsg('');
    const payload = { title: draft.title, target_roles: draft.target_roles.split(',').map((s) => s.trim()).filter(Boolean), body: draft.body };
    try {
      if (sel?.id) await axios.put(`${API}/staff-onboarding/templates/${kind}/${sel.id}`, payload, { headers });
      else await axios.post(`${API}/staff-onboarding/templates/${kind}`, payload, { headers });
      setMsg(t('staffing.onb_saved', 'Saved ✓')); await load(); setSel(null);
    } catch (e) { setMsg('⚠ ' + (e?.response?.data?.detail || t('staffing.onb_save_failed', 'Save failed'))); } finally { setBusy(''); }
  };
  const resetDefaults = async () => {
    setBusy('reset');
    try { const r = await axios.post(`${API}/staff-onboarding/templates/reset-defaults`, {}, { headers }); setMsg(`${t('staffing.onb_reset', 'Reset')} ${r.data.reset} ${t('staffing.onb_builtin_templates', 'built-in templates')}`); await load(); }
    finally { setBusy(''); }
  };

  const list = templates[kind] || [];

  return (
    <Modal onClose={onClose} title={t('staffing.onb_templates_title', 'Offer & Contract Templates')} testId="template-manager" wide>
      <div className="flex items-center gap-2 mb-3">
        {['offer', 'contract'].map((k) => (
          <button key={k} onClick={() => { setKind(k); setSel(null); }} data-testid={`tmpl-kind-${k}`}
            className={`px-3 py-1.5 rounded-lg text-sm capitalize ${kind === k ? 'bg-cyan-500/20 text-cyan-300' : 'opacity-70'}`}
            style={{ color: kind === k ? undefined : 'var(--theme-text)' }}>{k === 'offer' ? t('staffing.onb_offer_letters', 'offer letters') : t('staffing.onb_contract_letters', 'contract letters')}</button>
        ))}
        <button onClick={newTmpl} data-testid="tmpl-new"
          className="ml-auto inline-flex items-center gap-1.5 text-xs px-3 py-1.5 rounded-lg border" style={{ color: 'var(--theme-text)', borderColor: 'var(--theme-border)' }}><Plus size={13} /> {t('staffing.onb_new', 'New')}</button>
        <button onClick={resetDefaults} disabled={busy === 'reset'} data-testid="tmpl-reset"
          className="inline-flex items-center gap-1.5 text-xs px-3 py-1.5 rounded-lg border" style={{ color: 'var(--theme-text)', borderColor: 'var(--theme-border)' }}><RotateCcw size={13} /> {t('staffing.onb_reset_defaults', 'Reset defaults')}</button>
      </div>
      {msg && <div className="mb-3 text-xs px-3 py-2 rounded-lg" data-testid="tmpl-msg" style={{ background: 'var(--theme-surface)', color: 'var(--theme-text)' }}>{msg}</div>}

      {!sel ? (
        <div className="space-y-2" data-testid="tmpl-list">
          {list.map((tpl) => (
            <button key={tpl.id} onClick={() => openTmpl(tpl)} data-testid={`tmpl-row-${tpl.key}`}
              className="w-full text-left px-3 py-2.5 rounded-lg border flex items-center justify-between gap-2 hover:bg-white/[0.03]" style={surface}>
              <div>
                <div className="font-medium" style={{ color: 'var(--theme-text)' }}>{tpl.title}
                  {tpl.is_sample && <span className="ml-2 text-[10px] text-amber-300">{t('staffing.onb_placeholder', 'PLACEHOLDER')}</span>}</div>
                <div className="text-xs opacity-60" style={{ color: 'var(--theme-text)' }}>{(tpl.target_roles || []).join(', ') || t('staffing.onb_all_roles', 'all roles')} · v{tpl.version}</div>
              </div>
              <Pencil size={14} style={{ color: 'var(--theme-text)' }} />
            </button>
          ))}
        </div>
      ) : (
        <div className="space-y-3">
          <div className="grid grid-cols-2 gap-3">
            <TextIn label={t('staffing.onb_template_title', 'Template title')} testId="tmpl-title" value={draft.title} onChange={(v) => setDraft((p) => ({ ...p, title: v }))} />
            <TextIn label={t('staffing.onb_target_roles', 'Target roles (comma separated)')} testId="tmpl-roles" value={draft.target_roles} onChange={(v) => setDraft((p) => ({ ...p, target_roles: v }))} />
          </div>
          <div>
            <div className="text-xs opacity-70 mb-1" style={{ color: 'var(--theme-text)' }}>{t('staffing.onb_merge_fields', 'Merge fields (click to insert)')}</div>
            <div className="flex flex-wrap gap-1.5" data-testid="tmpl-merge-fields">
              {fields.map((f) => (
                <button key={f.key} onClick={() => insertField(f.token)} data-testid={`merge-${f.key}`} title={f.label}
                  className="text-[11px] px-2 py-1 rounded-md border" style={{ color: 'var(--theme-text)', borderColor: 'var(--theme-border)' }}>{f.token}</button>
              ))}
            </div>
          </div>
          <label className="block">
            <span className="text-xs opacity-70" style={{ color: 'var(--theme-text)' }}>{t('staffing.onb_doc_body', 'Document body')}</span>
            <textarea ref={taRef} value={draft.body} onChange={(e) => setDraft((p) => ({ ...p, body: e.target.value }))} data-testid="tmpl-body"
              rows={14} className="mt-1 w-full rounded-lg px-3 py-2 text-xs font-mono border bg-transparent"
              style={{ color: 'var(--theme-text)', borderColor: 'var(--theme-border)' }} />
          </label>
          <div className="flex gap-2 flex-wrap">
            <Btn onClick={() => setSel(null)} testId="tmpl-back">{t('staffing.onb_back', 'Back')}</Btn>
            <Btn onClick={doPreview} busy={busy === 'preview'} testId="tmpl-preview-btn">{t('staffing.onb_preview', 'Preview')}</Btn>
            <Btn onClick={save} busy={busy === 'save'} testId="tmpl-save" primary>{t('staffing.onb_save_template', 'Save template')}</Btn>
          </div>
          {preview && (
            <pre className="whitespace-pre-wrap p-3 rounded-lg text-xs max-h-64 overflow-auto" data-testid="tmpl-preview"
              style={{ background: 'var(--theme-surface)', color: 'var(--theme-text)' }}>{preview}</pre>
          )}
        </div>
      )}
    </Modal>
  );
}

/* ───────────────── Onboarding settings (pack email) ───────────────── */
function PackSettings({ headers, onClose }) {
  const { t } = useTranslation();
  const [s, setS] = useState(null);
  const [recips, setRecips] = useState('');
  const [enabled, setEnabled] = useState(true);
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState('');

  useEffect(() => {
    axios.get(`${API}/staff-onboarding/settings`, { headers }).then((r) => {
      setS(r.data); setEnabled(r.data.email_pack_on_activation !== false);
      setRecips((r.data.pack_recipient_emails || []).join('\n'));
    });
  }, [headers]);

  const save = async () => {
    setBusy(true); setMsg('');
    const list = recips.split(/[\n,;]+/).map((x) => x.trim()).filter((x) => x.includes('@'));
    try {
      const r = await axios.put(`${API}/staff-onboarding/settings`,
        { email_pack_on_activation: enabled, pack_recipient_emails: list }, { headers });
      setRecips((r.data.pack_recipient_emails || []).join('\n')); setMsg(t('staffing.onb_saved', 'Saved ✓'));
    } catch (e) { setMsg('⚠ ' + (e?.response?.data?.detail || t('staffing.onb_save_failed', 'Save failed'))); } finally { setBusy(false); }
  };

  if (!s) return null;
  return (
    <Modal onClose={onClose} title={t('staffing.onb_settings_title', 'Onboarding settings')} testId="pack-settings">
      <div className="space-y-4 text-sm" style={{ color: 'var(--theme-text)' }}>
        <label className="flex items-start gap-3 cursor-pointer" data-testid="pack-email-toggle">
          <input type="checkbox" checked={enabled} onChange={(e) => setEnabled(e.target.checked)} className="mt-1" />
          <span><span className="font-medium flex items-center gap-1.5"><Mail size={14} /> {t('staffing.onb_email_pack', 'Email the Onboarding Pack on activation')}</span>
            <span className="block opacity-60 text-xs mt-0.5">{t('staffing.onb_email_pack_note', 'When an employee is activated, the audit-ready Onboarding Pack PDF is emailed to the recipients below (plus the person activating).')}</span></span>
        </label>
        <label className="block">
          <span className="text-xs opacity-70">{t('staffing.onb_recipients', 'HR / payroll recipients (one per line)')}</span>
          <textarea value={recips} onChange={(e) => setRecips(e.target.value)} data-testid="pack-recipients"
            rows={5} placeholder="hr@company.com&#10;payroll@company.com"
            className="mt-1 w-full rounded-lg px-3 py-2 text-sm border bg-transparent"
            style={{ color: 'var(--theme-text)', borderColor: 'var(--theme-border)' }} />
        </label>
        {msg && <div className="text-xs" data-testid="pack-settings-msg">{msg}</div>}
        <div className="flex gap-2">
          <Btn onClick={save} busy={busy} testId="pack-settings-save" primary>{t('staffing.onb_save_settings', 'Save settings')}</Btn>
          <Btn onClick={onClose} testId="pack-settings-close">{t('staffing.onb_close', 'Close')}</Btn>
        </div>

        <div className="pt-4 border-t" style={{ borderColor: 'var(--theme-border)' }}>
          <DocsManager headers={headers} />
        </div>
      </div>
    </Modal>
  );
}

/* Company policies & agreements — upload your own docs; AI detects signature points. */
function DocsManager({ headers }) {
  const { t } = useTranslation();
  const [docs, setDocs] = useState({ policies: [], agreements: [] });
  const [newTitle, setNewTitle] = useState({ policies: '', agreements: '' });
  const [busy, setBusy] = useState('');
  const [ai, setAi] = useState({});

  const load = useCallback(async () => {
    const r = await axios.get(`${API}/staff-onboarding/templates`, { headers });
    setDocs({ policies: r.data.policies || [], agreements: r.data.agreements || [] });
  }, [headers]);
  useEffect(() => { load(); }, [load]);

  const add = async (kind) => {
    const title = newTitle[kind].trim(); if (!title) return;
    setBusy(`add-${kind}`);
    try { await axios.post(`${API}/staff-onboarding/${kind}`, { title }, { headers }); setNewTitle((p) => ({ ...p, [kind]: '' })); await load(); }
    finally { setBusy(''); }
  };
  const remove = async (kind, key) => {
    setBusy(`del-${key}`);
    try { await axios.delete(`${API}/staff-onboarding/${kind}/${key}`, { headers }); await load(); }
    finally { setBusy(''); }
  };
  const upload = async (kind, key, e) => {
    const file = e.target.files?.[0]; if (!file) return;
    setBusy(`up-${key}`); setAi((p) => ({ ...p, [key]: null }));
    const fd = new FormData(); fd.append('file', file);
    try {
      const r = await axios.post(`${API}/staff-onboarding/${kind}/${key}/upload`, fd, { headers });
      setAi((p) => ({ ...p, [key]: r.data.ai })); await load();
    } finally { setBusy(''); }
  };

  const renderList = (kind, label) => (
    <div>
      <div className="font-semibold text-sm mb-2" style={{ color: 'var(--theme-text)' }}>{label}</div>
      <div className="space-y-2">
        {docs[kind].map((d) => (
          <div key={d.key} className="rounded-lg border p-2.5" style={surface} data-testid={`doc-row-${d.key}`}>
            <div className="flex items-center gap-2">
              <span className="text-sm flex-1" style={{ color: 'var(--theme-text)' }}>{d.title}
                {d.is_sample && <span className="ml-1 text-[10px] text-amber-400">{t('staffing.onb_sample', 'SAMPLE')}</span>}
                {d.pdf_filename && <span className="ml-1 text-[10px] text-emerald-400">{t('staffing.onb_pdf_ok', 'PDF ✓')}</span>}</span>
              <label className="text-xs px-2 py-1 rounded-md border cursor-pointer" style={{ color: 'var(--theme-text)', borderColor: 'var(--theme-border)' }} data-testid={`doc-upload-${d.key}`}>
                {busy === `up-${d.key}` ? t('staffing.onb_analysing', 'Analysing…') : t('staffing.onb_upload_pdf', 'Upload PDF')}
                <input type="file" accept="application/pdf" className="hidden" onChange={(e) => upload(kind, d.key, e)} />
              </label>
              <button onClick={() => remove(kind, d.key)} disabled={busy === `del-${d.key}`} data-testid={`doc-del-${d.key}`}
                className="text-slate-400 hover:text-red-400"><X size={15} /></button>
            </div>
            {(ai[d.key] || d.signature_fields?.length > 0) && (
              <div className="mt-1.5 text-[11px]" style={{ color: 'var(--theme-text)', opacity: 0.7 }} data-testid={`doc-ai-${d.key}`}>
                {ai[d.key]?.summary || (d.signature_fields?.length ? t('staffing.onb_sig_detected', 'Signature points detected on upload.') : '')}
                {(ai[d.key]?.signature_fields || d.signature_fields || []).length > 0 &&
                  <span className="ml-1">{t('staffing.onb_sig_points', 'Signature points:')} {(ai[d.key]?.signature_fields || d.signature_fields).map((f) => f.label).join(', ')}</span>}
              </div>
            )}
          </div>
        ))}
      </div>
      <div className="flex gap-2 mt-2">
        <input value={newTitle[kind]} onChange={(e) => setNewTitle((p) => ({ ...p, [kind]: e.target.value }))} data-testid={`doc-new-${kind}`}
          placeholder={kind === 'policies' ? t('staffing.onb_new_policy', 'New policy title') : t('staffing.onb_new_agreement', 'New agreement title')}
          className="flex-1 rounded-lg px-3 py-1.5 text-sm border bg-transparent" style={{ color: 'var(--theme-text)', borderColor: 'var(--theme-border)' }} />
        <Btn onClick={() => add(kind)} busy={busy === `add-${kind}`} testId={`doc-add-${kind}`}><Plus size={13} /> {t('staffing.onb_add', 'Add')}</Btn>
      </div>
    </div>
  );

  return (
    <div className="space-y-4" data-testid="docs-manager">
      <div>
        <div className="font-semibold flex items-center gap-1.5" style={{ color: 'var(--theme-text)' }}><ScrollText size={15} /> {t('staffing.onb_policies_agreements', 'Your policies & agreements')}</div>
        <div className="text-xs opacity-60 mb-3" style={{ color: 'var(--theme-text)' }}>{t('staffing.onb_policies_note', "Upload your company's own documents. When you upload a PDF, AI reads it and flags where signatures/initials are required.")}</div>
      </div>
      {renderList('policies', t('staffing.onb_policies', 'Policies (read & acknowledge)'))}
      {renderList('agreements', t('staffing.onb_agreements', 'Agreements (require signature)'))}
    </div>
  );
}

/* ───────────────── shared UI ───────────────── */
function Modal({ children, onClose, title, testId, wide }) {
  useEffect(() => {
    const onKey = (e) => { if (e.key === 'Escape') onClose(); };
    document.addEventListener('keydown', onKey);
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => { document.removeEventListener('keydown', onKey); document.body.style.overflow = prev; };
  }, [onClose]);
  return createPortal(
    <div className="fixed inset-0 z-[300] flex items-start justify-center p-4 overflow-y-auto"
      style={{ background: 'rgba(0,0,0,0.7)' }} data-testid={testId}
      onMouseDown={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <div className={`w-full ${wide ? 'max-w-3xl' : 'max-w-2xl'} rounded-2xl border my-8 max-h-[calc(100vh-4rem)] overflow-y-auto`}
        style={{ background: 'var(--theme-bg, #0f1417)', borderColor: 'var(--theme-border)' }}>
        <div className="flex items-center justify-between px-5 py-3 border-b sticky top-0 z-10"
          style={{ borderColor: 'var(--theme-border)', background: 'var(--theme-bg, #0f1417)' }}>
          <h3 className="font-bold" style={{ color: 'var(--theme-text)' }}>{title}</h3>
          <button onClick={onClose} data-testid="modal-close"><X size={18} style={{ color: 'var(--theme-text)' }} /></button>
        </div>
        <div className="p-5">{children}</div>
      </div>
    </div>,
    document.body,
  );
}
function Row({ k, v }) {
  return <div className="flex justify-between gap-3 border-b py-1.5" style={{ borderColor: 'var(--theme-border)' }}>
    <span className="opacity-60">{k}</span><span className="font-medium text-right">{v ?? '—'}</span></div>;
}
function Btn({ children, onClick, busy, testId, primary, disabled }) {
  return <button onClick={onClick} disabled={busy || disabled} data-testid={testId}
    className={`inline-flex items-center gap-1.5 px-4 py-2 rounded-lg text-sm font-semibold disabled:opacity-40 ${primary ? 'text-slate-900' : 'border'}`}
    style={primary ? { background: 'var(--color-brand-cyan,#19CDFF)' } : { color: 'var(--theme-text)', borderColor: 'var(--theme-border)' }}>
    {busy ? <Loader2 size={14} className="animate-spin" /> : children}</button>;
}

/**
 * VehiclesTab — HR/manager fleet register + weekly check register.
 * Assign vehicles to staff drivers + a check type; review submitted weekly
 * checks; export for Health & Safety. Reuses staff_members (drivers) and
 * engineer vehicle_reg (import) — no data is duplicated.
 */
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import axios from 'axios';
import { Truck, Plus, ShieldAlert, FileDown, FileText, FileArchive, Link2, Loader2, X, Check, Trash2 } from 'lucide-react';
import CrashPacksManager from './CrashPacksManager';
import { compressImage } from '../../../utils/compressImage';

const API = `${process.env.REACT_APP_BACKEND_URL}/api`;
const token = () => (typeof window !== 'undefined' ? localStorage.getItem('token') : '');
const VEHICLE_TYPE_LABEL = { car: 'Car', electric_car: 'Electric Car', van: 'Van', electric_van: 'Electric Van', lorry: 'Lorry / HGV', van_maintenance: 'Van', vehicle_check: 'Car' };
const vtLabel = (v) => VEHICLE_TYPE_LABEL[v?.vehicle_type || v?.check_type] || 'Vehicle';

async function downloadCheckPdf(checkId, headers) {
  const r = await axios.get(`${API}/vehicle-checks/${checkId}/pdf`, { headers, responseType: 'blob' });
  const cd = r.headers['content-disposition'] || '';
  const m = cd.match(/filename\*?=(?:UTF-8'')?"?([^";]+)"?/i);
  const name = m ? decodeURIComponent(m[1]) : `vehicle-check-${checkId}.pdf`;
  const url = URL.createObjectURL(r.data);
  const a = document.createElement('a'); a.href = url; a.download = name; a.click();
  URL.revokeObjectURL(url);
}

const STATUS_TONE = {
  due: '#F59E0B', in_progress: '#19CDFF', submitted: '#10B981', reviewed: '#10B981',
};
const fmtD = (s) => (s ? new Date(s + (s?.length === 10 ? 'T00:00:00' : '')).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' }) : '—');

export default function VehiclesTab({ headers }) {
  const [view, setView] = useState('dashboard'); // 'dashboard' | 'register' | 'checks' | 'defects'
  const [data, setData] = useState(null);
  const [drivers, setDrivers] = useState([]);
  const [edit, setEdit] = useState(null); // vehicle being edited or {} for new
  const [importOpen, setImportOpen] = useState(false);
  const [detail, setDetail] = useState(null); // check detail id

  const load = useCallback(() => {
    axios.get(`${API}/vehicles`, { headers }).then((r) => setData(r.data)).catch(() => setData({ vehicles: [] }));
    axios.get(`${API}/vehicles/driver-options`, { headers }).then((r) => setDrivers(r.data.drivers || [])).catch(() => {});
  }, [headers]);
  useEffect(() => { load(); }, [load]);

  if (!data) return <div className="p-6"><Loader2 className="animate-spin" style={{ color: 'var(--color-brand-cyan)' }} /></div>;

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between gap-2 flex-wrap">
        <div className="inline-flex rounded-lg overflow-hidden border" style={{ borderColor: 'var(--theme-border)' }}>
          {[['dashboard', 'Overview'], ['register', 'Fleet register'], ['checks', 'Weekly checks'], ['defects', 'Defects'], ['crash', 'Crash Packs']].map(([id, lab]) => (
            <button key={id} onClick={() => setView(id)} data-testid={`vehicles-view-${id}`}
              className="px-4 py-1.5 text-xs font-semibold"
              style={view === id ? { background: 'var(--color-brand-cyan)', color: 'var(--color-ink)' } : { color: 'var(--theme-text-muted)' }}>{lab}</button>
          ))}
        </div>
        {view === 'register' && (
          <div className="flex gap-2">
            <button onClick={() => setImportOpen(true)} data-testid="vehicles-import-btn" className="inline-flex items-center gap-1 text-xs font-semibold rounded-full px-3 py-1.5 border" style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }}><Link2 size={13} /> Import Vehicle Details</button>
            <button onClick={async () => { const r = await axios.get(`${API}/vehicles/export.csv`, { headers, responseType: 'blob' }); const url = URL.createObjectURL(r.data); const a = document.createElement('a'); a.href = url; a.download = 'Fleet Register.csv'; a.click(); URL.revokeObjectURL(url); }} data-testid="vehicles-export-csv" className="inline-flex items-center gap-1 text-xs font-semibold rounded-full px-3 py-1.5 border" style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }}><FileDown size={13} /> Export CSV</button>
            <button onClick={async () => { const r = await axios.get(`${API}/vehicles/export.pdf`, { headers, responseType: 'blob' }); const url = URL.createObjectURL(r.data); const a = document.createElement('a'); a.href = url; a.download = 'Fleet Register.pdf'; a.click(); URL.revokeObjectURL(url); }} data-testid="vehicles-export-pdf" className="inline-flex items-center gap-1 text-xs font-semibold rounded-full px-3 py-1.5 border" style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }}><FileText size={13} /> Print / PDF</button>
            <button onClick={() => setEdit({})} data-testid="vehicles-add-btn" className="inline-flex items-center gap-1 text-xs font-semibold rounded-full px-3 py-1.5" style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-ink)' }}><Plus size={13} /> Add vehicle</button>
          </div>
        )}
      </div>

      {view === 'register' ? (
        <FleetRegister data={data} onEdit={setEdit} onChanged={load} headers={headers} />
      ) : view === 'checks' ? (
        <WeeklyChecks headers={headers} week={data.week_commencing} onOpen={setDetail} />
      ) : view === 'defects' ? (
        <DefectTracker headers={headers} />
      ) : view === 'crash' ? (
        <CrashPacksManager headers={headers} />
      ) : (
        <FleetDashboard headers={headers} onGoto={setView} />
      )}

      {edit && <VehicleModal vehicle={edit} drivers={drivers} headers={headers} onClose={() => setEdit(null)} onSaved={() => { setEdit(null); load(); }} />}
      {importOpen && <ImportModal headers={headers} onClose={() => setImportOpen(false)} onDone={() => { setImportOpen(false); load(); }} />}
      {detail && <CheckDetailModal checkId={detail} headers={headers} onClose={() => setDetail(null)} onReviewed={() => setDetail(null)} />}
    </div>
  );
}

function StatCard({ label, value, sub, tone, testId, onClick }) {
  return (
    <button onClick={onClick} disabled={!onClick} data-testid={testId}
      className="text-left rounded-xl border p-4 disabled:cursor-default hover:shadow-sm transition-shadow"
      style={{ borderColor: 'var(--theme-border)', background: 'var(--theme-surface)' }}>
      <div className="text-[11px] font-semibold uppercase tracking-wide" style={{ color: 'var(--theme-text-muted)' }}>{label}</div>
      <div className="text-2xl font-bold mt-1" style={{ color: tone || 'var(--theme-text)' }}>{value}</div>
      {sub && <div className="text-[11px] mt-0.5" style={{ color: 'var(--theme-text-muted)' }}>{sub}</div>}
    </button>
  );
}

function FleetDashboard({ headers, onGoto }) {
  const [d, setD] = useState(null);
  useEffect(() => { axios.get(`${API}/vehicle-checks/dashboard`, { headers }).then((r) => setD(r.data)).catch(() => setD({ total_vehicles: 0 })); }, [headers]);
  if (!d) return <Loader2 className="animate-spin" style={{ color: 'var(--color-brand-cyan)' }} />;
  if (!d.total_vehicles) return <div className="rounded-xl border p-10 text-center text-sm" style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text-muted)' }}>No vehicles yet — add one in the Fleet register to start tracking compliance.</div>;

  const pctTone = d.checks_pct >= 90 ? '#16a34a' : d.checks_pct >= 60 ? '#d97706' : '#dc2626';
  const expTone = (days) => (days < 0 ? '#dc2626' : days <= 14 ? '#d97706' : 'var(--theme-text)');
  return (
    <div className="space-y-4" data-testid="vehicles-dashboard">
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        <StatCard testId="dash-checks-pct" label="Checks done this week" value={`${d.checks_pct}%`} tone={pctTone} sub={`${d.checks_done}/${d.total_vehicles} vehicles · ${d.checks_reviewed} reviewed`} onClick={() => onGoto('checks')} />
        <StatCard testId="dash-open-defects" label="Open defects" value={d.open_defects} tone={d.open_defects ? '#dc2626' : '#16a34a'} sub={`${d.booked_defects} booked in`} onClick={() => onGoto('defects')} />
        <StatCard testId="dash-not-safe" label="Flagged not safe" value={d.not_safe} tone={d.not_safe ? '#dc2626' : '#16a34a'} sub="unresolved" onClick={() => onGoto('defects')} />
        <StatCard testId="dash-expiries" label="Legal dates ≤60 days" value={d.expiries.length} tone={d.expiries.some((e) => e.days < 0) ? '#dc2626' : d.expiries.length ? '#d97706' : '#16a34a'} sub="MOT / tax / insurance / service / lease" />
      </div>

      <div className="rounded-xl border p-4" style={{ borderColor: 'var(--theme-border)' }} data-testid="dash-outstanding">
        <div className="flex items-center justify-between mb-2">
          <h3 className="text-sm font-bold" style={{ color: 'var(--theme-text)' }}>Outstanding checks — week {fmtD(d.week_commencing)}</h3>
          <span className="text-xs" style={{ color: 'var(--theme-text-muted)' }}>{d.outstanding.length} to complete</span>
        </div>
        {d.outstanding.length === 0 ? (
          <div className="text-sm inline-flex items-center gap-1" style={{ color: '#16a34a' }}><Check size={15} /> All vehicles checked this week.</div>
        ) : (
          <div className="flex flex-wrap gap-2">
            {d.outstanding.map((o) => (
              <span key={o.id} className="inline-flex items-center gap-1.5 rounded-full border px-3 py-1 text-xs" style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text-muted)' }} data-testid={`dash-outstanding-${o.id}`}>
                <span className="font-bold uppercase" style={{ color: 'var(--theme-text)' }}>{o.reg_no}</span>
                {o.driver_names.length ? `· ${o.driver_names.join(', ')}` : '· unassigned'}
              </span>
            ))}
          </div>
        )}
      </div>

      <div className="rounded-xl border p-4" style={{ borderColor: 'var(--theme-border)' }} data-testid="dash-legal">
        <h3 className="text-sm font-bold mb-2" style={{ color: 'var(--theme-text)' }}>Upcoming MOT / tax / insurance / service / lease renewals</h3>
        {d.expiries.length === 0 ? (
          <div className="text-sm" style={{ color: 'var(--theme-text-muted)' }}>Nothing due in the next 60 days.</div>
        ) : (
          <div className="space-y-1.5">
            {d.expiries.map((e, i) => (
              <div key={i} className="flex items-center justify-between gap-3 text-sm" data-testid={`dash-expiry-${i}`}>
                <span><span className="font-bold uppercase" style={{ color: 'var(--theme-text)' }}>{e.reg_no}</span> <span style={{ color: 'var(--theme-text-muted)' }}>· {e.kind}</span></span>
                <span className="font-semibold" style={{ color: expTone(e.days) }}>{e.days < 0 ? `Overdue ${-e.days}d` : e.days === 0 ? 'Due today' : `in ${e.days}d`} <span className="text-xs font-normal" style={{ color: 'var(--theme-text-muted)' }}>({e.date})</span></span>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

const DEPARTMENTS = ['Management', 'Head Office', 'Installations', 'Service Engineers', 'Design & Build', 'Install'];

function Section({ title, children }) {
  return (
    <div className="rounded-xl border p-4" style={{ borderColor: 'var(--theme-border)', background: 'var(--theme-bg)' }}>
      <div className="text-[11px] font-bold uppercase tracking-wide mb-3" style={{ color: 'var(--color-brand-cyan)' }}>{title}</div>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 text-sm">{children}</div>
    </div>
  );
}
function TInput({ label, value, onChange, type = 'text', placeholder, upper, testid, span }) {
  return (
    <label className={`block ${span ? 'sm:col-span-2' : ''}`}>
      <span className="text-[11px] font-semibold" style={{ color: 'var(--theme-text-muted)' }}>{label}</span>
      <input type={type} value={value || ''} onChange={onChange} placeholder={placeholder}
        className={`mt-1 w-full rounded-lg border px-3 py-2 text-sm ${upper ? 'uppercase' : ''}`}
        style={{ background: 'var(--theme-surface)', borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }}
        data-testid={testid} />
    </label>
  );
}

function FleetRegister({ data, onEdit, onChanged, headers }) {
  const del = async (id, e) => { e.stopPropagation(); if (!window.confirm('Remove this vehicle from the register?')) return; await axios.delete(`${API}/vehicles/${id}`, { headers }); onChanged(); };
  if (!data.vehicles.length) return <div className="rounded-xl border p-10 text-center text-sm" style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text-muted)' }}>No vehicles yet. Add one or import from engineer profiles.</div>;
  const groups = {};
  data.vehicles.forEach((v) => { const d = v.fleet_department || 'Unassigned department'; (groups[d] = groups[d] || []).push(v); });
  const order = Object.keys(groups).sort((a, b) => {
    const ia = DEPARTMENTS.indexOf(a), ib = DEPARTMENTS.indexOf(b);
    return (ia === -1 ? 99 : ia) - (ib === -1 ? 99 : ib) || a.localeCompare(b);
  });
  return (
    <div className="space-y-5" data-testid="vehicles-register">
      {order.map((dep) => (
        <div key={dep} data-testid={`fleet-dept-${dep}`}>
          <div className="flex items-center gap-2 mb-2">
            <h3 className="text-xs font-bold uppercase tracking-wide" style={{ color: 'var(--color-brand-cyan)' }}>{dep}</h3>
            <span className="text-[11px]" style={{ color: 'var(--theme-text-muted)' }}>{groups[dep].length} vehicle{groups[dep].length === 1 ? '' : 's'}</span>
          </div>
          <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
            {groups[dep].map((v) => (
              <button key={v.id} onClick={() => onEdit(v)} data-testid={`vehicle-reg-${v.id}`}
                className="text-left rounded-xl border p-3 hover:shadow-md transition-shadow"
                style={{ borderColor: 'var(--theme-border)', background: 'var(--theme-surface)' }}>
                <div className="flex items-start justify-between gap-2">
                  <div className="min-w-0">
                    <div className="font-bold uppercase flex items-center gap-1.5" style={{ color: 'var(--theme-text)' }}>
                      {v.reg_no}
                      {v.is_ev && <span className="text-[9px] px-1 rounded bg-emerald-100 text-emerald-700">EV</span>}
                      {v.is_hybrid && <span className="text-[9px] px-1 rounded bg-amber-100 text-amber-700">HYB</span>}
                    </div>
                    <div className="text-xs truncate" style={{ color: 'var(--theme-text-muted)' }}>{v.make_model || vtLabel(v)}</div>
                  </div>
                  <span className="inline-flex items-center gap-1 text-[10px] font-semibold px-2 py-0.5 rounded-full shrink-0" style={{ background: `${STATUS_TONE[v.this_week?.status] || '#9a9fa1'}22`, color: STATUS_TONE[v.this_week?.status] || '#9a9fa1' }} data-testid={`vehicle-week-${v.id}`}>
                    {v.this_week?.has_defects && <ShieldAlert size={10} />}
                    {{ due: 'Due', in_progress: 'In progress', submitted: 'Submitted', reviewed: 'Reviewed' }[v.this_week?.status] || 'Due'}
                  </span>
                </div>
                <div className="mt-2 flex items-center justify-between gap-2">
                  <span className="text-xs truncate" style={{ color: 'var(--theme-text-muted)' }}>
                    {(v.driver_names || []).join(', ') || v.driver_label || <span className="text-amber-600">Unassigned</span>}
                  </span>
                  <span className="flex items-center gap-2 shrink-0">
                    {v.lease_end_date && <span className="text-[10px]" style={{ color: 'var(--theme-text-muted)' }}>Lease {fmtD(v.lease_end_date)}</span>}
                    <span onClick={(e) => del(v.id, e)} data-testid={`vehicle-del-${v.id}`} className="text-slate-400 hover:text-rose-500 cursor-pointer"><Trash2 size={13} /></span>
                  </span>
                </div>
              </button>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}

function WeeklyChecks({ headers, week, onOpen }) {
  const [wk, setWk] = useState(week);
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [rows, setRows] = useState(null);
  const ranged = !!(from || to);
  const load = useCallback(() => {
    const qs = ranged
      ? `?date_from=${from || ''}&date_to=${to || ''}`
      : `?week=${wk}`;
    axios.get(`${API}/vehicle-checks/register${qs}`, { headers })
      .then((r) => setRows(r.data.checks || [])).catch(() => setRows([]));
  }, [wk, from, to, ranged, headers]);
  useEffect(() => { load(); }, [load]);
  const exportCsv = async () => {
    const qs = ranged ? `?date_from=${from || ''}&date_to=${to || ''}` : `?week=${wk}`;
    const r = await axios.get(`${API}/vehicle-checks/export.csv${qs}`, { headers, responseType: 'blob' });
    const url = URL.createObjectURL(r.data); const a = document.createElement('a');
    a.href = url; a.download = `vehicle-checks-${ranged ? `${from || 'start'}_to_${to || 'now'}` : wk}.csv`; a.click();
  };
  const [zipBusy, setZipBusy] = useState(false);
  const exportZip = async () => {
    setZipBusy(true);
    try {
      const qs = ranged ? `?date_from=${from || ''}&date_to=${to || ''}` : `?week=${wk}`;
      const r = await axios.get(`${API}/vehicle-checks/export-zip${qs}`, { headers, responseType: 'blob' });
      const cd = r.headers['content-disposition'] || '';
      const m = cd.match(/filename\*?=(?:UTF-8'')?"?([^";]+)"?/i);
      const name = m ? decodeURIComponent(m[1]) : `Vehicle Checks - ${ranged ? `${from || 'start'} to ${to || 'now'}` : wk}.zip`;
      const url = URL.createObjectURL(r.data); const a = document.createElement('a');
      a.href = url; a.download = name; a.click(); URL.revokeObjectURL(url);
    } catch (e) {
      alert(e?.response?.status === 404 ? 'No completed checks in this range.' : 'Could not build the ZIP.');
    } finally { setZipBusy(false); }
  };
  return (
    <div className="space-y-3" data-testid="vehicles-checks">
      <div className="flex items-end gap-2 flex-wrap">
        <label className="flex flex-col gap-1">
          <span className="text-[11px] font-semibold" style={{ color: 'var(--theme-text-muted)' }}>Week commencing</span>
          <input type="date" value={wk} disabled={ranged} onChange={(e) => setWk(e.target.value)} data-testid="vehicles-week"
            className="rounded-lg px-3 py-1.5 text-sm border disabled:opacity-40"
            style={{ background: 'var(--theme-bg)', borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }} />
        </label>
        <span className="pb-2 text-[11px] font-semibold" style={{ color: 'var(--theme-text-muted)' }}>or date range</span>
        <label className="flex flex-col gap-1">
          <span className="text-[11px] font-semibold" style={{ color: 'var(--theme-text-muted)' }}>From</span>
          <input type="date" value={from} onChange={(e) => setFrom(e.target.value)} data-testid="vehicles-date-from"
            className="rounded-lg px-3 py-1.5 text-sm border"
            style={{ background: 'var(--theme-bg)', borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }} />
        </label>
        <label className="flex flex-col gap-1">
          <span className="text-[11px] font-semibold" style={{ color: 'var(--theme-text-muted)' }}>To</span>
          <input type="date" value={to} onChange={(e) => setTo(e.target.value)} data-testid="vehicles-date-to"
            className="rounded-lg px-3 py-1.5 text-sm border"
            style={{ background: 'var(--theme-bg)', borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }} />
        </label>
        {ranged && (
          <button onClick={() => { setFrom(''); setTo(''); }} data-testid="vehicles-range-clear"
            className="pb-2 text-[11px] font-semibold underline" style={{ color: 'var(--color-brand-cyan)' }}>Clear range</button>
        )}
        <button onClick={exportCsv} data-testid="vehicles-export" className="ml-auto inline-flex items-center gap-1 text-xs font-semibold rounded-full px-3 py-1.5 border self-end" style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }}><FileDown size={13} /> Export CSV</button>
        <button onClick={exportZip} disabled={zipBusy} data-testid="vehicles-export-zip" className="inline-flex items-center gap-1 text-xs font-semibold rounded-full px-3 py-1.5 self-end text-white disabled:opacity-60" style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-ink)' }}>{zipBusy ? <Loader2 size={13} className="animate-spin" /> : <FileArchive size={13} />} Download all PDFs (ZIP)</button>
      </div>
      {!rows ? <Loader2 className="animate-spin" style={{ color: 'var(--color-brand-cyan)' }} /> : rows.length === 0 ? (
        <div className="rounded-xl border p-10 text-center text-sm" style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text-muted)' }}>{ranged ? 'No checks completed in this date range.' : 'No checks submitted for this week yet.'}</div>
      ) : (
        <div className="rounded-xl border overflow-hidden" style={{ borderColor: 'var(--theme-border)' }}>
          <table className="w-full text-sm">
            <thead><tr className="text-xs" style={{ color: 'var(--theme-text-muted)' }}>
              <th className="text-left py-2 px-3">Reg</th><th className="text-left py-2 px-3">Driver</th>
              <th className="text-left py-2 px-3">Completed</th>
              <th className="text-left py-2 px-3">Status</th><th className="text-left py-2 px-3">Defects</th><th className="w-16" /></tr></thead>
            <tbody>
              {rows.map((c) => (
                <tr key={c.id} className="border-t" style={{ borderColor: 'var(--theme-border)' }} data-testid={`check-row-${c.id}`}>
                  <td className="py-2 px-3 font-bold uppercase" style={{ color: 'var(--theme-text)' }}>{c.details?.reg_no}</td>
                  <td className="py-2 px-3" style={{ color: 'var(--theme-text-muted)' }}>{c.driver_name}</td>
                  <td className="py-2 px-3" style={{ color: 'var(--theme-text-muted)' }}>{c.submitted_at ? fmtD(c.submitted_at.slice(0, 10)) : '—'}</td>
                  <td className="py-2 px-3"><span className="text-[11px] font-semibold px-2 py-0.5 rounded-full" style={{ background: `${STATUS_TONE[c.status] || '#9a9fa1'}22`, color: STATUS_TONE[c.status] || '#9a9fa1' }}>{c.status}</span></td>
                  <td className="py-2 px-3">{c.has_defects ? <span className="inline-flex items-center gap-1 text-rose-600 text-xs font-semibold"><ShieldAlert size={13} /> {c.defect?.safe_to_drive === false ? 'Not safe' : 'Yes'}</span> : <span className="text-xs" style={{ color: 'var(--theme-text-muted)' }}>None</span>}</td>
                  <td className="py-2 px-3 text-right whitespace-nowrap">
                    <button onClick={() => downloadCheckPdf(c.id, headers)} data-testid={`check-pdf-${c.id}`} title="Download PDF" className="inline-flex items-center gap-1 text-[11px] font-semibold mr-3" style={{ color: 'var(--theme-text-muted)' }}><FileDown size={13} /> PDF</button>
                    <button onClick={() => onOpen(c.id)} data-testid={`check-open-${c.id}`} className="text-[11px] font-semibold underline" style={{ color: 'var(--color-brand-cyan)' }}>Open</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

const DEFECT_TONE = { open: '#dc2626', booked_in: '#d97706', resolved: '#16a34a' };
const DEFECT_LABEL = { open: 'Open', booked_in: 'Booked in', resolved: 'Resolved' };

function DefectTracker({ headers }) {
  const [status, setStatus] = useState('open');
  const [data, setData] = useState(null);
  const [busyId, setBusyId] = useState(null);
  const [booking, setBooking] = useState(null); // defect being booked-in
  const load = useCallback(() => {
    const qs = status === 'all' ? '' : `?status=${status}`;
    axios.get(`${API}/vehicle-defects${qs}`, { headers }).then((r) => setData(r.data)).catch(() => setData({ defects: [], counts: {} }));
  }, [status, headers]);
  useEffect(() => { load(); }, [load]);

  const setState = async (id, newStatus, extra = {}) => {
    setBusyId(id);
    try { await axios.patch(`${API}/vehicle-defects/${id}`, { status: newStatus, ...extra }, { headers }); setBooking(null); load(); }
    finally { setBusyId(null); }
  };

  const counts = data?.counts || {};
  return (
    <div className="space-y-3" data-testid="vehicles-defects">
      <div className="flex items-center gap-2 flex-wrap">
        {[['open', `Open (${counts.open ?? 0})`], ['booked_in', `Booked in (${counts.booked_in ?? 0})`], ['resolved', `Resolved (${counts.resolved ?? 0})`], ['all', 'All']].map(([id, lab]) => (
          <button key={id} onClick={() => setStatus(id)} data-testid={`defect-filter-${id}`}
            className="px-3 py-1.5 text-xs font-semibold rounded-full border"
            style={status === id ? { background: 'var(--color-brand-cyan)', color: 'var(--color-ink)', borderColor: 'transparent' } : { borderColor: 'var(--theme-border)', color: 'var(--theme-text-muted)' }}>{lab}</button>
        ))}
      </div>
      {!data ? <Loader2 className="animate-spin" style={{ color: 'var(--color-brand-cyan)' }} /> : data.defects.length === 0 ? (
        <div className="rounded-xl border p-10 text-center text-sm" style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text-muted)' }}>No {status === 'all' ? '' : DEFECT_LABEL[status]?.toLowerCase()} defects. 🎉</div>
      ) : (
        <div className="space-y-2">
          {data.defects.map((d) => (
            <div key={d.id} className="rounded-xl border p-4" style={{ borderColor: 'var(--theme-border)' }} data-testid={`defect-${d.id}`}>
              <div className="flex items-start justify-between gap-3 flex-wrap">
                <div className="min-w-0">
                  <div className="flex items-center gap-2 flex-wrap">
                    <span className="font-bold uppercase" style={{ color: 'var(--theme-text)' }}>{d.reg_no}</span>
                    {(d.priority === 'critical' || d.escalated) && <span className="inline-flex items-center gap-1 text-[11px] font-bold px-2 py-0.5 rounded-full text-white" style={{ background: '#dc2626' }} data-testid={`defect-critical-${d.id}`}><ShieldAlert size={12} /> CRITICAL</span>}
                    {d.safe_to_drive === false && <span className="inline-flex items-center gap-1 text-[11px] font-semibold text-rose-600"><ShieldAlert size={12} /> Not safe</span>}
                    <span className="text-[11px] font-semibold px-2 py-0.5 rounded-full" style={{ background: `${DEFECT_TONE[d.status]}22`, color: DEFECT_TONE[d.status] }}>{DEFECT_LABEL[d.status]}</span>
                  </div>
                  <p className="text-sm mt-1 whitespace-pre-line" style={{ color: 'var(--theme-text)' }}>{d.details || 'No description provided.'}</p>
                  {(d.photo_ids || []).length > 0 && (
                    <div className="flex gap-2 mt-2 flex-wrap" data-testid={`defect-photos-${d.id}`}>
                      {d.photo_ids.map((fid) => (
                        <a key={fid} href={`${API}/vehicle-checks/photo/${fid}?auth=${token()}`} target="_blank" rel="noreferrer">
                          <img src={`${API}/vehicle-checks/photo/${fid}?auth=${token()}`} alt="defect" className="h-16 w-16 object-cover rounded-lg border" style={{ borderColor: 'var(--theme-border)' }} />
                        </a>
                      ))}
                    </div>
                  )}
                  <div className="text-[11px] mt-1" style={{ color: 'var(--theme-text-muted)' }}>
                    Reported by {d.reported_by || '—'}
                    {d.booking_ref && ` · Ref ${d.booking_ref}`}{d.booking_date && ` · Booked ${fmtD(d.booking_date)}`}
                    {d.resolved_note && ` · ${d.resolved_note}`}
                  </div>
                </div>
                <div className="flex gap-1.5 shrink-0">
                  {d.status === 'open' && (
                    <button onClick={() => setBooking(d)} disabled={busyId === d.id} data-testid={`defect-book-${d.id}`}
                      className="text-[11px] font-semibold rounded-full px-3 py-1.5 text-white" style={{ background: '#d97706' }}>Mark booked-in</button>
                  )}
                  {d.status !== 'resolved' && (
                    <button onClick={() => setState(d.id, 'resolved')} disabled={busyId === d.id} data-testid={`defect-resolve-${d.id}`}
                      className="inline-flex items-center gap-1 text-[11px] font-semibold rounded-full px-3 py-1.5 text-white bg-emerald-600">{busyId === d.id ? <Loader2 size={12} className="animate-spin" /> : <Check size={12} />} Resolve</button>
                  )}
                  {d.status === 'resolved' && (
                    <button onClick={() => setState(d.id, 'open')} disabled={busyId === d.id} data-testid={`defect-reopen-${d.id}`}
                      className="text-[11px] font-semibold rounded-full px-3 py-1.5 border" style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text-muted)' }}>Reopen</button>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {booking && (
        <Modal onClose={() => setBooking(null)} testId="defect-booking-modal">
          <div className="flex items-center justify-between mb-3"><h3 className="font-bold text-slate-900">Book in repair — {booking.reg_no}</h3><button onClick={() => setBooking(null)} className="text-slate-400"><X size={18} /></button></div>
          <BookingForm onSubmit={(ref, dt) => setState(booking.id, 'booked_in', { booking_ref: ref, booking_date: dt })} />
        </Modal>
      )}
    </div>
  );
}

function BookingForm({ onSubmit }) {
  const [ref, setRef] = useState('');
  const [dt, setDt] = useState('');
  return (
    <div className="space-y-3 text-sm">
      <label className="block"><span className="text-xs text-slate-500">Provider / garage reference</span>
        <input value={ref} onChange={(e) => setRef(e.target.value)} data-testid="defect-booking-ref" className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2" placeholder="e.g. Vanarama ref" /></label>
      <label className="block"><span className="text-xs text-slate-500">Booking date</span>
        <input type="date" value={dt} onChange={(e) => setDt(e.target.value)} data-testid="defect-booking-date" className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2" /></label>
      <div className="flex justify-end"><button onClick={() => onSubmit(ref, dt)} data-testid="defect-booking-save" className="px-4 py-2 rounded-lg text-sm font-bold text-slate-900" style={{ background: 'var(--color-brand-cyan)' }}>Save booking</button></div>
    </div>
  );
}

function Modal({ children, onClose, testId, wide, themed }) {
  useEffect(() => {
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = prev; };
  }, []);
  return createPortal(
    <div className="fixed inset-0 z-[1000] flex items-start sm:items-center justify-center bg-black/60 p-4 overflow-y-auto" onClick={onClose} data-testid={testId}>
      <div className={`w-full ${wide ? 'max-w-3xl' : 'max-w-lg'} my-4 sm:my-8 max-h-[92vh] overflow-y-auto rounded-2xl p-5 shadow-2xl ${themed ? '' : 'bg-white'}`}
        style={themed ? { background: 'var(--theme-surface)', border: '1px solid var(--theme-border)' } : undefined}
        onClick={(e) => e.stopPropagation()}>{children}</div>
    </div>,
    document.body,
  );
}

function DriverPicker({ value, drivers, onChange }) {
  const [open, setOpen] = useState(false);
  const [q, setQ] = useState('');
  const ref = useRef(null);
  const selected = drivers.find((d) => d.id === value);
  useEffect(() => {
    const h = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener('mousedown', h);
    return () => document.removeEventListener('mousedown', h);
  }, []);
  const ql = q.trim().toLowerCase();
  const filtered = ql
    ? drivers.filter((d) => (d.full_name || '').toLowerCase().includes(ql) || (d.department || '').toLowerCase().includes(ql) || (d.job_title || '').toLowerCase().includes(ql))
    : drivers;
  const pick = (id) => { onChange(id); setOpen(false); setQ(''); };
  return (
    <div className="relative mt-1" ref={ref}>
      <button type="button" onClick={() => setOpen((o) => !o)} data-testid="vm-driver-select"
        className="w-full flex items-center justify-between rounded-lg border px-3 py-2 text-sm text-left"
        style={{ background: 'var(--theme-surface)', borderColor: 'var(--theme-border)', color: selected ? 'var(--theme-text)' : 'var(--theme-text-muted)' }}>
        <span className="truncate">{selected ? `${selected.full_name}${selected.department ? ` · ${selected.department}` : ''}` : '— Unassigned —'}</span>
        <span className="flex items-center gap-2 shrink-0">
          {selected && <X size={13} onClick={(e) => { e.stopPropagation(); pick(''); }} className="hover:text-rose-500" />}
          <span className="text-[10px]" style={{ color: 'var(--theme-text-muted)' }}>▾</span>
        </span>
      </button>
      {open && (
        <div className="absolute z-20 mt-1 w-full rounded-lg border shadow-xl"
          style={{ background: 'var(--theme-surface)', borderColor: 'var(--theme-border)' }}>
          <div className="p-2 border-b" style={{ borderColor: 'var(--theme-border)' }}>
            <input autoFocus value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search staff by name…" data-testid="vm-driver-search"
              className="w-full rounded-md border px-2.5 py-1.5 text-sm"
              style={{ background: 'var(--theme-bg)', borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }} />
          </div>
          <div className="max-h-44 overflow-y-auto">
            <button type="button" onClick={() => pick('')} className="w-full text-left px-3 py-2 text-sm hover:opacity-70" style={{ color: 'var(--theme-text-muted)' }}>— Unassigned —</button>
            {filtered.length === 0 && <div className="px-3 py-2 text-xs" style={{ color: 'var(--theme-text-muted)' }}>No staff match &ldquo;{q}&rdquo;.</div>}
            {filtered.map((d) => (
              <button key={d.id} type="button" onClick={() => pick(d.id)} data-testid={`vm-driver-option-${d.id}`}
                className="w-full text-left px-3 py-2 text-sm hover:opacity-70 flex items-center justify-between"
                style={{ color: 'var(--theme-text)', background: d.id === value ? 'var(--theme-bg)' : 'transparent' }}>
                <span className="truncate">{d.full_name}</span>
                {d.department && <span className="text-[11px] shrink-0 ml-2" style={{ color: 'var(--theme-text-muted)' }}>{d.department}</span>}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

function VehicleModal({ vehicle, drivers, headers, onClose, onSaved }) {
  const isNew = !vehicle.id;
  const [f, setF] = useState({
    reg_no: vehicle.reg_no || '', make_model: vehicle.make_model || '',
    vehicle_type: vehicle.vehicle_type || vehicle.check_type || 'car',
    provider: vehicle.provider || '', driver_staff_ids: vehicle.driver_staff_ids || [],
    primary_driver_staff_id: vehicle.primary_driver_staff_id || null,
    driver_label: vehicle.driver_label || '',
    fleet_department: vehicle.fleet_department || '',
    lease_company: vehicle.lease_company || '',
    lease_end_date: vehicle.lease_end_date || '',
    fuel_card_number: vehicle.fuel_card_number || '',
    dart: vehicle.dart || '', congestion: vehicle.congestion || '', m6_toll: vehicle.m6_toll || '',
    odometer: vehicle.odometer || '', service_record: vehicle.service_record || {},
    notes: vehicle.notes || '',
    is_ev: vehicle.is_ev ?? ((vehicle.vehicle_type || vehicle.check_type || '').startsWith('electric')),
    is_hybrid: vehicle.is_hybrid ?? false,
  });
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState('');
  const [fines, setFines] = useState(vehicle.fines || []);
  const [nf, setNf] = useState({ kind: '', date: '', value: '', paid: false, file_id: null });
  const [fineBusy, setFineBusy] = useState(false);
  const uploadFine = async (file) => {
    if (!file) return;
    setFineBusy(true);
    try {
      const fd = new FormData(); fd.append('file', await compressImage(file));
      const r = await axios.post(`${API}/vehicles/fine-upload`, fd, { headers: { ...headers, 'Content-Type': 'multipart/form-data' } });
      setNf((p) => ({ ...p, file_id: r.data.file_id }));
    } catch { setErr('Fine document upload failed.'); } finally { setFineBusy(false); }
  };
  const addFine = async () => {
    if (!nf.kind.trim()) { setErr('Enter the fine type first.'); return; }
    setFineBusy(true); setErr('');
    try {
      const r = await axios.post(`${API}/vehicles/${vehicle.id}/fines`, nf, { headers });
      setFines((p) => [...p, r.data]); setNf({ kind: '', date: '', value: '', paid: false, file_id: null });
    } catch (e) { setErr(e?.response?.data?.detail || 'Could not add fine.'); } finally { setFineBusy(false); }
  };
  const toggleFine = async (fid, paid) => {
    await axios.patch(`${API}/vehicles/${vehicle.id}/fines/${fid}`, { paid }, { headers });
    setFines((p) => p.map((f) => (f.id === fid ? { ...f, paid } : f)));
  };
  const delFine = async (fid) => {
    if (!window.confirm('Remove this fine?')) return;
    await axios.delete(`${API}/vehicles/${vehicle.id}/fines/${fid}`, { headers });
    setFines((p) => p.filter((f) => f.id !== fid));
  };
  const set = (k, v) => setF((p) => ({ ...p, [k]: v }));
  const sr = f.service_record || {};
  const setSr = (k, v) => setF((p) => ({ ...p, service_record: { ...p.service_record, [k]: v } }));
  const save = async () => {
    if (!f.reg_no.trim()) { setErr('Registration is required.'); return; }
    setBusy(true); setErr('');
    try {
      if (isNew) await axios.post(`${API}/vehicles`, f, { headers });
      else await axios.patch(`${API}/vehicles/${vehicle.id}`, f, { headers });
      onSaved();
    } catch (e) { setErr(e?.response?.data?.detail || 'Save failed.'); setBusy(false); }
  };
  const cellStyle = { background: 'var(--theme-surface)', borderColor: 'var(--theme-border)', color: 'var(--theme-text)' };
  return (
    <Modal onClose={onClose} testId="vehicle-modal" wide themed>
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2 min-w-0">
          <span className="rounded-xl p-2" style={{ background: 'var(--color-brand-cyan)', color: 'var(--color-ink)' }}><Truck size={18} /></span>
          <div className="min-w-0">
            <h3 className="font-bold uppercase truncate" style={{ color: 'var(--theme-text)' }}>{f.reg_no || (isNew ? 'Add vehicle' : 'Vehicle')}</h3>
            <div className="text-xs truncate" style={{ color: 'var(--theme-text-muted)' }}>{f.make_model || vtLabel(f)}{f.fleet_department ? ` · ${f.fleet_department}` : ''}</div>
          </div>
        </div>
        <button onClick={onClose} style={{ color: 'var(--theme-text-muted)' }}><X size={18} /></button>
      </div>

      <div className="space-y-3">
        <Section title="Vehicle details">
          <TInput label="Registration *" value={f.reg_no} onChange={(e) => set('reg_no', e.target.value)} upper testid="vm-reg" />
          <TInput label="Make / model" value={f.make_model} onChange={(e) => set('make_model', e.target.value)} testid="vm-model" />
          <label className="block">
            <span className="text-[11px] font-semibold" style={{ color: 'var(--theme-text-muted)' }}>Vehicle type</span>
            <select value={f.vehicle_type} onChange={(e) => set('vehicle_type', e.target.value)} data-testid="vm-vehicle-type"
              className="mt-1 w-full rounded-lg border px-3 py-2 text-sm" style={cellStyle}>
              <option value="car">Car</option><option value="electric_car">Electric Car</option>
              <option value="van">Van</option><option value="electric_van">Electric Van</option><option value="lorry">Lorry / HGV</option>
            </select>
          </label>
          <label className="block">
            <span className="text-[11px] font-semibold" style={{ color: 'var(--theme-text-muted)' }}>Department</span>
            <input list="fleet-departments" value={f.fleet_department} onChange={(e) => set('fleet_department', e.target.value)} placeholder="e.g. Service Engineers" data-testid="vm-department"
              className="mt-1 w-full rounded-lg border px-3 py-2 text-sm" style={cellStyle} />
            <datalist id="fleet-departments">{DEPARTMENTS.map((d) => <option key={d} value={d} />)}</datalist>
          </label>
          <TInput label="Odometer" value={f.odometer} onChange={(e) => set('odometer', e.target.value)} />
          <div className="sm:col-span-2 flex flex-wrap items-center gap-5" data-testid="vm-powertrain">
            <span className="text-[11px] font-semibold uppercase tracking-wide" style={{ color: 'var(--theme-text-muted)' }}>Powertrain</span>
            <label className="flex items-center gap-2 cursor-pointer" style={{ color: 'var(--theme-text)' }}>
              <input type="checkbox" checked={!!f.is_ev} onChange={(e) => set('is_ev', e.target.checked)} data-testid="vm-is-ev" className="h-4 w-4" /> Electric (EV)
            </label>
            <label className="flex items-center gap-2 cursor-pointer" style={{ color: 'var(--theme-text)' }}>
              <input type="checkbox" checked={!!f.is_hybrid} onChange={(e) => set('is_hybrid', e.target.checked)} data-testid="vm-is-hybrid" className="h-4 w-4" /> Hybrid
            </label>
            <span className="text-[11px] basis-full" style={{ color: 'var(--theme-text-muted)' }}>Tick EV to add the electric-vehicle section to the weekly checklist.</span>
          </div>
        </Section>

        <Section title="Assigned driver">
          <div className="sm:col-span-2">
            <span className="text-[11px] font-semibold" style={{ color: 'var(--theme-text-muted)' }}>Driver</span>
            <DriverPicker
              value={f.primary_driver_staff_id}
              drivers={drivers}
              onChange={(id) => setF((p) => ({ ...p, primary_driver_staff_id: id || null, driver_staff_ids: id ? [id] : [] }))}
            />
            {!f.primary_driver_staff_id && f.driver_label && (
              <p className="mt-1.5 text-[11px]" style={{ color: 'var(--theme-text-muted)' }} data-testid="vm-driver-hint">
                Imported driver: <span className="font-semibold" style={{ color: 'var(--theme-text)' }}>{f.driver_label}</span> — search above to link them to a staff member.
              </p>
            )}
          </div>
          <TInput label="Driver label (pool / leased / unlinked)" value={f.driver_label} onChange={(e) => set('driver_label', e.target.value)} placeholder="e.g. Pool Car, Leased, Install" span testid="vm-driver-label" />
        </Section>

        <Section title="Lease & finance">
          <TInput label="Lease / finance company" value={f.lease_company} onChange={(e) => set('lease_company', e.target.value)} placeholder="e.g. LEX Auto Lease" testid="vm-lease-company" />
