async function downloadBlob(API, token, path, filename) {
  try {
    const res = await axios.get(`${API}${path}`, {
      headers: { Authorization: `Bearer ${token}` }, responseType: 'blob',
    });
    const url = URL.createObjectURL(res.data);
    const a = document.createElement('a');
    a.href = url; a.download = filename; document.body.appendChild(a); a.click();
    a.remove(); URL.revokeObjectURL(url);
    notify.success('Export downloaded');
  } catch { notify.error('Export failed'); }
}

export default function MODASERPortal({ onClose }) {
  const { API } = useAuth();
  const token = localStorage.getItem('token');
  const headers = useMemo(() => ({ Authorization: `Bearer ${token}` }), [token]);

  const [config, setConfig] = useState(null);
  const [view, setView] = useState('register'); // register | new | detail
  const [entries, setEntries] = useState([]);
  const [dash, setDash] = useState(null);
  const [loading, setLoading] = useState(true);
  const [activeId, setActiveId] = useState(null);
  const [emailModal, setEmailModal] = useState(null); // {mode:'summary'|'evidence', equipmentId, siteId, label}
  const [filters, setFilters] = useState({ q: '', risk: '', status: '', event_type: '' });

  const loadConfig = useCallback(async () => {
    try {
      const { data } = await axios.get(`${API}/mod/aser/config`, { headers });
      setConfig(data);
    } catch { setConfig({ event_types: [], sites: [], is_manager: false }); }
  }, [API, headers]);

  const loadRegister = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      Object.entries(filters).forEach(([k, v]) => v && params.set(k, v));
      const [reg, d] = await Promise.all([
        axios.get(`${API}/mod/aser?${params.toString()}`, { headers }),
        axios.get(`${API}/mod/aser/dashboard`, { headers }),
      ]);
      setEntries(reg.data.entries || []);
      setDash(d.data);
    } catch { setEntries([]); }
    setLoading(false);
  }, [API, headers, filters]);

  useEffect(() => { loadConfig(); }, [loadConfig]);
  useEffect(() => { if (view === 'register') loadRegister(); }, [view, loadRegister]);

  return (
    <div className="mod-aser-inline w-full text-[var(--theme-text)]" data-testid="mod-aser-portal">
      <header className="border-b border-[var(--theme-border)]">
        <div className="px-1 py-3 flex items-center justify-between gap-3 flex-wrap">
