      const r = await axios.get(`${API}/mod/site/quotes`, { headers });
      setList(r.data.quotes || []);
    } catch (e) { notify.error('Could not load quotes'); }
    setLoading(false);
  }, [API]);
  useEffect(() => { load(); }, [load]);

  const openDetail = async (id) => {
    try {
      const r = await axios.get(`${API}/mod/site/quotes/${id}`, { headers });
