export default function ModulePage({ module: m }) {
  const moduleIntent = MODULE_INTENT_MAP[m.id];
  const startTrial = () => openTrial(moduleIntent);
  return (
    <MarketingShell>
      <Hero m={m} onStartTrial={startTrial} />
      <ProblemSolution m={m} />
      <Features m={m} />
      <VisualSections m={m} />
      <AISection m={m} />
      <Integrations m={m} />
