        <a href={`mailto:${doc.email}`} className="text-xs font-semibold inline-flex items-center gap-1 rounded-full border border-zinc-200 px-3 py-1 text-zinc-700 hover:bg-zinc-50">
          <Mail size={11} /> Email client
        </a>
      </div>
    </div>
