/**
 * AdminPartnerAttribution — Iter 220q
 *
 * Master-admin view of the top-of-funnel attribution data captured by
 * iter 220o (Instagram-attributed apply form). Renders the live
 * landings + conversions per UTM source, with conversion rate, mini
 * bar chart, and totals.
 *
 * Data source: GET /api/partners/attribution-summary (master-admin
 * only — already gated server-side).
 *
 * Empty-state copy is explicit: this dashboard counts UTM-tagged
 * landings only (organic traffic lives in your web analytics).
 * Mirrors the comment on the backend track-source endpoint so the
 * UX matches the system rule.
 */
import { useCallback, useEffect, useMemo, useState } from 'react';
import axios from 'axios';
import { Loader2, BarChart3, TrendingUp, Globe } from 'lucide-react';

const API = process.env.REACT_APP_BACKEND_URL;

// Iter 220q — small per-source icon hint so the table reads at a glance.
const SOURCE_GLYPHS = {
  instagram: '📷',
  linkedin: '💼',
  facebook: '📘',
  twitter: '🐦',
  tiktok: '🎵',
  email: '📧',
  newsletter: '📬',
  direct: '🔗',
  google: '🔎',
};

export default function AdminPartnerAttribution() {
  const token = useMemo(() => localStorage.getItem('token'), []);
  const headers = useMemo(() => ({ Authorization: `Bearer ${token}` }), [token]);
  const [rows, setRows] = useState([]);
  const [totals, setTotals] = useState({ landings: 0, applications_attributed: 0 });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchSummary = useCallback(async () => {
    setLoading(true); setError(null);
    try {
      const r = await axios.get(`${API}/api/partners/attribution-summary`, { headers });
      setRows(r.data?.rows || []);
      setTotals(r.data?.totals || { landings: 0, applications_attributed: 0 });
    } catch (e) {
      setError(e.response?.data?.detail || 'Could not load attribution summary');
    } finally {
      setLoading(false);
    }
  }, [headers]);

  useEffect(() => { fetchSummary(); }, [fetchSummary]);

  // Compute the max-landings so each row's mini bar can be scaled
  // relative to the top source — gives an instant "Instagram is
  // 5x more than LinkedIn" read without a real chart library.
  const maxLandings = useMemo(
    () => rows.reduce((m, r) => Math.max(m, r.landings || 0), 0) || 1,
    [rows],
  );

  // Overall conversion rate across all tagged channels.
  const overallRate = totals.landings
    ? ((totals.applications_attributed / totals.landings) * 100).toFixed(2)
    : '0.00';

  return (
    <section
      className="rounded-2xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 p-4"
      data-testid="admin-partner-attribution"
    >
      <header className="flex items-start justify-between gap-3 mb-3">
        <div className="flex items-center gap-2">
          <BarChart3 size={14} className="text-purple-500" />
          <h3 className="text-sm font-extrabold uppercase tracking-wider">
            Attribution &amp; conversions
          </h3>
        </div>
        <button
          type="button"
          onClick={fetchSummary}
          className="text-xs font-bold text-zinc-500 hover:text-zinc-700 dark:hover:text-zinc-300 inline-flex items-center gap-1"
          data-testid="admin-attribution-refresh"
        >
          {loading ? <Loader2 size={12} className="animate-spin" /> : 'Refresh'}
        </button>
      </header>

      {/* Top stats — landings, applications, overall conversion rate. */}
      <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 mb-4">
        <Stat
          icon={Globe}
          label="UTM landings"
          value={totals.landings.toLocaleString()}
          testId="admin-attr-stat-landings"
        />
        <Stat
          icon={TrendingUp}
          label="Applications attributed"
          value={totals.applications_attributed.toLocaleString()}
          testId="admin-attr-stat-applications"
        />
        <Stat
          icon={BarChart3}
          label="Overall conversion"
          value={`${overallRate}%`}
          testId="admin-attr-stat-conversion"
          accent
        />
      </div>

      {error ? (
        <div className="text-xs text-rose-700 bg-rose-50 border border-rose-200 rounded-lg px-3 py-2" data-testid="admin-attribution-error">
          {error}
        </div>
      ) : null}

      {loading && !rows.length ? (
        <div className="text-xs text-zinc-500 py-6 text-center">
          <Loader2 size={14} className="animate-spin inline mr-2" />
          Loading attribution data…
        </div>
      ) : rows.length === 0 ? (
        <div className="rounded-xl border border-dashed border-zinc-300 dark:border-zinc-700 p-6 text-center" data-testid="admin-attribution-empty">
          <p className="text-sm font-semibold text-zinc-700 dark:text-zinc-200">No tagged traffic yet</p>
          <p className="text-xs text-zinc-500 mt-1 max-w-md mx-auto">
            This panel counts <strong>UTM-tagged</strong> landings only.
            Organic traffic + first-touch SEO stay in your web analytics.
            Tag a campaign URL with{' '}
            <code className="px-1 py-0.5 bg-zinc-100 dark:bg-zinc-800 rounded text-[11px]">
              ?utm_source=instagram
            </code>{' '}
            and refresh to see it appear.
          </p>
        </div>
      ) : (
        <div className="overflow-x-auto" data-testid="admin-attribution-table-wrap">
          <table className="w-full text-xs" data-testid="admin-attribution-table">
            <thead>
              <tr className="text-left text-[10px] uppercase tracking-wider text-zinc-500 border-b border-zinc-200 dark:border-zinc-800">
                <th className="py-2 pr-3">Source</th>
                <th className="py-2 pr-3">Medium</th>
                <th className="py-2 pr-3">Campaign</th>
                <th className="py-2 pr-3 text-right">Landings</th>
                <th className="py-2 pr-3 w-[140px]">Landings (visual)</th>
                <th className="py-2 pr-3 text-right">Applications</th>
                <th className="py-2 pr-3 text-right">Conversion</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((r) => {
                const src = (r.utm_source || '').toLowerCase();
                const glyph = SOURCE_GLYPHS[src] || '🌐';
                const barWidth = `${Math.max(2, (r.landings / maxLandings) * 100)}%`;
                const isHot = r.conversion_rate_pct >= 5;
                return (
                  <tr
                    key={r.key || `${r.utm_source}|${r.utm_medium}|${r.utm_campaign}`}
                    className="border-b border-zinc-100 dark:border-zinc-800/50 hover:bg-zinc-50 dark:hover:bg-zinc-800/30"
                    data-testid={`admin-attribution-row-${r.utm_source || 'unknown'}`}
                  >
                    <td className="py-2 pr-3">
                      <span className="inline-flex items-center gap-1.5 font-semibold">
                        <span aria-hidden>{glyph}</span>
                        <span>{r.utm_source || '—'}</span>
                      </span>
                    </td>
                    <td className="py-2 pr-3 text-zinc-600 dark:text-zinc-400">{r.utm_medium || '—'}</td>
                    <td className="py-2 pr-3 text-zinc-600 dark:text-zinc-400 max-w-[200px] truncate" title={r.utm_campaign || ''}>
                      {r.utm_campaign || '—'}
                    </td>
                    <td className="py-2 pr-3 text-right tabular-nums font-semibold">
                      {(r.landings || 0).toLocaleString()}
                    </td>
                    <td className="py-2 pr-3">
                      <div className="h-2 rounded-full bg-zinc-100 dark:bg-zinc-800 overflow-hidden">
                        <div
                          className="h-full rounded-full"
                          style={{
                            width: barWidth,
                            background: 'linear-gradient(90deg, #0091CA 0%, #19CDFF 100%)',
                          }}
                          aria-label={`${r.landings} landings`}
                        />
                      </div>
                    </td>
                    <td className="py-2 pr-3 text-right tabular-nums font-semibold">
                      {(r.applications || 0).toLocaleString()}
                    </td>
                    <td className="py-2 pr-3 text-right tabular-nums">
                      <span
                        className={`inline-flex items-center gap-1 px-1.5 py-0.5 rounded font-bold ${
                          isHot
                            ? 'bg-emerald-50 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-300'
                            : 'bg-zinc-100 text-zinc-600 dark:bg-zinc-800 dark:text-zinc-300'
                        }`}
                      >
                        {(r.conversion_rate_pct || 0).toFixed(2)}%
                      </span>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </section>
  );
}

function Stat({ icon: Icon, label, value, testId, accent }) {
  return (
    <div
      className={`rounded-xl border p-3 ${
        accent
          ? 'border-transparent text-white'
          : 'border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900'
      }`}
      style={accent ? { background: 'linear-gradient(135deg, #0091CA 0%, #19CDFF 50%, #19CDFF 100%)' } : undefined}
      data-testid={testId}
    >
      <div className={`text-[10px] uppercase tracking-wider font-bold inline-flex items-center gap-1 ${accent ? 'text-white/85' : 'text-zinc-500'}`}>
        {Icon ? <Icon size={11} /> : null}
        {label}
      </div>
      <div className={`text-xl font-black mt-1 ${accent ? 'text-white' : ''}`}>{value}</div>
    </div>
  );
}

import { useEffect, useState, useCallback } from 'react';
import axios from 'axios';
import { notify } from '@/components/notifications';
import { notifyApiError } from '@/lib/formatApiError';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { UserPlus, UserMinus, HeadphonesIcon, Mail, Loader2, Copy } from 'lucide-react';

function authConfig() {
  const token = localStorage.getItem('token');
  return { headers: token ? { Authorization: `Bearer ${token}` } : {} };
}

const BRAND_BADGE = {
  gymaxis: 'bg-cyan-50 text-cyan-700 border-cyan-200',
  pulse:   'bg-blue-50 text-blue-700 border-blue-200',
};

export default function AdminServiceDesk({ API, isPulseAdmin = false }) {
  const [members, setMembers] = useState([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(false);

  // Create-new form
  const [createOpen, setCreateOpen] = useState(false);
  const [createForm, setCreateForm] = useState({ email: '', full_name: '', brand: 'gymaxis' });
  const [creating, setCreating] = useState(false);
  const [lastCreated, setLastCreated] = useState(null); // {email, temp_password, brand} when email failed

  // Grant existing form — pick from a dropdown of current staff
  const [grantEmail, setGrantEmail] = useState('');
  const [people, setPeople] = useState([]);
  const grantBrand = isPulseAdmin ? 'pulse' : 'gymaxis';

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const r = await axios.get(`${API}/master-admin/service-desk/members`, authConfig());
      setMembers(r.data.members || []);
      setTotal(r.data.total || 0);
    } catch {
      notify.error('Failed to load Service Desk members');
    } finally { setLoading(false); }
  }, [API]);

  const loadPeople = useCallback(async () => {
    try {
      const r = await axios.get(`${API}/master-admin/users`, authConfig());
      setPeople(r.data.users || []);
    } catch { /* dropdown just stays empty */ }
  }, [API]);

  useEffect(() => { load(); loadPeople(); }, [load, loadPeople]);

  const createUser = async () => {
    const email = createForm.email.trim().toLowerCase();
    const full_name = createForm.full_name.trim();
    if (!email || !full_name) return;
    setCreating(true);
    try {
      const r = await axios.post(`${API}/master-admin/service-desk/users`,
        { email, full_name, brand: createForm.brand }, authConfig());
      const sent = r.data.email_sent;
      notify.success(
        sent
          ? `Created ${createForm.brand === 'pulse' ? 'Pulse' : 'Pulse Fitness'} Service Desk user · welcome email sent to ${email}`
          : `Created ${email} — share the temp password manually below (email failed)`,
        { duration: 8000 },
      );
      if (!sent) {
        setLastCreated({ email, temp_password: r.data.temp_password, brand: createForm.brand });
      }
      setCreateForm({ email: '', full_name: '', brand: createForm.brand });
      setCreateOpen(false);
      await load();
    } catch (e) {
      notifyApiError(notify, e, 'Failed to create Service Desk user');
    } finally { setCreating(false); }
  };

  const grantExisting = async () => {
    const email = grantEmail.trim().toLowerCase();
    if (!email) return;
    try {
      await axios.post(`${API}/master-admin/service-desk/members/grant`,
        { email, brand: grantBrand }, authConfig());
      notify.success(`Granted Service Desk access to ${email}`);
      setGrantEmail('');
      await load(); await loadPeople();
    } catch (e) {
      notifyApiError(notify, e, 'Grant failed');
    }
  };

  const revoke = async (email) => {
    if (!window.confirm(`Revoke Service Desk access from ${email}?`)) return;
    try {
      await axios.post(`${API}/master-admin/service-desk/members/revoke`, { email }, authConfig());
      notify.success(`Revoked Service Desk role from ${email}`);
      await load(); await loadPeople();
    } catch (e) {
      notifyApiError(notify, e, 'Revoke failed');
    }
  };

  // Staff who don't already have Service Desk access — the grant dropdown options
  const memberEmails = new Set(members.map((m) => (m.email || '').toLowerCase()));
  const candidates = people
    .filter((p) => p.email && !memberEmails.has(p.email.toLowerCase()) && !p.is_service_desk)
    .sort((a, b) => (a.full_name || a.email).localeCompare(b.full_name || b.email));

  return (
    <div className="space-y-4" data-testid="admin-service-desk">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h2 className="text-lg font-semibold text-zinc-900 flex items-center gap-2">
            <HeadphonesIcon className="w-5 h-5 text-orange-600" /> Service Desk Members
          </h2>
          <p className="text-sm text-zinc-500 mt-1">
            {total} {total === 1 ? 'person has' : 'people have'} Service Desk access.{' '}
            Nominate Pulse Fitness Ltd staff — they’re routed straight to the Service Desk when they sign in.
          </p>
        </div>
        <Button
          onClick={() => setCreateOpen((v) => !v)}
          className="bg-orange-600 hover:bg-orange-700 text-white"
          data-testid="desk-create-toggle"
        >
          <UserPlus className="w-4 h-4 mr-1" /> Create Service Desk user
        </Button>
      </div>

      {/* Create-new card */}
      {createOpen && (
        <Card className="p-5 border-orange-200 bg-orange-50/40" data-testid="desk-create-card">
          <div className="text-sm font-medium text-zinc-900 mb-3">
            New Service Desk user — temp password emailed automatically
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 mb-3">
            <Input
              placeholder="Full name"
              value={createForm.full_name}
              onChange={(e) => setCreateForm((f) => ({ ...f, full_name: e.target.value }))}
              data-testid="desk-create-name"
            />
            <Input
              type="email"
              placeholder="agent@email.com"
              value={createForm.email}
              onChange={(e) => setCreateForm((f) => ({ ...f, email: e.target.value }))}
              data-testid="desk-create-email"
            />
          </div>
          <div className="flex justify-end gap-2">
            <Button variant="outline" onClick={() => setCreateOpen(false)} disabled={creating} data-testid="desk-create-cancel">Cancel</Button>
            <Button
              onClick={createUser}
              disabled={creating || !createForm.email.trim() || !createForm.full_name.trim()}
              className="bg-orange-600 hover:bg-orange-700 text-white"
              data-testid="desk-create-submit"
            >
              {creating ? <Loader2 className="w-4 h-4 mr-1 animate-spin" /> : <Mail className="w-4 h-4 mr-1" />}
              Create &amp; email temp password
            </Button>
          </div>
          <p className="text-[11px] text-zinc-500 mt-2">
            Service Desk users are routed <strong>straight to the Service Desk</strong> when they sign in. They can view tickets across all clients in their brand, reply, change status, assign, and import equipment.
          </p>
        </Card>
      )}

      {/* If email delivery failed, show fallback temp password once */}
      {lastCreated && (
        <Card className="p-5 border-amber-300 bg-amber-50" data-testid="desk-temp-pwd-fallback">
          <div className="flex items-center justify-between gap-3">
            <div className="text-sm">
              Welcome email failed to send to <strong>{lastCreated.email}</strong>. Share this temp password manually:
              <div className="font-mono text-base font-semibold text-amber-900 mt-1">{lastCreated.temp_password}</div>
            </div>
            <Button
              size="sm" variant="outline"
              onClick={() => { navigator.clipboard.writeText(lastCreated.temp_password); notify.success('Copied'); }}
              data-testid="desk-temp-pwd-copy"
            >
              <Copy className="w-3.5 h-3.5 mr-1" /> Copy
            </Button>
          </div>
          <button onClick={() => setLastCreated(null)} className="text-xs text-amber-700 underline mt-2">Dismiss</button>
        </Card>
      )}

      {/* Grant-existing card */}
      <Card className="p-5">
        <div className="text-sm font-medium text-zinc-900 mb-2">Grant Service Desk role to an existing user</div>
        <div className="flex flex-wrap gap-2 items-center">
          <select
            value={grantEmail}
            onChange={(e) => setGrantEmail(e.target.value)}
            className="flex-1 min-w-[300px] text-sm border border-zinc-200 rounded-md px-3 py-2 bg-white"
            data-testid="desk-grant-user"
          >
            <option value="">Select a staff member…</option>
            {candidates.map((p) => (
              <option key={p.id || p.email} value={p.email}>
                {(p.full_name || p.email)}{p.full_name ? ` — ${p.email}` : ''}{p.job_title ? ` · ${p.job_title}` : ''}
              </option>
            ))}
          </select>
          <Button
            onClick={grantExisting}
            disabled={!grantEmail.trim()}
            className="bg-zinc-800 hover:bg-zinc-900 text-white"
            data-testid="desk-grant-btn"
          >
            <UserPlus className="w-4 h-4 mr-1" /> Grant access
          </Button>
        </div>
        {candidates.length === 0 && (
          <p className="text-xs text-zinc-500 mt-2">All staff already have Service Desk access, or no other staff exist yet.</p>
        )}
      </Card>

      {/* Members list */}
      <Card className="p-5">
        <div className="text-sm font-medium text-zinc-900 mb-3">Current Members</div>
        {loading ? (
          <div className="text-xs text-zinc-500">Loading…</div>
        ) : members.length === 0 ? (
          <div className="text-xs text-zinc-500">No Service Desk members yet.</div>
        ) : (
          <div className="space-y-1">
            {members.map((m) => (
              <div
                key={m.id}
                className="flex items-center justify-between py-2 border-b border-zinc-100 last:border-0 text-sm"
                data-testid={`desk-member-${m.id}`}
              >
                <div className="min-w-0">
                  <div className="text-zinc-900 truncate">{m.full_name || m.email}</div>
                  <div className="text-xs text-zinc-500 truncate">{m.email}</div>
                </div>
                <div className="flex items-center gap-2 flex-wrap justify-end">
                  <Badge variant="outline" className="text-[10px] bg-orange-50 text-orange-700 border-orange-200">Service Desk</Badge>
                  {m.must_change_password && (
                    <Badge variant="outline" className="text-[10px] bg-amber-50 text-amber-700 border-amber-200">Pending first sign-in</Badge>
                  )}
                  {m.is_master_admin && (
                    <Badge variant="outline" className="text-[10px] bg-purple-50 text-purple-700 border-purple-200">Master Admin</Badge>
                  )}
                  {m.disabled && (
                    <Badge variant="outline" className="text-[10px] bg-red-50 text-red-700 border-red-200">Disabled</Badge>
                  )}
                  {!m.is_master_admin && (
                    <Button
                      size="sm" variant="outline"
                      onClick={() => revoke(m.email)}
                      className="text-red-600 border-red-200 hover:bg-red-50"
                      data-testid={`desk-revoke-${m.id}`}
                    >
                      <UserMinus className="w-3 h-3 mr-1" /> Revoke
                    </Button>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </Card>
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import axios from 'axios';
import { Bell, ShieldAlert, Loader2, CheckCheck, ShieldCheck } from 'lucide-react';

/**
 * Master Admin header alert bell. Shows a live unread count of critical/abuse
 * security alerts (short-polled by the parent) and, on click, a dropdown of
 * the most recent unread alerts with "Mark all read" + jump-to-Security-Centre.
 */
function fmtWhen(iso) {
  if (!iso) return '';
  try {
    return new Date(iso).toLocaleString('en-GB', {
      day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit',
    });
  } catch { return ''; }
}

export default function AlertBell({ API, headers, count = 0, onViewCentre, onChanged }) {
  const [open, setOpen] = useState(false);
  const [alerts, setAlerts] = useState([]);
  const [loading, setLoading] = useState(false);
  const [marking, setMarking] = useState(false);
  const ref = useRef(null);

  const fetchList = async () => {
    setLoading(true);
    try {
      const r = await axios.get(`${API}/master-admin/security-centre/alerts`, {
        headers, params: { limit: 15 },
      });
      setAlerts(r.data?.alerts || []);
    } catch { /* transient */ } finally { setLoading(false); }
  };

  useEffect(() => {
    if (open) fetchList();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  // Close on outside click / Escape.
  useEffect(() => {
    if (!open) return undefined;
    const onDown = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    const onKey = (e) => { if (e.key === 'Escape') setOpen(false); };
    document.addEventListener('mousedown', onDown);
    document.addEventListener('keydown', onKey);
    return () => { document.removeEventListener('mousedown', onDown); document.removeEventListener('keydown', onKey); };
  }, [open]);

  const markAllRead = async () => {
    setMarking(true);
    try {
      await axios.post(`${API}/master-admin/security-centre/alerts/ack`, {}, { headers });
      setAlerts([]);
      onChanged?.();
    } catch { /* best-effort */ } finally { setMarking(false); }
  };

  const badge = count > 99 ? '99+' : String(count);

  return (
    <div className="relative flex-shrink-0" ref={ref}>
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className="relative p-2 rounded-lg text-zinc-600 hover:text-zinc-900 hover:bg-zinc-100 transition-colors"
        aria-label={`Security alerts${count ? ` (${count} unread)` : ''}`}
        data-testid="alert-bell-btn"
      >
        <Bell size={18} className={count > 0 ? 'text-red-600' : ''} />
        {count > 0 && (
          <span
            className="absolute -top-0.5 -right-0.5 min-w-[16px] h-4 px-1 flex items-center justify-center rounded-full bg-red-600 text-white text-[10px] font-bold leading-none animate-in zoom-in-50"
            data-testid="alert-bell-badge"
          >
            {badge}
          </span>
        )}
      </button>

      {open && (
        <div
          className="absolute right-0 mt-2 w-[360px] max-w-[calc(100vw-2rem)] rounded-xl border border-zinc-200 bg-white shadow-2xl z-[9999] overflow-hidden"
          data-testid="alert-bell-dropdown"
        >
          <div className="flex items-center justify-between px-4 py-2.5 border-b border-zinc-100">
            <div className="flex items-center gap-2">
              <ShieldAlert size={15} className="text-red-500" />
              <span className="text-sm font-semibold text-zinc-900">Security alerts</span>
              {count > 0 && (
                <span className="rounded-full bg-red-100 text-red-700 px-1.5 py-0.5 text-[10px] font-bold">{badge}</span>
              )}
            </div>
            {alerts.length > 0 && (
              <button
                onClick={markAllRead}
                disabled={marking}
                className="inline-flex items-center gap-1 text-xs font-medium text-zinc-500 hover:text-zinc-900 disabled:opacity-50"
                data-testid="alert-bell-mark-read"
              >
                {marking ? <Loader2 size={12} className="animate-spin" /> : <CheckCheck size={13} />}
                Mark all read
              </button>
            )}
          </div>

          <div className="max-h-[340px] overflow-y-auto">
            {loading ? (
              <div className="flex items-center justify-center gap-2 py-10 text-zinc-400 text-sm">
                <Loader2 size={16} className="animate-spin" /> Loading…
              </div>
            ) : alerts.length === 0 ? (
              <div className="flex flex-col items-center gap-2 py-10 text-zinc-400" data-testid="alert-bell-empty">
                <ShieldCheck size={26} className="text-emerald-400" />
                <p className="text-sm">No unread security alerts.</p>
              </div>
            ) : (
              <ul className="divide-y divide-zinc-100" data-testid="alert-bell-list">
                {alerts.map((a) => {
                  const critical = a.severity === 'critical';
                  return (
                    <li key={a.id} data-testid={`alert-bell-item-${a.id}`}>
                      <button
                        onClick={() => { setOpen(false); onViewCentre?.(); }}
                        className="w-full text-left px-4 py-3 hover:bg-zinc-50 transition-colors"
                      >
                        <div className="flex items-center gap-2">
                          <span className={`h-2 w-2 rounded-full flex-shrink-0 ${critical ? 'bg-red-500' : 'bg-amber-500'}`} />
                          <span className="text-sm font-medium text-zinc-900 truncate">{a.title}</span>
                          <span className="ml-auto text-[11px] text-zinc-400 whitespace-nowrap">{fmtWhen(a.created_at)}</span>
                        </div>
                        <p className="mt-0.5 pl-4 text-xs text-zinc-500 truncate">
                          {a.actor}{a.detail ? ` — ${a.detail}` : ''}
                        </p>
                      </button>
                    </li>
                  );
                })}
              </ul>
            )}
          </div>

          <div className="border-t border-zinc-100 px-4 py-2">
            <button
              onClick={() => { setOpen(false); onViewCentre?.(); }}
              className="w-full text-center text-xs font-semibold text-[var(--color-brand-blue,#0091ca)] hover:underline"
              data-testid="alert-bell-view-centre"
            >
              Open Security Alert Centre →
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * Iter 216h17 — Master Admin brand context (P1+P2 of the Master Admin
 * IA redesign, per /app/design_guidelines.json).
 *
 * Single React context that holds the operator's "I'm currently
 * looking at..." choice: All / Pulse Fitness / Pulse Fitness. The value is
 * persisted to localStorage so the choice survives reloads.
 *
 * Components READ from this context to filter data; they MUST NOT
 * duplicate the filter logic across surfaces. This becomes the
 * single switch between the two brands across every Master Admin
 * panel (replaces the ad-hoc `gymaxisOnly` flag scattering).
 */
import { createContext, useContext, useEffect, useMemo, useState, useCallback } from 'react';

const STORAGE_KEY = 'master_admin_brand_filter';
export const BRAND_OPTIONS = [
  { id: 'all', label: 'All Brands', short: 'All', accent: '#1B1C1D' },
  { id: 'pulse', label: 'Pulse Fitness', short: 'Pulse', accent: '#19CDFF' },
  { id: 'gymaxis', label: 'Pulse Fitness', short: 'Pulse Fitness', accent: '#10B981' },
];

const BrandContext = createContext({
  brand: 'all',
  setBrand: () => {},
  brandLabel: 'All Brands',
});

export const BrandContextProvider = ({ children }) => {
  const [brand, setBrandState] = useState(() => {
    try {
      const v = localStorage.getItem(STORAGE_KEY);
      if (BRAND_OPTIONS.some((o) => o.id === v)) return v;
    } catch { /* SSR or denied */ }
    return 'all';
  });

  const setBrand = useCallback((next) => {
    if (!BRAND_OPTIONS.some((o) => o.id === next)) return;
    setBrandState(next);
    try { localStorage.setItem(STORAGE_KEY, next); } catch { /* ignore */ }
  }, []);

  // Fire a window event so non-React legacy code (some panels still
  // read directly from localStorage) can reactively refresh.
  useEffect(() => {
    try { window.dispatchEvent(new CustomEvent('master-admin-brand-change', { detail: { brand } })); } catch { /* noop */ }
  }, [brand]);

  const value = useMemo(() => ({
    brand,
    setBrand,
    brandLabel: (BRAND_OPTIONS.find((o) => o.id === brand) || BRAND_OPTIONS[0]).label,
    brandShort: (BRAND_OPTIONS.find((o) => o.id === brand) || BRAND_OPTIONS[0]).short,
    brandAccent: (BRAND_OPTIONS.find((o) => o.id === brand) || BRAND_OPTIONS[0]).accent,
  }), [brand, setBrand]);

  return <BrandContext.Provider value={value}>{children}</BrandContext.Provider>;
};

export const useBrandContext = () => useContext(BrandContext);

/** Pure helper — apply the brand filter to an array of records that
 *  have a `brand` field or an inferable shape. Until each panel
 *  adopts its own scoping logic, components can call this to get a
 *  shared default. */
export const filterByBrand = (records, brand) => {
  if (!Array.isArray(records) || !brand || brand === 'all') return records || [];
  return records.filter((r) => {
    const rb = (r?.brand || r?.account_type || '').toLowerCase();
    if (brand === 'pulse') return rb === 'pulse' || rb === 'pulse_fitness' || rb === 'pulse_pro';
    if (brand === 'gymaxis') return rb === 'gymaxis' || rb === 'full' || rb === '';
    return true;
  });
};

export default BrandContext;

/**
 * Iter 216h17 — Brand context picker pill, lives in the Master Admin
 * top bar. Replaces the ad-hoc `gymaxisOnly` flag scattering across
 * sidebar/panel files.
 *
 * Iter 216h22 — `isPulseAdmin` prop. When the signed-in operator is a
 * delegated Pulse Master Admin (`is_pulse_admin && !is_master_admin`)
 * the picker is FORCED to "Pulse" on mount and rendered as a
 * non-clickable scope pill so Pulse admins can never accidentally
 * peek at Pulse Fitness-only customers. Pulse Fitness Master Admins keep the
 * full toggle.
 */
import React from 'react';
import { ChevronDown, Globe2 } from 'lucide-react';
import { useBrandContext, BRAND_OPTIONS } from './BrandContext';

export const BrandPicker = ({ compact = false, isPulseAdmin = false }) => {
  const { brand, setBrand, brandShort, brandAccent } = useBrandContext();
  const [open, setOpen] = React.useState(false);
  const ref = React.useRef(null);

  // Force the brand to Pulse for Pulse-only admins on first mount and
  // any time they somehow ended up on a different brand (e.g. stale
  // localStorage from a previous Pulse Fitness-master session in the same
  // browser). Idempotent.
  React.useEffect(() => {
    if (isPulseAdmin && brand !== 'pulse') setBrand('pulse');
  }, [isPulseAdmin, brand, setBrand]);

  React.useEffect(() => {
    if (!open) return undefined;
    const handler = (e) => {
      if (ref.current && !ref.current.contains(e.target)) setOpen(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [open]);

  // Pulse-only admins see a plain brand label — no dropdown, no scope
  // wording. Per operator request the Pulse Fitness team should not be
  // shown that their console is "scope locked".
  if (isPulseAdmin) {
    return (
      <div
        className="inline-flex items-center gap-2 rounded-full border bg-white px-3 py-1.5 text-sm font-medium shadow-sm"
        style={{ borderColor: '#BFDBFE', color: '#0091CA', background: '#E4F9FF' }}
        data-testid="master-admin-brand-picker-locked"
      >
        <span className="inline-block w-2 h-2 rounded-full" style={{ background: '#19CDFF' }} aria-hidden />
        <span className="font-semibold tracking-tight">Pulse Fitness</span>
      </div>
    );
  }

  return (
    <div ref={ref} className="relative inline-block" data-testid="master-admin-brand-picker">
      <button
        type="button"
        onClick={() => setOpen((p) => !p)}
        className="inline-flex items-center gap-2 rounded-full border bg-white px-3 py-1.5 text-sm font-medium shadow-sm hover:bg-zinc-50 transition-colors"
        style={{ borderColor: '#E0E0E0', color: '#1B1C1D' }}
        data-testid="master-admin-brand-picker-trigger"
        aria-haspopup="listbox"
        aria-expanded={open}
      >
        <span className="inline-block w-2 h-2 rounded-full" style={{ background: brandAccent }} aria-hidden />
        {!compact && <Globe2 size={14} className="text-zinc-500" aria-hidden />}
        <span className="font-semibold tracking-tight">{brandShort}</span>
        <ChevronDown size={14} className="text-zinc-400" aria-hidden />
      </button>
      {open && (
        <div
          role="listbox"
          className="absolute right-0 mt-1.5 w-56 rounded-lg border bg-white shadow-lg z-50 overflow-hidden"
          style={{ borderColor: '#E0E0E0' }}
          data-testid="master-admin-brand-picker-menu"
        >
          <div className="px-3 pt-2.5 pb-1 text-[10px] font-bold uppercase tracking-wider text-zinc-500">Brand context</div>
          {BRAND_OPTIONS.map((opt) => {
            const active = opt.id === brand;
            return (
              <button
                key={opt.id}
                type="button"
                role="option"
                aria-selected={active}
                onClick={() => { setBrand(opt.id); setOpen(false); }}
                className="w-full text-left px-3 py-2 text-sm flex items-center gap-2.5 hover:bg-zinc-50"
                style={{ background: active ? 'rgba(25, 205, 255,0.06)' : 'transparent' }}
                data-testid={`master-admin-brand-picker-option-${opt.id}`}
              >
                <span className="inline-block w-2 h-2 rounded-full" style={{ background: opt.accent }} aria-hidden />
                <span className={active ? 'font-semibold text-zinc-900' : 'text-zinc-700'}>{opt.label}</span>
                {active && <span className="ml-auto text-[10px] font-bold uppercase tracking-wider text-[#19CDFF]">Active</span>}
              </button>
            );
          })}
          <div className="px-3 pt-2 pb-2.5 text-[10px] leading-snug text-zinc-500 border-t" style={{ borderColor: '#F0F0F0' }}>
            Filters every Master Admin list, dashboard and audit view by brand. Stored locally so it survives reloads.
          </div>
        </div>
      )}
    </div>
  );
};

export default BrandPicker;

import React, { useState } from 'react';
import { Search, X } from 'lucide-react';

// Searchable multi-select of every MOD site an engineer can be allocated to.
export const EngineerSitePicker = ({ sites, value = [], onChange, testid }) => {
  const [q, setQ] = useState('');
  const term = q.trim().toLowerCase();
  const shown = sites.filter((s) => !term || `${s.name} ${s.country || ''}`.toLowerCase().includes(term));
  const byId = Object.fromEntries(sites.map((s) => [s.id, s]));
  const toggle = (id, on) => onChange(on ? [...value, id] : value.filter((x) => x !== id));

  return (
    <div className="rounded-lg bg-cyan-50/40 border border-cyan-100 p-3 space-y-2" data-testid={testid}>
      <div className="flex items-center justify-between">
        <span className="text-[11px] font-semibold uppercase tracking-wider text-slate-500">Sites covered ({value.length})</span>
        {value.length > 0 && <button type="button" onClick={() => onChange([])} className="text-[11px] text-slate-500 hover:text-red-600" data-testid={`${testid}-clear`}>Clear</button>}
      </div>
      {value.length > 0 && (
        <div className="flex flex-wrap gap-1.5" data-testid={`${testid}-selected`}>
          {value.map((id) => (
            <span key={id} className="inline-flex items-center gap-1 text-[12px] px-2 py-0.5 rounded-full bg-white border border-cyan-200 text-cyan-800">
              {byId[id]?.name || id}
              <button type="button" onClick={() => toggle(id, false)} className="text-cyan-500 hover:text-red-600" data-testid={`${testid}-remove-${id}`}><X size={11} /></button>
            </span>
          ))}
        </div>
      )}
      <div className="relative">
        <Search size={13} className="absolute left-2.5 top-2.5 text-slate-400" />
        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search sites or country"
          className="w-full h-8 rounded-md border border-slate-200 bg-white pl-8 pr-2 text-[13px] focus:outline-none focus:ring-2 focus:ring-cyan-400" data-testid={`${testid}-search`} />
      </div>
      <div className="max-h-44 overflow-auto rounded-lg border border-slate-200 bg-white p-2 space-y-1">
        {sites.length === 0 && <p className="text-[11px] text-slate-400" data-testid={`${testid}-empty`}>No MOD sites set up yet — add them under MOD onboarding.</p>}
        {sites.length > 0 && shown.length === 0 && <p className="text-[11px] text-slate-400">No sites match.</p>}
        {shown.map((s) => (
          <label key={s.id} className="flex items-center gap-2 text-[13px] text-slate-700 cursor-pointer">
            <input type="checkbox" checked={value.includes(s.id)} className="accent-cyan-500" onChange={(ev) => toggle(s.id, ev.target.checked)} data-testid={`${testid}-site-${s.id}`} />
            <span className="flex-1 truncate">{s.name}</span>
            {s.country && <span className="text-[10px] text-slate-400">{s.country}</span>}
          </label>
        ))}
      </div>
    </div>
  );
};

/**
 * Estate Modules Rollup — Iter 216av · Phase 3 #8.
 *
 * Read-only finance panel. Surfaces every paying org's module
 * entitlement so HQ-tier finance operators can:
 *   • Audit license usage across the estate
 *   • See which modules are paid vs trial vs orphan
 *   • Catch trials expiring within 7 days
 *   • Spot orgs with NO modules enabled (billing red flag)
 */
import { useEffect, useState, useCallback } from 'react';
import axios from 'axios';
import {
  BarChart3, Loader2, AlertTriangle, Clock, Building2, Activity,
  Calendar, Briefcase, Rocket,
} from 'lucide-react';

const API = process.env.REACT_APP_BACKEND_URL;

const MODULE_META = {
  operations:  { label: 'Operations',  icon: Activity,  accent: '#19CDFF' },
  memberships: { label: 'Memberships', icon: Calendar,  accent: '#10B981' },
  marketing:   { label: 'Marketing',   icon: Rocket,    accent: '#F43F5E' },
  crm:         { label: 'CRM',         icon: Briefcase, accent: '#19CDFF' },
};

export default function EstateRollupPanel() {
  const token = typeof window !== 'undefined' ? localStorage.getItem('token') : null;
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState('');

  const load = useCallback(async () => {
    setLoading(true); setErr('');
    try {
      const r = await axios.get(
        `${API}/api/master-admin/estate/modules-rollup`,
        { headers: { Authorization: `Bearer ${token}` } },
      );
      setData(r.data);
    } catch (e) {
      setErr(e.response?.data?.detail || e.message || 'Failed to load');
    }
    setLoading(false);
  }, [token]);
  useEffect(() => { load(); }, [load]);

  if (loading) return <div className="p-8 text-center" data-testid="estate-rollup-loading"><Loader2 size={24} className="animate-spin inline" /></div>;
  if (err)     return <div className="p-8 text-center text-rose-500 text-sm" data-testid="estate-rollup-error">{err}</div>;
  if (!data)   return null;

  return (
    <div className="space-y-6" data-testid="estate-rollup">
      <div className="flex items-center gap-2 text-zinc-700 dark:text-zinc-300">
        <BarChart3 size={16} />
        <span className="text-sm">{data.total_orgs} organisations · as of {new Date(data.as_of).toLocaleString()}</span>
      </div>

      {/* By module */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-3">
        {Object.entries(data.by_module).map(([key, stats]) => {
          const meta = MODULE_META[key] || { label: key, icon: BarChart3, accent: '#6E7476' };
          const Icon = meta.icon;
          return (
            <div key={key} className="rounded-xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 p-4" data-testid={`estate-module-${key}`}>
              <div className="flex items-center gap-2 mb-3">
                <div className="w-9 h-9 rounded-lg flex items-center justify-center text-white" style={{ background: meta.accent }}>
                  <Icon size={16} />
                </div>
                <div>
                  <p className="text-sm font-bold text-zinc-900 dark:text-zinc-100 pulse-font-heading">{meta.label}</p>
                  <p className="text-[10px] uppercase tracking-wider font-bold text-zinc-500">{stats.enabled} of {data.total_orgs} orgs</p>
                </div>
              </div>
              <div className="grid grid-cols-3 gap-1.5 text-center">
                <Mini label="Paid"          value={stats.paid} />
                <Mini label="Trial active"  value={stats.trial_active} accent="#F59E0B" />
                <Mini label="Expiring 7d"   value={stats.trial_expiring_7d} accent={stats.trial_expiring_7d > 0 ? '#EF4444' : undefined} />
              </div>
            </div>
          );
        })}
      </div>

      {/* By tier */}
      <div className="rounded-xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 p-4">
        <p className="text-sm font-bold text-zinc-900 dark:text-zinc-100 mb-3 inline-flex items-center gap-2">
          <Building2 size={14} /> By account tier
        </p>
        <div className="overflow-x-auto">
          <table className="w-full text-xs">
            <thead>
              <tr className="text-left text-zinc-500 dark:text-zinc-400 border-b border-zinc-200 dark:border-zinc-800">
                <th className="py-2 font-bold uppercase tracking-wider">Tier</th>
                <th className="py-2 font-bold uppercase tracking-wider text-right">Orgs</th>
                {Object.keys(MODULE_META).map((k) => (
                  <th key={k} className="py-2 font-bold uppercase tracking-wider text-right">{MODULE_META[k].label}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {Object.entries(data.by_tier).map(([tier, t]) => (
                <tr key={tier} className="border-b border-zinc-100 dark:border-zinc-800/50" data-testid={`estate-tier-${tier}`}>
                  <td className="py-2 font-bold text-zinc-900 dark:text-zinc-100">{tier}</td>
                  <td className="py-2 text-right tabular-nums">{t.count}</td>
                  {Object.keys(MODULE_META).map((k) => (
                    <td key={k} className="py-2 text-right tabular-nums">{t.modules?.[k] || 0}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Trials expiring */}
      <div className="rounded-xl border border-amber-200 dark:border-amber-800/50 bg-amber-50 dark:bg-amber-950/20 p-4">
        <p className="text-sm font-bold text-amber-900 dark:text-amber-200 mb-3 inline-flex items-center gap-2">
          <Clock size={14} /> Trials expiring in 7 days ({data.trials_expiring_7d.length})
        </p>
        {data.trials_expiring_7d.length === 0 ? (
          <p className="text-xs text-amber-800 dark:text-amber-300">No trials expiring soon.</p>
        ) : (
          <ul className="space-y-1.5">
            {data.trials_expiring_7d.map((t, i) => (
              <li key={i} className="flex items-center gap-3 text-xs" data-testid={`estate-trial-expiring-${i}`}>
                <span className="font-bold text-zinc-900 dark:text-zinc-100">{t.organization_name}</span>
                <span className="text-amber-700 dark:text-amber-300 uppercase tracking-wider font-bold text-[10px]">{t.module}</span>
                <span className="ml-auto text-zinc-600 dark:text-zinc-400">{new Date(t.expires_at).toLocaleString()}</span>
              </li>
            ))}
          </ul>
        )}
      </div>

      {/* Orphans */}
      {data.orphans_count > 0 && (
        <div className="rounded-xl border border-rose-200 dark:border-rose-800/50 bg-rose-50 dark:bg-rose-950/20 p-4" data-testid="estate-orphans">
          <p className="text-sm font-bold text-rose-900 dark:text-rose-200 mb-3 inline-flex items-center gap-2">
            <AlertTriangle size={14} /> Orphan orgs — no modules enabled ({data.orphans_count})
          </p>
          <ul className="space-y-1.5">
            {data.orphans.map((o) => (
              <li key={o.organization_id} className="flex items-center gap-3 text-xs">
                <span className="font-bold text-zinc-900 dark:text-zinc-100">{o.organization_name || o.organization_id.slice(0, 8)}</span>
                <span className="text-rose-700 dark:text-rose-300 uppercase tracking-wider font-bold text-[10px]">{o.account_type || '—'}</span>
                {o.subscription_status && <span className="ml-auto text-zinc-600 dark:text-zinc-400">{o.subscription_status}</span>}
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}

function Mini({ label, value, accent }) {
  return (
    <div className="text-center">
      <p className="text-lg font-bold tabular-nums" style={{ color: accent || 'var(--theme-text)' }}>{value}</p>
      <p className="text-[9px] uppercase tracking-wider font-bold text-zinc-500">{label}</p>
    </div>
  );
}

/**
 * Master Admin — External Service Providers (unified)
 *
 * One place to onboard every external company that services MOD / overseas
 * sites: the company itself plus its field engineers, each a real /bfpo
 * portal login. Engineers flagged MOD/BFPO get the sites they cover;
 * all get an invite link or a temporary password. Replaces the separate
 * Dealer/Engineer, BFPO-Engineers and Service-Providers flows.
 */
import { useState, useEffect, useCallback } from 'react';
import axios from 'axios';
import {
  Truck, Mail, Phone, User, MapPin, Building2, Loader2, Search, ShieldCheck,
  Pencil, X, Plus, Trash2, CheckCircle2, Copy, Link2, KeyRound, Wrench, ArrowLeft,
} from 'lucide-react';
import { toast } from 'sonner';
import { EngineerSitePicker } from './EngineerSitePicker';

const API = process.env.REACT_APP_BACKEND_URL + '/api';
const headers = () => ({ Authorization: `Bearer ${localStorage.getItem('token')}` });

const emptyEngineer = () => ({
  full_name: '', email: '', phone: '', mod_bfpo: 'inherit',
  territory_ids: [], site_ids: [], password_mode: 'invite', temp_password: '',
});

const inputCls = 'w-full px-3 py-2 text-sm rounded-lg border border-slate-200 bg-white focus:outline-none focus:ring-2 focus:ring-cyan-500/30 focus:border-cyan-400';
const labelCls = 'text-[11px] font-semibold uppercase tracking-wide text-slate-500';

const ExternalServiceProviders = () => {
  const [providers, setProviders] = useState([]);
  const [sites, setSites] = useState([]);
  const [loading, setLoading] = useState(true);
  const [q, setQ] = useState('');
  const [view, setView] = useState('list'); // 'list' | 'form'
  const [editing, setEditing] = useState(null); // provider being edited (null = new)
  const [busy, setBusy] = useState(false);
  const [result, setResult] = useState(null);

  const [company, setCompany] = useState({ name: '', contact_name: '', email: '', phone: '', country: '', notes: '', mod_bfpo_default: 'yes' });
  const [engineers, setEngineers] = useState([]);
  const [existingEngs, setExistingEngs] = useState([]);
  const [rowBusy, setRowBusy] = useState(null);
  const [reissue, setReissue] = useState({}); // { [engId]: {busy, mode, invite_url, temp_password} }

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const [p, s] = await Promise.all([
        axios.get(`${API}/master-admin/mod-estate/external-providers`, { headers: headers() }),
        axios.get(`${API}/master-admin/mod-estate/bfpo-sites`, { headers: headers() }),
      ]);
      setProviders(p.data?.providers || []);
      setSites(s.data?.sites || []);
    } catch {
      setProviders([]);
    } finally { setLoading(false); }
  }, []);

  useEffect(() => { load(); }, [load]);

  const openNew = () => {
    setEditing(null); setResult(null);
    setCompany({ name: '', contact_name: '', email: '', phone: '', country: '', notes: '', mod_bfpo_default: 'yes' });
    setEngineers([emptyEngineer()]);
    setExistingEngs([]);
    setView('form');
  };
  const openEdit = (p) => {
    setEditing(p); setResult(null);
    setCompany({
      name: p.name || '', contact_name: p.contact_name || '', email: p.email || '',
      phone: p.phone || '', country: (p.countries || [])[0] || '', notes: p.notes || '',
      mod_bfpo_default: p.is_mod_bfpo ? 'yes' : 'yes',
    });
    setEngineers([]); // only ADD new engineers while editing
    setExistingEngs((p.engineers || []).map((e) => ({
      id: e.id, full_name: e.full_name || '', email: e.email || '', phone: e.phone || '',
      mod_bfpo: e.is_mod_bfpo ? 'yes' : 'no',
      territory_ids: e.territory_ids || [], site_ids: e.site_ids || [],
      login_status: e.login_status,
    })));
    setView('form');
  };
  const backToList = () => { setView('list'); setResult(null); load(); };

  const setEng = (i, k, v) => setEngineers((arr) => arr.map((e, idx) => (idx === i ? { ...e, [k]: v } : e)));
  const addEng = () => setEngineers((arr) => [...arr, emptyEngineer()]);
  const removeEng = (i) => setEngineers((arr) => arr.filter((_, idx) => idx !== i));

  const setExist = (i, k, v) => setExistingEngs((arr) => arr.map((e, idx) => (idx === i ? { ...e, [k]: v } : e)));
  const saveExisting = async (i) => {
    const e = existingEngs[i];
    if (!e.full_name.trim()) return toast.error('Full name is required');
    setRowBusy(e.id);
    try {
      await axios.patch(`${API}/master-admin/mod-estate/external-providers/${editing.id}/engineers/${e.id}`, {
        full_name: e.full_name, phone: e.phone, mod_bfpo: e.mod_bfpo,
        territory_ids: e.territory_ids, site_ids: e.site_ids,
      }, { headers: headers() });
      toast.success(`${e.full_name} updated`);
      load();
    } catch (err) {
      toast.error(err?.response?.data?.detail || 'Could not update engineer');
    } finally { setRowBusy(null); }
  };
  const removeExisting = async (i) => {
    const e = existingEngs[i];
    if (!window.confirm(`Remove ${e.full_name}? This deletes their MOD portal login.`)) return;
    setRowBusy(e.id);
    const doDelete = async (force) => axios.delete(
      `${API}/master-admin/mod-estate/external-providers/${editing.id}/engineers/${e.id}${force ? '?force=true' : ''}`,
      { headers: headers() });
    try {
      const { data } = await doDelete(false);
      toast.success(`${e.full_name} removed`);
      setExistingEngs((arr) => arr.filter((_, idx) => idx !== i));
      load();
    } catch (err) {
      const detail = err?.response?.data?.detail;
      if (err?.response?.status === 409 && detail?.code === 'engineer_has_open_cases') {
        const n = detail.open_case_count;
        const ok = window.confirm(
          `⚠️ ${e.full_name} still has ${n} OPEN service case${n === 1 ? '' : 's'} assigned.\n\n`
          + `Removing them will UNASSIGN those case${n === 1 ? '' : 's'} (the case history is kept, but they'll have no engineer until you reassign).\n\n`
          + `Remove anyway?`);
        if (!ok) { setRowBusy(null); return; }
        try {
          const { data } = await doDelete(true);
          toast.success(`${e.full_name} removed — ${data.unassigned_cases || 0} case(s) unassigned`);
          setExistingEngs((arr) => arr.filter((_, idx) => idx !== i));
          load();
        } catch (err2) {
          toast.error(err2?.response?.data?.detail?.message || err2?.response?.data?.detail || 'Could not remove engineer');
        }
      } else {
        toast.error((detail && (detail.message || detail)) || 'Could not remove engineer');
      }
    } finally { setRowBusy(null); }
  };
  const reissueLogin = async (e, mode) => {
    setReissue((r) => ({ ...r, [e.id]: { busy: true } }));
    try {
      const { data } = await axios.post(`${API}/master-admin/mod-estate/external-providers/${editing.id}/engineers/${e.id}/reissue`, { mode }, { headers: headers() });
      setReissue((r) => ({ ...r, [e.id]: { busy: false, ...data } }));
      toast.success(mode === 'invite' ? 'Invite link reissued' : 'New temporary password set');
      load();
    } catch (err) {
      setReissue((r) => ({ ...r, [e.id]: { busy: false } }));
      toast.error(err?.response?.data?.detail || 'Could not reissue login');
    }
  };

  const renderTerrSites = (eng, onField, idPrefix) => (
    <EngineerSitePicker sites={sites} value={eng.site_ids || []} onChange={(ids) => onField('site_ids', ids)} testid={`${idPrefix}-sites`} />
  );

  const copy = (txt) => { navigator.clipboard?.writeText(txt); toast.success('Copied'); };

  const submit = async () => {
    if (!company.name.trim()) return toast.error('Provider company name is required');
    for (const [i, e] of engineers.entries()) {
      if (!e.full_name.trim() || !e.email.trim()) return toast.error(`Engineer ${i + 1}: name and email are required`);
    }
    setBusy(true);
    try {
      const payload = { ...company, engineers };
      let data;
      if (editing?.id) {
        ({ data } = await axios.patch(`${API}/master-admin/mod-estate/external-providers/${editing.id}`, payload, { headers: headers() }));
        toast.success('Provider updated');
      } else {
        ({ data } = await axios.post(`${API}/master-admin/mod-estate/external-providers`, payload, { headers: headers() }));
        toast.success(`Provider "${company.name}" onboarded`);
      }
      if ((data.engineers || []).length > 0) setResult(data);
      else backToList();
    } catch (e) {
      toast.error(e?.response?.data?.detail || 'Could not save provider');
    } finally { setBusy(false); }
  };

  const filtered = providers.filter((p) => {
    if (!q.trim()) return true;
    const hay = `${p.name} ${p.email} ${p.contact_name} ${(p.engineers || []).map((e) => e.full_name + e.email).join(' ')} ${(p.sites || []).map((s) => s.name).join(' ')}`.toLowerCase();
    return hay.includes(q.trim().toLowerCase());
  });

  /* ── Success screen ─────────────────────────────────────────────── */
  if (view === 'form' && result) {
    const Cred = ({ acc }) => (
      <div className="rounded-lg border border-slate-200 p-3 bg-slate-50" data-testid={`esp-result-${acc.email}`}>
        <div className="flex items-center justify-between gap-2">
          <div className="min-w-0">
            <div className="text-sm font-semibold text-slate-800 truncate">{acc.full_name}
              {acc.is_mod_bfpo && <span className="ml-2 text-[10px] font-bold uppercase px-1.5 py-0.5 rounded-full bg-cyan-100 text-cyan-700">MOD/BFPO</span>}
            </div>
            <div className="text-[12px] text-slate-500 truncate">{acc.email}</div>
          </div>
          <span className={`text-[10px] font-bold uppercase px-2 py-1 rounded-full flex items-center gap-1 ${acc.mode === 'invite' ? 'bg-cyan-100 text-cyan-700' : 'bg-amber-100 text-amber-700'}`}>
            {acc.mode === 'invite' ? <Link2 size={11} /> : <KeyRound size={11} />}
            {acc.mode === 'invite' ? 'Invite link' : 'Temp password'}
          </span>
        </div>
        {acc.mode === 'invite' ? (
          <div className="mt-2 flex items-center gap-2">
            <input readOnly value={acc.invite_url} className="flex-1 text-[11px] font-mono px-2 py-1.5 rounded border border-slate-200 bg-white truncate" data-testid={`esp-invite-${acc.email}`} />
            <button onClick={() => copy(acc.invite_url)} className="p-1.5 rounded border border-slate-200 hover:bg-white"><Copy size={13} /></button>
          </div>
        ) : (
          <div className="mt-2 flex items-center gap-2">
            <code className="flex-1 text-[12px] font-mono px-2 py-1.5 rounded border border-slate-200 bg-white" data-testid={`esp-password-${acc.email}`}>{acc.temp_password}</code>
            <button onClick={() => copy(acc.temp_password)} className="p-1.5 rounded border border-slate-200 hover:bg-white"><Copy size={13} /></button>
          </div>
        )}
      </div>
    );
    return (
      <div className="max-w-2xl space-y-4" data-testid="esp-result-screen">
        <div className="flex items-center gap-2 text-emerald-600">
          <CheckCircle2 size={20} />
          <h3 className="text-base font-bold text-slate-900">Engineer logins created</h3>
        </div>
        <p className="text-sm text-slate-600">Share the credentials below. MOD/BFPO engineers can sign in to the MOD portal straight away.</p>
        <div className="space-y-2">{(result.engineers || []).map((e) => <Cred key={e.id} acc={e} />)}</div>
        <button onClick={backToList} className="mt-2 px-4 py-2 rounded-lg bg-cyan-500 text-white text-sm font-semibold hover:bg-cyan-600" data-testid="esp-back-to-list">
          Back to providers
        </button>
      </div>
    );
  }

  /* ── Add / Edit form ────────────────────────────────────────────── */
  if (view === 'form') {
    return (
      <div className="max-w-3xl space-y-5" data-testid="esp-form">
        <button onClick={() => setView('list')} className="inline-flex items-center gap-1.5 text-sm font-semibold text-slate-500 hover:text-slate-900" data-testid="esp-form-back">
          <ArrowLeft size={15} /> Back to providers
        </button>

        {/* Company */}
        <section className="rounded-xl border border-slate-200 p-4 space-y-4">
          <div className="flex items-center gap-2 text-slate-800"><Building2 size={16} className="text-cyan-500" /><h3 className="text-sm font-bold">Service provider company</h3></div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <label className="block"><span className={labelCls}>Company name *</span><input className={`mt-1 ${inputCls}`} value={company.name} onChange={(e) => setCompany((c) => ({ ...c, name: e.target.value }))} data-testid="esp-company-name" autoFocus /></label>
            <label className="block"><span className={labelCls}>Contact name</span><input className={`mt-1 ${inputCls}`} value={company.contact_name} onChange={(e) => setCompany((c) => ({ ...c, contact_name: e.target.value }))} data-testid="esp-company-contact" /></label>
            <label className="block"><span className={labelCls}>Email (job alerts)</span><input className={`mt-1 ${inputCls}`} value={company.email} onChange={(e) => setCompany((c) => ({ ...c, email: e.target.value }))} data-testid="esp-company-email" /></label>
            <label className="block"><span className={labelCls}>Phone</span><input className={`mt-1 ${inputCls}`} value={company.phone} onChange={(e) => setCompany((c) => ({ ...c, phone: e.target.value }))} data-testid="esp-company-phone" /></label>
            <label className="block"><span className={labelCls}>Country</span><input className={`mt-1 ${inputCls}`} value={company.country} onChange={(e) => setCompany((c) => ({ ...c, country: e.target.value }))} placeholder="e.g. Kenya" data-testid="esp-company-country" /></label>
            <label className="block"><span className={labelCls}>MOD / BFPO default</span>
              <select className={`mt-1 ${inputCls}`} value={company.mod_bfpo_default} onChange={(e) => setCompany((c) => ({ ...c, mod_bfpo_default: e.target.value }))} data-testid="esp-company-mod-default">
                <option value="yes">Yes — MOD/BFPO service provider</option>
                <option value="no">No — directory only</option>
              </select>
            </label>
          </div>
          <label className="block"><span className={labelCls}>Notes</span><textarea rows={2} className={`mt-1 ${inputCls} resize-none`} value={company.notes} onChange={(e) => setCompany((c) => ({ ...c, notes: e.target.value }))} data-testid="esp-company-notes" /></label>
          {editing && <p className="text-[11px] text-slate-400">Editing <strong>{editing.name}</strong>. Existing engineers are unchanged — add new engineer logins below.</p>}
        </section>

        {/* Current engineers (edit / remove) */}
        {editing && existingEngs.length > 0 && (
          <section className="rounded-xl border border-slate-200 p-4 space-y-4" data-testid="esp-existing-engineers">
            <div className="flex items-center gap-2 text-slate-800"><Wrench size={16} className="text-cyan-500" /><h3 className="text-sm font-bold">Current engineers</h3></div>
            {existingEngs.map((e, i) => (
              <div key={e.id} className="rounded-lg border border-slate-200 p-3 space-y-3 bg-white" data-testid={`esp-existing-row-${i}`}>
                <div className="flex items-center justify-between gap-2">
                  <span className={labelCls}>{e.email}
                    <span className={`ml-2 ${e.login_status === 'active' ? 'text-emerald-600' : e.login_status === 'invite_pending' ? 'text-cyan-600' : 'text-amber-600'}`}>
                      {e.login_status === 'active' ? 'Active' : e.login_status === 'invite_pending' ? 'Invite sent' : 'Temp pw'}
                    </span>
                  </span>
                  <button onClick={() => removeExisting(i)} disabled={rowBusy === e.id} className="inline-flex items-center gap-1 text-[11px] font-semibold text-red-500 hover:text-red-700 disabled:opacity-50" data-testid={`esp-existing-remove-${i}`}>
                    <Trash2 size={13} /> Remove
                  </button>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                  <label className="block"><span className={labelCls}>Full name *</span><input className={`mt-1 ${inputCls}`} value={e.full_name} onChange={(ev) => setExist(i, 'full_name', ev.target.value)} data-testid={`esp-existing-name-${i}`} /></label>
                  <label className="block"><span className={labelCls}>Phone</span><input className={`mt-1 ${inputCls}`} value={e.phone} onChange={(ev) => setExist(i, 'phone', ev.target.value)} data-testid={`esp-existing-phone-${i}`} /></label>
                  <label className="block"><span className={labelCls}>MOD / BFPO</span>
                    <select className={`mt-1 ${inputCls}`} value={e.mod_bfpo} onChange={(ev) => setExist(i, 'mod_bfpo', ev.target.value)} data-testid={`esp-existing-mod-${i}`}>
                      <option value="yes">Yes — MOD/BFPO</option>
                      <option value="no">No</option>
                    </select>
                  </label>
                </div>
                {e.mod_bfpo === 'yes' && renderTerrSites(e, (k, v) => setExist(i, k, v), `esp-existing-${i}`)}
                <div className="rounded-lg border border-dashed border-slate-200 p-2.5 space-y-2" data-testid={`esp-existing-reissue-${i}`}>
                  <div className="flex flex-wrap items-center gap-2">
                    <span className="text-[11px] font-semibold text-slate-500">Reissue login:</span>
                    <button type="button" onClick={() => reissueLogin(e, 'invite')} disabled={reissue[e.id]?.busy} className="inline-flex items-center gap-1 text-[11px] font-semibold px-2.5 py-1 rounded-full border border-cyan-200 text-cyan-700 hover:bg-cyan-50 disabled:opacity-50" data-testid={`esp-existing-reissue-invite-${i}`}><Link2 size={12} /> Resend invite</button>
                    <button type="button" onClick={() => reissueLogin(e, 'temp')} disabled={reissue[e.id]?.busy} className="inline-flex items-center gap-1 text-[11px] font-semibold px-2.5 py-1 rounded-full border border-amber-200 text-amber-700 hover:bg-amber-50 disabled:opacity-50" data-testid={`esp-existing-reissue-temp-${i}`}><KeyRound size={12} /> Reset temp password</button>
                    {reissue[e.id]?.busy && <Loader2 size={12} className="animate-spin text-slate-400" />}
                  </div>
                  {reissue[e.id]?.invite_url && (
                    <div className="flex items-center gap-2"><input readOnly value={reissue[e.id].invite_url} className="flex-1 text-[11px] font-mono px-2 py-1.5 rounded border border-slate-200 bg-white truncate" data-testid={`esp-existing-invite-url-${i}`} /><button onClick={() => copy(reissue[e.id].invite_url)} className="p-1.5 rounded border border-slate-200 hover:bg-white"><Copy size={13} /></button></div>
                  )}
                  {reissue[e.id]?.temp_password && (
                    <div className="flex items-center gap-2"><code className="flex-1 text-[12px] font-mono px-2 py-1.5 rounded border border-slate-200 bg-white" data-testid={`esp-existing-temp-pw-${i}`}>{reissue[e.id].temp_password}</code><button onClick={() => copy(reissue[e.id].temp_password)} className="p-1.5 rounded border border-slate-200 hover:bg-white"><Copy size={13} /></button></div>
                  )}
                </div>
                <div className="flex justify-end">
                  <button onClick={() => saveExisting(i)} disabled={rowBusy === e.id} className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold rounded-lg bg-cyan-500 text-white hover:bg-cyan-600 disabled:opacity-50" data-testid={`esp-existing-save-${i}`}>
                    {rowBusy === e.id ? <Loader2 size={13} className="animate-spin" /> : <CheckCircle2 size={13} />} Save changes
                  </button>
                </div>
              </div>
            ))}
          </section>
        )}

        {/* Engineers */}
        <section className="rounded-xl border border-slate-200 p-4 space-y-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2 text-slate-800"><Wrench size={16} className="text-cyan-500" /><h3 className="text-sm font-bold">Engineers {editing && <span className="text-slate-400 font-normal">(add new)</span>}</h3></div>
            <button onClick={addEng} className="flex items-center gap-1.5 px-3 py-1.5 text-sm rounded-lg border border-cyan-200 text-cyan-700 hover:bg-cyan-50" data-testid="esp-add-engineer"><Plus size={14} /> Add engineer</button>
          </div>
          {engineers.length === 0 && <p className="text-[12px] text-slate-400">No engineers added yet.</p>}
          {engineers.map((e, i) => {
            const effectiveMod = e.mod_bfpo === 'inherit' ? company.mod_bfpo_default === 'yes' : e.mod_bfpo === 'yes';
            return (
              <div key={i} className="rounded-lg border border-slate-200 p-3 space-y-3 bg-slate-50/50" data-testid={`esp-engineer-row-${i}`}>
                <div className="flex items-center justify-between">
                  <span className={labelCls}>Engineer {i + 1}</span>
                  <button onClick={() => removeEng(i)} className="p-1 text-slate-400 hover:text-red-500" data-testid={`esp-remove-engineer-${i}`}><Trash2 size={14} /></button>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <label className="block"><span className={labelCls}>Full name *</span><input className={`mt-1 ${inputCls}`} value={e.full_name} onChange={(ev) => setEng(i, 'full_name', ev.target.value)} data-testid={`esp-engineer-name-${i}`} /></label>
                  <label className="block"><span className={labelCls}>Email *</span><input className={`mt-1 ${inputCls}`} value={e.email} onChange={(ev) => setEng(i, 'email', ev.target.value)} data-testid={`esp-engineer-email-${i}`} /></label>
                  <label className="block"><span className={labelCls}>Phone</span><input className={`mt-1 ${inputCls}`} value={e.phone} onChange={(ev) => setEng(i, 'phone', ev.target.value)} data-testid={`esp-engineer-phone-${i}`} /></label>
                  <label className="block"><span className={labelCls}>MOD / BFPO</span>
                    <select className={`mt-1 ${inputCls}`} value={e.mod_bfpo} onChange={(ev) => setEng(i, 'mod_bfpo', ev.target.value)} data-testid={`esp-engineer-mod-${i}`}>
                      <option value="inherit">Use company default ({company.mod_bfpo_default === 'yes' ? 'MOD/BFPO' : 'Directory only'})</option>
                      <option value="yes">Yes — MOD/BFPO</option>
                      <option value="no">No</option>
                    </select>
                  </label>
                </div>
                {effectiveMod && (
                  <EngineerSitePicker sites={sites} value={e.site_ids || []} onChange={(ids) => setEng(i, 'site_ids', ids)} testid={`esp-engineer-sites-${i}`} />
                )}
                <div className="flex flex-wrap items-center gap-4 text-sm">
                  <label className="flex items-center gap-2 cursor-pointer"><input type="radio" checked={e.password_mode === 'invite'} onChange={() => setEng(i, 'password_mode', 'invite')} data-testid={`esp-engineer-invite-${i}`} /> Invite link</label>
                  <label className="flex items-center gap-2 cursor-pointer"><input type="radio" checked={e.password_mode === 'temp'} onChange={() => setEng(i, 'password_mode', 'temp')} data-testid={`esp-engineer-temp-${i}`} /> Temp password</label>
                  {e.password_mode === 'temp' && <input className={`${inputCls} flex-1 min-w-[180px]`} placeholder="Auto-generate if blank" value={e.temp_password} onChange={(ev) => setEng(i, 'temp_password', ev.target.value)} data-testid={`esp-engineer-temp-pw-${i}`} />}
                </div>
              </div>
            );
          })}
        </section>

        <div className="flex items-center gap-3">
          <button onClick={submit} disabled={busy} className="flex items-center gap-2 px-5 py-2.5 rounded-lg bg-cyan-500 text-white text-sm font-bold hover:bg-cyan-600 disabled:opacity-60" data-testid="esp-submit">
            {busy ? <Loader2 size={15} className="animate-spin" /> : <CheckCircle2 size={15} />}
            {editing ? 'Save provider' : 'Onboard provider'}
          </button>
          <span className="text-[12px] text-slate-400">{editing ? 'Updates the company' : 'Creates the provider company'}{engineers.length ? ` + ${engineers.length} engineer login(s)` : ''}.</span>
        </div>
      </div>
    );
  }

  /* ── List ───────────────────────────────────────────────────────── */
  return (
    <div className="space-y-4" data-testid="external-service-providers">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          <Truck size={18} className="text-cyan-600" />
          <h2 className="text-lg font-extrabold text-zinc-900">External Service Providers</h2>
          <span className="text-xs font-semibold px-2 py-0.5 rounded-full bg-zinc-100 text-zinc-600" data-testid="esp-count">{providers.length}</span>
        </div>
        <div className="flex items-center gap-2">
          <div className="relative">
            <Search size={14} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-zinc-400" />
            <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search providers, engineers or sites…" className="pl-8 pr-3 py-2 text-sm rounded-lg border border-zinc-300 focus:border-cyan-400 focus:outline-none w-72" data-testid="esp-search" />
          </div>
          <button onClick={openNew} data-testid="esp-add-btn" className="inline-flex items-center gap-1.5 px-3 py-2 text-sm font-bold rounded-lg bg-cyan-600 text-white hover:bg-cyan-700"><Plus size={15} /> Add provider</button>
        </div>
      </div>

      {loading ? (
        <div className="flex items-center gap-2 text-zinc-500 text-sm py-12 justify-center"><Loader2 size={16} className="animate-spin" /> Loading providers…</div>
      ) : filtered.length === 0 ? (
        <div className="text-center py-16 text-zinc-500" data-testid="esp-empty">
          <Truck size={30} className="mx-auto mb-3 text-zinc-300" />
          <p className="text-sm font-semibold">No service providers yet</p>
          <p className="text-xs mt-1">Add an external provider with its field engineers — each gets a MOD portal login.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-3">
          {filtered.map((p) => (
            <div key={p.id} className="rounded-xl border border-zinc-200 bg-white p-4" data-testid={`esp-card-${p.id}`}>
              <div className="flex items-start justify-between gap-2">
                <div className="min-w-0">
                  <div className="flex items-center gap-2 flex-wrap">
                    <h3 className="font-bold text-zinc-900 truncate">{p.name}</h3>
                    {p.is_mod_bfpo && <span className="inline-flex items-center gap-1 text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-cyan-50 text-cyan-700 border border-cyan-200"><ShieldCheck size={10} /> MOD/BFPO</span>}
                  </div>
                  <div className="mt-1.5 space-y-1 text-sm text-zinc-600">
                    {p.contact_name && <div className="flex items-center gap-1.5"><User size={13} className="text-zinc-400" /> {p.contact_name}</div>}
                    {p.email ? <a href={`mailto:${p.email}`} className="flex items-center gap-1.5 text-cyan-700 hover:underline"><Mail size={13} className="text-zinc-400" /> {p.email}</a> : <div className="flex items-center gap-1.5 text-zinc-400"><Mail size={13} /> No email on file</div>}
                    {p.phone && <a href={`tel:${p.phone}`} className="flex items-center gap-1.5 text-zinc-600 hover:underline"><Phone size={13} className="text-zinc-400" /> {p.phone}</a>}
                    {(p.countries?.length > 0) && <div className="flex items-center gap-1.5 text-zinc-500"><MapPin size={13} className="text-zinc-400" /> {p.countries.join(', ')}</div>}
                  </div>
                </div>
                <button onClick={() => openEdit(p)} data-testid={`esp-edit-${p.id}`} className="shrink-0 inline-flex items-center gap-1 text-xs font-semibold text-zinc-500 hover:text-zinc-900 px-2 py-1 rounded-md border border-zinc-200 hover:border-zinc-300"><Pencil size={12} /> Edit</button>
              </div>

              {/* Engineers */}
              <div className="mt-3 pt-3 border-t border-zinc-100">
                <div className="flex items-center gap-1.5 text-[11px] font-bold uppercase tracking-wide text-zinc-400 mb-1.5"><Wrench size={12} /> {p.engineer_count} engineer{p.engineer_count === 1 ? '' : 's'}</div>
                {(p.engineers || []).length === 0 ? <p className="text-xs text-zinc-400">No engineer logins yet.</p> : (
                  <div className="space-y-1.5" data-testid={`esp-card-engineers-${p.id}`}>
                    {p.engineers.map((e) => (
                      <div key={e.id} className="flex items-center justify-between gap-2 text-[13px]">
                        <div className="min-w-0 flex items-center gap-1.5">
                          <span className="font-semibold text-zinc-800 truncate">{e.full_name}</span>
                          {e.territory_names?.length > 0 && <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-emerald-50 text-emerald-700 border border-emerald-100 whitespace-nowrap">{e.territory_names.join(', ')}</span>}
                          {e.site_names?.length > 0 && <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-cyan-50 text-cyan-700 border border-cyan-100 whitespace-nowrap" title={e.site_names.join(', ')} data-testid={`esp-card-engineer-sites-${e.id}`}>{e.site_names.length === 1 ? e.site_names[0] : `${e.site_names.length} sites`}</span>}
                        </div>
                        <span className={`text-[10px] font-bold uppercase whitespace-nowrap ${e.login_status === 'active' ? 'text-emerald-600' : e.login_status === 'invite_pending' ? 'text-cyan-600' : 'text-amber-600'}`}>
                          {e.login_status === 'active' ? 'Active' : e.login_status === 'invite_pending' ? 'Invite sent' : 'Temp pw'}
                        </span>
                      </div>
                    ))}
                  </div>
                )}
              </div>

              {/* Covered sites */}
              <div className="mt-3 pt-3 border-t border-zinc-100">
                <div className="flex items-center gap-1.5 text-[11px] font-bold uppercase tracking-wide text-zinc-400 mb-1.5"><Building2 size={12} /> Covers {(p.sites || []).length} site{(p.sites || []).length === 1 ? '' : 's'}</div>
                {(p.sites || []).length === 0 ? <p className="text-xs text-zinc-400">No sites assigned yet.</p> : (
                  <div className="flex flex-wrap gap-1.5" data-testid={`esp-card-sites-${p.id}`}>
                    {p.sites.map((s) => <span key={s.id} className="inline-flex items-center gap-1 text-[11px] font-semibold px-2 py-0.5 rounded-full bg-emerald-50 text-emerald-800 border border-emerald-100">{s.name}</span>)}
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default ExternalServiceProviders;

import { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import {
  Upload, FileSpreadsheet, CheckCircle2, AlertTriangle, Copy, Loader2,
  Download, ArrowRight, ArrowLeft, RotateCcw, Database, Sparkles,
} from 'lucide-react';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { notify } from '@/components/notifications';
import { notifyApiError } from '@/lib/formatApiError';

const API = process.env.REACT_APP_BACKEND_URL + '/api';

const STEPS = ['Setup', 'Upload & map', 'Review', 'Done'];

const ImportWizard = ({ presetOrgId = null, projectId = null, projectStepKey = null }) => {
  const [step, setStep] = useState(0);
  const [types, setTypes] = useState([]);
  const [orgs, setOrgs] = useState([]);
  const [importType, setImportType] = useState('');
  const [orgId, setOrgId] = useState(presetOrgId || '');
  const [analysis, setAnalysis] = useState(null);     // {columns, fields, rows, suggested_mapping, dedupe_keys}
  const [mapping, setMapping] = useState({});
  const [validation, setValidation] = useState(null);
  const [dedupeAction, setDedupeAction] = useState('skip');
  const [sendWelcome, setSendWelcome] = useState(false);
  const [report, setReport] = useState(null);
  const [busy, setBusy] = useState(false);
  const [aiBusy, setAiBusy] = useState(false);
  const [aiIssues, setAiIssues] = useState(null);
  const fileRef = useRef(null);

  useEffect(() => {
    axios.get(`${API}/onboarding/import/types`).then((r) => setTypes(r.data.types || [])).catch(() => {});
    if (!presetOrgId) {
      axios.get(`${API}/master-admin/pulse-organizations`)
        .then((r) => { const d = r.data; setOrgs(Array.isArray(d) ? d : (d.organizations || d.orgs || [])); })
        .catch(() => {});
    }
  }, [presetOrgId]);

  const reset = () => {
    setStep(0); setAnalysis(null); setMapping({}); setValidation(null); setReport(null); setDedupeAction('skip'); setSendWelcome(false);
  };

  const downloadTemplate = async () => {
    try {
      const r = await axios.get(`${API}/onboarding/import/template/${importType}`, { responseType: 'blob' });
      const url = URL.createObjectURL(r.data);
      const a = document.createElement('a'); a.href = url; a.download = `${importType}-template.csv`;
      document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);
      notify.success('Template downloaded');
    } catch (e) { notifyApiError(notify, e, 'Template download failed'); }
  };

  const onFile = async (file) => {
    if (!file) return;
    setBusy(true);
    try {
      const fd = new FormData();
      fd.append('import_type', importType);
      fd.append('file', file);
      const { data } = await axios.post(`${API}/onboarding/import/analyze`, fd);
      setAnalysis(data);
      setMapping(data.suggested_mapping || {});
      setStep(1);
      notify.success('File analysed', `${data.row_count} rows · ${data.columns.length} columns. Columns auto-mapped.`);
    } catch (e) { notifyApiError(notify, e, 'Could not read file'); }
    finally { setBusy(false); }
  };

  const askAi = async () => {
    setAiBusy(true);
    try {
      const { data } = await axios.post(`${API}/onboarding/import/ai-analyze`, {
        columns: analysis.columns, sample_rows: analysis.sample_rows,
      });
      if (data.mapping && Object.keys(data.mapping).length) {
        setMapping((m) => ({ ...m, ...data.mapping }));
      }
      setAiIssues(data);
      notify.success('AI suggestions applied', `${Object.keys(data.mapping || {}).length} columns mapped · ${(data.issues || []).length} issue(s) flagged.`);
    } catch (e) { notifyApiError(notify, e, 'AI suggestion failed'); }
    finally { setAiBusy(false); }
  };

  const runValidate = async () => {
    setBusy(true);
    try {
      const { data } = await axios.post(`${API}/onboarding/import/validate`, {
        import_type: importType, mapping, rows: analysis.rows, organization_id: orgId,
      });
      setValidation(data);
      setStep(2);
    } catch (e) { notifyApiError(notify, e, 'Validation failed'); }
    finally { setBusy(false); }
  };

  const runCommit = async () => {
    setBusy(true);
    try {
      const { data } = await axios.post(`${API}/onboarding/import/commit`, {
        import_type: importType, mapping, rows: analysis.rows, organization_id: orgId,
        dedupe_action: dedupeAction, project_id: projectId, project_step_key: projectStepKey,
        send_welcome: sendWelcome,
      });
      setReport(data.report);
      setStep(3);
      notify.success('Import complete', `${data.report.created} created · ${data.report.updated} updated · ${data.report.skipped} skipped`);
    } catch (e) { notifyApiError(notify, e, 'Import failed'); }
    finally { setBusy(false); }
  };

  const typeSpec = types.find((t) => t.id === importType);
  const creatingTenant = !!typeSpec?.creates_tenant;
  const requiredOk = typeSpec ? typeSpec.fields.filter((f) => f.required).every((f) => mapping[f.key]) : false;

  return (
    <Card className="p-5" data-testid="import-wizard">
      {/* Stepper */}
      <div className="flex items-center gap-2 mb-5">
        {STEPS.map((s, i) => (
          <div key={s} className="flex items-center gap-2">
            <div className={`h-6 w-6 rounded-full flex items-center justify-center text-[11px] font-semibold ${
              i < step ? 'bg-emerald-500 text-white' : i === step ? 'bg-blue-600 text-white' : 'bg-zinc-200 text-zinc-500'
            }`}>{i < step ? '✓' : i + 1}</div>
            <span className={`text-xs ${i === step ? 'text-zinc-900 font-medium' : 'text-zinc-400'}`}>{s}</span>
            {i < STEPS.length - 1 && <div className="w-6 h-px bg-zinc-200" />}
          </div>
        ))}
      </div>

      {/* Step 0 — Setup */}
      {step === 0 && (
        <div className="space-y-4" data-testid="iw-setup">
          <div>
            <Label className="text-xs">Import type</Label>
            <Select value={importType} onValueChange={setImportType}>
              <SelectTrigger data-testid="iw-type"><SelectValue placeholder="Choose what to import" /></SelectTrigger>
              <SelectContent>
                {types.map((t) => <SelectItem key={t.id} value={t.id}>{t.label}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>
          {!presetOrgId && !creatingTenant && (
            <div>
              <Label className="text-xs">Target customer</Label>
              <Select value={orgId} onValueChange={setOrgId}>
                <SelectTrigger data-testid="iw-org"><SelectValue placeholder="Which organisation receives these records?" /></SelectTrigger>
                <SelectContent>
                  {orgs.map((o) => <SelectItem key={o.id} value={o.id}>{o.name}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
          )}
          {creatingTenant && (
            <div className="rounded-lg bg-blue-50 border border-blue-200 p-3 text-xs text-blue-800" data-testid="iw-tenant-note">
              Each row creates a new <strong>Lite</strong> customer organisation (<strong>Operations only</strong> — dashboard, equipment &amp; faults, no AI) <strong>and</strong> a matching, linked company in the Pulse&nbsp;Fitness&nbsp;Ltd CRM. Memberships, CRM, Marketing and AI unlock when the customer upgrades to Pro. Existing customers (matched by name) are skipped, not duplicated.
            </div>
          )}
          {importType && (
            <div className="flex items-center justify-between rounded-lg bg-zinc-50 border border-zinc-200 p-3">
              <span className="text-xs text-zinc-600">Get the CSV template with the right columns.</span>
              <Button size="sm" variant="outline" onClick={downloadTemplate} data-testid="iw-template">
                <Download size={13} className="mr-1.5" /> Download template
              </Button>
            </div>
          )}
          <input ref={fileRef} type="file" accept=".csv" className="hidden"
                 onChange={(e) => onFile(e.target.files?.[0])} data-testid="iw-file-input" />
          <Button
            disabled={!importType || (!orgId && !creatingTenant) || busy}
            onClick={() => fileRef.current?.click()}
            data-testid="iw-upload-btn"
          >
            {busy ? <Loader2 size={15} className="mr-1.5 animate-spin" /> : <Upload size={15} className="mr-1.5" />} Upload CSV
          </Button>
        </div>
      )}

      {/* Step 1 — Map */}
      {step === 1 && analysis && (
        <div className="space-y-4" data-testid="iw-map">
          <div className="flex items-center justify-between gap-2">
            <p className="text-xs text-zinc-500">{analysis.row_count} rows detected. Confirm how your columns map — required fields are marked.</p>
            <Button size="sm" variant="outline" onClick={askAi} disabled={aiBusy} data-testid="iw-ai-suggest"
                    className="border-violet-300 text-violet-700 hover:bg-violet-50">
              {aiBusy ? <Loader2 size={13} className="mr-1.5 animate-spin" /> : <Sparkles size={13} className="mr-1.5" />} Ask AI to map
            </Button>
          </div>
          {aiIssues && (
            <div className="rounded-lg border border-violet-200 bg-violet-50 p-3 text-xs space-y-1" data-testid="iw-ai-issues">
              <p className="font-medium text-violet-800">AI suggestion ({aiIssues.confidence || 'n/a'} confidence) — advisory only</p>
              {aiIssues.suggested_type && <p className="text-violet-700">Looks like: <b>{aiIssues.suggested_type}</b></p>}
              {(aiIssues.issues || []).map((i, idx) => (
                <p key={idx} className={i.severity === 'error' ? 'text-red-600' : 'text-amber-700'}>• {i.message}</p>
              ))}
              {(aiIssues.cleanup_suggestions || []).map((s, idx) => <p key={`c${idx}`} className="text-violet-600">✦ {s}</p>)}
            </div>
          )}
          <div className="space-y-2">
            {analysis.fields.map((f) => (
              <div key={f.key} className="flex items-center gap-3" data-testid={`iw-map-${f.key}`}>
                <div className="w-40 text-sm text-zinc-700">
                  {f.label}{f.required && <span className="text-red-500 ml-0.5">*</span>}
                </div>
                <Select value={mapping[f.key] || '__none__'} onValueChange={(v) => setMapping((m) => ({ ...m, [f.key]: v === '__none__' ? undefined : v }))}>
                  <SelectTrigger className="flex-1 h-9"><SelectValue placeholder="— not mapped —" /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="__none__">— not mapped —</SelectItem>
                    {analysis.columns.map((c) => <SelectItem key={c} value={c}>{c}</SelectItem>)}
                  </SelectContent>
                </Select>
              </div>
            ))}
          </div>
          <div className="flex justify-between">
            <Button variant="outline" onClick={() => setStep(0)}><ArrowLeft size={14} className="mr-1.5" /> Back</Button>
            <Button disabled={!requiredOk || busy} onClick={runValidate} data-testid="iw-validate-btn">
              {busy ? <Loader2 size={15} className="mr-1.5 animate-spin" /> : null} Validate <ArrowRight size={14} className="ml-1.5" />
            </Button>
          </div>
        </div>
      )}

      {/* Step 2 — Review */}
      {step === 2 && validation && (
        <div className="space-y-4" data-testid="iw-review">
          <div className="grid grid-cols-4 gap-2">
            <div className="rounded-lg border border-emerald-200 bg-emerald-50 p-3 text-center" data-testid="iw-count-valid">
              <div className="text-xl font-bold text-emerald-600">{validation.counts.valid}</div>
              <div className="text-[10px] text-emerald-700">Valid</div>
            </div>
            <div className="rounded-lg border border-red-200 bg-red-50 p-3 text-center" data-testid="iw-count-errors">
              <div className="text-xl font-bold text-red-600">{validation.counts.errors}</div>
              <div className="text-[10px] text-red-700">Errors</div>
            </div>
            <div className="rounded-lg border border-amber-200 bg-amber-50 p-3 text-center" data-testid="iw-count-dupe-existing">
              <div className="text-xl font-bold text-amber-600">{validation.counts.dupes_existing}</div>
              <div className="text-[10px] text-amber-700">Existing dupes</div>
            </div>
            <div className="rounded-lg border border-amber-200 bg-amber-50 p-3 text-center" data-testid="iw-count-dupe-file">
              <div className="text-xl font-bold text-amber-600">{validation.counts.dupes_in_file}</div>
              <div className="text-[10px] text-amber-700">In-file dupes</div>
            </div>
          </div>

          <div className="max-h-64 overflow-y-auto rounded-lg border border-zinc-200">
            <table className="w-full text-xs">
              <thead className="bg-zinc-50 sticky top-0"><tr>
                <th className="text-left p-2 font-medium text-zinc-500">#</th>
                <th className="text-left p-2 font-medium text-zinc-500">Record</th>
                <th className="text-left p-2 font-medium text-zinc-500">Status</th>
              </tr></thead>
              <tbody>
                {validation.rows.slice(0, 200).map((r) => (
                  <tr key={r.row} className="border-t border-zinc-100">
                    <td className="p-2 text-zinc-400">{r.row}</td>
                    <td className="p-2 text-zinc-700">{Object.values(r.doc).filter(Boolean).slice(0, 3).join(' · ')}</td>
                    <td className="p-2">
                      {r.errors.length > 0 ? (
                        <span className="text-red-600 flex items-center gap-1"><AlertTriangle size={11} /> {r.errors.join('; ')}</span>
                      ) : r.flags.includes('duplicate_existing') ? (
                        <span className="text-amber-600 flex items-center gap-1"><Database size={11} /> Exists already</span>
                      ) : r.flags.includes('duplicate_in_file') ? (
                        <span className="text-amber-600 flex items-center gap-1"><Copy size={11} /> Duplicate in file</span>
                      ) : (
                        <span className="text-emerald-600 flex items-center gap-1"><CheckCircle2 size={11} /> Ready</span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <div>
            <Label className="text-xs">When a matching record already exists</Label>
            <Select value={dedupeAction} onValueChange={setDedupeAction}>
              <SelectTrigger className="w-full" data-testid="iw-dedupe-action"><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value="skip">Skip — keep existing record</SelectItem>
                <SelectItem value="update">Update — merge new values into existing</SelectItem>
                <SelectItem value="create">Create anyway — add as new record</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {creatingTenant && (
            <label className="flex items-start gap-2.5 rounded-lg border border-blue-200 bg-blue-50 p-3 cursor-pointer" data-testid="iw-send-welcome-row">
              <input type="checkbox" className="mt-0.5 h-4 w-4 accent-blue-600"
                     checked={sendWelcome} onChange={(e) => setSendWelcome(e.target.checked)}
                     data-testid="iw-send-welcome" />
              <span className="text-xs text-blue-800">
                <strong>Send welcome emails</strong> — each new customer with a contact email gets a secure
                “set your password” link, plus links to browse modules and the Help &amp; Tutorials.
                Customers without an email are created but not emailed.
              </span>
            </label>
          )}

          <div className="flex justify-between">
            <Button variant="outline" onClick={() => setStep(1)}><ArrowLeft size={14} className="mr-1.5" /> Back</Button>
            <Button disabled={busy} onClick={runCommit} data-testid="iw-commit-btn">
              {busy ? <Loader2 size={15} className="mr-1.5 animate-spin" /> : null} Import {validation.total} rows
            </Button>
          </div>
        </div>
      )}

      {/* Step 3 — Done */}
      {step === 3 && report && (
        <div className="space-y-4 text-center py-4" data-testid="iw-done">
          <CheckCircle2 size={40} className="mx-auto text-emerald-500" />
          <h3 className="text-lg font-semibold">Import complete</h3>
          <div className="grid grid-cols-4 gap-2 max-w-md mx-auto">
            <div><div className="text-xl font-bold text-emerald-600">{report.created}</div><div className="text-[10px] text-zinc-500">Created</div></div>
            <div><div className="text-xl font-bold text-blue-600">{report.updated}</div><div className="text-[10px] text-zinc-500">Updated</div></div>
            <div><div className="text-xl font-bold text-zinc-500">{report.skipped}</div><div className="text-[10px] text-zinc-500">Skipped</div></div>
            <div><div className="text-xl font-bold text-red-600">{report.failed}</div><div className="text-[10px] text-zinc-500">Failed</div></div>
          </div>
          {report.errors?.length > 0 && (
            <div className="max-w-md mx-auto text-left text-xs text-red-600 bg-red-50 rounded-lg p-3 max-h-32 overflow-y-auto">
              {report.errors.slice(0, 20).map((e, i) => <div key={i}>Row {e.row}: {e.errors.join('; ')}</div>)}
            </div>
          )}
          {(report.welcome_sent > 0 || report.welcome_no_email > 0 || report.welcome_failed > 0) && (
            <div className="max-w-md mx-auto text-xs text-zinc-600 bg-zinc-50 rounded-lg p-3" data-testid="iw-welcome-summary">
              Welcome emails: <strong className="text-emerald-600">{report.welcome_sent} sent</strong>
              {report.welcome_no_email > 0 && <> · <strong className="text-amber-600">{report.welcome_no_email} had no email</strong></>}
              {report.welcome_failed > 0 && <> · <strong className="text-red-600">{report.welcome_failed} failed</strong></>}
            </div>
          )}
          <Button variant="outline" onClick={reset} data-testid="iw-restart"><RotateCcw size={14} className="mr-1.5" /> Import more</Button>
        </div>
      )}
    </Card>
  );
};

export default ImportWizard;

/**
 * Iter 216h22 — Master Admin Integrations Hub (P5 redesign).
 *
 * Single page that consolidates the 4 integration surfaces operators
 * deal with daily:
 *   • Stripe Connect — platform-level OAuth + per-customer onboarding
 *   • Sicon Service  — Sage 200 ledger bridge (cases + invoices)
 *   • Orbit 4        — stock / equipment master
 *   • Sage 200       — per-org customer ledger numbers (rides Sicon)
 *
 * Layout:
 *   ┌────────────────────────────────────────────────────────┐
 *   │ Title + summary pills (X connected · Y degraded · …)   │
 *   ├──────────┬──────────┬──────────┬───────────────────────┤
 *   │ Stripe   │ Sicon    │ Orbit 4  │ Sage 200              │
 *   │  card    │  card    │  card    │  card                 │
 *   └──────────┴──────────┴──────────┴───────────────────────┘
 *
 * Each card carries: status pill · brand badge · last sync · events 24h
 * · org coverage (X of Y orgs configured). Clicking the card opens a
 * right-hand drawer with the FULL existing configuration page embedded
 * — mappings, logs, config, per-org table all preserved.
 */
import { useEffect, useState, useCallback } from 'react';
import axios from 'axios';
import { Sheet, SheetContent, SheetHeader, SheetTitle } from '@/components/ui/sheet';
import { ArrowLeftRight, Banknote, Plug, ShieldCheck, RefreshCw, AlertTriangle, CheckCircle2, Clock, XCircle, ExternalLink, Settings } from 'lucide-react';
import Button from '@/components/shared/Button';
import SiconIntegrationPage from './SiconIntegrationPage';
import IntegrationAdminPanel from '../IntegrationAdminPanel';
import AdminStripeConnect from './AdminStripeConnect';
import { useBrandContext } from './BrandContext';

const API_BASE = `${process.env.REACT_APP_BACKEND_URL}/api`;

const STATUS_TONES = {
  connected:      { label: 'Connected',      bg: '#ECFDF5', fg: '#047857', border: '#A7F3D0', icon: CheckCircle2 },
  degraded:       { label: 'Degraded',       bg: '#FFFBEB', fg: '#B45309', border: '#FDE68A', icon: AlertTriangle },
  not_configured: { label: 'Not configured', bg: '#F7F7F7', fg: '#565B5E', border: '#E0E0E0', icon: XCircle },
  down:           { label: 'Down',           bg: '#FEF2F2', fg: '#B91C1C', border: '#FECACA', icon: XCircle },
};

const ICONS = {
  stripe_connect: Banknote,
  sicon:          ArrowLeftRight,
  orbit4:         Plug,
  sage200:        ShieldCheck,
};

const BRAND_TONES = {
  pulse:   { label: 'Pulse Fitness', bg: 'rgba(25, 205, 255,0.08)', fg: '#0091CA' },
  gymaxis: { label: 'Pulse Fitness',       bg: 'rgba(16,185,129,0.10)', fg: '#047857' },
  all:     { label: 'Both brands',   bg: 'rgba(63,63,70,0.08)', fg: '#393E41' },
};

const formatSince = (iso) => {
  if (!iso) return 'No events recorded';
  const then = new Date(iso);
  if (Number.isNaN(then.getTime())) return iso;
  const ms = Date.now() - then.getTime();
  const mins = Math.round(ms / 60_000);
  if (mins < 1) return 'just now';
  if (mins < 60) return `${mins} min ago`;
  const h = Math.round(mins / 60);
  if (h < 24) return `${h} h ago`;
  return `${Math.round(h / 24)} d ago`;
};

const StatusPill = ({ status, testId }) => {
  const tone = STATUS_TONES[status] || STATUS_TONES.not_configured;
  const Icon = tone.icon;
  return (
    <span
      className="inline-flex items-center gap-1 rounded-full border px-2 py-0.5 text-[10px] font-bold uppercase tracking-wider"
      style={{ background: tone.bg, color: tone.fg, borderColor: tone.border }}
      data-testid={testId}
    >
      <Icon size={10} />
      {tone.label}
    </span>
  );
};

const BrandBadge = ({ brand }) => {
  const tone = BRAND_TONES[brand] || BRAND_TONES.all;
  return (
