export default OrgIntegrationsTab;

/**
 * Org People directory (Master Admin → People → Org People).
 *
 * One row per person showing JOB TITLE + which MODULES they can access
 * (Operations · CRM · Memberships · Marketing) at a glance — the entitlement
 * view that complements the contact-centric "Directory" tab.
 *
 * Feed: the existing /api/master-admin/users payload, now enriched with
 * `job_title` and `module_access` (see master_admin_users._enrich_with_module_access).
 */
import { useMemo, useState } from 'react';
import axios from 'axios';
import { toast } from 'sonner';
import { Search, Check, Minus, Download, Briefcase, ChevronRight, Pencil, Loader2 } from 'lucide-react';

const MODULES = [
  { key: 'operations', label: 'Operations', color: '#19CDFF' },
  { key: 'crm', label: 'CRM', color: '#B45309' },
  { key: 'memberships', label: 'Memberships', color: '#047857' },
  { key: 'marketing', label: 'Marketing', color: '#0091CA' },
];

const roleLabel = (u) => {
  const r = (u.display_role || u.role || 'staff').toLowerCase();
  const map = {
    pulse_master_admin: 'Pulse Admin', 'pulse platform admin': 'Pulse Admin',
    master_admin: 'Master Admin', owner: 'Owner', manager: 'Manager', staff: 'Staff',
    'partner engineer': 'Partner Engineer', engineer_partner: 'Partner Engineer',
  };
  return map[r] || (u.display_role || u.role || 'Staff');
};

const ModuleCell = ({ on, color }) => (
  <td className="px-2 py-3 text-center">
    {on
      ? <Check size={15} className="inline" style={{ color }} aria-label="Has access" />
      : <Minus size={14} className="inline text-zinc-300" aria-label="No access" />}
  </td>
);

const OrgPeopleDirectory = ({ users = [], API, onReload, onOpenUser }) => {
  const [search, setSearch] = useState('');
  const [moduleFilter, setModuleFilter] = useState('');
  const [edits, setEdits] = useState({});       // userId → saved title (optimistic)
  const [editingId, setEditingId] = useState(null);
  const [draft, setDraft] = useState('');
  const [savingId, setSavingId] = useState(null);

  const titleOf = (u) => (edits[u.id] !== undefined ? edits[u.id] : (u.job_title || ''));

  const startEdit = (e, u) => {
    e.stopPropagation();
    setEditingId(u.id);
    setDraft(titleOf(u));
  };
  const cancelEdit = () => { setEditingId(null); setDraft(''); };
  const saveTitle = async (u) => {
    const next = draft.trim();
    if (next === (titleOf(u) || '')) { cancelEdit(); return; }
    setSavingId(u.id);
    try {
      await axios.put(`${API}/master-admin/users/${u.id}/edit`, { job_title: next }, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
      });
      setEdits((m) => ({ ...m, [u.id]: next }));
      toast.success('Job title updated');
      onReload?.();
      cancelEdit();
    } catch (err) {
      toast.error(err?.response?.data?.detail || 'Could not update job title');
    } finally { setSavingId(null); }
  };

  const active = useMemo(
    () => users.filter((u) => !(u.status === 'archived' || u.is_archived)),
    [users],
  );

  const filtered = useMemo(() => {
    const s = search.trim().toLowerCase();
    return active.filter((u) => {
      if (moduleFilter && !(u.module_access || {})[moduleFilter]) return false;
      if (s) {
        const hay = `${u.full_name || ''} ${u.email || ''} ${u.organization_name || ''} ${u.job_title || ''}`.toLowerCase();
        if (!hay.includes(s)) return false;
      }
      return true;
    });
  }, [active, search, moduleFilter]);

  const exportCsv = () => {
    const head = ['Name', 'Email', 'Job title', 'Organisation', 'Role', ...MODULES.map((m) => m.label)];
    const esc = (v) => `"${String(v ?? '').replace(/"/g, '""')}"`;
    const lines = filtered.map((u) => [
      u.full_name || '', u.email || '', titleOf(u), u.organization_name || '', roleLabel(u),
      ...MODULES.map((m) => ((u.module_access || {})[m.key] ? 'Yes' : 'No')),
    ].map(esc).join(','));
    const csv = [head.map(esc).join(','), ...lines].join('\n');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
    const a = document.createElement('a');
    a.href = url; a.download = 'org-people.csv'; a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-4" data-testid="org-people-directory">
      <div className="flex items-start justify-between gap-3 flex-wrap">
        <div>
          <h2 className="text-xl font-bold text-zinc-900 tracking-tight flex items-center gap-2">
            <Briefcase size={18} className="text-[var(--color-brand-blue)]" /> Org People
          </h2>
          <p className="text-sm text-zinc-500 mt-0.5">Every person with their job title and the modules they can access — one row each.</p>
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          <div className="relative">
            <Search size={14} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-zinc-400 pointer-events-none" />
            <input
              type="text"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search name, job title, org…"
              className="pl-7 pr-3 py-1.5 rounded-full border bg-white text-xs"
              style={{ borderColor: '#E0E0E0', width: 240 }}
              data-testid="org-people-search"
            />
          </div>
          <select
            value={moduleFilter}
            onChange={(e) => setModuleFilter(e.target.value)}
            className="px-3 py-1.5 rounded-full border bg-white text-xs font-medium text-zinc-700"
            style={{ borderColor: '#E0E0E0' }}
            data-testid="org-people-module-filter"
          >
            <option value="">All modules</option>
            {MODULES.map((m) => <option key={m.key} value={m.key}>Has {m.label}</option>)}
          </select>
          <button
            type="button"
            onClick={exportCsv}
            className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full border bg-white text-xs font-semibold text-zinc-700 hover:bg-zinc-50"
            style={{ borderColor: '#E0E0E0' }}
            data-testid="org-people-export-csv"
          >
            <Download size={13} /> CSV
          </button>
        </div>
      </div>

      <div className="rounded-lg border bg-white overflow-x-auto" style={{ borderColor: '#E0E0E0' }} data-testid="org-people-table">
        {filtered.length === 0 ? (
          <div className="px-6 py-10 text-center text-sm text-zinc-500" data-testid="org-people-empty">No people match the current filter.</div>
        ) : (
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b" style={{ borderColor: '#E0E0E0' }}>
                <th className="text-left px-4 py-2.5 font-semibold text-zinc-600 min-w-[220px]">Person</th>
                <th className="text-left px-3 py-2.5 font-semibold text-zinc-600 min-w-[150px]">Job title</th>
                <th className="text-left px-3 py-2.5 font-semibold text-zinc-600 min-w-[140px]">Organisation</th>
                <th className="text-left px-3 py-2.5 font-semibold text-zinc-600">Role</th>
                {MODULES.map((m) => (
                  <th key={m.key} className="px-2 py-2.5 text-center font-medium text-zinc-600 min-w-[92px]" data-testid={`org-people-col-${m.key}`}>
                    {m.label}
                  </th>
                ))}
                <th className="px-2" />
              </tr>
            </thead>
            <tbody className="divide-y" style={{ borderColor: '#F0F0F0' }}>
              {filtered.map((u) => (
                <tr
                  key={`${u.id}-${u.organization_id || ''}`}
                  onClick={() => onOpenUser?.(u)}
                  className="hover:bg-zinc-50 transition-colors cursor-pointer"
                  data-testid={`org-people-row-${u.id}`}
                >
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-2.5">
                      <div className="w-8 h-8 rounded-full flex-shrink-0 flex items-center justify-center text-xs font-bold" style={{ background: '#F0F0F0', color: '#565B5E' }}>
                        {(u.full_name || u.email || '?').slice(0, 1).toUpperCase()}
                      </div>
                      <div className="min-w-0">
                        <div className="font-semibold text-zinc-900 truncate">{u.full_name || u.email}</div>
                        <div className="text-[11px] text-zinc-500 truncate">{u.email}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-3 py-3" onClick={(e) => e.stopPropagation()}>
                    {editingId === u.id ? (
                      <div className="flex items-center gap-1">
                        <input
                          autoFocus
                          value={draft}
                          onChange={(e) => setDraft(e.target.value)}
                          onKeyDown={(e) => { if (e.key === 'Enter') saveTitle(u); if (e.key === 'Escape') cancelEdit(); }}
                          onBlur={() => saveTitle(u)}
                          placeholder="Job title"
                          className="px-2 py-1 rounded border text-xs w-36"
                          style={{ borderColor: '#C9CBCC' }}
                          data-testid={`org-people-title-input-${u.id}`}
                        />
                        {savingId === u.id && <Loader2 size={13} className="animate-spin text-zinc-400" />}
                      </div>
                    ) : (
                      <button
                        type="button"
                        onClick={(e) => startEdit(e, u)}
                        className="group inline-flex items-center gap-1.5 text-zinc-700 hover:text-[var(--color-brand-blue)]"
                        title="Edit job title"
                        data-testid={`org-people-title-${u.id}`}
                      >
                        {titleOf(u) || <span className="text-zinc-400 italic">Add title</span>}
                        <Pencil size={11} className="opacity-0 group-hover:opacity-100 transition-opacity" />
                      </button>
                    )}
                  </td>
                  <td className="px-3 py-3 text-zinc-600 truncate">{u.organization_name && u.organization_name !== 'N/A' ? u.organization_name : <span className="text-zinc-400">—</span>}</td>
                  <td className="px-3 py-3">
                    <span className="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider bg-zinc-100 text-zinc-600">{roleLabel(u)}</span>
                  </td>
                  {MODULES.map((m) => (
                    <ModuleCell key={m.key} on={!!(u.module_access || {})[m.key]} color={m.color} />
                  ))}
                  <td className="px-2 text-right"><ChevronRight size={15} className="text-zinc-400 inline" /></td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      <div className="flex items-center justify-between text-[11px] text-zinc-500">
        <span className="flex items-center gap-3">
          <span className="flex items-center gap-1"><Check size={12} className="text-emerald-500" /> Has access</span>
          <span className="flex items-center gap-1"><Minus size={12} className="text-zinc-300" /> No access</span>
        </span>
        <span data-testid="org-people-count">Showing {filtered.length} of {active.length} people</span>
      </div>
    </div>
  );
};

export default OrgPeopleDirectory;

/**
 * Iter 216h19 — People Directory (Phase 3 of the Master Admin
 * redesign blueprint).
 *
 * Single source of truth for every human on the platform. Replaces
 * the 3 legacy panels (AdminUsers + GlobalUsersPanel + AdminPulseAdmins
 * + AdminCRMUsers — 4 surfaces collapsing into 1) with:
 *
 *   • Top stats strip       — totals + breakdown by category.
 *   • Filter pill row       — Pulse Admins · Owners · Staff · CRM contacts · Archived.
 *   • Search box            — name / email / org.
 *   • Brand-aware list      — already brand-filtered by the parent
 *                             MasterAdminPage.loadData (iter 216h18).
 *   • Row "portals" chips   — Service Portal · CRM · Pulse Platform.
 *   • Row drawer            — opens existing UserEditDialog (Profile +
 *                             Sites + Permissions tabs already exist).
 *
 * The backend feed is the existing /api/master-admin/users payload
 * which already returns a deduped, brand-scoped, org-enriched merge
 * of users + crm_users + pulse-admin memberships. No new endpoint
 * needed.
 */
import { useMemo, useState } from 'react';
import { Search, Users, ShieldCheck, Briefcase, UserCog, Archive, AlertTriangle, ChevronRight, Clock, Wrench } from 'lucide-react';
import { useBrandContext } from './BrandContext';

const classifyUser = (u) => {
  if (u.is_partner_engineer || u.role === 'engineer_partner' || u.display_role === 'Partner Engineer') return 'partner_engineers';
  if (u.is_pulse_master_admin || u.role === 'pulse_master_admin' || u.user_type === 'pulse_master_admin') return 'pulse_admins';
  if (u.role === 'owner') return 'owners';
  if (u.role === 'manager' || u.role === 'staff') return 'staff';
  if (Array.isArray(u.portals) && u.portals.length === 1 && u.portals[0] === 'crm') return 'crm_only';
  return 'staff';
};

const PortalBadge = ({ portal }) => {
  const styles = {
    service_portal: { bg: 'rgba(16,185,129,0.12)', fg: '#047857', label: 'Service Portal' },
    engineer_app:   { bg: 'rgba(25, 205, 255,0.12)',  fg: '#0091ca', label: 'Engineer App' },
    crm:            { bg: 'rgba(245,158,11,0.14)', fg: '#B45309', label: 'CRM' },
    pulse_platform: { bg: 'rgba(25, 205, 255,0.12)',   fg: '#19CDFF', label: 'Pulse Platform' },
  }[portal] || { bg: 'rgba(113,113,122,0.12)', fg: '#565B5E', label: portal };
  return (
    <span
      className="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold tracking-wide"
      style={{ background: styles.bg, color: styles.fg }}
      data-testid={`people-portal-badge-${portal}`}
    >
      {styles.label}
    </span>
  );
};

const RoleChip = ({ user }) => {
  const role = (user.display_role || user.role || 'staff').toLowerCase();
  const map = {
    'pulse_master_admin':    { label: 'Pulse Admin', bg: '#E4F9FF', fg: '#0091CA' },
    'pulse platform admin':  { label: 'Pulse Admin', bg: '#E4F9FF', fg: '#0091CA' },
    'owner':                 { label: 'Owner',       bg: '#FAF5FF', fg: '#0091CA' },
    'manager':               { label: 'Manager',     bg: '#ECFDF5', fg: '#047857' },
    'staff':                 { label: 'Staff',       bg: '#F0F0F0', fg: '#393E41' },
    'partner engineer':      { label: 'Partner Engineer', bg: '#EEF2FF', fg: '#0091ca' },
    'master_admin':          { label: 'Master Admin', bg: '#FFEDD5', fg: '#C2410C' },
  };
  const tone = map[role] || map.staff;
  return (
    <span
      className="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider"
      style={{ background: tone.bg, color: tone.fg }}
      data-testid={`people-role-chip-${user.id}`}
    >
      {tone.label}
    </span>
  );
};

const StatTile = ({ label, value, hint, icon: Icon, accent, active, onClick }) => (
  <button
    type="button"
    onClick={onClick}
    aria-pressed={active}
    className="text-left rounded-lg border bg-white p-4 transition-all hover:-translate-y-0.5 hover:shadow-[0_8px_20px_-8px_rgba(27, 28, 29,0.18)] focus:outline-none"
    style={{
      borderColor: active ? accent : '#E0E0E0',
      boxShadow: active ? `inset 0 0 0 1px ${accent}` : undefined,
      background: active ? `${accent}0A` : '#fff',
    }}
    data-testid={`people-stat-${label.toLowerCase().replace(/\s+/g, '-')}`}
  >
    <div className="flex items-start justify-between mb-1">
      <span className="text-[10px] font-bold uppercase tracking-wider text-zinc-500">{label}</span>
      {Icon && <Icon size={14} style={{ color: accent || '#6E7476' }} />}
    </div>
    <div className="text-2xl font-bold" style={{ color: accent || '#1B1C1D' }}>{value}</div>
    {hint && <div className="text-[10px] text-zinc-500 mt-0.5">{hint}</div>}
  </button>
);

const PeopleDirectory = ({ users = [], onOpenUser }) => {
  const { brandLabel } = useBrandContext();
  const [activePill, setActivePill] = useState('all');
  const [search, setSearch] = useState('');

  // Clicking the active filter card again clears back to "Everyone".
  const setFilter = (id) => setActivePill((cur) => (cur === id && id !== 'all') ? 'all' : id);

  // Iter 216h19 — classify once for cheap re-filtering on pill change.
  const classified = useMemo(() => {
    return users.map((u) => ({ ...u, _category: classifyUser(u) }));
  }, [users]);

  const stats = useMemo(() => {
    const c = { total: classified.length, pulse_admins: 0, owners: 0, staff: 0, partner_engineers: 0, crm_only: 0, archived: 0, mismatch: 0, invite_pending: 0 };
    for (const u of classified) {
      if (u.status === 'archived' || u.is_archived) { c.archived += 1; continue; }
      c[u._category] = (c[u._category] || 0) + 1;
      if (u.invited_role && u.invited_role !== u.role) c.mismatch += 1;
      if (u.invite_pending) c.invite_pending += 1;
    }
    return c;
  }, [classified]);

  const filtered = useMemo(() => {
    const s = search.trim().toLowerCase();
    return classified.filter((u) => {
      // Pill filter
      const isArchived = u.status === 'archived' || u.is_archived;
      if (activePill === 'archived') {
        if (!isArchived) return false;
      } else if (activePill === 'all') {
        if (isArchived) return false; // hide archived from "Everyone"
      } else if (activePill === 'mismatch') {
        if (isArchived) return false;
        if (!(u.invited_role && u.invited_role !== u.role)) return false;
      } else if (activePill === 'invite_pending') {
        if (isArchived) return false;
        if (!u.invite_pending) return false;
      } else {
        if (isArchived) return false;
        if (u._category !== activePill) return false;
      }
      // Search filter
      if (s) {
        const hay = `${u.full_name || ''} ${u.email || ''} ${u.organization_name || ''}`.toLowerCase();
        if (!hay.includes(s)) return false;
      }
      return true;
    });
  }, [classified, activePill, search]);

  return (
    <div className="space-y-5" data-testid="people-directory">
      {/* Header */}
      <div className="flex items-start justify-between gap-3 flex-wrap">
        <div>
          <h2 className="text-xl font-bold text-zinc-900 tracking-tight">People directory</h2>
          <p className="text-sm text-zinc-500 mt-0.5">Single source of truth — click any card below to filter. Brand context: <span className="font-semibold text-zinc-700">{brandLabel}</span>.</p>
        </div>
        <div className="relative flex-shrink-0">
          <Search size={14} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-zinc-400 pointer-events-none" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search name, email or org..."
            className="pl-7 pr-3 py-1.5 rounded-full border bg-white text-xs"
            style={{ borderColor: '#E0E0E0', width: 280 }}
            data-testid="people-search-input"
          />
        </div>
      </div>

      {/* Stats strip — each card is an interactive filter (replaces the old pill row) */}
      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 xl:grid-cols-9 gap-3" data-testid="people-stats-strip">
        <StatTile label="Total active" value={stats.total - stats.archived} icon={Users} accent="#1B1C1D" hint={stats.archived ? `${stats.archived} archived` : ''} active={activePill === 'all'} onClick={() => setFilter('all')} />
