export default function PulseFitnessGrowthHub({ onJumpSection }) {
  const [data, setData] = useState(null);
  const [err, setErr] = useState(null);
  const [busy, setBusy] = useState(false);
  // Iter 220ah — server-driven B2B journey template list. We keep it
  // in its own state slot so launching a template doesn't reload the
  // whole overview payload.
  const [templates, setTemplates] = useState(null);
  const [templatesErr, setTemplatesErr] = useState(null);
  // Iter 220aj — 30-day sparklines per KPI tile.
  const [spark, setSpark] = useState(null);
  // Iter 220ak — inbound demo-request alerts feed.
  const [alerts, setAlerts] = useState({ rows: [], unread: 0 });

  const load = useCallback(async () => {
    setBusy(true); setErr(null);
    try {
      const r = await axios.get(`${API}/api/master-admin/growth/overview`, { headers: auth() });
      setData(r.data);
    } catch (e) {
      setErr(e?.response?.data?.detail || 'Could not load growth overview');
    } finally { setBusy(false); }
  }, []);

  const loadSparklines = useCallback(async () => {
    try {
      const r = await axios.get(`${API}/api/master-admin/growth/sparklines`, { headers: auth() });
      setSpark(r.data?.series || null);
    } catch (_e) {
      // Sparklines are optional — silent fail so the Hub still renders
      // when the endpoint is mid-deploy. The tiles just hide them.
      setSpark(null);
    }
  }, []);

  const loadAlerts = useCallback(async () => {
    try {
      const r = await axios.get(`${API}/api/master-admin/growth/alerts`, { headers: auth() });
      setAlerts({
        rows: r.data?.alerts || [],
        unread: Number(r.data?.unread || 0),
      });
    } catch (_e) {
      setAlerts({ rows: [], unread: 0 });
    }
  }, []);

  const markAlertsRead = async () => {
    try {
      await axios.post(`${API}/api/master-admin/growth/alerts/mark-read`, {}, { headers: auth() });
      await loadAlerts();
    } catch (_e) { /* silent */ }
  };

  const loadTemplates = useCallback(async () => {
    setTemplatesErr(null);
    try {
      const r = await axios.get(
        `${API}/api/master-admin/growth/journey-templates`,
        { headers: auth() },
      );
      setTemplates(r.data?.templates || []);
    } catch (e) {
      setTemplatesErr(e?.response?.data?.detail || 'Could not load journey templates');
    }
  }, []);

  useEffect(() => { load(); loadTemplates(); loadSparklines(); loadAlerts(); }, [load, loadTemplates, loadSparklines, loadAlerts]);

  // Best-effort: change section in the parent MasterAdminPage. Falls
  // back to a soft hash navigation if the prop isn't wired (e.g. when
  // rendered in isolation by Jest).
  //
  // Iter 220aq — Some Growth Hub tiles deep-link to surfaces that live
  // OUTSIDE Master Admin (the CRM portal at `/crm`). For those keys we
  // perform a full URL navigation with `?tab=` so the CRM lands on the
  // right inner tab. Without this, clicking "Open CRM" / "Open
  // Companies" routed to a Master Admin section id that didn't exist
  // and the content area went blank.
  const CRM_TAB_MAP = {
    'crm-deals': 'pipeline',
    'crm-analytics': 'pipeline',
    'crm-companies': 'companies',
    'crm-contacts': 'contacts',
  };
  const jump = (sectionId) => {
    if (CRM_TAB_MAP[sectionId]) {
      try {
        window.location.assign(`/crm?tab=${CRM_TAB_MAP[sectionId]}`);
        return;
      } catch { /* fall through */ }
    }
    if (typeof onJumpSection === 'function') {
      onJumpSection(sectionId);
      return;
    }
    try { window.location.hash = `#${sectionId}`; } catch { /* noop */ }
  };

  if (err) {
    return (
      <div className="rounded-2xl border border-rose-200 bg-rose-50 text-rose-700 px-4 py-3 text-sm" data-testid="growth-hub-error">
        {err}
      </div>
    );
  }

  if (!data) {
    return (
      <div className="rounded-2xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-950 p-10 flex items-center justify-center gap-2 text-zinc-500" data-testid="growth-hub-loading">
        <Loader2 size={16} className="animate-spin" /> Loading Pulse Fitness growth overview…
      </div>
    );
  }

  return (
    <div className="space-y-5" data-testid="gymaxis-growth-hub">
      {/* Hero — explains this is Pulse Fitness self-promo. */}
      <header
        className="rounded-2xl border border-zinc-200 dark:border-zinc-800 bg-gradient-to-r from-fuchsia-50 via-white to-blue-50 dark:from-zinc-900 dark:via-zinc-900 dark:to-zinc-900 px-4 sm:px-5 py-4 flex flex-col sm:flex-row sm:items-center gap-3 sm:gap-4"
        data-testid="growth-hub-hero"
      >
        <div className="flex items-start gap-3 sm:contents">
          <span className="shrink-0 w-10 h-10 sm:w-12 sm:h-12 rounded-2xl bg-gradient-to-br from-fuchsia-500 to-blue-600 text-white flex items-center justify-center shadow-[0_8px_20px_-8px_rgba(217,70,239,0.6)]">
            <Rocket size={18} />
          </span>
          <div className="flex-1 min-w-0">
            <p className="text-[10px] sm:text-[11px] uppercase tracking-[0.18em] font-bold text-fuchsia-700 dark:text-fuchsia-400">
              Growth · Master Admin
            </p>
            <h2 className="text-lg sm:text-2xl font-extrabold text-zinc-900 dark:text-zinc-50 tracking-tight mt-0.5 leading-tight">
              Pulse Fitness Growth Hub
            </h2>
            <p className="hidden sm:block text-xs sm:text-sm text-zinc-600 dark:text-zinc-300 mt-1 max-w-2xl">
              How we&apos;re marketing Pulse Fitness to fitness operators. Pulls live
              numbers from Trials, SEO Autopilot, Outbound Emails, CRM Pipeline
              and Sales Insights — no module is rebuilt here, every tile deep-links
              into the existing tool.
            </p>
            <p className="sm:hidden text-xs text-zinc-600 dark:text-zinc-300 mt-1 leading-snug">
              Live numbers from Trials, SEO, Outbound, CRM &amp; Sales — every tile deep-links into the tool.
            </p>
          </div>
        </div>
        <button
          type="button" onClick={() => { load(); loadSparklines(); }} disabled={busy}
          className="inline-flex w-full sm:w-auto items-center justify-center gap-1.5 px-3 py-2 sm:py-1.5 rounded-md text-xs font-bold border border-zinc-200 dark:border-zinc-700 text-zinc-700 dark:text-zinc-100 hover:border-fuchsia-400 disabled:opacity-50 bg-white dark:bg-zinc-950"
          data-testid="growth-hub-refresh"
        >
          {busy ? <Loader2 size={12} className="animate-spin"/> : <RefreshCw size={12} />}
          Refresh
        </button>
      </header>

      {/* Iter 220ak — inbound demo-request alerts. Rendered only when
          there's at least one row; mark-read clears the unread badge. */}
      {alerts.rows.length ? (
        <section
          className="rounded-2xl border border-amber-200 dark:border-amber-900 bg-amber-50/60 dark:bg-amber-950/30 px-5 py-4"
          data-testid="growth-hub-alerts"
        >
          <div className="flex items-center gap-3 flex-wrap">
            <span className="shrink-0 w-9 h-9 rounded-xl bg-amber-500 text-white flex items-center justify-center">
              <Inbox size={15}/>
            </span>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-extrabold tracking-tight inline-flex items-center gap-2">
                New inbound demo requests
                {alerts.unread ? (
                  <span
                    className="text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full bg-amber-600 text-white"
                    data-testid="growth-hub-alerts-unread"
                  >
                    {alerts.unread} unread
                  </span>
                ) : null}
              </p>
              <p className="text-[12px] text-zinc-600 dark:text-zinc-300">
                From the public <code>/demo-request</code> landing page · auto-enrolled
                into the cold-to-demo journey.
              </p>
            </div>
            {alerts.unread ? (
              <button
                type="button" onClick={markAlertsRead}
                className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-bold border border-amber-200 text-amber-800 hover:bg-amber-100"
                data-testid="growth-hub-alerts-mark-read"
              >
                <Check size={11}/> Mark all read
              </button>
            ) : null}
          </div>
          <ul className="mt-3 divide-y divide-amber-200/60 dark:divide-amber-900/60" data-testid="growth-hub-alerts-list">
            {alerts.rows.slice(0, 5).map((a) => (
              <li key={a.id} className="py-2 flex items-center gap-3" data-testid={`growth-hub-alert-${a.id}`}>
                <Bell size={12} className={`shrink-0 ${a.read ? 'text-zinc-400' : 'text-amber-600'}`} />
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-bold truncate">{a.title}</p>
                  <p className="text-[11px] text-zinc-500">{a.summary}</p>
                </div>
                <button
                  type="button"
                  onClick={() => jump('crm-deals')}
                  className="text-[11px] font-bold text-fuchsia-700 hover:text-fuchsia-900 inline-flex items-center gap-0.5"
                  data-testid={`growth-hub-alert-${a.id}-open`}
                >
                  Open deal <ArrowRight size={10}/>
                </button>
              </li>
            ))}
          </ul>
        </section>
      ) : null}

      {/* Top KPI band */}
      <div className="grid grid-cols-2 lg:grid-cols-5 gap-3" data-testid="growth-hub-kpis">
        <KpiTile
          label="Active trials" value={data.trials.active}
          hint={`${data.trials.converted_30d} converted in 30d`}
          icon={Users}
          series={spark?.trials_started}
          accentStroke="#0091ca"
        />
        <KpiTile
          label="Blog views" value={data.seo.blog_views_total.toLocaleString()}
          hint={`${data.seo.articles_published} articles published`}
          icon={BookOpen}
          series={spark?.blog_views}
          accentStroke="#19cdff"
        />
        <KpiTile
          label="Emails sent (30d)" value={data.outbound.sent_30d.toLocaleString()}
          hint={`${data.outbound.failed_30d} failed`}
          icon={Mail}
          series={spark?.emails_sent}
          accentStroke="var(--color-rose)"
        />
        <KpiTile
          label="Pipeline £" value={`£${Number(data.pipeline.pipeline_value_gbp || 0).toLocaleString()}`}
          hint={`${data.pipeline.deals_open} open · ${(spark?.deals_created || []).reduce((s,p)=>s+(p.value||0),0)} new in 30d`}
          icon={TrendingUp}
          accent="text-emerald-700"
          series={spark?.deals_created}
          accentStroke="#059669"
        />
        <KpiTile
          label="Site chats (30d)" value={data.sales_insights.chat_sessions_30d.toLocaleString()}
          hint={`${data.sales_insights.chat_messages_30d} messages`}
          icon={MessageSquare}
          series={spark?.chat_sessions}
          accentStroke="#0091ca"
        />
      </div>

      {/* Funnel cards — one per existing module group */}
      <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-3" data-testid="growth-hub-funnel">
        <FunnelCard
          icon={Users}
          accent="bg-gradient-to-br from-blue-500 to-blue-700"
          title="Trial pipeline"
          lede="Active trials + 30-day conversion"
          stats={[
            { label: 'Active', value: data.trials.active },
            { label: 'Converted (30d)', value: data.trials.converted_30d },
          ]}
          ctaLabel="Open Trials"
          deepLink={data.trials.deep_link}
          onJump={jump}
          testId="growth-card-trials"
        />
        <FunnelCard
          icon={Sparkles}
          accent="bg-gradient-to-br from-amber-400 to-fuchsia-600"
          title="SEO Autopilot"
          lede="Daily articles + blog traffic"
          stats={[
            { label: 'Published', value: data.seo.articles_published },
            { label: 'Drafts', value: data.seo.articles_draft },
            { label: 'Keywords queued', value: data.seo.keywords_queued },
            { label: 'Blog views', value: data.seo.blog_views_total.toLocaleString() },
          ]}
          ctaLabel="Open SEO Autopilot"
          deepLink={data.seo.deep_link}
          onJump={jump}
          testId="growth-card-seo"
        />
        <FunnelCard
          icon={Mail}
          accent="bg-gradient-to-br from-rose-500 to-fuchsia-600"
          title="Outbound emails"
          lede="All platform-sent emails (30d)"
          stats={[
            { label: 'Sent', value: data.outbound.sent_30d.toLocaleString() },
            { label: 'Failed', value: data.outbound.failed_30d.toLocaleString() },
          ]}
          ctaLabel="Open Outbound emails"
          deepLink={data.outbound.deep_link}
          onJump={jump}
          testId="growth-card-outbound"
        />
        <FunnelCard
          icon={TrendingUp}
          accent="bg-gradient-to-br from-emerald-500 to-emerald-700"
          title="CRM Pipeline"
          lede="Open deals + win/loss (30d)"
          stats={[
            { label: 'Open', value: data.pipeline.deals_open },
            { label: 'Value', value: `£${Number(data.pipeline.pipeline_value_gbp || 0).toLocaleString()}` },
            { label: 'Won (30d)', value: data.pipeline.deals_won_30d },
            { label: 'Lost (30d)', value: data.pipeline.deals_lost_30d },
          ]}
          ctaLabel="Open CRM"
          deepLink="crm-deals"
          onJump={jump}
          testId="growth-card-pipeline"
        />
        <FunnelCard
          icon={MessageSquare}
          accent="bg-gradient-to-br from-violet-500 to-fuchsia-600"
          title="Sales Insights"
          lede="Themes from public-site AI chat"
          stats={[
            { label: 'Sessions (30d)', value: data.sales_insights.chat_sessions_30d },
            { label: 'Messages (30d)', value: data.sales_insights.chat_messages_30d },
          ]}
          ctaLabel="Open Sales Insights"
          deepLink={data.sales_insights.deep_link}
          onJump={jump}
          testId="growth-card-sales-insights"
        />
        <FunnelCard
          icon={Building2}
          accent="bg-gradient-to-br from-zinc-700 to-zinc-900"
          title="Companies in CRM"
          lede="Total prospect + customer companies"
          stats={[
            { label: 'Companies', value: data.pipeline.companies_total },
          ]}
          ctaLabel="Open Companies"
          deepLink="crm-companies"
          onJump={jump}
          testId="growth-card-companies"
        />
      </div>

      {/* B2B Journey templates — server-driven launcher. The "Launch"
          button materialises the template into ``marketing_journeys``
          for the master-admin org via the growth-hub launch endpoint.
          Re-create archives the previous copy and spawns a fresh one.
          The journey runs in Marketing → Journeys — we don't duplicate
          the canvas here. */}
      <section data-testid="growth-hub-journeys">
        <div className="flex items-center gap-2 mb-3">
          <Workflow size={14} className="text-fuchsia-600"/>
          <h3 className="text-sm font-extrabold">B2B journey templates</h3>
          <span className="text-[10px] font-bold uppercase tracking-wider text-zinc-400">
            One-click launch · runs in Marketing → Journeys
          </span>
          <button
            type="button" onClick={loadTemplates}
            className="ml-auto text-[11px] inline-flex items-center gap-1 text-zinc-500 hover:text-zinc-900"
            data-testid="growth-hub-journeys-refresh"
            title="Refresh launch status"
          >
            <RefreshCw size={11}/> Refresh
          </button>
        </div>
        {templatesErr ? (
          <div className="rounded-md border border-rose-200 bg-rose-50 text-rose-700 px-3 py-2 text-sm" data-testid="growth-hub-journeys-error">
            {templatesErr}
          </div>
        ) : !templates ? (
          <div className="text-zinc-500 text-sm inline-flex items-center gap-2" data-testid="growth-hub-journeys-loading">
            <Loader2 size={14} className="animate-spin"/> Loading templates…
          </div>
        ) : (
          <div className="grid md:grid-cols-2 gap-3">
            {templates.map((t) => (
              <JourneyTemplateCard
                key={t.id} t={t} onLaunched={loadTemplates}
              />
            ))}
          </div>
        )}
        <p className="text-[11px] text-zinc-400 mt-3">
          Each &quot;Launch&quot; creates a multi-step email journey in
          <code className="mx-1">marketing_journeys</code>
          scoped to the master-admin org. Edit the steps in
          Marketing &rarr; Journeys, then test-send or enrol contacts there.
        </p>
      </section>
    </div>
  );
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import axios from 'axios';
import {
  ShieldAlert, RefreshCcw, Download, Search, AlertTriangle,
  Ban, ShieldCheck, Activity, Loader2, ShieldOff,
} from 'lucide-react';
import { notify, useConfirm } from '@/components/notifications';

const API = process.env.REACT_APP_BACKEND_URL
  ? `${process.env.REACT_APP_BACKEND_URL}/api`
  : '/api';
const auth = () => ({ headers: { Authorization: `Bearer ${localStorage.getItem('token') || ''}` } });
const BASE = `${API}/master-admin/security-centre`;

const CATEGORY_LABELS = {
  access_denied: 'Access denied',
  workflow: 'Skip-approval / workflow',
  mass_assignment: 'Mass assignment',
  step_up: 'Step-up',
  financial: 'Invoices',
  stock: 'Stock',
  privileged: 'Privileged',
  abuse: 'Abuse / auto-response',
};

const SEVERITY_STYLE = {
  critical: { bg: 'bg-red-500/15', text: 'text-red-400', dot: 'bg-red-500' },
  warning: { bg: 'bg-amber-500/15', text: 'text-amber-400', dot: 'bg-amber-500' },
  info: { bg: 'bg-sky-500/15', text: 'text-sky-400', dot: 'bg-sky-500' },
};

function fmtTime(iso) {
  if (!iso) return '—';
  try { return new Date(iso).toLocaleString('en-GB', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit', second: '2-digit' }); }
  catch { return iso; }
}
function prettyType(t) { return (t || '').replace(/_/g, ' '); }

export default function SecurityAlertCentre() {
  const [summary, setSummary] = useState(null);
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [sinceDays, setSinceDays] = useState(7);
  const [category, setCategory] = useState('');
  const [severity, setSeverity] = useState('');
  const [search, setSearch] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const [live, setLive] = useState(true);
  const [lastRefresh, setLastRefresh] = useState(null);
  const [suspended, setSuspended] = useState([]);
  const [clearingKey, setClearingKey] = useState(null);
  const confirm = useConfirm();

  // Debounce the search box into debouncedSearch (avoids stale-closure refetch).
  useEffect(() => {
    const id = setTimeout(() => setDebouncedSearch(search.trim()), 400);
    return () => clearTimeout(id);
  }, [search]);

  const load = useCallback(async () => {
    try {
      const params = { since_days: sinceDays, limit: 300 };
      if (category) params.category = category;
      if (severity) params.severity = severity;
      if (debouncedSearch) params.search = debouncedSearch;
      const [sRes, eRes, aRes] = await Promise.all([
        axios.get(`${BASE}/summary`, { ...auth(), params: { since_days: sinceDays } }),
        axios.get(`${BASE}/events`, { ...auth(), params }),
        axios.get(`${BASE}/abuse/active`, { ...auth() }).catch(() => ({ data: { actors: [] } })),
      ]);
      setSummary(sRes.data);
      setEvents(eRes.data.events || []);
      setSuspended(aRes.data.actors || []);
      setLastRefresh(new Date());
    } catch (e) {
      console.error('security-centre load failed', e);
    } finally {
      setLoading(false);
    }
  }, [sinceDays, category, severity, debouncedSearch]);

  const clearSuspension = async (row) => {
    const ok = await confirm({
      title: 'Clear suspension?',
      tone: 'warning',
      detail: `This immediately lifts the ${row.level_name.replace('_', ' ')} escalation on “${row.actor}”. They'll be able to perform sensitive actions again. The action is audited.`,
      confirmLabel: 'Clear suspension',
    });
    if (!ok) return;
    setClearingKey(row.key);
    try {
      await axios.post(`${BASE}/abuse/clear`, { key: row.key }, { ...auth() });
      notify.success('Suspension cleared', `${row.actor} can act normally again.`);
      setSuspended((prev) => prev.filter((r) => r.key !== row.key));
      load();
    } catch (e) {
      notify.error('Could not clear suspension', e?.response?.data?.detail || e.message);
    } finally {
      setClearingKey(null);
    }
  };

  useEffect(() => { load(); }, [load]);

  // Live auto-refresh every 15s.
  useEffect(() => {
    if (!live) return undefined;
    const id = setInterval(load, 15000);
    return () => clearInterval(id);
  }, [live, load]);

  const onSearchChange = (v) => setSearch(v);

  const exportCsv = async () => {
    try {
      const params = { since_days: Math.max(sinceDays, 30) };
      if (category) params.category = category;
      if (severity) params.severity = severity;
      if (debouncedSearch) params.search = debouncedSearch;
      const r = await axios.get(`${BASE}/export.csv`, { ...auth(), params, responseType: 'blob' });
      const url = window.URL.createObjectURL(new Blob([r.data]));
      const a = document.createElement('a');
      a.href = url; a.download = `pulse-security-events.csv`;
      document.body.appendChild(a); a.click(); a.remove();
      window.URL.revokeObjectURL(url);
    } catch (e) { console.error('export failed', e); }
  };

  const tiles = useMemo(() => {
    const s = summary || {};
    const sev = s.by_severity || {};
    return [
      { key: 'total', label: 'Events', value: s.total || 0, icon: Activity, tone: 'text-sky-400' },
      { key: 'critical', label: 'Critical', value: sev.critical || 0, icon: AlertTriangle, tone: 'text-red-400' },
      { key: 'warning', label: 'Warnings', value: sev.warning || 0, icon: ShieldAlert, tone: 'text-amber-400' },
      { key: 'denials', label: 'Access denials', value: s.access_denials || 0, icon: Ban, tone: 'text-red-400' },
    ];
  }, [summary]);

  return (
    <div className="space-y-6" data-testid="security-alert-centre">
      {/* Header */}
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <div className="flex h-11 w-11 items-center justify-center rounded-xl bg-red-500/15">
            <ShieldAlert className="h-6 w-6 text-red-400" />
          </div>
          <div>
            <h1 className="text-xl font-semibold text-white">Security Alert Centre</h1>
            <p className="text-sm text-white/50">
              Live Zero-Trust telemetry · access denials, cross-tenant/site attempts, skip-approval blocks, step-up & financial events
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={() => setLive((v) => !v)}
            className={`inline-flex items-center gap-2 rounded-lg px-3 py-2 text-xs font-medium transition-colors ${live ? 'bg-emerald-500/15 text-emerald-400' : 'bg-white/5 text-white/50'}`}
            data-testid="security-live-toggle"
          >
            <span className={`h-2 w-2 rounded-full ${live ? 'bg-emerald-400 animate-pulse' : 'bg-white/30'}`} />
            {live ? 'Live' : 'Paused'}
          </button>
          <button onClick={load} className="inline-flex items-center gap-2 rounded-lg bg-white/5 px-3 py-2 text-xs font-medium text-white/70 hover:bg-white/10" data-testid="security-refresh-btn">
            <RefreshCcw className="h-4 w-4" /> Refresh
          </button>
          <button onClick={exportCsv} className="inline-flex items-center gap-2 rounded-lg bg-white/5 px-3 py-2 text-xs font-medium text-white/70 hover:bg-white/10" data-testid="security-export-btn">
            <Download className="h-4 w-4" /> Export CSV
          </button>
        </div>
      </div>

      {/* KPI tiles */}
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
        {tiles.map((t) => (
          <div key={t.key} className="rounded-xl border border-white/10 bg-white/[0.03] p-4" data-testid={`security-tile-${t.key}`}>
            <div className="flex items-center justify-between">
              <span className="text-xs uppercase tracking-wide text-white/40">{t.label}</span>
              <t.icon className={`h-4 w-4 ${t.tone}`} />
            </div>
            <div className={`mt-2 text-2xl font-semibold ${t.tone}`}>{t.value}</div>
          </div>
        ))}
      </div>

      {/* Suspended actors — one-click clear */}
      {suspended.length > 0 && (
        <div className="rounded-xl border border-amber-500/30 bg-amber-500/[0.06]" data-testid="abuse-suspended-panel">
          <div className="flex items-center gap-2 border-b border-amber-500/20 px-4 py-2.5">
            <ShieldOff className="h-4 w-4 text-amber-400" />
            <h3 className="text-sm font-semibold text-amber-200">
              Suspended / throttled actors
              <span className="ml-2 rounded-full bg-amber-500/20 px-2 py-0.5 text-xs text-amber-300">{suspended.length}</span>
            </h3>
            <span className="ml-auto text-xs text-white/40">Auto-response escalation · clear a wrongly-flagged actor</span>
          </div>
          <div className="divide-y divide-white/5">
            {suspended.map((row) => (
              <div key={row.key} className="flex flex-wrap items-center gap-3 px-4 py-3" data-testid={`abuse-actor-${row.key}`}>
                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-2">
                    <span className="truncate text-sm font-medium text-white/90">{row.actor}</span>
                    <span className="rounded-full bg-red-500/15 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-red-300">
                      {row.level_name.replace('_', ' ')}
                    </span>
                  </div>
                  <div className="mt-0.5 text-xs text-white/40">
                    {row.count} denial{row.count === 1 ? '' : 's'}
                    {row.last_ip ? ` · IP ${row.last_ip}` : ''}
                    {row.until ? ` · until ${fmtTime(row.until)}` : ''}
                  </div>
                </div>
                <button
                  onClick={() => clearSuspension(row)}
                  disabled={clearingKey === row.key}
                  className="inline-flex items-center gap-1.5 rounded-lg bg-emerald-500/15 px-3 py-1.5 text-xs font-semibold text-emerald-300 hover:bg-emerald-500/25 disabled:opacity-50"
                  data-testid={`abuse-clear-btn-${row.key}`}
                >
                  {clearingKey === row.key
                    ? <Loader2 className="h-3.5 w-3.5 animate-spin" />
                    : <ShieldCheck className="h-3.5 w-3.5" />}
                  Clear suspension
                </button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Filters */}
      <div className="flex flex-wrap items-center gap-2">
        <select value={sinceDays} onChange={(e) => setSinceDays(Number(e.target.value))} className="rounded-lg border border-white/10 bg-black/30 px-3 py-2 text-sm text-white/80" data-testid="security-since-select">
          <option value={1}>Last 24h</option>
          <option value={7}>Last 7 days</option>
          <option value={30}>Last 30 days</option>
          <option value={90}>Last 90 days</option>
        </select>
        <select value={severity} onChange={(e) => setSeverity(e.target.value)} className="rounded-lg border border-white/10 bg-black/30 px-3 py-2 text-sm text-white/80" data-testid="security-severity-select">
          <option value="">All severities</option>
          <option value="critical">Critical</option>
          <option value="warning">Warning</option>
          <option value="info">Info</option>
        </select>
        <div className="flex flex-wrap gap-1.5">
          <button onClick={() => setCategory('')} className={`rounded-full px-3 py-1.5 text-xs ${!category ? 'bg-sky-500/20 text-sky-300' : 'bg-white/5 text-white/50 hover:bg-white/10'}`} data-testid="security-cat-all">All</button>
          {Object.entries(CATEGORY_LABELS).map(([k, label]) => (
            <button key={k} onClick={() => setCategory(k)} className={`rounded-full px-3 py-1.5 text-xs ${category === k ? 'bg-sky-500/20 text-sky-300' : 'bg-white/5 text-white/50 hover:bg-white/10'}`} data-testid={`security-cat-${k}`}>
              {label}{summary?.by_category?.[k] ? ` (${summary.by_category[k]})` : ''}
            </button>
          ))}
        </div>
        <div className="relative ml-auto">
          <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-white/30" />
          <input value={search} onChange={(e) => onSearchChange(e.target.value)} placeholder="Search detail, path, IP, resource…" className="w-64 rounded-lg border border-white/10 bg-black/30 py-2 pl-9 pr-3 text-sm text-white/80 outline-none focus:border-sky-500" data-testid="security-search-input" />
        </div>
      </div>

      {/* Events table */}
      <div className="overflow-hidden rounded-xl border border-white/10">
        <div className="flex items-center justify-between border-b border-white/10 bg-white/[0.02] px-4 py-2 text-xs text-white/40">
          <span>{events.length} event{events.length === 1 ? '' : 's'}</span>
          {lastRefresh && <span>Updated {lastRefresh.toLocaleTimeString('en-GB')}</span>}
        </div>
        {loading ? (
          <div className="flex items-center justify-center gap-2 py-16 text-white/40"><Loader2 className="h-5 w-5 animate-spin" /> Loading…</div>
        ) : events.length === 0 ? (
          <div className="flex flex-col items-center gap-2 py-16 text-white/40" data-testid="security-empty">
            <ShieldCheck className="h-8 w-8 text-emerald-400/60" />
            <p className="text-sm">No security events for this filter — all clear.</p>
          </div>
        ) : (
          <div className="max-h-[560px] overflow-auto">
            <table className="w-full text-left text-sm">
              <thead className="sticky top-0 bg-[#0f1218] text-xs uppercase tracking-wide text-white/40">
                <tr>
                  <th className="px-4 py-2 font-medium">Time</th>
                  <th className="px-4 py-2 font-medium">Event</th>
                  <th className="px-4 py-2 font-medium">Actor</th>
                  <th className="px-4 py-2 font-medium">Resource</th>
                  <th className="px-4 py-2 font-medium">Detail</th>
                  <th className="px-4 py-2 font-medium">IP</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-white/5" data-testid="security-events-table">
