  // Real-Time Security Alerts (security §32/§34) — short-poll the alert feed
  // every 10s while the Master Admin console is open and raise a sonner-style
  // toast the instant a critical/abuse event lands, jumping straight to the
  // Security Alert Centre on click. Acknowledged server-side so each alert
  // toasts exactly once across refreshes.
  const alertSinceRef = useRef(new Date().toISOString());
  const [unreadAlerts, setUnreadAlerts] = useState(0);
  const refreshUnreadRef = useRef(null);
  useEffect(() => {
    let cancelled = false;
    const poll = async () => {
      try {
        const r = await axios.get(
          `${API}/master-admin/security-centre/alerts`,
          { headers, params: { since: alertSinceRef.current } },
        );
        if (cancelled) return;
        if (r.data?.server_time) alertSinceRef.current = r.data.server_time;
        if (typeof r.data?.total_unread === 'number') setUnreadAlerts(r.data.total_unread);
        const alerts = r.data?.alerts || [];
        if (alerts.length === 0) return;
        // Toast new alerts once (client-side dedup via the `since` cursor).
        // We intentionally do NOT ack here — alerts stay unread on the bell
        // badge until the admin opens the bell and marks them read.
        [...alerts].reverse().forEach((a) => {
          const isCritical = a.severity === 'critical';
          const push = isCritical ? notify.error : notify.warning;
          push(
            `Security alert · ${a.title}`,
            `${a.actor}${a.detail ? ` — ${a.detail}` : ''}`,
            {
              ttl: isCritical ? 12000 : 8000,
              action: {
                label: 'View in Security Centre',
                onClick: () => setSection('security-centre'),
              },
            },
          );
        });
      } catch { /* transient — retry next tick */ }
    };
    refreshUnreadRef.current = poll;
    const t = setInterval(poll, 10000);
    poll();
    return () => { cancelled = true; clearInterval(t); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [API]);

  // Iter 216h189 — server-side `q` filter on `/master-admin/organizations`.
  // We previously shipped the entire org list (up to 2000) on every load
  // and filtered client-side. With ~1k orgs that's ~3-5 MB on every
  // refresh / keystroke. Now we debounce the search box (300 ms) and
  // re-fetch only the orgs slice with a `?q=…` query param when the
  // operator pauses typing. The first mount loader (`loadData`) still
  // primes the list with everything when search is empty, so navigating
  // between sub-tabs with no search active is unchanged.
  useEffect(() => {
    const term = (search || '').trim();
    // When the operator clears the search, re-prime the full list so
    // they don't get stuck looking at the last search-narrowed slice.
    if (term.length === 0) {
      // Only re-prime if the list is small (signals a previous narrow
      // search). Saves a redundant round-trip on the initial mount,
      // where `loadData` has already populated the list.
      if (organizations.length > 0 && organizations.length < 50) {
        const t = setTimeout(() => { loadData(); }, 50);
        return () => clearTimeout(t);
      }
      return undefined;
    }
    if (term.length < 2) return undefined; // 1-char queries hit the backend's own guard, skip
    const t = setTimeout(async () => {
      try {
        const params = new URLSearchParams();
        if (_brandCtx && _brandCtx !== 'all') params.set('brand', _brandCtx);
        params.set('q', term);
        const r = await axios.get(
          `${API}/master-admin/organizations?${params.toString()}`,
          { headers },
        );
        setOrganizations(r.data.organizations || []);
      } catch { /* keep previous list on transient failure */ }
    }, 300);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- intentional: reviewed in iter 216h226-deps-walk — effect either runs once on mount or re-fires on the listed trigger deps; omitted refs are stable identities or fetcher closures that read live state at call time, so including them would re-fire without changing semantics.
  }, [search, _brandQS]);

  const actions = useMasterAdminActions({ API, headers, loadData, loadSectionData });

  const saveCapexThresholds = async () => {
    try {
      await axios.put(`${API}/capex/thresholds`, capexThresholds, { headers });
      notify.success('CAPEX thresholds updated');
