      case 'documents':
        return <DocumentsPanel />;
      case 'collections':
        return <CollectionsDashboard onPickOrg={(orgId) => { setSection('org-billing'); setBillingOrgId(orgId); }} />;
      case 'db-viewer':
        return <DbViewerPanel />;
      case 'pulse-data':
        return <PulseDbExplorerPanel />;
      case 'catalogue':
        return <CataloguePanel />;
      case 'equipment-gaps':
        return <EquipmentGapsSection />;
      case 'machine-manuals':
        return <MachineManualsDirectoryPanel />;
      case 'service-desk-customers':
        return <ServiceDeskCustomersPanel />;
      case 'social-media-library':
        return <SocialMediaLibraryPanel />;
      case 'custom-properties':
        return <CustomPropertiesPanel />;
