          onClick={() => setSidebarOpen(false)}
          data-testid="sidebar-backdrop"
        />
      )}

      <AdminSidebar
        section={section}
        setSection={setSection}
        setSearch={setSearch}
        sidebarOpen={sidebarOpen}
        setSidebarOpen={setSidebarOpen}
        onLogout={handleLogout}
        onPulseSwitch={handlePulseSwitch}
        onPulseFitnessSwitch={handlePulseFitnessSwitch}
        onOrgSwitch={handleOrgSwitch}
        organizations={organizations}
        isPulseAdmin={isPulseAdmin}
      />

      <main className="flex-1 overflow-y-auto min-w-0">
        <div className="p-4 sm:p-6 lg:p-8 max-w-[1440px]">
          <div className="flex items-center gap-2 sm:gap-3 mb-4 lg:mb-6 flex-wrap">
            <button
              onClick={() => setSidebarOpen(true)}
              className="lg:hidden p-2 -ml-2 text-zinc-600 hover:text-zinc-900 hover:bg-zinc-100 rounded-lg"
              data-testid="sidebar-toggle-btn"
              aria-label="Open navigation"
            >
              <Menu size={22} />
            </button>
            <div className="flex-1 min-w-0">
              <h1 className="text-xl sm:text-2xl font-bold tracking-tight text-zinc-900 truncate">
                {sectionTitles[section]}
              </h1>
              <p className="text-xs sm:text-sm text-slate-500 mt-0.5 truncate">
                {(() => {
                  if (isPulseAdmin && section === 'overview') return 'Platform-wide metrics across your modules · revenue · cases';
                  if (isPulseAdmin && section === 'theme-settings') return 'Your Pulse Fitness design tokens and per-tenant brand overrides.';
                  return sectionDescriptions[section] || '';
                })()}
              </p>
            </div>
            <CommandPalette
              orgs={organizations}
              isPulseAdmin={isPulseAdmin}
              onJumpSection={(id) => setSection(id)}
              onOpenOrg={(o) => {
                // Jump to overview, then surface the org by setting the
                // shared selectedOrg state — AdminOrganizations consumes
                // it via the orgsProps bundle.
                setSection('overview');
                setSelectedOrg(o);
              }}
            />
            {/* Iter 222 — Pulse Fitness platform email-deliverability health is
                internal platform infra; hidden for delegated Pulse admins. */}
            {!isPulseAdmin && <EmailHealthPill />}
            <AlertBell
              API={API}
              headers={headers}
              count={unreadAlerts}
              onViewCentre={() => setSection('security-centre')}
              onChanged={() => { setUnreadAlerts(0); refreshUnreadRef.current?.(); }}
            />
            {/* Iter 285 — Brand switcher removed: there is now a single Pulse
                Fitness brand, so the picker only added confusing duplicate
                "Pulse Fitness" entries. Brand context stays 'all' (everything). */}
            <Button
              size="sm"
              variant="outline"
              disabled={refreshing}
              className="border-zinc-200 text-zinc-600 hover:bg-zinc-100 flex-shrink-0"
              onClick={async () => {
                setRefreshing(true);
                try {
                  await Promise.all([loadData(), loadSectionData(section)]);
                  setRefreshTick(t => t + 1);  // signals child sections to re-fetch
                  notify.success('Refreshed');
                } catch (e) {
                  notify.error('Refresh failed');
                } finally {
                  setRefreshing(false);
                }
              }}
              data-testid="refresh-data-btn"
            >
              <RefreshCw size={14} className={`mr-1 hidden sm:inline ${refreshing ? 'animate-spin' : ''}`} />
              <span className="hidden sm:inline">{refreshing ? 'Refreshing…' : 'Refresh'}</span>
              <RefreshCw size={14} className={`sm:hidden ${refreshing ? 'animate-spin' : ''}`} />
            </Button>
          </div>

          {loading && !stats ? (
            <div className="flex items-center justify-center h-64">
