                return (
                  <span key={s} className="px-1.5 py-0.5 rounded text-[10px] font-bold uppercase" style={{ background: `${tone}26`, color: tone }} data-testid={`events-costume-summary-${s}`}>
                    {n} {t(`memberships_console.evt_costume_${s}`, s)}
                  </span>
                );
              })}
