          ) : null}
        </div>
      </div>

      {/* AI comms drawer */}
      {aiOpen ? (
        <div className="border-t p-4 space-y-2" style={{ borderColor: 'var(--theme-border, #e0e0e0)', background: 'rgba(25, 205, 255,0.04)' }} data-testid="events-ai-comms">
