              </div>

              <div className="rounded-lg border border-[color:var(--theme-border)] p-4 space-y-3">
                <p className="text-[11px] font-bold uppercase tracking-[0.16em] text-[color:var(--theme-text-muted)] flex items-center gap-1.5">
