/**
 * Public instructor profile page.
 *
 * Route: /m/:slug/i/:instructorSlug
 * Backend: GET /api/public/studios/:slug/instructors/:instructorSlug
 *
 * Goal: a shareable marketing page that sells the instructor and their
 * upcoming classes. Works without auth — perfect for pasting on
 * Instagram / linking in email. The design leans into a warm editorial
 * vibe rather than the operator-console dashboard aesthetic: hero
 * photo, generous typography, specialty chips, upcoming class list with
 * direct booking links.
 */
import { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import axios from 'axios';
import { Instagram, Link2, Globe, ArrowRight, Calendar, MapPin, Share2, Copy } from 'lucide-react';

const API = `${process.env.REACT_APP_BACKEND_URL}/api`;

function SocialChip({ href, label, Icon, colour }) {
  if (!href) return null;
  const url = href.startsWith('http') ? href : `https://instagram.com/${href.replace(/^@/, '')}`;
  return (
    <a href={url} target="_blank" rel="noreferrer"
       className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-bold"
       style={{ background: 'rgba(255,255,255,0.06)', color: colour }}
       data-testid={`instructor-social-${label.toLowerCase()}`}>
      <Icon size={12} /> {label}
    </a>
  );
}

function formatDate(iso) {
  if (!iso) return '';
  try { return new Date(iso).toLocaleString('en-GB', { weekday: 'short', day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }); }
  catch { return iso; }
}

export default function PublicInstructorPage() {
  const { slug, instructorSlug } = useParams();
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState(null);
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    (async () => {
      try {
        const r = await axios.get(`${API}/public/studios/${slug}/instructors/${instructorSlug}`);
        setData(r.data);
      } catch (e) {
        setErr(e.response?.data?.detail || 'Could not load profile');
      } finally { setLoading(false); }
    })();
  }, [slug, instructorSlug]);

  const share = async () => {
    const url = window.location.href;
    if (navigator.share) {
      try { await navigator.share({ url, title: data?.instructor?.name }); return; } catch { /* ignore */ }
    }
    try { await navigator.clipboard.writeText(url); setCopied(true); setTimeout(() => setCopied(false), 2000); } catch { /* ignore */ }
  };

  if (loading) return <div style={{ background: '#1B1C1D', color: '#fff', minHeight: '100vh', display: 'grid', placeItems: 'center' }}>Loading…</div>;
  if (err) return (
    <div style={{ background: '#1B1C1D', color: '#fff', minHeight: '100vh', display: 'grid', placeItems: 'center', padding: 24 }}>
      <div style={{ maxWidth: 420, textAlign: 'center' }}>
        <h1 style={{ fontSize: 28, margin: 0 }}>Profile not found</h1>
        <p style={{ opacity: 0.7, marginTop: 12 }}>{err}</p>
        <Link to={`/m/${slug}`} style={{ color: '#00B2C7' }}>← Back to studio</Link>
      </div>
    </div>
  );

  const { studio, instructor, upcoming } = data;
  const primary = studio.primary_color || '#00B2C7';

  const initials = (instructor.name || '?').split(' ').map((w) => w[0]).slice(0, 2).join('').toUpperCase();

  return (
    <div style={{ background: '#1B1C1D', color: '#fff', minHeight: '100vh' }} data-testid="public-instructor-page">
      {/* Top bar */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                    padding: '18px 24px', maxWidth: 1080, margin: '0 auto' }}>
        <Link to={`/m/${slug}`} style={{ color: 'rgba(255,255,255,0.75)', textDecoration: 'none', fontSize: 12, letterSpacing: '0.22em', textTransform: 'uppercase' }}
          data-testid="instructor-back">{studio.name}</Link>
        <button onClick={share}
          style={{ background: 'rgba(255,255,255,0.06)', color: '#fff', border: 'none',
                   padding: '8px 14px', borderRadius: 999, fontSize: 12, fontWeight: 700,
                   display: 'inline-flex', alignItems: 'center', gap: 6, cursor: 'pointer' }}
          data-testid="instructor-share">
          {copied ? <Copy size={12} /> : <Share2 size={12} />}
          {copied ? 'Copied' : 'Share'}
        </button>
      </div>

      {/* Hero */}
      <div style={{ position: 'relative', maxWidth: 1080, margin: '0 auto', padding: '24px 24px 48px' }}>
        {instructor.hero_photo_url && (
          <div style={{
            position: 'absolute', inset: 0,
            background: `url(${instructor.hero_photo_url}) center/cover`,
            opacity: 0.22, borderRadius: 18, filter: 'blur(2px)',
          }} />
        )}
        <div style={{ position: 'relative', display: 'grid', gridTemplateColumns: 'auto 1fr', gap: 32, alignItems: 'center' }}>
          {instructor.photo_url ? (
            <img src={instructor.photo_url} alt={instructor.name}
              style={{ width: 200, height: 200, borderRadius: '50%', objectFit: 'cover', border: `3px solid ${primary}` }}
              data-testid="instructor-photo" />
          ) : (
            <div style={{ width: 200, height: 200, borderRadius: '50%', background: primary,
                          display: 'grid', placeItems: 'center', fontSize: 72, fontWeight: 900, color: '#1B1C1D' }}
              data-testid="instructor-photo-initials">
              {initials}
            </div>
          )}
          <div>
            <p style={{ margin: 0, fontSize: 11, letterSpacing: '0.22em', textTransform: 'uppercase',
                        opacity: 0.55 }}>Instructor</p>
            <h1 style={{ fontSize: 56, lineHeight: 1.05, margin: '8px 0 6px', fontWeight: 900, letterSpacing: '-0.02em' }}
              data-testid="instructor-name">{instructor.name}</h1>
            {instructor.headline && (
              <p style={{ margin: 0, fontSize: 20, color: primary, fontWeight: 700 }}
                data-testid="instructor-headline">{instructor.headline}</p>
            )}
            <div style={{ marginTop: 18, display: 'flex', flexWrap: 'wrap', gap: 8 }}>
              {(instructor.specialties || []).map((s) => (
                <span key={s} data-testid={`instructor-specialty-${s.toLowerCase().replace(/\s+/g, '-')}`}
                  style={{ background: 'rgba(255,255,255,0.06)', color: '#fff',
                           padding: '5px 12px', borderRadius: 999, fontSize: 12, fontWeight: 700 }}>{s}</span>
              ))}
              {typeof instructor.years_experience === 'number' && instructor.years_experience > 0 && (
                <span style={{ background: primary, color: '#1B1C1D',
                               padding: '5px 12px', borderRadius: 999, fontSize: 12, fontWeight: 800 }}
                  data-testid="instructor-experience">{instructor.years_experience}y teaching</span>
              )}
            </div>
            <div style={{ marginTop: 16, display: 'flex', flexWrap: 'wrap', gap: 8 }}>
              <SocialChip href={instructor.social?.instagram} label="Instagram" Icon={Instagram} colour={primary} />
              <SocialChip href={instructor.social?.tiktok}    label="TikTok"    Icon={Link2} colour={primary} />
              <SocialChip href={instructor.social?.linkedin}  label="LinkedIn"  Icon={Link2} colour={primary} />
              <SocialChip href={instructor.social?.website}   label="Website"   Icon={Globe} colour={primary} />
            </div>
          </div>
        </div>
      </div>

      {/* Bio */}
      {instructor.bio && (
        <section style={{ maxWidth: 780, margin: '0 auto', padding: '0 24px 48px' }} data-testid="instructor-bio">
          <h2 style={{ fontSize: 14, letterSpacing: '0.22em', textTransform: 'uppercase', opacity: 0.55, margin: 0 }}>About</h2>
          <p style={{ fontSize: 18, lineHeight: 1.7, whiteSpace: 'pre-wrap', marginTop: 12 }}>{instructor.bio}</p>
        </section>
      )}

      {/* Qualifications */}
      {(instructor.qualifications || []).length > 0 && (
        <section style={{ maxWidth: 780, margin: '0 auto', padding: '0 24px 48px' }} data-testid="instructor-qualifications">
          <h2 style={{ fontSize: 14, letterSpacing: '0.22em', textTransform: 'uppercase', opacity: 0.55, margin: 0 }}>Qualifications</h2>
          <ul style={{ marginTop: 12, padding: 0, listStyle: 'none' }}>
            {instructor.qualifications.map((q) => (
              <li key={q} style={{ display: 'flex', gap: 10, alignItems: 'center', padding: '10px 0',
                                   borderBottom: '1px solid rgba(255,255,255,0.08)', fontSize: 15 }}>
                <span style={{ width: 8, height: 8, borderRadius: 999, background: primary, flex: 'none' }} />
                {q}
              </li>
            ))}
          </ul>
        </section>
      )}

      {/* Upcoming classes */}
      <section style={{ maxWidth: 1080, margin: '0 auto', padding: '0 24px 64px' }}>
        <h2 style={{ fontSize: 14, letterSpacing: '0.22em', textTransform: 'uppercase', opacity: 0.55, margin: 0 }}>
          Upcoming classes
        </h2>
        {(upcoming || []).length === 0 ? (
          <p style={{ marginTop: 16, opacity: 0.55, fontSize: 14 }}>
            No classes scheduled yet. Follow the studio for updates.
          </p>
        ) : (
          <div style={{ marginTop: 16, display: 'grid', gap: 10 }} data-testid="instructor-upcoming">
            {upcoming.map((occ) => {
              const spotsLeft = Math.max((occ.capacity || 0) - (occ.bookings_count || 0), 0);
              const full = occ.capacity && spotsLeft === 0;
              return (
                <Link to={`/m/${slug}/c/${occ.id}`} key={occ.id}
                  style={{ display: 'grid', gridTemplateColumns: '1fr auto', gap: 14, alignItems: 'center',
                           padding: '18px 20px', background: 'rgba(255,255,255,0.04)',
                           borderLeft: `3px solid ${primary}`, borderRadius: 12,
                           textDecoration: 'none', color: '#fff' }}
                  data-testid={`instructor-class-${occ.id}`}>
                  <div>
                    <div style={{ fontSize: 17, fontWeight: 800, marginBottom: 4 }}>{occ.name || 'Class'}</div>
                    <div style={{ fontSize: 13, opacity: 0.65, display: 'flex', gap: 12, flexWrap: 'wrap' }}>
                      <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }}>
                        <Calendar size={11} /> {formatDate(occ.starts_at)}
                      </span>
                      {occ.room_name && (
                        <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }}>
                          <MapPin size={11} /> {occ.room_name}
                        </span>
                      )}
                      <span style={{ color: full ? '#f87171' : primary, fontWeight: 700 }}>
                        {full ? 'Waitlist' : `${spotsLeft} spots left`}
                      </span>
                    </div>
                  </div>
                  <ArrowRight size={18} style={{ opacity: 0.5 }} />
                </Link>
              );
            })}
          </div>
        )}
      </section>
    </div>
  );
}

/**
 * RevenueAutopilotPanel — Phase 1 of Pulse Fitness Autopilot.
 *
 * A supervised agent that recovers at-risk membership revenue: it detects
 * failed charges + churn signals, then (per the org's autonomy level) auto-
 * sends reversible recovery emails and queues money actions (card retries)
 * for human approval. Backed by /api/autopilot/revenue/*.
 */
import { useCallback, useEffect, useState } from 'react';
import { api } from '@/lib/api';
import { notify } from '@/components/notifications';
import {
  Bot, Loader2, RefreshCw, PlayCircle, ShieldCheck, AlertTriangle,
  CheckCircle2, Clock, Lightbulb, XCircle, Sparkles, Settings2,
} from 'lucide-react';

function gbp(n, ccy = 'gbp') {
  const sym = { gbp: '£', usd: '$', eur: '€' }[String(ccy).toLowerCase()] || '£';
  return `${sym}${Number(n || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

const LEVELS = [
  { id: 'off', label: 'Off', desc: 'Autopilot does nothing.' },
  { id: 'suggest', label: 'Suggest', desc: 'Proposes actions — you run them.' },
  { id: 'act', label: 'Act & notify', desc: 'Auto-sends emails; asks before money. (Recommended)' },
  { id: 'auto', label: 'Autonomous', desc: 'Runs everything within your policy.' },
];

const STATUS_META = {
  executed: { icon: CheckCircle2, cls: 'text-emerald-600', label: 'Done' },
  pending_approval: { icon: Clock, cls: 'text-amber-600', label: 'Needs approval' },
  suggested: { icon: Lightbulb, cls: 'text-sky-600', label: 'Suggested' },
  approved: { icon: CheckCircle2, cls: 'text-emerald-600', label: 'Approved' },
  rejected: { icon: XCircle, cls: 'text-zinc-400', label: 'Rejected' },
  failed: { icon: AlertTriangle, cls: 'text-rose-600', label: 'Failed' },
};

function Stat({ label, value, sub, testId }) {
  return (
    <div className="theme-card rounded-2xl p-4" data-testid={testId}>
      <div className="text-2xl font-bold" style={{ color: 'var(--theme-text)' }}>{value}</div>
      <div className="text-sm" style={{ color: 'var(--theme-text-muted)' }}>{label}</div>
      {sub != null && <div className="text-xs mt-1" style={{ color: 'var(--theme-text-muted)' }}>{sub}</div>}
    </div>
  );
}

export default function RevenueAutopilotPanel() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const { data: d } = await api.get('/autopilot/revenue/overview');
      setData(d);
    } catch (e) { notify.error('Failed to load Autopilot.'); }
    setLoading(false);
  }, []);

  useEffect(() => { load(); }, [load]);

  const saveSettings = async (patch) => {
    setBusy('settings');
    try {
      const { data: s } = await api.put('/autopilot/revenue/settings', patch);
      setData((prev) => ({ ...prev, settings: s }));
      notify.success('Autopilot settings updated.');
    } catch (e) { notify.error('Could not update settings.'); }
    setBusy('');
  };

  const runNow = async (dryRun) => {
    setBusy(dryRun ? 'preview' : 'run');
    try {
      const { data: r } = await api.post('/autopilot/revenue/run', { dry_run: dryRun });
      const c = r.counts || {};
      if (r.skipped) notify.info('Autopilot is currently off — turn it on or use Preview.');
      else if (dryRun) notify.success(`Preview: ${r.planned} action(s) Autopilot would take.`);
      else notify.success(`Ran: ${c.executed || 0} sent · ${c.pending_approval || 0} need approval.`);
      await load();
    } catch (e) { notify.error('Autopilot run failed.'); }
    setBusy('');
  };

  const decide = async (id, approve) => {
    setBusy(id);
    try {
      await api.post(`/autopilot/revenue/actions/${id}/${approve ? 'approve' : 'reject'}`);
      notify.success(approve ? 'Action approved.' : 'Action rejected.');
      await load();
    } catch (e) { notify.error(e?.response?.data?.detail || 'Action failed.'); }
    setBusy('');
  };

  if (loading) {
    return <div className="flex items-center justify-center py-20"><Loader2 className="w-6 h-6 animate-spin" /></div>;
  }
  if (!data) return null;

  const s = data.settings || {};
  const ar = data.at_risk || {};
  const pending = (data.recent_actions || []).filter((a) => a.status === 'pending_approval');

  return (
    <div className="space-y-6" data-testid="revenue-autopilot-panel">
      {/* Hero */}
      <div className="theme-card rounded-2xl p-5 flex flex-col sm:flex-row sm:items-center gap-4">
        <div className="flex items-center gap-3 flex-1">
          <div className="w-11 h-11 rounded-xl flex items-center justify-center"
            style={{ background: 'rgba(0,145,202,0.1)' }}>
            <Bot className="w-6 h-6" style={{ color: '#0091ca' }} />
          </div>
          <div>
            <h2 className="text-lg font-bold" style={{ color: 'var(--theme-text)' }}>Revenue Recovery Autopilot</h2>
            <p className="text-sm" style={{ color: 'var(--theme-text-muted)' }}>
              Detects at-risk revenue and recovers it for you — automatically chasing failed
              payments and winning back lapsing members.
            </p>
          </div>
        </div>
        <label className="flex items-center gap-2 cursor-pointer" data-testid="autopilot-enable-toggle">
          <span className="text-sm font-semibold" style={{ color: 'var(--theme-text)' }}>
            {s.revenue_enabled ? 'On' : 'Off'}
          </span>
          <input type="checkbox" className="sr-only peer" checked={!!s.revenue_enabled}
            onChange={(e) => saveSettings({ revenue_enabled: e.target.checked })}
            disabled={busy === 'settings'} />
          <span className="w-11 h-6 rounded-full transition-colors relative peer-checked:bg-blue-600"
            style={{ background: s.revenue_enabled ? '#0091ca' : '#c9cbcc' }}>
            <span className={`absolute top-0.5 left-0.5 w-5 h-5 bg-white rounded-full transition-transform ${s.revenue_enabled ? 'translate-x-5' : ''}`} />
          </span>
        </label>
      </div>

      {/* At-risk stats */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        <Stat testId="ap-stat-revenue" label="Revenue at risk" value={gbp(ar.dunning_revenue)} sub="from failed charges" />
        <Stat testId="ap-stat-payment" label="Failed payments" value={ar.dunning_count || 0} sub="past-due members" />
        <Stat testId="ap-stat-churn" label="Churn signals" value={ar.churn_count || 0} sub="lapsing members" />
        <Stat testId="ap-stat-pending" label="Awaiting approval" value={data.pending_approvals || 0} sub="money actions" />
      </div>

      {/* Controls */}
      <div className="flex flex-wrap gap-2">
        <button onClick={() => runNow(true)} disabled={!!busy} data-testid="autopilot-preview-btn"
          className="inline-flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-semibold border"
          style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }}>
          {busy === 'preview' ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
          Preview actions
        </button>
        <button onClick={() => runNow(false)} disabled={!!busy} data-testid="autopilot-run-btn"
          className="inline-flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-semibold text-white"
          style={{ background: '#0091ca' }}>
          {busy === 'run' ? <Loader2 className="w-4 h-4 animate-spin" /> : <PlayCircle className="w-4 h-4" />}
          Run recovery now
        </button>
        <button onClick={load} disabled={!!busy}
          className="inline-flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-semibold border"
          style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }}>
          <RefreshCw className="w-4 h-4" /> Refresh
        </button>
      </div>

      {/* Autonomy + policy */}
      <div className="theme-card rounded-2xl p-5">
        <div className="flex items-center gap-2 mb-3">
          <Settings2 className="w-4 h-4" style={{ color: 'var(--theme-text-muted)' }} />
          <h3 className="font-semibold" style={{ color: 'var(--theme-text)' }}>How much can Autopilot do?</h3>
        </div>
        <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-2">
          {LEVELS.map((l) => {
            const active = s.autonomy_level === l.id;
            return (
              <button key={l.id} onClick={() => saveSettings({ autonomy_level: l.id })}
                disabled={busy === 'settings'} data-testid={`autopilot-level-${l.id}`}
                className="text-left rounded-xl p-3 border transition-colors"
                style={{
                  borderColor: active ? '#0091ca' : 'var(--theme-border)',
                  background: active ? 'rgba(25, 205, 255,0.06)' : 'transparent',
                }}>
                <div className="text-sm font-bold" style={{ color: active ? '#0091ca' : 'var(--theme-text)' }}>{l.label}</div>
                <div className="text-xs mt-1" style={{ color: 'var(--theme-text-muted)' }}>{l.desc}</div>
              </button>
            );
          })}
        </div>
        <label className="flex items-start gap-3 mt-4 cursor-pointer" data-testid="autopilot-money-toggle">
          <input type="checkbox" className="mt-1" checked={!!s.allow_money_actions}
            onChange={(e) => saveSettings({ allow_money_actions: e.target.checked })}
            disabled={busy === 'settings'} />
          <span>
            <span className="text-sm font-semibold flex items-center gap-1" style={{ color: 'var(--theme-text)' }}>
              <ShieldCheck className="w-4 h-4" /> Let Autopilot retry card charges automatically
            </span>
            <span className="text-xs block" style={{ color: 'var(--theme-text-muted)' }}>
              Only applies at the "Autonomous" level. When off, every card retry waits for your approval. Money never moves without this.
            </span>
          </span>
        </label>
      </div>

      {/* Pending approvals */}
      {pending.length > 0 && (
        <div className="theme-card rounded-2xl p-5" data-testid="autopilot-approvals">
          <h3 className="font-semibold mb-3 flex items-center gap-2" style={{ color: 'var(--theme-text)' }}>
            <Clock className="w-4 h-4 text-amber-600" /> Waiting for your approval
          </h3>
          <div className="space-y-2">
            {pending.map((a) => (
              <div key={a.id} className="flex flex-col sm:flex-row sm:items-center gap-2 rounded-xl border p-3"
                style={{ borderColor: 'var(--theme-border)' }} data-testid={`approval-row-${a.id}`}>
                <div className="flex-1">
                  <div className="text-sm font-semibold" style={{ color: 'var(--theme-text)' }}>
                    {a.member_name || 'Member'} · {gbp(a.amount, a.currency)}
                  </div>
                  <div className="text-xs" style={{ color: 'var(--theme-text-muted)' }}>{a.rationale || a.evidence}</div>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => decide(a.id, true)} disabled={busy === a.id}
                    data-testid={`approve-${a.id}`}
                    className="inline-flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-semibold text-white"
                    style={{ background: '#059669' }}>
                    {busy === a.id ? <Loader2 className="w-3 h-3 animate-spin" /> : <CheckCircle2 className="w-3 h-3" />} Approve
                  </button>
                  <button onClick={() => decide(a.id, false)} disabled={busy === a.id}
                    data-testid={`reject-${a.id}`}
                    className="inline-flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-semibold border"
                    style={{ borderColor: 'var(--theme-border)', color: 'var(--theme-text)' }}>
                    <XCircle className="w-3 h-3" /> Reject
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Recent activity */}
      <div className="theme-card rounded-2xl p-5" data-testid="autopilot-activity">
        <h3 className="font-semibold mb-3" style={{ color: 'var(--theme-text)' }}>What Autopilot has done</h3>
        {(data.recent_actions || []).length === 0 ? (
          <p className="text-sm" style={{ color: 'var(--theme-text-muted)' }}>
            No actions yet. Turn Autopilot on, or click <strong>Run recovery now</strong> to let it work through your at-risk members.
          </p>
        ) : (
          <div className="space-y-1.5">
            {data.recent_actions.map((a) => {
              const meta = STATUS_META[a.status] || STATUS_META.suggested;
              const Icon = meta.icon;
              return (
                <div key={a.id} className="flex items-start gap-3 py-2 border-b last:border-0"
                  style={{ borderColor: 'var(--theme-border)' }}>
                  <Icon className={`w-4 h-4 mt-0.5 shrink-0 ${meta.cls}`} />
                  <div className="flex-1 min-w-0">
                    <div className="text-sm" style={{ color: 'var(--theme-text)' }}>
                      <span className="font-semibold">{a.member_name || 'Member'}</span>
                      {' · '}{(a.kind || '').replace(/_/g, ' ')}
                    </div>
                    <div className="text-xs truncate" style={{ color: 'var(--theme-text-muted)' }}>{a.rationale || a.evidence}</div>
                  </div>
                  <span className={`text-xs font-semibold shrink-0 ${meta.cls}`}>{meta.label}</span>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * StudioBrainTab — Phase E (Iter 216ad)
 *
 * AI-powered boardroom view:
 *   • Headline card — the one thing the operator should act on
 *   • Growth / revenue / bookings KPIs
 *   • Retention-risk leaderboard (per-student)
 *   • Occupancy heat-map (7 days × 6 time-buckets)
 *   • AI timetable suggestions
 */
import React, { useCallback, useEffect, useMemo, useState } from 'react';
import axios from 'axios';
import {
  Loader2, Sparkles, TrendingUp, TrendingDown, AlertTriangle,
  Users, CalendarRange, Wand2, RefreshCw, Brain, Zap,
} from 'lucide-react';
import { notify } from '@/components/notifications';

const RISK_TONES = {
  high:   { bg: 'rgba(239,68,68,0.14)',  fg: '#b91c1c', label: 'High' },
  medium: { bg: 'rgba(245,158,11,0.14)', fg: '#b45309', label: 'Medium' },
  low:    { bg: 'rgba(16,185,129,0.14)', fg: '#047857', label: 'Low' },
};
const fmtGBP = (p) => `£${(((p ?? 0) / 100) || 0).toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 0 })}`;

export default function StudioBrainTab({ API, headers }) {
  const auth = useMemo(() => ({ headers }), [headers]);
  const [data, setData] = useState(null);
  const [heatmap, setHeatmap] = useState(null);
  const [suggestions, setSuggestions] = useState(null);
  const [retention, setRetention] = useState(null);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const [board, hm, sg, rk] = await Promise.all([
        axios.get(`${API}/memberships/studio/boardroom`, auth),
        axios.get(`${API}/memberships/studio/occupancy-heatmap?weeks=4`, auth),
        axios.get(`${API}/memberships/studio/timetable-suggestions`, auth),
        axios.get(`${API}/memberships/studio/retention-risk?weeks=8&limit=25`, auth),
      ]);
      setData(board.data);
      setHeatmap(hm.data);
      setSuggestions(sg.data);
      setRetention(rk.data);
    } catch (e) {
      notify.error('Failed to load studio brain', e?.response?.data?.detail || e.message);
    } finally { setLoading(false); }
  }, [API, auth]);
  useEffect(() => { load(); }, [load]);

  if (loading) {
    return (
      <div className="flex items-center gap-2 text-sm text-muted-foreground p-6" data-testid="studio-brain-loading">
        <Loader2 size={14} className="animate-spin" /> Scoring your studio…
      </div>
    );
  }
  if (!data) return null;

  const k = data.kpis || {};
  const risk = retention?.summary || data.retention_summary || {};
  const rows = retention?.rows || [];
  const sugg = suggestions?.suggestions || [];

  return (
    <div className="space-y-5" data-testid="studio-brain-tab">
      {/* Headline */}
      <section
        className="rounded-2xl border p-4 flex items-start gap-3 flex-wrap"
        style={{
          borderColor: 'var(--theme-border, #e0e0e0)',
          background: 'linear-gradient(135deg, rgba(25, 205, 255,0.10), rgba(59,130,246,0.06))',
        }}
        data-testid="studio-brain-headline"
      >
        <div className="rounded-full p-2" style={{ background: 'rgba(25, 205, 255,0.2)' }}>
          <Brain size={18} className="text-violet-600" />
        </div>
        <div className="flex-1 min-w-0">
          <p className="text-[11px] uppercase tracking-wider font-bold opacity-60">
            Headline · what to do this week
          </p>
          <h2 className="text-base font-bold leading-snug mt-0.5" data-testid="studio-brain-headline-text">
            {data.headline}
          </h2>
        </div>
        <button type="button" onClick={load} className="px-2 py-1 rounded text-[11px] font-bold border inline-flex items-center gap-1" style={{ borderColor: 'var(--theme-border)' }} data-testid="studio-brain-refresh">
          <RefreshCw size={11} /> Refresh
        </button>
      </section>

      {/* KPIs */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3" data-testid="studio-brain-kpis">
        <Kpi label="Members" value={k.members_total} icon={Users} />
        <Kpi
          label="New (30d)"
          value={k.members_new_30d}
          hint={k.growth_pct !== null && k.growth_pct !== undefined
            ? `${k.growth_pct >= 0 ? '+' : ''}${k.growth_pct}% vs prev 30d`
            : null}
          trend={k.growth_pct}
          icon={TrendingUp}
        />
        <Kpi label="Revenue (30d)" value={fmtGBP(k.revenue_30d_pence)} icon={Sparkles} />
        <Kpi label="Bookings (30d)" value={k.bookings_30d} icon={CalendarRange} />
      </div>

      {/* At-risk + Heatmap — two columns */}
      <div className="grid grid-cols-1 xl:grid-cols-2 gap-5">
        <RetentionCard summary={risk} rows={rows} testid="retention" />
        <HeatmapCard heatmap={heatmap} testid="heatmap" />
      </div>

      {/* AI suggestions */}
      <SuggestionsCard suggestions={sugg} model={suggestions?.model} />
    </div>
  );
}

function Kpi({ label, value, hint, icon: Icon, trend }) {
  const trendIcon = trend && trend > 0 ? TrendingUp : (trend !== null && trend !== undefined && trend < 0 ? TrendingDown : null);
  return (
    <div className="rounded-2xl border p-3" style={{ borderColor: 'var(--theme-border, #e0e0e0)', background: 'var(--theme-surface, #fff)' }} data-testid={`studio-brain-kpi-${label.toLowerCase().replace(/\s+/g, '-').replace(/[()]/g, '')}`}>
      <div className="flex items-center gap-2 opacity-70">
        {Icon ? <Icon size={12} /> : null}
        <span className="text-[10px] uppercase tracking-wider font-bold">{label}</span>
      </div>
      <p className="text-xl font-extrabold tabular-nums mt-1">{value ?? '—'}</p>
      {hint ? (
        <p className="text-[11px] opacity-70 mt-0.5 inline-flex items-center gap-1">
          {trendIcon && React.createElement(trendIcon, { size: 10, style: { color: trend > 0 ? '#10b981' : '#ef4444' } })}
          <span>{hint}</span>
        </p>
      ) : null}
    </div>
  );
}

function RetentionCard({ summary, rows, testid }) {
  return (
    <section className="rounded-2xl border p-4" style={{ borderColor: 'var(--theme-border, #e0e0e0)', background: 'var(--theme-surface, #fff)' }} data-testid={`studio-brain-${testid}`}>
      <header className="flex items-start justify-between flex-wrap gap-2 mb-3">
        <div>
          <p className="text-[11px] uppercase tracking-wider font-bold opacity-60 inline-flex items-center gap-1">
            <AlertTriangle size={11} /> Retention risk
          </p>
          <h3 className="text-base font-bold">Students trending towards churn</h3>
        </div>
        <div className="flex items-center gap-1 flex-wrap">
          <BandPill tone={RISK_TONES.high}   value={summary.high ?? 0}   label="high" />
          <BandPill tone={RISK_TONES.medium} value={summary.medium ?? 0} label="medium" />
          <BandPill tone={RISK_TONES.low}    value={summary.low ?? 0}    label="low" />
        </div>
      </header>
      {rows.length === 0 ? (
        <div className="text-center py-6 px-3 rounded-xl border-2 border-dashed" style={{ borderColor: 'var(--theme-border, #e0e0e0)' }} data-testid={`studio-brain-${testid}-empty`}>
          <Zap size={22} className="mx-auto mb-1 text-emerald-500" />
          <p className="text-sm font-bold">All clear</p>
          <p className="text-xs opacity-70 mt-1">No students show a concerning attendance pattern. We'll surface any drops as they appear.</p>
        </div>
      ) : (
        <ul className="space-y-1.5" data-testid={`studio-brain-${testid}-list`}>
          {rows.map((r, idx) => {
            const tone = RISK_TONES[r.band] || RISK_TONES.low;
            return (
              <li key={`${r.member_id}-${r.sub_profile_id}-${idx}`} className="flex items-start gap-2 p-2 rounded border" style={{ borderColor: 'var(--theme-border, #e0e0e0)' }} data-testid={`studio-brain-${testid}-row-${idx}`}>
                <span style={{ width: 4, alignSelf: 'stretch', background: tone.fg, borderRadius: 2, flexShrink: 0 }} />
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 flex-wrap">
                    <span className="text-sm font-bold truncate">{r.attendee_name}</span>
                    <span className="px-1.5 py-0.5 rounded-full text-[10px] font-bold tabular-nums" style={{ background: tone.bg, color: tone.fg }}>
                      {r.score}/100 · {tone.label}
                    </span>
                    {r.days_since_last_attended !== null ? (
                      <span className="text-[10px] opacity-60 ml-auto tabular-nums">{r.days_since_last_attended}d ago</span>
                    ) : null}
                  </div>
                  <ul className="list-disc list-inside space-y-0 text-[11px] opacity-80 mt-0.5">
                    {(r.reasons || []).map((reason, i) => <li key={i}>{reason}</li>)}
                  </ul>
                </div>
              </li>
            );
          })}
        </ul>
      )}
    </section>
  );
}

function BandPill({ tone, value, label }) {
  return (
    <span className="px-2 py-0.5 rounded-full text-[10px] font-bold" style={{ background: tone.bg, color: tone.fg }}>
      {value} {label}
    </span>
  );
}

function HeatmapCard({ heatmap, testid }) {
  if (!heatmap) return null;
  const { days = [], buckets = [], cells = [] } = heatmap;
  const byDayBucket = {};
  cells.forEach((c) => { byDayBucket[`${c.day}/${c.bucket}`] = c; });

  // Colour by utilisation %.
  const colourFor = (pct, occurrences) => {
    if (!occurrences) return 'rgba(148,163,184,0.08)';
    if (pct >= 90) return '#dc2626';
    if (pct >= 75) return '#d97706';
    if (pct >= 50) return '#f59e0b';
    if (pct >= 25) return '#84cc16';
    return '#19cdff';
  };

  return (
    <section className="rounded-2xl border p-4" style={{ borderColor: 'var(--theme-border, #e0e0e0)', background: 'var(--theme-surface, #fff)' }} data-testid={`studio-brain-${testid}`}>
      <header className="mb-3">
        <p className="text-[11px] uppercase tracking-wider font-bold opacity-60 inline-flex items-center gap-1">
          <CalendarRange size={11} /> Occupancy heatmap · last 4 weeks
        </p>
        <h3 className="text-base font-bold">Where your studio is full (and empty)</h3>
      </header>
      <div className="overflow-x-auto" data-testid={`studio-brain-${testid}-grid`}>
        <table className="w-full text-[11px]" style={{ tableLayout: 'fixed' }}>
          <thead>
            <tr>
              <th className="text-left p-1"></th>
              {days.map((d) => <th key={d} className="text-center p-1 font-bold opacity-70">{d}</th>)}
            </tr>
          </thead>
          <tbody>
            {buckets.map((b) => (
              <tr key={b}>
                <td className="p-1 opacity-70 tabular-nums">{b}</td>
                {days.map((d) => {
                  const c = byDayBucket[`${d}/${b}`] || { utilisation_pct: 0, occurrences: 0, booked: 0, capacity_total: 0 };
                  const bg = colourFor(c.utilisation_pct, c.occurrences);
                  return (
                    <td key={`${d}-${b}`} className="p-0.5">
                      <div
                        className="rounded text-center tabular-nums font-bold"
                        style={{
                          background: bg,
                          color: c.utilisation_pct >= 50 && c.occurrences ? '#fff' : 'inherit',
                          padding: '6px 2px',
                          minHeight: 26,
                          opacity: c.occurrences ? 1 : 0.5,
                        }}
                        title={`${d} ${b} — ${c.booked}/${c.capacity_total} (${c.utilisation_pct}%) across ${c.occurrences} classes`}
                        data-testid={`studio-brain-${testid}-cell-${d}-${b}`}
                      >
                        {c.occurrences ? `${c.utilisation_pct}%` : ''}
                      </div>
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div className="flex items-center gap-2 mt-3 text-[10px] opacity-70 flex-wrap" data-testid={`studio-brain-${testid}-legend`}>
        <LegendSwatch c="#19cdff" label="<25%" />
        <LegendSwatch c="#84cc16" label="25–49%" />
        <LegendSwatch c="#f59e0b" label="50–74%" />
        <LegendSwatch c="#d97706" label="75–89%" />
        <LegendSwatch c="#dc2626" label="≥ 90%" />
      </div>
      {heatmap.hottest && heatmap.coldest ? (
        <div className="grid grid-cols-2 gap-2 mt-3 text-[11px]">
          <div className="rounded-lg border p-2" style={{ borderColor: 'var(--theme-border)' }} data-testid={`studio-brain-${testid}-hottest`}>
            <p className="opacity-60 uppercase tracking-wider text-[10px] font-bold">Hottest slot</p>
            <p className="font-bold">{heatmap.hottest.day} {heatmap.hottest.bucket}</p>
            <p className="opacity-70">{heatmap.hottest.booked}/{heatmap.hottest.capacity_total} · {heatmap.hottest.utilisation_pct}%</p>
          </div>
          <div className="rounded-lg border p-2" style={{ borderColor: 'var(--theme-border)' }} data-testid={`studio-brain-${testid}-coldest`}>
            <p className="opacity-60 uppercase tracking-wider text-[10px] font-bold">Coldest slot</p>
            <p className="font-bold">{heatmap.coldest.day} {heatmap.coldest.bucket}</p>
            <p className="opacity-70">{heatmap.coldest.booked}/{heatmap.coldest.capacity_total} · {heatmap.coldest.utilisation_pct}%</p>
          </div>
        </div>
      ) : null}
    </section>
  );
}

function LegendSwatch({ c, label }) {
  return (
    <span className="inline-flex items-center gap-1">
      <span style={{ width: 10, height: 10, borderRadius: 2, background: c, display: 'inline-block' }} />
      {label}
    </span>
  );
}

function SuggestionsCard({ suggestions, model }) {
  const hot = suggestions.filter((s) => s.kind === 'open_extra_slot');
  const cold = suggestions.filter((s) => s.kind === 'consolidate_or_drop');
  const other = suggestions.filter((s) => !['open_extra_slot', 'consolidate_or_drop'].includes(s.kind));
  return (
    <section className="rounded-2xl border p-4" style={{ borderColor: 'var(--theme-border, #e0e0e0)', background: 'var(--theme-surface, #fff)' }} data-testid="studio-brain-suggestions">
      <header className="flex items-start justify-between flex-wrap gap-2 mb-3">
        <div>
          <p className="text-[11px] uppercase tracking-wider font-bold opacity-60 inline-flex items-center gap-1">
            <Wand2 size={11} className="text-violet-500" /> AI timetable optimisation
          </p>
          <h3 className="text-base font-bold">What to change about your schedule</h3>
        </div>
        <span className="text-[10px] opacity-60 px-2 py-0.5 rounded-full border" style={{ borderColor: 'var(--theme-border)' }} data-testid="studio-brain-suggestions-model">
          {model || 'heuristic_only'}
        </span>
      </header>
      {suggestions.length === 0 ? (
        <div className="text-center py-6 px-3 rounded-xl border-2 border-dashed" style={{ borderColor: 'var(--theme-border, #e0e0e0)' }} data-testid="studio-brain-suggestions-empty">
          <Sparkles size={22} className="mx-auto mb-1 text-violet-500" />
          <p className="text-sm font-bold">Not enough signal yet</p>
          <p className="text-xs opacity-70 mt-1">We need at least a few weeks of booking history to suggest meaningful timetable changes.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          <SuggestionGroup title="Open another slot" tone="#10b981" items={hot} icon={TrendingUp} testid="hot" />
          <SuggestionGroup title="Consolidate or drop" tone="#f59e0b" items={cold} icon={TrendingDown} testid="cold" />
          {other.length ? (
            <SuggestionGroup title="Other opportunities" tone="#19cdff" items={other} icon={Sparkles} testid="other" />
          ) : null}
        </div>
      )}
    </section>
  );
}

function SuggestionGroup({ title, tone, items, icon: Icon, testid }) {
  if (!items.length) {
    return (
      <div className="rounded-xl border p-3" style={{ borderColor: 'var(--theme-border, #e0e0e0)', opacity: 0.7 }} data-testid={`studio-brain-suggestions-${testid}-empty`}>
        <p className="text-[11px] uppercase tracking-wider font-bold opacity-60 inline-flex items-center gap-1">
          <Icon size={11} style={{ color: tone }} /> {title}
        </p>
        <p className="text-xs opacity-60 italic mt-1">No candidates in this band.</p>
