/**
 * Service Desk → Equipment (Iter 216h49)
 *
 * Pulse Fitness asked for parity with Sicon Service: one global search
 * box across every customer's kit, so a desk operator can type a serial
 * number or model and pinpoint exactly which gym a machine lives at.
 *
 * Read-only on purpose — Service Desk staff do NOT impersonate the
 * customer to inspect kit; the org name + site name are surfaced inline
 * on every row so the desk operator has full context without entering
 * the customer's account. Mutations (move/delete) still go through the
 * customer's own owner/manager via the Pulse Equipment tab.
 */
import { useEffect, useState, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import axios from 'axios';
import { Search, Wrench, Building2, MapPin, Calendar, Hash, ClipboardList, PackagePlus, PackageMinus, CheckCircle2, XCircle, Loader2, Printer } from 'lucide-react';
import { notify } from '@/components/notifications';
import { Card } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import ServiceDeskIntakeForm from '@/pages/ServiceOps/ServiceDeskIntakeForm';

const DeskEquipment = ({ API }) => {
  const { t } = useTranslation();
  const [q, setQ] = useState('');
  const [equipment, setEquipment] = useState([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(false);

  const search = useCallback(async (query) => {
    setLoading(true);
    try {
      const token = localStorage.getItem('token');
      const res = await axios.get(`${API}/service-desk/equipment`, {
        params: { q: query, limit: 50 },
        headers: { Authorization: `Bearer ${token}` },
      });
      setEquipment(res.data?.equipment || []);
      setTotal(res.data?.total || 0);
    } catch {
      setEquipment([]); setTotal(0);
    } finally {
      setLoading(false);
    }
  }, [API]);

  // Debounce 300ms so per-keystroke requests don't flood the API.
  useEffect(() => {
    const timer = setTimeout(() => { search(q); }, q ? 300 : 0);
    return () => clearTimeout(timer);
  }, [q, search]);

  // ── Site-first browse: pick a customer + site to view/select machines
  const [customers, setCustomers] = useState([]);
  const [custOrg, setCustOrg] = useState('');
  const [sitesList, setSitesList] = useState([]);
  const [siteSel, setSiteSel] = useState('');
  const [siteEquip, setSiteEquip] = useState([]);
  const [selected, setSelected] = useState([]);
  const [intakeInitial, setIntakeInitial] = useState(null);
  const authH = () => ({ headers: { Authorization: `Bearer ${localStorage.getItem('token') || ''}` } });

  useEffect(() => {
    (async () => {
      try { const r = await axios.get(`${API}/svc/desk/customers`, authH()); setCustomers(r.data?.customers || []); }
      catch { /* non-blocking */ }
    })();
  }, [API]);
  useEffect(() => {
    setSitesList([]); setSiteSel(''); setSiteEquip([]); setSelected([]);
    if (!custOrg) return;
    (async () => {
      try { const r = await axios.get(`${API}/svc/desk/customer-sites`, { params: { organization_id: custOrg }, ...authH() }); setSitesList(r.data?.sites || []); }
      catch { setSitesList([]); }
    })();
  }, [custOrg, API]);
  useEffect(() => {
    setSiteEquip([]); setSelected([]);
    if (!custOrg || !siteSel) return;
    (async () => {
      try { const r = await axios.get(`${API}/svc/desk/customer-equipment`, { params: { organization_id: custOrg, site_id: siteSel }, ...authH() }); setSiteEquip(r.data?.equipment || []); }
      catch { setSiteEquip([]); }
    })();
  }, [custOrg, siteSel, API]);

  const toggleSel = (id) => setSelected((p) => (p.includes(id) ? p.filter((x) => x !== id) : [...p, id]));
  const openCase = () => {
    if (!selected.length) return;
    let siteId = siteSel;
    if (siteSel === 'all') {
      const sites = [...new Set(siteEquip.filter((e) => selected.includes(e.id)).map((e) => e.site_id || ''))];
      if (sites.length !== 1 || !sites[0]) {
        notify.error(t('service.eq_one_site_only', 'Pick machines from one site to log a case'), sites.includes('') ? t('service.eq_one_site_hint', 'Unassigned machines need a site first.') : undefined);
        return;
      }
      [siteId] = sites;
    }
    setIntakeInitial({ customerOrgId: custOrg, siteId, equipmentIds: selected });
  };
  const [printing, setPrinting] = useState(false);
  const printList = async () => {
    const win = window.open('', '_blank');
    setPrinting(true);
    try {
      const r = await axios.get(`${API}/svc/desk/customer-equipment.pdf`, { params: { organization_id: custOrg, site_id: siteSel }, responseType: 'blob', ...authH() });
      const url = URL.createObjectURL(new Blob([r.data], { type: 'application/pdf' }));
      if (win) win.location.href = url; else window.location.href = url;
    } catch {
      win?.close();
      notify.error(t('service.eq_print_failed', 'Could not build the asset list'));
    } finally { setPrinting(false); }
  };

  return (
    <div className="space-y-5" data-testid="desk-equipment">
      <header>
        <h2 className="text-2xl font-bold text-slate-900 dark:text-zinc-100">{t('service.eq_title', 'Equipment')}</h2>
        <p className="text-sm text-slate-500 mt-1">
          {t('service.eq_subtitle', "Search every customer's kit by name, model, manufacturer or serial number. Read-only view — use the customer's own console to make changes.")}
        </p>
      </header>

      <EquipmentChangeReview API={API} />

      {/* Site-first: choose a customer + site to view and select machines */}
      <Card className="p-4 bg-white border-slate-200 dark:bg-zinc-900 dark:border-zinc-800" data-testid="desk-equipment-sitefirst">
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          <div>
            <label className="text-xs font-semibold text-slate-500">{t('service.eq_customer', 'Customer')}</label>
            <select value={custOrg} onChange={(e) => setCustOrg(e.target.value)}
              className="w-full mt-1 h-10 rounded-lg border border-slate-200 dark:border-zinc-700 bg-white dark:bg-zinc-900 px-3 text-sm" data-testid="desk-eq-customer">
              <option value="">{t('service.eq_select_customer', '— Select customer —')}</option>
              {customers.map((c) => <option key={c.organization_id} value={c.organization_id}>{c.name}{c.is_operator ? ' (my org)' : ''}</option>)}
            </select>
          </div>
          <div>
            <label className="text-xs font-semibold text-slate-500">{t('service.eq_site', 'Site')}</label>
            <select value={siteSel} onChange={(e) => setSiteSel(e.target.value)} disabled={!custOrg}
              className="w-full mt-1 h-10 rounded-lg border border-slate-200 dark:border-zinc-700 bg-white dark:bg-zinc-900 px-3 text-sm" data-testid="desk-eq-site">
              <option value="">{sitesList.length ? t('service.eq_select_site', '— Select site —') : t('service.eq_no_sites', 'No sites')}</option>
              {sitesList.length > 0 && <option value="all">{t('service.eq_all_sites', 'All sites')}</option>}
              {sitesList.map((s) => <option key={s.id} value={s.id}>{s.name}{s.equipment_count != null ? ` · ${s.equipment_count} machines` : ''}</option>)}
            </select>
          </div>
        </div>
        {siteSel && (
          <div className="mt-3">
            <div className="flex items-center justify-between mb-2">
              <span className="text-xs font-semibold text-slate-500">{siteEquip.length} machines · {selected.length} selected</span>
              <div className="flex items-center gap-2">
              <Button size="sm" variant="outline" disabled={printing || !siteEquip.length} onClick={printList} data-testid="desk-eq-print">
                {printing ? <Loader2 size={13} className="mr-1.5 animate-spin" /> : <Printer size={13} className="mr-1.5" />} {t('service.eq_print_list', 'Print asset list')}
              </Button>
              <Button size="sm" disabled={!selected.length} onClick={openCase} data-testid="desk-eq-logcase"
                className="bg-[var(--color-brand-cyan)] text-[var(--color-ink)] hover:opacity-90">
                <ClipboardList size={13} className="mr-1.5" /> {t('service.eq_log_case_for', 'Log case for {{n}} machine(s)', { n: selected.length || '' })}
              </Button>
              </div>
            </div>
            <div className="max-h-80 overflow-auto rounded-lg border border-slate-200 dark:border-zinc-800 divide-y divide-slate-100 dark:divide-zinc-800" data-testid="desk-eq-machinelist">
              {siteEquip.length === 0 ? <p className="p-3 text-xs text-slate-400">{t('service.eq_none_site', 'No equipment on this site')}</p> : siteEquip.map((e) => (
                <label key={e.id} className="flex items-center gap-2 px-3 py-2 text-sm cursor-pointer hover:bg-slate-50 dark:hover:bg-zinc-800" data-testid={`desk-eq-machine-${e.id}`}>
                  <input type="checkbox" checked={selected.includes(e.id)} onChange={() => toggleSel(e.id)} />
                  <span className="flex-1 truncate">{e.name || 'Unnamed'}{e.manufacturer ? ` · ${e.manufacturer}` : ''}{e.model ? ` ${e.model}` : ''}</span>
                  {siteSel === 'all' && <span className="text-[11px] text-slate-500 truncate max-w-[30%]">{e.site_name}</span>}
                  {e.serial_number && <span className="text-[11px] font-mono text-slate-400">{e.serial_number}</span>}
                </label>
              ))}
            </div>
          </div>
        )}
      </Card>

      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
        <Input
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder={t('service.eq_search_ph', 'Search equipment across all customers (e.g. Matrix T75, 12345-A, treadmill)…')}
          className="pl-10 h-11 bg-white dark:bg-zinc-900"
          data-testid="desk-equipment-search"
        />
      </div>

      {loading && (
        <p className="text-sm text-slate-500" data-testid="desk-equipment-loading">{t('service.eq_searching', 'Searching…')}</p>
      )}

      {!loading && equipment.length === 0 && (
        <Card className="p-12 text-center bg-white border-slate-200 dark:bg-zinc-900 dark:border-zinc-800" data-testid="desk-equipment-empty">
          <Wrench size={36} className="mx-auto mb-3 text-slate-300" />
          <p className="text-sm font-medium text-slate-600">
            {q ? t('service.eq_no_match', 'No matching equipment') : t('service.eq_start_typing', "Start typing to search every customer's kit")}
          </p>
          <p className="text-xs text-slate-400 mt-1">
            {q ? t('service.eq_try_diff', 'Try a different model name or serial number.') : t('service.eq_context_hint', 'Org and site context appear inline on every result.')}
          </p>
        </Card>
      )}

      {!loading && equipment.length > 0 && (
        <p className="text-xs text-slate-500">{t('service.eq_showing', 'Showing {{n}} of {{total}} matching items', { n: equipment.length, total })}</p>
      )}

      <div className="space-y-2">
        {equipment.map((eq) => (
          <Card
            key={eq.id}
            className="p-4 bg-white border-slate-200 hover:border-slate-300 transition-colors dark:bg-zinc-900 dark:border-zinc-800"
            data-testid={`desk-equipment-row-${eq.id}`}
          >
            <div className="flex items-start gap-4">
              <div className="w-10 h-10 rounded-lg flex items-center justify-center shrink-0 bg-slate-100 dark:bg-zinc-800">
                <Wrench size={18} className="text-slate-500" />
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 flex-wrap">
                  <p className="text-sm font-semibold text-slate-900 truncate dark:text-zinc-100">{eq.name || t('service.eq_unnamed', 'Unnamed equipment')}</p>
                  {eq.equipment_type && (
                    <Badge variant="outline" className="text-[10px] border-slate-200 text-slate-500 dark:border-zinc-800">
                      {eq.equipment_type}
                    </Badge>
                  )}
                </div>
                <div className="flex items-center gap-4 flex-wrap mt-1 text-xs text-slate-500">
                  {eq.organization_name && (
                    <span className="flex items-center gap-1">
                      <Building2 size={11} className="text-slate-400" />
                      {eq.organization_name}
                    </span>
                  )}
                  {eq.site_name && (
                    <span className="flex items-center gap-1">
                      <MapPin size={11} className="text-slate-400" />
                      {eq.site_name}
                    </span>
                  )}
                  {eq.manufacturer && (
                    <span>
                      {eq.manufacturer}{eq.model ? ` · ${eq.model}` : ''}
                    </span>
                  )}
                  {eq.serial_number && (
                    <span className="flex items-center gap-1 font-mono">
                      <Hash size={10} className="text-slate-400" />
                      {eq.serial_number}
                    </span>
                  )}
                  {eq.warranty_expiry && (
                    <span className="flex items-center gap-1">
                      <Calendar size={11} className="text-slate-400" />
                      {t('service.eq_warranty', 'Warranty')} {new Date(eq.warranty_expiry).toLocaleDateString('en-GB')}
                    </span>
                  )}
                </div>
              </div>
            </div>
          </Card>
        ))}
      </div>

      {intakeInitial && (
        <ServiceDeskIntakeForm
          initial={intakeInitial}
          onClose={() => setIntakeInitial(null)}
          onCreated={() => { setIntakeInitial(null); setSelected([]); }}
        />
      )}
    </div>
  );
};

export default DeskEquipment;

// ─────────────────────────────────────────────────────────────────
// Office review queue for engineer-proposed equipment add/remove.
// Nothing is applied to a site's asset list until approved here.
// ─────────────────────────────────────────────────────────────────
function EquipmentChangeReview({ API }) {
  const [rows, setRows] = useState([]);
  const [pending, setPending] = useState(0);
  const [open, setOpen] = useState(false);
  const [busyId, setBusyId] = useState(null);
  const auth = () => ({ headers: { Authorization: `Bearer ${localStorage.getItem('token') || ''}` } });

  const load = useCallback(async () => {
    try {
      const r = await axios.get(`${API}/svc/desk/equipment-change-requests`, { ...auth(), params: { status: 'pending' } });
      setRows(r.data?.requests || []);
      setPending(r.data?.pending_count || 0);
    } catch { setRows([]); setPending(0); }
  }, [API]);
  useEffect(() => { load(); }, [load]);

  const decide = async (id, action) => {
    setBusyId(id);
    try {
      await axios.post(`${API}/svc/desk/equipment-change-requests/${id}/${action}`, {}, auth());
      await load();
    } catch (e) {
      // eslint-disable-next-line no-alert
      window.alert(e?.response?.data?.detail || `Could not ${action}`);
    } finally { setBusyId(null); }
  };

  if (pending === 0 && !open) return null;

  return (
    <Card className="p-4 bg-white border-amber-200 dark:bg-zinc-900 dark:border-amber-900/50" data-testid="equipment-change-review">
      <button type="button" onClick={() => setOpen((o) => !o)} className="w-full flex items-center justify-between" data-testid="equipment-change-review-toggle">
        <span className="text-sm font-bold flex items-center gap-2 text-amber-800 dark:text-amber-300">
          <ClipboardList size={15} /> Equipment changes to review
          {pending > 0 && <span className="text-[10px] font-extrabold px-2 py-0.5 rounded-full bg-amber-500 text-white" data-testid="equipment-change-badge">{pending}</span>}
        </span>
        <span className="text-xs text-slate-400">{open ? 'Hide' : 'Show'}</span>
      </button>
      {open && (
        <div className="mt-3 space-y-2" data-testid="equipment-change-list">
          {rows.length === 0 ? (
            <p className="text-xs text-slate-500">No changes awaiting review.</p>
          ) : rows.map((r) => (
            <div key={r.id} className="rounded-lg border border-slate-200 dark:border-zinc-800 p-3 flex items-start justify-between gap-3" data-testid={`equipment-change-${r.id}`}>
              <div className="min-w-0">
                <div className="flex items-center gap-2">
                  {r.change_type === 'add'
                    ? <span className="inline-flex items-center gap-1 text-[10px] font-bold uppercase px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-700"><PackagePlus size={11} /> Add</span>
                    : <span className="inline-flex items-center gap-1 text-[10px] font-bold uppercase px-2 py-0.5 rounded-full bg-rose-100 text-rose-700"><PackageMinus size={11} /> Remove</span>}
                  <span className="text-sm font-bold text-slate-900 dark:text-zinc-100 truncate">
                    {r.change_type === 'add' ? (r.proposed?.name || 'New equipment') : (r.equipment_name || 'Equipment')}
                  </span>
                </div>
                <p className="text-[11px] text-slate-500 mt-0.5">
                  {r.site_name || '—'}{r.customer_name ? ` · ${r.customer_name}` : ''} · by {r.engineer_name}
                </p>
                {r.change_type === 'add' && (
                  <p className="text-[11px] text-slate-500 mt-0.5">
                    {[r.proposed?.equipment_type, r.proposed?.manufacturer, r.proposed?.model].filter(Boolean).join(' · ')}
                    {r.proposed?.serial_number ? ` · SN ${r.proposed.serial_number}` : ''}
                  </p>
                )}
                {r.change_type === 'remove' && r.reason && <p className="text-[11px] text-slate-500 mt-0.5">Reason: {r.reason}</p>}
                {r.proposed?.notes && <p className="text-[11px] text-slate-500 mt-0.5">{r.proposed.notes}</p>}
              </div>
              <div className="flex items-center gap-1.5 shrink-0">
                <Button size="sm" variant="outline" disabled={busyId === r.id} onClick={() => decide(r.id, 'reject')} data-testid={`equipment-change-reject-${r.id}`}
                  className="text-rose-600 border-rose-200 hover:bg-rose-50">
                  {busyId === r.id ? <Loader2 size={13} className="animate-spin" /> : <XCircle size={13} />}
                </Button>
                <Button size="sm" disabled={busyId === r.id} onClick={() => decide(r.id, 'approve')} data-testid={`equipment-change-approve-${r.id}`}
                  className="bg-emerald-600 text-white hover:bg-emerald-700">
                  {busyId === r.id ? <Loader2 size={13} className="animate-spin mr-1" /> : <CheckCircle2 size={13} className="mr-1" />} Approve
                </Button>
              </div>
            </div>
          ))}
        </div>
      )}
    </Card>
  );
}

/**
 * Migration Import Wizard — Iter 255.
 *
 * 4-step guided import for service suppliers migrating onto the platform:
 * Upload (CSV/XLSX) → Map columns (rule-based + AI fallback) → Preview &
 * validate (errors + duplicates) → Commit (summary + error CSV download).
 * Backed by /api/svc/imports/*.
 */
import { useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import axios from 'axios';
import { Card } from '@/components/ui/card';
import {
  Upload, Users, ClipboardList, Loader2, Sparkles, ArrowRight, ArrowLeft,
  CheckCircle2, AlertTriangle, Download, RotateCcw,
} from 'lucide-react';
import { authConfig } from './authConfig';

export default function DeskImports({ API, embedded = false }) {
  const { t } = useTranslation();
  const TYPES = [
    { id: 'customers', label: t('service.imp_type_customers', 'Customers & sites'), icon: Users, blurb: t('service.imp_type_customers_blurb', 'Names, contacts and site addresses → your customer book.') },
    { id: 'cases', label: t('service.imp_type_cases', 'Historical cases'), icon: ClipboardList, blurb: t('service.imp_type_cases_blurb', 'Past jobs imported as closed records with their original dates.') },
  ];
  const STEP_LABELS = [
    t('service.imp_step_upload', 'Upload'),
    t('service.imp_step_map', 'Map columns'),
    t('service.imp_step_preview', 'Preview'),
    t('service.imp_step_done', 'Done'),
  ];
  const fileRef = useRef(null);
  const [step, setStep] = useState(0);
  const [importType, setImportType] = useState('customers');
  const [busy, setBusy] = useState(false);
  const [aiBusy, setAiBusy] = useState(false);
  const [error, setError] = useState('');
  const [job, setJob] = useState(null);          // /parse response
  const [mapping, setMapping] = useState({});    // header -> field|''
  const [validation, setValidation] = useState(null);
  const [strategy, setStrategy] = useState('skip');
  const [result, setResult] = useState(null);

  const reset = () => {
    setStep(0); setJob(null); setMapping({}); setValidation(null);
    setResult(null); setError(''); setStrategy('skip');
    if (fileRef.current) fileRef.current.value = '';
  };

  const fail = (e, fallback) => setError(e.response?.data?.detail || fallback);

  const upload = async (file) => {
    if (!file) return;
    setBusy(true); setError('');
    try {
      const fd = new FormData();
      fd.append('file', file);
      fd.append('import_type', importType);
      const { data } = await axios.post(`${API}/svc/imports/parse`, fd, authConfig());
      setJob(data);
      setMapping(Object.fromEntries(
        Object.entries(data.suggested_mapping).map(([h, f]) => [h, f || ''])));
      setStep(1);
    } catch (e) { fail(e, t('service.imp_upload_failed', 'Upload failed')); } finally { setBusy(false); }
  };

  const askAi = async () => {
    const unmatched = Object.entries(mapping).filter(([, f]) => !f).map(([h]) => h);
    if (!unmatched.length) return;
    setAiBusy(true); setError('');
    try {
      const { data } = await axios.post(`${API}/svc/imports/${job.import_id}/ai-map`,
        { headers: unmatched }, authConfig());
      const found = Object.entries(data.mapping || {}).filter(([, f]) => f);
      if (!found.length) { setError(t('service.imp_ai_none', 'AI could not confidently map the remaining columns — pick them manually.')); return; }
      setMapping((m) => ({ ...m, ...Object.fromEntries(found) }));
    } catch (e) { fail(e, t('service.imp_ai_failed', 'AI mapping failed — map the remaining columns manually')); }
    finally { setAiBusy(false); }
  };

  const runValidate = async () => {
    setBusy(true); setError('');
    try {
      const { data } = await axios.post(`${API}/svc/imports/${job.import_id}/validate`,
        { mapping }, authConfig());
      setValidation(data);
      setStep(2);
    } catch (e) { fail(e, t('service.imp_validation_failed', 'Validation failed')); } finally { setBusy(false); }
  };

  const runCommit = async () => {
    setBusy(true); setError('');
    try {
      const { data } = await axios.post(`${API}/svc/imports/${job.import_id}/commit`,
        { mapping, duplicate_strategy: strategy }, authConfig());
      setResult(data);
      setStep(3);
    } catch (e) { fail(e, t('service.imp_import_failed', 'Import failed')); } finally { setBusy(false); }
  };

  const downloadErrors = async () => {
    const r = await axios.get(`${API}/svc/imports/${job.import_id}/errors.csv`,
      { ...authConfig(), responseType: 'blob' });
    const url = URL.createObjectURL(new Blob([r.data], { type: 'text/csv' }));
    const a = document.createElement('a');
    a.href = url; a.download = 'import-errors.csv';
    document.body.appendChild(a); a.click(); a.remove();
    URL.revokeObjectURL(url);
  };

  const fields = job?.target_fields || {};
  const usedFields = new Set(Object.values(mapping).filter(Boolean));
  const requiredUnmapped = Object.entries(fields)
    .filter(([k, v]) => v.required && !usedFields.has(k)).map(([, v]) => v.label);
  const unmatchedCount = Object.values(mapping).filter((f) => !f).length;

  return (
    <div className="space-y-6 max-w-4xl" data-testid="desk-imports">
      {!embedded && (
      <div>
        <h1 className="text-2xl font-semibold text-zinc-900 dark:text-zinc-100">{t('service.imp_title', 'Import data')}</h1>
        <p className="text-sm text-zinc-500 mt-1">
          {t('service.imp_subtitle', 'Migrate customers, sites and historical cases from spreadsheets or a legacy system.')}
        </p>
      </div>
      )}

      {/* Stepper */}
      <div className="flex items-center gap-2" data-testid="import-stepper">
        {STEP_LABELS.map((label, i) => (
          <div key={i} className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-semibold ${
            i === step ? 'bg-orange-500 text-white'
              : i < step ? 'bg-emerald-50 text-emerald-700'
                : 'bg-white text-zinc-400 border border-zinc-200'
          }`} data-testid={`import-step-${i}`}>
            {i < step ? <CheckCircle2 size={13} /> : <span>{i + 1}.</span>} {label}
          </div>
        ))}
      </div>

      {error && (
        <div className="text-sm text-red-600 bg-red-50 border border-red-100 rounded-lg px-3 py-2" data-testid="import-error">
          {error}
        </div>
      )}

      {/* Step 1 — type + upload */}
      {step === 0 && (
        <Card className="p-6 space-y-5" data-testid="import-upload-step">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            {TYPES.map(({ id, label, icon: Icon, blurb }) => (
              <button key={id} onClick={() => setImportType(id)}
                className={`text-left p-4 rounded-xl border transition-colors ${
                  importType === id ? 'border-orange-500 bg-orange-50/50 ring-1 ring-orange-500/30' : 'border-zinc-200 hover:border-zinc-300'
                }`} data-testid={`import-type-${id}`}>
                <Icon size={18} className={importType === id ? 'text-orange-600' : 'text-zinc-400'} />
                <div className="text-sm font-semibold text-zinc-900 mt-2">{label}</div>
                <div className="text-xs text-zinc-500 mt-0.5">{blurb}</div>
              </button>
            ))}
          </div>
          <div className="border-2 border-dashed border-zinc-200 rounded-xl p-8 text-center">
            <Upload className="mx-auto text-zinc-400 mb-2" size={22} />
            <p className="text-sm text-zinc-600 mb-3">{t('service.imp_file_hint', 'CSV or Excel (.xlsx) — up to 10,000 rows / 10MB')}</p>
            <input ref={fileRef} type="file" accept=".csv,.xlsx" className="hidden"
              onChange={(e) => upload(e.target.files?.[0])} data-testid="import-file-input" />
            <button onClick={() => fileRef.current?.click()} disabled={busy}
              className="inline-flex items-center gap-2 bg-orange-500 hover:bg-orange-600 disabled:opacity-60 text-white text-sm font-semibold px-5 py-2.5 rounded-lg"
              data-testid="import-choose-file">
              {busy ? <Loader2 size={15} className="animate-spin" /> : <Upload size={15} />} {t('service.imp_choose_file', 'Choose file')}
            </button>
          </div>
        </Card>
      )}

      {/* Step 2 — column mapping */}
      {step === 1 && job && (
        <Card className="p-6 space-y-4" data-testid="import-mapping-step">
          <div className="flex items-center justify-between flex-wrap gap-2">
            <div className="text-sm text-zinc-600">
              <span className="font-semibold text-zinc-900">{job.row_count.toLocaleString()}</span> {t('service.imp_rows_in', 'rows in')}{' '}
              <span className="font-mono text-xs">{job.headers.length}</span> {t('service.imp_cols_match', 'columns — match each column to a field, or ignore it.')}
            </div>
            {unmatchedCount > 0 && (
              <button onClick={askAi} disabled={aiBusy}
                className="inline-flex items-center gap-1.5 text-xs font-semibold px-3 py-1.5 rounded-lg bg-teal-50 text-teal-700 border border-teal-200 hover:bg-teal-100 disabled:opacity-60"
                data-testid="import-ai-map">
                {aiBusy ? <Loader2 size={13} className="animate-spin" /> : <Sparkles size={13} />}
                {t('service.imp_ai_map', 'Ask AI to map {{n}} unmatched', { n: unmatchedCount })}
              </button>
            )}
          </div>
          <div className="divide-y divide-zinc-100">
            {job.headers.map((h) => (
              <div key={h} className="grid grid-cols-2 gap-3 items-center py-2" data-testid={`map-row-${h}`}>
                <div className="min-w-0">
                  <div className="text-sm font-medium text-zinc-800 truncate">{h}</div>
                  <div className="text-[11px] text-zinc-400 truncate">
                    {t('service.imp_eg', 'e.g.')} {(job.sample_rows || []).map((r) => r[h]).filter(Boolean).slice(0, 2).join(' · ') || '—'}
                  </div>
                </div>
                <select value={mapping[h] || ''} onChange={(e) => setMapping({ ...mapping, [h]: e.target.value })}
                  className="px-2 py-1.5 rounded-lg border border-zinc-200 text-sm bg-white"
                  data-testid={`map-select-${h}`}>
                  <option value="">{t('service.imp_ignore', '— Ignore —')}</option>
                  {Object.entries(fields).map(([k, v]) => (
                    <option key={k} value={k} disabled={usedFields.has(k) && mapping[h] !== k}>
                      {v.label}{v.required ? ' *' : ''}
                    </option>
                  ))}
                </select>
              </div>
            ))}
          </div>
          {requiredUnmapped.length > 0 && (
            <div className="text-xs text-amber-700 bg-amber-50 border border-amber-200 rounded-lg px-3 py-2" data-testid="import-required-warning">
              {t('service.imp_required', 'Required:')} {requiredUnmapped.join(', ')}
            </div>
          )}
          <div className="flex gap-3">
            <button onClick={reset} className="inline-flex items-center gap-1.5 px-4 py-2 text-sm text-zinc-600 hover:text-zinc-900">
              <ArrowLeft size={14} /> {t('service.imp_start_over', 'Start over')}
            </button>
            <button onClick={runValidate} disabled={busy || requiredUnmapped.length > 0}
              className="inline-flex items-center gap-2 bg-orange-500 hover:bg-orange-600 disabled:opacity-60 text-white text-sm font-semibold px-5 py-2.5 rounded-lg"
              data-testid="import-validate">
              {busy ? <Loader2 size={15} className="animate-spin" /> : <>{t('service.imp_preview_import', 'Preview import')} <ArrowRight size={15} /></>}
            </button>
          </div>
        </Card>
      )}

      {/* Step 3 — preview & validate */}
      {step === 2 && validation && (
        <Card className="p-6 space-y-5" data-testid="import-preview-step">
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            <div className="rounded-xl bg-emerald-50 border border-emerald-100 p-4" data-testid="import-valid-count">
              <div className="text-2xl font-bold text-emerald-700 tabular-nums">{validation.valid_count.toLocaleString()}</div>
              <div className="text-xs text-emerald-700/80">{t('service.imp_ready', 'Ready to import')}</div>
            </div>
            <div className="rounded-xl bg-amber-50 border border-amber-100 p-4" data-testid="import-dupe-count">
              <div className="text-2xl font-bold text-amber-700 tabular-nums">{validation.duplicate_count.toLocaleString()}</div>
              <div className="text-xs text-amber-700/80">{t('service.imp_possible_dupes', 'Possible duplicates')}</div>
            </div>
            <div className="rounded-xl bg-red-50 border border-red-100 p-4" data-testid="import-error-count">
              <div className="text-2xl font-bold text-red-700 tabular-nums">{validation.error_count.toLocaleString()}</div>
              <div className="text-xs text-red-700/80">{t('service.imp_rows_errors', 'Rows with errors')}</div>
            </div>
          </div>

          {validation.duplicate_count > 0 && (
            <div className="flex items-center gap-4 text-sm" data-testid="import-dupe-strategy">
              <span className="text-zinc-600 font-medium">{t('service.imp_duplicates', 'Duplicates:')}</span>
              {[['skip', importType === 'cases' ? t('service.imp_skip_ref', 'Skip (matched by reference)') : t('service.imp_skip_existing', 'Skip existing')],
                ...(importType === 'customers' ? [['update', t('service.imp_update_existing', 'Update existing')]] : [])].map(([v, label]) => (
                <label key={v} className="inline-flex items-center gap-1.5 cursor-pointer">
                  <input type="radio" name="dupe" checked={strategy === v} onChange={() => setStrategy(v)}
                    data-testid={`dupe-strategy-${v}`} />
                  <span className="text-zinc-700">{label}</span>
                </label>
              ))}
            </div>
          )}

          {validation.errors.length > 0 && (
            <div className="space-y-1.5" data-testid="import-errors-list">
              <div className="flex items-center gap-1.5 text-xs font-semibold text-red-700">
                <AlertTriangle size={13} /> {t('service.imp_first_errors', 'First {{n}} errors (these rows will be skipped)', { n: Math.min(validation.errors.length, 50) })}
              </div>
              <div className="max-h-40 overflow-y-auto rounded-lg border border-zinc-100 divide-y divide-zinc-50 text-xs">
                {validation.errors.map((e, i) => (
                  <div key={i} className="px-3 py-1.5 flex gap-3">
                    <span className="text-zinc-400 shrink-0">{t('service.imp_row', 'Row {{n}}', { n: e.row })}</span>
                    <span className="text-zinc-700">{e.reason}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {validation.preview.length > 0 && (
            <div className="overflow-x-auto rounded-lg border border-zinc-100" data-testid="import-preview-table">
              <table className="w-full text-xs">
                <thead className="bg-zinc-50 text-zinc-500">
                  <tr>{Object.keys(validation.preview[0]).map((k) => (
                    <th key={k} className="text-left px-3 py-2 font-semibold whitespace-nowrap">{fields[k]?.label || k}</th>
                  ))}</tr>
                </thead>
                <tbody className="divide-y divide-zinc-50">
                  {validation.preview.map((r, i) => (
                    <tr key={i}>{Object.keys(validation.preview[0]).map((k) => (
                      <td key={k} className="px-3 py-1.5 text-zinc-700 whitespace-nowrap max-w-[180px] truncate">{r[k] || '—'}</td>
                    ))}</tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          <div className="flex gap-3">
            <button onClick={() => setStep(1)} className="inline-flex items-center gap-1.5 px-4 py-2 text-sm text-zinc-600 hover:text-zinc-900">
              <ArrowLeft size={14} /> {t('service.imp_back_mapping', 'Back to mapping')}
            </button>
            <button onClick={runCommit} disabled={busy || validation.valid_count === 0}
              className="inline-flex items-center gap-2 bg-emerald-600 hover:bg-emerald-700 disabled:opacity-60 text-white text-sm font-semibold px-5 py-2.5 rounded-lg"
              data-testid="import-commit">
              {busy ? <Loader2 size={15} className="animate-spin" /> : <>{t('service.imp_import_n', 'Import {{n}} rows', { n: validation.valid_count.toLocaleString() })} <ArrowRight size={15} /></>}
            </button>
          </div>
        </Card>
      )}

      {/* Step 4 — done */}
      {step === 3 && result && (
        <Card className="p-6 space-y-5" data-testid="import-done-step">
          <div className="flex items-center gap-2 text-emerald-700">
            <CheckCircle2 size={20} />
            <div className="text-lg font-semibold">{t('service.imp_complete', 'Import complete')}</div>
          </div>
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
            {[[t('service.imp_created', 'Created'), result.created, 'text-emerald-700', 'import-result-created'],
              [t('service.imp_updated', 'Updated'), result.updated, 'text-sky-700', 'import-result-updated'],
              [t('service.imp_skipped', 'Skipped'), result.skipped, 'text-zinc-600', 'import-result-skipped'],
              [t('service.imp_errored', 'Errored'), result.errored, 'text-red-700', 'import-result-errored']].map(([label, v, tone, tid]) => (
              <div key={tid} className="rounded-xl border border-zinc-100 p-4" data-testid={tid}>
                <div className={`text-2xl font-bold tabular-nums ${tone}`}>{Number(v).toLocaleString()}</div>
                <div className="text-xs text-zinc-500">{label}</div>
              </div>
            ))}
          </div>
          <div className="flex gap-3 flex-wrap">
            {result.errored > 0 && (
              <button onClick={downloadErrors}
                className="inline-flex items-center gap-2 border border-zinc-200 hover:bg-zinc-50 text-zinc-700 text-sm font-semibold px-4 py-2 rounded-lg"
                data-testid="import-download-errors">
                <Download size={14} /> {t('service.imp_download_errors', 'Download errored rows (CSV)')}
              </button>
            )}
            <button onClick={reset}
              className="inline-flex items-center gap-2 bg-orange-500 hover:bg-orange-600 text-white text-sm font-semibold px-4 py-2 rounded-lg"
              data-testid="import-another">
              <RotateCcw size={14} /> {t('service.imp_another', 'Import another file')}
            </button>
          </div>
        </Card>
      )}
    </div>
  );
}

/**
 * Service Desk — Integrations (self-serve Orbit 4 connection).
 *
 * Lets a Service Desk admin connect their OWN Orbit 4 account: paste the API
 * token + webhook secret, copy a unique webhook URL into Orbit 4, and toggle
 * the connection live. Inbound Orbit 4 tickets then land as Service Desk
 * cases automatically — no Pulse Fitness admin involvement required.
 */
import { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { Badge } from '@/components/ui/badge';
import {
  Plug, Copy, Check, RefreshCw, Loader2, Zap, ListChecks,
  ExternalLink, Users, Rocket,
} from 'lucide-react';
import Orbit4Wizard from './Orbit4Wizard';

const BACKEND = process.env.REACT_APP_BACKEND_URL || '';

export default function DeskIntegrations() {
  const { t } = useTranslation();
  const [conn, setConn] = useState(null);
  const [activity, setActivity] = useState(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [testing, setTesting] = useState(false);
  const [copied, setCopied] = useState(false);
  const [apiToken, setApiToken] = useState('');
  const [webhookSecret, setWebhookSecret] = useState('');
  const [webBaseUrl, setWebBaseUrl] = useState('');
  const [engineers, setEngineers] = useState([]);
  const [o4Users, setO4Users] = useState([]);
  const [wizardOpen, setWizardOpen] = useState(false);
  const [autoPrompted, setAutoPrompted] = useState(false);

  const fullWebhookUrl = conn?.webhook_path ? `${BACKEND}${conn.webhook_path}` : (conn?.webhook_url || '');

  const load = async () => {
    setLoading(true);
    try {
      const [c, a, e] = await Promise.all([
        api.get('/svc/orbit4/connection'),
        api.get('/svc/orbit4/connection/activity').catch(() => ({ data: null })),
        api.get('/svc/orbit4/engineers').catch(() => ({ data: null })),
      ]);
      setConn(c.data);
      setActivity(a.data);
      setWebBaseUrl(c.data?.web_base_url || '');
      setEngineers(e.data?.engineers || []);
      setO4Users(e.data?.orbit4_users || []);
      // Auto-launch the onboarding wizard once for a brand-new connection.
      if (!autoPrompted && !c.data?.api_token && !c.data?.enabled) {
        setAutoPrompted(true);
        setWizardOpen(true);
      }
    } catch (e) {
      toast.error(t('service.o4_load_err', 'Could not load the Orbit 4 connection'));
    } finally {
      setLoading(false);
    }
  };

  const mapEngineer = async (engineerId, orbit4UserId) => {
    try {
      await api.put(`/svc/orbit4/engineers/${engineerId}`, { orbit4_user_id: orbit4UserId || null });
      setEngineers((prev) => prev.map((x) => x.id === engineerId
        ? { ...x, orbit4_user_id: orbit4UserId ? Number(orbit4UserId) : null } : x));
      toast.success(t('service.o4_mapping_updated', 'Engineer mapping updated'));
    } catch {
      toast.error(t('service.o4_mapping_err', 'Could not update mapping'));
    }
  };

  useEffect(() => { load(); }, []);

  const save = async (patch) => {
    setSaving(true);
    try {
      const r = await api.put('/svc/orbit4/connection', patch);
      setConn(r.data);
      return r.data;
    } catch (e) {
      toast.error(t('service.o4_save_failed', 'Save failed'));
      throw e;
    } finally {
      setSaving(false);
    }
  };

  const handleToggle = async (next) => {
    if (next && !conn?.api_token && !apiToken) {
      // allow enabling for inbound-only, but warn outbound needs a token
    }
    await save({ enabled: next });
    toast.success(next ? t('service.o4_now_live', 'Orbit 4 connection is live') : t('service.o4_now_paused', 'Orbit 4 connection paused'));
  };

  const handleSaveCreds = async () => {
    const patch = { web_base_url: webBaseUrl };
    if (apiToken) patch.api_token = apiToken;
    if (webhookSecret) patch.webhook_secret = webhookSecret;
    await save(patch);
    setApiToken('');
    setWebhookSecret('');
    toast.success(t('service.o4_settings_saved', 'Settings saved'));
  };

  const handleRotate = async () => {
    setSaving(true);
    try {
      const r = await api.post('/svc/orbit4/connection/rotate-key');
      setConn(r.data);
      toast.success(t('service.o4_url_regenerated', 'Webhook URL regenerated — update it in Orbit 4'));
    } catch {
      toast.error(t('service.o4_rotate_err', 'Could not rotate the key'));
    } finally {
      setSaving(false);
    }
  };

  const handleTest = async () => {
    setTesting(true);
    try {
      const r = await api.post('/svc/orbit4/connection/test');
      if (r.data.ok) toast.success(r.data.message || t('service.o4_connected', 'Connected'));
      else toast.error(r.data.message || t('service.o4_could_not_connect', 'Could not connect'));
    } catch {
      toast.error(t('service.o4_test_failed', 'Test failed'));
    } finally {
      setTesting(false);
    }
  };

  const copyUrl = () => {
    navigator.clipboard.writeText(fullWebhookUrl);
    setCopied(true);
    setTimeout(() => setCopied(false), 1800);
    toast.success(t('service.o4_url_copied', 'Webhook URL copied'));
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-20 text-slate-500 text-sm" data-testid="desk-integrations-loading">
        <Loader2 size={16} className="mr-2 animate-spin" /> {t('service.o4_loading', 'Loading…')}
      </div>
    );
  }

  return (
    <div className="space-y-6 max-w-3xl" data-testid="desk-integrations">
      <Orbit4Wizard
        open={wizardOpen}
        onClose={() => setWizardOpen(false)}
        conn={conn}
        onConnUpdate={(c) => setConn(c)}
        onFinished={load}
      />
      <div className="flex items-start justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 flex items-center gap-2">
            <Plug size={22} className="text-indigo-600" /> {t('service.o4_title', 'Integrations')}
          </h1>
          <p className="text-sm text-slate-500 mt-1">
            {t('service.o4_subtitle', 'Connect Orbit 4 so faults logged by your customers flow straight into your Service Desk.')}
          </p>
        </div>
        <Button onClick={() => setWizardOpen(true)} data-testid="orbit4-launch-wizard-btn">
          <Rocket size={15} className="mr-2" /> {t('service.o4_setup_wizard', 'Setup wizard')}
        </Button>
      </div>

      {/* Connection status card */}
      <Card data-testid="orbit4-connection-card">
        <CardHeader className="flex flex-row items-center justify-between space-y-0">
          <CardTitle className="text-base flex items-center gap-2">
            Orbit 4
            {conn?.enabled
              ? <Badge className="bg-emerald-100 text-emerald-700 hover:bg-emerald-100" data-testid="orbit4-status-live">{t('service.o4_live', 'Live')}</Badge>
              : <Badge variant="secondary" data-testid="orbit4-status-paused">{t('service.o4_paused', 'Paused')}</Badge>}
          </CardTitle>
          <div className="flex items-center gap-2">
            <Label htmlFor="orbit4-enabled" className="text-sm text-slate-600">{t('service.o4_enabled', 'Enabled')}</Label>
            <Switch
              id="orbit4-enabled"
              checked={!!conn?.enabled}
              onCheckedChange={handleToggle}
              disabled={saving}
              data-testid="orbit4-enable-toggle"
            />
          </div>
        </CardHeader>
        <CardContent className="space-y-5">
          {/* Webhook URL */}
          <div>
            <Label className="text-sm font-medium text-slate-700">{t('service.o4_step1', '1. Your unique webhook URL')}</Label>
            <p className="text-xs text-slate-500 mb-2">
              {t('service.o4_step1_hint', 'Paste this into Orbit 4 → Settings → Webhooks. Orbit 4 will POST ticket, note, photo and asset events here.')}
            </p>
            <div className="flex items-center gap-2">
              <code className="flex-1 text-xs bg-slate-50 border border-slate-200 rounded px-3 py-2 break-all" data-testid="orbit4-webhook-url">
                {fullWebhookUrl}
              </code>
              <Button variant="outline" size="sm" onClick={copyUrl} data-testid="orbit4-copy-url-btn">
                {copied ? <Check size={14} className="text-emerald-600" /> : <Copy size={14} />}
              </Button>
              <Button variant="ghost" size="sm" onClick={handleRotate} disabled={saving} title={t('service.o4_regen_url', 'Regenerate URL')} data-testid="orbit4-rotate-key-btn">
                <RefreshCw size={14} />
              </Button>
            </div>
          </div>

          {/* Credentials */}
          <div className="grid sm:grid-cols-2 gap-4">
            <div>
              <Label htmlFor="orbit4-secret" className="text-sm font-medium text-slate-700">{t('service.o4_step2', '2. Webhook secret')}</Label>
              <p className="text-xs text-slate-500 mb-2">{t('service.o4_step2_hint', 'Optional. If set, we verify the signature on every webhook.')}</p>
              <Input
                id="orbit4-secret"
                type="password"
                placeholder={conn?.webhook_secret ? t('service.o4_set', '•••••• (set)') : t('service.o4_paste_secret', 'Paste secret')}
                value={webhookSecret}
                onChange={(e) => setWebhookSecret(e.target.value)}
                data-testid="orbit4-webhook-secret-input"
              />
            </div>
            <div>
              <Label htmlFor="orbit4-token" className="text-sm font-medium text-slate-700">{t('service.o4_step3', '3. API token')}</Label>
              <p className="text-xs text-slate-500 mb-2">{t('service.o4_step3_hint', 'Lets us push case progress (status, notes, photos) back to Orbit 4.')}</p>
              <Input
                id="orbit4-token"
                type="password"
                placeholder={conn?.api_token ? t('service.o4_set', '•••••• (set)') : t('service.o4_paste_token', 'Paste API token')}
                value={apiToken}
                onChange={(e) => setApiToken(e.target.value)}
                data-testid="orbit4-api-token-input"
              />
            </div>
          </div>

          <div>
            <Label htmlFor="orbit4-web-url" className="text-sm font-medium text-slate-700">{t('service.o4_step4', '4. Orbit 4 ticket URL (optional)')}</Label>
            <p className="text-xs text-slate-500 mb-2">{t('service.o4_step4_hint', 'Base URL for "View in Orbit 4" links on cases, e.g. https://app.orbit4.org/tickets — we append the ticket id.')}</p>
            <Input
              id="orbit4-web-url"
              placeholder="https://app.orbit4.org/tickets"
              value={webBaseUrl}
              onChange={(e) => setWebBaseUrl(e.target.value)}
              data-testid="orbit4-web-url-input"
            />
          </div>

          <div className="flex items-center gap-2">
            <Button onClick={handleSaveCreds} disabled={saving} data-testid="orbit4-save-creds-btn">
              {saving ? <Loader2 size={14} className="mr-2 animate-spin" /> : null}
              {t('service.o4_save_settings', 'Save settings')}
            </Button>
            <Button variant="outline" onClick={handleTest} disabled={testing} data-testid="orbit4-test-btn">
              {testing ? <Loader2 size={14} className="mr-2 animate-spin" /> : <Zap size={14} className="mr-2" />}
              {t('service.o4_test_connection', 'Test connection')}
            </Button>
          </div>

          <div className="text-xs text-slate-400 flex items-center gap-1">
            <ExternalLink size={12} />
            {t('service.o4_last_event', 'Last event:')} {conn?.last_event_at ? new Date(conn.last_event_at).toLocaleString() : t('service.o4_none_yet', 'none yet')} · {t('service.o4_total', '{{n}} total', { n: conn?.stats?.events_total || 0 })}
          </div>
        </CardContent>
      </Card>

      {/* Connection health strip */}
      <Card data-testid="orbit4-health-strip">
        <CardContent className="py-4">
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
            <div className="rounded-lg bg-slate-50 px-3 py-2">
              <div className="text-[11px] uppercase tracking-wide text-slate-400">{t('service.o4_status', 'Status')}</div>
              <div className={`text-sm font-semibold ${activity?.enabled ? 'text-emerald-600' : 'text-slate-500'}`} data-testid="health-status">
                {activity?.enabled ? t('service.o4_live', 'Live') : t('service.o4_paused', 'Paused')}
              </div>
            </div>
            <div className="rounded-lg bg-slate-50 px-3 py-2">
              <div className="text-[11px] uppercase tracking-wide text-slate-400">{t('service.o4_last_inbound', 'Last inbound')}</div>
              <div className="text-sm font-semibold text-slate-700" data-testid="health-last-inbound">
                {activity?.last_inbound_at ? new Date(activity.last_inbound_at).toLocaleString() : '—'}
              </div>
            </div>
            <div className="rounded-lg bg-slate-50 px-3 py-2">
              <div className="text-[11px] uppercase tracking-wide text-slate-400">{t('service.o4_last_sync_out', 'Last sync out')}</div>
              <div className={`text-sm font-semibold ${activity?.last_outbound?.status === 'error' ? 'text-red-600' : 'text-slate-700'}`} data-testid="health-last-outbound">
                {activity?.last_outbound?.at
                  ? `${activity.last_outbound.status === 'error' ? '⚠ ' : '✓ '}${new Date(activity.last_outbound.at).toLocaleString()}`
                  : '—'}
              </div>
            </div>
            <div className="rounded-lg bg-slate-50 px-3 py-2">
              <div className="text-[11px] uppercase tracking-wide text-slate-400">{t('service.o4_cases_week', 'Cases this week')}</div>
              <div className="text-sm font-semibold text-slate-700" data-testid="health-cases-week">
                {activity?.cases_this_week ?? 0}
                {activity?.error_count > 0 && (
                  <span className="text-red-600 text-xs ml-2" data-testid="health-errors">{t('service.o4_sync_errors', '{{n}} sync error(s)', { n: activity.error_count })}</span>
                )}
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Activity */}
      <Card data-testid="orbit4-activity-card">
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <ListChecks size={18} className="text-slate-500" /> {t('service.o4_cases_from', 'Cases from Orbit 4')}
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-center gap-6 mb-4">
            <div>
              <div className="text-2xl font-bold text-slate-900" data-testid="orbit4-cases-total">{activity?.cases_total ?? 0}</div>
              <div className="text-xs text-slate-500">{t('service.o4_total_cases_created', 'Total cases created')}</div>
            </div>
          </div>
          {activity?.recent_cases?.length ? (
            <div className="divide-y divide-slate-100 border border-slate-200 rounded-lg overflow-hidden">
              {activity.recent_cases.map((c) => (
