              <h2 className="text-xl font-semibold text-zinc-900" data-testid="pc-detail-name">{c.name}</h2>
              <div className="text-sm text-zinc-500 mt-0.5">
                {[c.email, c.phone].filter(Boolean).join(' · ') || 'No contact details'}
