          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-zinc-50 text-zinc-500 text-xs">
                <tr>
                  {['Name', 'Contact', 'Site', 'Postcode', 'Added'].map((h) => (
                    <th key={h} className="text-left px-4 py-2 font-semibold whitespace-nowrap">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-zinc-50">
                {rows.map((c) => (
                  <tr key={c.id} onClick={() => openDetail(c.id)}
                    className="hover:bg-orange-50/40 cursor-pointer transition-colors"
                    data-testid={`pc-row-${c.id}`}>
                    <td className="px-4 py-2.5 font-medium text-zinc-900 whitespace-nowrap">{c.name}</td>
                    <td className="px-4 py-2.5 text-zinc-600 whitespace-nowrap">{c.email || c.phone || '—'}</td>
                    <td className="px-4 py-2.5 text-zinc-600 whitespace-nowrap">{c.site_name || '—'}</td>
                    <td className="px-4 py-2.5 text-zinc-600 whitespace-nowrap">{c.postcode || '—'}</td>
                    <td className="px-4 py-2.5 text-zinc-400 text-xs whitespace-nowrap">{(c.created_at || '').slice(0, 10)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </Card>
      )}
    </div>
  );
}

/**
 * Orbit 4 onboarding wizard — one screen, four guided steps for a new
 * service provider:
 *   1. Paste API token (+ optional ticket URL)  →  auto-test
 *   2. Generate / copy the webhook secret + unique URL, paste into Orbit 4
 *   3. Go live + wait for the first ticket to arrive (polled)
 *   4. Done — jump to the first case
 * Uses the existing /svc/orbit4 endpoints; no new backend required.
 */
import { useState, useEffect, useRef } from 'react';
import { api } from '@/lib/api';
import { toast } from 'sonner';
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Check, Copy, Loader2, Zap, KeyRound, Webhook, Rocket, PartyPopper,
  ArrowRight, RefreshCw, AlertTriangle,
} from 'lucide-react';

const BACKEND = process.env.REACT_APP_BACKEND_URL || '';
const STEPS = ['Connect', 'Webhook', 'Go live', 'Done'];

function randomSecret() {
  const a = new Uint8Array(24);
  (window.crypto || {}).getRandomValues?.(a);
  return btoa(String.fromCharCode(...a)).replace(/[^a-zA-Z0-9]/g, '').slice(0, 28);
}

function CopyField({ value, testid }) {
  const [done, setDone] = useState(false);
  return (
    <div className="flex items-center gap-2">
      <code className="flex-1 text-xs bg-slate-50 border border-slate-200 rounded px-3 py-2 break-all" data-testid={testid}>{value}</code>
      <Button variant="outline" size="sm" onClick={() => { navigator.clipboard.writeText(value); setDone(true); setTimeout(() => setDone(false), 1600); toast.success('Copied'); }} data-testid={`${testid}-copy`}>
        {done ? <Check size={14} className="text-emerald-600" /> : <Copy size={14} />}
      </Button>
    </div>
  );
}

export default function Orbit4Wizard({ open, onClose, conn, onConnUpdate, onFinished }) {
  const [step, setStep] = useState(0);
  const [apiToken, setApiToken] = useState('');
  const [webUrl, setWebUrl] = useState(conn?.web_base_url || '');
  const [secret, setSecret] = useState('');
  const [busy, setBusy] = useState(false);
  const [testResult, setTestResult] = useState(null);
  const [casesTotal, setCasesTotal] = useState(0);
  const [firstCase, setFirstCase] = useState(null);
  const pollRef = useRef(null);

  const webhookUrl = conn?.webhook_path ? `${BACKEND}${conn.webhook_path}` : (conn?.webhook_url || '');

  useEffect(() => {
    if (open) {
      setStep(0); setApiToken(''); setSecret(''); setTestResult(null);
      setWebUrl(conn?.web_base_url || '');
    }
    return () => { if (pollRef.current) clearInterval(pollRef.current); };
  }, [open]); // eslint-disable-line

  // Poll for the first ticket while on the "Go live" step.
  useEffect(() => {
    if (step !== 2) { if (pollRef.current) clearInterval(pollRef.current); return; }
    const tick = async () => {
      try {
        const r = await api.get('/svc/orbit4/connection/activity');
        setCasesTotal(r.data?.cases_total || 0);
        if ((r.data?.cases_total || 0) > 0) {
          setFirstCase(r.data.recent_cases?.[0] || null);
          clearInterval(pollRef.current);
          setStep(3);
          toast.success('First Orbit 4 ticket received!');
        }
      } catch { /* keep polling */ }
    };
    tick();
    pollRef.current = setInterval(tick, 4000);
    return () => { if (pollRef.current) clearInterval(pollRef.current); };
  }, [step]);

  const saveAndTest = async () => {
    setBusy(true);
    try {
      const patch = { web_base_url: webUrl };
      if (apiToken) patch.api_token = apiToken;
      const r = await api.put('/svc/orbit4/connection', patch);
      onConnUpdate?.(r.data);
      const t = await api.post('/svc/orbit4/connection/test');
      setTestResult(t.data);
      setStep(1);
    } catch {
      toast.error('Could not save the connection');
    } finally {
      setBusy(false);
    }
  };

  const generateSecret = async () => {
    const s = randomSecret();
    setBusy(true);
    try {
      const r = await api.put('/svc/orbit4/connection', { webhook_secret: s });
      onConnUpdate?.(r.data);
      setSecret(s);
      toast.success('Secret generated — copy it into Orbit 4');
    } catch {
      toast.error('Could not save the secret');
    } finally {
      setBusy(false);
    }
  };

  const goLive = async () => {
    setBusy(true);
    try {
      const r = await api.put('/svc/orbit4/connection', { enabled: true });
      onConnUpdate?.(r.data);
      setStep(2);
      toast.success('Connection is live — waiting for your first ticket');
    } catch {
      toast.error('Could not enable the connection');
    } finally {
      setBusy(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={(o) => { if (!o) onClose?.(); }}>
      <DialogContent className="max-w-xl" data-testid="orbit4-wizard">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Rocket size={18} className="text-indigo-600" /> Connect Orbit 4
          </DialogTitle>
          <DialogDescription>
            Link your Orbit 4 account so customer faults flow into your Service Desk.
          </DialogDescription>
        </DialogHeader>

        {/* Stepper */}
        <div className="flex items-center gap-2 mb-2" data-testid="orbit4-wizard-steps">
          {STEPS.map((s, i) => (
            <div key={s} className="flex items-center gap-2 flex-1">
              <div className={`h-7 w-7 rounded-full flex items-center justify-center text-xs font-bold shrink-0 ${i < step ? 'bg-emerald-500 text-white' : i === step ? 'bg-indigo-600 text-white' : 'bg-slate-200 text-slate-500'}`}>
                {i < step ? <Check size={14} /> : i + 1}
              </div>
              <span className={`text-xs ${i === step ? 'text-slate-900 font-semibold' : 'text-slate-400'}`}>{s}</span>
              {i < STEPS.length - 1 && <div className="h-px flex-1 bg-slate-200" />}
            </div>
          ))}
        </div>

        {/* Step 0 — Connect */}
        {step === 0 && (
          <div className="space-y-4" data-testid="orbit4-wizard-step-connect">
            <p className="text-sm text-slate-600">Paste your Orbit 4 API token. This lets us push case progress back to Orbit 4 and verify the connection.</p>
            <div>
              <Label htmlFor="wiz-token" className="text-sm font-medium flex items-center gap-1"><KeyRound size={14} /> Orbit 4 API token</Label>
              <Input id="wiz-token" type="password" placeholder={conn?.api_token ? '•••••• (already set)' : 'Paste API token'} value={apiToken} onChange={(e) => setApiToken(e.target.value)} className="mt-1" data-testid="orbit4-wizard-token-input" />
            </div>
            <div>
              <Label htmlFor="wiz-url" className="text-sm font-medium">Orbit 4 ticket URL (optional)</Label>
              <Input id="wiz-url" placeholder="https://app.orbit4.org/tickets" value={webUrl} onChange={(e) => setWebUrl(e.target.value)} className="mt-1" data-testid="orbit4-wizard-weburl-input" />
              <p className="text-xs text-slate-400 mt-1">Used for "View in Orbit 4" links on cases.</p>
            </div>
            <div className="flex justify-end">
              <Button onClick={saveAndTest} disabled={busy} data-testid="orbit4-wizard-connect-btn">
                {busy ? <Loader2 size={14} className="mr-2 animate-spin" /> : <Zap size={14} className="mr-2" />}
                Save & test
              </Button>
            </div>
          </div>
        )}

        {/* Step 1 — Webhook */}
        {step === 1 && (
          <div className="space-y-4" data-testid="orbit4-wizard-step-webhook">
            {testResult && (
              <div className={`text-sm rounded-lg px-3 py-2 flex items-center gap-2 ${testResult.ok ? 'bg-emerald-50 text-emerald-700' : 'bg-amber-50 text-amber-700'}`} data-testid="orbit4-wizard-test-result">
                {testResult.ok ? <Check size={15} /> : <AlertTriangle size={15} />}
                {testResult.ok ? 'Connected to Orbit 4.' : (testResult.message || 'Could not verify outbound — you can still receive tickets.')}
              </div>
            )}
            <p className="text-sm text-slate-600 flex items-center gap-1"><Webhook size={14} /> In Orbit 4 → Settings → Webhooks, add this endpoint:</p>
            <div>
              <Label className="text-xs text-slate-500">Webhook URL</Label>
              <CopyField value={webhookUrl} testid="orbit4-wizard-webhook-url" />
            </div>
            <div>
              <Label className="text-xs text-slate-500">Webhook secret</Label>
              {secret ? (
                <CopyField value={secret} testid="orbit4-wizard-secret" />
              ) : (
                <Button variant="outline" size="sm" onClick={generateSecret} disabled={busy} className="mt-1" data-testid="orbit4-wizard-gen-secret-btn">
                  {busy ? <Loader2 size={14} className="mr-2 animate-spin" /> : <RefreshCw size={14} className="mr-2" />}
                  Generate a secret to paste into Orbit 4
                </Button>
              )}
            </div>
            <div className="flex justify-between">
              <Button variant="ghost" onClick={() => setStep(0)}>Back</Button>
              <Button onClick={goLive} disabled={busy} data-testid="orbit4-wizard-golive-btn">
                {busy ? <Loader2 size={14} className="mr-2 animate-spin" /> : null}
                I've added it — go live <ArrowRight size={14} className="ml-2" />
              </Button>
            </div>
          </div>
        )}

        {/* Step 2 — Waiting for first ticket */}
        {step === 2 && (
          <div className="space-y-4 text-center py-4" data-testid="orbit4-wizard-step-waiting">
            <Loader2 size={32} className="animate-spin text-indigo-600 mx-auto" />
            <p className="text-sm font-medium text-slate-800">Connection is live — waiting for your first ticket…</p>
            <p className="text-sm text-slate-500">Log a test fault in Orbit 4 for one of your customers. It'll appear here as a Service Desk case within seconds.</p>
            <p className="text-xs text-slate-400">Cases received so far: {casesTotal}</p>
            <Button variant="ghost" size="sm" onClick={() => onClose?.()}>Close — I'll check later</Button>
          </div>
        )}

        {/* Step 3 — Done */}
        {step === 3 && (
          <div className="space-y-4 text-center py-4" data-testid="orbit4-wizard-step-done">
            <PartyPopper size={32} className="text-emerald-500 mx-auto" />
            <p className="text-base font-semibold text-slate-900">You're connected!</p>
            {firstCase && (
              <p className="text-sm text-slate-600">First case created: <span className="font-medium">{firstCase.reference}</span> — {firstCase.title}</p>
            )}
            <p className="text-sm text-slate-500">Orbit 4 tickets now flow straight into your Service Desk, and case progress flows back automatically.</p>
            <Button onClick={() => { onFinished?.(); onClose?.(); }} data-testid="orbit4-wizard-finish-btn">Done</Button>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

/**
 * PPM visit detail — opens when a calendar shell is clicked.
 * Shows the site, every machine involved, and (once the job is completed) the
 * engineer's workings. Offers Allocate / Delete actions.
 */
import { useEffect, useState } from 'react';
import { Loader2, X, MapPin, Wrench, CheckCircle2, Trash2, CalendarClock, User, Printer } from 'lucide-react';
import { api } from '@/lib/api';
import { notify } from '@/components/notifications';
import { EngineerReportView } from '@/components/shared/EngineerReportView';
import { BookFollowUpButton } from '@/components/shared/BookFollowUpButton';
import { Button } from '@/components/ui/button';

const fmtDate = (d) => (d ? new Date(d).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }) : '—');

// Classify a calibration reading as 'speed' or 'incline' (explicit type → label → unit).
const axisOf = (r) => {
  const t = String(r?.type || '').toLowerCase();
  if (t === 'speed' || t === 'incline') return t;
  const l = String(r?.label || '').toLowerCase();
  const u = String(r?.unit || '').toLowerCase();
  if (l.includes('incline') || u === '%') return 'incline';
  return 'speed';
};
// Human-friendly set-point label (strip "Speed — "/"Incline — " prefix; fall back to target+unit).
const humanizeReading = (r) => {
  let lbl = String(r?.label || '').replace(/^(speed|incline)\s*[—–-]\s*/i, '').trim();
  if (!lbl) lbl = r?.target ? `${r.target}${r.unit ? ` ${r.unit}` : ''}` : '';
  return lbl || '—';
};

const MW_COLS = '<colgroup><col style="width:30%"/><col style="width:15%"/><col style="width:17%"/><col style="width:10%"/><col style="width:10%"/><col style="width:18%"/></colgroup>';

function buildReportHtml(data) {
  const s = data?.schedule || {};
  const machines = data?.machines || [];
  const visits = data?.visits || [];
  const esc = (x) => String(x ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
  const yn = (b) => (b ? '✓' : '—');
  const dt = (d) => (d ? new Date(d).toLocaleString('en-GB', { dateStyle: 'medium', timeStyle: 'short' }) : '—');
  const reportHtml = (r) => {
    const parts = (r.further_parts_required || []).map((p) => `${p.qty} × ${esc(p.name)}${p.sku ? ` (${esc(p.sku)})` : ''}`).join('<br/>') || 'None';
    const row = (k, v) => `<tr><th style="width:32%">${k}</th><td style="white-space:pre-wrap">${v}</td></tr>`;
    return `<h4>Engineer report</h4><table class="rt fx">${row('Start time', esc(dt(r.start_time)))}${row('End time', esc(dt(r.end_time)))}${row('Description of Work Completed', esc(r.work_completed || '—'))}${row('Further Work Required', esc(r.further_work_required || 'None'))}${row('Further Parts Required', parts)}</table>`;
  };
  const sigHtml = (sg) => {
    if (!sg) return '';
    if (sg.unavailable) return `<p class="meta">Customer unable to sign — ${esc(sg.unavailable_reason)}</p>`;
    return `<h4>Customer sign-off</h4>${sg.image_data ? `<img src="${sg.image_data}" alt="Signature" style="max-height:70px;border:1px solid #ddd;padding:3px"/>` : ''}<p class="meta">Signed by ${esc(sg.signed_by_name || 'Customer')}${sg.signed_at ? ` · ${esc(dt(sg.signed_at))}` : ''}</p>`;
  };
  const calibHtml = (readings) => {
    const sp = readings.filter((r) => axisOf(r) === 'speed');
    const inc = readings.filter((r) => axisOf(r) === 'incline');
    const sect = (title, rows) => (rows.length ? `<div class="cal"><div class="calh">${title}</div><table class="rt fx"><colgroup><col style="width:45%"/><col style="width:35%"/><col style="width:20%"/></colgroup><tr><th>Set point</th><th>Measured</th><th>Result</th></tr>${rows.map((r) => `<tr><td>${esc(humanizeReading(r))}</td><td>${esc(r.measured || '—')}</td><td class="${r.result === 'fail' ? 'fail' : 'pass'}">${esc((r.result || 'pass').toUpperCase())}</td></tr>`).join('')}</table></div>` : '');
    return sect('Speed (mph)', sp) + sect('Incline (%)', inc);
  };
  const workedKeys = new Set(visits.flatMap((v) => (v.machine_work || []).flatMap((m) => [m.asset_serial, m.asset_name].filter(Boolean).map((x) => String(x).toLowerCase()))));
  const unworked = machines.filter((m) => ![m.serial_number, m.name].filter(Boolean).some((x) => workedKeys.has(String(x).toLowerCase())));
  const visitsHtml = visits.map((v, vi) => {
    const cm = (v.calibration?.machines || []).filter((m) => (m.readings || []).length);
    const flat = v.calibration?.readings || [];
    const extra = vi === 0 ? unworked.map((m) => `<tr><td>${esc(m.name)}</td><td>${esc(m.equipment_type || '')}</td><td>${esc(m.serial_number || '')}</td><td>—</td><td>—</td><td>Not serviced</td></tr>`).join('') : '';
    const mw = (v.machine_work || []).map((m) => `<tr><td>${esc(m.asset_name)}</td><td>${esc(m.asset_type || '')}</td><td>${esc(m.asset_serial || '')}</td><td>${yn(m.serviced)}</td><td>${yn(m.cleaned)}</td><td>${esc(m.notes || '')}</td></tr>`).join('') + extra;
    const calib = cm.length
      ? cm.map((m) => `<div class="cm"><div class="cmh">${esc(m.equipment_name || 'Treadmill')}${m.serial ? ` · SN ${esc(m.serial)}` : ''} — <b>${esc((m.overall_result || 'pass').toUpperCase())}</b></div>${calibHtml(m.readings || [])}</div>`).join('')
      : (flat.length ? calibHtml(flat) : '');
    return `<div class="visit">
      <h3>Visit — ${esc(fmtDate(v.scheduled_at || v.completed_at))} ${v.reference ? `(Job ${esc(v.reference)})` : ''}</h3>
      <p class="meta">Engineer: ${esc(v.engineer || '—')} · Status: ${esc(v.status || '—')}${v.completed_at ? ` · Completed ${esc(fmtDate(v.completed_at))}` : ''}</p>
      ${v.engineer_report ? reportHtml(v.engineer_report) : (v.summary ? `<p class="summary">${esc(v.summary)}</p>` : '')}
      ${sigHtml(v.signoff)}
      ${mw ? `<h4>Machines worked</h4><table class="rt fx">${MW_COLS}<tr><th>Machine</th><th>Type</th><th>Serial</th><th>Serviced</th><th>Cleaned</th><th>Notes</th></tr>${mw}</table>` : ''}
      ${calib ? `<h4>Treadmill calibration${v.calibration_result ? ` · ${esc(String(v.calibration_result).toUpperCase())}` : ''}</h4>${calib}` : ''}
    </div>`;
  }).join('');
  return `<!doctype html><html><head><meta charset="utf-8"><title>Service report — ${esc(s.site_name || '')}</title>
  <style>
    body{font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#111;margin:32px;font-size:12px}
    h1{font-size:20px;margin:0 0 2px} h2{font-size:13px;margin:16px 0 6px;color:#555;text-transform:uppercase;letter-spacing:.04em}
    h3{font-size:14px;margin:14px 0 2px} h4{font-size:12px;margin:10px 0 4px;color:#444}
    .sub{color:#666;margin:0 0 12px} .meta{color:#666;margin:2px 0 6px} .summary{margin:4px 0;white-space:pre-wrap}
    table.rt{border-collapse:collapse;width:100%;margin:4px 0 8px} .rt th,.rt td{border:1px solid #ddd;padding:4px 7px;text-align:left;font-size:11px}
    .rt th{background:#f5f5f5;font-weight:700} .fail{color:#b00020;font-weight:700} .pass{color:#0a7d33}
    .visit{border-top:2px solid #eee;padding-top:8px;margin-top:10px} .cal{margin:4px 0} .calh{font-weight:700;font-size:11px;color:#333;margin:4px 0 2px}
    .cm{border:1px solid #eee;border-radius:6px;padding:6px 8px;margin:6px 0} .cmh{font-weight:700;font-size:11px;margin-bottom:3px}
    .foot{margin-top:24px;color:#5B6570;font-size:9px;border-top:1px solid #C9D4E5;padding-top:8px}
    table.lh{width:100%;border-collapse:collapse;border-bottom:2px solid #0073A4;margin-bottom:10px} .lh td{vertical-align:top;padding:0 0 8px}
    .co{text-align:right;font-size:10px;color:#5B6570;line-height:1.45}
    h1.ttl{font-size:28px;margin:10px 0 10px}
    .boxes{display:grid;grid-template-columns:1fr 1fr;gap:12px;align-items:stretch}
    .bx{border:1px solid #000;padding:6px 8px;min-height:64px;line-height:1.5;box-sizing:border-box}
    table.fx{table-layout:fixed} .fx td,.fx th{overflow-wrap:anywhere}
    .ilogos{display:flex;align-items:center;gap:12px} .imod{height:50px}
    table.ref{width:100%;border-collapse:collapse;margin:10px 0 4px;border:1px solid #000;table-layout:fixed} .ref th,.ref td{padding:4px 7px;text-align:left;font-size:11px;border-bottom:1px solid #000} .ref th{font-weight:700} .ref th:not(:first-child){border-left:1px solid #000}
    .ihdr{display:flex;justify-content:space-between;align-items:center;margin:0 0 10px}
    .ilogo{height:40px} .iaddr{height:50px}
    .gen{margin-top:18px;color:#5B6570;font-size:9px}
    table.pg{width:100%;border-collapse:collapse} table.pg>thead>tr>td,table.pg>tbody>tr>td,table.pg>tfoot>tr>td{padding:0;border:0}
    .ifoot img{display:block;width:100%;margin-top:16px}
    .fspace{display:none}
    @media print{@page{size:A4;margin:8mm 0 0 0} body{margin:0 12mm}
      .fspace{display:block;height:38mm}
      .ifoot{position:fixed;left:0;right:0;bottom:0} .ifoot img{width:100%;max-width:none;margin:0}}
  </style></head><body>
  <table class="pg"><tbody><tr><td>
  <div class="ihdr"><div class="ilogos"><img class="ilogo" src="${window.location.origin}/brand/pulse-header-logo.png" alt="Pulse Fitness"/>${s.is_mod ? `<img class="imod" src="${window.location.origin}/brand/mod-badge.png" alt="Ministry of Defence"/>` : ''}</div><img class="iaddr" src="${window.location.origin}/brand/pulse-header-address.png" alt="Pulse Fitness, Part of The Pulse Group, Radnor Park, Greenfield Road, Congleton, Cheshire CW12 4TW. +44 (0)1260 294600, info@pulsefitness.com, www.pulsefitness.com"/></div>
  <h1 class="ttl">Service Report</h1>
  <div class="boxes">
    <div class="bx"><b>Customer / Site Address</b><br/>${[s.customer_name, s.site_name, s.site_address].filter(Boolean).map(esc).join('<br/>') || '—'}</div>
    <div class="bx"><b>Engineer</b><br/>${esc(visits[0]?.engineer || s.engineer || '—')}<br/>${esc(s.service_type || '')}</div>
  </div>
  <table class="ref"><tr><th>Scheduled</th><td>${esc(fmtDate(s.date))}</td><th>Service</th><td>${esc(s.service_type || '—')}</td><th>Machines</th><td>${machines.length}</td></tr>
    <tr><th>Visits</th><td>${visits.length}</td><th>Latest job</th><td>${esc(visits[0]?.reference || '—')}</td><th>Issued</th><td>${esc(new Date().toLocaleDateString('en-GB'))}</td></tr></table>
  <h2>Engineer's workings${visits.length > 1 ? ` (${visits.length} visits)` : ''}</h2>
  ${visitsHtml || `<p>No completed visits yet.</p>${machines.length ? `<h4>Machines</h4><table class="rt fx">${MW_COLS}<tr><th>Machine</th><th>Type</th><th>Serial</th><th>Serviced</th><th>Cleaned</th><th>Notes</th></tr>${machines.map((m) => `<tr><td>${esc(m.name)}</td><td>${esc(m.equipment_type || '')}</td><td>${esc(m.serial_number || '')}</td><td>—</td><td>—</td><td>Not serviced</td></tr>`).join('')}</table>` : ''}`}
  <p class="gen">Generated by PulseFitness.ai · ${esc(new Date().toLocaleString('en-GB'))}</p>
  </td></tr></tbody><tfoot><tr><td><div class="fspace"></div></td></tr></tfoot></table>
  <div class="ifoot"><img src="${window.location.origin}/brand/pulse-invoice-footer.png" alt="A pulseglobal Company. Registered Office: Pulse Fitness Limited, Radnor Park, Greenfield Road, Congleton, Cheshire, CW12 4TW. Company Registration No 4354059. VAT Registration No 785413509."/></div>
  </body></html>`;
}

function printReport(data) {
  const win = window.open('', '_blank', 'width=900,height=1000');
  if (!win) { notify.error('Please allow pop-ups to print the report'); return; }
  win.document.open();
  win.document.write(buildReportHtml(data));
  win.document.close();
  win.focus();
  setTimeout(() => { try { win.print(); } catch { /* user can print manually */ } }, 350);
}


export default function PpmScheduleDetail({ scheduleId, onClose, onAllocate, onDeleted }) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [deleting, setDeleting] = useState(false);

  useEffect(() => {
    (async () => {
      setLoading(true);
      try { const r = await api.get(`/svc/ppm/schedules/${scheduleId}`); setData(r.data); }
      catch { notify.error('Could not load the visit'); onClose?.(); }
      finally { setLoading(false); }
    })();
  }, [scheduleId]);

  useEffect(() => {
    const onKey = (e) => { if (e.key === 'Escape') onClose?.(); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);

  const del = async () => {
    if (!window.confirm('Delete this PM visit from the calendar?')) return;
    setDeleting(true);
    try {
      const r = await api.post('/svc/ppm/schedules/delete', { schedule_ids: [scheduleId] });
      notify.success(`Removed ${r.data?.deleted || 1} visit`);
      await onDeleted?.();
    } catch { notify.error('Could not delete the visit'); }
    finally { setDeleting(false); }
  };

  const s = data?.schedule;
  const w = data?.workings;
  const visits = data?.visits || [];

  return (
    <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4"
