            <h3 className="text-base font-bold truncate" data-testid="ppm-detail-site">{s?.site_name || 'Maintenance visit'}</h3>
            <p className="text-xs text-zinc-500 truncate">{s?.customer_name || ''}{s?.service_type ? ` · ${s.service_type}` : ''}</p>
