      external: true,
      tone: 'bg-emerald-50 text-emerald-700 border-emerald-200 hover:bg-emerald-100',
      testid: 'jaag-maps',
    },
    {
      key: 'email',
      label: t('service.eng_jd_email', 'Email'),
      icon: Send,
      href: email ? `mailto:${email}` : null,
