                          {eq.model ? <span className="text-slate-500"> {eq.model}</span> : null}
                        </span>
                        {eq.serial_number ? <span className="font-mono text-[10px] text-slate-400 ml-auto truncate">SN {eq.serial_number}</span> : null}
