                ) : null}
              </div>
            </>
          )}
        </div>

        {/* Footer */}
        <div className="px-4 py-3 border-t border-slate-200 flex gap-2">
          <button
            type="button"
            onClick={onClose}
            className="flex-1 border border-slate-300 rounded-xl py-2 text-sm font-semibold"
            data-testid="queue-preview-cancel"
          >
            Close
          </button>
          <button
            type="button"
            onClick={() => onClaim?.(job)}
            className="flex-1 bg-cyan-600 hover:bg-cyan-700 text-white rounded-xl py-2 text-sm font-bold inline-flex items-center justify-center gap-1.5"
            data-testid="queue-preview-allocate"
          >
            <Hand size={12} /> Allocate to me
          </button>
        </div>
      </div>
    </div>
  );
};

// ── Row ──────────────────────────────────────────────────────
// Iter 216h176 — Row signature adapted for react-window v2.
// react-window calls `rowComponent({ index, style, ariaAttributes, ...rowProps })`
// for each visible row; we accept the full props bag, look up the
// job by index from the `jobs` array, and apply the absolute-positioned
// `style` the windowing engine hands us.
const Row = ({ index, style, ariaAttributes, jobs, onClaim, onPreview, onOpen, viewMode, showDistance }) => {
  const job = jobs[index];
  if (!job) return null;
  // Iter 220p — "My gyms" rows are supplier_cases routed via the
  // public supplier-portal token flow; the engineer doesn't claim
  // them through this queue (they're already dispatched). The row's
  // CTA opens the token page instead.
  const isMyGymRow = viewMode === 'my-gyms';
  const rowKey = job.reference || job.id || `row-${index}`;
  return (
  <div
    style={style}
    {...ariaAttributes}
    className="p-3 sm:p-4 flex items-start gap-3 border-b border-slate-100 bg-white"
    data-testid={`queue-row-${rowKey}`}
  >
    <span
      className={`w-1.5 self-stretch rounded-full ${PRIO[job.priority] || PRIO.P3} flex-shrink-0`}
      aria-hidden
    />
    <div className="flex-1 min-w-0">
      <div className="flex items-center gap-2 mb-1 flex-wrap">
        <span className={`px-1.5 py-0.5 rounded text-[10px] font-extrabold text-white ${PRIO[job.priority] || PRIO.P3}`}>
          {job.priority || 'P3'}
        </span>
        <p className="text-[11px] font-bold text-slate-500 tabular-nums truncate">
          {job.reference || (job.issue_id ? `#${String(job.issue_id).slice(0, 8)}` : '')}
        </p>
        {/* Iter 220p — provenance badge: this fault came from a gym
            the engineer referred (auto-attached as supplier on signup). */}
        {job.from_referred_gym ? (
          <span
            className="px-1.5 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider inline-flex items-center gap-1 border"
            style={{ background: 'rgba(14,116,144,0.08)', borderColor: 'rgba(14,116,144,0.3)', color: '#0073a4' }}
            data-testid={`queue-row-referred-${rowKey}`}
            title="From a gym you referred. You're their primary auto-dispatched supplier."
          >
            <span aria-hidden>★</span> Referred
          </span>
        ) : null}
        {fmtSLA(job.sla_resolve_at)}
        {job.unlinked_area ? (
          <span
            className="px-1.5 py-0.5 rounded text-[10px] font-bold inline-flex items-center gap-1 bg-indigo-50 text-indigo-700 border border-indigo-200"
            data-testid={`queue-row-area-${rowKey}`}
            title="Matched to your postcode area — not yet linked to a CRM customer"
          >
            <MapPin size={10} /> In your area
          </span>
        ) : null}
        {showDistance ? (
          <span className="ml-auto inline-flex items-center gap-1" data-testid={`queue-row-near-${rowKey}`}>
            <span
              className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-bold tabular-nums bg-emerald-50 text-emerald-700"
              data-testid={`queue-row-distance-${rowKey}`}
            >
              <Navigation size={10} />
              {job.distance_km != null ? `${job.distance_km} km` : '—'}
            </span>
            {job.eta_minutes != null ? (
              <span
                className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-bold tabular-nums bg-slate-100 text-slate-700"
                data-testid={`queue-row-eta-${rowKey}`}
                title="Estimated drive time at 50 km/h average"
              >
                <Clock size={10} />
                ~{job.eta_minutes < 60
                  ? `${job.eta_minutes}m`
                  : `${Math.floor(job.eta_minutes / 60)}h${job.eta_minutes % 60 ? ` ${job.eta_minutes % 60}m` : ''}`}
              </span>
            ) : null}
          </span>
        ) : (
          <span className="text-[10px] text-slate-400 ml-auto tabular-nums">
            {fmtRelative(job.created_at)} ago
          </span>
        )}
      </div>
      <p className="text-sm font-semibold text-slate-900 truncate">{job.title}</p>
      <p className="text-xs text-slate-500 mt-0.5 truncate flex items-center gap-1.5">
        <MapPin size={10} />
        {job.site_name || job.customer_name || job.organization_name || 'Site TBC'}
        {job.site_postcode ? ` · ${job.site_postcode}` : ''}
        {job.intake_channel ? <span className="text-slate-400">· {job.intake_channel}</span> : null}
      </p>
      {job.description ? (
        <p className="text-xs text-slate-500 mt-1 line-clamp-2 leading-snug">{job.description}</p>
      ) : null}
    </div>
    {isMyGymRow ? (
      <a
        href={job.supplier_case_token ? `/supplier/case/${job.supplier_case_token}` : '#'}
        target="_blank"
        rel="noreferrer"
        className="bg-teal-600 hover:bg-teal-700 text-white text-xs font-semibold px-3 py-2 rounded-lg flex items-center gap-1.5 flex-shrink-0"
        data-testid={`queue-open-supplier-case-${rowKey}`}
      >
        Open ticket
      </a>
    ) : job.assigned_engineer_id ? (
      <div className="flex flex-col gap-1.5 items-end flex-shrink-0">
        <span
          className="px-2 py-1 rounded-lg text-[10px] font-bold bg-slate-100 text-slate-600 inline-flex items-center gap-1 max-w-[130px]"
          data-testid={`queue-assigned-${rowKey}`}
          title={job.assigned_engineer_name || 'Assigned'}
        >
          <ShieldCheck size={11} className="flex-shrink-0" />
          <span className="truncate">{job.assigned_engineer_name ? `Assigned · ${job.assigned_engineer_name}` : 'Assigned'}</span>
        </span>
        <button
          type="button"
          onClick={() => onOpen && onOpen(job)}
          className="text-cyan-700 hover:bg-cyan-50 text-[11px] font-bold px-2.5 py-1 rounded-md inline-flex items-center gap-1"
          data-testid={`queue-open-${rowKey}`}
        >
          View →
        </button>
      </div>
    ) : (
      <div className="flex flex-col gap-1.5 items-end flex-shrink-0">
        <button
          type="button"
          onClick={() => onClaim && onClaim(job)}
          className="bg-cyan-600 hover:bg-cyan-700 text-white text-xs font-semibold px-3 py-2 rounded-lg flex items-center gap-1.5"
          data-testid={`queue-claim-${rowKey}`}
        >
          <Hand size={12} /> Allocate to me
        </button>
        <button
          type="button"
          onClick={() => onPreview && onPreview(job)}
          className="text-cyan-700 hover:bg-cyan-50 text-[11px] font-bold px-2.5 py-1 rounded-md inline-flex items-center gap-1"
          data-testid={`queue-preview-${rowKey}`}
        >
          View details →
        </button>
      </div>
    )}
  </div>
  );
};

// ── Main page ──────────────────────────────────────────────
export default function EngineerQueue() {
  const orgBrand = useEngineerOrgBrand();
  const navigate = useNavigate();
  const [jobs, setJobs] = useState([]);
  const [stats, setStats] = useState({ total: 0, p1: 0, sla_breached_or_due: 0 });
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const [claimFor, setClaimFor] = useState(null);
  const [previewFor, setPreviewFor] = useState(null);
  const [claimBusy, setClaimBusy] = useState(false);
  const [sortMode, setSortMode] = useState('default');   // 'default' | 'nearest'
  const [origin, setOrigin] = useState(null);            // { lat, lon } | { postcode }
  const [originSource, setOriginSource] = useState(null); // 'geolocation' | 'postcode' | null
  const [locating, setLocating] = useState(false);
  // Iter 220p — "My gyms" view. When toggled on, swap data source
  // from org-wide /queue/unassigned to /queue/my-gyms (supplier_cases
  // dispatched directly to this engineer from the gyms they referred).
  const [viewMode, setViewMode] = useState('queue'); // 'queue' | 'my-gyms'
  const [myGyms, setMyGyms] = useState({ jobs: [], total: 0, gyms_count: 0, is_partner_engineer: null });

  const load = useCallback(async (sortOverride, originOverride) => {
    setLoading(true);
    try {
      const effectiveSort = sortOverride ?? sortMode;
      const effectiveOrigin = originOverride !== undefined ? originOverride : origin;
      const params = {};
      if (effectiveSort === 'nearest' && effectiveOrigin) {
        params.sort = 'nearest';
        if (effectiveOrigin.lat != null && effectiveOrigin.lon != null) {
          params.lat = effectiveOrigin.lat;
          params.lon = effectiveOrigin.lon;
        } else if (effectiveOrigin.postcode) {
          params.postcode = effectiveOrigin.postcode;
        }
      }
      const [j, g] = await Promise.all([
        axios.get(`${API}/svc/engineer/queue/territory`, { ...auth(), params }),
        // Iter 220p — fetch "My gyms" alongside for the pill badge count.
        axios.get(`${API}/svc/engineer/queue/my-gyms`, auth())
          .catch(() => ({ data: { jobs: [], total: 0, is_partner_engineer: null } })),
      ]);
      const tjobs = j.data?.jobs || [];
      setJobs(tjobs);
      setOriginSource(null);
      // Territory view computes its own stat strip from the returned cases.
      const p1 = tjobs.filter((x) => (x.priority || '').toUpperCase() === 'P1').length;
      const slaRisk = tjobs.filter((x) => {
        if (!x.sla_resolve_at) return false;
        return (new Date(x.sla_resolve_at) - Date.now()) < 2 * 3600 * 1000;
      }).length;
      setStats({ total: tjobs.length, p1, sla_breached_or_due: slaRisk });
      setMyGyms(g.data || { jobs: [], total: 0, is_partner_engineer: null });
      // Iter 216h176 — Warm the engineer's "active week" cache so the
      // diary + notifications survive going offline. Throttled to once
      // every 5 minutes; no-op if the SW isn't installed.
      warmEngineerCache();
    } catch (e) {
      notify.error('Failed to load queue', e?.response?.data?.detail || e.message);
    } finally {
      setLoading(false);
    }
  }, [sortMode, origin]); // eslint-disable-line react-hooks/exhaustive-deps -- intentional: reviewed in iter 216h226-deps-walk — runs on the listed trigger deps; omitted refs are stable identities or read live state at call time.

  useEffect(() => { load(); }, [load]);

  // Auto-refresh every 30s so race-with-other-engineers doesn't show stale jobs.
  useEffect(() => {
    const t = setInterval(() => load(), 30000);
    return () => clearInterval(t);
  }, [load]);

  // ── Nearest-to-me handler ────────────────────────────────
  const enableNearest = useCallback(async () => {
    if (sortMode === 'nearest') {
      // Toggle off
      setSortMode('default');
      setOrigin(null);
      setOriginSource(null);
      load('default', null);
      return;
    }
    setLocating(true);
    // Try browser geolocation first
    const tryGeo = () => new Promise((resolve) => {
      if (!navigator.geolocation) return resolve(null);
      navigator.geolocation.getCurrentPosition(
        (pos) => resolve({ lat: pos.coords.latitude, lon: pos.coords.longitude }),
        () => resolve(null),
        { enableHighAccuracy: false, timeout: 7000, maximumAge: 60_000 },
      );
    });
    const coords = await tryGeo();
    let nextOrigin = null;
    if (coords) {
      nextOrigin = { lat: coords.lat, lon: coords.lon };
    } else {
      // Fallback: fetch engineer profile postcode
      try {
        const me = await axios.get(`${API}/svc/engineer/me`, auth());
        const pc = me.data?.engineer?.home_address?.postcode
                || me.data?.home_address?.postcode
                || me.data?.postcode;
        if (pc) nextOrigin = { postcode: pc };
      } catch (_) { /* ignore */ }
    }
    setLocating(false);
    if (!nextOrigin) {
      notify.error('Location unavailable',
        'Grant location access or set a postcode on your engineer profile to sort by distance.');
      return;
    }
    setSortMode('nearest');
    setOrigin(nextOrigin);
    load('nearest', nextOrigin);
  }, [sortMode, load]);

  const filtered = useMemo(() => {
    // Iter 220p — when viewing "My gyms", show the engineer's
    // supplier_cases. These aren't claimable through the normal queue
    // (they came via the supplier portal token flow), so the row
    // component routes the user to the supplier_case page instead.
    if (viewMode === 'my-gyms') return myGyms.jobs || [];
    if (filter === 'all') return jobs;
    if (filter === 'p1') return jobs.filter((j) => (j.priority || '').toUpperCase() === 'P1');
    if (filter === 'risk') return jobs.filter((j) => {
      if (!j.sla_resolve_at) return false;
      const ms = new Date(j.sla_resolve_at) - Date.now();
      return ms < 2 * 3600 * 1000;
    });
    return jobs;
  }, [jobs, filter, viewMode, myGyms.jobs]);

  const onClaim = async (payload) => {
    if (!claimFor) return;
    setClaimBusy(true);
    try {
      const r = await axios.post(
        `${API}/svc/engineer/queue/${claimFor.id}/claim`,
        payload,
        auth(),
      );
      notify.success(`Allocated ${r.data.reference}`);
      setClaimFor(null);
      // Iter 220dn — pass `from=queue` so the job-detail back button
      // returns the engineer to Up-for-grabs instead of dumping them
      // on Engineer Home. Fixes the "the job disappeared" feedback —
      // the queue now visibly re-renders without the claimed row.
      navigate(`/svc/engineer/jobs/${r.data.case_id}?from=queue`);
    } catch (e) {
      const detail = e?.response?.data?.detail;
      if (e?.response?.status === 409) {
        const msg = (typeof detail === 'object' ? detail.detail : null) ||
                    'Sorry — that job has just been taken by another engineer.';
        notify.error('Already claimed', msg);
        setClaimFor(null);
        load();
      } else {
        notify.error('Allocate failed', (typeof detail === 'object' ? JSON.stringify(detail) : detail) || e.message);
      }
    } finally {
      setClaimBusy(false);
    }
  };

  const Stat = ({ label, value, accent }) => (
    <div className={`flex-1 rounded-xl border p-3 ${accent || 'bg-white border-slate-200'}`}>
      <p className="text-[10px] font-bold uppercase tracking-wider text-slate-500">{label}</p>
      <p className="text-2xl font-extrabold text-slate-900 tabular-nums leading-tight">{value}</p>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50" data-testid="engineer-queue">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10">
        <div className="max-w-4xl mx-auto px-4 py-4 flex items-center justify-between gap-3">
          <div className="flex items-center gap-3 min-w-0">
            <button
              type="button"
              onClick={() => navigate('/svc/engineer')}
              className="text-slate-500 hover:text-slate-900"
              data-testid="queue-back"
              aria-label="Back"
            >
              <ChevronLeft size={22} />
            </button>
            <div className="min-w-0">
              <p className="text-[10px] font-bold uppercase tracking-[0.2em] text-cyan-700">
                {orgBrand.label}
              </p>
              <h1 className="text-xl font-extrabold text-slate-900 flex items-center gap-2">
                <Hand size={20} /> Territory jobs
              </h1>
            </div>
          </div>
          <button
            type="button"
            onClick={load}
            className="p-2 rounded-lg hover:bg-slate-100 text-slate-500"
            data-testid="queue-refresh"
            aria-label="Refresh"
          >
            {loading ? <Loader2 size={18} className="animate-spin" /> : <RefreshCw size={18} />}
          </button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-4 py-4 space-y-3">
        {/* Stat strip */}
        <section className="flex gap-2" data-testid="queue-stats">
          <Stat label="Open" value={stats.total} />
          <Stat label="P1" value={stats.p1} accent={stats.p1 ? 'bg-red-50 border-red-200' : ''} />
          <Stat label="SLA risk" value={stats.sla_breached_or_due} accent={stats.sla_breached_or_due ? 'bg-amber-50 border-amber-200' : ''} />
        </section>

        {/* Iter 220p — view mode switcher: org-wide queue ↔ My gyms.
            The "My gyms" pill is only shown for Partner Engineers (i.e.
            users we've found a partner_engineers row for). For everyone
            else it stays hidden so the queue UX is unchanged. */}
        {myGyms.is_partner_engineer ? (
          <div className="flex items-center gap-2" data-testid="queue-view-switcher">
            <button
              type="button"
              onClick={() => setViewMode('queue')}
              className={`px-3 py-1.5 rounded-full text-xs font-semibold transition-colors ${
                viewMode === 'queue'
                  ? 'bg-slate-900 text-white shadow-sm'
                  : 'bg-white border border-slate-200 text-slate-700 hover:bg-slate-50'
              }`}
              data-testid="queue-view-org"
            >
              Territory jobs{jobs.length ? ` · ${jobs.length}` : ''}
            </button>
            <button
              type="button"
              onClick={() => setViewMode('my-gyms')}
              className={`px-3 py-1.5 rounded-full text-xs font-semibold transition-colors inline-flex items-center gap-1.5 ${
                viewMode === 'my-gyms'
                  ? 'text-white shadow-sm'
                  : 'bg-white border text-slate-700 hover:bg-slate-50'
              }`}
              style={viewMode === 'my-gyms'
                ? { background: 'linear-gradient(135deg, #0091ca 0%, #0073a4 100%)' }
                : { borderColor: '#0e749033' }
              }
              data-testid="queue-view-my-gyms"
              title="Faults from gyms where you're the auto-dispatched supplier"
            >
              <span aria-hidden>★</span>
              My gyms{myGyms.total ? ` · ${myGyms.total}` : ''}
              {myGyms.gyms_count ? (
                <span className={`ml-1 px-1.5 py-0.5 rounded text-[10px] font-bold ${
                  viewMode === 'my-gyms' ? 'bg-white/20 text-white' : 'bg-teal-50 text-teal-700'
                }`}>
                  {myGyms.gyms_count} gym{myGyms.gyms_count === 1 ? '' : 's'}
                </span>
              ) : null}
            </button>
          </div>
        ) : null}

        {/* Filters */}
        <div className="bg-white border border-slate-200 rounded-2xl px-3 py-2 flex items-center gap-1 flex-wrap">
          {[
            { k: 'all',  label: `All${jobs.length ? ` · ${jobs.length}` : ''}` },
            { k: 'p1',   label: `P1${stats.p1 ? ` · ${stats.p1}` : ''}` },
            { k: 'risk', label: `SLA risk${stats.sla_breached_or_due ? ` · ${stats.sla_breached_or_due}` : ''}` },
          ].map((opt) => (
            <button
              key={opt.k}
              type="button"
              onClick={() => setFilter(opt.k)}
              className={`px-3 py-1.5 rounded-lg text-xs font-semibold ${
                filter === opt.k ? 'bg-cyan-600 text-white' : 'text-slate-600 hover:bg-slate-100'
              }`}
              data-testid={`queue-filter-${opt.k}`}
            >
              {opt.label}
            </button>
          ))}
          <span className="flex-1" />
          <button
            type="button"
            onClick={enableNearest}
            disabled={locating}
            className={`px-3 py-1.5 rounded-lg text-xs font-semibold flex items-center gap-1.5 ${
              sortMode === 'nearest'
                ? 'bg-emerald-600 text-white'
                : 'text-slate-700 border border-slate-300 hover:bg-slate-50'
            }`}
            data-testid="queue-sort-nearest"
            title="Sort jobs by distance from your current location"
          >
            {locating ? <Loader2 size={12} className="animate-spin" /> : <Crosshair size={12} />}
            {sortMode === 'nearest' ? 'Sorted: nearest' : 'Nearest to me'}
          </button>
        </div>

        {sortMode === 'nearest' && originSource ? (
          <p className="text-[11px] text-slate-500 px-1" data-testid="queue-origin-source">
            Distances from your{' '}
            {originSource === 'geolocation' ? 'current location' : 'home postcode'};
            ETA assumes a 50 km/h field-service average. Sites without a postcode appear last.
          </p>
        ) : null}

        {/* List */}
        {!loading && filtered.length === 0 ? (
          <div className="bg-white border border-dashed border-slate-300 rounded-2xl p-10 text-center" data-testid="queue-empty">
            <CheckCircle2 size={28} className="mx-auto text-emerald-500 mb-2" />
            <p className="text-sm font-semibold text-slate-700">
              {viewMode === 'my-gyms' ? 'No open jobs from your gyms' : 'No jobs in your area'}
            </p>
            <p className="text-xs text-slate-500 mt-1">
              {viewMode === 'my-gyms'
                ? (myGyms.no_gyms_yet
                    ? "You haven't been added as a supplier yet. Share your referral link to onboard gyms."
                    : "Your gyms are all clear right now. New faults will appear here automatically.")
                : "No open cases logged in your territory right now. We refresh this every 30 seconds."}
            </p>
          </div>
        ) : (
          // Iter 216h176 — Virtualised list. For ≤30 jobs we fall back
          // to the static <ul> so very short queues don't pay the
          // windowing overhead. Above that, react-window only mounts
          // ~10 rows at a time which keeps scroll smooth at 60 fps
          // even with 200+ jobs in the engineer's region.
          filtered.length <= 30 ? (
            <ul className="bg-white border border-slate-200 rounded-2xl divide-y divide-slate-100 overflow-hidden">
              {filtered.map((j, idx) => (
                <Row
                  key={j.id}
                  index={idx}
                  style={{ position: 'relative' }}
                  ariaAttributes={{}}
                  jobs={filtered}
                  onClaim={viewMode === 'my-gyms' ? null : setClaimFor}
                  onPreview={viewMode === 'my-gyms' ? null : setPreviewFor}
                  onOpen={(j) => navigate(`/svc/engineer/jobs/${j.id}?from=queue`)}
                  viewMode={viewMode}
                  showDistance={sortMode === 'nearest'}
                />
              ))}
            </ul>
          ) : (
            <div
              className="bg-white border border-slate-200 rounded-2xl overflow-hidden"
              data-testid="queue-virtualised"
              style={{ height: 'calc(100vh - 320px)', minHeight: 360 }}
            >
              <List
                rowCount={filtered.length}
                rowHeight={132}
                rowComponent={Row}
                rowProps={{
                  jobs: filtered,
                  onClaim: viewMode === 'my-gyms' ? null : setClaimFor,
                  onPreview: viewMode === 'my-gyms' ? null : setPreviewFor,
                  onOpen: (j) => navigate(`/svc/engineer/jobs/${j.id}?from=queue`),
                  viewMode,
                  showDistance: sortMode === 'nearest',
                }}
                overscanCount={3}
              />
            </div>
          )
        )}

        {/* Footer hint */}
        <div className="bg-cyan-50 border border-cyan-200 rounded-xl p-3 text-xs text-cyan-900 flex items-start gap-2">
          <ShieldCheck size={14} className="mt-0.5 flex-shrink-0" />
          <p>
            Two engineers can't grab the same job — first tap wins. If you see "already claimed",
            just refresh and pick the next one.
          </p>
        </div>
      </main>

      <ClaimModal
        job={claimFor}
        onClose={() => setClaimFor(null)}
        onConfirm={onClaim}
        busy={claimBusy}
      />
      <PreviewModal
        job={previewFor}
        onClose={() => setPreviewFor(null)}
        onClaim={(j) => { setPreviewFor(null); setClaimFor(j); }}
      />
    </div>
  );
}

/**
 * WorkVisitMachinesCard — Iter 220d
 *
 * Per-machine work-report card shown inside the Engineer App's Complete
 * tab. Replicates the row-per-machine spreadsheet workflow that real
 * engineers use on PPM site visits (the dan_starr export):
 *
 *   Row 1  ·  BikeErg #03   ·  [✓] Serviced  [✓] Cleaned  ·  Notes…
 *   Row 2  ·  RowErg  #14   ·  [✓] Serviced  [ ] Cleaned  ·  Notes…
 *   ...
 *
 * Each row's notes field has the shared/personal `NotePresetChips`
 * palette attached, so recurring sentences become 1-tap entries.
 *
 * The "Apply to all rows below" action copies serviced/cleaned/notes
 * from the source row to subsequent rows — saves 8x typing on a PPM
 * visit where every BikeErg gets the same calibration note.
 */
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';
import {
  Plus, Loader2, Trash2, Copy, Wrench, Sparkles, ChevronDown,
  ChevronUp, ChevronRight, Camera, X, PackagePlus, Package, CheckSquare, Square,
  ListChecks, Search, Check, Clock, ShieldCheck,
} from 'lucide-react';
import { notify } from '@/components/notifications';
import { chunkedUpload } from '@/utils/chunkedUpload';
import { stashPausedUpload } from '@/utils/engineerUploadStash';
import { outboxPost } from '@/utils/engineerOutbox';
import NotePresetChips from './NotePresetChips';
import MachineRowCustomFields from './MachineRowCustomFields';

const API = process.env.REACT_APP_BACKEND_URL
  ? `${process.env.REACT_APP_BACKEND_URL}/api`
  : '/api';
const auth = () => ({
  headers: { Authorization: `Bearer ${localStorage.getItem('token') || ''}` },
});

// Iter 220ea·21 — client idempotency key so an offline-queued
// "part used" replays exactly once when the connection returns.
const newIdemKey = () => (
  (typeof crypto !== 'undefined' && crypto.randomUUID)
    ? crypto.randomUUID()
    : `idem-${Date.now()}-${Math.random().toString(36).slice(2)}`
);

export default function WorkVisitMachinesCard({ caseId }) {
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [expandedId, setExpandedId] = useState(null);
  const [assetOptions, setAssetOptions] = useState([]);
  const [assetSearch, setAssetSearch] = useState('');
  // Iter 220cj — Site equipment picker (multi-select w/ Select All)
  const [sitePickerOpen, setSitePickerOpen] = useState(false);
  // Engineer-proposed equipment changes (office must approve before they apply)
  const [proposeOpen, setProposeOpen] = useState(false);
  const [proposals, setProposals] = useState([]);

  const loadProposals = useCallback(async () => {
    if (!caseId) return;
    try {
      const r = await axios.get(`${API}/svc/engineer/jobs/${caseId}/equipment-change-requests`, auth());
      setProposals(r.data?.requests || []);
    } catch { setProposals([]); }
  }, [caseId]);
  useEffect(() => { loadProposals(); }, [loadProposals]);

  const proposeRemoval = async (row) => {
    if (!row?.asset_id) { notify.error('This row has no linked asset to remove'); return; }
    const reason = window.prompt(`Propose removing "${row.asset_name}" from the site asset list?\n\nThe office will review before it is archived. Add a reason (optional):`, '');
    if (reason === null) return;
    try {
      await axios.post(`${API}/svc/engineer/equipment-change-requests`, {
        case_id: caseId, change_type: 'remove',
        equipment_id: row.asset_id, equipment_name: row.asset_name || '', reason,
      }, auth());
      notify.success('Removal proposed — sent to the office for review');
      loadProposals();
    } catch (e) { notify.error('Could not propose removal', e?.response?.data?.detail || e?.message); }
  };


  const load = useCallback(async () => {
    if (!caseId) { setLoading(false); return; }
    setLoading(true);
    try {
      const r = await axios.get(`${API}/svc/engineer/jobs/${caseId}/machines`, auth());
      const list = r.data?.machines || [];
      setRows(list);
      if (list.length && !expandedId) setExpandedId(list[0].id);
    } catch (e) {
      console.warn('[machines] load failed', e);
      setRows([]);
    } finally {
      setLoading(false);
    }
  }, [caseId, expandedId]);

  useEffect(() => { load(); }, [load]);  

  // Load equipment list for the asset picker — once per session is enough.
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const r = await axios.get(`${API}/equipment`, auth());
        if (cancelled) return;
        const trimmed = (r.data?.equipment || []).map(e => ({
          id: e.id,
          label: [e.manufacturer, e.model || e.name].filter(Boolean).join(' ').trim() || e.name || 'Equipment',
          serial: e.serial_number || '',
          equipment_type: e.equipment_type || '',
        }));
        setAssetOptions(trimmed);
      } catch (e) {
        setAssetOptions([]);
      }
    })();
    return () => { cancelled = true; };
  }, []);

  const patchRow = async (rowId, patch) => {
    // Optimistic.
    setRows((prev) => prev.map(r => r.id === rowId ? { ...r, ...patch } : r));
    try {
      const r = await axios.patch(
        `${API}/svc/engineer/jobs/${caseId}/machines/${rowId}`,
        patch,
        auth(),
      );
      setRows((prev) => prev.map(x => x.id === rowId ? r.data : x));
    } catch (e) {
      notify.error('Save failed', e?.response?.data?.detail || e?.message);
      load();
    }
  };

  const deleteRow = async (rowId) => {
    if (!window.confirm('Remove this machine from the report?')) return;
    try {
      await axios.delete(`${API}/svc/engineer/jobs/${caseId}/machines/${rowId}`, auth());
      setRows((prev) => prev.filter(x => x.id !== rowId));
    } catch (e) {
      notify.error('Could not remove', e?.response?.data?.detail || e?.message);
    }
  };

  const copyDown = async (rowId, fields) => {
    try {
      const r = await axios.post(
        `${API}/svc/engineer/jobs/${caseId}/machines/${rowId}/copy-down`,
        { fields },
        auth(),
      );
      notify.success(`Applied to ${r.data.updated} row${r.data.updated === 1 ? '' : 's'} below`);
      load();
    } catch (e) {
      notify.error('Copy-down failed', e?.response?.data?.detail || e?.message);
    }
  };

  const attachPhoto = async (rowId, file, caption = '') => {
    if (!file) return;
    try {
      // Iter 220ea·4 — Route through chunkedUpload so a 4G blip
      // drops one 1 MB chunk, not the entire upload. The stash
      // captures the session blob the moment init succeeds so
      // the engineer can resume from the paused-uploads pill if
      // the connection (or the tab) dies mid-flight.
      const uploaded = await chunkedUpload({
        baseURL: API,
        file,
        category: 'service-media',
        authHeaders: auth().headers,
        onSession: async ({ uploadId, totalChunks }) => {
          await stashPausedUpload({
            upload_id: uploadId,
            total_chunks: totalChunks,
            case_id: caseId,
            machine_row_id: rowId,
            filename: file.name || `photo-${Date.now()}.jpg`,
            size: file.size,
            content_type: file.type || 'image/jpeg',
            blob: file,
            caption: caption || '',
            kind: 'photo',
            saved_at: Date.now(),
          });
        },
      });
      const fileUrl = uploaded?.download_url || uploaded?.storage_path;
      const r = await axios.post(`${API}/svc/engineer/photos`, {
        case_id: caseId,
        machine_row_id: rowId,
        file_url: fileUrl,
        mime_type: uploaded?.content_type || 'image/jpeg',
        caption: caption || '',
      }, auth());
      // Optimistic insert into the row.
      setRows((prev) => prev.map(r2 => r2.id === rowId
        ? { ...r2, photos: [...(r2.photos || []), r.data] }
        : r2,
      ));
      // Upload landed cleanly — drop the stash row so it stops
      // counting against the paused-uploads pill.
      if (uploaded?.upload_method === 'chunked' && uploaded?.id) {
        // chunked path: session was stashed under upload_id which we
        // captured via onSession; we can't know it back here, so
        // delegate to a best-effort cleanup that walks the stash
        // for any row referencing this same case+filename+size and
        // drops it. Cheap, scoped, idempotent.
        try {
          const { listPausedUploads, dropPausedUpload: drop } = await import('@/utils/engineerUploadStash');
          for (const row of await listPausedUploads()) {
            if (row.case_id === caseId
                && row.filename === (file.name || '')
                && row.size === file.size) {
              await drop(row.upload_id);
            }
          }
        } catch { /* swallow */ }
      }
      notify.success('Photo attached');
    } catch (e) {
      // Stash row stays put — the resume sheet will pick it up.
      notify.error('Upload failed', e?.response?.data?.detail || e?.message);
    }
  };

  const removePhoto = async (rowId, photoId) => {
    if (!window.confirm('Remove this photo?')) return;
    try {
      await axios.delete(`${API}/svc/engineer/photos/${photoId}`, auth());
      setRows((prev) => prev.map(r => r.id === rowId
        ? { ...r, photos: (r.photos || []).filter(p => p.id !== photoId) }
        : r,
      ));
    } catch (e) {
      notify.error('Could not remove', e?.response?.data?.detail || e?.message);
    }
  };

  const filteredAssets = useMemo(() => {
    const needle = assetSearch.trim().toLowerCase();
    if (!needle) return assetOptions.slice(0, 50);
    return assetOptions.filter(a =>
      a.label.toLowerCase().includes(needle) ||
      (a.serial || '').toLowerCase().includes(needle),
    ).slice(0, 50);
  }, [assetOptions, assetSearch]);

  return (
    <div className="bg-white rounded-2xl border border-slate-200" data-testid="machines-card">
      {/* Iter 220ea·10 — Header + action bar redesign. The three
          actions used to sit in a wrap-cluster that stacked
          vertically on a 412 px phone; now they're an evenly
          spaced 3-up grid with clear labels. */}
      <div className="p-4 border-b border-slate-100">
        <div className="flex items-start gap-2 mb-3">
          <Wrench size={14} className="text-cyan-600 mt-0.5 shrink-0" />
          <div className="flex-1 min-w-0">
            <p className="text-sm font-bold text-slate-900">
              Machines on this visit
            </p>
            <p className="text-[11px] text-slate-500 mt-0.5 leading-snug">
              One row per machine. Tick what you serviced or cleaned, then add notes.
            </p>
          </div>
        </div>
        {/* Iter 220ea·11 — "Add machine" removed. Every machine
            must be backed by a real asset record so the engineer
            picks "From site" (existing equipment for this gym)
            or "New asset" (create + attach). The old blank-row
            "Add machine" path created orphan rows with no asset
            linkage. */}
        <div className="grid grid-cols-2 gap-2">
          <button
            type="button"
            onClick={() => setSitePickerOpen(true)}
            className="inline-flex flex-col items-center justify-center gap-1 py-2.5 rounded-xl border border-cyan-200 bg-cyan-50 text-cyan-700 text-xs font-extrabold hover:bg-cyan-100"
            data-testid="machines-load-from-site-btn"
            title="Show all equipment for this site and pick which ones to work on"
          >
            <Package size={16} />
            <span>From site</span>
          </button>
          <button
            type="button"
            onClick={() => setProposeOpen(true)}
            className="inline-flex flex-col items-center justify-center gap-1 py-2.5 rounded-xl border border-slate-200 bg-white text-slate-700 text-xs font-extrabold hover:bg-slate-50"
            data-testid="machines-propose-asset-btn"
            title="Propose a brand-new asset for this site — the office reviews it before it's added"
          >
            <PackagePlus size={16} />
            <span>Propose new</span>
          </button>
        </div>
        {proposals.length > 0 && (
          <div className="mt-3 rounded-xl border border-amber-200 bg-amber-50 p-2.5" data-testid="machines-proposals">
            <p className="text-[11px] font-extrabold uppercase tracking-wide text-amber-700 mb-1">Proposed changes · office review</p>
            <ul className="space-y-1">
              {proposals.map((p) => (
                <li key={p.id} className="text-[11px] text-amber-900 flex items-center justify-between gap-2" data-testid={`machine-proposal-${p.id}`}>
                  <span className="truncate">
                    {p.change_type === 'add' ? `Add: ${p.proposed?.name || ''}` : `Remove: ${p.equipment_name || ''}`}
                  </span>
                  <span className={`shrink-0 text-[9px] font-bold uppercase px-1.5 py-0.5 rounded-full ${p.status === 'pending' ? 'bg-amber-200 text-amber-800' : p.status === 'approved' ? 'bg-emerald-200 text-emerald-800' : 'bg-rose-200 text-rose-800'}`}>{p.status}</span>
                </li>
              ))}
            </ul>
          </div>
        )}
      </div>

      {loading ? (
        <div className="p-6 flex items-center justify-center text-slate-400">
          <Loader2 size={14} className="animate-spin mr-2" /> Loading…
        </div>
      ) : rows.length === 0 ? (
        <div className="p-6 text-center" data-testid="machines-empty">
          <p className="text-sm font-bold text-slate-900">No machines added yet</p>
          <p className="text-xs text-slate-500 mt-1">
            Tap <span className="font-bold">Add machine</span> for each Erg you serviced.
            You can still complete the job without adding any.
          </p>
        </div>
      ) : (
        <div className="divide-y divide-slate-100">
          {rows.map((row, idx) => (
            <MachineRow
              key={row.id}
              row={row}
              index={idx}
              caseId={caseId}
              expanded={expandedId === row.id}
              onExpand={() => setExpandedId(expandedId === row.id ? null : row.id)}
              onPatch={(patch) => patchRow(row.id, patch)}
              onDelete={() => deleteRow(row.id)}
              onCopyDown={(fields) => copyDown(row.id, fields)}
              onAttachPhoto={(file) => attachPhoto(row.id, file)}
              onRemovePhoto={(photoId) => removePhoto(row.id, photoId)}
              onProposeRemoval={() => proposeRemoval(row)}
              showCopyDown={idx < rows.length - 1}
              assetOptions={filteredAssets}
              assetSearch={assetSearch}
              setAssetSearch={setAssetSearch}
              refreshRows={load}
            />
          ))}
        </div>
      )}
      {/* Iter 220cj — Site equipment picker modal */}
      {sitePickerOpen ? (
        <SiteEquipmentPicker
          caseId={caseId}
          onClose={() => setSitePickerOpen(false)}
          onImported={() => { setSitePickerOpen(false); load(); }}
        />
      ) : null}
      {proposeOpen ? (
        <ProposeEquipmentModal
          caseId={caseId}
          onClose={() => setProposeOpen(false)}
          onProposed={() => { setProposeOpen(false); loadProposals(); }}
        />
      ) : null}
    </div>
  );
}

// Engineer proposes a brand-new asset for the site. Goes to the office review
// queue — nothing is added to the live asset list until approved.
function ProposeEquipmentModal({ caseId, onClose, onProposed }) {
  const [form, setForm] = useState({ name: '', equipment_type: '', manufacturer: '', model: '', serial_number: '', notes: '' });
  const [busy, setBusy] = useState(false);
  const set = (k, v) => setForm((p) => ({ ...p, [k]: v }));
  const submit = async () => {
    if (!form.name.trim()) { notify.error('Give the equipment a name'); return; }
    setBusy(true);
    try {
      await axios.post(`${API}/svc/engineer/equipment-change-requests`, {
        case_id: caseId, change_type: 'add', proposed: form,
      }, auth());
      notify.success('New equipment proposed — sent to the office for review');
      onProposed?.();
    } catch (e) { notify.error('Could not propose', e?.response?.data?.detail || e?.message); }
    finally { setBusy(false); }
  };
  const inp = 'w-full mt-1 text-sm border border-slate-200 rounded-lg px-3 py-2 bg-white';
  return (
    <div className="fixed inset-0 z-50 bg-black/40 flex items-end sm:items-center justify-center p-0 sm:p-4" data-testid="propose-equipment-modal">
      <div className="bg-white w-full sm:max-w-md max-h-[92vh] sm:rounded-2xl rounded-t-2xl shadow-2xl flex flex-col overflow-hidden">
        <div className="px-4 py-3 border-b border-slate-200 flex items-center justify-between">
          <p className="text-sm font-bold text-slate-900">Propose new equipment</p>
          <button onClick={onClose} className="w-9 h-9 rounded-xl border border-slate-200 flex items-center justify-center text-slate-600" data-testid="propose-equipment-close"><X size={16} /></button>
        </div>
        <div className="p-4 overflow-y-auto space-y-2.5">
          <p className="text-[11px] text-slate-500">The office reviews this before it's added to the site's asset list.</p>
          <div><label className="text-[10px] font-bold uppercase tracking-wide text-slate-500">Name *</label>
            <input className={inp} value={form.name} onChange={(e) => set('name', e.target.value)} placeholder="e.g. Technogym Run 1000" data-testid="propose-name" /></div>
          <div className="grid grid-cols-2 gap-2">
            <div><label className="text-[10px] font-bold uppercase tracking-wide text-slate-500">Type</label>
              <input className={inp} value={form.equipment_type} onChange={(e) => set('equipment_type', e.target.value)} placeholder="Treadmill" data-testid="propose-type" /></div>
            <div><label className="text-[10px] font-bold uppercase tracking-wide text-slate-500">Serial no.</label>
              <input className={inp} value={form.serial_number} onChange={(e) => set('serial_number', e.target.value)} data-testid="propose-serial" /></div>
            <div><label className="text-[10px] font-bold uppercase tracking-wide text-slate-500">Manufacturer</label>
              <input className={inp} value={form.manufacturer} onChange={(e) => set('manufacturer', e.target.value)} data-testid="propose-manufacturer" /></div>
            <div><label className="text-[10px] font-bold uppercase tracking-wide text-slate-500">Model</label>
              <input className={inp} value={form.model} onChange={(e) => set('model', e.target.value)} data-testid="propose-model" /></div>
          </div>
          <div><label className="text-[10px] font-bold uppercase tracking-wide text-slate-500">Notes</label>
            <textarea className={inp} rows={2} value={form.notes} onChange={(e) => set('notes', e.target.value)} data-testid="propose-notes" /></div>
        </div>
        <div className="px-4 py-3 border-t border-slate-200 flex gap-2">
          <button onClick={onClose} className="flex-1 border border-slate-300 rounded-xl py-2.5 text-sm font-semibold" data-testid="propose-cancel">Cancel</button>
          <button onClick={submit} disabled={busy} className="flex-1 bg-cyan-600 hover:bg-cyan-700 disabled:bg-slate-300 text-white rounded-xl py-2.5 text-sm font-bold inline-flex items-center justify-center gap-1.5" data-testid="propose-submit">
            {busy ? <><Loader2 size={12} className="animate-spin" /> Sending…</> : <><PackagePlus size={14} /> Propose</>}
          </button>
        </div>
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────────────
// Iter 220cj — SiteEquipmentPicker
// Mobile-first multi-select sheet. Pulls every equipment record on the
// case's site, lets the engineer tick 1 / many / all, and bulk-attaches
// them as machine rows on the job. Already-attached items are ghosted.
// ─────────────────────────────────────────────────────────────────────

function SiteEquipmentPicker({ caseId, onClose, onImported }) {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [q, setQ] = useState('');
  const [selected, setSelected] = useState(() => new Set());
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      setLoading(true);
      setError('');
      try {
        const r = await axios.get(
          `${API}/svc/engineer/jobs/${caseId}/site-equipment`, auth(),
        );
        if (cancelled) return;
        setItems(r.data?.site_equipment || []);
      } catch (e) {
        if (cancelled) return;
        setError(e?.response?.data?.detail || e?.message || 'Failed to load');
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => { cancelled = true; };
  }, [caseId]);

  const filtered = useMemo(() => {
    const needle = q.trim().toLowerCase();
    if (!needle) return items;
    return items.filter((it) =>
      (it.name || '').toLowerCase().includes(needle)
      || (it.serial_number || '').toLowerCase().includes(needle)
      || (it.manufacturer || '').toLowerCase().includes(needle)
      || (it.equipment_type || '').toLowerCase().includes(needle),
    );
  }, [items, q]);

  const selectable = filtered.filter((i) => !i.already_on_job);
  const allSelected =
    selectable.length > 0 && selectable.every((i) => selected.has(i.id));
  const someSelected = selectable.some((i) => selected.has(i.id));

  const toggle = (id) => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  };

  const toggleAll = () => {
    setSelected((prev) => {
      if (allSelected) {
        const next = new Set(prev);
        selectable.forEach((i) => next.delete(i.id));
        return next;
      }
      const next = new Set(prev);
      selectable.forEach((i) => next.add(i.id));
      return next;
    });
  };

  const onAttach = async () => {
    if (selected.size === 0) return;
    setSubmitting(true);
    try {
      const r = await axios.post(
        `${API}/svc/engineer/jobs/${caseId}/machines/bulk-from-site`,
        { equipment_ids: Array.from(selected) },
        auth(),
      );
      const inserted = r.data?.inserted || 0;
      const skipped = r.data?.skipped || 0;
      notify.success(
        `Added ${inserted} machine${inserted === 1 ? '' : 's'}` +
        (skipped > 0 ? ` · skipped ${skipped} already on job` : ''),
      );
      onImported?.();
    } catch (e) {
      notify.error('Could not attach',
                   e?.response?.data?.detail || e?.message);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div
      className="fixed inset-0 z-50 bg-black/40 flex items-end sm:items-center justify-center p-0 sm:p-4"
      data-testid="site-equipment-picker"
    >
      <div className="bg-white w-full sm:max-w-lg max-h-[92vh] sm:rounded-2xl rounded-t-2xl shadow-2xl flex flex-col overflow-hidden">
        <div className="px-4 py-3 border-b border-slate-200 flex items-center justify-between gap-3">
          <div className="flex-1 min-w-0">
            <p className="text-sm font-bold text-slate-900">Pre-load from site</p>
            <p className="text-[11px] text-slate-500 leading-tight">
              Tick one, several, or Select all
            </p>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="w-9 h-9 rounded-xl border border-slate-200 flex items-center justify-center text-slate-600 hover:bg-slate-50"
            data-testid="site-equipment-picker-close"
            aria-label="Close"
          >
            <X size={16} />
          </button>
        </div>

        <div className="px-4 pt-3 pb-2 border-b border-slate-100 space-y-2">
          <div className="relative">
            <Search size={13} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
            <input
              type="text"
              value={q}
              onChange={(e) => setQ(e.target.value)}
              placeholder="Filter by name, serial, manufacturer…"
              className="w-full pl-9 pr-3 py-2 rounded-xl border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-cyan-500"
              data-testid="site-equipment-picker-search"
            />
          </div>
          {selectable.length > 0 ? (
            <button
              type="button"
              onClick={toggleAll}
              className="w-full inline-flex items-center justify-center gap-1.5 px-3 py-1.5 rounded-lg border border-slate-200 text-xs font-bold text-slate-700 hover:bg-slate-50"
              data-testid="site-equipment-picker-select-all"
            >
              {allSelected
                ? <><CheckSquare size={12} /> Deselect all ({selectable.length})</>
                : someSelected
                  ? <><ListChecks size={12} /> Select all ({selectable.length})</>
                  : <><Square size={12} /> Select all ({selectable.length})</>}
            </button>
          ) : null}
        </div>

        <div className="flex-1 overflow-y-auto">
          {loading ? (
            <div className="flex items-center justify-center py-10 text-slate-400">
              <Loader2 size={14} className="animate-spin mr-2" /> Loading site equipment…
            </div>
          ) : error ? (
            <div className="m-4 bg-rose-50 border border-rose-200 rounded-xl p-3 text-xs text-rose-700">
              {error}
            </div>
          ) : filtered.length === 0 ? (
            <div className="px-4 py-10 text-center" data-testid="site-equipment-picker-empty">
              <Package size={24} className="mx-auto text-slate-300 mb-2" />
              <p className="text-sm font-bold text-slate-900">
                {q ? 'No matches' : 'No equipment for this site yet'}
              </p>
              <p className="text-xs text-slate-500 mt-1">
                {q ? 'Adjust your search.' : 'Add some via the Equipment tab — they\'ll appear here on every future job.'}
              </p>
            </div>
          ) : (
            <ul className="divide-y divide-slate-100" data-testid="site-equipment-picker-list">
              {filtered.map((it) => {
                const ticked = selected.has(it.id);
                const disabled = it.already_on_job;
                return (
                  <li key={it.id}>
                    <button
                      type="button"
                      onClick={() => !disabled && toggle(it.id)}
                      disabled={disabled}
                      className={`w-full text-left px-4 py-3 flex items-center gap-3 ${
                        disabled
                          ? 'opacity-50 cursor-not-allowed'
                          : ticked
                            ? 'bg-cyan-50'
                            : 'hover:bg-slate-50'
                      }`}
                      data-testid={`site-equipment-item-${it.id}`}
                    >
                      <span className="w-5 h-5 flex-shrink-0">
                        {ticked
                          ? <CheckSquare size={20} className="text-cyan-600" />
                          : <Square size={20} className="text-slate-400" />}
                      </span>
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-bold text-slate-900 truncate">
                          {it.name}
                          <span className="ml-1.5 text-[11px] font-medium text-slate-500">
                            {it.manufacturer ? `${it.manufacturer} ` : ''}{it.model || ''}
                          </span>
                        </p>
                        <p className="text-[11px] text-slate-500 truncate flex items-center gap-2 flex-wrap">
                          {it.equipment_type && <span>{it.equipment_type}</span>}
                          {it.serial_number && <span className="font-mono">SN {it.serial_number}</span>}
                          {it.location && <span>· {it.location}</span>}
                          {disabled && <span className="text-emerald-700 font-bold">· Already on job</span>}
                        </p>
                      </div>
                    </button>
                  </li>
                );
              })}
            </ul>
          )}
        </div>

        <div className="px-4 py-3 border-t border-slate-200 flex gap-2">
          <button
            type="button"
            onClick={onClose}
            className="flex-1 border border-slate-300 rounded-xl py-2.5 text-sm font-semibold"
            data-testid="site-equipment-picker-cancel"
          >
            Cancel
          </button>
          <button
            type="button"
            disabled={submitting || selected.size === 0}
            onClick={onAttach}
            className="flex-1 bg-cyan-600 hover:bg-cyan-700 disabled:bg-slate-300 text-white rounded-xl py-2.5 text-sm font-bold inline-flex items-center justify-center gap-1.5"
            data-testid="site-equipment-picker-attach"
          >
            {submitting
              ? <><Loader2 size={12} className="animate-spin" /> Adding…</>
              : <><Plus size={12} /> Add {selected.size || ''}</>}
          </button>
        </div>
      </div>
    </div>
  );
}

// ─── Iter 220ea·12 · Per-machine parts widgets ────────────────────
// Two compact inline widgets that surface parts tagged to a single
// machine row. Both reuse the existing engineer parts endpoints
// (`/parts/use` for consumed parts, `/parts-requests` for parts
// the engineer wants ops to order for a return visit). Each widget
// is self-fetching so it can live inside the per-row expansion
// without the card having to ferry data through props.

function MachineRowPartsPickerInline({ onPick, onCancel, busy }) {
  const [q, setQ] = useState('');
  const [results, setResults] = useState([]);
  const [searching, setSearching] = useState(false);
  const [qty, setQty] = useState(1);
  const [picked, setPicked] = useState(null);

  useEffect(() => {
    let cancelled = false;
    const timer = setTimeout(async () => {
      if (!q || q.length < 2) { setResults([]); return; }
      setSearching(true);
      try {
        const r = await axios.get(`${API}/svc/parts`, {
          ...auth(), params: { q, limit: 8 },
        });
        if (!cancelled) setResults(r.data?.items || []);
      } catch { if (!cancelled) setResults([]); }
      finally { if (!cancelled) setSearching(false); }
    }, 250);
    return () => { cancelled = true; clearTimeout(timer); };
  }, [q]);

  return (
    <div className="rounded-lg border border-slate-200 bg-slate-50 p-2 space-y-2"
         data-testid="machine-parts-picker">
      {!picked ? (
        <>
          <div className="relative">
            <Search size={12} className="absolute left-2 top-1/2 -translate-y-1/2 text-slate-400" />
            <input
              autoFocus
              type="text"
              value={q}
              onChange={(e) => setQ(e.target.value)}
              placeholder="Search parts by name or SKU…"
              className="w-full pl-7 pr-2 py-1.5 text-xs border border-slate-200 rounded-lg bg-white focus:outline-none focus:ring-1 focus:ring-cyan-300"
              data-testid="machine-parts-search-input"
            />
          </div>
          {searching && (
            <p className="text-[11px] text-slate-500">Searching…</p>
          )}
          {!searching && q.length >= 2 && results.length === 0 && (
            <p className="text-[11px] text-slate-500">
              No matches. Use the Parts tab to request an unlisted part.
            </p>
          )}
          {results.length > 0 && (
            <ul className="space-y-1">
              {results.map((p) => (
                <li key={p.sku}>
                  <button
                    type="button"
                    onClick={() => setPicked(p)}
                    className="w-full text-left flex items-center justify-between gap-2 px-2 py-1.5 rounded-lg bg-white border border-slate-200 hover:bg-cyan-50"
                    data-testid={`machine-parts-pick-${p.sku}`}
                  >
                    <div className="min-w-0 flex-1">
