  return (
    <div className="fixed inset-0 z-[190] flex items-start justify-center overflow-y-auto bg-black/50 p-4" data-testid="inv-install-actions" onClick={onClose}>
      <div className="my-24 w-full max-w-sm rounded-2xl bg-white shadow-2xl" onClick={(e) => e.stopPropagation()}>
        <div className="border-b border-slate-200 px-5 py-3"><h3 className="font-bold text-slate-900">{alloc.serial_number}</h3><p className="text-xs text-slate-400">{alloc.customer_company_name}{alloc.customer_site ? ` · ${alloc.customer_site}` : ''}</p></div>
        <div className="px-5 py-4 text-sm space-y-1">
          <div className="flex justify-between"><span className="text-slate-500">{t('inv.inst.reference', 'Reference')}</span><span className="font-semibold">{alloc.reference}</span></div>
          <div className="flex justify-between"><span className="text-slate-500">{t('inv.inst.planned', 'Planned')}</span><span className="font-semibold">{alloc.planned_install_date ? fmtDate(alloc.planned_install_date) : t('inv.inst.unscheduled', 'Unscheduled')}</span></div>
        </div>
        <div className="flex flex-wrap justify-end gap-2 border-t border-slate-200 px-5 py-3">
          <Btn variant="secondary" onClick={onPack} data-testid="inv-install-actions-pack"><ClipboardList size={14} /> {t('inv.inst.pack', 'Install pack')}</Btn>
          <Btn variant="secondary" onClick={onSchedule} data-testid="inv-install-actions-schedule"><CalendarDays size={14} /> {alloc.planned_install_date ? t('inv.inst.reschedule', 'Reschedule') : t('inv.inst.schedule', 'Schedule')}</Btn>
          <Btn onClick={onInstall} data-testid="inv-install-actions-install"><Wrench size={14} /> {t('inv.inst.complete_checks', 'Install checks')}</Btn>
        </div>
      </div>
    </div>
  );
}

// ───────────── Installations — logistics calendar ─────────────
const WEEKDAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const localKey = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

export function Installations() {
  const { t } = useTranslation();
  const [rows, setRows] = useState(null);
  const [view, setView] = useState('calendar');
  const [cursor, setCursor] = useState(() => { const d = new Date(); return new Date(d.getFullYear(), d.getMonth(), 1); });
  const [acting, setActing] = useState(null);
  const [scheduling, setScheduling] = useState(null);
  const [installing, setInstalling] = useState(null);
  const [packing, setPacking] = useState(null);
  const load = useCallback(() => invApi.allocations('awaiting_installation').then((d) => setRows(d.allocations || [])).catch(() => setRows([])), []);
  useEffect(() => { load(); }, [load]);

  const byDay = {};
  const unscheduled = [];
  (rows || []).forEach((a) => {
    if (a.planned_install_date) { const k = a.planned_install_date.slice(0, 10); (byDay[k] = byDay[k] || []).push(a); }
    else unscheduled.push(a);
  });

  // Build month grid (Mon-first)
  const first = new Date(cursor.getFullYear(), cursor.getMonth(), 1);
  const lead = (first.getDay() + 6) % 7; // days before the 1st (Mon-first)
  const daysInMonth = new Date(cursor.getFullYear(), cursor.getMonth() + 1, 0).getDate();
  const cells = [];
  for (let i = 0; i < lead; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) cells.push(new Date(cursor.getFullYear(), cursor.getMonth(), d));
  const todayKey = localKey(new Date());
  const monthLabel = cursor.toLocaleDateString('en-GB', { month: 'long', year: 'numeric' });

  const doneAll = () => { setActing(null); setScheduling(null); setInstalling(null); setPacking(null); load(); };

  return (
    <div className="space-y-4" data-testid="inv-installations">
      <div className="flex flex-wrap items-center gap-3">
        <div>
          <h2 className="text-xl font-bold text-slate-900">{t('inv.inst.title', 'Installations')}</h2>
          <p className="text-sm text-slate-500">{t('inv.inst.subtitle', 'Logistics calendar for machines allocated from CRM orders. Schedule installs, then engineers complete install checks via the Engineer App to activate the asset & warranty.')}</p>
        </div>
        <div className="ml-auto flex rounded-lg border border-slate-200 bg-white p-0.5" data-testid="inv-install-viewtoggle">
          {[['calendar', t('inv.inst.view_calendar', 'Calendar'), CalendarDays], ['list', t('inv.inst.view_list', 'List'), List]].map(([v, l, Ic]) => (
            <button key={v} onClick={() => setView(v)} data-testid={`inv-install-view-${v}`} className={`inline-flex items-center gap-1.5 rounded-md px-3 py-1.5 text-sm font-semibold transition-colors ${view === v ? 'inv-active text-white' : 'text-slate-600 hover:bg-slate-50'}`}><Ic size={14} /> {l}</button>
          ))}
        </div>
      </div>

      {rows === null ? <Spinner /> : view === 'list' ? (
        rows.length === 0 ? <Card className="p-10 text-center text-slate-400" testId="inv-install-empty">{t('inv.inst.list_empty', 'Nothing awaiting installation.')}</Card> : (
          <Card testId="inv-install-table">
            <table className="w-full text-sm">
              <thead><tr className="border-b border-slate-200 text-left text-xs uppercase text-slate-400"><th className="px-4 py-3">{t('inv.alloc.th_ref', 'Ref')}</th><th>{t('inv.alloc.th_serial', 'Serial')}</th><th>{t('inv.alloc.th_customer', 'Customer')}</th><th>{t('inv.alloc.th_site', 'Site')}</th><th>{t('inv.alloc.th_planned', 'Planned')}</th><th></th></tr></thead>
              <tbody>
                {rows.map((a) => (
                  <tr key={a.id} className="border-b border-slate-100" data-testid={`inv-install-row-${a.reference}`}>
                    <td className="px-4 py-3 font-semibold text-[#0073A4]">{a.reference}</td>
                    <td className="font-mono text-xs">{a.serial_number}</td>
                    <td>{a.customer_company_name}</td><td className="text-slate-500">{a.customer_site || '—'}</td>
                    <td className={a.planned_install_date ? 'text-slate-600' : 'text-amber-600 font-semibold'}>{a.planned_install_date ? fmtDate(a.planned_install_date) : t('inv.inst.unscheduled', 'Unscheduled')}</td>
                    <td className="pr-4 text-right"><div className="flex justify-end gap-2"><Btn variant="secondary" onClick={() => setPacking(a)} data-testid={`inv-install-pack-${a.reference}`}><ClipboardList size={13} /> {t('inv.inst.pack', 'Install pack')}</Btn><Btn variant="secondary" onClick={() => setScheduling(a)} data-testid={`inv-install-schedule-${a.reference}`}><CalendarDays size={13} /> {a.planned_install_date ? t('inv.inst.reschedule', 'Reschedule') : t('inv.inst.schedule', 'Schedule')}</Btn><Btn onClick={() => setInstalling(a)} data-testid={`inv-install-open-${a.reference}`}><Wrench size={13} /> {t('inv.inst.complete_checks', 'Install checks')}</Btn></div></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </Card>
        )
      ) : (
        <div className="grid grid-cols-1 gap-4 lg:grid-cols-[1fr_280px]">
          <Card className="p-4" testId="inv-install-calendar">
            <div className="mb-3 flex items-center gap-2">
              <button onClick={() => setCursor(new Date(cursor.getFullYear(), cursor.getMonth() - 1, 1))} className="rounded-lg border border-slate-200 p-1.5 text-slate-500 hover:bg-slate-50" data-testid="inv-cal-prev"><ChevronLeft size={16} /></button>
              <button onClick={() => { const d = new Date(); setCursor(new Date(d.getFullYear(), d.getMonth(), 1)); }} className="rounded-lg border border-slate-200 px-2.5 py-1.5 text-xs font-semibold text-slate-600 hover:bg-slate-50" data-testid="inv-cal-today">{t('inv.inst.today', 'Today')}</button>
              <button onClick={() => setCursor(new Date(cursor.getFullYear(), cursor.getMonth() + 1, 1))} className="rounded-lg border border-slate-200 p-1.5 text-slate-500 hover:bg-slate-50" data-testid="inv-cal-next"><ChevronRight size={16} /></button>
              <span className="ml-2 text-sm font-bold text-slate-900" data-testid="inv-cal-month">{monthLabel}</span>
            </div>
            <div className="grid grid-cols-7 gap-1">
              {WEEKDAYS.map((w) => <div key={w} className="pb-1 text-center text-[10px] font-bold uppercase tracking-wide text-slate-400">{w}</div>)}
              {cells.map((d, i) => {
                if (!d) return <div key={`b${i}`} />;
                const k = localKey(d);
                const items = byDay[k] || [];
                const isToday = k === todayKey;
                return (
                  <div key={k} className={`min-h-[84px] rounded-lg border p-1 ${isToday ? 'border-[#19CDFF] bg-cyan-50/40' : 'border-slate-100'}`} data-testid={`inv-cal-day-${k}`}>
                    <div className={`px-1 text-[11px] font-semibold ${isToday ? 'text-[#0BB0DD]' : 'text-slate-400'}`}>{d.getDate()}</div>
                    <div className="space-y-1">
                      {items.slice(0, 3).map((a) => (
                        <button key={a.id} onClick={() => setActing(a)} title={`${a.customer_company_name} · ${a.serial_number}`} data-testid={`inv-cal-chip-${a.reference}`}
                          className="block w-full truncate rounded bg-cyan-100 px-1.5 py-1 text-left text-[11px] font-medium text-cyan-900 hover:bg-cyan-200">
                          {a.customer_company_name || a.serial_number}
                        </button>
                      ))}
                      {items.length > 3 && <div className="px-1 text-[10px] text-slate-400">{t('inv.inst.more', '+{{n}} more', { n: items.length - 3 })}</div>}
                    </div>
                  </div>
                );
              })}
            </div>
          </Card>

          <Card className="p-4" testId="inv-install-unscheduled">
            <h3 className="mb-1 flex items-center gap-1.5 text-sm font-bold text-slate-900"><Clock size={14} className="text-amber-500" /> {t('inv.inst.to_schedule', 'To schedule')}</h3>
            <p className="mb-3 text-xs text-slate-400">{t('inv.inst.to_schedule_note', 'Allocated from CRM orders, awaiting an install date.')}</p>
            {unscheduled.length === 0 ? <p className="py-6 text-center text-xs text-slate-400">{t('inv.inst.all_scheduled', 'All installs are scheduled.')}</p> : (
              <div className="space-y-2">
                {unscheduled.map((a) => (
                  <div key={a.id} className="rounded-lg border border-slate-200 p-2.5" data-testid={`inv-unscheduled-${a.reference}`}>
                    <p className="text-sm font-semibold text-slate-800 truncate">{a.customer_company_name}</p>
                    <p className="text-[11px] text-slate-400 truncate">{a.serial_number}{a.customer_site ? ` · ${a.customer_site}` : ''}</p>
                    <Btn variant="secondary" className="mt-2 w-full" onClick={() => setScheduling(a)} data-testid={`inv-unscheduled-schedule-${a.reference}`}><CalendarPlus size={13} /> {t('inv.inst.schedule', 'Schedule')}</Btn>
                  </div>
                ))}
              </div>
            )}
          </Card>
        </div>
      )}

      {acting && <InstallActions alloc={acting} onClose={() => setActing(null)} onSchedule={() => { setScheduling(acting); setActing(null); }} onInstall={() => { setInstalling(acting); setActing(null); }} onPack={() => { setPacking(acting); setActing(null); }} />}
      {scheduling && <ScheduleModal alloc={scheduling} onClose={() => setScheduling(null)} onDone={doneAll} />}
      {installing && <InstallModal alloc={installing} onClose={() => setInstalling(null)} onDone={doneAll} />}
      {packing && <InstallPackModal alloc={packing} onClose={() => setPacking(null)} onChanged={load} />}
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { ArrowLeft, Truck, FileText, PackageCheck, ScanLine, AlertTriangle, Plus, ArrowRightLeft, CheckCircle2 } from 'lucide-react';
import { notify } from '@/components/notifications';
import { invApi, fmtDate, statusLabel, money } from './api';
import { Card, Spinner, StatusBadge, Btn, Field, inputCls } from './ui';

const SHIP_STATUSES = ['booked', 'collected', 'in_transit', 'customs_hold', 'customs_cleared', 'out_for_delivery', 'delivered', 'delivery_discrepancy', 'returned', 'cancelled'];
const DOC_TYPES = [['packing_list', 'inv.ship.doc_packing_list', 'Packing List'], ['delivery_note', 'inv.ship.doc_delivery_note', 'Delivery Note'], ['commercial_invoice_support', 'inv.ship.doc_commercial', 'Commercial Invoice Support'], ['export_packing_list', 'inv.ship.doc_export_packing', 'Export Packing List']];
const CUSTOMS_FIELDS = [['incoterm', 'inv.ship.incoterm', 'Incoterm'], ['hs_code', 'inv.ship.hs_code', 'HS / commodity code'], ['country_of_origin', 'inv.ship.origin', 'Country of origin'], ['export_reason', 'inv.ship.export_reason', 'Export reason'], ['declared_value', 'inv.ship.declared_value', 'Declared value'], ['currency', 'inv.ship.currency', 'Currency'], ['gross_weight', 'inv.ship.gross_weight', 'Gross weight (kg)'], ['eori', 'inv.ship.eori', 'EORI']];

// ───────────── Shipment detail (tracking, customs, docs, dealer receipt) ─────────────
function ShipmentDetail({ shipmentId, onBack }) {
  const { t } = useTranslation();
  const [data, setData] = useState(null);
  const [busy, setBusy] = useState('');
  const [customs, setCustoms] = useState({});
  const [receipt, setReceipt] = useState({ confirmed: {}, damaged: {} });

  const load = useCallback(() => { invApi.shipment(shipmentId).then((d) => { setData(d); setCustoms(d.shipment.customs || {}); }).catch(() => notify.error(t('inv.common.load_failed', 'Load failed'))); }, [shipmentId]);
  useEffect(() => { load(); }, [load]);
  if (!data) return <Spinner />;
  const { shipment: sh, packages, units, receipt: existingReceipt, documents } = data;

  const act = async (fn, key) => { setBusy(key); try { await fn(); load(); } catch (e) { const d = e?.response?.data?.detail; notify.error(typeof d === 'object' ? d.message : (d || t('inv.common.failed', 'Failed'))); } finally { setBusy(''); } };

  const doReceive = async () => {
    const confirmed_serials = units.filter((u) => receipt.confirmed[u.id]).map((u) => u.serial_number);
    const damaged_serials = units.filter((u) => receipt.damaged[u.id]).map((u) => u.serial_number);
    if (!confirmed_serials.length && !damaged_serials.length) { notify.error(t('inv.ship.mark_one', 'Mark at least one unit')); return; }
    setBusy('receive');
    try {
      const r = await invApi.dealerReceive(shipmentId, { confirmed_serials, damaged_serials });
      notify.success(`Receipt ${statusLabel(r.receipt_status)} — ${r.confirmed} confirmed, ${r.damaged} damaged`);
      load();
    } catch (e) { const d = e?.response?.data?.detail; notify.error(typeof d === 'object' ? d.message : t('inv.common.failed', 'Failed')); } finally { setBusy(''); }
  };

  return (
    <div className="space-y-5" data-testid="inv-shipment-detail">
      <div className="flex items-center gap-3">
        <Btn variant="ghost" onClick={onBack} data-testid="inv-shipment-back"><ArrowLeft size={16} /> {t('inv.ship.title', 'Shipments')}</Btn>
        <div><h2 className="text-xl font-bold text-slate-900">{sh.reference}</h2><p className="text-sm text-slate-500">{sh.dealer_name} · {sh.dealer_country} · {sh.carrier}</p></div>
        <StatusBadge status={sh.status} className="ml-2" />
      </div>

      {/* Tracking */}
      <Card className="p-4" testId="inv-ship-tracking">
        <h3 className="mb-3 text-sm font-bold text-slate-900">{t('inv.ship.tracking', 'Tracking')}</h3>
        <div className="flex flex-wrap items-center gap-3 text-sm">
          <span className="text-slate-500">{t('inv.ship.tracking', 'Tracking')}: <span className="font-semibold text-slate-800">{sh.tracking || '—'}</span></span>
          <span className="text-slate-500">{t('inv.ship.destination', 'Destination:')} {sh.destination || '—'}</span>
          <select className={inputCls + ' ml-auto w-auto'} value={sh.status} data-testid="inv-ship-status" onChange={(e) => act(() => invApi.shipmentStatus(shipmentId, { status: e.target.value }), 'status')}>
            {SHIP_STATUSES.map((s) => <option key={s} value={s}>{statusLabel(s)}</option>)}
          </select>
        </div>
      </Card>

      <div className="grid grid-cols-1 gap-5 lg:grid-cols-2">
        {/* Customs / international */}
        <Card className="p-4" testId="inv-ship-customs">
          <h3 className="mb-3 text-sm font-bold text-slate-900">{t('inv.ship.customs', 'International / customs')}</h3>
          <div className="grid grid-cols-2 gap-3">
            {CUSTOMS_FIELDS.map(([k, lk, def]) => (
              <Field key={k} label={t(lk, def)}><input className={inputCls} value={customs[k] || ''} data-testid={`inv-customs-${k}`} onChange={(e) => setCustoms((c) => ({ ...c, [k]: e.target.value }))} /></Field>
            ))}
          </div>
          <Btn className="mt-3" onClick={() => act(() => invApi.setCustoms(shipmentId, customs), 'customs')} disabled={!!busy} data-testid="inv-customs-save">{t('inv.ship.save_customs', 'Save customs data')}</Btn>
          <p className="mt-2 text-[11px] text-slate-400">{t('inv.ship.customs_note', 'Pulse never invents customs classifications — values require human review.')}</p>
        </Card>

        {/* Documents */}
        <Card className="p-4" testId="inv-ship-documents">
          <h3 className="mb-3 text-sm font-bold text-slate-900">{t('inv.ship.paperwork', 'Paperwork (versioned)')}</h3>
          <div className="flex flex-wrap gap-2">
            {DOC_TYPES.map(([dt, lk, def]) => (
              <Btn key={dt} variant="secondary" onClick={() => act(() => invApi.genDocument(shipmentId, { type: dt }), 'doc')} disabled={!!busy} data-testid={`inv-gen-doc-${dt}`}><FileText size={14} /> {t(lk, def)}</Btn>
            ))}
          </div>
          <div className="mt-3 space-y-1">
            {(documents || []).length === 0 ? <p className="text-sm text-slate-400">{t('inv.ship.no_docs', 'No documents generated.')}</p> : documents.map((d) => (
              <div key={d.id} className="flex items-center gap-2 border-b border-slate-100 py-1.5 text-sm last:border-0" data-testid={`inv-doc-${d.reference}`}>
                <FileText size={14} className="text-[#0073A4]" />
                <span className="font-semibold">{d.template}</span>
                <span className="text-xs text-slate-400">{d.reference} · {d.template_version} · rev {d.revision}</span>
                <span className="ml-auto text-xs text-slate-400">{fmtDate(d.created_at)}</span>
              </div>
            ))}
          </div>
        </Card>
      </div>

      {/* Dealer receipt */}
      <Card className="p-4" testId="inv-ship-receipt">
        <h3 className="mb-1 text-sm font-bold text-slate-900">{t('inv.ship.receipt', 'Dealer receipt confirmation')}</h3>
        <p className="mb-3 text-[11px] text-slate-400">{t('inv.ship.receipt_note', 'Scan/confirm each serial the dealer received. Damaged units are flagged as a discrepancy. (The Dealer Portal calls this same action.)')}</p>
        {existingReceipt ? (
          <div className="rounded-lg bg-slate-50 p-3 text-sm" data-testid="inv-receipt-done">
            <StatusBadge status={existingReceipt.status} />
            <p className="mt-2 text-slate-600">{t('inv.ship.confirmed', 'Confirmed:')} {(existingReceipt.confirmed || []).join(', ') || '—'}</p>
            <p className="text-rose-600">{t('inv.ship.damaged', 'Damaged:')} {(existingReceipt.damaged || []).join(', ') || '—'}</p>
          </div>
        ) : (
          <>
            <div className="space-y-2">
              {units.map((u) => (
                <div key={u.id} className="flex items-center gap-3 rounded-lg border border-slate-200 p-2" data-testid={`inv-receipt-unit-${u.id}`}>
                  <span className="text-sm font-semibold text-slate-700"><ScanLine size={13} className="mr-1 inline text-[#0073A4]" />{u.serial_number}</span>
                  <div className="ml-auto flex gap-2">
                    <label className="flex items-center gap-1 text-xs"><input type="checkbox" checked={!!receipt.confirmed[u.id]} data-testid={`inv-receipt-confirm-${u.id}`} onChange={(e) => setReceipt((r) => ({ ...r, confirmed: { ...r.confirmed, [u.id]: e.target.checked }, damaged: { ...r.damaged, [u.id]: false } }))} /> {t('inv.ship.received_lbl', 'Received')}</label>
                    <label className="flex items-center gap-1 text-xs text-rose-600"><input type="checkbox" checked={!!receipt.damaged[u.id]} data-testid={`inv-receipt-damage-${u.id}`} onChange={(e) => setReceipt((r) => ({ ...r, damaged: { ...r.damaged, [u.id]: e.target.checked }, confirmed: { ...r.confirmed, [u.id]: false } }))} /> {t('inv.ship.damaged_lbl', 'Damaged')}</label>
                  </div>
                </div>
              ))}
            </div>
            <Btn className="mt-3" onClick={doReceive} disabled={!!busy} data-testid="inv-receipt-submit"><PackageCheck size={15} /> {busy === 'receive' ? t('inv.ship.confirming', 'Confirming…') : t('inv.ship.confirm_receipt', 'Confirm dealer receipt')}</Btn>
          </>
        )}
      </Card>
    </div>
  );
}

