import { useCallback, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Rocket, ScanLine, CheckCircle2, XCircle, Package, Truck, ShieldCheck, AlertTriangle } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { notify } from '@/components/notifications';
import { invApi, fmtDate, statusLabel } from './api';
import { Card, Spinner, StatusBadge, Btn, Field, inputCls } from './ui';

const QC_RESULTS = [
  { v: 'pass', k: 'inv.ful.qc_pass', label: 'Pass' }, { v: 'pass_note', k: 'inv.ful.qc_pass_note', label: 'Pass with note' },
  { v: 'rework', k: 'inv.ful.qc_rework', label: 'Rework required' }, { v: 'quarantine', k: 'inv.ful.qc_quarantine', label: 'Quarantine' }, { v: 'failed', k: 'inv.ful.qc_failed', label: 'Failed' },
];

function ScanInput({ placeholder, onScan, testId, disabled }) {
  const { t } = useTranslation();
  const [v, setV] = useState('');
  const submit = () => { if (v.trim()) { onScan(v.trim()); setV(''); } };
  return (
    <div className="flex items-center gap-2">
      <div className="relative flex-1">
        <ScanLine size={16} className="absolute left-2.5 top-2.5 text-[#0073A4]" />
        <input className={`${inputCls} pl-8`} placeholder={placeholder} value={v} data-testid={testId} disabled={disabled}
          onChange={(e) => setV(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && submit()} />
      </div>
      <Btn variant="secondary" onClick={submit} disabled={disabled || !v.trim()} data-testid={`${testId}-go`}>{t('inv.common.scan', 'Scan')}</Btn>
    </div>
  );
}

// Step wrapper
function Step({ n, title, done, active, children }) {
  return (
    <Card className={`p-4 ${active ? 'ring-2 ring-[#0073A4]/30' : ''}`} testId={`inv-ful-step-${n}`}>
      <div className="mb-3 flex items-center gap-2">
        <span className={`flex h-6 w-6 items-center justify-center rounded-full text-xs font-bold ${done ? 'bg-emerald-500 text-white' : active ? 'inv-active text-white' : 'bg-slate-200 text-slate-500'}`}>{done ? '✓' : n}</span>
        <h3 className="text-sm font-bold text-slate-900">{title}</h3>
      </div>
      {children}
    </Card>
  );
}

export default function OrderFulfilment({ orderId }) {
  const { t } = useTranslation();
  const [data, setData] = useState(null);
  const [busy, setBusy] = useState('');
  const [qcTpl, setQcTpl] = useState(null);
  const [dispatch, setDispatch] = useState({ carrier: '', tracking: '' });

  const load = useCallback(() => { invApi.fulfilment(orderId).then(setData).catch(() => notify.error(t('inv.ful.load_error', 'Could not load fulfilment'))); }, [orderId]);
  useEffect(() => { load(); invApi.qcTemplates().then((d) => setQcTpl(d.templates?.[0] || null)).catch(() => {}); }, [load]);

  if (!data) return <Spinner />;
  const { order, pick_tasks: tasks, units, qc, packages, shipment } = data;

  const released = tasks.length > 0;
  const allPicked = released && tasks.every((pt) => pt.status === 'picked');
  const pickedUnits = units.filter((u) => ['picked', 'quality_checked', 'packed', 'dispatched'].includes(u.status));
  const openPackages = packages.filter((p) => p.status !== 'sealed' && p.status !== 'dispatched');
  const sealedPackages = packages.filter((p) => ['sealed', 'dispatched'].includes(p.status));
  const dispatched = !!shipment;

  const act = async (fn, key) => { setBusy(key); try { await fn(); load(); } catch (e) {
    const d = e?.response?.data?.detail; notify.error(typeof d === 'object' ? d.message : (d || t('inv.common.action_failed', 'Action failed')));
  } finally { setBusy(''); } };

  const doPick = async (task, serial) => {
    try { await invApi.pick(task.id, task.kind === 'serialised' ? { serial } : { qty: task.required_qty }); notify.success(t('inv.ful.picked', 'Picked')); load(); }
    catch (e) { const d = e?.response?.data?.detail; notify.error(typeof d === 'object' ? d.message : (d || 'Pick rejected')); }
  };
  const doQc = async (unitId, result) => act(() => invApi.qcUnit(unitId, { template_id: qcTpl?.id, result }), 'qc');
  const addScan = async (pkgId, serial) => {
    try { const r = await invApi.addToPackage(pkgId, { serial }); notify.success(`Packed ${r.serial || ''}`); load(); }
    catch (e) { const d = e?.response?.data?.detail; notify.error(typeof d === 'object' ? d.message : (d || 'Cannot pack')); }
  };

  return (
    <div className="space-y-4" data-testid="inv-fulfilment">
      <div className="flex items-center gap-2 text-sm text-slate-500">
        <span className="font-semibold text-slate-700">{t('inv.ful.wh_ful', 'Warehouse fulfilment')}</span>
        <StatusBadge status={order.status} />
      </div>

      {/* Step 1 — Release */}
      <Step n={1} title={t('inv.ful.step1', 'Release to warehouse')} done={released} active={!released}>
        {!released ? (
          <Btn onClick={() => act(() => invApi.release(orderId), 'release')} disabled={!!busy} data-testid="inv-ful-release"><Rocket size={15} /> {busy === 'release' ? t('inv.ful.releasing', 'Releasing…') : t('inv.ful.release_btn', 'Release & generate pick tasks')}</Btn>
        ) : <p className="text-sm text-slate-500">{t('inv.ful.tasks_generated', '{{n}} pick task(s) generated.', { n: tasks.length })}</p>}
      </Step>

      {/* Step 2 — Picking */}
      {released && (
        <Step n={2} title={t('inv.ful.step2', 'Picking (scan exact serial)')} done={allPicked} active={!allPicked}>
          <div className="space-y-2">
            {tasks.map((pt) => (
              <div key={pt.id} className="flex items-center gap-3 rounded-lg border border-slate-200 p-2" data-testid={`inv-ful-task-${pt.id}`}>
                <span className="w-28 truncate text-sm font-mono text-slate-600">{pt.product_code}</span>
                {pt.serial_number && <span className="text-xs text-slate-400">{pt.serial_number}</span>}
                {pt.status === 'picked' ? (
                  <span className="ml-auto flex items-center gap-1 text-sm font-semibold text-emerald-600"><CheckCircle2 size={15} /> {t('inv.ful.picked', 'Picked')}</span>
                ) : (
                  <div className="ml-auto w-64">
                    {pt.kind === 'serialised'
                      ? <ScanInput placeholder={t('inv.ful.scan_serial_pick', 'Scan serial to pick')} testId={`inv-ful-pick-${pt.id}`} onScan={(s) => doPick(pt, s)} disabled={!!busy} />
                      : <Btn variant="secondary" onClick={() => doPick(pt)} data-testid={`inv-ful-pick-${pt.id}`}>{t('inv.ful.pick', 'Pick')} ×{pt.required_qty}</Btn>}
                  </div>
                )}
              </div>
            ))}
          </div>
        </Step>
      )}

      {/* Step 3 — QC */}
      {pickedUnits.length > 0 && (
        <Step n={3} title={t('inv.ful.step3', 'Quality control')} done={pickedUnits.every((u) => ['quality_checked', 'packed', 'dispatched'].includes(u.status) || u.quarantined)} active>
          <p className="mb-2 text-[11px] text-slate-400">{qcTpl ? qcTpl.name : t('inv.ful.std_qc', 'Standard machine QC')} — {t('inv.ful.qc_note', 'failed / quarantined units cannot be packed.')}</p>
          <div className="space-y-2">
            {pickedUnits.map((u) => (
              <div key={u.id} className="flex items-center gap-3 rounded-lg border border-slate-200 p-2" data-testid={`inv-ful-qc-${u.id}`}>
                <span className="text-sm font-semibold text-slate-700">{u.serial_number}</span>
                {u.qc_result ? (
                  <span className={`ml-auto flex items-center gap-1 text-sm font-semibold ${u.quarantined ? 'text-rose-600' : 'text-emerald-600'}`}>
                    {u.quarantined ? <AlertTriangle size={15} /> : <ShieldCheck size={15} />} {statusLabel(u.qc_result)}
                  </span>
                ) : (
                  <div className="ml-auto flex flex-wrap gap-1">
                    {QC_RESULTS.map((r) => (
                      <button key={r.v} className={`rounded px-2 py-1 text-xs font-semibold ${r.v === 'pass' ? 'bg-emerald-100 text-emerald-700' : r.v === 'quarantine' || r.v === 'failed' ? 'bg-rose-100 text-rose-700' : 'bg-slate-100 text-slate-600'}`} data-testid={`inv-ful-qc-${u.id}-${r.v}`} onClick={() => doQc(u.id, r.v)} disabled={!!busy}>{t(r.k, r.label)}</button>
                    ))}
                  </div>
                )}
              </div>
            ))}
          </div>
        </Step>
      )}

      {/* Step 4 — Packing */}
      {pickedUnits.length > 0 && (
        <Step n={4} title={t('inv.ful.step4', 'Packing')} done={sealedPackages.length > 0 && openPackages.length === 0} active>
          <Btn variant="secondary" className="mb-3" onClick={() => act(() => invApi.createPackage(orderId, { type: 'pallet' }), 'pkg')} disabled={!!busy} data-testid="inv-ful-new-package"><Package size={15} /> {t('inv.ful.new_package', 'New package')}</Btn>
          <div className="space-y-3">
            {packages.map((p) => (
              <div key={p.id} className="rounded-lg border border-slate-200 p-3" data-testid={`inv-ful-package-${p.package_number}`}>
                <div className="mb-2 flex items-center gap-2">
                  <span className="font-mono text-sm font-semibold">{p.package_number}</span>
                  <StatusBadge status={p.status} />
                  <span className="ml-auto text-xs text-slate-400">{(p.unit_ids || []).length} {t('inv.ful.units_suffix', 'unit(s)')}</span>
                </div>
                {p.status !== 'sealed' && p.status !== 'dispatched' ? (
                  <div className="space-y-2">
                    <ScanInput placeholder={t('inv.ful.scan_into_pkg', 'Scan serial into package')} testId={`inv-ful-pack-${p.id}`} onScan={(s) => addScan(p.id, s)} disabled={!!busy} />
                    <Btn variant="secondary" onClick={() => act(() => invApi.sealPackage(p.id, { weight: 100 }), 'seal')} disabled={!!busy || (p.unit_ids || []).length === 0} data-testid={`inv-ful-seal-${p.id}`}>{t('inv.ful.seal', 'Seal package')}</Btn>
                  </div>
                ) : (
                  <span className="text-xs text-emerald-600">{t('inv.ful.sealed', 'Sealed')}{p.weight ? ` · ${p.weight}kg` : ''}</span>
                )}
              </div>
            ))}
          </div>
        </Step>
      )}

      {/* Step 5 — Dispatch */}
      {sealedPackages.length > 0 && (
        <Step n={5} title={t('inv.ful.step5', 'Dispatch')} done={dispatched} active={!dispatched}>
          {dispatched ? (
            <div className="rounded-lg bg-emerald-50 p-3 text-sm text-emerald-800" data-testid="inv-ful-shipment">
              <p className="font-semibold">{shipment.reference} · {shipment.carrier}</p>
              <p className="text-xs">{t('inv.ful.tracking', 'Tracking')} {shipment.tracking || '—'} · {(shipment.package_ids || []).length} {t('inv.ful.packages_suffix', 'package(s)')} · {t('inv.ful.in_transit_since', 'In transit since')} {fmtDate(shipment.dispatched_at)}</p>
            </div>
          ) : (
            <div className="flex flex-wrap items-end gap-2">
              <div className="w-40"><Field label={t('inv.ful.carrier', 'Carrier')}><input className={inputCls} value={dispatch.carrier} data-testid="inv-ful-carrier" onChange={(e) => setDispatch((d) => ({ ...d, carrier: e.target.value }))} /></Field></div>
              <div className="w-40"><Field label={t('inv.ful.tracking', 'Tracking')}><input className={inputCls} value={dispatch.tracking} data-testid="inv-ful-tracking" onChange={(e) => setDispatch((d) => ({ ...d, tracking: e.target.value }))} /></Field></div>
              <Btn onClick={() => act(() => invApi.dispatch(orderId, dispatch), 'dispatch')} disabled={!!busy || !dispatch.carrier.trim()} data-testid="inv-ful-dispatch"><Truck size={15} /> {busy === 'dispatch' ? t('inv.ful.dispatching', 'Dispatching…') : t('inv.ful.dispatch_btn', 'Dispatch shipment')}</Btn>
            </div>
          )}
        </Step>
      )}
    </div>
  );
}

// Cross-order warehouse queue (used by Receiving/Picking/QC/Packing/Dispatch nav sections)
export function WarehouseQueue({ stage, title }) {
  const { t } = useTranslation();
  const [rows, setRows] = useState(null);
  const navigate = useNavigate();
  useEffect(() => { invApi.queue(stage).then((d) => setRows(d.orders || [])).catch(() => setRows([])); }, [stage]);
  return (
