        <Card className="p-10 text-center text-slate-400" testId={`inv-queue-${stage}-empty`}>{t('inv.ful.queue_empty', 'Nothing in this queue right now.')}</Card>
      ) : (
        <Card testId={`inv-queue-${stage}-table`}>
          <table className="w-full text-sm">
            <thead><tr className="border-b border-slate-200 text-left text-xs uppercase text-slate-400"><th className="px-4 py-3">{t('inv.th.reference', 'Reference')}</th><th>{t('inv.th.dealer', 'Dealer')}</th><th>{t('inv.th.country', 'Country')}</th><th>{t('inv.th.status', 'Status')}</th><th></th></tr></thead>
            <tbody>
              {rows.map((o) => (
                <tr key={o.id} className="border-b border-slate-100 hover:bg-slate-50" data-testid={`inv-queue-row-${o.reference}`}>
                  <td className="px-4 py-3 font-semibold text-[#0073A4]">{o.reference}</td>
                  <td>{o.dealer_name}</td>
                  <td>{o.dealer_country}</td>
                  <td><StatusBadge status={o.status} /></td>
                  <td className="text-right pr-4"><Btn variant="secondary" onClick={() => navigate(`/service-desk/inventory?s=orders&order=${o.id}`)} data-testid={`inv-queue-open-${o.reference}`}>{t('inv.common.open', 'Open')}</Btn></td>
