      {tab === 'sage' ? <div className="space-y-6"><SageConnection /><SageOrders /></div> : tab === 'field-ownership' ? <FieldOwnership /> : tab === 'logistics-logins' ? <LogisticsLogins /> : (
        !s ? <Spinner /> : (
          <div className="space-y-5">
