  const load = useCallback(async () => {
    if (!caseId) return;
    setLoading(true);
    try {
      const r = await axios.get(`${API}/svc/cases/${caseId}`, auth());
      setDoc(r.data);
      setEdits({});
    } catch (e) {
      notify.error(t('service.cd_load_case_failed', 'Failed to load case'), e?.response?.data?.detail || e.message);
    } finally { setLoading(false); }
  }, [caseId]);

  useEffect(() => { load(); }, [load]);

  // Esc closes the drawer.
  useEffect(() => {
    const onKey = (e) => { if (e.key === 'Escape') onClose?.(); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);

  const events = doc?.events || [];
  const merged = useMemo(() => ({ ...(doc || {}), ...edits }), [doc, edits]);
  const dirty = Object.keys(edits).length > 0;
  const legalNext = TRANSITIONS[merged?.status] || [];
  const pri = PRIORITY_META[merged?.priority] || PRIORITY_META.p3;

  const setEdit = (k, v) => setEdits((e) => ({ ...e, [k]: v }));

  const saveEdits = async () => {
    if (!dirty) return;
    setSaving(true);
    try {
      const r = await axios.put(`${API}/svc/cases/${caseId}`, edits, auth());
      setDoc((d) => ({ ...d, ...r.data, events: d?.events || [] }));
      setEdits({});
      notify.success(t('service.cd_case_updated', 'Case updated'));
      await load();
      onChanged?.();
    } catch (e) {
      notify.error(t('service.cd_save_failed', 'Failed to save'), e?.response?.data?.detail || e.message);
    } finally { setSaving(false); }
  };

  const submitNote = async () => {
    const body = note.trim();
    if (!body) return;
    setSaving(true);
    try {
      await axios.post(`${API}/svc/cases/${caseId}/notes`, { body, visibility: 'internal' }, auth());
      setNote('');
      await load();
      notify.success(t('service.cd_note_added', 'Note added'));
    } catch (e) {
      notify.error(t('service.cd_note_failed', 'Failed to add note'), e?.response?.data?.detail || e.message);
    } finally { setSaving(false); }
  };

  const loadComms = useCallback(async () => {
    if (!caseId) return;
    setCommsLoading(true);
    try {
      const [logResp, tplResp] = await Promise.all([
        axios.get(`${API}/svc/comms/log`, { ...auth(), params: { case_id: caseId, limit: 50 } }),
        commsTemplates.length === 0
          ? axios.get(`${API}/svc/comms/templates`, auth()).catch(() => ({ data: { templates: [] } }))
          : Promise.resolve({ data: { templates: commsTemplates } }),
      ]);
      setCommsLog(logResp.data?.events || []);
      const tpl = tplResp.data?.templates || [];
      if (tpl.length && commsTemplates.length === 0) {
        setCommsTemplates(tpl.filter((t) => t.audience === 'customer'));
      }
    } catch (e) {
      notify.error(t('service.cd_comms_failed', 'Failed to load comms'), e?.response?.data?.detail || e.message);
    } finally { setCommsLoading(false); }
  }, [caseId, commsTemplates]);

  useEffect(() => {
    if (tab === 'comms') loadComms();
  }, [tab, loadComms]);

  const sendCustomerEmail = async () => {
    if (!caseId || !commsTemplateKey) return;
    if (!doc?.customer_email) {
      notify.error(t('service.cd_no_email', 'No customer email'), t('service.cd_no_email_hint', 'Set a customer email on the Customer tab first.'));
      return;
    }
    setCommsSending(true);
    try {
      const r = await axios.post(
        `${API}/svc/comms/case/${caseId}/notify`,
        { template_key: commsTemplateKey },
        auth(),
      );
      if (r.data?.ok) {
        notify.success(t('service.cd_email_sent', 'Email sent'), `${doc.customer_email}`);
      } else {
        notify.error(t('service.cd_email_failed', 'Email send failed'), r.data?.log?.error || t('service.cd_provider_rejected', 'Provider rejected the request'));
      }
      await loadComms();
      await load();
    } catch (e) {
      notify.error(t('service.cd_send_failed', 'Send failed'), e?.response?.data?.detail || e.message);
    } finally { setCommsSending(false); }
  };

  const toggleAutoNotify = async () => {
    const next = !(doc?.comms_auto_notify !== false);
    try {
      await axios.put(`${API}/svc/cases/${caseId}`, { comms_auto_notify: next }, auth());
      await load();
    } catch (e) {
      notify.error(t('service.cd_update_failed', 'Failed to update'), e?.response?.data?.detail || e.message);
    }
  };

  // Iter 216h82 — Service Report PDF + email (operator-side fast-path)
  const [reportBusy, setReportBusy] = useState('');
  const openServiceReport = () => {
    if (!caseId) return;
    fetch(`${API}/svc/cases/${caseId}/service-report.pdf`, auth())
      .then((r) => { if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.blob(); })
      .then((blob) => {
        const blobUrl = URL.createObjectURL(blob);
        window.open(blobUrl, '_blank', 'noopener');
        setTimeout(() => URL.revokeObjectURL(blobUrl), 60000);
      })
      .catch((e) => notify.error(t('service.cd_open_report_failed', 'Could not open report'), e.message || String(e)));
  };
  const openCalibrationCert = () => {
    if (!caseId) return;
    fetch(`${API}/svc/cases/${caseId}/calibration/certificate.pdf`, auth())
      .then((r) => { if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.blob(); })
      .then((blob) => {
        const blobUrl = URL.createObjectURL(blob);
        window.open(blobUrl, '_blank', 'noopener');
        setTimeout(() => URL.revokeObjectURL(blobUrl), 60000);
      })
      .catch((e) => notify.error(t('service.cd_open_cert_failed', 'Could not open certificate'), e.message || String(e)));
  };
  const downloadCalibrationCert = () => {
    if (!caseId) return;
    fetch(`${API}/svc/cases/${caseId}/calibration/certificate.pdf`, auth())
      .then((r) => { if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.blob(); })
      .then((blob) => {
        const blobUrl = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = blobUrl;
        link.download = `calibration-${doc?.reference || caseId}.pdf`;
        document.body.appendChild(link);
        link.click();
        link.remove();
        setTimeout(() => URL.revokeObjectURL(blobUrl), 60000);
      })
      .catch((e) => notify.error(t('service.cd_download_cert_failed', 'Could not download certificate'), e.message || String(e)));
  };
  const emailCalibrationCert = async () => {
    if (!caseId || reportBusy) return;
    const defaultTo = doc?.customer_email || '';
    const to = window.prompt(t('service.cd_cert_to', 'Send the calibration certificate to which email?'), defaultTo);
    if (!to) return;
    const note = window.prompt(t('service.cd_short_note', 'Add a short note (optional)'), '') || '';
    setReportBusy('cal-email');
    try {
      const r = await axios.post(
        `${API}/svc/cases/${caseId}/calibration/certificate/email`,
        { to, note },
        auth(),
      );
      notify.success(t('service.cd_cert_emailed', 'Certificate emailed'), t('service.cd_sent_to', 'Sent to {{to}}', { to: r.data?.to || to }));
      await load();
    } catch (e) {
      notify.error(t('service.cd_cert_send_failed', 'Could not send certificate'), e?.response?.data?.detail || e.message);
    } finally { setReportBusy(''); }
  };
  const emailServiceReport = async () => {
    if (!caseId || reportBusy) return;
    const defaultTo = doc?.customer_email || '';
    const to = window.prompt(t('service.cd_report_to', 'Send the service report to which email?'), defaultTo);
    if (!to) return;
    const note = window.prompt(t('service.cd_short_note', 'Add a short note (optional)'), '') || '';
    setReportBusy('email');
    try {
      const r = await axios.post(
        `${API}/svc/cases/${caseId}/service-report/email`,
        { to, note },
        auth(),
      );
      notify.success(t('service.cd_report_emailed', 'Report emailed'), t('service.cd_sent_to', 'Sent to {{to}}', { to: r.data?.to || to }));
      await load();
    } catch (e) {
      notify.error(t('service.cd_report_send_failed', 'Could not send report'), e?.response?.data?.detail || e.message);
    } finally { setReportBusy(''); }
  };

  // Iter 216h83 — Customer Live Tracking link (Uber-style share)
  const [trackingUrl, setTrackingUrl] = useState('');
  const copyTrackingLink = async () => {
    if (!caseId) return;
    try {
      const r = await axios.get(`${API}/svc/cases/${caseId}/tracking-link`, auth());
      const url = r.data?.url || '';
      setTrackingUrl(url);
      try {
        await navigator.clipboard.writeText(url);
        notify.success(t('service.cd_track_copied', 'Tracking link copied'), t('service.cd_track_copied_hint', 'Paste into SMS / WhatsApp / email for the customer.'));
      } catch {
        window.prompt(t('service.cd_copy_link', 'Copy the link below and share with the customer:'), url);
      }
    } catch (e) {
      notify.error(t('service.cd_track_gen_failed', 'Could not generate tracking link'), e?.response?.data?.detail || e.message);
    }
  };
  const regenerateTrackingLink = async () => {
    if (!caseId) return;
    if (!window.confirm(t('service.cd_regen_confirm', 'Regenerate the tracking link? The previous link will stop working.'))) return;
    try {
      const r = await axios.post(`${API}/svc/cases/${caseId}/tracking-link/regenerate`, {}, auth());
      const url = r.data?.url || '';
      setTrackingUrl(url);
      try {
        await navigator.clipboard.writeText(url);
        notify.success(t('service.cd_new_track_copied', 'New tracking link copied'), t('service.cd_old_link_invalid', 'Old link is now invalid.'));
      } catch {
        window.prompt(t('service.cd_copy_new_link', 'Copy the new link:'), url);
      }
    } catch (e) {
      notify.error(t('service.cd_regen_failed', 'Could not regenerate'), e?.response?.data?.detail || e.message);
    }
  };

  // Iter 216h81 — Customer rating prompt at case sign-off. When the
  // customer closes a case, surface a star rating prompt BEFORE the
  // transition fires so they can't miss it.
  const [ratingTarget, setRatingTarget] = useState(null); // pending status target
  const [rating, setRating] = useState(0);
  const [ratingComment, setRatingComment] = useState('');
  const [ratingSubmitting, setRatingSubmitting] = useState(false);
  // If a rating already exists on the case, don't re-prompt.
  const existingRating = merged?.customer_rating;

  const doTransition = async (target) => {
    // Closing/sign-off path → prompt for rating if engineer is assigned
    // and no rating recorded yet.
    if (
      (target === 'closed' || target === 'invoiced')
      && merged?.assigned_engineer_id
      && !existingRating
      && ratingTarget !== target  // already shown
    ) {
      setRatingTarget(target);
      return;
    }
    setSaving(true);
    try {
      await axios.post(
        `${API}/svc/cases/${caseId}/transition`,
        { to: target, reason: transitionReason || '' },
        auth(),
      );
      setTransitionReason('');
      notify.success(t('service.cd_moved_to', 'Moved to {{status}}', { status: statusLabel(t, target) }));
      await load();
      onChanged?.();
    } catch (e) {
      notify.error(t('service.cd_transition_rejected', 'Transition rejected'), e?.response?.data?.detail || e.message);
    } finally { setSaving(false); }
  };

  const submitRatingAndTransition = async () => {
    if (!ratingTarget) return;
    setRatingSubmitting(true);
    try {
      // 1) Write the rating (and optional comment) onto the case
      if (rating > 0) {
        await axios.put(`${API}/svc/cases/${caseId}`, {
          customer_rating: rating,
          customer_rating_comment: ratingComment.trim() || undefined,
        }, auth());
      }
      // 2) Then perform the transition
      await axios.post(
        `${API}/svc/cases/${caseId}/transition`,
        { to: ratingTarget, reason: transitionReason || '' },
        auth(),
      );
      setTransitionReason('');
      const tgt = ratingTarget;
      setRatingTarget(null); setRating(0); setRatingComment('');
      notify.success(rating > 0 ? t('service.cd_closed_rating', 'Closed · thanks for rating {{n}} stars', { n: rating }) : t('service.cd_moved_to', 'Moved to {{status}}', { status: statusLabel(t, tgt) }));
      await load();
      onChanged?.();
    } catch (e) {
      notify.error(t('service.cd_close_failed', 'Could not close'), e?.response?.data?.detail || e.message);
    } finally { setRatingSubmitting(false); }
  };

  const skipRatingAndTransition = async () => {
    if (!ratingTarget) return;
    setRating(0); setRatingComment('');
    const tgt = ratingTarget;
    setRatingTarget(null);
    // Re-enter doTransition with no rating; the guard checks `ratingTarget !== target`
    // so we briefly hold this in a local then call the API directly.
    setSaving(true);
    try {
      await axios.post(
        `${API}/svc/cases/${caseId}/transition`,
        { to: tgt, reason: transitionReason || '' },
        auth(),
      );
      setTransitionReason('');
      notify.success(t('service.cd_moved_to', 'Moved to {{status}}', { status: statusLabel(t, tgt) }));
      await load();
      onChanged?.();
    } catch (e) {
      notify.error(t('service.cd_transition_rejected', 'Transition rejected'), e?.response?.data?.detail || e.message);
    } finally { setSaving(false); }
  };

  const drawer = (
    <div
      className="svc-drawer-overlay"
      onClick={(e) => { if (e.target === e.currentTarget) onClose?.(); }}
      data-testid="case-drawer"
    >
      <aside
        className="svc-drawer"
        role="dialog"
        aria-label={t('service.cd_case_detail', 'Service case detail')}
        style={{ maxWidth: 720 }}
      >
        {/* Header */}
        <header className="svc-drawer-head">
          <div className="flex items-start justify-between gap-3">
            <div className="min-w-0">
              <p className="svc-eyebrow">{merged?.reference || t('service.cd_loading', 'Loading…')}</p>
              <h2 className="svc-h1" style={{ fontSize: 19, marginTop: 2 }} data-testid="drawer-title">
                {merged?.title || (loading ? '…' : t('service.cd_untitled', 'Untitled case'))}
              </h2>
              <div className="flex flex-wrap items-center gap-2 mt-2">
                <span className={`svc-pill svc-pill--${pri.tone === 'p1' ? 'danger' : pri.tone === 'p2' ? 'warn' : pri.tone === 'p3' ? 'info' : ''}`} data-testid="drawer-priority">
                  {priorityLabel(t, merged?.priority)}
                </span>
                <span className="svc-pill" data-testid="drawer-status">
                  {statusLabel(t, merged?.status) || merged?.status || '—'}
                </span>
                <SLABadge resolveAt={merged?.sla_resolve_at} />
                {doc?.is_mod ? (
                  <span className="svc-pill" style={{ background: '#1e3a5f', color: '#fff', fontWeight: 700 }} data-testid="drawer-mod-badge">MOD</span>
                ) : null}
                {merged?.customer_po_number ? (
                  <span
                    className="svc-pill inline-flex items-center gap-1"
                    style={{ background: '#ecfeff', color: '#0073a4', fontWeight: 700 }}
                    title={t('service.cd_po_title', "Customer PO / reference — links this chargeable job to the customer's purchase order")}
                    data-testid="drawer-customer-po">
                    PO / Ref: {merged.customer_po_number}
                  </span>
                ) : null}
                {existingRating ? (
                  <span
                    className="svc-pill inline-flex items-center gap-0.5"
                    style={{ background: '#fef3c7', color: '#92400e', fontWeight: 700 }}
                    title={merged?.customer_rating_comment || t('service.cd_rated_title', 'Customer rated this case {{n}}/5', { n: existingRating })}
                    data-testid="drawer-customer-rating">
                    <span style={{ color: '#f59e0b' }}>★</span> {existingRating}/5
                  </span>
                ) : null}
              </div>
            </div>
            <button type="button" onClick={onClose} aria-label={t('service.cd_close', 'Close')} data-testid="drawer-close" className="svc-icon-btn">
              <X size={16} />
            </button>
          </div>
          {doc?.desk_read_only ? (
            <ProviderReadOnlyBanner caseId={caseId} provider={doc.external_provider} onDone={() => { load(); onChanged?.(); }} />
          ) : null}
        </header>

        {/* Tabs */}
        <div className="svc-tabs" style={{ margin: 0, padding: '0 18px' }}>
          {doc?.is_mod ? (
            <TabButton id="jobfile" label="Job file" icon={FileText} active={tab === 'jobfile'} onClick={() => setTab('jobfile')} />
          ) : null}
          <TabButton id="timeline" label={t('service.cd_tab_timeline', 'Timeline')} icon={Activity} active={tab === 'timeline'} onClick={() => setTab('timeline')} count={events.length} />
          <TabButton id="details" label={t('service.cd_tab_details', 'Details')} icon={Wrench} active={tab === 'details'} onClick={() => setTab('details')} />
          <TabButton id="customer" label={t('service.cd_tab_customer', 'Customer')} icon={UserIcon} active={tab === 'customer'} onClick={() => setTab('customer')} />
          <TabButton id="comms" label={t('service.cd_tab_comms', 'Comms')} icon={Bell} active={tab === 'comms'} onClick={() => setTab('comms')} />
          <TabButton id="lifecycle" label={t('service.cd_tab_lifecycle', 'Lifecycle')} icon={Route} active={tab === 'lifecycle'} onClick={() => setTab('lifecycle')} />
        </div>

        {/* Body */}
        <div className="svc-drawer-body space-y-4">
          {loading ? (
            <div className="flex items-center gap-2 text-sm svc-muted"><Loader2 size={14} className="animate-spin" /> {t('service.cd_loading_case', 'Loading case…')}</div>
          ) : tab === 'timeline' ? (
            <>
              {/* AI summary */}
              <div className="svc-ai-block" data-testid="drawer-ai-summary-block">
                <div className="flex items-center justify-between gap-2">
                  <p className="svc-ai-eyebrow"><Sparkles size={11} /> AI summary</p>
                  <button
                    type="button"
                    onClick={runSummary}
                    disabled={aiBusy}
                    className="svc-btn svc-btn-primary svc-btn-sm"
                    data-testid="drawer-ai-summary-run"
                  >
                    {aiBusy ? <Loader2 size={10} className="animate-spin" /> : <Sparkles size={10} />}
                    {aiBusy ? '…' : aiSummary ? t('service.cd_refresh', 'Refresh') : t('service.cd_generate', 'Generate')}
                  </button>
                </div>
                {aiSummary ? (
                  <div className="space-y-2 text-xs mt-2">
                    <div>
                      <p className="svc-label" style={{ marginBottom: 2 }}>{t('service.cd_for_customer', 'For the customer')}</p>
                      <p data-testid="drawer-ai-customer-summary" style={{ lineHeight: 1.55 }}>{aiSummary.customer_summary}</p>
                    </div>
                    {aiSummary.engineer_summary ? (
                      <div>
                        <p className="svc-label" style={{ marginBottom: 2 }}>{t('service.cd_for_engineer', 'For the engineer')}</p>
                        <p data-testid="drawer-ai-engineer-summary" style={{ lineHeight: 1.55 }}>{aiSummary.engineer_summary}</p>
                      </div>
                    ) : null}
                  </div>
                ) : (
                  <p className="text-[11.5px] svc-muted mt-2">{t('service.cd_ai_summary_hint', 'One-click summary of every event so far — one for the customer, one for the engineer.')}</p>
                )}
              </div>

              {/* Add note */}
              <div className="svc-card-base p-3">
                <p className="svc-label">{t('service.cd_add_note', 'Add internal note')}</p>
                <textarea
                  value={note}
                  onChange={(e) => setNote(e.target.value)}
                  rows={2}
                  placeholder={t('service.cd_note_ph', 'Customer called back to confirm engineer access…')}
                  className="svc-textarea"
                  style={{ fontFamily: 'inherit', fontSize: 13 }}
                  data-testid="drawer-note-input"
                />
                <div className="flex justify-end mt-2">
                  <button
                    type="button"
                    disabled={!note.trim() || saving}
                    onClick={submitNote}
                    className="svc-btn svc-btn-primary svc-btn-sm"
                    data-testid="drawer-note-submit"
                  >
                    <Send size={11} /> {t('service.cd_add_note_btn', 'Add note')}
                  </button>
                </div>
              </div>

              {/* Timeline */}
              <ol className="svc-timeline" data-testid="drawer-timeline">
                {events.length === 0 ? (
                  <li className="text-sm svc-muted">{t('service.cd_no_events', 'No timeline events yet.')}</li>
                ) : events.map((ev) => {
                  const kind = TIMELINE_KIND(ev.type);
                  return (
                    <li key={ev.id} className={kind ? `svc-tl--${kind}` : ''}>
                      <p className="svc-tl-meta">
                        {ev.type === 'state_change'
                          ? `${statusLabel(t, ev.from_state)} → ${statusLabel(t, ev.to_state)}`
                          : ev.type}
                        <span className="svc-tl-meta-time"> · {fmtDate(ev.at)}{ev.actor_name ? ` · ${ev.actor_name}` : ''}</span>
                      </p>
                      {ev.body ? <p className="svc-tl-body">{ev.body}</p> : null}
                      {ev.reason ? <p className="svc-tl-reason">{t('service.cd_reason', 'Reason:')} {ev.reason}</p> : null}
                    </li>
                  );
                })}
              </ol>
            </>
          ) : tab === 'details' ? (
            <>
              {doc.follow_up_of_reference && (
                <p className="mb-3 text-xs text-slate-500" data-testid="case-follow-up-of">Follow-up to <b>{doc.follow_up_of_reference}</b></p>
              )}
              {(doc.engineer_report || doc.signoff) && (
                <div className="mb-4 space-y-2">
                  <EngineerReportView report={doc.engineer_report} signoff={doc.signoff} fallbackSummary={doc.resolution_notes} />
                  <BookFollowUpButton caseId={doc.id} report={doc.engineer_report} followUpRef={doc.follow_up_case_reference} onBooked={load} />
                </div>
              )}
              {/* Iter 216h205 — coverage banner derived from
                 source_meta.coverage_* stamped by the issue intake
                 (iter h199). Tells the operator at a glance whether
                 this case is under contract, in warranty or
                 chargeable, BEFORE they edit cover_type below. */}
              {(merged.source_meta?.coverage_status || merged.cover_type) && (
                <div className="mb-3" data-testid="case-coverage-section">
                  <CoverageBanner
                    coverage={merged.source_meta || {
                      coverage_status:
                        merged.cover_type === 'contract' ? 'covered_contract'
                        : merged.cover_type === 'warranty' ? 'covered_warranty'
                        : 'uncovered',
                    }}
                    testid="case-coverage"
                  />
                </div>
              )}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <Field label={t('service.cd_f_title', 'Title')}>
                  <input value={merged.title || ''} onChange={(e) => setEdit('title', e.target.value)} className="svc-input" data-testid="drawer-edit-title" />
                </Field>
                <Field label={t('service.cd_f_priority', 'Priority')}>
                  <select value={merged.priority || 'p3'} onChange={(e) => setEdit('priority', e.target.value)} className="svc-select" data-testid="drawer-edit-priority">
                    <option value="p1">{t('service.cd_prio_p1', 'P1 · Critical')}</option>
                    <option value="p2">{t('service.cd_prio_p2', 'P2 · High')}</option>
                    <option value="p3">{t('service.cd_prio_p3', 'P3 · Standard')}</option>
                    <option value="p4">{t('service.cd_prio_p4', 'P4 · Low')}</option>
                  </select>
                </Field>
                <Field label={t('service.cd_f_site', 'Site')}>
                  <input value={merged.site_name || ''} onChange={(e) => setEdit('site_name', e.target.value)} className="svc-input" data-testid="drawer-edit-site" />
              </Field>
              <Field label={t('service.cd_f_asset', 'Asset')}>
                <input value={merged.asset_name || ''} onChange={(e) => setEdit('asset_name', e.target.value)} className="svc-input" data-testid="drawer-edit-asset" />
              </Field>
              <Field label={t('service.cd_f_fault', 'Fault code')}>
                <input value={merged.fault_code || ''} onChange={(e) => setEdit('fault_code', e.target.value)} className="svc-input" data-testid="drawer-edit-fault" />
              </Field>
              <Field label={t('service.cd_f_case_type', 'Case type')}>
                <select value={merged.case_type || ''} onChange={(e) => setEdit('case_type', e.target.value)} className="svc-select" data-testid="drawer-edit-case-type">
                  <option value="">—</option>
                  <option value="repair">{t('service.cd_type_repair', 'Repair')}</option>
                  <option value="ppm">{t('service.cd_type_ppm', 'PPM')}</option>
                  <option value="install">{t('service.cd_type_install', 'Install')}</option>
                </select>
              </Field>
              <Field label={t('service.cd_f_cover', 'Cover type')}>
                <select value={merged.cover_type || ''} onChange={(e) => setEdit('cover_type', e.target.value)} className="svc-select" data-testid="drawer-edit-cover">
                  <option value="">—</option>
                  <option value="contract">{t('service.cd_cover_contract', 'Contract')}</option>
                  <option value="warranty">{t('service.cd_cover_warranty', 'Warranty')}</option>
                  <option value="chargeable">{t('service.cd_cover_chargeable', 'Chargeable')}</option>
                </select>
              </Field>
              <Field label={t('service.cd_f_engineer', 'Engineer')}>
                <input
                  value={merged.assigned_engineer_name || ''}
                  onChange={(e) => setEdit('assigned_engineer_name', e.target.value)}
                  placeholder={t('service.cd_unassigned', 'Unassigned')}
                  className="svc-input"
                  data-testid="drawer-edit-engineer"
                />
              </Field>
              <Field label={t('service.cd_f_est_minutes', 'Estimated minutes')}>
                <input
                  type="number"
                  value={merged.estimated_minutes || 0}
                  onChange={(e) => setEdit('estimated_minutes', Number(e.target.value))}
                  className="svc-input"
                  data-testid="drawer-edit-est"
                />
              </Field>
              <div className="sm:col-span-2">
                <Field label={t('service.cd_f_description', 'Description')}>
                  <textarea
                    value={merged.description || ''}
                    onChange={(e) => setEdit('description', e.target.value)}
                    rows={4}
                    className="svc-textarea"
                    style={{ fontFamily: 'inherit', fontSize: 13 }}
                    data-testid="drawer-edit-description"
                  />
                </Field>
              </div>
              <div className="sm:col-span-2 grid grid-cols-2 gap-3 text-xs svc-muted">
                <p>{t('service.cd_logged', 'Logged:')} {fmtDate(doc?.created_at)}{doc?.logged_by_name ? ` · ${doc.logged_by_name}` : ''}</p>
                <p>{t('service.cd_sla_respond_by', 'SLA respond by:')} {fmtDate(doc?.sla_response_at)}</p>
                <p>{t('service.cd_source', 'Source:')} {doc?.source || '—'}</p>
                <p>{t('service.cd_sla_resolve_by', 'SLA resolve by:')} {fmtDate(doc?.sla_resolve_at)}</p>
              </div>
            </div>
            </>
          ) : tab === 'customer' ? (
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <Field label={t('service.cd_f_customer_name', 'Customer name')}>
                <input value={merged.customer_name || ''} onChange={(e) => setEdit('customer_name', e.target.value)} className="svc-input" data-testid="drawer-edit-customer-name" />
              </Field>
              <Field label={t('service.cd_f_phone', 'Phone')}>
                <input value={merged.customer_phone || ''} onChange={(e) => setEdit('customer_phone', e.target.value)} className="svc-input" data-testid="drawer-edit-customer-phone" />
              </Field>
              <Field label={t('service.cd_f_email', 'Email')}>
                <input value={merged.customer_email || ''} onChange={(e) => setEdit('customer_email', e.target.value)} className="svc-input" data-testid="drawer-edit-customer-email" />
              </Field>
              <Field label={t('service.cd_f_site', 'Site')}>
                <input value={merged.site_name || ''} onChange={(e) => setEdit('site_name', e.target.value)} className="svc-input" data-testid="drawer-edit-customer-site" />
              </Field>
              <div className="sm:col-span-2 flex flex-wrap gap-3 text-xs pt-1">
                {merged.customer_phone ? <a href={`tel:${merged.customer_phone}`} className="svc-link inline-flex items-center gap-1"><Phone size={11} /> {t('service.cd_call', 'Call')}</a> : null}
                {merged.customer_email ? <a href={`mailto:${merged.customer_email}`} className="svc-link inline-flex items-center gap-1"><Mail size={11} /> {t('service.cd_email', 'Email')}</a> : null}
                {merged.site_name ? <span className="inline-flex items-center gap-1 svc-muted"><MapPin size={11} /> {merged.site_name}</span> : null}
              </div>
              <div className="sm:col-span-2"><CrmContextCard caseId={caseId} /></div>
            </div>
          ) : tab === 'jobfile' ? (
            <MODJobFileTab caseId={caseId} />
          ) : tab === 'lifecycle' ? (
            <ServiceCaseLifecycleTab caseId={caseId} onNavigate={setTab} />
          ) : (
            <CommsTab
              doc={doc}
              commsLog={commsLog}
              commsLoading={commsLoading}
              templates={commsTemplates}
              templateKey={commsTemplateKey}
              setTemplateKey={setCommsTemplateKey}
              onSend={sendCustomerEmail}
              sending={commsSending}
              autoNotify={doc?.comms_auto_notify !== false}
              onToggleAutoNotify={toggleAutoNotify}
              onRefresh={loadComms}
            />
          )}
        </div>

        {/* Footer — transitions + save */}
        <footer className="svc-drawer-foot space-y-2">
          {tab !== 'timeline' && dirty && !doc?.desk_read_only ? (
            <div className="flex justify-end">
              <button
                type="button"
                onClick={saveEdits}
                disabled={saving}
                className="svc-btn svc-btn-primary svc-btn-sm"
                data-testid="drawer-save"
              >
                <Save size={11} /> {t('service.cd_save_changes', 'Save changes')}
              </button>
            </div>
          ) : null}
          {/* Iter 216h83 — Customer Live Tracking link share */}
          <div
            className="rounded-lg border p-2 flex items-center gap-2 flex-wrap"
            style={{ borderColor: 'var(--theme-border, #e0e0e0)' }}
            data-testid="drawer-tracking-link-row"
          >
            <LinkIcon size={13} className="opacity-70" />
            <span className="text-[11.5px] font-semibold">{t('service.cd_customer_tracking', 'Customer tracking')}</span>
            {trackingUrl ? (
              <span
                className="text-[10px] font-bold uppercase tracking-wider px-1.5 py-0.5 rounded-full"
                style={{ background: '#dbeafe', color: '#0091ca' }}
                data-testid="drawer-tracking-link-active"
              >
                Link active
              </span>
            ) : null}
            <div className="ml-auto flex gap-1.5">
              <button
                type="button"
                onClick={copyTrackingLink}
                className="svc-btn svc-btn-primary svc-btn-sm"
                data-testid="drawer-tracking-link-copy"
              >
                <LinkIcon size={11} /> {trackingUrl ? t('service.cd_copy_again', 'Copy again') : t('service.cd_get_link', 'Get link')}
              </button>
              {trackingUrl ? (
                <button
                  type="button"
                  onClick={regenerateTrackingLink}
                  className="svc-btn svc-btn-secondary svc-btn-sm"
                  title={t('service.cd_regen_title', 'Invalidate the old link and mint a fresh one')}
                  data-testid="drawer-tracking-link-regenerate"
                >
                  <RefreshCw size={11} /> {t('service.cd_regenerate', 'Regenerate')}
                </button>
              ) : null}
            </div>
          </div>
          {/* Iter 216h82 — Customer-facing Service Report shortcut */}
          {(['repaired', 'awaiting_sign_off', 'closed', 'invoiced'].includes(doc?.status)) ? (
            <div
              className="rounded-lg border p-2 flex items-center gap-2 flex-wrap"
              style={{ borderColor: 'var(--theme-border, #e0e0e0)' }}
              data-testid="drawer-service-report"
            >
              <FileText size={13} className="opacity-70" />
              <span className="text-[11.5px] font-semibold">{t('service.cd_service_report', 'Service report')}</span>
              {doc?.service_report_sent_at ? (
                <span
                  className="text-[10px] font-bold uppercase tracking-wider px-1.5 py-0.5 rounded-full"
                  style={{ background: '#dcfce7', color: '#166534' }}
                  data-testid="drawer-service-report-sent"
                >
                  {t('service.cd_report_sent_to', 'Sent to {{who}}', { who: doc.service_report_sent_to || t('service.cd_the_customer', 'customer') })}
                </span>
              ) : null}
              <div className="ml-auto flex gap-1.5">
                <button
                  type="button"
                  onClick={openServiceReport}
                  className="svc-btn svc-btn-secondary svc-btn-sm"
                  data-testid="drawer-service-report-view"
                >
                  {t('service.cd_view', 'View')}
                </button>
                <button
                  type="button"
                  onClick={emailServiceReport}
                  disabled={reportBusy === 'email'}
                  className="svc-btn svc-btn-primary svc-btn-sm"
                  data-testid="drawer-service-report-email"
                >
                  <Send size={11} /> {reportBusy === 'email' ? t('service.cd_sending', 'Sending…') : (doc?.service_report_sent_at ? t('service.cd_resend', 'Resend') : t('service.cd_email_customer', 'Email customer'))}
                </button>
              </div>
            </div>
          ) : null}
          {/* Calibration certificate — audit evidence, gated on capture */}
          {doc?.calibration_captured ? (
            <div
              className="rounded-lg border p-2 flex items-center gap-2 flex-wrap"
              style={{ borderColor: 'var(--theme-border, #e0e0e0)' }}
              data-testid="drawer-calibration-cert"
            >
              <Award size={13} className="opacity-70" />
              <span className="text-[11.5px] font-semibold">{t('service.cd_calibration_cert', 'Calibration certificate')}</span>
              {doc?.calibration_result ? (
                <span
                  className="text-[10px] font-bold uppercase tracking-wider px-1.5 py-0.5 rounded-full"
                  style={String(doc.calibration_result).toLowerCase() === 'pass'
                    ? { background: '#dcfce7', color: '#166534' }
                    : { background: '#fee2e2', color: '#991b1b' }}
                  data-testid="drawer-calibration-result"
                >
                  {String(doc.calibration_result).toUpperCase()}
                </span>
              ) : null}
              {doc?.calibration_cert_sent_at ? (
                <span
                  className="text-[10px] font-bold uppercase tracking-wider px-1.5 py-0.5 rounded-full"
                  style={{ background: '#dbeafe', color: '#0073a4' }}
                  data-testid="drawer-calibration-cert-sent"
                >
                  {t('service.cd_report_sent_to', 'Sent to {{who}}', { who: doc.calibration_cert_sent_to || t('service.cd_the_customer', 'customer') })}
                </span>
              ) : null}
              <div className="ml-auto flex gap-1.5">
                <button
                  type="button"
                  onClick={openCalibrationCert}
                  className="svc-btn svc-btn-secondary svc-btn-sm"
                  data-testid="drawer-calibration-cert-view"
                >
                  {t('service.cd_view', 'View')}
                </button>
                <button
                  type="button"
                  onClick={downloadCalibrationCert}
                  className="svc-btn svc-btn-secondary svc-btn-sm"
                  data-testid="drawer-calibration-cert-download"
                >
                  {t('service.cd_download', 'Download')}
                </button>
                <button
                  type="button"
                  onClick={emailCalibrationCert}
                  disabled={reportBusy === 'cal-email'}
                  className="svc-btn svc-btn-primary svc-btn-sm"
                  data-testid="drawer-calibration-cert-email"
                >
                  <Send size={11} /> {reportBusy === 'cal-email' ? t('service.cd_sending', 'Sending…') : (doc?.calibration_cert_sent_at ? t('service.cd_resend', 'Resend') : t('service.cd_email_customer', 'Email customer'))}
                </button>
              </div>
            </div>
          ) : null}
          {legalNext.length > 0 ? (
            <div className="space-y-2">
              <input
                value={transitionReason}
                onChange={(e) => setTransitionReason(e.target.value)}
                placeholder={t('service.cd_reason_ph', 'Reason / note (optional)')}
                className="svc-input svc-input-sm"
                data-testid="drawer-transition-reason"
              />
              <div className="flex flex-wrap gap-1.5">
                {legalNext.map((s) => {
                  const isDanger = s === 'rejected';
                  const isPositive = s === 'closed' || s === 'invoiced' || s === 'repaired';
                  const lockedByProvider = doc?.desk_read_only && !DESK_COMPLETE_STATES.has(s);
                  return (
                    <button
                      key={s}
                      type="button"
                      onClick={() => doTransition(s)}
                      disabled={saving || lockedByProvider}
                      title={lockedByProvider ? 'With an outside provider — take over to change this' : undefined}
                      className={`svc-btn svc-btn-sm ${isPositive ? 'svc-btn-primary' : isDanger ? 'svc-btn-danger' : 'svc-btn-secondary'}`}
                      data-testid={`drawer-transition-${s}`}
                    >
                      {isPositive ? <CheckCircle2 size={11} /> : null}
                      {STATUS_LABEL[s] ? statusLabel(t, s) : s}
                      {!isPositive && !isDanger ? <ChevronRight size={11} /> : null}
                    </button>
                  );
                })}
              </div>
            </div>
          ) : (
            <p className="text-[11.5px] svc-muted">{t('service.cd_no_transitions', 'No further transitions available from this state.')}</p>
          )}
        </footer>
      </aside>

      {/* Iter 216h81 — Customer rating prompt at sign-off */}
      {ratingTarget && (
        <RatingPromptModal
          rating={rating}
          setRating={setRating}
          comment={ratingComment}
          setComment={setRatingComment}
          busy={ratingSubmitting}
          targetLabel={statusLabel(t, ratingTarget)}
          onSubmit={submitRatingAndTransition}
          onSkip={skipRatingAndTransition}
          onCancel={() => { setRatingTarget(null); setRating(0); setRatingComment(''); }}
        />
      )}
    </div>
  );

  return createPortal(drawer, document.body);
}


function RatingPromptModal({ rating, setRating, comment, setComment, busy, targetLabel, onSubmit, onSkip, onCancel }) {
  const { t } = useTranslation();
  return (
    <div
      className="svc-drawer-overlay"
      style={{ zIndex: 1100 }}
      onClick={(e) => { if (e.target === e.currentTarget) onCancel?.(); }}
      data-testid="rating-prompt-modal"
    >
      <div className="rounded-2xl bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 shadow-xl max-w-md w-full p-6"
        style={{ margin: 'auto' }}>
        <h2 className="text-lg font-black mb-1">{t('service.cd_rate_title', "Rate this engineer's work")}</h2>
        <p className="text-xs svc-muted mb-4">
          {t('service.cd_rate_blurb', 'Your rating feeds the partner performance score and helps Pulse Fitness recognise the best engineers. Optional — you can skip.')}
        </p>
        <div className="flex gap-1.5 justify-center my-4" data-testid="rating-stars">
          {[1, 2, 3, 4, 5].map((n) => (
            <button key={n} type="button" onClick={() => setRating(n)}
              data-testid={`rating-star-${n}`}
              className="text-3xl leading-none transition-transform hover:scale-110"
              style={{ color: rating >= n ? '#f59e0b' : '#c9cbcc' }}>
              ★
            </button>
          ))}
        </div>
        {rating > 0 && (
          <div className="text-center text-xs font-bold svc-muted mb-3" data-testid="rating-summary">
            {['', t('service.cd_rate_1', 'Poor'), t('service.cd_rate_2', 'Could be better'), t('service.cd_rate_3', 'Solid'), t('service.cd_rate_4', 'Great'), t('service.cd_rate_5', 'Excellent')][rating]}
          </div>
        )}
        <label className="block">
          <span className="text-[10px] uppercase tracking-wider font-bold svc-muted">{t('service.cd_comment_optional', 'Comment (optional)')}</span>
          <textarea
            value={comment}
            onChange={(e) => setComment(e.target.value.slice(0, 500))}
            placeholder={t('service.cd_comment_ph', "Anything you'd like to flag to Pulse Fitness or the engineer?")}
            rows={3}
            className="svc-input w-full mt-1"
            data-testid="rating-comment"
          />
        </label>
        <div className="flex items-center justify-between gap-2 mt-5 pt-3 border-t border-zinc-100 dark:border-zinc-800">
          <button onClick={onSkip} disabled={busy}
            className="svc-btn-sm text-zinc-500 hover:text-zinc-800 dark:hover:text-zinc-200 disabled:opacity-50"
            data-testid="rating-skip">
            {t('service.cd_skip_and', 'Skip & {{action}}', { action: targetLabel.toLowerCase() })}
          </button>
          <div className="flex gap-2">
            <button onClick={onCancel} disabled={busy}
              className="svc-btn-sm"
              data-testid="rating-cancel">
              Cancel
            </button>
            <button onClick={onSubmit} disabled={busy || rating === 0}
              className="svc-btn-sm svc-btn-primary disabled:opacity-50"
              data-testid="rating-submit">
              {busy ? t('service.cd_saving', 'Saving…') : t('service.cd_submit_and', 'Submit & {{action}}', { action: targetLabel.toLowerCase() })}

            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

function Field({ label, children }) {
  return (
    <label className="block">
      <span className="svc-label">{label}</span>
      {children}
    </label>
  );
}

function CommsTab({
  doc, commsLog, commsLoading, templates, templateKey, setTemplateKey,
  onSend, sending, autoNotify, onToggleAutoNotify, onRefresh,
}) {
  const { t } = useTranslation();
  const customerEmail = doc?.customer_email || '';
  const customerName = doc?.customer_name || '';
  return (
    <div className="space-y-3" data-testid="drawer-comms-tab">
      {/* Auto-notify toggle */}
      <div className="svc-card-base p-3" data-testid="drawer-comms-auto-card">
        <div className="flex items-start gap-3">
          <Bell size={14} className="mt-0.5" />
          <div className="flex-1 min-w-0">
            <p className="font-bold text-sm">{t('service.cd_auto_notify_title', 'Auto-notify customer on key events')}</p>
            <p className="text-[11.5px] svc-muted mt-0.5">
              {t('service.cd_auto_notify_desc', 'When enabled, Pulse Fitness automatically emails {{email}} as the engineer moves to en route, arrives on site, and the case is completed. Each event sends at most once per case.', { email: customerEmail || t('service.cd_the_customer_lc', 'the customer') })}
            </p>
          </div>
          <label className="inline-flex items-center gap-2 cursor-pointer text-xs">
            <input
              type="checkbox"
              checked={autoNotify}
              onChange={onToggleAutoNotify}
              data-testid="drawer-comms-auto-toggle"
            />
            <span className="font-bold">{autoNotify ? t('service.cd_on', 'On') : t('service.cd_off', 'Off')}</span>
          </label>
        </div>
      </div>

      {/* Manual send */}
      <div className="svc-card-base p-3" data-testid="drawer-comms-send-card">
        <p className="svc-label">{t('service.cd_send_email_now', 'Send customer email now')}</p>
        {!customerEmail ? (
          <p className="text-[11.5px] svc-muted mt-1">
            {t('service.cd_no_email_send', 'No customer email on this case. Add one on the Customer tab to enable sends.')}
          </p>
        ) : (
          <p className="text-[11.5px] svc-muted mt-1">
            {t('service.cd_to_label', 'To:')} <strong>{customerName ? `${customerName} <${customerEmail}>` : customerEmail}</strong>
          </p>
        )}
        <div className="flex flex-wrap gap-2 mt-2 items-center">
          <select
            value={templateKey}
            onChange={(e) => setTemplateKey(e.target.value)}
            className="svc-select svc-select-sm"
            style={{ maxWidth: 240 }}
            disabled={!customerEmail || sending}
            data-testid="drawer-comms-template-select"
          >
            {templates.length === 0 ? (
              <>
                <option value="case_logged">case_logged</option>
                <option value="engineer_en_route">engineer_en_route</option>
                <option value="engineer_arrived">engineer_arrived</option>
                <option value="case_completed">case_completed</option>
              </>
            ) : templates.map((tpl) => (
              <option key={tpl.key} value={tpl.key}>{tpl.key}</option>
            ))}
          </select>
          <button
            type="button"
            onClick={onSend}
            disabled={!customerEmail || sending || !templateKey}
            className="svc-btn svc-btn-primary svc-btn-sm"
            data-testid="drawer-comms-send-btn"
          >
            {sending ? <Loader2 size={11} className="animate-spin" /> : <Send size={11} />}
            {sending ? t('service.cd_sending', 'Sending…') : t('service.cd_send_now', 'Send now')}
          </button>
          <button
            type="button"
            onClick={onRefresh}
            className="svc-btn svc-btn-secondary svc-btn-sm"
            data-testid="drawer-comms-refresh"
          >
            <History size={11} /> {t('service.cd_refresh_log', 'Refresh log')}
          </button>
        </div>
      </div>

      {/* Log */}
      <div className="svc-section" data-testid="drawer-comms-log-section">
        <div className="svc-section-head">
          <div className="svc-section-title inline-flex items-center gap-1.5">
            <History size={13} /> {t('service.cd_email_history', 'Email history')}
            <span className="svc-muted text-xs">({commsLog.length})</span>
          </div>
        </div>
        <div className="svc-section-body">
          {commsLoading ? (
            <div className="svc-empty"><Loader2 size={14} className="animate-spin" /> {t('service.cd_loading', 'Loading…')}</div>
          ) : commsLog.length === 0 ? (
            <p className="text-[11.5px] svc-muted italic">{t('service.cd_no_emails', 'No emails have been sent for this case yet.')}</p>
          ) : (
            <ul className="space-y-2" data-testid="drawer-comms-log-list">
              {commsLog.map((row) => (
                <li
                  key={row.id}
                  className="flex items-start gap-2 p-2 rounded border"
                  style={{ borderColor: 'var(--theme-border)' }}
                  data-testid={`drawer-comms-log-${row.id}`}
                >
                  {row.ok ? (
                    <CheckCircle2 size={14} style={{ color: '#10b981', flexShrink: 0, marginTop: 2 }} />
                  ) : (
                    <AlertTriangle size={14} style={{ color: '#ef4444', flexShrink: 0, marginTop: 2 }} />
                  )}
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center justify-between gap-2 flex-wrap">
                      <span className="font-bold text-sm truncate">{row.subject || t('service.cd_no_subject', '(no subject)')}</span>
                      <span className="text-[10px] svc-muted tabular-nums">
                        {new Date(row.at).toLocaleString()}
                      </span>
                    </div>
                    <div className="flex items-center gap-1.5 flex-wrap mt-0.5">
                      <span className="svc-pill" data-testid={`drawer-comms-log-kind-${row.id}`}>
                        {row.kind === 'case_notify_auto' ? t('service.cd_auto', 'auto') : t('service.cd_manual', 'manual')}
                      </span>
                      <span className="text-[11px] svc-muted">{row.template_key} · {row.to}</span>
                      {!row.ok && row.error ? (
                        <span className="text-[11px]" style={{ color: '#b91c1c' }}>· {row.error}</span>
                      ) : null}
                    </div>
                  </div>
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>
    </div>
  );
}

/**
 * ServiceDeskIntakeForm — iter 215ec (cascade redesign).
 *
 * Modal-based intake form for service-desk operators logging cases.
 * Cascade order matches the operations portal flow so info inherits
 * site → contact → equipment → serial → contract coverage:
 *
 *   1. Site
 *   2. Contact (filtered by site, with manual fallback)
 *   3. Equipment type (filtered by site)
 *   4. Serial number (auto-filled from equipment)
 *   5. Cover type + SLA (auto from equipment coverage; chargeable opens Quote / PO inputs)
 *   6. Description
 *   7. Attach pictures / videos
 *   8. AI triage
 *   9. Fault code
 *
 * Uses the shared `_serviceops.css` design layer.
 */
import { useEffect, useMemo, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import axios from 'axios';
import {
  X, Phone, Loader2, Sparkles, MapPin, User as UserIcon, Wrench, Hash,
  ShieldCheck, FileText, Camera, AlertTriangle, CheckCircle2, Trash2, Upload,
  Search, Check, ChevronDown,
} from 'lucide-react';
import { notify } from '@/components/notifications';
import './_serviceops.css';

const API = process.env.REACT_APP_BACKEND_URL ? `${process.env.REACT_APP_BACKEND_URL}/api` : '/api';
const auth = () => ({ headers: { Authorization: `Bearer ${localStorage.getItem('token') || ''}` } });

export default function ServiceDeskIntakeForm({ onClose, onCreated, initial }) {
  const { t } = useTranslation();
  const PRIORITY_OPTIONS = [
    { v: 'p1', label: t('service.intake_prio_p1', 'P1 — Critical (1h response, 4h resolve)') },
    { v: 'p2', label: t('service.intake_prio_p2', 'P2 — High (4h response, 24h resolve)') },
    { v: 'p3', label: t('service.intake_prio_p3', 'P3 — Standard (8h response, 72h resolve)') },
    { v: 'p4', label: t('service.intake_prio_p4', 'P4 — Low (24h response, 7d resolve)') },
  ];
  // Cascade selections
  const [customerOrgId, setCustomerOrgId] = useState('');
  const [siteId, setSiteId] = useState('');
  const [contactMode, setContactMode] = useState(initial?.customerName ? 'manual' : 'existing'); // existing | manual
  const [contactId, setContactId] = useState('');
  const [equipmentId, setEquipmentId] = useState('');
  const [prefillEquip] = useState(initial?.equipmentIds || []);
  const [serial, setSerial] = useState('');

  // Lookup data
  const [customers, setCustomers] = useState([]);
  const [sites, setSites] = useState([]);
  const [contacts, setContacts] = useState([]);
  const [equipmentList, setEquipmentList] = useState([]);
  const [coverage, setCoverage] = useState(null);
  const [coverageLoading, setCoverageLoading] = useState(false);

  // Manual contact entry (used as fallback)
  const [customerName, setCustomerName] = useState(initial?.customerName || '');
  const [customerEmail, setCustomerEmail] = useState(initial?.customerEmail || '');
  const [customerPhone, setCustomerPhone] = useState(initial?.customerPhone || '');

  // Description / chargeable / media / triage
  const [title, setTitle] = useState(initial?.title || '');
  const [description, setDescription] = useState(initial?.description || '');
  const [coverType, setCoverType] = useState(initial?.coverType || 'contract'); // contract | warranty | chargeable
  const [caseType, setCaseType] = useState('repair');     // repair | ppm | install
  const [priority, setPriority] = useState(initial?.priority || 'p3');
  const [quoteRequired, setQuoteRequired] = useState(false);
  const [customerPONumber, setCustomerPONumber] = useState('');
  const [attachments, setAttachments] = useState([]); // [{id, name, url, mime}]
  const [uploading, setUploading] = useState(false);
  const fileRef = useRef(null);

  const [aiBusy, setAiBusy] = useState(false);
  const [ai, setAi] = useState(null);
  const [faultCode, setFaultCode] = useState('');

  const [saving, setSaving] = useState(false);

  // ── Initial customer list (operator + CRM-linked imported customers)
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const r = await axios.get(`${API}/svc/desk/customers`, auth());
        if (cancelled) return;
        const list = r.data?.customers || [];
        setCustomers(list);
        // Prefill from an "initial" (e.g. Log case from equipment); else default
        // to the operator's own org so existing behaviour is unchanged.
        if (initial?.customerOrgId && list.some((c) => c.organization_id === initial.customerOrgId)) {
          setCustomerOrgId(initial.customerOrgId);
        } else {
          const op = list.find((c) => c.is_operator) || list[0];
          if (op) setCustomerOrgId(op.organization_id);
        }
      } catch {
        // silent — operators can still type customer details manually
      }
    })();
    return () => { cancelled = true; };
  }, []);

  // ── Customer → sites
  useEffect(() => {
    let cancelled = false;
    setSiteId(''); setEquipmentId(''); setSerial(''); setSites([]);
    if (!customerOrgId) return undefined;
    (async () => {
      try {
        const r = await axios.get(`${API}/svc/desk/customer-sites?organization_id=${encodeURIComponent(customerOrgId)}`, auth());
        if (!cancelled) setSites(r.data?.sites || []);
      } catch {
        if (!cancelled) setSites([]);
      }
    })();
    return () => { cancelled = true; };
  }, [customerOrgId]);

  // ── Site → equipment + contacts
  useEffect(() => {
    let cancelled = false;
    if (!siteId) {
      setEquipmentList([]); setContacts([]); setEquipmentId(''); setSerial('');
      return undefined;
    }
    (async () => {
      try {
        const [eqRes, staffRes] = await Promise.all([
          axios.get(`${API}/svc/desk/customer-equipment?organization_id=${encodeURIComponent(customerOrgId)}&site_id=${encodeURIComponent(siteId)}`, auth()).catch(() => ({ data: { equipment: [] } })),
          axios.get(`${API}/gym-floor/staff`, auth()).catch(() => ({ data: { staff: [] } })),
        ]);
        if (cancelled) return;
        const eqs = (eqRes.data?.equipment || []).filter((e) => !e.site_id || e.site_id === siteId);
        setEquipmentList(eqs);
        setContacts(staffRes.data?.staff || []);
      } catch {
        if (!cancelled) { setEquipmentList([]); setContacts([]); }
      }
    })();
    return () => { cancelled = true; };
  }, [siteId, customerOrgId]);

  // ── Equipment → serial + coverage
  useEffect(() => {
    let cancelled = false;
    if (!equipmentId) {
      setCoverage(null); setSerial('');
      return undefined;
    }
    const equip = equipmentList.find((e) => e.id === equipmentId);
    if (equip) setSerial(equip.serial_number || '');
    (async () => {
      setCoverageLoading(true); setCoverage(null);
      try {
        const r = await axios.get(`${API}/svc/desk/equipment-coverage?organization_id=${encodeURIComponent(customerOrgId)}&equipment_id=${encodeURIComponent(equipmentId)}`, auth());
        if (!cancelled) {
          setCoverage(r.data || null);
          if (r.data?.covered) {
            const ct = (r.data.type || 'contract').toLowerCase();
            setCoverType(ct === 'warranty' ? 'warranty' : 'contract');
            setQuoteRequired(false);
          } else {
            setCoverType('chargeable');
            setQuoteRequired(true);
          }
        }
      } catch {
        if (!cancelled) setCoverage(null);
      } finally {
        if (!cancelled) setCoverageLoading(false);
      }
    })();
    return () => { cancelled = true; };
  }, [equipmentId, equipmentList, customerOrgId]);

  // ── Resolve customer details from selected contact
  const selectedContact = useMemo(
    () => contacts.find((c) => c.id === contactId),
    [contacts, contactId],
  );
  useEffect(() => {
    if (contactMode !== 'existing' || !selectedContact) return;
    setCustomerName(selectedContact.name || '');
    setCustomerEmail(selectedContact.email || '');
    setCustomerPhone(selectedContact.mobile || '');
  }, [contactMode, selectedContact]);

  const selectedSite = useMemo(() => sites.find((s) => s.id === siteId), [sites, siteId]);
  const selectedEquipment = useMemo(() => equipmentList.find((e) => e.id === equipmentId), [equipmentList, equipmentId]);

  // Prefill site + equipment when opened from the Equipment tab ("Log case").
  useEffect(() => {
    if (initial?.siteId && sites.length && !siteId && sites.some((s) => s.id === initial.siteId)) {
      setSiteId(initial.siteId);
    }
  }, [sites, siteId, initial]);
  useEffect(() => {
    if (prefillEquip.length && equipmentList.length && !equipmentId
        && equipmentList.some((e) => e.id === prefillEquip[0])) {
      setEquipmentId(prefillEquip[0]);
    }
  }, [equipmentList, equipmentId, prefillEquip]);

  // ── Media upload
  const onPickFiles = async (filesIn) => {
    const files = Array.from(filesIn || []);
    if (files.length === 0) return;
    setUploading(true);
    try {
      const next = [];
      for (const f of files) {
        const fd = new FormData();
        fd.append('file', f);
        try {
          const r = await axios.post(`${API}/files/upload`, fd, {
            headers: { ...auth().headers, 'Content-Type': 'multipart/form-data' },
          });
          next.push({
            id: r.data?.id || `${Date.now()}-${f.name}`,
            name: f.name,
            url: r.data?.url || r.data?.file_url || '',
            mime: f.type || 'application/octet-stream',
          });
        } catch {
          next.push({ id: `local-${Date.now()}-${f.name}`, name: f.name, url: '', mime: f.type, _local: true });
        }
      }
      setAttachments((prev) => [...prev, ...next]);
    } finally {
      setUploading(false);
      if (fileRef.current) fileRef.current.value = '';
    }
  };

  const removeAttachment = (id) => setAttachments((prev) => prev.filter((a) => a.id !== id));

  // ── AI triage
  const runTriage = async () => {
    const desc = (description || title || '').trim();
    if (desc.length < 12) { notify.error(t('service.intake_err_ai_desc', 'Add a fault description (at least a sentence) before AI triage')); return; }
    setAiBusy(true);
    try {
      const r = await axios.post(`${API}/svc/ai/triage`, {
        description: desc,
        site_name: selectedSite?.name || '',
        asset_name: selectedEquipment?.name || '',
        customer_name: customerName,
      }, auth());
      if (r.data?.ok) {
        setAi(r.data);
        notify.success(t('service.intake_ai_ready', 'AI triage ready'), t('service.intake_ai_suggested', 'Suggested {{prio}} · {{code}}', { prio: (r.data.priority || '').toUpperCase(), code: r.data.fault_code || '—' }));
      } else {
        notify.error(t('service.intake_ai_unavailable', 'AI triage unavailable'), r.data?.error || t('service.intake_ai_try', 'Try again or fill in manually'));
      }
    } catch (e) {
      notify.error(t('service.intake_ai_failed', 'AI triage failed'), e?.response?.data?.detail || e.message);
    } finally { setAiBusy(false); }
  };

  const acceptAi = () => {
    if (!ai) return;
    if (ai.priority) setPriority(ai.priority);
    if (ai.fault_code) setFaultCode(ai.fault_code);
    notify.success(t('service.intake_ai_applied', 'AI suggestions applied'));
  };

  // ── Submit
  const submit = async () => {
    if (!siteId) { notify.error(t('service.intake_err_site', 'Pick a site first')); return; }
    if (contactMode === 'existing' && !contactId) { notify.error(t('service.intake_err_contact', 'Pick a contact (or switch to manual entry)')); return; }
    if (!customerName.trim()) { notify.error(t('service.intake_err_name', 'Contact name required')); return; }
    if (!customerEmail.trim() && !customerPhone.trim()) { notify.error(t('service.intake_err_reach', 'Contact phone or email required')); return; }
    if (!title.trim() && !description.trim()) { notify.error(t('service.intake_err_title_desc', 'Title or description required')); return; }
    if (coverType === 'chargeable' && quoteRequired && !customerPONumber.trim()) {
      // PO is "required" only when explicitly toggled — soft warning, not blocking
      // (we still let the operator submit so they can chase the PO after).
    }
    setSaving(true);
    try {
      const payload = {
        title: title.trim() || (description.trim().slice(0, 80)),
        description: description.trim(),
        priority,
        cover_type: coverType,
        site_id: siteId,
        site_name: selectedSite?.name || '',
        site_postcode: selectedSite?.postcode || selectedSite?.address || '',
        asset_id: equipmentId || '',
        asset_name: selectedEquipment?.name || '',
        equipment_ids: Array.from(new Set([equipmentId, ...prefillEquip].filter(Boolean))),
        equipment_serials: serial ? [serial] : [],
        fault_code: faultCode,
        contact_id: contactMode === 'existing' ? contactId : '',
        customer_name: customerName.trim(),
        customer_email: customerEmail.trim(),
        customer_phone: customerPhone.trim(),
        quote_required: quoteRequired,
        customer_po_number: customerPONumber.trim(),
        attachments: attachments.filter((a) => a.url).map((a) => ({ id: a.id, name: a.name, url: a.url, mime: a.mime })),
        contract_id: coverage?.sla_contract_ref || '',
        follow_up_of: initial?.followUpOf || undefined,
      };
      const r = await axios.post(`${API}/svc/intake/phone`, payload, auth());
      // Iter 215ed — chargeable + quote_required cases auto-draft a Sage SLQuote.
      // Surface the confirmation so the operator knows the quote is queued.
      const draft = r.data?.sage_quote_outbox;
      if (draft?.id) {
        notify.success(
          t('service.intake_quote_drafted', 'Quote drafted in Sage outbox'),
          t('service.intake_quote_drafted_detail', 'Reference {{ref}} · status {{status}}', { ref: r.data?.reference || '', status: draft.status || 'pending' }),
        );
      }
      onCreated?.(r.data);
    } catch (e) {
      notify.error(t('service.intake_log_failed', 'Failed to log case'), e?.response?.data?.detail || e.message);
    } finally { setSaving(false); }
  };

  // ── Render
  return (
    <div
      className="svc-modal-overlay"
      onClick={(e) => { if (e.target === e.currentTarget) onClose?.(); }}
      data-testid="svc-intake-form"
    >
      <div className="svc-modal" role="dialog" aria-label={t('service.intake_log_new_case', 'Log new service case')}>
        {/* Header */}
        <div className="svc-drawer-head flex items-center justify-between gap-3">
          <div className="min-w-0">
            <h2 className="svc-h1" style={{ fontSize: 20, textAlign: 'left' }}>{initial?.followUpOf ? t('service.intake_book_follow_up', 'Book follow-up visit') : t('service.intake_log_new_case', 'Log new service case')}</h2>
            {initial?.followUpOf && (
              <p className="text-xs text-slate-500 mt-0.5" data-testid="svc-intake-follow-up-of">
                {t('service.intake_follow_up_of', 'Follow-up to {{ref}} · parts requested for it move to this job', { ref: initial.followUpRef || '' })}
              </p>
            )}
          </div>
          <button type="button" onClick={onClose} aria-label={t('service.intake_close', 'Close')} data-testid="svc-intake-close" className="svc-icon-btn">
            <X size={16} />
          </button>
        </div>

        {/* Body */}
        <div className="svc-drawer-body space-y-4">
          {/* Step 1 — Customer & site */}
          <Step n={1} icon={<MapPin size={12} />} label={t('service.intake_step_customer_site', 'Customer & site')}>
            {customers.length > 1 && (
              <CustomerCombobox
                customers={customers}
                value={customerOrgId}
                onChange={setCustomerOrgId}
              />
            )}
            <select
              value={siteId}
              onChange={(e) => { setSiteId(e.target.value); setContactId(''); setEquipmentId(''); }}
              className="svc-select"
              data-testid="intake-site-select"
            >
              <option value="">{sites.length ? t('service.intake_select_site', '— Select site —') : t('service.intake_no_sites', 'No sites for this customer')}</option>
              {sites.map((s) => (
                <option key={s.id} value={s.id}>
                  {s.name}{s.equipment_count != null ? ` · ${t('service.intake_machines', '{{n}} machines', { n: s.equipment_count })}` : ''}
                </option>
              ))}
            </select>
          </Step>

          {/* Step 2 — Contact */}
          <Step n={2} icon={<UserIcon size={12} />} label={t('service.intake_step_contact', 'Contact at site')} disabled={!siteId}>
            <div className="flex gap-2 mb-2 text-[11px]">
              <ToggleChip
                active={contactMode === 'existing'}
                onClick={() => setContactMode('existing')}
                testid="intake-contact-mode-existing"
              >{t('service.intake_pick_directory', 'Pick from directory')}</ToggleChip>
              <ToggleChip
                active={contactMode === 'manual'}
                onClick={() => setContactMode('manual')}
                testid="intake-contact-mode-manual"
              >{t('service.intake_enter_manually', 'Enter manually')}</ToggleChip>
            </div>
            {contactMode === 'existing' ? (
              <select
                value={contactId}
                onChange={(e) => setContactId(e.target.value)}
                className="svc-select"
                data-testid="intake-contact-select"
                disabled={!siteId}
              >
                <option value="">{contacts.length ? t('service.intake_select_contact', '— Select contact —') : t('service.intake_no_contacts', 'No contacts on file (switch to manual)')}</option>
                {contacts.map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.name}{c.email ? ` · ${c.email}` : ''}{c.mobile ? ` · ${c.mobile}` : ''}
                  </option>
                ))}
              </select>
            ) : (
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
                <input value={customerName} onChange={(e) => setCustomerName(e.target.value)} placeholder={t('service.intake_ph_name', 'Name')} className="svc-input" data-testid="intake-contact-name" />
                <input value={customerPhone} onChange={(e) => setCustomerPhone(e.target.value)} placeholder={t('service.intake_ph_phone', 'Phone')} className="svc-input" data-testid="intake-contact-phone" />
                <input value={customerEmail} onChange={(e) => setCustomerEmail(e.target.value)} placeholder={t('service.intake_ph_email', 'Email')} className="svc-input" data-testid="intake-contact-email" />
              </div>
            )}
            {contactMode === 'existing' && selectedContact ? (
              <p className="svc-fieldset-hint mt-2">
                <strong>{selectedContact.name}</strong>
                {selectedContact.email ? ` · ${selectedContact.email}` : ''}
                {selectedContact.mobile ? ` · ${selectedContact.mobile}` : ''}
              </p>
            ) : null}
          </Step>

          {/* Step 3 — Equipment */}
          <Step n={3} icon={<Wrench size={12} />} label={t('service.intake_step_equipment', 'Equipment')} disabled={!siteId}>
            <select
              value={equipmentId}
              onChange={(e) => setEquipmentId(e.target.value)}
              className="svc-select"
              data-testid="intake-equipment-select"
              disabled={!siteId}
            >
              <option value="">{equipmentList.length ? t('service.intake_select_equipment', '— Select equipment —') : t('service.intake_no_equipment', 'No equipment on this site')}</option>
              {equipmentList.map((e) => (
                <option key={e.id} value={e.id}>
                  {e.name || e.display_name || t('service.intake_unknown', 'Unknown')}
                  {e.manufacturer ? ` · ${e.manufacturer}` : ''}
                  {e.model ? ` · ${e.model}` : ''}
                </option>
              ))}
            </select>
          </Step>

          {/* Step 4 — Serial */}
          <Step n={4} icon={<Hash size={12} />} label={t('service.intake_step_serial', 'Serial number')} disabled={!equipmentId}>
            <input
              value={serial}
              onChange={(e) => setSerial(e.target.value)}
              placeholder={equipmentId ? t('service.intake_serial_autofill', 'Auto-filled from equipment') : t('service.intake_serial_pickfirst', 'Pick equipment first')}
              className="svc-input"
              style={{ letterSpacing: '0.04em', fontVariantNumeric: 'tabular-nums' }}
              data-testid="intake-serial"
              disabled={!equipmentId}
            />
            {selectedEquipment?.serial_number && serial !== selectedEquipment.serial_number ? (
              <p className="svc-fieldset-hint mt-1" style={{ color: 'var(--svc-warn-text)' }}>
                {t('service.intake_serial_differs', 'Differs from registered serial')} <strong>{selectedEquipment.serial_number}</strong>
              </p>
            ) : null}
          </Step>

          {/* Step 5 — Cover & SLA */}
          <Step n={5} icon={<ShieldCheck size={12} />} label={t('service.intake_step_cover', 'Cover type & SLA')} disabled={!equipmentId}>
            <CoveragePanel
              loading={coverageLoading}
              coverage={coverage}
              coverType={coverType}
              setCoverType={setCoverType}
              quoteRequired={quoteRequired}
              setQuoteRequired={setQuoteRequired}
              customerPONumber={customerPONumber}
              setCustomerPONumber={setCustomerPONumber}
            />
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 mt-3">
              <Field label={t('service.intake_f_job_type', 'Job type')}>
                {/* Iter 220dt — surface friendly labels (the customer
                    + engineer Summary reads from the same source). */}
                <select
                  value={caseType}
                  onChange={(e) => setCaseType(e.target.value)}
                  className="svc-select"
                  data-testid="intake-case-type"
                >
                  <option value="repair">{t('service.intake_jt_repair', 'Repair')}</option>
                  <option value="ppm">{t('service.intake_jt_ppm', 'Preventative Maintenance Service')}</option>
                  <option value="install">{t('service.intake_jt_install', 'Installation')}</option>
                  <option value="inspection">{t('service.intake_jt_inspection', 'Safety / compliance inspection')}</option>
                  <option value="callout">{t('service.intake_jt_callout', 'Emergency callout')}</option>
                  <option value="audit">{t('service.intake_jt_audit', 'Asset audit')}</option>
                </select>
              </Field>
              <Field label={t('service.intake_f_cover', 'Cover type')}>
                <select value={coverType} onChange={(e) => setCoverType(e.target.value)} className="svc-select" data-testid="intake-cover-type">
                  <option value="contract">{t('service.intake_cover_contract', 'Contract')}</option>
                  <option value="warranty">{t('service.intake_cover_warranty', 'Warranty')}</option>
                  <option value="chargeable">{t('service.intake_cover_chargeable', 'Chargeable')}</option>
                </select>
              </Field>
              <Field label={t('service.intake_f_priority', 'Priority')}>
                <select value={priority} onChange={(e) => setPriority(e.target.value)} className="svc-select" data-testid="intake-priority">
                  {PRIORITY_OPTIONS.map((p) => <option key={p.v} value={p.v}>{p.label}</option>)}
                </select>
              </Field>
            </div>
          </Step>

          {/* Step 6 — Description */}
          <Step n={6} icon={<FileText size={12} />} label={t('service.intake_step_desc', 'Description of issue')}>
            <input
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder={t('service.intake_ph_title', 'Title (e.g. Treadmill #14 belt frayed)')}
              className="svc-input mb-2"
              data-testid="intake-title"
            />
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={3}
              placeholder={t('service.intake_ph_desc', 'Customer reports rubber peeling on the left edge of the running belt. Belt makes a slapping sound at higher speeds.')}
              className="svc-textarea"
              style={{ fontFamily: 'inherit', fontSize: 13 }}
              data-testid="intake-description"
            />
          </Step>

          {/* Step 7 — Media */}
          <Step n={7} icon={<Camera size={12} />} label={t('service.intake_step_media', 'Attach photos / videos')}>
            <div className="flex items-center gap-2 flex-wrap">
              <button
                type="button"
                onClick={() => fileRef.current?.click()}
                disabled={uploading}
                className="svc-btn svc-btn-secondary svc-btn-sm"
                data-testid="intake-media-pick"
              >
                {uploading ? <Loader2 size={11} className="animate-spin" /> : <Upload size={11} />}
                {uploading ? t('service.intake_uploading', 'Uploading…') : t('service.intake_choose_files', 'Choose files')}
              </button>
              <input
                ref={fileRef}
                type="file"
                multiple
                accept="image/*,video/*"
                hidden
                onChange={(e) => onPickFiles(e.target.files)}
                data-testid="intake-media-input"
              />
              <span className="svc-fieldset-hint">{t('service.intake_media_hint', 'Photos and short videos help the engineer arrive prepared.')}</span>
            </div>
            {attachments.length > 0 ? (
              <ul className="mt-2 space-y-1" data-testid="intake-media-list">
                {attachments.map((a) => (
                  <li key={a.id} className="flex items-center justify-between gap-2 text-[11.5px] svc-pill" style={{ width: '100%', justifyContent: 'space-between' }}>
                    <span className="truncate">
                      {a.url ? <a href={a.url} target="_blank" rel="noreferrer" style={{ color: 'var(--svc-link)' }}>{a.name}</a> : a.name}
                      {a._local ? <span className="svc-muted ml-2">{t('service.intake_saved_locally', '(saved locally — re-pick when online)')}</span> : null}
                    </span>
                    <button type="button" onClick={() => removeAttachment(a.id)} className="svc-icon-btn" aria-label={t('service.intake_remove', 'Remove {{name}}', { name: a.name })} data-testid={`intake-media-remove-${a.id}`}>
                      <Trash2 size={11} />
                    </button>
                  </li>
                ))}
              </ul>
            ) : null}
          </Step>

          {/* Step 8 — AI triage */}
          <Step n={8} icon={<Sparkles size={12} />} label={t('service.intake_step_ai', 'AI triage')}>
            <div className="svc-ai-block" data-testid="intake-ai-block">
              <div className="flex items-center justify-between gap-2">
                <p className="svc-ai-eyebrow"><Sparkles size={12} /> {t('service.intake_ai_assistant', 'AI triage assistant')}</p>
                <button
                  type="button"
                  onClick={runTriage}
                  disabled={aiBusy}
                  className="svc-btn svc-btn-primary svc-btn-sm"
                  data-testid="intake-ai-run"
                >
                  {aiBusy ? <Loader2 size={11} className="animate-spin" /> : <Sparkles size={11} />}
                  {aiBusy ? t('service.intake_thinking', 'Thinking…') : ai ? t('service.intake_rerun', 'Re-run') : t('service.intake_suggest', 'Suggest priority + parts')}
                </button>
              </div>
              {ai ? (
                <div className="space-y-1.5 mt-2" data-testid="intake-ai-result">
                  <div className="flex flex-wrap items-center gap-2">
                    <span className={`svc-prio svc-prio--${(ai.priority || 'p3').toLowerCase()}`} style={{ width: 'auto', padding: '2px 8px' }}>
                      {(ai.priority || '').toUpperCase()}
                    </span>
                    <span className="text-[11.5px]"><strong>{t('service.intake_fault_label', 'Fault:')}</strong> {ai.fault_code || '—'}</span>
                    <span className="svc-muted text-[11px] ml-auto tabular-nums">{t('service.intake_conf', 'conf {{p}}% · {{ms}}ms', { p: Math.round((ai.confidence || 0) * 100), ms: ai.latency_ms ?? 0 })}</span>
                  </div>
                  {ai.rationale ? <p className="text-xs">{ai.rationale}</p> : null}
                  {Array.isArray(ai.likely_parts) && ai.likely_parts.length > 0 ? (
                    <ul className="text-[11.5px] list-disc pl-4 space-y-0.5">
                      {ai.likely_parts.map((p, i) => (
                        <li key={`${p.sku}-${i}`}>
                          <strong>{p.sku}</strong> — {p.name}
                          {p.reason ? <span className="svc-muted"> · {p.reason}</span> : null}
                        </li>
                      ))}
                    </ul>
                  ) : null}
                  <div className="flex gap-2 pt-1">
                    <button type="button" onClick={acceptAi} className="svc-btn svc-btn-primary svc-btn-sm" data-testid="intake-ai-accept">
                      {t('service.intake_apply', 'Apply suggestions')}
                    </button>
                    <button type="button" onClick={() => setAi(null)} className="svc-btn svc-btn-ghost svc-btn-sm" data-testid="intake-ai-dismiss">
                      {t('service.intake_dismiss', 'Dismiss')}
                    </button>
                  </div>
                </div>
              ) : (
                <p className="text-[11.5px] svc-muted mt-2">
                  {t('service.intake_ai_hint', 'Type the fault description and click Suggest priority + parts. Claude returns a recommended priority, fault code, and parts to allocate.')}
                </p>
              )}
            </div>
          </Step>

          {/* Step 9 — Fault code */}
          <Step n={9} icon={<AlertTriangle size={12} />} label={t('service.intake_step_fault', 'Fault code')}>
            <input
              value={faultCode}
              onChange={(e) => setFaultCode(e.target.value)}
              placeholder={ai?.fault_code ? t('service.intake_ph_fault_suggested', 'Suggested: {{code}}', { code: ai.fault_code }) : 'TM-BLT-WEAR'}
              className="svc-input"
              data-testid="intake-fault"
            />
          </Step>
        </div>

        {/* Footer */}
        <div className="svc-drawer-foot flex items-center justify-end gap-2">
          <button type="button" onClick={onClose} className="svc-btn svc-btn-ghost" data-testid="intake-cancel">
            {t('service.intake_cancel', 'Cancel')}
          </button>
          <button
            type="button"
            onClick={submit}
            disabled={saving}
            className="svc-btn svc-btn-primary"
            data-testid="intake-submit"
          >
            {saving ? <Loader2 size={13} className="animate-spin" /> : <Phone size={13} />}
            {saving ? t('service.intake_logging', 'Logging…') : t('service.intake_log_case', 'Log case')}
          </button>
        </div>
      </div>
    </div>
  );
}

function CustomerCombobox({ customers, value, onChange }) {
