                  <p className="opacity-60 mt-0.5">{ev.from_state} → {ev.to_state}{ev.reason ? ` · ${ev.reason}` : ''}</p>
                ) : null}
              </li>
            ))}
          </ol>
        )}
      </Section>
      {digestOpen ? <DigestSettingsModal onClose={() => setDigestOpen(false)} /> : null}
    </ServiceOpsShell>
  );
}

